// ══════════════════════════════════════════════════════════════════════════
// SPLASH — Masked gala intro sequence
// Runs immediately on script load. Boot proceeds behind the overlay.
// Desktop/landscape: 0s gala → 2s title → 3.3s tagline → 4.2s subline → 6.5s fade out.
// Mobile portrait:   0s bg photo → 3s type overlay → 7s fade out (no tagline/subline).
// ══════════════════════════════════════════════════════════════════════════
(function initSplash() {
    const overlay = document.getElementById('splashOverlay');
    if (!overlay) return;

    const isMobilePortrait = window.innerWidth <= 480 && window.innerHeight > window.innerWidth;

    if (isMobilePortrait) {
        // Mobile portrait: two-phase splash with text overlay
        const mobileType = document.getElementById('splashMobileType');
        const tagline = document.getElementById('splashTagline');
        const subline = document.getElementById('splashSubline');
        // Style tagline/subline for mobile top positioning (hidden until type image appears)
        if (tagline) { tagline.style.display = ''; tagline.classList.add('splash-mobile-text'); }
        if (subline) { subline.style.display = ''; subline.innerHTML = 'Deeply responsive<br>literary and cinegraphic novels'; subline.classList.add('splash-mobile-text'); }
        // 3s: fade in type overlay on top of bg photo
        setTimeout(() => { if (mobileType) mobileType.classList.add('visible'); }, 3000);
        // 4s: fade in tagline + subline after type image settles
        setTimeout(() => { if (tagline) tagline.classList.add('visible'); }, 4000);
        setTimeout(() => { if (subline) subline.classList.add('visible'); }, 4600);
        // 7.5s: fade out entire overlay (text fades with it)
        setTimeout(() => {
            overlay.classList.add('fade-out');
            overlay.addEventListener('transitionend', () => {
                overlay.classList.add('splash-done');
            }, { once: true });
            setTimeout(() => { overlay.classList.add('splash-done'); }, 1500);
        }, 7500);
    } else {
        // Desktop / landscape: original sequence
        const title   = document.getElementById('splashTitle');
        const tagline = document.getElementById('splashTagline');
        const subline = document.getElementById('splashSubline');
        setTimeout(() => { if (title) title.classList.add('visible'); }, 2000);
        setTimeout(() => { if (tagline) tagline.classList.add('visible'); }, 3300);
        setTimeout(() => { if (subline) subline.classList.add('visible'); }, 4200);
        setTimeout(() => {
            overlay.classList.add('fade-out');
            overlay.addEventListener('transitionend', () => {
                overlay.classList.add('splash-done');
            }, { once: true });
            setTimeout(() => { overlay.classList.add('splash-done'); }, 1500);
        }, 6500);
    }
})();

// Wait for Supabase SDK to be available before using it
async function waitForSupabaseSDK(timeoutMs = 2000) {
  const start = Date.now();
  while (
    !(window.supabase && typeof window.supabase.createClient === 'function') &&
    (Date.now() - start) < timeoutMs
  ) {
    await new Promise(r => setTimeout(r, 25));
  }
  return window.supabase || null;
}
