  // Normalize world key — strips spaces / hyphens / underscores so the same
  // bias applies regardless of which form the world identifier takes
  // ("glass_house" vs "glass-house" vs "Glass House" all → "glasshouse").
  function _resolveWorldKey(state) {
      const raw =
          (state && state.picks && state.picks.worldSubtype) ||
          (state && state.worldSubtype) ||
          (state && state.world) ||
          (state && state.setting) ||
          '';
      return String(raw).toLowerCase().replace(/[\s\-_]/g, '');
  }

  // World-aware domain bias — duplicates preferred domains in the candidate
  // pool so `_pickCinematicDomain`'s random selection actually favors them
  // (reordering alone wouldn't bias since the picker uses uniform random).
  // Returns the base pool unchanged for unrecognized worlds.
  function _weightedDomainsForWorld(state, base) {
      const world = _resolveWorldKey(state);
      const W = (d, n) => Array(n).fill(d);
      if (world === 'glasshouse') {
          // Visibility / exposure feel — environmental + mechanical lead.
          return [...W('environmental', 3), ...W('mechanical', 2), ...base];
      }
      if (world === 'dogma') {
          // Systems / processing / containment feel.
          return [...W('mechanical', 3), ...W('environmental', 2), ...base];
      }
      if (world === 'fatelands') {
          // Mythic / elemental feel — cosmic / oceanic / weather lead.
          return [...W('cosmic', 3), ...W('oceanic', 2), ...W('weather', 2), ...base];
      }
      return base;
  }

  // Per-domain beat-signal regexes — looser than DOMAIN_SIGNALS, oriented
  // around the dramatic arc (approach / escalation / climax / aftermath)
  // rather than vocabulary breadth. Used by `_beatCoverageOk` to confirm
  // the LLM actually MAPPED the arc rather than dropping a pretty
  // standalone metaphor with no progression. Threshold: 2 of 4.
  const _CINEMATIC_BEAT_SIGNALS = {
      cosmic: {
          approach:   /\b(orbit|gravity|closing\s+distance)\b/i,
          escalation: /\b(accelerat|tighten|build\s+pressure|drawn\s+in)\b/i,
          climax:     /\b(collapse|rupture|event\s+horizon|collision|singularity)\b/i,
          aftermath:  /\b(debris|afterglow|quiet|drift|fall\s+silent)\b/i
      },
      weather: {
          approach:   /\b(front|pressure|heat\s+building|charged\s+air)\b/i,
          escalation: /\b(gather|surge|wind\s+rising|thicken)\b/i,
          climax:     /\b(break|thunder|lightning|downpour|burst)\b/i,
          aftermath:  /\b(rain\s+easing|cool\s+air|stillness|clearing)\b/i
      },
      oceanic: {
          approach:   /\b(tide|pull|undertow|drawn\s+out)\b/i,
          escalation: /\b(surge|crest|swell|rising\s+wave)\b/i,
          climax:     /\b(crash|break|swallow|submerge)\b/i,
          aftermath:  /\b(recede|foam|calm\s+water|ebb)\b/i
      },
      mechanical: {
          approach:   /\b(load|tension|set|align|hinge)\b/i,
          escalation: /\b(strain|tighten|shear\s+building|stress)\b/i,
          climax:     /\b(snap|failure|release|give\s+way|break)\b/i,
          aftermath:  /\b(settle|cooling|residual|loosen)\b/i
      },
      environmental: {
          approach:   /\b(out\s+of\s+place|shift\s+beginning|tilt|not\s+quite\s+steady)\b/i,
          escalation: /\b(things\s+moving|displaced|sliding|unfixed)\b/i,
          climax:     /\b(fell|toppled|gave\s+way|out\s+of\s+position)\b/i,
          aftermath:  /\b(by\s+morning|no\s+longer\s+where\s+it\s+had\s+been|quiet\s+room|left\s+changed)\b/i
      }
  };

  // Below this char threshold the beat-coverage check is skipped — short
  // ST3 paths (interruption, hesitation) legitimately can't hit 2 beats
  // and shouldn't be punished for being short. ~2-3 short paragraphs.
  const MIN_LEN_FOR_BEATS = 220;

  // Beat coverage with miss accounting — returns which beats hit and
  // which missed so telemetry can identify systematically weak regexes
  // (e.g. cosmic.escalation missing 60% of the time → loosen that cell).
  function _beatCoverageReport(text, domain) {
      const beats = _CINEMATIC_BEAT_SIGNALS[domain];
      if (!beats || !text) return { ok: true, hits: {}, misses: [], hitCount: 0 };
      const hits = {
          approach:   beats.approach.test(text),
          escalation: beats.escalation.test(text),
          climax:     beats.climax.test(text),
          aftermath:  beats.aftermath.test(text)
      };
      const hitCount = Object.values(hits).filter(Boolean).length;
      const misses = Object.keys(hits).filter(k => !hits[k]);
      return { ok: hitCount >= 2, hits, misses, hitCount };
  }

  // Density-scaled stuffing detector. On strict retries the LLM may try
  // to game `_domainSignalOk` by spraying domain keywords without real
  // metaphorical structure. We allow a base of 3 hits, then ~1 more per
  // 250 chars — so longer scenes can legitimately repeat vocabulary.
  function _domainSignalCount(text, domain) {
      const rx = _CINEMATIC_DOMAIN_SIGNALS[domain];
      if (!rx || !text) return 0;
      const matches = text.match(new RegExp(rx.source, 'gi'));
      return matches ? matches.length : 0;
  }

  function _domainSignalDensityFail(text, domain) {
      if (!text || !domain) return false;
      const count = _domainSignalCount(text, domain);
      const maxAllowed = Math.max(3, Math.floor(text.length / 250));
      return count > maxAllowed;
  }

  // Lightweight telemetry — lazy-init on first write, lives on state so
  // it persists across scenes within a story. Survey via
  // `state._cinematicTelemetry` from the console after a few ST3 scenes.
  function _initCinematicTelemetry(state) {
      if (!state) return;
      if (!state._cinematicTelemetry) {
          state._cinematicTelemetry = { retries: 0, byDomain: {} };
      }
  }

  function _ensureDomainTelemetry(state, domain) {
      _initCinematicTelemetry(state);
      const t = state._cinematicTelemetry;
      if (!t.byDomain[domain]) {
          t.byDomain[domain] = {
              retries: 0,
              beatMisses: { approach: 0, escalation: 0, climax: 0, aftermath: 0 }
          };
      }
      return t.byDomain[domain];
  }

  function _logBeatMisses(state, domain, misses) {
      if (!state || !misses || !misses.length) return;
      const d = _ensureDomainTelemetry(state, domain);
      misses.forEach(m => { d.beatMisses[m] = (d.beatMisses[m] || 0) + 1; });
  }

  function _logCinematicRetry(state, domain) {
      if (!state) return;
      const d = _ensureDomainTelemetry(state, domain);
      state._cinematicTelemetry.retries++;
      d.retries++;
  }

