          // register: raunchy stand-up comedy voice. Uses explicit
          // anatomy + acts WORDS as character voice (not as intimate
          // signals). Sonnet sanitizes the comedy beats; needs Grok.
          if (worldSubtype.indexOf('comedian') >= 0 ||
              worldSubtype.indexOf('stand_up') >= 0 ||
              worldSubtype.indexOf('standup') >= 0 ||
              worldSubtype.indexOf('shock_jock') >= 0 ||
              worldSubtype.indexOf('shockjock') >= 0 ||
              flavor.indexOf('comedian') >= 0 ||
              flavor.indexOf('stand_up') >= 0 ||
              flavor.indexOf('standup') >= 0 ||
              flavor.indexOf('shock_jock') >= 0) {
              return { key: 'comedian', template: MODE1_CHARACTER_TEMPLATES.comedian };
          }
