  /**
   * Resolve which female character template applies based on world flavor +
   * archetype. Priority: blue-blood > middle-class-professional > blue-collar.
   * Returns { key, template } or null when no template matches.
   */
  function _resolveMode1FemaleCharacterTemplate(s) {
      s = s || window.state || {};
      const liGender = String(s.loveInterest || s.loveInterestGender || _defaultLIGenderForPC(s)).toLowerCase();
      if (liGender !== 'female') return null;
      const arch = String(s.archetype && s.archetype.primary || '').toLowerCase();
      const world = String(s.picks && s.picks.world || '').toLowerCase();
      const worldSubtype = String(s.worldSubtype || (s.picks && s.picks.worldSubtype) || '').toLowerCase();
      const flavor = String(s.picks && s.picks.flavor || '').toLowerCase();

      // Modern-only — all three female templates assume modern register.
      if (!/modern/.test(world)) return null;

      // VIVIENNE — blue-blood / old-money / high-society wins first.
      if (worldSubtype.indexOf('blue-blood') >= 0 ||
          worldSubtype.indexOf('old-money') >= 0 ||
          worldSubtype.indexOf('high-society') >= 0 ||
          worldSubtype.indexOf('billionaire') >= 0 ||
          flavor === 'sovereign' ||
          flavor === 'billionaire') {
          return { key: 'vivienne', template: MODE1_FEMALE_CHARACTER_TEMPLATES.vivienne };
      }

      // MAYA — middle-class professional / corporate / social.
      if (worldSubtype.indexOf('middle-class') >= 0 ||
          worldSubtype.indexOf('professional') >= 0 ||
          worldSubtype.indexOf('corporate') >= 0 ||
          flavor.indexOf('professional') >= 0 ||
          flavor.indexOf('corporate') >= 0) {
          return { key: 'maya', template: MODE1_FEMALE_CHARACTER_TEMPLATES.maya };
      }

      // ALICE — blue-collar / working-class / trades / hospitality.
      if (worldSubtype.indexOf('blue-collar') >= 0 ||
          worldSubtype.indexOf('working-class') >= 0 ||
          worldSubtype.indexOf('small_town') >= 0 ||
          worldSubtype.indexOf('small-town') >= 0 ||
          worldSubtype.indexOf('trades') >= 0 ||
          worldSubtype.indexOf('hospitality') >= 0 ||
          flavor.indexOf('blue-collar') >= 0 ||
          flavor.indexOf('working-class') >= 0) {
          return { key: 'alice', template: MODE1_FEMALE_CHARACTER_TEMPLATES.alice };
      }

      return null; // No template — generic Female Mode 1 behavior applies.
  }
