          try { localStorage.setItem('sb_petition_first_whisper_consumed', '1'); } catch (_) {}
          try { console.log('[FATE-WHISPER] First click — granting free Petition Fate credit.'); } catch (_) {}
          if (typeof showToast === 'function') {
              showToast('A first petition, on the house. Try it.');
          }
