      // BANNED from prose mutation (it was the fallback here); a line-edit must never reach Haiku.
      _assertModelRoute('mistral-small-latest', 'line_edit', 'cheap-edit:' + (label || ''));
      var res = await fetch('/api/mistral-proxy', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ role: 'LINE_EDITOR', model: 'mistral-small-latest', temperature: 0.2, max_tokens: Math.max(1500, Math.ceil(originalText.length / 4) + 800), messages: [{ role: 'system', content: sys }, { role: 'user', content: user }] })
      });
      if (!res.ok) { try { console.warn('[CHEAP-EDIT] ' + (label || '') + ' mistral HTTP ' + res.status + ' — keeping original.'); } catch (_) {} return originalText; }
      var data = await res.json();
      var edited = (data && (data.content || (data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content))) || '';
      edited = edited.replace(/^\s*```[a-z]*\s*/i, '').replace(/\s*```\s*$/i, '').trim();
      if (!edited) return originalText;
      var oLen = originalText.length, nLen = edited.length;
