  window._ensureSceneCostAcc = _ensureSceneCostAcc;

  // ── DIRECT-PROXY COST RECORDER (Roman 2026-06-02) ──
  // The Bibles / R-plot / A-plot / audits call /api/anthropic-proxy (and the
  // A-plot's callOneProvider hits /api/proxy etc.) DIRECTLY, bypassing
  // orchestration-client's _accumulateTokens — so they were invisible in
  // [SCENE-COST]. Each such site calls this with the parsed proxy `data` (which
  // carries data.usage {prompt_tokens, completion_tokens, cache_*} and
  // data._orchestration.model) + a category. NOT double-counted: orchestration
  // routes prose/GPT through a different path; these raw fetches do not.
  //   category: 'setup' (once-per-story: bibles, r-plot, a-plot, scaffold) |
  //             'audit' (per-scene instrumentation) | 'scene' | 'wasted'.
  function _recordProxyTextCost(data, fallbackModel, category) {
      try {
          if (!data || !data.usage) return;
          var model = (data._orchestration && data._orchestration.model) || fallbackModel || 'default';
          var acc = _ensureSceneCostAcc();
          if (acc) acc.addText(model, data.usage, category || 'setup');
          // Lightweight last-model ledger so Famous Fate beta reports can attach
          // which model produced text (state holds no per-scene model otherwise).
          try {
              if (window.state) {
                  state._lastTextGen = { model: model, category: category || 'setup', ts: Date.now() };
                  state._lastTextModelByCategory = state._lastTextModelByCategory || {};
                  state._lastTextModelByCategory[category || 'setup'] = model;
              }
          } catch (_) {}
      } catch (_) {}
  }
  window._recordProxyTextCost = _recordProxyTextCost;

  // ── AUDIT LLM ROUTING (Roman 2026-06-26) ─────────────────────────────────────────────────
  // Audits/classifiers moved off Haiku → gpt-4o-mini (cheaper, best strict-JSON, and keeps Haiku
  // to setup/spine only per the routing rule). Drop-in for the audit fetches: pass the existing
  // anthropic-style body ({temperature, max_tokens, messages}) and this returns a fetch-LIKE
  // object whose .json() yields { content, usage } — so each audit's existing res.ok / data.content
  // parsing + downstream _recordProxyTextCost(data,'gpt-4o-mini','audit') keep working unchanged.
  async function _auditPost(body) {
    body = body || {};
    try {
      var r = await fetch('/api/chatgpt-proxy', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ role: 'PRIMARY_AUTHOR', model: 'gpt-4o-mini', temperature: (body.temperature != null ? body.temperature : 0.2), max_tokens: body.max_tokens || 600, messages: body.messages || [] })
      });
      if (!r.ok) return { ok: false, status: r.status, json: async function () { return {}; } };
      var d = await r.json();
      var content = (d && (d.content || (d.choices && d.choices[0] && d.choices[0].message && d.choices[0].message.content))) || '';
      return { ok: true, status: 200, json: async function () { return { content: content, usage: (d && d.usage) || null, _orchestration: { model: 'gpt-4o-mini' } }; } };
    } catch (e) { return { ok: false, status: 0, json: async function () { return {}; } }; }
  }
  window._auditPost = _auditPost;

  // ── SETUP REROLL ROUTING (Roman 2026-06-26) ──────────────────────────────────────────────
  // Short, schema-validated SETUP rerolls (bespoke axis, verb-guard, physical/behav-canon rewrite,
  // crisis reroll, 5-field/body-tell reroll) moved off Haiku → Mistral-Small (low-risk: output is
  // short + validated, and the existing reroll/validation guards catch bad JSON). Drop-in like
  // _auditPost: pass the anthropic-style body; returns a fetch-like obj whose .json() yields
  // {content, usage, _orchestration:{model}} so downstream data.content parsing + cost-record (which
  // reads _orchestration.model) record as mistral-small without touching the cost-record lines.
  async function _setupMistralPost(body) {
    body = body || {};
    try {
      var r = await fetch('/api/mistral-proxy', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ role: 'STRUCTURE_GENERATOR', model: 'mistral-small-latest', temperature: (body.temperature != null ? body.temperature : 0.7), max_tokens: body.max_tokens || 600, messages: body.messages || [] })
      });
      if (!r.ok) return { ok: false, status: r.status, json: async function () { return {}; } };
      var d = await r.json();
      var content = (d && (d.content || (d.choices && d.choices[0] && d.choices[0].message && d.choices[0].message.content))) || '';
      return { ok: true, status: 200, json: async function () { return { content: content, usage: (d && d.usage) || null, _orchestration: { model: 'mistral-small-latest' } }; } };
    } catch (e) { return { ok: false, status: 0, json: async function () { return {}; } }; }
  }
  window._setupMistralPost = _setupMistralPost;

  // ── PER-SCENE CONDITIONAL-REPAIR CIRCUIT BREAKER (Roman 2026-06-26, Phase 1) ──────────────
  // _sceneCostAcc buckets author+repair together, so the breaker keeps its OWN per-scene counter
  // of CONDITIONAL repair/polish/fallback STARTS (the unconditional author + de-calc + repair
  // baseline is NOT counted; deterministic scrubs/closer/POV fixes are NOT counted — they make no
  // LLM call). Once the cap is hit, new conditional repair passes are skipped (the spiral stops);
