  // large+stable builders that aren't cached) before refactoring anything.
  // ═══════════════════════════════════════════════════════════════════════════
  const _SCENE_AUDIT_LS_KEY = 'sb_scene_audit_v1';
  const _SCENE_AUDIT_MAX = 20; // was 50 — trimmed to reduce localStorage-quota pressure (Roman 2026-06-04 lockout)

  function _ensureSceneAuditAcc() {
      if (!window.state) return null;
      if (!window.state._sceneAuditAcc) {
          window.state._sceneAuditAcc = {
              startedAt: Date.now(),
              firstLlmResponseAt: null,
              firstProseResponseAt: null,
              storyId: window.state.storyId || null,
              sceneIndex: (typeof window.state.turnCount === 'number') ? window.state.turnCount : null,
              regens: [],
              callCount: 0,
              proseCallCount: 0
          };
      }
      return window.state._sceneAuditAcc;
  }
  window._ensureSceneAuditAcc = _ensureSceneAuditAcc;

  // Hooked from acc.addText so every text response (orchestration + raw proxy)
  // contributes timing data. category is the same label addText already uses.
  function _auditOnTextCall(model, usage, category) {
      const a = _ensureSceneAuditAcc();
      if (!a) return;
      const now = Date.now();
      if (a.firstLlmResponseAt == null) a.firstLlmResponseAt = now;
      if ((category === 'main' || category === 'scene') && a.firstProseResponseAt == null) {
          a.firstProseResponseAt = now;
      }
      a.callCount++;
      if (category === 'main' || category === 'scene') a.proseCallCount++;
  }
  window._auditOnTextCall = _auditOnTextCall;

  // Record one regen attempt with before/after fail counts. Each site computes
  // its own before/after by running the same validator on raw + regen output.
  // Pass costRaw (sum of acc.breakdown.text entries added during the regen) +
  // ms (wall-clock for the regen call). improvementDetected is auto-computed.
  function _auditRecordRegen(opts) {
      const a = _ensureSceneAuditAcc();
      if (!a) return;
      const b = (opts && opts.before) || { hardFails: null, softFails: null };
      const af = (opts && opts.after) || { hardFails: null, softFails: null };
      let improvementDetected = null;
      if (b.hardFails != null && af.hardFails != null) {
          improvementDetected =
              (af.hardFails < b.hardFails) ||
              (af.hardFails === b.hardFails && (af.softFails || 0) < (b.softFails || 0));
      }
      a.regens.push({
          gate: (opts && opts.gate) || 'unknown',
          reason: (opts && opts.reason) || null,
          model: (opts && opts.model) || null,
          outcome: (opts && opts.outcome) || 'accepted',
          costRaw: (opts && opts.costRaw) || 0,
          ms: (opts && opts.ms) || 0,
          hardFailsBefore: b.hardFails,
          softFailsBefore: b.softFails,
          hardFailsAfter: af.hardFails,
          softFailsAfter: af.softFails,
          improvementDetected: improvementDetected,
          at: Date.now()
      });
  }
  window._auditRecordRegen = _auditRecordRegen;

  // Helper for regen sites: snapshot cost-acc length BEFORE the regen, run it,
  // sum the newly-added cost entries AFTER. Returns { costRaw, model, ms }.
  // Caller still needs to compute hardFailsBefore/After and pass to recordRegen.
  function _auditRegenSnapshot() {
      const acc = window.state && window.state._sceneCostAcc;
      const startLen = (acc && acc.breakdown && acc.breakdown.text) ? acc.breakdown.text.length : 0;
      const t0 = Date.now();
      return {
          finish: function () {
              const _newCalls = (acc && acc.breakdown && acc.breakdown.text)
                  ? acc.breakdown.text.slice(startLen) : [];
              const _cost = _newCalls.reduce(function (s, c) { return s + (c.cost || 0); }, 0);
              const _model = (_newCalls[0] && _newCalls[0].model) || null;
              return { costRaw: _cost, model: _model, ms: Date.now() - t0 };
          }
      };
  }
  window._auditRegenSnapshot = _auditRegenSnapshot;

  // Finalize: pull builder bytes from existing state._lastPromptAudit, diff
  // against last scene's builder heads for changedSincePrev, persist record.
  // Called from _finalizeSceneCost AFTER _sealedSceneCostAcc is set.
  function _finalizeSceneAudit() {
      const a = window.state && window.state._sceneAuditAcc;
      if (!a) return;
      const acc = window.state && window.state._sealedSceneCostAcc;
      const now = Date.now();

      // Spend by category (raw, NOT overhead-multiplied — audit talks in real $).
      const spend = { initial: 0, regens: 0, setup: 0, audits: 0, wasted: 0, total: 0 };
      const _txt = (acc && acc.breakdown && acc.breakdown.text) || [];
      for (const e of _txt) {
          const c = (e && e.cost) || 0;
          const cat = (e && e.category) || 'main';
          spend.total += c;
          if (cat === 'setup') spend.setup += c;
          else if (cat === 'audit') spend.audits += c;
          else if (cat === 'wasted') spend.wasted += c;
          else spend.initial += c; // 'main' and 'scene' + unknown
      }
      // Regen cost: sum across recorded regens (each carries its own costRaw).
      for (const r of a.regens) spend.regens += (r.costRaw || 0);
      // Subtract regen cost from initial to avoid double-count (regen calls
      // ARE in breakdown.text under 'main'/'scene' category by default).
      spend.initial = Math.max(0, spend.initial - spend.regens);

      // Cache token totals from breakdown.text usage. Provider-aware (Roman 2026-07-11): the
      // author is Grok + gpt-4o-mini now (OpenAI-shaped), NOT Anthropic — so read the OpenAI/Grok
      // cache field (cached_tokens, a SUBSET of prompt_tokens) as well as the legacy Anthropic
      // fields. For OpenAI, prompt_tokens is the TOTAL input; do not double-count the cached slice.
      let cacheRead = 0, cacheWrite = 0, freshIn = 0;
      for (const e of _txt) {
          const u = e && e.usage;
          if (!u) continue;
          if (typeof u.input_tokens === 'number') {
              // Anthropic shape: input_tokens = fresh (uncached); cache read/creation are separate.
              cacheRead += u.cache_read_input_tokens || 0;
              cacheWrite += u.cache_creation_input_tokens || 0;
              freshIn += u.input_tokens;
          } else if (typeof u.prompt_tokens === 'number') {
              // OpenAI/Grok shape: prompt_tokens = TOTAL input; cached_tokens is a subset of it.
              const _cached = (typeof u.cached_tokens === 'number' ? u.cached_tokens
                  : ((u.prompt_tokens_details && u.prompt_tokens_details.cached_tokens) || 0));
              cacheRead += _cached;
              freshIn += Math.max(0, u.prompt_tokens - _cached);
          }
      }
      const totalTok = cacheRead + cacheWrite + freshIn;

      // Builders: pull from the existing _dszParts capture and diff against
      // previous scene's heads (stored on state._prevSceneBuilderHeads).
      const promptAudit = (window.state && window.state._lastPromptAudit) || null;
      const prevHeads = (window.state && window.state._prevSceneBuilderHeads) || {};
      const builders = [];
      const newPrevHeads = {};
      if (promptAudit && Array.isArray(promptAudit.parts)) {
          for (const p of promptAudit.parts) {
              const name = p.name;
              const bytes = p.len || 0;
              const head = p.head || '';
              const changedSincePrev = (prevHeads[name] != null) ? (prevHeads[name] !== head) : null;
              builders.push({ name: name, bytes: bytes, changedSincePrev: changedSincePrev });
              newPrevHeads[name] = head;
          }
      }
      window.state._prevSceneBuilderHeads = newPrevHeads;

      const record = {
          ts: now,
          storyId: a.storyId,
          sceneIndex: a.sceneIndex,
          startedAt: a.startedAt,
          totalMs: now - a.startedAt,
          ttftMs: (a.firstLlmResponseAt != null) ? (a.firstLlmResponseAt - a.startedAt) : null,
          ttftProseMs: (a.firstProseResponseAt != null) ? (a.firstProseResponseAt - a.startedAt) : null,
          prompt: {
              cacheReadTok: cacheRead,
              cacheWriteTok: cacheWrite,
              freshTok: freshIn,
              totalTok: totalTok,
              hitPct: totalTok > 0 ? Math.round(100 * cacheRead / totalTok) : 0
          },
          callCount: a.callCount,
          proseCallCount: a.proseCallCount,
          regens: a.regens,
          spend: {
              initial: Number(spend.initial.toFixed(5)),
              regens: Number(spend.regens.toFixed(5)),
              setup: Number(spend.setup.toFixed(5)),
              audits: Number(spend.audits.toFixed(5)),
              wasted: Number(spend.wasted.toFixed(5)),
              total: Number(spend.total.toFixed(5))
          },
          builders: builders
      };

      try {
          console.log('[SCENE-AUDIT]', JSON.stringify({
              sc: record.sceneIndex,
              ms: record.totalMs,
              ttft: record.ttftMs,
              ttftProse: record.ttftProseMs,
              spend: record.spend,
              hitPct: record.prompt.hitPct,
              regens: record.regens.length,
              gates: record.regens.map(function (r) { return r.gate + (r.improvementDetected === false ? '✗' : r.improvementDetected === true ? '✓' : '?'); }).join(',')
          }));
      } catch (_) {}
      try {
          const raw = localStorage.getItem(_SCENE_AUDIT_LS_KEY);
          const arr = raw ? JSON.parse(raw) : [];
          arr.push(record);
          while (arr.length > _SCENE_AUDIT_MAX) arr.shift();
          localStorage.setItem(_SCENE_AUDIT_LS_KEY, JSON.stringify(arr));
      } catch (e) {
          try { console.warn('[SCENE-AUDIT] persist failed:', e && e.message); } catch (_) {}
      }
      window.state._sceneAuditAcc = null;

      // Lock-turn classifier (Roman 2026-06-09) — async Haiku read of the
      // finalized scene's prose against pairBond. No-ops when pairBond is
      // missing or prose isn't yet on state.scenes[]. Updates the LS record
      // in place when classification returns.
      try { if (typeof _scheduleLockTurnClassification === 'function') _scheduleLockTurnClassification(); } catch (_) {}

      // Health check (Roman 2026-06-09) — aggregates scene-audit + lock-turn
      // data across the last 50 scenes, flags new issues (calcification,
      // under/over-pressed locks, regen cost without benefit, cache drops,
      // cost climbing, pairBond off-vocab). Silent when healthy except for
      // periodic confirmation every 5 scenes. Toasts + warns on FIRST
      // detection of each new issue; subsequent scenes don't re-toast.
      try { if (typeof _storyboundHealthMaybeAlert === 'function') _storyboundHealthMaybeAlert(); } catch (_) {}
  }
  window._finalizeSceneAudit = _finalizeSceneAudit;

  // ── Readers ──
  window._auditTail = function (N) {
      N = (typeof N === 'number' && N > 0) ? N : 10;
      try {
          const raw = localStorage.getItem(_SCENE_AUDIT_LS_KEY);
          const arr = raw ? JSON.parse(raw) : [];
          return arr.slice(-N);
      } catch (_) { return []; }
  };

  // Cost-center table: aggregates last N audits into the table the user wants.
  // Reports % of total spend AND % of total ms per cost center. Regen rows are
  // attribued per-gate; setup/initial/audits are flat categories.
  window._auditTable = function (N) {
      N = (typeof N === 'number' && N > 0) ? N : 50;
      const arr = window._auditTail(N);
      if (!arr.length) { console.warn('[SCENE-AUDIT] no records yet'); return []; }
      const centers = {};
      const add = function (name, spend, ms) {
          const c = centers[name] = centers[name] || { spend: 0, ms: 0, count: 0, regensFired: 0, regensImproved: 0, regensSoftKept: 0 };
          c.spend += spend || 0; c.ms += ms || 0; c.count += 1;
      };
      let totalSpend = 0, totalMs = 0;
      for (const rec of arr) {
          totalSpend += rec.spend.total || 0;
          totalMs += rec.totalMs || 0;
          add('initial-draft', rec.spend.initial, rec.ttftProseMs || rec.ttftMs || 0);
          add('setup-bibles', rec.spend.setup, 0);
          add('audits', rec.spend.audits, 0);
          add('wasted', rec.spend.wasted, 0);
          for (const r of (rec.regens || [])) {
              const key = 'regen:' + (r.gate || 'unknown');
              const c = centers[key] = centers[key] || { spend: 0, ms: 0, count: 0, regensFired: 0, regensImproved: 0, regensSoftKept: 0 };
              c.regensFired += 1;
              c.spend += (r.costRaw || 0);
              c.ms += (r.ms || 0);
              if (r.improvementDetected === true) c.regensImproved += 1;
              if (r.outcome === 'soft-kept') c.regensSoftKept += 1;
          }
      }
      const rows = Object.keys(centers).map(function (name) {
          const c = centers[name];
          return {
              center: name,
              scenes: c.count,
              spend$: Number(c.spend.toFixed(4)),
              pctSpend: totalSpend > 0 ? Math.round(100 * c.spend / totalSpend) : 0,
              ms: c.ms,
              pctMs: totalMs > 0 ? Math.round(100 * c.ms / totalMs) : 0,
              regensFired: c.regensFired,
              improvedRatio: c.regensFired > 0 ? Math.round(100 * c.regensImproved / c.regensFired) + '%' : 'n/a'
          };
      }).sort(function (a, b) { return b.spend$ - a.spend$; });
      try { console.table(rows); } catch (_) { console.log(rows); }
      return rows;
  };

  // Per-gate regen histogram across last N audits — includes outcome breakdown.
  window._auditHistogram = function (N) {
      N = (typeof N === 'number' && N > 0) ? N : 50;
      const arr = window._auditTail(N);
      if (!arr.length) { console.warn('[SCENE-AUDIT] no records yet'); return {}; }
      const gates = {};
      for (const rec of arr) {
          for (const r of (rec.regens || [])) {
              const g = r.gate || 'unknown';
              const e = gates[g] = gates[g] || { fired: 0, improved: 0, noChange: 0, regressed: 0, softKept: 0, fallback: 0, rejectedDrift: 0, totalCost$: 0 };
              e.fired += 1;
              e.totalCost$ += (r.costRaw || 0);
              if (r.improvementDetected === true) e.improved += 1;
              else if (r.improvementDetected === false) e.regressed += 1;
              else e.noChange += 1;
              if (r.outcome === 'soft-kept') e.softKept += 1;
              if (r.outcome === 'fallback') e.fallback += 1;
              if (r.outcome === 'rejected_drift') e.rejectedDrift += 1;
          }
      }
      Object.keys(gates).forEach(function (g) { gates[g].totalCost$ = Number(gates[g].totalCost$.toFixed(4)); });
      try { console.table(gates); } catch (_) { console.log(gates); }
      return gates;
  };

  // Cache-opportunity ranking: which builders are LARGE and STABLE.
  // stability = fraction of scenes where the head 240c did NOT change.
  // opportunity score = avgBytes × stability (large + stable wins).
  window._auditCacheOpportunity = function (N) {
      N = (typeof N === 'number' && N > 0) ? N : 50;
      const arr = window._auditTail(N);
      if (!arr.length) { console.warn('[SCENE-AUDIT] no records yet'); return []; }
      const bld = {};
      for (const rec of arr) {
          for (const b of (rec.builders || [])) {
              const e = bld[b.name] = bld[b.name] || { sizes: [], changed: 0, unchanged: 0 };
              e.sizes.push(b.bytes);
              if (b.changedSincePrev === true) e.changed += 1;
              else if (b.changedSincePrev === false) e.unchanged += 1;
          }
      }
      const rows = Object.keys(bld).map(function (name) {
          const e = bld[name];
          const totalDiff = e.changed + e.unchanged;
          const avgBytes = e.sizes.reduce(function (a, b) { return a + b; }, 0) / e.sizes.length;
          const stability = totalDiff > 0 ? (e.unchanged / totalDiff) : null;
          const opportunity = (stability != null) ? Math.round(avgBytes * stability) : 0;
          return {
              builder: name,
              avgBytes: Math.round(avgBytes),
              scenes: e.sizes.length,
              stability: stability != null ? Math.round(stability * 100) + '%' : 'n/a',
              opportunity: opportunity
          };
      }).sort(function (a, b) { return b.opportunity - a.opportunity; });
      try { console.table(rows.slice(0, 30)); } catch (_) { console.log(rows.slice(0, 30)); }
      return rows;
  };

  window._auditClear = function () {
      try { localStorage.removeItem(_SCENE_AUDIT_LS_KEY); } catch (_) {}
      try { if (window.state) window.state._prevSceneBuilderHeads = {}; } catch (_) {}
      console.log('[SCENE-AUDIT] cleared');
  };

  // Concierge-facing helpers. Returns formatted strings; Concierge wires these
  // into its response logic when user asks about cost.
  //
  // PRODUCTION GUARD: every cost-revealing helper checks isDevMode() first.
  // In production, helpers return the deflection string so cost data is
  // never leaked. In dev (localhost / 127.0.0.1 / *.local / window.__DEV__)
  // they return real cost phrases.
  function isDevMode() {
      try {
          if (typeof window === 'undefined') return false;
          const host = window.location && window.location.hostname;
          if (!host) return false;
          return (
              host === 'localhost' ||
              host === '127.0.0.1' ||
              host.endsWith('.local') ||
              window.__DEV__ === true
          );
      } catch (_) {
          return false;
      }
  }
  window.isDevMode = isDevMode;

  const COST_PROD_DEFLECTION = "I don't keep track of costs like that. I just keep the story moving.";

  function formatCents(dollars) {
      // Spec 1: 2-decimal cents (e.g. 4.20¢)
      return (Math.round(dollars * 100 * 100) / 100) + '¢';
  }
  function formatCentsOneDecimal(dollars) {
      // Spec 2 (toCents): 1-decimal cents for averages/ranges (e.g. 11.2¢)
      return (Math.round(dollars * 100 * 10) / 10) + '¢';
  }
  function formatDollars(dollars) {
      return '$' + (Math.round(dollars * 100) / 100).toFixed(2);
  }

  // Optional context line per Spec 1 Part 5.
  function _sceneWeightContext(cost) {
      if (cost > 0.10) return ' That was a heavier scene.';
      if (cost < 0.03) return ' That was a light scene.';
      return '';
  }

  // Last-scene cost phrase. Returns null if no scene generated yet (caller
  // decides UX). Production-guarded.
  function getLastSceneCostPhrase() {
      if (!isDevMode()) return COST_PROD_DEFLECTION;
      const s = window.state || {};
      if (typeof s._lastSceneAPICost !== 'number' || s._lastSceneAPICost <= 0) {
          return null; // "no scene yet" — Concierge says "You haven't generated a scene yet."
      }
      return 'That scene cost about ' + formatCents(s._lastSceneAPICost) + ' to generate.' +
             _sceneWeightContext(s._lastSceneAPICost);
  }

  // Cumulative cost phrase. Production-guarded.
  function getCumulativeCostPhrase() {
      if (!isDevMode()) return COST_PROD_DEFLECTION;
      const s = window.state || {};
      if (typeof s._cumulativeAPICost !== 'number' || s._cumulativeAPICost <= 0) return null;
      return 'So far, you\'ve spent about ' + formatDollars(s._cumulativeAPICost) + ' generating this story.';
  }

  // Per-type average cost phrases (grok / gn / literary). Returns the
  // appropriate phrase for each type, with avg + range. Production-guarded.
  // type: 'grok' | 'gn' | 'literary'
  function getCategoryCostPhrase(type) {
      if (!isDevMode()) return COST_PROD_DEFLECTION;
      const s = window.state || {};
      const stats = s._costStats && s._costStats[type];
      if (!stats || stats.count === 0) {
          // Friendly per-type "not enough data" line.
          const labelMap = { grok: 'Grok', gn: 'GN', literary: 'Literary' };
          const label = labelMap[type] || type;
          return 'I haven\'t seen enough ' + label + ' scenes yet to estimate that.';
      }
      const avg = stats.total / stats.count;
      const labelLowerMap = { grok: 'Grok', gn: 'GN', literary: 'Literary' };
      const label = labelLowerMap[type] || type;
      return label + ' scenes usually cost about ' + formatCentsOneDecimal(avg) +
             ', typically ranging from ' + formatCentsOneDecimal(stats.min) +
             ' to ' + formatCentsOneDecimal(stats.max) + '.';
  }

  window.fateCostHelpers = {
      isDevMode,
      formatCents,
      formatCentsOneDecimal,
      formatDollars,
      getLastSceneCostPhrase,
      getCumulativeCostPhrase,
      getCategoryCostPhrase,
      // Convenience shorthands for the three category phrases.
      getGrokCostPhrase:     function() { return getCategoryCostPhrase('grok'); },
      getGnCostPhrase:       function() { return getCategoryCostPhrase('gn'); },
      getLiteraryCostPhrase: function() { return getCategoryCostPhrase('literary'); }
  };

  /**
   * Compact directive (~50 tokens). LLM may emit any of three signals at
   * scene end; multiple are allowed when applicable. Phase 1 telemetry only.
   */
  function buildSceneSignalsDirective() {
      if (!window.state) return '';
      const turn = window.state.turnCount || 0;
      if (turn < 1) return '';
      return '\nSCENE SIGNALS (telemetry — emit any that apply at scene end, on their own line):\n' +
             '    <<INTIMACY>>          — physical intimacy occurred or was attempted\n' +
             '    <<MAJOR_CONSEQUENCE>> — betrayal, rejection, major loss, fundamental relationship shift\n' +
             '    <<MEANINGFUL_SHIFT>>  — clear emotional or relational direction change\n' +
             '  Multiple may apply. Markers are invisible (system strips). If unsure → omit.\n';
  }
  window.buildSceneSignalsDirective = buildSceneSignalsDirective;

  /**
   * Build the compact system-prompt directive for FORCE marker emission.
   * Token-light (~90 tokens). Suppression mirrors the Friction directive:
   * skip Scene 1, ST5+, when 3/3 cap hit, and during lexical_probe scenes.
   *
   * The directive explicitly forbids co-emission with FRICTION (mutual
   * exclusion at the LLM level — render-side mutual exclusion handles
   * violations defensively).
   */
  function buildForceMarkerDirective() {
      if (!window.state) return '';
      const turn = window.state.turnCount || 0;
      // Tempt Fate's diegetic reveal is Scene 3, so don't even ask the LLM
      // to emit FORCE markers before then.
      if (turn < 2) return '';
      const st = window.state.storyturn || 'ST1';
      // Tempt only fires ST3 / ST4 — no point asking for the marker outside.
      if (!/^ST[34]$/.test(st)) return '';
      // Per-arc cap reached. Launch cap is 2 (down from spec's earlier 3).
      const tw = window.state._temptWhisper || {};
      if ((tw.count || 0) >= 2) return '';
      // Kill switch — skip emitting the directive entirely when Tempt is
      // globally disabled. Saves tokens; LLM won't even consider FORCE.
      if (window.state._disableTemptWhispers) return '';
      // Spacing — don't ask if last Tempt fired recently.
      if (tw.lastTurn != null && (turn - tw.lastTurn) < 5) return '';
      // Don't compete with the lexical probe.
      if (window.state._explicitSignalSource === 'lexical_probe') return '';

      // LAUNCH-TIGHTENED: only fatal + physical-HARD-BLOCK eligible. Institutional
      // and time emissions are suppressed at launch (telemetry-only via scrub log).
      // Bar is "cannot proceed without breaking the world."
      return '\nFORCE MARKER (very rare — emit AT MOST ONE per scene, only on UNDENIABLE external constraint):\n' +
             '  Use ONLY when a reader would feel "this cannot proceed without breaking the world" — death, apparent\n' +
             '  death, or a HARD physical block (escape sealed, path destroyed, body physically cannot move).\n' +
             '    <<FORCE:fatal>>    — death, dying, apparent fatal end, mortal injury, irreversible loss\n' +
             '    <<FORCE:physical>> — HARD BLOCK only: rubble seals the only exit / locked from outside / pinned\n' +
             '                          and unable to move / cliff fell behind them. NOT for routine obstacles.\n' +
             '  HARD CONSTRAINTS:\n' +
             '    • If unsure → DO NOT emit.\n' +
             '    • Never emit in low or medium tension.\n' +
             '    • Never emit alongside <<FRICTION:*>>.\n' +
             '    • Never emit for INSTITUTIONAL (law, oath, family) or TIME (deadline) cases at this stage —\n' +
             '      reserved for later expansion; suppress those even when tempted.\n' +
             '  Place at scene end, on its own line. Marker is invisible to the reader (system strips).\n';
  }
  window.buildForceMarkerDirective = buildForceMarkerDirective;

  // ── Tempt whisper template library (LAUNCH — restrained, 6 lines total) ──
  // Theatrical lines from earlier draft removed: "answer to you", "bend to your
  // will", "make fate answer for this", "force fate to give you one moment more".
  // Institutional + time pools dropped — those force types are launch-suppressed.
  // Each line: 8-14 words, includes "fate" or strongly implies it, restrained tone.
  const TEMPT_WHISPER_TEMPLATES = {
      physical: [
          'Or force fate to clear the way.',
          'Or refuse to let the path stay closed.'
      ],
      fatal: [
          'Or refuse to let this be how it ends.',
          'Or see what happens if this isn\'t the end yet.'
      ],
      general: [
          'Or refuse to let this be final.',
          'Or see what happens if fate is wrong.'
      ]
  };

  /**
   * Pick one Tempt template for the given force type, avoiding the last 3
   * used (per-story rotation). Falls back to general pool if force type
   * pool is empty or all candidates were recently used.
   */
  function generateTemptWhisper(forceType) {
      const _normalized = (forceType && TEMPT_WHISPER_TEMPLATES[forceType]) ? forceType : 'general';
      const candidates = (TEMPT_WHISPER_TEMPLATES[_normalized] || TEMPT_WHISPER_TEMPLATES.general || []).slice();
      if (candidates.length === 0) return null;

      if (!window.state) return candidates[0];
      window.state._temptWhisper = window.state._temptWhisper || { lastTurn: null, count: 0, lastUsed: [] };
      const lastUsed = window.state._temptWhisper.lastUsed || [];

      const fresh = candidates.filter(t => lastUsed.indexOf(t) === -1);
      const pickFrom = fresh.length > 0 ? fresh : candidates;
      const pick = pickFrom[Math.floor(Math.random() * pickFrom.length)];

      window.state._temptWhisper.lastUsed = [pick].concat(lastUsed).slice(0, 3);
      return pick;
  }
  window.generateTemptWhisper = generateTemptWhisper;

  /**
   * Tempt whisper render gate — parallel to _maybeRenderFateWhisper. Returns
   * the Tempt whisper HTML string, or null when any gate fails.
   *
   * GATES (strict):
   *   • state._force.type set + state._force.turn === current turn
   *   • storyturn ∈ ['ST3', 'ST4']
   *   • count < 3 (per-arc cap)
   *   • turnCount - lastTurn >= 5 (spacing)
   *   • turnCount >= 2 (Tempt Fate diegetic unlock)
   *   • NOT colliding with Petition whisper this turn (mutual exclusion)
   *   • NOT during lexical_probe scenes
   *
   * Side effects on success: increments count, stamps lastTurn, sets
   * state._highlightTemptFate = true, applies body.highlight-tempt-fate
   * class. Clears state._force (single-use signal).
   */
  function _maybeRenderTemptWhisper(mode) {
      const _state = window.state;
      if (!_state) return null;
      // KILL SWITCH — global suppression without unwiring upstream pipeline.
      if (_state._disableTemptWhispers) return null;
      const _twState = _state._temptWhisper = _state._temptWhisper || { lastTurn: null, count: 0, lastUsed: [] };
      const _force = _state._force || { type: null, turn: null };
      const _twTurn = _state.turnCount || 0;

      // AUTO-EXPIRE: if the turn has advanced past the last Tempt render,
      // clear the highlight flag. Prevents "ghost glow" when the user moved
      // on without clicking. Click-time clear handles the click path; this
      // handles the navigate-past path.
      if (_twState.lastTurn != null && _twTurn > _twState.lastTurn) {
          if (_state._highlightTemptFate) {
              _state._highlightTemptFate = false;
              try { console.log('[TEMPT-WHISPER] Auto-expired highlight (turn advanced past lastTurn:', _twState.lastTurn, ')'); } catch (_) {}
          }
      }

      // Reflect highlight state in DOM (after auto-expire so the body class
      // matches the post-expiration flag value).
      try {
          if (_state._highlightTemptFate) document.body.classList.add('highlight-tempt-fate');
          else document.body.classList.remove('highlight-tempt-fate');
      } catch (_) {}

      // Mutual exclusion: if Petition whisper rendered this same turn, bail.
      const _fwState = _state._fateWhisper || {};
      if (_fwState.activeOnTurn === _twTurn) {
          try { console.log('[TEMPT-WHISPER] Skipping — Petition whisper already rendered this turn.'); } catch (_) {}
          return null;
      }

      // Hard gates (LAUNCH-TIGHTENED).
      // Eligibility: fatal OR physical only. Institutional / time markers
      // may still arrive from LLM violations — render-side rejects them
      // (scrub-side telemetry already logs the violation).
      const _LAUNCH_ELIGIBLE_FORCE = ['fatal', 'physical'];
      const _twSt = _state.storyturn || 'ST1';
      const _gate =
          !!_force.type
          && _LAUNCH_ELIGIBLE_FORCE.indexOf(_force.type) >= 0
          && _force.turn === _twTurn
          && _twTurn >= 2
          && /^ST[34]$/.test(_twSt)
          && (_twState.count || 0) < 2
          && (_twState.lastTurn == null || (_twTurn - _twState.lastTurn) >= 5)
          && _state._explicitSignalSource !== 'lexical_probe';
      if (!_gate) {
          // Telemetry on rejected ineligible types — useful to see whether
          // LLM is honoring the "no institutional / time at launch" rule.
          if (_force.type && _LAUNCH_ELIGIBLE_FORCE.indexOf(_force.type) < 0) {
              try { console.warn('[TEMPT-WHISPER] Rejected ineligible force type at launch:', _force.type); } catch (_) {}
          }
          return null;
      }

      if (typeof generateTemptWhisper !== 'function') return null;
      const _twText = generateTemptWhisper(_force.type);
      if (!_twText) return null;

      _twState.count = (_twState.count || 0) + 1;
      _twState.lastTurn = _twTurn;
      _twState.activeOnTurn = _twTurn;
      _twState.activeText = _twText;
      _twState.activeForce = _force.type;
      _state._highlightTemptFate = true;
      try { document.body.classList.add('highlight-tempt-fate'); } catch (_) {}
      try { console.log('[TEMPT-WHISPER] Rendered (' + (mode || '?') + '):', _force.type, '| count:', _twState.count, '/', 3); } catch (_) {}

      const _twHtml =
          '<p class="tempt-whisper-line" data-force="' +
          _force.type + '" data-turn="' + _twTurn + '" data-mode="' + (mode || '') + '">' +
          '<span class="tempt-whisper" data-action="tempt" role="button" tabindex="0">' +
          _twText + '</span></p>';

      // FORCE LOCK: clear after consumption (mirrors friction lock).
      _state._force = { type: null, turn: null };

      return _twHtml;
  }
  window._maybeRenderTemptWhisper = _maybeRenderTemptWhisper;

  // ── Tempt whisper click → open Tempt Fate ──
  // No first-click free credit (Tempt is the dangerous option; the discovery
  // momentum belongs to Petition). Clicking simply opens the modal.
  function _onTemptWhisperClick(ev) {
      const span = ev.target.closest && ev.target.closest('.tempt-whisper[data-action="tempt"]');
      if (!span) return;
      ev.preventDefault();
      ev.stopPropagation();

      const _state = window.state;
      if (!_state) return;

      // Clear the highlight flag — user found Tempt Fate.
      _state._highlightTemptFate = false;
      try { document.body.classList.remove('highlight-tempt-fate'); } catch (_) {}

      // Visual feedback.
      span.classList.add('opening');
      setTimeout(() => span.classList.remove('opening'), 600);

      if (typeof window.openTemptZoom === 'function') {
          try { window.openTemptZoom(); }
          catch (e) { console.warn('[TEMPT-WHISPER] openTemptZoom failed:', e && e.message); }
      } else {
          console.warn('[TEMPT-WHISPER] openTemptZoom not available.');
      }
  }
  document.addEventListener('click', _onTemptWhisperClick);
  document.addEventListener('keydown', function(ev) {
      if (ev.key !== 'Enter' && ev.key !== ' ') return;
      const span = ev.target.closest && ev.target.closest('.tempt-whisper[data-action="tempt"]');
      if (!span) return;
      _onTemptWhisperClick(ev);
  });

  // ── Mode 1 LIVE-SYSTEM TEST COMMANDS ──────────────────────────────
  // Console-only utilities for forcing Mode 1 triggers in real
  // playthroughs without relying on RNG / archetype luck. Use during
  // development to verify the live LLM-call flow + Grok routing.
  // Run each from the browser console DURING a real story session.

  function _mode1TestLiKey() {
      var s = window.state || {};
      return (s.storybeau && s.storybeau.name) || s.loveInterestName || 'primary';
  }

  // Force the male-whisper variant to fire on the NEXT scene.
  // Sets gates that would normally have to align organically:
  //   • storyturn → ST2 if currently ST3+ wouldn't qualify
  //   • storyLength → 'fling' if not Fling/Affair
  //   • archetype → 'spellbinder' if not in dominant cohort
  //   • contentMode → 'full' (receptivity)
  //   • loveInterest → 'Male' (whisper variant is male-coded)
  //   • clears firedFor / rejectedFor for current LI
  //   • bypasses the 35% probability roll (forceFireNext flag)
  window._mode1ForceWhisperNext = function() {
      if (!window.state) { console.error('[MODE1:TEST] No state — start a story first.'); return; }
      if (!window.state._mode1) {
          console.error('[MODE1:TEST] state._mode1 not initialized. Has handleBeginStory run?');
          return;
      }
      var changes = [];
      var st = window.state.storyturn || 'ST1';
      if (st === 'ST3' || st === 'ST4' || st === 'ST5' || st === 'ST6') {
          window.state.storyturn = 'ST2';
          changes.push('storyturn ' + st + ' → ST2');
      }
      var len = String(window.state.storyLength || '').toLowerCase();
      if (len !== 'fling' && len !== 'affair') {
          window.state.storyLength = 'fling';
          changes.push('storyLength "' + len + '" → "fling"');
      }
      var arch = (window.state.archetype && window.state.archetype.primary) || '';
      if (!/(spellbinder|dark\s*vice|beautiful\s*ruin|armored\s*fox)/i.test(arch)) {
          if (!window.state.archetype) window.state.archetype = {};
          window.state.archetype.primary = 'spellbinder';
          changes.push('archetype "' + arch + '" → "spellbinder"');
      }
      if (_storyboundPlatform !== 'ios_app_store' && window.state.contentMode !== 'full') {
          changes.push('contentMode "' + window.state.contentMode + '" → "full"');
          window.state.contentMode = 'full';
      }
      var liGender = String(window.state.loveInterest || 'Male').toLowerCase();
      if (liGender === 'female') {
          window.state.loveInterest = 'Male';
          changes.push('loveInterest "Female" → "Male" (whisper variant is male-coded)');
      }
      var liKey = _mode1TestLiKey();
      if (window.state._mode1.firedFor[liKey]) {
          delete window.state._mode1.firedFor[liKey];
          changes.push('cleared firedFor[' + liKey + ']');
      }
      if (window.state._mode1.rejectedFor[liKey]) {
          delete window.state._mode1.rejectedFor[liKey];
          changes.push('cleared rejectedFor[' + liKey + ']');
      }
      window.state._mode1.forceFireNext = true;
      changes.push('forceFireNext = true (bypass 35% roll)');
      console.log('[MODE1:TEST] WHISPER force-armed for next scene:');
      changes.forEach(function(c) { console.log('  • ' + c); });
      console.log('  → Submit your next say/do action. Whisper directive will inject.');
  };

  // Force the female-variant gatekeeper directive to fire on the NEXT
  // scene. Same archetype/length/storyturn forcing as the whisper, but
  // flips loveInterest to 'Female' and ensures eagerness signal is set.
  window._mode1ForceFemaleVariantNext = function() {
      if (!window.state || !window.state._mode1) {
          console.error('[MODE1:TEST] No state. Start a story first.');
          return;
      }
      var changes = [];
      var st = window.state.storyturn || 'ST1';
      if (st !== 'ST1' && st !== 'ST2') {
          window.state.storyturn = 'ST2';
          changes.push('storyturn ' + st + ' → ST2');
      }
      var len = String(window.state.storyLength || '').toLowerCase();
      if (len !== 'fling' && len !== 'affair') {
          window.state.storyLength = 'fling';
          changes.push('storyLength "' + len + '" → "fling"');
      }
      var arch = (window.state.archetype && window.state.archetype.primary) || '';
      if (!/(spellbinder|dark\s*vice|beautiful\s*ruin|armored\s*fox)/i.test(arch)) {
          if (!window.state.archetype) window.state.archetype = {};
          window.state.archetype.primary = 'spellbinder';
          changes.push('archetype "' + arch + '" → "spellbinder"');
      }
      var liGender = String(window.state.loveInterest || 'Male').toLowerCase();
      if (liGender !== 'female') {
          window.state.loveInterest = 'Female';
          changes.push('loveInterest "' + liGender + '" → "Female"');
      }
      // Eagerness signal — set contentMode 'full' to satisfy the directive's gate
      // (iOS hard-locked safe: never flip the register, even for a dev force-arm)
      if (_storyboundPlatform !== 'ios_app_store' && window.state.contentMode !== 'full') {
          window.state.contentMode = 'full';
          changes.push('contentMode → "full" (eagerness signal)');
      }
      console.log('[MODE1:TEST] FEMALE VARIANT force-armed for next scene:');
      changes.forEach(function(c) { console.log('  • ' + c); });
      console.log('  → Submit a say/do that reads as eager. Female-variant directive will inject.');
  };

  // Simulate the whisper having landed — sets aftermathActive so the
  // aftermath directive fires on the NEXT scene with the assertive-LI
  // posture. Pass 'defer' to pre-roll the reciprocation deferral path;
  // 'consummate' (default) for the standard reciprocation path.
  window._mode1JumpToAftermath = function(decision) {
      if (!window.state || !window.state._mode1) {
          console.error('[MODE1:TEST] No state. Start a story first.');
          return;
      }
      var liKey = _mode1TestLiKey();
      var turn = window.state.turnCount || 0;
      var rd = (decision === 'defer') ? 'defer' : 'consummate';
      window.state._mode1.firedFor[liKey] = turn;
      window.state._mode1.aftermathActive = { liKey: liKey, sceneStarted: turn, reciprocationDecision: rd };
      console.log('[MODE1:TEST] Aftermath force-active for "' + liKey + '" (reciprocationDecision: ' + rd + ').');
      console.log('  → Next scene will run aftermath directive. Up to 3 scenes of debate before forced rendezvous.');
  };

  // Simulate a rendezvous offer — sets rendezvous-pending so the
  // rendezvous directive fires on subsequent scenes watching for
  // player attendance at the offered place.
  window._mode1JumpToRendezvous = function() {
      if (!window.state || !window.state._mode1) {
          console.error('[MODE1:TEST] No state. Start a story first.');
          return;
      }
      var liKey = _mode1TestLiKey();
      var turn = window.state.turnCount || 0;
      window.state._mode1.aftermathActive = null;
      window.state._mode1.rendezvous = { liKey: liKey, sceneOffered: turn, attended: false };
      console.log('[MODE1:TEST] Rendezvous-pending for "' + liKey + '". Next scene watches for attendance.');
      console.log('  → Submit a say/do that describes going to a place; LLM should detect arrival and fire <<MODE1_RENDEZVOUS_ATTENDED>>.');
  };

  // Clear all Mode 1 state — useful between tests.
  window._mode1Reset = function() {
      if (!window.state) return;
      window.state._mode1 = {
          firedFor: {},
          aftermathActive: null,
          rejectedFor: {},
          returnChanceFor: {},
          routeToGrok: false,
          rendezvous: null,
          rendezvousFulfilled: {}
      };
      console.log('[MODE1:TEST] state._mode1 fully reset.');
  };

  // Inspect current Mode 1 gate status — prints which gates pass / fail
  // and which test commands are available.
  window._mode1Diagnose = function() {
      if (!window.state) { console.log('No state.'); return; }
      var s = window.state;
      var liKey = _mode1TestLiKey();
      var liGender = String(s.loveInterest || 'Male');
      var arch = (s.archetype && s.archetype.primary) || '(none)';
      var len = String(s.storyLength || '');
      var st = s.storyturn || 'ST1';
      var dom = /(spellbinder|dark\s*vice|beautiful\s*ruin|armored\s*fox)/i.test(arch);
      var lenOk = /^(fling|affair)$/i.test(len);
      var stOk = /^ST[12]$/.test(st);
      var aft = s._mode1 && s._mode1.aftermathActive;
      var rdv = s._mode1 && s._mode1.rendezvous;
      console.log('═══ [MODE1:DIAGNOSE] ═══');
      console.log('  LI key:           ', liKey);
      console.log('  LI gender:        ', liGender, liGender.toLowerCase() === 'female' ? '→ female-variant path' : '→ whisper variant path');
      console.log('  Archetype:        ', arch, dom ? '✓ dominant cohort' : '✗ NOT dominant cohort');
      console.log('  Story length:     ', len, lenOk ? '✓ Fling/Affair' : '✗ not Fling/Affair');
      console.log('  Storyturn:        ', st, stOk ? '✓ pre-ST3' : '✗ ST3+ — whisper blocked (aftermath/rdv may still fire)');
      console.log('  contentMode:      ', s.contentMode, s.contentMode === 'full' ? '✓ receptive' : '○ not full');
      console.log('  intensityStance:  ', s._intensityStance || '(none)', s._intensityStance === 'surrender' ? '✓ receptive' : '');
      console.log('  Whisper fired?    ', !!(s._mode1 && s._mode1.firedFor[liKey]));
      console.log('  LI rejected?      ', !!(s._mode1 && s._mode1.rejectedFor[liKey]));
      console.log('  Aftermath active: ', !!aft, aft ? '(reciprocationDecision: ' + (aft.reciprocationDecision || '?') + ')' : '');
      console.log('  Rendezvous open:  ', !!rdv, rdv ? '(offered scene ' + rdv.sceneOffered + ')' : '');
      console.log('  routeToGrok:      ', !!(s._mode1 && s._mode1.routeToGrok));
      console.log('  forceFireNext:    ', !!(s._mode1 && s._mode1.forceFireNext));
      console.log('');
      console.log('  TEST COMMANDS:');
      console.log('    _mode1ForceWhisperNext()        — force male-whisper directive on next scene');
      console.log('    _mode1ForceFemaleVariantNext()  — force female-variant directive on next scene');
      console.log('    _mode1JumpToAftermath("consummate"|"defer")  — simulate whisper landed; aftermath active');
      console.log('    _mode1JumpToRendezvous()        — simulate deferral; rendezvous-pending active');
      console.log('    _mode1Reset()                   — clear all Mode 1 state');
      console.log('    _mode1Diagnose()                — this readout');
  };

  /**
   * Apply safe directive override to persistent cache.
   * FULL REPLACEMENT — discards original directives entirely, returns only safe block.
   * No keyword filtering, no regex. Simpler = safer.
   * @param {string} _directives - ignored (original cache discarded in safe mode)
   * @returns {string} safe-only directive block
   */
  function stripExplicitDirectives(_directives) {
      if (window.state?.contentMode !== 'safe') return _directives;
      console.warn('[SAFE:DIRECTIVES] Full override — original directive cache replaced with safe block');
      return buildSafeModeDirective();
  }
  window.stripExplicitDirectives = stripExplicitDirectives;

  /**
   * Set content mode from user toggle (web only).
   * @param {'safe'|'full'} mode
   */
  function setContentMode(mode) {
      if (_storyboundPlatform === 'ios_app_store') return; // iOS: no override
      if (mode !== 'safe' && mode !== 'full') return;
      window.state.userContentPreference = mode;
      window.state.contentMode = mode;
      localStorage.setItem('sb_content_mode', mode);
      if (mode === 'safe') {
          applySafeModeConstraints();
          showToast('Cinegraphic Mode active — intimate scenes rendered metaphorically.');
      } else {
          showToast('Immersive Mode active.');
      }
  }
  window.setContentMode = setContentMode;

  /**
   * Check if platform is iOS App Store.
   */
  function isIOSAppStore() {
      return _storyboundPlatform === 'ios_app_store';
  }
  window.isIOSAppStore = isIOSAppStore;

  /**
   * Request Full Mode — shows binding confirmation for 18+ content (web only).
   * Called from Vault appearance toggle.
   */
  window._requestFullMode = function() {
      if (isIOSAppStore()) return;
      // If already confirmed, just switch
      if (window.state?.userContentPreference === 'full' || window.state?.explicitEmbodimentAuthorized) {
          setContentMode('full');
          return;
      }
      // Show confirmation overlay
      const existing = document.querySelector('.gn-style-overlay.content-mode-confirm');
      if (existing) existing.remove();
      const overlay = document.createElement('div');
      overlay.className = 'gn-style-overlay content-mode-confirm';
      overlay.innerHTML = `<div class="gn-style-panel">
        <h3 class="gn-style-title">Immersive Mode</h3>
        <p style="color:rgba(255,255,255,0.6); font-size:0.85em; line-height:1.5; margin:8px 0 16px;">Some stories are told without restraint.<br><span style="font-size:0.9em; color:rgba(255,255,255,0.4);">Confirm you\u2019re 18+ to experience them fully.</span></p>
        <div class="gn-style-options">
          <button class="gn-style-card" id="confirmFullMode"><span class="gn-style-name">I\u2019m 18+ \u2014 Enable Immersive Mode</span></button>
          <button class="gn-style-card" id="declineFullMode"><span class="gn-style-name">Stay in Cinegraphic Mode</span></button>
        </div>
      </div>`;
      document.body.appendChild(overlay);
      overlay.querySelector('#confirmFullMode').addEventListener('click', async () => {
          setContentMode('full');
          // Persist to profile
          try {
              const { data: { user } } = await sb.auth.getUser();
              if (user?.id) {
                  await sb.from('profiles').update({ age_confirmed: true }).eq('id', user.id);
              }
          } catch (_) {}
          overlay.remove();
      });
      overlay.querySelector('#declineFullMode').addEventListener('click', () => {
          setContentMode('safe');
          overlay.remove();
      });
      overlay.addEventListener('click', (e) => { if (e.target === overlay) overlay.remove(); });
  };

  // Initialize content mode on load
  if (window.state) {
      window.state.contentMode = resolveContentMode();
      if (window.state.contentMode === 'safe') {
          applySafeModeConstraints();
          console.warn('[SAFE MODE ACTIVE] Platform:', _storyboundPlatform, '| All explicit content blocked at source.');
      } else {
          console.log('[CONTENT MODE] Full — platform:', _storyboundPlatform);
      }
  }

  // iOS: hide content mode toggle + age gate elements
  if (isIOSAppStore()) {
      document.addEventListener('DOMContentLoaded', () => {
          const cmSection = document.getElementById('contentModeSection');
          if (cmSection) cmSection.style.display = 'none';
          const ageGate = document.getElementById('ageGate');
          if (ageGate) ageGate.style.display = 'none';
      });
  }

  // ── GEO-GATE (client soft-gate) ──────────────────────────────────────────────
  // UX layer only: ask /api/geo (Vercel edge IP country) once on boot and, if the
  // region is enforce-blocked, show a polite unavailable screen instead of the app.
  // The REAL enforcement is server-side on the payment path — this can be defeated
  // by a VPN and that's fine. FAIL-OPEN: any error → allow (never brick the app).
  // Kill switch: window.__geoGate = false. NOT a language gate.
  function _showGeoBlockScreen() {
    try {
      if (document.getElementById('sbGeoBlock')) return;
      var el = document.createElement('div');
      el.id = 'sbGeoBlock'; el.setAttribute('data-no-i18n', '');
      el.style.cssText = 'position:fixed;inset:0;z-index:2147483600;background:#0a0a0a;display:flex;align-items:center;justify-content:center;text-align:center;padding:32px;';
      el.innerHTML = '<div style="max-width:440px;color:#e8d9b0;font-family:\'Cinzel\',\'Lora\',serif;">'
        + '<div style="font-size:1.35em;letter-spacing:0.06em;margin-bottom:14px;">Storybound is not available in your region.</div>'
        + '<div style="font-size:0.9em;opacity:0.7;line-height:1.6;">Availability depends on local laws and payment-region rules.</div>'
        + '</div>';
      (document.body || document.documentElement).appendChild(el);
      if (document.body) document.body.style.overflow = 'hidden';
    } catch (_) {}
  }
  async function _geoSoftGate() {
    try {
      if (window.__geoGate === false) return;                                  // kill switch
      if (sessionStorage.getItem('sb_geo_decision') === 'allow') return;       // cached this session
      var geo = null;
      try {
        var ctrl = new AbortController();
        var to = setTimeout(function () { ctrl.abort(); }, 4000);
        var r = await fetch('/api/geo', { signal: ctrl.signal });
        clearTimeout(to);
        if (r && r.ok) geo = await r.json();
      } catch (_) {}
      if (!geo) {                                                              // fetch failed → fail-open
        try { if (typeof sbLogBeta === 'function') sbLogBeta('geo_gate_unknown_country', { signal: 'unknown', decision: 'unknown_allow', reason: 'geo_fetch_failed' }); } catch (_) {}
        return;
      }
      try { sessionStorage.setItem('sb_geo_decision', geo.blocked ? 'block' : 'allow'); } catch (_) {}
      try { if (typeof sbLogBeta === 'function') sbLogBeta('geo_gate_decision', { country: geo.country || null, signal: 'ip', decision: geo.decision, mode: geo.mode, blocked: !!geo.blocked }); } catch (_) {}
      if (geo.decision === 'log_only') { try { if (typeof sbLogBeta === 'function') sbLogBeta('geo_gate_log_only', { country: geo.country || null, decision: 'log_only' }); } catch (_) {} }
      if (geo.blocked) _showGeoBlockScreen();
    } catch (_) {}
  }
