    if (_sfgProx(t, _SFG_NAME, _SFG_ROLE, 48)) return true;   // the NAME cast as the Prophet
    if (_SFG_ACT.test(t)) return true;                        // Tier 1 — unmistakable acts
    if (_SFG_MOON.test(t) && _SFG_ISLAMCTX.test(t)) return true; // Tier 1b — moon-split, in-context only
