      // billingGraceUntil (period_end). Treated as 'active' for all
      // entitlement checks; the 'canceling' label is purely an Account-tab
      // surface so the user knows their sub is winding down.
      state.billingStatus = 'canceling';
      state.billingGraceUntil = _dbGraceUntil;
      state.billingLastError = '';
