    if (typeof profile.bonus_tempt_charges === 'number') {
      state.bonus_tempt_charges = profile.bonus_tempt_charges;
    }
    // ── OPTIMISTIC FORTUNE RECONCILIATION (rewired 2026-05-21) ─────
