    // though romance_preferences was sanitized when first stored, re-scrub on
    // load so a tampered-with row can't reach an LLM prompt.
    state.romancePreferences = Array.isArray(profile.romance_preferences)
      ? profile.romance_preferences
          .map(function (s) { return typeof s === 'string' ? (sanitizeShortInput(s, 200, { silent: true }) || '') : ''; })
          .filter(Boolean)
      : [];
    state.romanceVector = computeRomanceVector(state.romancePreferences);
    // SECURITY: same trust-boundary scrub as romance_preferences above.
    state.avoidances = Array.isArray(profile.avoidances)
      ? profile.avoidances
          .map(function (s) { return typeof s === 'string' ? (sanitizeShortInput(s, 200, { silent: true }) || '') : ''; })
          .filter(Boolean)
      : [];
