  // ════════════════════════════════════════════════════════════════
  function _obsLines(input) { if (Array.isArray(input)) return input; return _TELEMETRY_RING.map(function (e) { return (e && e.line) || ''; }); }
  function _obsAvg(a) { return a.length ? Math.round(a.reduce(function (s, x) { return s + x; }, 0) / a.length) : 0; }
  function _obsPct(n, d) { return d ? Math.round(100 * n / d) : 0; }
