      Object.keys(r.byLanding).sort(function (a, b) { return r.byLanding[b] - r.byLanding[a]; }).forEach(function (k) { console.log(_obsBarRow(k, r.byLanding[k], r.total)); });
      console.log('    source→landing: ' + Object.keys(r.sourceToLanding).map(function (k) { return k + ' ×' + r.sourceToLanding[k]; }).join(', '));
