  // ═══════════════════════════════════════════════════════════════════════════
  // WORLD REGISTRY — 3-tier normalized facade { anchor, directive, validation }
  // Reads from existing scattered objects. Does NOT replace them.
  // anchor   = defines reality, system physics, core concepts (state-independent)
  // directive = controls scene flow, pacing, character behavior (may be state-dependent)
  // validation = forbids things, enforces constraints, prevents drift
  // ═══════════════════════════════════════════════════════════════════════════

  function getWorldRegistryEntry(world, flavor, st) {
    var anchor = [];
    var directive = [];
    var validation = [];

    // ── ANCHOR: static world truths ──
    if (SYSTEMIC_PRESSURE_LINES[flavor]) anchor.push('World Pressure: ' + SYSTEMIC_PRESSURE_LINES[flavor]);
    if (CONTEXT_GRAVITY && CONTEXT_GRAVITY[flavor]) anchor.push('Context Effect: ' + CONTEXT_GRAVITY[flavor]);

    // Glass House: two-tier via system registry
    if (_isSystemActive('worldSystems', 'chorus')) {
      var _chTier = state.systems.worldSystems.chorus.tier;
      anchor.push(_chTier === 1 ? (WORLD_BIBLE.glass_house + buildGlassHouseSurfaceDirective()) : GLASS_HOUSE_ANCHOR);
    }

    // Angry Room: lightweight registry supplement (full behavior in directive layer)
    if (flavor === 'angry_room') {
      anchor.push('You are assigned the role of punishment within a procedural system.');
      anchor.push('Subjects are guilty. The system expects control.');
      directive.push('Early: control \u2192 punishment \u2192 variation. Later: disruption through one subject who does not break.');
      validation.push('LI must not break. System cannot be escaped early. Do not moralize player actions.');
    }

    // ── DIRECTIVE: scene-shaping rules (may be stateful) ──
    if (FLAVOR_HARD_CONSTRAINTS[flavor]) directive.push(FLAVOR_HARD_CONSTRAINTS[flavor]);
    if (DYSTOPIA_FLAVOR_EFFECTS && DYSTOPIA_FLAVOR_EFFECTS[flavor]) directive.push(DYSTOPIA_FLAVOR_EFFECTS[flavor]);

    // ── VALIDATION: drift prevention + forbidden terms ──
    var bellwether = BELLWETHERS.world && BELLWETHERS.world[flavor];
    if (bellwether) validation.push('BELLWETHER \u2014 STRUCTURAL REFERENCE:\n' + bellwether + '\nDo not copy wording. Absorb structural logic only.');

    return { anchor: anchor, directive: directive, validation: validation };
  }

  function composeWorld(world, resolvedFlavors, st) {
    var result = { anchor: [], directive: [], validation: [] };

    for (var i = 0; i < resolvedFlavors.length; i++) {
      var entry = getWorldRegistryEntry(world, resolvedFlavors[i].val, st);
      result.anchor = result.anchor.concat(entry.anchor);
      result.directive = result.directive.concat(entry.directive);
      result.validation = result.validation.concat(entry.validation);
    }

    return result;
  }

  function formatComposedWorld(composed) {
    var parts = [];
    if (composed.anchor.length) parts.push('ANCHOR:\n' + composed.anchor.join('\n'));
    if (composed.directive.length) parts.push('DIRECTIVE:\n' + composed.directive.join('\n'));
    if (composed.validation.length) parts.push('VALIDATION:\n' + composed.validation.join('\n'));
    return parts.join('\n\n');
  }

  // Expose for testing / incremental migration
  window._getWorldRegistryEntry = getWorldRegistryEntry;
  window._composeWorld = composeWorld;

  // ═══════════════════════════════════════════════════════════════════════════
  // TELEMETRY — lightweight behavioral event tracking (opt-in, no content)
  // Default OFF. Tracks actions, state transitions, and drop-off signals.
  // No prompts, no scenes, no user text. In-memory buffer only.
  // ═══════════════════════════════════════════════════════════════════════════

  function _getCurrentPhase() {
    return state.catharsisComplete ? 'LI' : (state.worldSubtype === 'angry_room' ? 'catharsis' : 'story');
  }

  function _logTelemetry(event) {
    if (!state.telemetryEnabled) return;
    if (!state.telemetryBuffer) state.telemetryBuffer = [];
    // Lazy session ID init
    if (!state.sessionId) state.sessionId = Math.random().toString(36).slice(2);
    // Auto-inject session + phase on every event
    state.telemetryBuffer.push(Object.assign({
      ts: Date.now(),
      sessionId: state.sessionId,
      phase: _getCurrentPhase()
    }, event));
    // Soft cap: prevent unbounded growth
    if (state.telemetryBuffer.length > 100) state.telemetryBuffer.shift();
  }

  function _flushTelemetry() {
    if (!state.telemetryEnabled || !state.telemetryBuffer) return;
    console.log('[TELEMETRY]', state.telemetryBuffer.length, 'events:', state.telemetryBuffer);
  }

  function _checkDropoff() {
    if (!state.telemetryEnabled) return;
    var idle = Date.now() - (state.lastActionAt || Date.now());
    if (idle > 60000) {
      _logTelemetry({ type: 'potential_dropoff', sceneIndex: state.turnCount || 0 });
    }
  }

  // Periodic drop-off check (every 60s, only when telemetry enabled)
  setInterval(_checkDropoff, 60000);

  // Expose for console access + cross-IIFE calls (concierge IIFE needs _logTelemetry)
  window._logTelemetry = _logTelemetry;
  window._flushTelemetry = _flushTelemetry;
  window._enableTelemetry = function() { state.telemetryEnabled = true; state.lastActionAt = Date.now(); console.log('[TELEMETRY] Enabled'); };
  window._disableTelemetry = function() { state.telemetryEnabled = false; console.log('[TELEMETRY] Disabled'); };

  // ═══════════════════════════════════════════════════════════════════════════
  // TUNING TELEMETRY — fire-rate counters + per-event records for tuning work
  // (added 2026-05-17, after 3 batches of CG directive parity + intimacy gate).
  // Distinct from _logTelemetry: counters survive past the 100-event buffer
  // cap, so multi-scene rates remain accurate. Records still flow through
  // _logTelemetry for the timeline view; counters give the aggregate view.
  // Always-on (cheap, integer increments) — no enable flag needed.
  // ═══════════════════════════════════════════════════════════════════════════
  function _tuneRecord(eventType, meta) {
    if (!state.tuningCounters) state.tuningCounters = {};
    var c = state.tuningCounters[eventType];
    if (!c) c = state.tuningCounters[eventType] = { count: 0, fired: 0, eligible: 0, firstSceneIdx: null, lastSceneIdx: null, lastTs: null };
    c.count += 1;
    c.lastTs = Date.now();
    var sceneIdx = (meta && typeof meta.sceneIndex === 'number') ? meta.sceneIndex : (state.turnCount || 0);
    if (c.firstSceneIdx === null) c.firstSceneIdx = sceneIdx;
    c.lastSceneIdx = sceneIdx;
    if (meta && meta.fired === true) c.fired += 1;
    if (meta && meta.eligible === true) c.eligible += 1;
    // Also push to the event timeline (capped buffer) so console can replay
    // chronologically. Telemetry-enable flag does NOT gate counters — only
    // the event log. Counters are always-on so dev never loses the rate.
    try { _logTelemetry(Object.assign({ type: 'tune:' + eventType }, meta || {})); } catch (_) {}
  }

  // Convenience wrapper for the common "did builder X fire this scene?"
  // pattern. Records both eligibility (preconditions met) and firing
  // (returned non-empty). For each builder, instrumentation passes:
  //   - eligible: did the gates that block the builder all pass?
  //   - fired: did the builder return a non-empty string?
  // Adoption-when-eligible rate = fired / eligible. Fire rate per scene = fired / total scenes.
  function _tuneBuilderFire(eventType, fired, meta) {
    var sceneIdx = (state.turnCount || 0);
    _tuneRecord(eventType, Object.assign({
      sceneIndex: sceneIdx,
      fired: !!fired,
      eligible: true  // by definition, if we're recording here, gates passed enough to call
    }, meta || {}));
  }

  window._tuneRecord = _tuneRecord;
  window._tuneBuilderFire = _tuneBuilderFire;

  // ── PUBLIC: print a rates summary to console. ──
  // Walks state.tuningCounters and prints fire rate, adoption-when-eligible,
  // scene range. Plus a separate Last Events tail (from telemetryBuffer).
  window._tuningReport = function() {
    var counters = state.tuningCounters || {};
    var keys = Object.keys(counters).sort();
    if (keys.length === 0) {
      console.log('[TUNING] No counters yet. Play through some scenes first.');
      return;
    }
    var totalScenes = (state.turnCount || 0) + 1;
    console.log('[TUNING] === Counters (total scenes so far: ' + totalScenes + ') ===');
    var rows = keys.map(function(k) {
      var c = counters[k];
      var firePct = totalScenes > 0 ? ((c.fired / totalScenes) * 100).toFixed(1) + '%' : 'n/a';
      var adoptPct = c.eligible > 0 ? ((c.fired / c.eligible) * 100).toFixed(1) + '%' : 'n/a';
      return {
        event: k,
        total_recorded: c.count,
        fired: c.fired,
        eligible: c.eligible,
        fire_rate_per_scene: firePct,
        adoption_when_eligible: adoptPct,
        scene_range: (c.firstSceneIdx === null ? '—' : (c.firstSceneIdx + '..' + c.lastSceneIdx))
      };
    });
    try { console.table(rows); } catch (_) { console.log(rows); }
    // Tail of timeline for chronological view.
    var buf = state.telemetryBuffer || [];
    var tuneEvents = buf.filter(function(e) { return e.type && e.type.indexOf('tune:') === 0; });
    if (tuneEvents.length > 0) {
      console.log('[TUNING] Last ' + Math.min(10, tuneEvents.length) + ' tuning events:');
      try { console.table(tuneEvents.slice(-10)); } catch (_) { console.log(tuneEvents.slice(-10)); }
    }
  };

  window._tuningReset = function() {
    state.tuningCounters = {};
    console.log('[TUNING] Counters reset.');
  };

