  // ─────────────────────────────────────────────────────────────────────
  // PRONOUN RESOLUTION — robust match for LI / MC gender strings.
  //
  // Prior code used STRICT equality ('Female' / 'Male') with They/Them as
  // silent fallback. That dropped explicit user selections to non-binary
  // pronouns whenever the value had been lightly munged (lowercase,
  // trailing whitespace, or a custom-dropdown raw string like "woman").
  // Resolve by keyword match on the actual string, so "female" / "Female" /
  // "  Female " / "woman" / "she" / "her" all map to She/Her; same for male.
  //
  // Non-binary ONLY fires when the user explicitly typed an NB term (or
  // picked Non-Binary from the gender dropdown). Truly unresolvable values
  // default to the 80-90% majority case per product spec:
  //   • LI default  = He/Him  (majority use: female protagonist + male LI)
  //   • MC default  = She/Her (majority use: female protagonist)
  // Users can override via Petition Fate (free) if the default doesn't match.
  // ─────────────────────────────────────────────────────────────────────
  function _detectExplicitPronouns(s) {
      // Shared keyword matcher. Returns 'She/Her', 'He/Him', 'They/Them',
      // or null when the string gives no explicit signal. Non-binary match
      // runs first so "fem" inside "feminine" etc. doesn't false-positive.
      if (!s) return null;
      if (/\b(non[-\s]?binary|enby|nb|genderqueer|genderfluid|they|them|their)\b/.test(s)) return 'They/Them';
      if (/\b(female|woman|she|her|fem|girl|lady)\b/.test(s))  return 'She/Her';
      if (/\b(male|man|he|him|masc|boy|guy)\b/.test(s))        return 'He/Him';
      return null;
  }
  function resolveLIPronounsFromGender(genderStr) {
      var s = String(genderStr || '').trim().toLowerCase();
      var explicit = _detectExplicitPronouns(s);
      // Unresolvable → He/Him (majority-case default: female protagonist +
      // male LI). Explicit non-binary still honored via _detectExplicitPronouns.
      return explicit || 'He/Him';
  }
  function resolveMCPronounsFromGender(genderStr) {
      var s = String(genderStr || '').trim().toLowerCase();
      var explicit = _detectExplicitPronouns(s);
      // Unresolvable → She/Her (majority-case default: female protagonist).
      return explicit || 'She/Her';
  }
  window.resolveLIPronounsFromGender = resolveLIPronounsFromGender;
  window.resolveMCPronounsFromGender = resolveMCPronounsFromGender;

  const MC_PRONOUN_MAPS = {
      'Male': { MC_SUBJ: 'he', MC_OBJ: 'him', MC_POS: 'his', MC_REFL: 'himself' },
      'Female': { MC_SUBJ: 'she', MC_OBJ: 'her', MC_POS: 'her', MC_REFL: 'herself' },
      'Non-Binary': { MC_SUBJ: 'they', MC_OBJ: 'them', MC_POS: 'their', MC_REFL: 'themself' }
  };

  function resolveLIPronouns(text) {
      if (!text) return text;
      const liGender = state.loveInterest || 'Male';
      const liMap = LI_PRONOUN_MAPS[liGender] || LI_PRONOUN_MAPS['Male'];
      const mcGender = state.gender || 'Female';
      const mcMap = MC_PRONOUN_MAPS[mcGender] || MC_PRONOUN_MAPS['Female'];
      return text
          .replace(/\{LI_SUBJ\}/g, liMap.LI_SUBJ)
          .replace(/\{LI_OBJ\}/g, liMap.LI_OBJ)
          .replace(/\{LI_POS\}/g, liMap.LI_POS)
          .replace(/\{LI_REFL\}/g, liMap.LI_REFL)
          .replace(/\{MC_SUBJ\}/g, mcMap.MC_SUBJ)
          .replace(/\{MC_OBJ\}/g, mcMap.MC_OBJ)
          .replace(/\{MC_POS\}/g, mcMap.MC_POS)
          .replace(/\{MC_REFL\}/g, mcMap.MC_REFL)
          // Capitalize sentence-start pronouns (subject, possessive, object)
          .replace(/(^|[.!?]\s+|[\n])([a-z])/g, (m, prefix, ch) => prefix + ch.toUpperCase());
  }
  // Resolve pronouns for player mask cards: LI_ placeholders use PLAYER gender
  function _resolvePlayerMaskPronouns(text) {
      if (!text) return text;
      const pGender = state.gender || 'Female';
      const pMap = LI_PRONOUN_MAPS[pGender] || LI_PRONOUN_MAPS['Female'];
      const mcGender = state.loveInterest || 'Male';
      const mcMap = MC_PRONOUN_MAPS[mcGender] || MC_PRONOUN_MAPS['Male'];
      return text
          .replace(/\{LI_SUBJ\}/g, pMap.LI_SUBJ)
          .replace(/\{LI_OBJ\}/g, pMap.LI_OBJ)
          .replace(/\{LI_POS\}/g, pMap.LI_POS)
          .replace(/\{LI_REFL\}/g, pMap.LI_REFL)
          .replace(/\{MC_SUBJ\}/g, mcMap.MC_SUBJ)
          .replace(/\{MC_OBJ\}/g, mcMap.MC_OBJ)
          .replace(/\{MC_POS\}/g, mcMap.MC_POS)
          .replace(/\{MC_REFL\}/g, mcMap.MC_REFL)
          .replace(/(^|[.!?]\s+|[\n])([a-z])/g, (m, prefix, ch) => prefix + ch.toUpperCase());
  }

