  // The early resolution block (~line 6651) runs BEFORE window.state is created
  // (the literal above), so its `if (window.state)` guard fails silently and the
  // content register is never resolved from platform — leaving the 'full' default
  // live even on iOS (the bit-rot that emitted unrestricted prompts in App Store
  // builds). Resolve HERE, where state is guaranteed to exist. iOS hard-locks the
  // APPLE_SAFE register; web honors the persisted/default preference.
  try {
      _applyContentRegister();
      if (state.contentMode === 'safe') {
          console.warn('[CONTENT REGISTER] ' + state.contentRegister + ' (safe) — platform:', _storyboundPlatform, '| explicit content blocked at source.');
      } else {
          console.log('[CONTENT REGISTER] ' + state.contentRegister + ' (full) — platform:', _storyboundPlatform);
      }
  } catch (_crErr) { console.warn('[CONTENT REGISTER] boot resolution failed:', _crErr && _crErr.message); }

