  // ═══════════════════════════════════════════════════════════════════
  // CANONICAL TONE NORMALIZATION — Collapse legacy tones to 4 pillars
  // ═══════════════════════════════════════════════════════════════════
  function canonicalizeTone(tone) {
    switch (tone) {
      case 'Comedic':
      case 'Satirical':
        return 'WryConfession';
      case 'Horror':
        return 'Dark';
      case 'Surreal':
        return 'Mythic';
      case 'Poetic':
        return 'Earnest';
      default:
        return tone;
    }
  }
  window.canonicalizeTone = canonicalizeTone;

