  function selectMaterialObserverChain() {
      if (state.povMode !== 'environment4th') return null;
      const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];
      const chain = [
          pick(MATERIAL_OBSERVERS_DISTANT),
          pick(MATERIAL_OBSERVERS_MID),
          pick(MATERIAL_OBSERVERS_NEAR)
      ];
      // 70% chance of a 4th micro observer
      if (Math.random() < 0.7) chain.push(pick(MATERIAL_OBSERVERS_MICRO));
      // 30% chance of a 5th (different micro)
      if (Math.random() < 0.3) {
          let micro2 = pick(MATERIAL_OBSERVERS_MICRO);
          while (micro2 === chain[chain.length - 1]) micro2 = pick(MATERIAL_OBSERVERS_MICRO);
          chain.push(micro2);
      }
      state.currentMaterialObserverChain = chain;
      console.log('[4thPerson] Material observer chain:', chain.join(' → '));
      return chain;
  }
  window.selectMaterialObserverChain = selectMaterialObserverChain;

