      // If 3+ consecutive paragraphs contain human-subject cognition/emotion
      // with no material observer framing, flag as violation
      const humanInteriorPattern = /\b(she|he|they|her|his|their)\s+(felt|thought|knew|realized|wondered|believed|sensed|remembered|hoped|feared|decided|wanted|considered)\b/gi;
      const materialFramePattern = /\b(the\s+)?(wall|floor|stone|glass|wood|air|light|wind|door|chair|table|window|fabric|metal|rain|dust|shadow|ceiling|lamp|candle|brick|concrete|pavement|cobblestone|tile|beam|railing|counter|shelf|mirror|frame|curtain|pillow|blanket|floorboard|stair|fence|gate|roof|chimney|pipe|wire|hinge|lock|handle|surface|edge|corner|threshold|arch)/i;
