      console.log('  Tempt uses:    ' + (s._temptUsageCount || 0));
      console.log('  Wry distortion active: ' + (s._wryDistortion && s._wryDistortion.active ? 'yes (scenes remaining: ' + s._wryDistortion.scenesRemaining + ')' : 'no'));

      // ── Corridor health (filtered to this story) ────────────────
