  function resolveFateAnchorRecovery() {
    if (state.fateAnchorStatus !== 'lost') return;
    state.fateAnchorStatus = 'recovering';
    state.fateAnchorLossResolved = true;
    console.log('[FATE ANCHOR] Recovery initiated');
    setTimeout(function() {
      if (state.fateAnchorStatus === 'recovering') {
        state.fateAnchorStatus = 'present';
        state.fateAnchorRecoveryBoostActive = true;
        state.fateAnchorRecoveryBoostConsumed = false;
        applyFateAnchorGating();
        console.log('[FATE ANCHOR] Restored + recovery boost active');
      }
    }, 0);
  }

  // ═══════════════════════════════════════════════════════════════════
  // TAROT ONBOARDING — Diegetic Fate mechanic reveal for new players
