  // Inject micro-expression UI elements + react token placeholders into formatted HTML
  // P1: Anchor text itself becomes interactive (no diamond marker)
  // P2: tap/click reveals options; auto-reveal after 400ms idle as fallback
  function _injectMicroExprHTML(formattedHTML, injections) {
    if (!injections || !injections.length) return formattedHTML;
    var result = formattedHTML;

    // First pass: replace [REACT_N] tokens with shimmer placeholders
    result = result.replace(/\[REACT_(\d+)\]/g, function(match, num) {
      return '<span class="react-token react-token-pending" data-token="REACT_' + num + '">\u2014</span>';
    });

    // Second pass: wrap anchor text as interactive + inject options (reverse order)
    for (var ii = injections.length - 1; ii >= 0; ii--) {
      var inj = injections[ii];
      var anchorEscaped = inj.anchor.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      var anchorIdx = result.search(new RegExp(anchorEscaped.slice(0, 60)));
      if (anchorIdx === -1) continue;

      var afterAnchor = result.indexOf(inj.anchor, anchorIdx);
      if (afterAnchor === -1) continue;

      var optBtns = inj.options.map(function(opt, oi) {
        return '<button class="micro-expr-opt" data-expr-idx="' + ii + '" data-opt-idx="' + oi + '" onclick="window._selectMicroExpr(' + ii + ',' + oi + ')">' + _povAdaptMicroLine(opt) + '</button>';
      }).join('');

      // Wrap anchor text with interactive span; options panel follows
      var wrappedAnchor = '<span class="microexpr-anchor" data-anchor-id="' + ii + '" onclick="window._toggleMicroExpr(' + ii + ')">' + inj.anchor + '</span>' +
        '<span class="micro-expr-moment" data-expr-idx="' + ii + '">' +
        '<span class="micro-expr-options">' + optBtns + '</span>' +
        '</span>';

      result = result.slice(0, afterAnchor) + wrappedAnchor + result.slice(afterAnchor + inj.anchor.length);

      // Record show time for telemetry
      inj._showTime = Date.now();
    }

    return result;
  }

  // P6: GN mode — lightweight micro-expression as tap overlay on panel
  // GN micro-expression: cinematic subtitle-style, anchored inside panel
  function _injectGNMicroExprHTML(panelsContainer, injections) {
    if (!injections || !injections.length || !panelsContainer) return;
    var inj = injections[0];
    var panels = panelsContainer.querySelectorAll('.gn-panel');
    var targetPanel = panels[2] || panels[1] || panels[0];
    if (!targetPanel) return;

    // Build layer inside panel
    var layer = document.createElement('div');
    layer.className = 'gn-micro-expr-layer';
    layer.dataset.exprIdx = '0';

    // Cinematic gradient (no UI box)
    var gradient = document.createElement('div');
    gradient.className = 'gn-micro-expr-gradient';
    layer.appendChild(gradient);

    // Options container with subtitle-style spans
    var optsContainer = document.createElement('div');
    optsContainer.className = 'gn-micro-expr-options';
    var shortOpts = inj.options.slice(0, 3);
    shortOpts.forEach(function(opt, oi) {
      var span = document.createElement('span');
      span.className = 'gn-micro-expr-opt';
      span.textContent = _povAdaptMicroLine(opt.split(/\s+/).slice(0, 3).join(' '));
      span.addEventListener('click', function(e) {
        e.stopPropagation();
        // Selection feedback
        span.style.color = '#f4d27a';
        span.style.transform = 'scale(0.96)';
        setTimeout(function() { span.style.transform = 'scale(1)'; }, 100);
        // Fade out all options
        optsContainer.style.opacity = '0';
        // Delayed resolution
        var _delay = 120 + Math.floor(Math.random() * 60);
        setTimeout(function() {
          window._selectMicroExpr(0, oi);
          // Remove layer after resolution
          setTimeout(function() { layer.remove(); }, 200);
        }, _delay);
      });
      optsContainer.appendChild(span);
    });
    layer.appendChild(optsContainer);
    targetPanel.appendChild(layer);

    // Timed reveal: 300ms after panel render
    setTimeout(function() {
      layer.classList.add('gn-micro-expr-visible');
    }, 300);

    inj._showTime = Date.now();
  }

  // Toggle handler for tap/click reveal (P2)
  window._toggleMicroExpr = function(exprIdx) {
    var moment = document.querySelector('.micro-expr-moment[data-expr-idx="' + exprIdx + '"]');
    if (!moment || moment.classList.contains('micro-expr-resolved')) return;
    moment.classList.toggle('micro-expr-active');
  };

  // Drop the link affordance from a micro-expression anchor once its moment is
  // resolved (auto OR manual) — a SPENT anchor should read as plain prose, not
  // a clickable gold link that does nothing (the reported "clicking does
  // nothing"). Anchor + moment share the index (data-anchor-id /
  // data-expr-idx, set in _injectMicroExprHTML).
  function _deLinkMicroExprAnchor(exprIdx) {
    try {
      var anchor = document.querySelector('.microexpr-anchor[data-anchor-id="' + exprIdx + '"]');
      if (!anchor) return;
      anchor.onclick = null;
      anchor.removeAttribute('onclick');
      anchor.classList.add('microexpr-anchor-resolved');
      anchor.style.color = 'inherit';
      anchor.style.textDecoration = 'none';
      anchor.style.cursor = 'default';
    } catch (_) {}
  }
  window._deLinkMicroExprAnchor = _deLinkMicroExprAnchor;

  // Auto-select behavior lines: agency-preserving phrasing (never implies system action)
  var _AUTO_SELECT_BEHAVIOR_LINES = [
    'You don\'t answer right away.',
    'You let the moment stretch.',
    'You don\'t move to respond.',
    'You stay exactly where you are.',
    'You let it settle before reacting.',
    'You hold the silence.',
    'You let it pass through you.',
    'You don\'t give them anything yet.'
  ];

  function _getAutoSelectBehaviorLine() {
    var pool = _AUTO_SELECT_BEHAVIOR_LINES;
    var recent = state._recentAutoSelectLines || [];
    var eligible = pool.filter(function(l) { return recent.indexOf(l) === -1; });
    if (!eligible.length) eligible = pool;
    var picked = eligible[Math.floor(Math.random() * eligible.length)];
    state._recentAutoSelectLines = (state._recentAutoSelectLines || []).concat(picked).slice(-2);
    return picked;
  }

  // Auto-reveal + viewport-gated auto-resolve.
  //
  // BUGFIX (2026-05-27): the prior version called this at scene mount and
  // immediately auto-resolved any moment that wasn't currently intersecting
  // the viewport — but the moment is embedded mid-prose, below the fold, so
  // it was ALWAYS off-screen at mount. The IntersectionObserver fired its
  // first callback with isIntersecting=false and resolved the decision before
  // the reader could ever scroll to it (compounded by an 800ms blanket
  // timer). Net effect: the inline micro-decision silently vanished in
  // essentially every scene.
  //
  // New contract: a moment is REVEALED when it scrolls into view, and only
  // auto-resolves once it has been SEEN and then scrolled past unchosen
  // (reader moved on). A moment that is never reached, or that the reader is
  // currently sitting on, stays interactive indefinitely. No time-based
  // blanket resolve.
  function _scheduleAutoReveal() {
    if (typeof IntersectionObserver === 'undefined') {
      // No observer support — just reveal and leave interactive (no auto-resolve).
      document.querySelectorAll('.micro-expr-moment:not(.micro-expr-active):not(.micro-expr-resolved)')
        .forEach(function(m) { m.classList.add('micro-expr-active'); });
      return;
    }

    var _seen = new WeakSet();
    var _visObs = new IntersectionObserver(function(entries) {
      entries.forEach(function(entry) {
        var m = entry.target;
        if (m.classList.contains('micro-expr-resolved')) { _visObs.unobserve(m); return; }
        if (entry.isIntersecting) {
          // Reached by the reader — reveal options + remember we showed it.
          _seen.add(m);
          m.classList.add('micro-expr-active');
        } else if (_seen.has(m)) {
          // Was on screen, now scrolled past without a choice → resolve with
          // the low-disruption default and stop observing.
          var exprIdx = parseInt(m.dataset.exprIdx, 10);
          if (!isNaN(exprIdx)) _autoResolveExpression(exprIdx);
          _visObs.unobserve(m);
        }
        // (not intersecting AND not yet seen → still below the fold; wait.)
      });
    }, { threshold: 0.25 });

    document.querySelectorAll('.micro-expr-moment:not(.micro-expr-resolved)')
      .forEach(function(m) { _visObs.observe(m); });
  }

  // Auto-resolve: select lowest-disruption option + inject agency-preserving line
  // Pattern-aware auto-select lines: keyed by dominant expression axis
  var _AUTO_SELECT_PATTERN_LINES = {
    avoidance:    ['You fall back into that same quiet distance.', 'You do what you always do \u2014 pull back slightly.', 'You let the space open up again.'],
    dominance:    ['You hold your ground, like you always do.', 'You don\'t soften now \u2014 you never really do.', 'You stay exactly where you are, unmoved.'],
    warmth:       ['You soften, almost without thinking.', 'You meet the moment the way you always do.', 'You don\'t pull away \u2014 you never quite do.'],
    approach:     ['You close the distance without deciding to.', 'You lean in \u2014 same as always.', 'Something draws you forward again.'],
    yielding:     ['You give ground, the way you tend to.', 'You let it happen, the way you do.', 'You don\'t resist \u2014 not this time either.'],
    playfulness:  ['You deflect \u2014 lightly, like you do.', 'You let the moment slide past you.', 'That familiar ease settles in.'],
    seriousness:  ['You stay with it \u2014 you always stay with it.', 'You don\'t look away from the weight.', 'You hold the gravity, same as before.']
  };

  function _autoResolveExpression(exprIdx) {
    var injections = state._currentMicroExprInjections || [];
    var inj = injections[exprIdx];
    if (!inj) return;
    var widget = document.querySelector('.micro-expr-moment[data-expr-idx="' + exprIdx + '"]');
    if (!widget || widget.classList.contains('micro-expr-resolved')) return;

    // Find lowest-disruption option
    var defaultIdx = 0;
    if (inj.bankKeys) {
      for (var di = 0; di < inj.bankKeys.length; di++) {
        if (/yielding|withdraw/.test(inj.bankKeys[di])) { defaultIdx = di; break; }
      }
    }

    // P1: Pattern-aware auto-select — use dominant axis phrasing if profile exists
    var behaviorLine;
    var profile = state.playerExpressionProfile || {};
    var axes = ['approach', 'avoidance', 'warmth', 'dominance', 'yielding', 'playfulness', 'seriousness'];
    var dominant = ''; var maxVal = 0;
    for (var ai = 0; ai < axes.length; ai++) {
      var val = Math.abs(profile[axes[ai]] || 0);
      if (val > maxVal) { maxVal = val; dominant = axes[ai]; }
    }
    if (maxVal >= 0.2 && _AUTO_SELECT_PATTERN_LINES[dominant]) {
      var pool = _AUTO_SELECT_PATTERN_LINES[dominant];
      var recent = state._recentAutoSelectLines || [];
      var eligible = pool.filter(function(l) { return recent.indexOf(l) === -1; });
      if (!eligible.length) eligible = pool;
      behaviorLine = eligible[Math.floor(Math.random() * eligible.length)];
    } else {
      behaviorLine = _getAutoSelectBehaviorLine();
    }
    state._recentAutoSelectLines = (state._recentAutoSelectLines || []).concat(behaviorLine).slice(-2);

    // STOP THE LEAK (2026-05-26): auto-resolve no longer renders the behavior
    // line into the prose — it read as confusing gold-italic system residue
    // ("You stay exactly where you are. That bounces off harder than
    // expected."). Render nothing; the expression-profile vector below still
    // fires (the real signal). behaviorLine is kept for the telemetry/log only.
    // De-link the anchor so the spent moment stops looking clickable.
    widget.innerHTML = '';
    widget.classList.add('micro-expr-resolved');
    _deLinkMicroExprAnchor(exprIdx);

    // Still apply vector + response consequence (half weight for auto)
    var vector = inj.expressionVectors[defaultIdx] || {};
    var bankKey = (inj.bankKeys && inj.bankKeys[defaultIdx]) || '';
    state.playerExpressionProfile = state.playerExpressionProfile || {};
    for (var vk in vector) {
      if (vector.hasOwnProperty(vk)) {
        state.playerExpressionProfile[vk] = (state.playerExpressionProfile[vk] || 0) + vector[vk] * 0.5;
      }
    }
    // (Auto-resolve outcome line suppressed — STOP THE LEAK. It used to inject
    // a .micro-expr-response outcome ("That bounces off harder than expected.")
    // inline, which read as system residue in the narration. The MANUAL-tap
    // path still shows the player's chosen reaction — that's their deliberate
    // choice, not auto-residue.)

    // Track skip streak for telemetry adaptation
    state._microExprSkipStreak = (state._microExprSkipStreak || 0) + 1;

    if (typeof window._logTelemetry === 'function') {
      window._logTelemetry({ type: 'micro_expression', sceneIndex: state.turnCount || 0, shown: true, interacted: false, autoResolved: true, skipped: false });
    }
    console.log('[MICRO-EXPR] Auto-resolved moment', exprIdx, ':', behaviorLine);
  }

  // P5: Scene-to-scene continuity — build opening echo from last expression
  function _buildMicroExprContinuityLine() {
    var last = state._lastMicroExpression;
    if (!last || !last.label) return '';
    // 50% probability
    if (Math.random() > 0.50) return '';

    var _continuityLines = {
      approach_warm:   'You don\'t look away this time.',
      approach_cold:   'That same edge follows you in.',
      withdraw_warm:   'Something still pulls you back, even now.',
      withdraw_cold:   'The distance is familiar — yours.',
      dominant_warm:   'That same quiet confidence lingers.',
      dominant_cold:   'You enter holding nothing back.',
      yielding_warm:   'Softness still sits where you left it.',
      yielding_cold:   'Your silence speaks before you do.',
      playful_warm:    'The lightness hasn\'t left you yet.',
      playful_cold:    'That smirk hasn\'t gone anywhere.',
      serious_warm:    'You carry the weight easily.',
      serious_cold:    'Nothing about you has softened.'
    };

    return _continuityLines[last.bankKey] || '';
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // PRESSURE ENGINE — targeted dramatic pressure based on player behavior
  // ═══════════════════════════════════════════════════════════════════════════
  // CORE RULE: The pressure profile represents where the player is most
  // sensitive. The system uses it to APPLY PRESSURE, not satisfaction.

  function _clampPressure(v) { return Math.max(0, Math.min(1, v)); }

  /**
   * Update pressure profile based on player behavior signals.
   * Called after each scene (scene 2+). Reads engagement signals, player
   * action text, and story state to infer sensitivity dimensions.
   * Max shift: 0.1 per scene per dimension.
   */
  function _updatePressureProfile(playerAction, playerDialogue) {
    var pp = state._pressureProfile;
    var scene = state.turnCount || 0;
    if (scene < 2) return; // No early adjustment
    if (scene === state._pressureProfileLastScene) return; // Once per scene
    state._pressureProfileLastScene = scene;

    var act = ((playerAction || '') + ' ' + (playerDialogue || '')).toLowerCase();
    var delta = { romance: 0, power: 0, conflict: 0, uncertainty: 0 };

    // Romance signals: affection, touch, vulnerability, intimacy keywords
    if (/kiss|touch|hold|closer|love|heart|feel|tender|soft|miss you|need you|afraid.*los/i.test(act)) {
      delta.romance += 0.08;
    }
    // Power signals: control, command, demand, refuse, dominate
    if (/command|demand|refuse|control|force|make (him|her|them)|submit|kneel|obey|my way|take charge/i.test(act)) {
      delta.power += 0.08;
    }
    // Conflict signals: confront, challenge, accuse, fight, argue
    if (/confront|challenge|accuse|fight|argue|push back|disagree|won't accept|call (him|her|them) out/i.test(act)) {
      delta.conflict += 0.08;
    }
    // Uncertainty signals: investigate, question, doubt, wait, hesitate
    if (/investigate|question|doubt|wait|hesitat|unsure|what if|look closer|search|explore|don't trust/i.test(act)) {
      delta.uncertainty += 0.08;
    }

    // Storyturn-based ambient pressure: ST phase biases certain dimensions
    var st = state.storyturn || 'ST1';
    if (st === 'ST1' || st === 'ST2') { delta.uncertainty += 0.03; delta.romance += 0.02; }
    if (st === 'ST3') { delta.romance += 0.05; delta.power += 0.03; }
    if (st === 'ST4') { delta.conflict += 0.05; delta.power += 0.03; }
    if (st === 'ST5') { delta.uncertainty += 0.05; delta.conflict += 0.03; }

    // Engagement signal integration: high engagement = lean into dominant dimension
    var signals = state._engagementSignals || {};
    if (signals.microExprInteracted) {
      // Player is paying attention — amplify dominant
      var max = Math.max(pp.romance, pp.power, pp.conflict, pp.uncertainty);
      if (pp.romance === max) delta.romance += 0.03;
      if (pp.power === max) delta.power += 0.03;
      if (pp.conflict === max) delta.conflict += 0.03;
      if (pp.uncertainty === max) delta.uncertainty += 0.03;
    }

    // Decay non-signaled dimensions toward 0.5 (neutral)
    ['romance', 'power', 'conflict', 'uncertainty'].forEach(function(dim) {
      if (delta[dim] === 0) {
        delta[dim] = (0.5 - pp[dim]) * 0.05; // Slow regression to center
      }
    });

    // Apply deltas with 0.1 cap per dimension per scene
    pp.romance = _clampPressure(pp.romance + Math.max(-0.1, Math.min(0.1, delta.romance)));
    pp.power = _clampPressure(pp.power + Math.max(-0.1, Math.min(0.1, delta.power)));
    pp.conflict = _clampPressure(pp.conflict + Math.max(-0.1, Math.min(0.1, delta.conflict)));
    pp.uncertainty = _clampPressure(pp.uncertainty + Math.max(-0.1, Math.min(0.1, delta.uncertainty)));

    _logPressureProfile();
  }

  // ── RELATIONAL-SHAPE READ (attraction architecture — SLICE 1) ──────────
  // Telemetry-ONLY classification of the RAW Say/Do input's emotional shape.
  // Influences NOTHING (no chemistry, no LI response, no glow). It exists so
  // the data model + plumbing + gating can be validated before any downstream
  // wiring. See project_relational_attraction_architecture.md.
  //
  // FIREWALLS honored here:
  //  • Reads RAW playerAction/playerDialogue — runs upstream of Say/Do
  //    transmutation, so the read can never grade the engine's own rewrite.
  //  • NO aggregate scalar — the read is a DISTRIBUTED object. A single
  //    number would be an alpha-stat in waiting.
  //  • Reads UNIVERSALLY (all orientations) — the unified-classifier decision.
  //    NOT a male module + female module (that would be the gender prison).
  //    One classifier reads the UNION of vectors for everyone; orientation is
  //    a SOFT PRIOR on emphasis (logged for ecology), corrected by observation.
  //  • NO aggregate scalar — DISTRIBUTED object only.
  //
  // CLASSIFICATION LOGIC LIVES IN THE SHARED AUTHORITY:
  //   public/relational-shape-classifier.js (window.StoryboundRelationalShape)
  // — the SAME module the simulation harness imports, so app + sim can never
  // drift. This function only gathers raw inputs + the soft prior from state,
  // calls the classifier, stores the result, and logs. It passes ctx=null for
  // now (→ identical v0 behavior); the context-aware tier activates once the
  // scene-relational signal extractor supplies what the LI just did.
  function _readRelationalShape(playerAction, playerDialogue) {
    try {
      var rsc = (typeof window !== 'undefined' && window.StoryboundRelationalShape) || null;
      if (!rsc || typeof rsc.classifyRelationalShape !== 'function') return; // module not loaded — fail safe

      // Soft prior for the ecology study (correlate shape with orientation) —
      // NOT a compute gate. See project_relational_attraction_architecture.md.
      var prior = {
        pc: String(state.gender || state.playerGender || 'Female').toLowerCase(),
        li: String(state.loveInterest || state.loveInterestGender || _defaultLIGenderForPC(state)).toLowerCase()
      };

      // ctx=null → v0 lexical behavior (no regression). The live scene-relational
      // extractor is a later slice; until then the scene-relational vectors
      // default per the classifier's documented v0 fallback.
      var r = rsc.classifyRelationalShape(playerAction, playerDialogue, prior, null);
      if (!r) return;
      r.scene = state.turnCount || 0;
      state._relationalShapeProbe = r;

      console.log('[RELSHAPE] raw input — act=' + r.initiative +
        ' tension=' + r.tension_handling +
        ' desire=' + r.desire_expression +
        ' reciprocity=' + r.reciprocity_recognition +
        ' register=' + r.register_shape +
        ' | recept=' + r.receptivity +
        ' own=' + r.desire_ownership +
        ' presence=' + r.presence_after_contact +
        ' vuln=' + r.vulnerability +
        ' | prior(pc=' + prior.pc + ',li=' + prior.li + ')' +
        ' (scene ' + (state.turnCount || 0) + ', ' + r._classifier + ')');
    } catch (_) {}
  }

  /**
   * Resolve pressure escalation phase based on scene index and story mode.
   * Returns: "probe" | "test" | "consequence"
   * Participatory: 2-beat cycle (test → consequence)
   * Literary: 3-beat cycle (probe → test → consequence)
   * Phase drift: offset increments every 4 scenes to break pattern recognition.
   */
  function _resolvePressurePhase(sceneIndex, storyMode) {
    var idx = sceneIndex || 0;
    var offset = state._pressureDriftOffset || 0;
    var phase;

    if (storyMode === 'literary') {
      var cycleLen = 3;
      var phase3 = (idx + offset) % cycleLen;
      phase = phase3 === 0 ? 'probe' : (phase3 === 1 ? 'test' : 'consequence');
      // Narrative-sensitive drift: only advance after consequence landed
      if (idx > 0 && idx % 4 === 0 && state._lastPhaseWasConsequence) {
        state._pressureDriftOffset = (offset + 1) % cycleLen;
      }
    } else {
      // Participatory: 2-beat cycle with drift
      var cycleLen2 = 2;
      var phase2 = (idx + offset) % cycleLen2;
      phase = phase2 === 0 ? 'test' : 'consequence';
      if (idx > 0 && idx % 4 === 0 && state._lastPhaseWasConsequence) {
        state._pressureDriftOffset = (offset + 1) % cycleLen2;
      }
    }

    // Track for next drift decision
    state._lastPhaseWasConsequence = (phase === 'consequence');
    return phase;
  }

  // ── CROSS-CHARACTER PRESSURE ROUTING ──
  // Different characters express different pressure phases within the same scene.
  // Global phase remains dominant; character variation is subtle layering.

  /**
   * Stable string hash → 0-2 index (deterministic, no randomness).
   */
  function _stableCharHash(str) {
    var h = 0;
    for (var i = 0; i < str.length; i++) {
      h = ((h << 5) - h + str.charCodeAt(i)) | 0;
    }
    return ((h < 0 ? -h : h) % 3);
  }

  // Archetype-to-phase bias: +1 offset toward natural pressure style
  // (canonical 7 only; Storm Reign / Golden Ruin / Gentle Siege removed).
  var _ARCHETYPE_PHASE_BIAS = {
    'Dark Vice': 1,       // bias toward test
    'Spellbinder': 1,     // bias toward test
    'Open Vein': -1       // bias toward probe
    // Antagonistic / remaining archetypes handled by default hash
  };

  var _PHASE_ORDER = ['probe', 'test', 'consequence'];

  // Phase routing tables: globalPhase → [hash0, hash1, hash2]
  var _CHAR_PHASE_ROUTING = {
    probe:       ['probe', 'probe', 'test'],
    test:        ['probe', 'test', 'consequence'],
    consequence: ['test', 'consequence', 'consequence']
  };

  /**
   * Resolve per-character pressure phase.
   * characterId: stable string identifier (archetype name or "protagonist")
   * globalPhase: the scene-level phase from _resolvePressurePhase
   * Returns: "probe" | "test" | "consequence"
   */
  function _resolveCharacterPressurePhase(characterId, globalPhase) {
    var routing = _CHAR_PHASE_ROUTING[globalPhase] || _CHAR_PHASE_ROUTING.test;
    var hash = _stableCharHash(characterId || 'unknown');

    // Apply archetype bias (shift hash index by bias, clamped 0-2)
    var bias = _ARCHETYPE_PHASE_BIAS[characterId] || 0;

    // Memory-weighted bias: tension pushes toward consequence, affinity toward probe
    // Max ±1 shift from memory (stability constraint)
    var mem = (state._characterMemory && state._characterMemory[characterId]) || _DEFAULT_CHAR_MEMORY;
    var memBias = 0;
    if (mem.tension > 0.6) memBias += 1;    // high tension → consequence
    if (mem.affinity > 0.5) memBias -= 1;   // high affinity → probe
    // respect > 0.5 stabilizes (no shift)

    var totalBias = bias + memBias;
    var biasedHash = Math.max(0, Math.min(2, hash + totalBias));

    return routing[biasedHash];
  }

  /**
   * Build cross-character pressure routing block for prompt injection.
   * Returns empty string if fewer than 2 characters or pressure inactive.
   */
  function _buildCrossCharacterPressureBlock(globalPhase) {
    var archetype = (state.archetype && state.archetype.primary) || '';
    if (!archetype) return '';

    var protagonistPhase = _resolveCharacterPressurePhase('protagonist', globalPhase);
    var liPhase = _resolveCharacterPressurePhase(archetype, globalPhase);

    // Stability: with 2 characters, ensure distinct phases
    if (protagonistPhase === liPhase) {
      var idx = _PHASE_ORDER.indexOf(liPhase);
      liPhase = _PHASE_ORDER[Math.min(idx + 1, 2)] || liPhase;
      if (liPhase === protagonistPhase) {
        liPhase = _PHASE_ORDER[Math.max(idx - 1, 0)] || liPhase;
      }
    }

    // Phase intent labels (compact)
    var _phaseLabel = {
      probe: 'assessing, withholding, restrained',
      test: 'challenging, forcing exposure, assertive',
      consequence: 'reacting, showing cost, revealing aftermath'
    };

    var lines = [];

    // ── SECTION 1: PHASE BEHAVIOR (hard constraints) ──
    lines.push('CROSS-CHARACTER DYNAMICS (scene tone: ' + globalPhase.toUpperCase() + '):');
    lines.push('');
    lines.push('PHASE BEHAVIOR (ENFORCE):');
    lines.push('- Protagonist: ' + protagonistPhase.toUpperCase() + ' (' + _phaseLabel[protagonistPhase] + ')');
    lines.push('- ' + archetype + ': ' + liPhase.toUpperCase() + ' (' + _phaseLabel[liPhase] + ')');
    lines.push('');
    lines.push('PROBE: Do NOT initiate confrontation or force decisions. Use observation, implication, subtext.');
    lines.push('TEST: Directly challenge, pressure, or force reaction. Do NOT remain passive.');
    lines.push('CONSEQUENCE: React to prior actions. Show cost, fallout, reversal. Do NOT initiate new pressure.');
    lines.push('Characters MUST follow assigned phase. Blurred behavior = failure.');

    // ── SECTION 2: MEMORY & INTERPRETATION ──
    var memBlock = (typeof _buildCharacterMemoryBlock === 'function') ? _buildCharacterMemoryBlock() : '';
    if (memBlock) {
      lines.push('');
      lines.push(memBlock);
    }
    lines.push('');
    lines.push('MEMORY & INTERPRETATION:');
    lines.push('Characters interpret the player subjectively based on affinity, respect, tension.');
    lines.push('Interpretations may be incorrect \u2014 a kind act seen as manipulative, a neutral act as intentional.');
    lines.push('Repeated player behavior compounds impact. Characters do NOT share a unified view.');

    // ── SECTION 3: CONFLICT & ALLIANCES ──
    lines.push('');
    lines.push('CONFLICT & ALLIANCES:');
    lines.push('Characters may disagree about the player and confront each other \u2014 not just the player.');
    lines.push('Conflict should feel uneven (one presses, another hesitates). Avoid symmetrical debate.');
    lines.push('Alliances are fluid and situational \u2014 characters may briefly align then diverge.');
    lines.push('Do NOT fabricate conflict or alliances without memory basis. Do NOT resolve disagreements immediately.');

    // ── SECTION 4: REALISM ──
    lines.push('');
    lines.push('REALISM:');
    lines.push('Characters may act on their own goals, not just react to the player.');
    lines.push('Subtle inconsistency is allowed under emotional pressure \u2014 not chaotic, but human.');
    lines.push('All behavior must be motivated. Characters are autonomous, not player-serving.');
    lines.push('Scenes should feel socially alive: layered, shifting, imperfect.');

    console.log('[PRESSURE ROUTING]', {
      protagonist: protagonistPhase,
      loveInterest: liPhase,
      archetype: archetype,
      globalPhase: globalPhase
    });

    return '\n' + lines.join('\n') + '\n';
  }

  // ── CHARACTER MEMORY SYSTEM ──
  // Per-character relational memory: affinity, respect, tension.
  // Drives grudge/favor states and memory-weighted pressure routing.

  var _DEFAULT_CHAR_MEMORY = { affinity: 0, respect: 0, tension: 0, lastTone: null, repeatCount: 0 };

  function _getCharMemory(characterId) {
    if (!state._characterMemory) state._characterMemory = {};
    if (!state._characterMemory[characterId]) {
      state._characterMemory[characterId] = { affinity: 0, respect: 0, tension: 0, lastTone: null, repeatCount: 0 };
    }
    return state._characterMemory[characterId];
  }

  function _clampMem(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }

  /**
   * Update character memory based on player action tone.
   * Called after each scene alongside pressure profile update.
   * playerAction: raw player input text
   * Lightweight keyword detection — no model calls.
   */
  function _updateCharacterMemory(playerAction) {
    if (!state._characterMemory) state._characterMemory = {};
    var act = (playerAction || '').toLowerCase();
    var archetype = (state.archetype && state.archetype.primary) || '';
    var characters = ['protagonist'];
    if (archetype) characters.push(archetype);

    // Detect tone from player action (priority: first match wins)
    var currentTone = null;
    if (/trust|open up|confess|admit|vulnerable|honest|scared|afraid|need you|sorry|forgive/i.test(act)) currentTone = 'vulnerable';
    else if (/command|demand|control|force|make (him|her|them)|submit|my way|take charge|insist|order/i.test(act)) currentTone = 'dominant';
    else if (/reject|refuse|push away|leave|walk away|don't care|shut (up|out)|ignore|cold shoulder/i.test(act)) currentTone = 'rejecting';
    else if (/avoid|evade|change subject|not now|later|don't know|shrug|silence|say nothing|look away/i.test(act)) currentTone = 'evasive';

    for (var i = 0; i < characters.length; i++) {
      var mem = _getCharMemory(characters[i]);

      // Apply scene decay toward neutral first
      mem.affinity *= 0.95;
      mem.respect *= 0.95;
      mem.tension *= 0.97;

      // Pattern reinforcement: track repeated tone
      if (currentTone) {
        if (currentTone === mem.lastTone) {
          mem.repeatCount = Math.min(mem.repeatCount + 1, 5); // cap at 5
        } else {
          mem.repeatCount = 1;
        }
        mem.lastTone = currentTone;

        // Amplify delta based on repeat count
        var multiplier = mem.repeatCount >= 3 ? 2.0 : (mem.repeatCount >= 2 ? 1.5 : 1.0);

        // Apply tone signals with multiplier
        if (currentTone === 'vulnerable') { mem.affinity += 0.05 * multiplier; }
        if (currentTone === 'dominant') { mem.respect += 0.05 * multiplier; mem.affinity -= 0.02 * multiplier; }
        if (currentTone === 'rejecting') { mem.affinity -= 0.05 * multiplier; mem.tension += 0.05 * multiplier; }
        if (currentTone === 'evasive') { mem.tension += 0.03 * multiplier; }
      }

      // Clamp
      mem.affinity = _clampMem(mem.affinity, -1, 1);
      mem.respect = _clampMem(mem.respect, -1, 1);
      mem.tension = _clampMem(mem.tension, 0, 1);
    }

    _logCharacterMemory();
  }

  /**
   * Derive grudge/favor states from character memory.
   */
  function _getCharDerivedState(characterId) {
    var mem = _getCharMemory(characterId);
    // Continuous grudge/favor levels (0-1)
    var grudgeLevel = _clampMem(mem.tension * (1 - mem.affinity), 0, 1);
    var favorLevel = _clampMem(Math.max(0, mem.affinity) * Math.max(0, mem.respect), 0, 1);
    return {
      grudge: grudgeLevel > 0.3,   // backwards-compatible boolean
      favor: favorLevel > 0.3,     // backwards-compatible boolean
      grudgeLevel: grudgeLevel,
      favorLevel: favorLevel
    };
  }

  function _intensityBand(level) {
    if (level >= 0.6) return 'dominant';
    if (level >= 0.3) return 'noticeable';
    return 'subtle';
  }

  /**
   * Build character memory prompt block for injection into cross-character routing.
   */
  function _buildCharacterMemoryBlock() {
    var archetype = (state.archetype && state.archetype.primary) || '';
    if (!archetype) return '';
    var scene = state.turnCount || 0;
    if (scene < 3) return ''; // No memory before scene 3

    var liMem = _getCharMemory(archetype);
    var liState = _getCharDerivedState(archetype);

    // Only inject if memory has deviated meaningfully from neutral
    if (Math.abs(liMem.affinity) < 0.15 && Math.abs(liMem.respect) < 0.15 && liMem.tension < 0.15) return '';

    var lines = [];
    lines.push('CHARACTER MEMORY STATES:');
    lines.push('Each character carries evolving memory of the player.');

    // Affinity description
    if (liMem.affinity > 0.3) lines.push('- ' + archetype + ': warmth, openness, risk-taking toward player.');
    else if (liMem.affinity < -0.3) lines.push('- ' + archetype + ': distance, coldness, resistance toward player.');

    // Respect description
    if (liMem.respect > 0.3) lines.push('- ' + archetype + ': takes player seriously, engages directly.');
    else if (liMem.respect < -0.3) lines.push('- ' + archetype + ': dismissive, underestimates player.');

    // Tension description
    if (liMem.tension > 0.4) lines.push('- ' + archetype + ': volatile, unpredictable with player.');

    // Pattern reinforcement note
    if (liMem.repeatCount >= 3) {
      lines.push('- ' + archetype + ': pattern detected \u2014 player has been consistently ' + (liMem.lastTone || 'neutral') + '. This compounds impact.');
    }

    // Continuous grudge/favor (PART 2)
    var grudgeBand = _intensityBand(liState.grudgeLevel);
    var favorBand = _intensityBand(liState.favorLevel);

    lines.push('');
    lines.push('RELATIONAL INTENSITY:');
    if (liState.grudgeLevel > 0.1) {
      var grudgeDesc = {
        dominant: 'sharper pressure, less forgiveness, quicker escalation',
        noticeable: 'guarded, testing, conditional behavior',
        subtle: 'minimal resentment, slight wariness'
      };
      lines.push('- Grudge toward player (' + grudgeBand + ', ' + liState.grudgeLevel.toFixed(2) + '): ' + grudgeDesc[grudgeBand]);
    }
    if (liState.favorLevel > 0.1) {
      var favorDesc = {
        dominant: 'more benefit of doubt, delayed consequence (but not removed)',
        noticeable: 'nuanced response, mixed signals',
        subtle: 'neutral baseline, slight warmth'
      };
      lines.push('- Favor toward player (' + favorBand + ', ' + liState.favorLevel.toFixed(2) + '): ' + favorDesc[favorBand]);
    }
    lines.push('These are gradients, not binary states.');

    // Memory-influenced behavior
    lines.push('');
    lines.push('MEMORY-INFLUENCED BEHAVIOR:');
    lines.push('Characters adjust HOW they apply pressure based on their history with the player.');
    lines.push('- High grudge \u2192 harsher consequence, less patience.');
    lines.push('- High favor \u2192 more nuanced probing, delayed consequence.');
    lines.push('- High tension \u2192 faster escalation toward consequence.');
    lines.push('- High affinity \u2192 deeper emotional stakes, not reduced pressure.');

    // PART 3 — Cross-Memory Triangulation
    var proMem = _getCharMemory('protagonist');
    var affinityGap = liMem.affinity - proMem.affinity;
    var tensionGap = liMem.tension - proMem.tension;
    // Only inject triangulation if meaningful asymmetry exists between characters
    if (Math.abs(affinityGap) > 0.25 || Math.abs(tensionGap) > 0.25) {
      lines.push('');
      lines.push('CROSS-MEMORY TRIANGULATION:');
      lines.push('Characters are aware of how the player treats others.');
      lines.push('- Treatment of one character influences how others perceive the player.');
      lines.push('- Characters may compare themselves to others.');
      lines.push('- Positive behavior toward one may create trust OR jealousy in another.');
      lines.push('- Negative behavior toward one may create fear or distrust in others.');
      lines.push('Characters do NOT operate in isolation \u2014 they observe patterns.');
      if (affinityGap > 0.25) {
        lines.push('- ' + archetype + ' perceives MORE warmth than protagonist received \u2192 may feel favored but wary of inconsistency.');
      } else if (affinityGap < -0.25) {
        lines.push('- ' + archetype + ' perceives LESS warmth than protagonist received \u2192 may feel overlooked, jealous, or distrustful.');
      }
      if (tensionGap > 0.25) {
        lines.push('- ' + archetype + ' carries MORE tension than protagonist \u2192 may question why they bear the brunt.');
      }
      lines.push('');
      lines.push('TRIANGULATED CONFLICT:');
      lines.push('If characters interpret the player\'s behavior differently:');
      lines.push('- They may challenge each other\'s view.');
      lines.push('- One may defend the player, another may accuse.');
      lines.push('- This disagreement should create tension between characters.');
      lines.push('Do NOT resolve immediately \u2014 allow competing interpretations to persist.');
    }

    return '\n' + lines.join('\n') + '\n';
  }

  /**
   * Debug logging for character memory.
   */
  function _logCharacterMemory() {
    var archetype = (state.archetype && state.archetype.primary) || '';
    if (!archetype) return;
    var mem = _getCharMemory(archetype);
    var derived = _getCharDerivedState(archetype);
    console.log('[CHARACTER MEMORY]', {
      characterId: archetype,
      affinity: mem.affinity.toFixed(2),
      respect: mem.respect.toFixed(2),
      tension: mem.tension.toFixed(2),
      repeatCount: mem.repeatCount,
      lastTone: mem.lastTone,
      grudgeLevel: derived.grudgeLevel.toFixed(2),
      favorLevel: derived.favorLevel.toFixed(2)
    });
    // Triangulation log
    var proMem = _getCharMemory('protagonist');
    var affinityGap = mem.affinity - proMem.affinity;
    var tensionGap = mem.tension - proMem.tension;
    if (Math.abs(affinityGap) > 0.15 || Math.abs(tensionGap) > 0.15) {
      console.log('[TRIANGULATION]', {
        characterA: archetype,
        characterB: 'protagonist',
        affinityGap: affinityGap.toFixed(2),
        tensionGap: tensionGap.toFixed(2)
      });
    }
  }

  // Phase-specific language per dimension
  var _PRESSURE_PHASE_LANG = {
    probe: {
      romance: 'Introduce vulnerability or emotional openness without forcing outcome.',
      power: 'Signal instability or subtle resistance to control.',
      conflict: 'Introduce friction or disagreement without escalation.',
      uncertainty: 'Hint at ambiguity or incomplete understanding.'
    },
    test: {
      romance: 'Force emotional exposure or meaningful vulnerability.',
      power: 'Directly challenge control with resistance or opposition.',
      conflict: 'Escalate disagreement into meaningful stakes or consequences.',
      uncertainty: 'Force action despite incomplete information.'
    },
    consequence: {
      romance: 'Apply emotional cost, risk of loss, or consequence of intimacy.',
      power: 'Trigger reversal, backlash, or loss of control.',
      conflict: 'Introduce irreversible outcomes or collateral impact.',
      uncertainty: 'Reveal partial truth that deepens complexity or creates new doubt.'
    }
  };

  // Phase-specific anti-comfort guardrails
  var _PRESSURE_PHASE_GUARDRAIL = {
    probe: 'Probe phase: do NOT resolve tension. Plant seeds of pressure only \u2014 no payoff, no comfort.',
    test: 'Test phase: create a clear tradeoff. The player must face a cost no matter which direction they choose.',
    consequence: 'Consequence phase: deliver cost or lasting effect. Something must change irreversibly.'
  };

  /**
   * Build the pressure profile prompt directive.
   * Injects phase-aware, targeted dramatic pressure instructions.
   */
  function buildPressureProfileDirective() {
    var pp = state._pressureProfile;
    if (!pp) return '';
    var scene = state.turnCount || 0;
    if (scene < 1) return '';

    var phase = _resolvePressurePhase(scene, state.storyMode);
    var phaseLang = _PRESSURE_PHASE_LANG[phase] || _PRESSURE_PHASE_LANG.test;

    var dims = [
      { key: 'romance', val: pp.romance },
      { key: 'power', val: pp.power },
      { key: 'conflict', val: pp.conflict },
      { key: 'uncertainty', val: pp.uncertainty }
    ].sort(function(a, b) { return b.val - a.val; });
    var dominant = dims[0];
    var secondary = dims[1];

    if (dominant.val <= 0.55) return '';

    var _archId = (state.archetype && state.archetype.primary) || '';
    var _archExpr = {
      'Open Vein': 'emotional exposure, vulnerability',
      'Spellbinder': 'controlled, indirect influence',
      'Dark Vice': 'provocation and risk',
      'Heart Warden': 'boundaries and correction',
      'Eternal Flame': 'inevitability and recognition',
      'Beautiful Ruin': 'destabilizing intensity',
      'Armored Fox': 'deflection and wit'
    };

    // ── UNIFIED PRESSURE ENGINE ──
    var p = [];
    p.push('PRESSURE ENGINE (phase: ' + phase.toUpperCase() + (_archId ? ', archetype: ' + _archId : '') + '):');
    p.push('This scene is driven by pressure. Phase defines intensity, archetype defines expression. They combine \u2014 never separate.');

    // Phase + dimension targeting
    if (pp.romance > 0.55) p.push('- Romance ' + (pp.romance > 0.75 ? 'HIGH' : 'MOD') + ': ' + phaseLang.romance);
    if (pp.power > 0.55) p.push('- Power ' + (pp.power > 0.75 ? 'HIGH' : 'MOD') + ': ' + phaseLang.power);
    if (pp.conflict > 0.55) p.push('- Conflict ' + (pp.conflict > 0.75 ? 'HIGH' : 'MOD') + ': ' + phaseLang.conflict);
    if (pp.uncertainty > 0.55) p.push('- Uncertainty ' + (pp.uncertainty > 0.75 ? 'HIGH' : 'MOD') + ': ' + phaseLang.uncertainty);
    if (_archId) p.push('- Archetype expression: ' + (_archExpr[_archId] || 'distinct'));

    // Phase guardrail (compact)
    p.push(_PRESSURE_PHASE_GUARDRAIL[phase]);

    // Anti-comfort + dominant dimension guardrail (merged)
    var guardrailMap = {
      romance: 'If intimacy is achieved, it must introduce risk. Comfort without cost is forbidden.',
      power: 'If control is gained, it must trigger resistance. Unchecked dominance is forbidden.',
      conflict: 'If a confrontation resolves, it must create secondary tension. Consequence-free resolution is forbidden.',
      uncertainty: 'If clarity is achieved, it must reveal a deeper unknown. Premature resolution is forbidden.'
    };
    if (dominant.val > 0.6) p.push(guardrailMap[dominant.key]);

    // Choice tradeoffs (compact)
    var choiceMap = {
      romance: 'Choices: vulnerability vs self-protection. No safe options.',
      power: 'Choices: control vs backlash. Every path to authority carries cost.',
      conflict: 'Choices: escalation vs restraint \u2014 consequences either way.',
      uncertainty: 'Choices: act without clarity vs wait \u2014 risk either way.'
    };
    p.push(choiceMap[dominant.key]);

    // Core rules (consolidated from separate anti-comfort + escalation blocks)
    p.push('RULES: Pressure must persist. Do NOT resolve tension without cost. Do NOT remove difficulty. Do NOT allow consequence-free interaction. The story does NOT optimize for player preference. Comfort is allowed only when earned through prior cost. If the scene lacks tension, cost, or directional pressure, it is invalid.');

    // Cross-character routing
    var charRouting = _buildCrossCharacterPressureBlock(phase);
    if (charRouting) p.push(charRouting);

    _logPressurePhase(scene, phase);
    return '\n' + p.join('\n') + '\n';
  }

  /**
   * Debug logging for pressure phase.
   */
  function _logPressurePhase(sceneIndex, phase) {
    console.log('[PRESSURE PHASE]', {
      sceneIndex: sceneIndex,
      phase: phase,
      offset: state._pressureDriftOffset || 0,
      storyMode: state.storyMode || 'participatory'
    });
  }

  /**
   * Debug logging for pressure profile.
   */
  function _logPressureProfile() {
    var pp = state._pressureProfile;
    console.log('[PRESSURE ENGINE]', {
      romance: pp.romance.toFixed(2),
      power: pp.power.toFixed(2),
      conflict: pp.conflict.toFixed(2),
      uncertainty: pp.uncertainty.toFixed(2),
      scene: state.turnCount || 0
    });
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // ADAPTIVE TUNING — invisible intra-mode scalar adjustment
  // ═══════════════════════════════════════════════════════════════════════════

  function _clampTuning(v) { return Math.max(0.7, Math.min(1.3, v)); }

  /**
   * Initialize adaptive tuning. Under the unified "Active + low-agency"
   * model, all stories start with Active defaults. Inference score from
   * corridor selections modulates Scene 1 scalars only (softer opening for
   * users whose picks strongly suggested Mindful — Soulmates + Literary +
   * 5th-person POV, etc.) without a separate prompt variant.
   */
  function _initAdaptiveTuning() {
    var inferenceScore = state._inferenceScore;
    var hookScalar = 1.0;
    var densityScalar = 1.0;

    // Scene 1 scalar modulation for strongly-Mindful-inferred users.
    // Softens the opening's pacing pressure without changing the contract.
    if (typeof inferenceScore === 'number' && inferenceScore <= -4) {
      hookScalar = 0.85;
      densityScalar = 1.1;
      console.log('[ADAPTIVE TUNING] Scene 1 softening applied — inferenceScore=' +
                  inferenceScore.toFixed(1) + ' (hook: 1.0→0.85, density: 1.0→1.1)');
    }

    state._adaptiveTuning = {
      paceScalar: 1.0,
      hookScalar: hookScalar,
      densityScalar: densityScalar,
      lastAdjustmentScene: 0
    };
  }

  /**
   * Update adaptive tuning based on engagement signals.
   * Called after each scene (scene 2+). Uses damped smoothing.
   */
  function _updateAdaptiveTuning() {
    var at = state._adaptiveTuning;
    if (!at) { _initAdaptiveTuning(); at = state._adaptiveTuning; }

    // INTENSITY CALIBRATION — one-shot nudge from the Scene 2/3 micro-
    // expression click. Runs BEFORE the scene-gated engagement tuning
    // below so a Scene 2 click (turnCount===1) isn't blocked by the
    // `if (scene < 2) return` guard. `_intensityAppliedToAdaptive`
    // ensures this applies exactly once per story regardless of how
    // many times _updateAdaptiveTuning is invoked afterward.
    if (state._intensityCalibrated && state._intensitySignal && !state._intensityAppliedToAdaptive) {
      var _densityIC = at.densityScalar;
      var _hookIC = at.hookScalar;
      var _paceIC = at.paceScalar;
      if (state._intensitySignal === 'toward') {
        _densityIC += 0.06;  // linger, richer detail
        _hookIC    += 0.04;  // stronger pull / fixation
        _paceIC    -= 0.04;  // slight slow-down
      } else if (state._intensitySignal === 'away') {
        _densityIC -= 0.06;  // lighter description
        _hookIC    -= 0.04;  // softer pull
        _paceIC    += 0.04;  // slightly faster movement
      }
      at.densityScalar = _clampTuning(_densityIC);
      at.hookScalar    = _clampTuning(_hookIC);
      at.paceScalar    = _clampTuning(_paceIC);
      state._intensityAppliedToAdaptive = true;
      console.log('[INTENSITY\u2192ADAPTIVE]', {
        signal:  state._intensitySignal,
        pace:    at.paceScalar.toFixed(2),
        density: at.densityScalar.toFixed(2),
        hook:    at.hookScalar.toFixed(2)
      });
    }

    // INTIMACY STANCE — per-scene nudge (surrender/control) applied when
    // the intimacy micro-decision fires. Unlike Scene 2 calibration (one-
    // shot), this can apply once per intimacy scene, so cumulative drift
    // is clamped via state._intimacyAccumulator: density ∈ ±0.15,
    // pace ∈ ±0.10. The per-scene application itself is gated by the
    // click handler — _intimacyMicroDecisionUsedThisScene prevents
    // double-fire within a scene, and the scene-advance reset allows
    // re-evaluation on the next scene.
    if (state._intensityStance && state._intimacyMicroDecisionUsedThisScene && !state._intimacyStanceAppliedThisScene) {
      if (!state._intimacyAccumulator) state._intimacyAccumulator = { density: 0, pace: 0 };
      var acc = state._intimacyAccumulator;
      var _deltaD = (state._intensityStance === 'surrender') ?  0.03 : -0.03;
      var _deltaP = (state._intensityStance === 'surrender') ? -0.02 :  0.02;
      var _prevAccD = acc.density;
      var _prevAccP = acc.pace;
      // Clamp the CUMULATIVE accumulator first; derive the effective
      // per-click delta from the clamp residue so partial nudges still
      // apply near the cap instead of being silently dropped.
      var _nextAccD = Math.max(-0.15, Math.min(0.15, _prevAccD + _deltaD));
      var _nextAccP = Math.max(-0.10, Math.min(0.10, _prevAccP + _deltaP));
      var _effDeltaD = _nextAccD - _prevAccD;
      var _effDeltaP = _nextAccP - _prevAccP;
      // Apply only when there's residual budget in the cap — if both
      // deltas collapse to 0 we're saturated; skip application + log.
      if (_effDeltaD !== 0 || _effDeltaP !== 0) {
        at.densityScalar = _clampTuning(at.densityScalar + _effDeltaD);
        at.paceScalar    = _clampTuning(at.paceScalar    + _effDeltaP);
        acc.density = _nextAccD;
        acc.pace    = _nextAccP;
      }
      // Prevent re-application on the next _updateAdaptiveTuning call
      // within the same scene. The per-scene reset at turn-advance
      // clears _intimacyMicroDecisionUsedThisScene so the NEXT scene's
      // click can re-trigger this block.
      console.log('[INTIMACY\u2192ADAPTIVE]', {
        stance:   state._intensityStance,
        applied:  { density: _effDeltaD.toFixed(3), pace: _effDeltaP.toFixed(3) },
        accum:    { density: acc.density.toFixed(3), pace: acc.pace.toFixed(3) },
        saturated: (_effDeltaD === 0 && _effDeltaP === 0)
      });
      // Guard — clear the within-scene marker so this branch doesn't
      // re-fire on subsequent tuning ticks before the scene advances.
      // The _intimacyMicroDecisionUsedThisScene flag stays true for
      // the extractor gate; we use a separate applied-marker to avoid
      // conflating render gating with tuning gating.
      state._intimacyStanceAppliedThisScene = true;
    }

    var scene = state.turnCount || 0;
    if (scene < 2) return;
    if (scene <= at.lastAdjustmentScene) return; // Once per scene
    at.lastAdjustmentScene = scene;

    var signals = state._engagementSignals || {};
    var avgDelay = state._avgInteractionDelayMs || 5000;
    var commitScore = _computeCommitmentScore();

    // Detect user speed pattern
    var slowUser = avgDelay > 7000 || commitScore <= 1;
    var fastUser = avgDelay < 2000 || commitScore >= 3;

    // Compute target adjustments
    var targetPace = at.paceScalar;
    var targetHook = at.hookScalar;
    var targetDensity = at.densityScalar;

    if (slowUser) {
      targetPace -= 0.1;
      targetHook -= 0.1;
      targetDensity += 0.1;
    } else if (fastUser) {
      targetPace += 0.1;
      targetHook += 0.1;
      targetDensity -= 0.1;
    }

    // TIER 1 — boredom signals feed next scene's pacing.
    // sceneIdleMs > 60s → user took a long time to interact with this scene.
    //   In Active mode: slight softening (they're already being pushed, don't over-push).
    //   In Mindful mode: sharpen (inferred-Mindful readers who are bored benefit from a nudge).
    // scrolledWithoutClicking → the anchor didn't land. Reduce insertion rate.
    var sceneIdle = signals.sceneIdleMs || 0;
    if (sceneIdle > 60000) {
      if (state.storyMode === 'literary') {
        targetHook += 0.15;
        targetPace += 0.15;
        targetDensity -= 0.1;
      } else {
        targetHook -= 0.05;
        targetPace -= 0.05;
      }
    }
    if (signals.scrolledWithoutClicking) {
      // Anchor visible but ignored → compress next scene, reduce anchor pressure
      targetDensity -= 0.1;
      targetHook -= 0.05;
    }
    if (signals.nudgeFired && signals.nudgeAcceptedClick) {
      // Nudge worked — user was bored and the pulse revived them. Keep pushing.
      targetHook += 0.05;
    }

    // Cross-scene low-agency silence → smooth pacing ramp (no snap shifts).
    // Gradual softening scales with the silence count, capped to avoid
    // runaway deceleration. Input quality is already weighted upstream
    // (rich input resets the counter).
    //   c=0: no target (null); scalars unchanged by silence
    //   c=1: scene target ~620w, density *0.95, hook -0.05, pace -0.03
    //   c=2: scene target ~740w, density *0.90, hook -0.10, pace -0.06
    //   c=3: scene target ~850w, density *0.85, hook -0.15, pace -0.09
    //   c≥4: clamped at c=4 (density *0.80, length 850)
    var silenceCount = state._crossSceneSilenceCount || 0;
    if (silenceCount >= 1) {
      var c = Math.min(silenceCount, 4);
      var densityFactor = Math.max(0.8, 1 - (0.05 * c));
      targetDensity *= densityFactor;
      targetHook -= 0.05 * c;
      targetPace -= 0.03 * c;
      var sceneTarget = 500 + Math.min(350, c * 120);
      state._lowAgencyLengthTarget = { min: sceneTarget, max: sceneTarget + 100 };
    } else {
      state._lowAgencyLengthTarget = null;
    }

    // Scene 2 _interactionBias (continuous, set in threshold classifier)
    // modulates adaptation confidence. Negative bias (withdraw-seeded)
    // softens faster on silence; positive bias (lean-in-seeded) resists
    // softening until silence count accumulates.
    var bias = state._interactionBias || 0;
    if (bias < 0 && silenceCount >= 1) {
      targetHook -= 0.05 * Math.abs(bias);
      targetDensity -= 0.05 * Math.abs(bias);
    } else if (bias > 0 && silenceCount < 2) {
      // Hold the line — transient silence doesn't back us off
      targetHook = Math.max(targetHook, 0.9 + (bias * 0.1));
    }

    // Damped smoothing: 70% old + 30% target
    at.paceScalar = _clampTuning(at.paceScalar * 0.7 + targetPace * 0.3);
    at.hookScalar = _clampTuning(at.hookScalar * 0.7 + targetHook * 0.3);
    at.densityScalar = _clampTuning(at.densityScalar * 0.7 + targetDensity * 0.3);

    // Tone preservation: literary never exceeds participatory hook aggression
    if (state.storyMode === 'literary') {
      at.hookScalar = Math.min(at.hookScalar, 0.8);
    }
    // Participatory never drops below minimum interactivity
    if (state.storyMode !== 'literary') {
      at.hookScalar = Math.max(at.hookScalar, 0.8);
      at.paceScalar = Math.max(at.paceScalar, 0.8);
    }

    _logAdaptiveTuning();
  }

  /**
   * Debug logging for adaptive tuning.
   */
  function _logAdaptiveTuning() {
    var at = state._adaptiveTuning;
    console.log('[ADAPTIVE TUNING]', {
      paceScalar: at.paceScalar.toFixed(2),
      hookScalar: at.hookScalar.toFixed(2),
      densityScalar: at.densityScalar.toFixed(2),
      scene: state.turnCount || 0,
      storyMode: state.storyMode || 'participatory',
      avgDelay: (state._avgInteractionDelayMs || 0).toFixed(0) + 'ms'
    });
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // ADAPTIVE SCENE LENGTH — commitment-based length targeting
  // ═══════════════════════════════════════════════════════════════════════════

  function _computeCommitmentScore() {
    var signals = state._engagementSignals || {};
    var score = 0;
    if (signals.microExprInteracted) score += 1;
    if (signals.madeChoice) score += 1;
    if (signals.timeToFirstInteractionMs > 0 && signals.timeToFirstInteractionMs < 10000) score += 1;
    if (signals.completedPreviousScene) score += 1;
    return Math.min(score, 3);
  }

  function _resolveTargetSceneLength() {
    var score = _computeCommitmentScore();
    var range;
    // Key the elevated length band on literary RENDER, not just the 'literary'
    // gameplay mode (Roman 2026-05-29). A participatory story rendered as literary
    // prose wants rich scenes; keying on storyMode alone starved it to the short
    // participatory band (400–540), so the model's natural ~700-word literary scene
    // tripped scene_too_long / late-first-choice every turn. Render mode is the
    // right axis (same fix already applied to the Scene-1 length band). CG/graphic
    // render is excluded (it has its own screenplay length system).
    var _isLit = state.storyMode === 'literary' ||
                 state.renderMode === 'literary' ||
                 state.storyModality === 'literary';

    // Literary mode: elevated base ranges (800–1000 target)
    if (_isLit) {
      if (score <= 1) range = { minWords: 700, maxWords: 900 };
      else if (score === 2) range = { minWords: 750, maxWords: 950 };
      else range = { minWords: 800, maxWords: 1000 };
    } else {
      if (score <= 1) range = { minWords: 400, maxWords: 600 };
      else if (score === 2) range = { minWords: 500, maxWords: 700 };
      else range = { minWords: 600, maxWords: 800 };
    }

    // Smoothing: prevent abrupt jumps (max 150 word shift per scene)
    var prev = state._prevTargetLengthRange;
    if (prev) {
      if (range.minWords - prev.minWords > 150) range.minWords = prev.minWords + 150;
      if (prev.minWords - range.minWords > 150) range.minWords = prev.minWords - 150;
      if (range.maxWords - prev.maxWords > 150) range.maxWords = prev.maxWords + 150;
      if (prev.maxWords - range.maxWords > 150) range.maxWords = prev.maxWords - 150;
    }

    // ST-based length bias: high-intensity STs bias toward upper range, setup STs toward lower
    // Literary mode: reduce bias magnitude (slower progression, more dwell time in ST2/ST3)
    var _st = state.storyturn || 'ST1';
    var _biasFactor = _isLit ? 0.15 : 0.3;
    if (_st === 'ST3' || _st === 'ST4') {
      var _stBias = Math.round((range.maxWords - range.minWords) * _biasFactor);
      range.minWords += _stBias;
    } else if (_st === 'ST1' || _st === 'ST2') {
      var _stBiasLow = Math.round((range.maxWords - range.minWords) * _biasFactor);
      range.maxWords -= _stBiasLow;
    }

    // Telemetry-driven length override: if drop-off rate high, compress
    // Literary mode respects override but with higher floor
    if (state._adaptiveLengthOverride && state._adaptiveLengthOverride.active && state._adaptiveLengthOverride.remainingScenes > 0) {
      range = _isLit ? { minWords: 600, maxWords: 800 } : { minWords: 400, maxWords: 550 };
      state._adaptiveLengthOverride.remainingScenes--;
      if (state._adaptiveLengthOverride.remainingScenes <= 0) state._adaptiveLengthOverride.active = false;
      console.log('[ADAPTIVE LENGTH] Override active — compressed to ' + range.minWords + '-' + range.maxWords + ', remaining:', state._adaptiveLengthOverride.remainingScenes);
    }

    // Reset on disengage (literary mode has higher floor)
    var signals = state._engagementSignals || {};
    if (!signals.microExprInteracted && (signals.timeToFirstInteractionMs || 0) > 15000) {
      range = _isLit ? { minWords: 650, maxWords: 850 } : { minWords: 400, maxWords: 600 };
    }

    // Apply adaptive tuning density scalar
    var _densityS = (state._adaptiveTuning && state._adaptiveTuning.densityScalar) || 1.0;
    if (_densityS !== 1.0) {
      range = {
        minWords: Math.round(range.minWords * _densityS),
        maxWords: Math.round(range.maxWords * _densityS)
      };
    }

    state._prevTargetLengthRange = range;
    state._targetSceneLengthRange = range;

    console.log('[ADAPTIVE LENGTH]', {
      sceneIndex: state.turnCount || 0,
      commitmentScore: score,
      storyMode: state.storyMode || 'participatory',
      densityScalar: _densityS.toFixed(2),
      targetRange: range.minWords + '-' + range.maxWords
    });

    return range;
  }

  function _buildAdaptiveLengthDirective() {
    var range = state._targetSceneLengthRange;
    if (!range) return '';

    // Adaptive tuning: hookScalar and paceScalar modulation
    var at = state._adaptiveTuning || {};
    var hookMod = '';
    var paceMod = '';
    if (at.hookScalar != null && at.hookScalar < 0.9) {
      hookMod = ' Reduce overt hook phrasing. Favor gradual tension over sharp spikes.';
    } else if (at.hookScalar != null && at.hookScalar > 1.1) {
      hookMod = ' Increase immediacy and sharpness of tension hooks.';
    }
    if (at.paceScalar != null && at.paceScalar < 0.9) {
      paceMod = ' Allow slower progression, extended beats, and reflective pacing.';
    } else if (at.paceScalar != null && at.paceScalar > 1.1) {
      paceMod = ' Tighten pacing, accelerate progression, reduce dwell time.';
    }

    if (state.storyMode === 'literary') {
      return '\nSCENE LENGTH GUIDANCE: Target ' + range.minWords + '-' + range.maxWords + ' words. ' +
        'Allow the scene to breathe \u2014 establish atmosphere and internal states before introducing conflict. ' +
        'A meaningful decision or turning point should emerge organically, not forced early. ' +
        'Favor reflective choices and softer forks over binary high-stakes demands. ' +
        'Decisions may have delayed consequences rather than immediate ones.' +
        hookMod + paceMod + '\n';
    }
    return '\nSCENE LENGTH GUIDANCE: Target ' + range.minWords + '-' + range.maxWords + ' words. ' +
      'Begin with immediate tension. Introduce a micro-expression moment within first 150 words. ' +
      'Ensure a meaningful player decision occurs by word 500 or earlier. ' +
      'Additional depth may be added AFTER the decision.' +
      hookMod + paceMod + '\n';
  }

  // P7-P8: KPI tracking (log only, no enforcement)
  function _logEngagementKPIs() {
    var metrics = state._engagementMetrics || { totalShown: 0, totalInteracted: 0, totalAutoResolved: 0, totalTimeMs: 0, interactionCount: 0, choiceReached: 0, dropOffBeforeChoice: 0, totalScenes: 0 };
    state._engagementMetrics = metrics;
    metrics.totalScenes++;

    var signals = state._engagementSignals || {};
    if (signals.microExprInteracted) { metrics.totalInteracted++; metrics.interactionCount++; }
    if (signals.microExprShown) metrics.totalShown++;
    if (signals.autoResolved) metrics.totalAutoResolved++;
    if (signals.timeToFirstInteractionMs > 0) metrics.totalTimeMs += signals.timeToFirstInteractionMs;
    if (signals.madeChoice) metrics.choiceReached++;
    if (signals.dropOffBeforeChoice) metrics.dropOffBeforeChoice++;

    var interactionRate = metrics.totalShown > 0 ? (metrics.totalInteracted / metrics.totalShown) : 0;
    var avgTimeMs = metrics.interactionCount > 0 ? (metrics.totalTimeMs / metrics.interactionCount) : 0;
    var dropOffRate = metrics.totalScenes > 0 ? (metrics.dropOffBeforeChoice / metrics.totalScenes) : 0;
    var choiceRate = metrics.totalScenes > 0 ? (metrics.choiceReached / metrics.totalScenes) : 0;

    console.log('[ENGAGEMENT KPI]', {
      microExprInteractionRate: (interactionRate * 100).toFixed(0) + '%',
      avgTimeToFirstInteraction: (avgTimeMs / 1000).toFixed(1) + 's',
      dropOffBeforeChoiceRate: (dropOffRate * 100).toFixed(0) + '%',
      choiceCompletionRate: (choiceRate * 100).toFixed(0) + '%',
      totalScenes: metrics.totalScenes
    });

    // Reset signals for next scene
    state._engagementSignals = { completedPreviousScene: true };
  }

  // ═══════════════════════════════════════════════════════════════════════
  // ENGAGEMENT TIER 1 — per-scene boredom/absorption telemetry.
  // Captures three signals that feed into _updateAdaptiveTuning() and the
  // Mindful→Active mode-switch offer:
  //   sceneMountTimeMs         — when the scene finished rendering
  //   sceneFirstInputTimeMs    — when the user first interacted with the story
  //   scrolledWithoutClicking  — they reached the bottom without tapping any
  //                              micro-expression anchor present in the scene
  // ═══════════════════════════════════════════════════════════════════════

  var _activeAnchorNudgeTimer = null;      // Tier 2 — Active-mode idle pulse timer
  var _engagementListenersBound = false;   // Guard — attach global listeners once

  function _bindEngagementListeners() {
    if (_engagementListenersBound) return;
    _engagementListenersBound = true;

    var storyText = document.getElementById('storyText');
    var storyContent = document.getElementById('storyContent');

    // First interaction capture — click, keypress, mousemove over story content.
    // Scroll is handled separately (we want to distinguish "scrolled past without
    // clicking" from "clicked the anchor").
    function markFirstInput() {
      var sig = state._engagementSignals || (state._engagementSignals = {});
      if (!sig.sceneFirstInputTimeMs && sig.sceneMountTimeMs) {
        sig.sceneFirstInputTimeMs = Date.now();
      }
      _clearActiveAnchorNudge();
    }
    (storyContent || document).addEventListener('click', markFirstInput, true);
    document.addEventListener('keydown', markFirstInput, true);

    // Scroll handler — detect reached-bottom-without-click.
    function onScroll() {
      var sig = state._engagementSignals || (state._engagementSignals = {});
      if (!sig.sceneMountTimeMs) return;
      if (sig.scrolledWithoutClicking) return; // already recorded
      if (sig.microExprInteracted) return;      // already clicked, no longer a "miss"
      // Reached bottom (within 100px)?
      var remaining = document.documentElement.scrollHeight
                      - window.innerHeight
                      - window.scrollY;
      if (remaining > 100) return;
      // Only record as "missed" if an anchor actually existed in this scene.
      var anchor = document.querySelector('#storyText .microexpr-anchor');
      if (!anchor) return;
      sig.scrolledWithoutClicking = true;
      console.log('[ENGAGEMENT] scrolled past anchor without interaction');
    }
    window.addEventListener('scroll', onScroll, { passive: true });
  }

  function _clearActiveAnchorNudge() {
    if (_activeAnchorNudgeTimer) {
      clearTimeout(_activeAnchorNudgeTimer);
      _activeAnchorNudgeTimer = null;
    }
  }

  // ═══════════════════════════════════════════════════════════════════════
  // LOW-AGENCY CLASSIFIER — unified model for handling all user inputs.
  // Every turn is a "response," but the response can be low-agency (silent,
  // minimal, deflecting) or engaged (substantive action/dialogue).
  // Feeds proximitySignal, desireProfile, and cross-scene silence counter.
  // ═══════════════════════════════════════════════════════════════════════
  // Short high-agency commands — exact-match escapes the ≤3-char and
  // substring-deflection checks. Players giving one-word orders ("no",
  // "go", "stop") or affirmations ("yes", "nod", "ok") are directing the
  // protagonist, not withholding.
  var COMMAND_VERBS = [
    'no', 'go', 'look', 'wait', 'stop', 'come', 'leave', 'stay', 'run', 'hide',
    'yes', 'nod', 'ok', 'okay'
  ];
  function _isCommandVerb(t) {
    return COMMAND_VERBS.indexOf(t) !== -1;
  }

  // Gestures that indicate passive/deflective response — flagged regardless
  // of surrounding text length. Unlike the deflection-phrase check below,
  // this fires on any input length (no < 40 cap) so "*shrugs*" in longer
  // RP-style input still lands correctly.
  var LOW_AGENCY_GESTURES = ['shrug', 'sigh', 'hesitate', 'pause'];

  function classifyAgencyLevel(actText, diaText) {
    var act = (actText || '').trim();
    var dia = (diaText || '').trim();
    var combined = (act + ' ' + dia).trim();

    // Empty input = low agency
    if (!combined) return 'low';
    var lower = combined.toLowerCase();

    // Explicit silence markers
    if (lower === '...' || lower === '…' || lower === 'silence') return 'low';

    // Exact command verb — high-agency despite short length; escapes both
    // the length and deflection checks below.
    if (_isCommandVerb(lower)) return 'engaged';

    // Short non-command input = low agency
    if (combined.length <= 3) return 'low';

    // Passive gestures — any input containing these reads as deflection
    // regardless of surrounding length. "I shrug and walk away" is low-agency;
    // so is "*sighs, says nothing*".
    for (var g = 0; g < LOW_AGENCY_GESTURES.length; g++) {
      if (lower.indexOf(LOW_AGENCY_GESTURES[g]) !== -1) return 'low';
    }

    // Weak / deflecting / hesitation signals in short-ish input
    var lowAgencyPhrases = [
      "don't know", "dont know", "not sure", "idk",
      "say nothing", "stay quiet", "stay silent", "wait", "ignore",
      "do nothing", "nothing", "hold back", "no response",
      "no answer", "nothing to say"
    ];
    for (var i = 0; i < lowAgencyPhrases.length; i++) {
      if (lower.indexOf(lowAgencyPhrases[i]) !== -1 && combined.length < 40) {
        // Short phrase containing a deflection keyword = low agency.
        // Longer inputs that happen to contain "wait" in a substantive sentence
        // ("I wait for him to meet my gaze, then speak") are engaged.
        return 'low';
      }
    }

    return 'engaged';
  }
  window.classifyAgencyLevel = classifyAgencyLevel;

  // Pattern pool for low-agency scene continuation. Model rotates through
  // these to keep repeated-silence handling varied.
  var LOW_AGENCY_PATTERNS = [
    'hesitation',
    'deflection',
    'delayed response',
    'interruption by another character',
    'silent observation',
    'attention shift'
  ];
  function _pickLowAgencyPattern() {
    var last = state._lastLowAgencyPattern;
    var available = LOW_AGENCY_PATTERNS.filter(function(p) { return p !== last; });
    var pick = available[Math.floor(Math.random() * available.length)];
    state._lastLowAgencyPattern = pick;
    return pick;
  }
  window._pickLowAgencyPattern = _pickLowAgencyPattern;

  // Called from triggerPostRenderHooks() each time a scene finishes rendering.
  function _onSceneMountEngagementHook() {
    _bindEngagementListeners();
    _clearActiveAnchorNudge();

    var sig = state._engagementSignals || (state._engagementSignals = {});
    sig.sceneMountTimeMs = Date.now();
    sig.sceneFirstInputTimeMs = null;
    sig.scrolledWithoutClicking = false;
    sig.nudgeFired = false;
    sig.nudgeAcceptedClick = false;

    // TIER 2 — Active-mode anchor idle pulse.
    // Only fires when: storyMode is Active, a micro-expression anchor exists in
    // this scene, user hasn't yet interacted, and 60s elapse without any input.
    // Single gentle 2s breath cycle; stops on any interaction.
    if (state.storyMode !== 'literary') {
      _activeAnchorNudgeTimer = setTimeout(function() {
        var s = state._engagementSignals || {};
        if (s.sceneFirstInputTimeMs || s.nudgeFired) return;
        var anchor = document.querySelector('#storyText .microexpr-anchor');
        if (!anchor) return;
        anchor.classList.add('idle-nudge');
        s.nudgeFired = true;
        console.log('[ENGAGEMENT] anchor idle-nudge fired (Active mode, 60s elapsed)');
        // Remove the animation class after it completes so it can be re-applied
        // if we ever want to (we don't — fire-once per scene).
        setTimeout(function() {
          anchor.classList.remove('idle-nudge');
        }, 2500);
      }, 60000);
    }
  }
  window._onSceneMountEngagementHook = _onSceneMountEngagementHook;

  // Called when user submits a turn — captures scene dwell, evaluates the
  // Mindful→Active mode-switch offer, and logs telemetry.
  function _captureSceneExitEngagement() {
    var sig = state._engagementSignals || {};
    if (!sig.sceneMountTimeMs) return;
    var now = Date.now();
    sig.sceneDwellMs = now - sig.sceneMountTimeMs;
    sig.sceneIdleMs = sig.sceneFirstInputTimeMs
        ? sig.sceneFirstInputTimeMs - sig.sceneMountTimeMs
        : sig.sceneDwellMs; // never interacted

    console.log('[ENGAGEMENT:SCENE]', {
      dwellMs: sig.sceneDwellMs,
      idleMs: sig.sceneIdleMs,
      scrolledWithoutClicking: !!sig.scrolledWithoutClicking,
      nudgeFired: !!sig.nudgeFired,
      mode: state.storyMode || 'participatory'
    });

    // Evaluate mode-switch offer first; if it shows, skip the lighter nudge
    // this scene so the reader isn't double-prompted.
    var offered = _maybeOfferModeSwitch(sig);
    if (!offered) _maybeShowEngagementNudge(sig);
  }
  window._captureSceneExitEngagement = _captureSceneExitEngagement;

  // ═══════════════════════════════════════════════════════════════════════
  // PACE-ADJUSTMENT OFFER — concierge prompt to adjust pacing under the
  // unified low-agency model. Fires on cross-scene silence (not Mindful
  // inference, since there's no toggle to flip). Offers natural-language
  // commands: "faster" / "slower" / "more action" / "less interruption".
  //   First offer: _crossSceneSilenceCount >= 3 AND scene >= 3.
  //   Re-offer: allowed once, ≥ 10 scenes after a decline.
  //   Hard cap: 2 declines. Accept applies scalar changes via NL matcher.
  //   Returns true if an offer was shown this call.
  // ═══════════════════════════════════════════════════════════════════════
  function _maybeOfferModeSwitch(sig) {
    if ((state.turnCount || 0) < 3) return false;
    if ((state._modeSwitchDeclineCount || 0) >= 2) return false;

    // Cooldown: if previously offered, require ≥10 scenes before re-offer
    var lastOffered = state._modeSwitchLastOfferedScene;
    var currentScene = state.turnCount || 0;
    if (lastOffered != null && (currentScene - lastOffered) < 10) return false;

    // Trigger: cross-scene low-agency silence accumulated to 3+.
    // (Input quality already weighted — rich-input slow readers don't count.)
    var silenceCount = state._crossSceneSilenceCount || 0;
    if (silenceCount < 3) return false;

    var isReOffer = (lastOffered != null);
    state._modeSwitchLastOfferedScene = currentScene;
    _showModeSwitchOffer(isReOffer);
    return true;
  }

  function _showModeSwitchOffer(isReOffer) {
    var overlay = document.getElementById('modeSwitchOfferOverlay');
    if (!overlay) return;

    // Alternate phrasing for re-offer so it doesn't read as nagging repetition.
    var lineEl = overlay.querySelector('.mode-switch-offer-line');
    var hintEl = overlay.querySelector('.mode-switch-offer-hint');
    var acceptBtn = overlay.querySelector('.mode-switch-offer-accept');
    var declineBtn = overlay.querySelector('.mode-switch-offer-decline');

    if (isReOffer) {
      if (lineEl) lineEl.textContent = 'Still feels unhurried? The pace is yours to shift.';
      if (hintEl) hintEl.textContent = 'Tell me "faster" or "slower" — or dismiss. Not asking twice after this.';
      if (acceptBtn) acceptBtn.textContent = 'Sharpen it';
      if (declineBtn) declineBtn.textContent = 'Stay as is';
    } else {
      if (lineEl) lineEl.textContent = 'Would a different pace serve you?';
      if (hintEl) hintEl.textContent = 'You can tell me "faster," "slower," "more action," or "less interruption" — any time.';
      if (acceptBtn) acceptBtn.textContent = 'Sharpen the pace';
      if (declineBtn) declineBtn.textContent = 'Stay with it';
    }

    overlay.classList.remove('hidden');
    overlay.classList.add('visible');
    console.log('[PACE-OFFER]', isReOffer ? 're-offer shown' : 'initial offer shown',
                '(scene', state.turnCount || 0, '— crossSceneSilenceCount=' + (state._crossSceneSilenceCount || 0) + ')');
  }

  // ═══════════════════════════════════════════════════════════════════════
  // ENGAGEMENT NUDGE — "shake things up" suggestion when the reader seems
  // listless but the mode-switch offer either (a) already declined and on
  // cooldown, (b) not applicable (Active mode), or (c) would be nagging.
  // Cycles through real in-app mechanics so the same prompt isn't repeated.
  // NOTE: does NOT include promo copy (no "get one free this month"). If a
  // monthly promo exists, add the copy to a nudge's `line` field.
  // ═══════════════════════════════════════════════════════════════════════
  var ENGAGEMENT_NUDGES = [
    {
      id: 'tempt_fate',
      // Dynamic copy: checks the Fortune's Favor / Pioneer Bonus systems so
      // we reference real user state. Priorities (first match wins):
      //   1. User has a free charge right now (story-scoped, universal, or Pioneer)
      //   2. User is in a monthly-spotlight flavor but hasn't hit scene 5 yet
      //   3. User is NOT in a spotlight flavor — mention the monthly promo
      //   4. Fallback generic Tempt Fate suggestion
      buildLine: function() {
        var ff = state.fortuneFavor;
        var monthlyKey = (typeof MONTHLY_FORTUNE_FAVOR !== 'undefined') ? MONTHLY_FORTUNE_FAVOR.monthKey : null;
        var spotlightFlavors = (typeof MONTHLY_FORTUNE_FAVOR !== 'undefined') ? MONTHLY_FORTUNE_FAVOR.spotlightFlavors : [];
        var currentFlavor = state.picks && state.picks.worldSubtype;

        // (1) Unused free charge in any bucket — tell them directly
        var hasStoryCharge = ff && ff.unlocked && !ff.used && ff.monthKey === monthlyKey;
        var hasUniversal = (state.bonus_tempt_charges || 0) > 0;
        var hasPioneer = (typeof hasPioneerTemptFate === 'function') && hasPioneerTemptFate();
        if (hasStoryCharge || hasUniversal || hasPioneer) {
          return 'You have a free Tempt Fate waiting. It pushes harder than a normal turn — and the story remembers the push.';
        }

        // (2) In a spotlight flavor, pre-scene-5 — promise the earned grant
        var inSpotlight = currentFlavor && spotlightFlavors && spotlightFlavors.indexOf(currentFlavor) !== -1;
        var sceneCount = state.turnCount || 0;
        if (inSpotlight && sceneCount < 5) {
          return 'Reach scene 5 in this world and one Tempt Fate becomes free — story-scoped. It pushes harder than a normal turn and the story remembers.';
        }

        // (3) Not in spotlight — mention the monthly promo but don't push for restart
        // Build a human list of spotlight flavor names (prefer labels if we have them)
        var flavorLabels = { glass_house: 'Glass House', prehistoric: 'Prehistoric', simulation: 'Enigma-S' };
        var spotlightNames = spotlightFlavors
          .map(function(f) { return flavorLabels[f] || f; })
          .filter(function(n) { return n; });
        if (spotlightNames.length > 0 && !inSpotlight) {
          var listStr = spotlightNames.length === 1
            ? spotlightNames[0]
            : (spotlightNames.slice(0, -1).join(', ') + ' or ' + spotlightNames[spotlightNames.length - 1]);
          return 'Try Tempt Fate. It pushes harder than a normal turn — and the story remembers. (This month, starting a story in ' + listStr + ' earns a free one at scene 5.)';
        }

        // (4) Fallback
        return 'Try Tempt Fate. It pushes harder than a normal turn — and the story remembers the push.';
      },
      eligible: function() {
        // Two paths to eligibility:
        //   a) They have a free charge waiting (always worth surfacing)
        //   b) They have enough fortunes to spend on Tempt Fate (≥ 5)
        var ff = state.fortuneFavor;
        var monthlyKey = (typeof MONTHLY_FORTUNE_FAVOR !== 'undefined') ? MONTHLY_FORTUNE_FAVOR.monthKey : null;
        var hasStoryCharge = ff && ff.unlocked && !ff.used && ff.monthKey === monthlyKey;
        var hasUniversal = (state.bonus_tempt_charges || 0) > 0;
        var hasPioneer = (typeof hasPioneerTemptFate === 'function') && hasPioneerTemptFate();
        if (hasStoryCharge || hasUniversal || hasPioneer) return true;
        var f = (state.fortunes || 0);
        return f >= 5;
      }
    },
    {
      id: 'visualize',
      line: 'Pull up a vision. Seeing the scene sometimes changes how you answer it.',
      eligible: function() {
        // Vision orb is available from world stage onward
        return (state.turnCount || 0) >= 1;
      }
    },
    {
      id: 'petition_fate',
      line: 'Petition Fate. A lighter touch — let the next turn lean toward what you want.',
      eligible: function() {
        var f = (state.fortunes || 0);
        return f >= 2;
      }
    },
    {
      id: 'say_and_do',
      line: 'Try writing both — what you say AND what you do this turn. The story reads both lines.',
      eligible: function() { return true; }
    }
  ];

  function _pickNextEngagementNudge() {
    var shown = state._engagementNudgeShownIds || [];
    var eligible = ENGAGEMENT_NUDGES.filter(function(n) {
      return shown.indexOf(n.id) === -1 && (!n.eligible || n.eligible());
    });
    if (eligible.length === 0) return null;
    // Cycle deterministically — first eligible wins
    return eligible[0];
  }

  function _maybeShowEngagementNudge(sig) {
    if ((state.turnCount || 0) < 3) return;                  // need a few scenes of signal
    if ((state._engagementNudgeShownIds || []).length >= 3) return; // cap at 3 total

    // Cooldown — ≥ 5 scenes between nudges
    var last = state._engagementNudgeLastShownScene;
    var currentScene = state.turnCount || 0;
    if (last != null && (currentScene - last) < 5) return;

    // Same boredom signals that trigger the mode offer
    var bored = (sig.sceneIdleMs && sig.sceneIdleMs > 60000)
             || (sig.scrolledWithoutClicking === true);
    if (!bored) return;

    var nudge = _pickNextEngagementNudge();
    if (!nudge) return;

    state._engagementNudgeLastShownScene = currentScene;
    state._engagementNudgeShownIds = (state._engagementNudgeShownIds || []).concat([nudge.id]);
    _showEngagementNudge(nudge);
  }

  function _showEngagementNudge(nudge) {
    var overlay = document.getElementById('engagementNudgeOverlay');
    if (!overlay) return;
    var lineEl = overlay.querySelector('.engagement-nudge-line');
    // Prefer dynamic buildLine() (e.g. tempt_fate reads Fortune's Favor state)
    // and fall back to the static line string for simpler nudges.
    var text = (typeof nudge.buildLine === 'function') ? nudge.buildLine() : nudge.line;
    if (lineEl) lineEl.textContent = text;
    overlay.dataset.nudgeId = nudge.id;
    overlay.classList.remove('hidden');
    overlay.classList.add('visible');
    console.log('[ENGAGEMENT:NUDGE] shown (' + nudge.id + ') at scene', state.turnCount || 0, '—', text);
  }

  window._dismissEngagementNudge = function() {
    var overlay = document.getElementById('engagementNudgeOverlay');
    if (!overlay) return;
    var nudgeId = overlay.dataset.nudgeId || '(unknown)';
    overlay.classList.remove('visible');
    overlay.classList.add('hidden');
    console.log('[ENGAGEMENT:NUDGE] dismissed (' + nudgeId + ')');
  };

  function _hideModeSwitchOffer() {
    var overlay = document.getElementById('modeSwitchOfferOverlay');
    if (!overlay) return;
    overlay.classList.remove('visible');
    overlay.classList.add('hidden');
  }

  // Accept — apply pace-sharpen scalars (equivalent to saying "faster" via NL).
  // Under the unified model there's no mode flip — just scalar adjustment.
  window._acceptModeSwitchToActive = function() {
    if (typeof window._applyPaceIntent === 'function') {
      window._applyPaceIntent('faster', { source: 'offer_button' });
    }
    _hideModeSwitchOffer();
    if (window.playUISound) window.playUISound('card_tap');
  };

  window._declineModeSwitch = function() {
    state._modeSwitchDeclineCount = (state._modeSwitchDeclineCount || 0) + 1;
    console.log('[PACE-OFFER] declined (decline count:',
                state._modeSwitchDeclineCount + '/2)');
    _hideModeSwitchOffer();
  };

  // ═══════════════════════════════════════════════════════════════════════
  // PACE INTENT SYSTEM — shared by concierge NL and pace-offer button.
  //   _detectPaceIntent(text) → 'faster' | 'slower' | null
  //   _applyPaceIntent(intent, opts) → adjusts adaptive scalars immediately
  // Concierge matches natural phrasings: "speed it up", "more action",
  // "this is slow", "slow down", "calm", "let it breathe", etc.
  // ═══════════════════════════════════════════════════════════════════════
  var PACE_INTENTS = {
    faster: [
      'faster', 'speed up', 'speed it up', 'more action', 'move quicker',
      'this is slow', 'too slow', 'pick it up', 'sharpen', 'sharper',
      'i\'m bored', 'im bored', 'this is boring', 'energize',
      'more interruption', 'more choice', 'more choices', 'quicker'
    ],
    slower: [
      'slow down', 'slower', 'too fast', 'calm down', 'calm',
      'let it breathe', 'breathe', 'more detail', 'slow it down',
      'more atmosphere', 'less interruption', 'fewer choices',
      'less action', 'overwhelming', 'overwhelmed', 'take it slow',
      'ease up', 'softer'
    ]
  };

  function _detectPaceIntent(text) {
    if (!text) return null;
    var t = text.toLowerCase().trim();
    // Check 'faster' before 'slower' — phrases like "don't slow down" are
    // edge cases we're not solving; exact-contains is intentional.
    for (var i = 0; i < PACE_INTENTS.faster.length; i++) {
      if (t.indexOf(PACE_INTENTS.faster[i]) !== -1) return 'faster';
    }
    for (var j = 0; j < PACE_INTENTS.slower.length; j++) {
      if (t.indexOf(PACE_INTENTS.slower[j]) !== -1) return 'slower';
    }
    return null;
  }
  window._detectPaceIntent = _detectPaceIntent;

  function _applyPaceIntent(intent, opts) {
    opts = opts || {};
    var at = state._adaptiveTuning || (state._adaptiveTuning = {
      paceScalar: 1.0, hookScalar: 1.0, densityScalar: 1.0, lastAdjustmentScene: 0
    });

    if (intent === 'faster') {
      at.hookScalar = Math.max(at.hookScalar || 1.0, 0.95) + 0.15;
      at.paceScalar = Math.max(at.paceScalar || 1.0, 1.05) + 0.1;
      at.densityScalar = Math.min(at.densityScalar || 1.0, 1.0) + 0.05;
      state._crossSceneSilenceCount = 0;  // user spoke — reset silence
      console.log('[PACE-INTENT] applied: faster (source: ' + (opts.source || 'unknown') + ')', {
        hook: at.hookScalar.toFixed(2),
        pace: at.paceScalar.toFixed(2),
        density: at.densityScalar.toFixed(2)
      });
      return 'The pace will sharpen. You\'ll feel it next scene.';
    }
    if (intent === 'slower') {
      at.hookScalar = Math.min(at.hookScalar || 1.0, 0.85) - 0.1;
      at.paceScalar = Math.min(at.paceScalar || 1.0, 0.95) - 0.1;
      at.densityScalar = Math.max(at.densityScalar || 1.0, 1.05) + 0.1;
      state._lowAgencyLengthTarget = { min: 700, max: 850 };
      console.log('[PACE-INTENT] applied: slower (source: ' + (opts.source || 'unknown') + ')', {
        hook: at.hookScalar.toFixed(2),
        pace: at.paceScalar.toFixed(2),
        density: at.densityScalar.toFixed(2)
      });
      return 'We\'ll take more time with this. Let it breathe.';
    }
    return null;
  }
  window._applyPaceIntent = _applyPaceIntent;

  // P1: Event-based first choice detection — called when Fate Cards mount or say/do activates
  function _registerFirstChoicePosition(sceneText) {
    if (state._firstChoiceRenderWordIndex != null) return; // already set
    var el = document.querySelector('.fate-card-display, .say-do-input, #fateCardContainer');
    if (!el) return;
    // Estimate word position from DOM: count words in #storyContent before this element
    var storyEl = document.getElementById('storyContent');
    if (!storyEl) return;
    var textBefore = '';
    var walker = document.createTreeWalker(storyEl, NodeFilter.SHOW_TEXT, null, false);
    var node;
    while ((node = walker.nextNode())) {
      if (el.contains(node) || node === el) break;
      textBefore += node.textContent;
    }
    state._firstChoiceRenderWordIndex = textBefore.split(/\s+/).filter(Boolean).length;
    console.log('[PACING] First choice detected at word index:', state._firstChoiceRenderWordIndex);
  }
  window._registerFirstChoicePosition = _registerFirstChoicePosition;

  // Selection handler — updates profile, resolves tokens/injects response, collapses widget
  window._selectMicroExpr = function(exprIdx, optIdx) {
    var injections = state._currentMicroExprInjections || [];
    if (!injections[exprIdx]) return;
    var inj = injections[exprIdx];
    // Anchor is now spent — drop its link affordance (manual path shows the
    // player's chosen reaction below; the anchor itself stops looking clickable).
    if (typeof _deLinkMicroExprAnchor === 'function') _deLinkMicroExprAnchor(exprIdx);
    var vector = inj.expressionVectors[optIdx] || {};
    var optText = inj.options[optIdx] || '';
    var bankKey = (inj.bankKeys && inj.bankKeys[optIdx]) || '';
    var reactionMap = (inj.reactionMaps && inj.reactionMaps[optIdx]) || {};
    var interactionTime = inj._showTime ? Date.now() - inj._showTime : -1;

    // Update player expression profile
    state.playerExpressionProfile = state.playerExpressionProfile || {
      approach: 0, avoidance: 0, warmth: 0, dominance: 0, yielding: 0,
      playfulness: 0, seriousness: 0
    };
    for (var vk in vector) {
      if (vector.hasOwnProperty(vk)) {
        state.playerExpressionProfile[vk] = (state.playerExpressionProfile[vk] || 0) + vector[vk];
      }
    }

    // Track expression history for echo system (P5)
    state._microExprHistory = state._microExprHistory || [];
    state._microExprHistory.push({ option: optText, bankKey: bankKey, scene: state.turnCount || 0 });
    if (state._microExprHistory.length > 10) state._microExprHistory.shift();
    // P5: Store last expression for scene-to-scene continuity
    state._lastMicroExpression = { label: optText, bankKey: bankKey, vector: vector };
    // Reset skip streak on manual interaction, track fast-tap + fatigue
    state._microExprSkipStreak = 0;
    if (interactionTime > 0 && interactionTime < 2000) {
      state._microExprFastTapStreak = (state._microExprFastTapStreak || 0) + 1;
    } else {
      state._microExprFastTapStreak = 0;
    }
    // P6: Track interaction speed for fatigue adaptation
    if (interactionTime > 0) {
      var _prevAvg = state._avgInteractionDelayMs || 0;
      var _count = state._interactionDelayCount || 0;
      state._avgInteractionDelayMs = (_prevAvg * _count + interactionTime) / (_count + 1);
      state._interactionDelayCount = _count + 1;
      state._slowInteractionStreak = interactionTime > 5000 ? (state._slowInteractionStreak || 0) + 1 : 0;
    }
    // Update engagement signals
    state._engagementSignals = state._engagementSignals || {};
    state._engagementSignals.microExprInteracted = true;
    state._engagementSignals.microExprShown = true;
    state._engagementSignals.timeToFirstInteractionMs = interactionTime;
    // If the Active-mode idle-pulse fired AND the user then clicked, credit the nudge.
    if (state._engagementSignals.nudgeFired) {
      state._engagementSignals.nudgeAcceptedClick = true;
      console.log('[ENGAGEMENT] nudge accepted — anchor click followed idle-pulse');
    }

    // Guaranteed visible consequence with causal delay (120-180ms)
    var hasReactToken = false;
    var resolvedTokens = [];
    var _reactionDelay = 120 + Math.floor(Math.random() * 60);

    setTimeout(function() {
      // A) Try reaction token resolution first
      for (var tokenId in reactionMap) {
        if (!reactionMap.hasOwnProperty(tokenId)) continue;
        var replacement = reactionMap[tokenId];
        var tokenEl = document.querySelector('.react-token[data-token="' + tokenId + '"]');
        if (tokenEl) {
          tokenEl.textContent = _povAdaptMicroLine(replacement);
          tokenEl.classList.remove('react-token-pending');
          tokenEl.classList.add('react-token-resolved');
          resolvedTokens.push(tokenId);
          hasReactToken = true;
        }
      }

      // B) Fallback: axis-specific micro-response with standard/edge selection
      if (!hasReactToken && bankKey && _MICRO_RESPONSE_LINES[bankKey]) {
        var responseText = _pickMicroResponse(bankKey);
        var widget = document.querySelector('.micro-expr-moment[data-expr-idx="' + exprIdx + '"]');
        if (widget) {
          var responseEl = document.createElement('span');
          responseEl.className = 'micro-expr-response';
          responseEl.textContent = ' ' + _povAdaptMicroLine(responseText);
          widget.parentElement.insertBefore(responseEl, widget.nextSibling);
        }
      }
    }, _reactionDelay);

    if (resolvedTokens.length) {
      console.log('[REACT TOKEN]', {
        sceneIndex: state.turnCount || 0,
        tokensFound: Object.keys(reactionMap),
        resolvedTokens: resolvedTokens,
        optionChosen: optText,
        success: resolvedTokens.length === Object.keys(reactionMap).length
      });
    }

    // P7: Telemetry
    console.log('[MICRO-EXPR:SELECT]', { expr: exprIdx, option: optText, bankKey: bankKey, vector: vector, timeToInteractionMs: interactionTime, profile: state.playerExpressionProfile });
    if (typeof window._logTelemetry === 'function') {
      window._logTelemetry({
        type: 'micro_expression',
        sceneIndex: state.turnCount || 0,
        shown: true,
        interacted: true,
        timeToInteractionMs: interactionTime,
        skipped: false,
        option: optText,
        bankKey: bankKey,
        consequence: hasReactToken ? 'react_token' : 'micro_response'
      });
    }

    // Collapse widget: replace with selected text
    var widgetEl = document.querySelector('.micro-expr-moment[data-expr-idx="' + exprIdx + '"]');
    if (widgetEl) {
      widgetEl.innerHTML = '<span class="micro-expr-chosen">' + optText + '</span>';
      widgetEl.classList.add('micro-expr-resolved');
    }

    // Also remove interactive styling from anchor
    var anchorEl = document.querySelector('.microexpr-anchor[data-anchor-id="' + exprIdx + '"]');
    if (anchorEl) anchorEl.classList.add('microexpr-anchor-resolved');
  };

  // P5: Expression echo — build downstream bias directive from expression profile
  function _buildExpressionEchoDirective() {
    // DEAD since System A (the client-side 3-option micro-expression pick) was
    // RIPPED OUT 2026-06-18: state.playerExpressionProfile / _microExprHistory are
    // now NEVER written (_buildMicroExprInjections returns []), so this only ever
    // hit the `if (!profile) return ''` guard. Gutted to an explicit no-op; the
    // build-call is also nulled at the prompt-assembly site. If a profile writer is
    // ever restored, restore from git. See [[project_micro_expression_systems]].
    return '';
  }

  // PHASE-LOCAL INTIMACY REGISTER — the protagonist's demonstrated manner
  // (state.playerExpressionProfile, accumulated from anchor-reaction
  // micro-expressions) calibrates how the LI carries register + intensity
  // DURING intimate scenes. This is an EXECUTION-MODE read, NOT a fourth
  // persistent axis: it reads the profile but EMITS only inside the intimacy
  // phase and writes nothing persistent (respects the firewall + soft-cap;
  // see the microDecision/axis handoff). It is SUBORDINATE to the explicit
  // Tier-4 transitional picks (voice/control/tempo) — a background tendency,
  // not a per-scene command — and shapes register/intensity only (never
  // consent, plot, or character identity).
  function buildExpressionStyleIntimacyDirective() {
      // DEAD since System A removal 2026-06-18 — read state.playerExpressionProfile /
      // _microExprHistory, both now NEVER written. Was already always-empty via the
      // `if (!profile) return ''` guard. Gutted to an explicit no-op; build-call also
      // nulled. Restore from git if a profile writer returns. See [[project_micro_expression_systems]].
      return '';
  }
  window.buildExpressionStyleIntimacyDirective = buildExpressionStyleIntimacyDirective;

  // ── WORLD SENSORY TEXTURE ─────────────────────────────────────────────
  // Every world has its own tactile register; scenes should deliver tension
  // and action THROUGH world-specific material detail woven into the beat —
  // a fist on waterlogged shipboards, implants reading an alien petal while
  // missing the sarcasm, a crystal chandelier ringing as a voice climbs.
  // Generalized from the billionaire-only MATERIAL OPULENCE block (user
