    'LostRelationship': 'history',
    'BetrayalHistory': 'history',
    'RelentlessPast': 'history',
    'OldDebts': 'history',
    // identity / transformation
    'BecomingPowerful': 'identity',
    'MoralCorruption': 'identity',
    'Awakening': 'identity',
    'IdentityShift': 'identity',
    'Ascension': 'identity',
    // mystery / chemistry
    'Noir': 'mystery',
    'Espionage': 'mystery',
    'DoubleLife': 'mystery'
