          var _remainingArchs = _ARCHETYPE_POOL_FOR_CANDIDATES.filter(function(a) { return a !== _userPick; });
          var _archShuffled = _remainingArchs.slice().sort(function() { return Math.random() - 0.5; });
          archetypeAssignments = [_userPick].concat(_archShuffled.slice(0, Math.max(0, count - 1)));
