  window.PSYCHOLOGICAL_LOCK_VOCABULARY = PSYCHOLOGICAL_LOCK_VOCABULARY;
  window.EROTIC_LOCK_VOCABULARY = EROTIC_LOCK_VOCABULARY;

  // ── L4 RELATIONSHIP UNCERTAINTY (Roman 2026-06-12) ────────────────────
  // Deterministic derivation from pairBond PC psychological lock. Each lock
  // tag has a canonical hope/fear pair (the positive vs negative reading of
  // the same psychic configuration). evidence_for / evidence_against pull
  // from the LI Bible's already-locked behavioral fields (attraction_
  // manifestation = evidence_for; deflection_pattern = evidence_against).
  // Zero LLM calls. Light surface area: one new state slot + one render block.
  const _LOCK_HOPE_FEAR_MAP = {
    'needs_to_be_needed':            { hope: 'He needs me — not as decoration, as the thing that holds.',                                fear: 'His needing me is a phase; he will solve it on his own and the need will pass.' },
    'lets_me_carry_quietly':         { hope: 'He lets me carry the thing I am ashamed of carrying and does not flinch.',                fear: 'He lets me carry because he has not yet noticed it should be shared.' },
    'private_helplessness':          { hope: 'He has shown me the part of him that is small and undefended.',                            fear: 'He has not shown me; the version I am loving is the version he performs.' },
    'chosen_despite_evidence':       { hope: 'He keeps choosing me even as the case against me grows.',                                  fear: 'He will stop choosing the moment the case becomes undeniable.' },
    'believes_me_without_proof':     { hope: 'He believes me when no one else does.',                                                    fear: 'He believes me because he does not yet know enough to doubt.' },
    'unflinching_witness':           { hope: 'He has seen the worst of me and stayed in the room.',                                      fear: 'He stayed because he has not yet processed what he saw.' },
    'chooses_when_room_doesnt':      { hope: 'He chooses me at the moment the rest of the room turns away.',                             fear: 'He chooses me out of contrarianism, not desire.' },
    'sees_through_me':               { hope: 'He sees through the version of me I show everyone else.',                                  fear: 'He sees through me and is just being polite about it.' },
    'trains_attention_on_what_i_care':{ hope: 'He pays attention to the thing only I notice mattering.',                                  fear: 'He pays attention because he is studying me, not because he is with me.' },
    'private_recognition':           { hope: 'He recognized the private version of me before I knew I was showing it.',                  fear: 'He recognized me from someone else\'s description, not his own seeing.' },
    'competes_with_no_one':          { hope: 'He has stopped looking at anyone else the way he looks at me.',                            fear: 'He is not competing because he has not yet decided I am worth competing for.' },
    'accepts_being_second':          { hope: 'He accepts the parts of my life he cannot be at the center of.',                           fear: 'He accepts being second now and will resent it later.' },
    'outlasts_my_grief':             { hope: 'He outlasts my grief — he does not need me to recover on his timeline.',                   fear: 'He is waiting out my grief because he expects a return to normal he will not get.' },
    'waits_without_shrinking':       { hope: 'He waits for me without becoming smaller.',                                                fear: 'He is waiting because he has not yet committed to the staying.' },
    'keeps_the_light_on':            { hope: 'He keeps the door open for me even when I do not ask him to.',                             fear: 'He keeps it open out of habit, not promise.' },
    'stays_when_loyalty_costs':      { hope: 'He stays even when staying costs him.',                                                    fear: 'He stays because he has not yet counted the cost.' },
    'refuses_to_look_away':          { hope: 'He keeps looking even when I expect him to flinch.',                                       fear: 'He is looking because of the spectacle, not because of me.' },
    'holds_her_position':            { hope: 'He does not move from the place that is mine.',                                            fear: 'He is holding the position because no one has asked him to leave yet.' },
    'accepts_being_the_cost':        { hope: 'He has accepted being the price I will pay.',                                              fear: 'He has not yet seen what being that price will cost him.' },
    'loves_me_as_spent':             { hope: 'He sees the version of me that is already tired and chooses it anyway.',                   fear: 'He is choosing the spent version because he has not yet met the un-spent one.' },
    'refuses_clean_moral_frame':     { hope: 'He does not need me to be the right kind of woman in this story.',                         fear: 'He does not need it yet; he will once the audience does.' },
    'releases_me_from_the_name':     { hope: 'He lets me put down the name I was carrying for everyone else.',                           fear: 'He is letting me put it down because he does not yet know what it means.' },
    'risks_being_known':             { hope: 'He has chosen to be known by me, knowing what that costs.',                                fear: 'He has not yet been seen at the level the knowing requires.' },
    'holds_the_other_half':          { hope: 'He holds the half of me I cannot hold alone.',                                             fear: 'He is holding because he has not yet been asked to do more.' },
    'holds_when_old_self_walks_in':  { hope: 'He holds my new self even when the old one returns.',                                      fear: 'He will choose the version of me he met first.' }
  };
  window._LOCK_HOPE_FEAR_MAP = _LOCK_HOPE_FEAR_MAP;

  function _deriveRelationshipUncertainty(state) {
    var s = state || window.state || {};
    if (!s.pairBond) return null;
    var bond = s.pairBond;
    var pcLock = bond.psychologicalLock_pc;
    if (!pcLock) return null;
    var mapping = _LOCK_HOPE_FEAR_MAP[pcLock];
    if (!mapping) return null;
    var li = s.liBodyBible || {};

    // evidence_for — from LI's attraction_manifestation (what his care LOOKS LIKE)
    var evidence_for = '';
    if (li.attraction_manifestation) {
      var first = String(li.attraction_manifestation).split(/[;.](?!\d)/)[0].trim();
      if (first) {
        evidence_for = first.charAt(0).toUpperCase() + first.slice(1);
        if (!/[.!?]$/.test(evidence_for)) evidence_for += '.';
      }
    }
    if (!evidence_for && li.defining_anecdote) {
      var firstA = String(li.defining_anecdote).split(/[.](?!\d)/)[0].trim();
      if (firstA && firstA.length < 240) {
        evidence_for = firstA.charAt(0).toUpperCase() + firstA.slice(1) + '.';
      }
    }

    // evidence_against — from LI's deflection_pattern (how he avoids being seen)
    var evidence_against = '';
    if (li.deflection_pattern) {
      var pat = String(li.deflection_pattern).trim();
      evidence_against = pat.charAt(0).toUpperCase() + pat.slice(1);
      if (!/[.!?]$/.test(evidence_against)) evidence_against += '.';
    }
    if (!evidence_against && li.signature_behavior) {
      var sb = String(li.signature_behavior).trim();
      evidence_against = sb.charAt(0).toUpperCase() + sb.slice(1);
      if (!/[.!?]$/.test(evidence_against)) evidence_against += '.';
    }

    return {
      hope: mapping.hope,
      fear: mapping.fear,
      evidence_for: evidence_for || null,
      evidence_against: evidence_against || null,
      source_lock: pcLock,
      derived_at: Date.now()
    };
  }
  window._deriveRelationshipUncertainty = _deriveRelationshipUncertainty;

  // ── L1 SCENE 1 ROMANCE PACKET (Roman 2026-06-12) ──────────────────────
  // Deterministic derivation of attraction-bearing memory content for the
  // Scene 1 prose layer. Templates rotate by storyId via _rotatingExemplars.
  // Engine-conditional: SHARED_HISTORY produces memory-shape; LOOMING_PRESENCE
  // produces anticipation-shape; COLLISION pre-meet leaves memory fields NULL
  // and produces only absence_register + fixation_objects (anticipation-coded).
  // Zero LLM calls. Pulls from existing Bible + pairBond fields.
  var _SCENE1_PACKET_TEMPLATES = {
    SHARED_HISTORY: {
      attraction_memory: [
        'The night {LI} had {LI_VERB} — and she had watched him notice {PC_FEATURE}, without naming why.',
        'The afternoon {LI} had {LI_VERB} — and her body had registered him before her mind had caught up.',
        'The first time she had seen {LI} {LI_VERB}, she had lost the next three words someone said to her.',
        'The hour after the {LI_VERB} — when neither of them had moved to leave the room.'
      ],
      unresolved_moment: [
        'The moment she had almost {PC_WANT_VERB} — and he had {LI_DEFLECT}, and neither of them had named it since.',
        'The conversation they had not finished — the one she had been finishing alone, for {DURATION}.',
        'The look he had given her at the {VENUE}, and the question she had not asked about it.',
        'The thing he had said the {TIME} — the one she had been carrying like a fact ever since.'
      ],
      absence_register: [
        'The shape of {PC_WANT} sat in her chest where his certainty might have been.',
        'His silence over the last {DURATION} was the loudest thing in the room.',
        'The space he was not in had a particular weight — the weight of having known him.',
        'She had been listening for him without choosing to, for {DURATION}.'
      ]
    },
    LOOMING_PRESENCE: {
      attraction_memory: [
        'The version of {LI} she had assembled from third-hand stories — the one who {LI_VERB} — was already running ahead of the real one.',
        'She had been hearing about {LI} for {DURATION}, and her body had decided he was already someone.',
        'The {LI} she had built in her head — the one who {LI_VERB} — had stopped being a stranger weeks ago.',
        'Three different people had described him the same way; she had been adding it to her own picture ever since.'
      ],
      unresolved_moment: [
        'The conversation she had been having with him in her head — the one she did not yet know if she would have out loud.',
        'The question she had been holding for the version of him she had not yet met.',
        'The way she had been rehearsing the moment of meeting him without admitting she was rehearsing.',
        'The thing she had been ready to say to him for {DURATION}, and the chance that had not yet come.'
      ],
      absence_register: [
        'The shape of {PC_WANT} sat in her chest where a stranger\'s certainty had no business being.',
        'She had been waiting for a man she had not met, for {DURATION}.',
        'His absence had a specific weight, the way the absence of a song you have not yet heard does.',
        'She had stopped pretending she was not listening for his name in other people\'s sentences.'
      ]
    },
    COLLISION: {
      attraction_memory: [],
      unresolved_moment: [],
      absence_register: [
        'The shape of {PC_WANT} sat in her chest with no specific person attached to it — yet.',
        'She had been carrying {PC_WANT_NOUN} alone for {DURATION}, and she had stopped expecting anyone.',
        'There was no one she was waiting for; the listening was a habit.',
        'The silence in the room was just silence. It was not waiting on anyone.'
      ]
    }
  };

  function _deriveRomancePacket(state) {
    var s = state || window.state || {};
    if (!s.pairBond || !s.liBodyBible || !s.pcBodyBible) return null;

    var engine = String(
      (s.aPlot && s.aPlot.romanceEngine) ||
      (s.pairDynamic && s.pairDynamic.romanceEngine) ||
      (s.romanceEnginePlan && s.romanceEnginePlan.engine) ||
      'SHARED_HISTORY'
    ).toUpperCase();
    // Map engine variants to the three template families
    var family = engine;
    if (engine === 'SECOND_CHANCE') family = 'SHARED_HISTORY';
    if (engine === 'ENEMIES_TO_LOVERS') family = 'SHARED_HISTORY';
    if (engine === 'FORBIDDEN') family = 'SHARED_HISTORY';
    if (engine === 'COMFORT') family = 'SHARED_HISTORY';
    if (!_SCENE1_PACKET_TEMPLATES[family]) family = 'SHARED_HISTORY';

    var tpl = _SCENE1_PACKET_TEMPLATES[family];
    var li = s.liBodyBible || {};
    var pc = s.pcBodyBible || {};
    var liName = s.loveInterestName || 'he';

    // Extract substitution tokens from existing Bible fields.
    var liVerbSrc = li.attraction_manifestation || li.defining_anecdote || li.signature_behavior || 'turned toward her';
    var liVerb = String(liVerbSrc).split(/[;.](?!\d)/)[0].trim();
    if (liVerb.length > 110) liVerb = liVerb.slice(0, 110).replace(/\s+\S*$/, '') + '…';
    liVerb = liVerb.replace(/^He\s+/i, '').replace(/^[A-Z]/, function (c) { return c.toLowerCase(); });

    var liDeflect = li.deflection_pattern ? String(li.deflection_pattern).trim() : 'let the silence run';
    liDeflect = liDeflect.replace(/^He\s+/i, '').replace(/^[A-Z]/, function (c) { return c.toLowerCase(); });
    if (liDeflect.length > 90) liDeflect = liDeflect.slice(0, 90).replace(/\s+\S*$/, '') + '…';

    // PC feature for "noticing her" beats — pull from li_keenly_aware_of (PC Bible)
    var pcFeature = '';
    if (pc.li_keenly_aware_of) {
      var feats = String(pc.li_keenly_aware_of).split(/[,;]/).map(function (s) { return s.trim(); }).filter(Boolean);
      if (feats.length) pcFeature = feats[0];
    }
    if (!pcFeature && pc.signature_feature) pcFeature = String(pc.signature_feature).split(/[,;.]/)[0].trim();
    if (!pcFeature) pcFeature = 'the thing she has stopped pointing out';

    // PC want — from private_hope; transform "to <verb>" → gerund-noun phrase so
    // it reads grammatically inside "The shape of X sat in her chest."
    var pcWantRaw = pc.private_hope ? String(pc.private_hope).trim() : 'wanting to be noticed';
    var pcWantGerund = pcWantRaw
      .replace(/^to be\s+/i, 'being ')           // "to be loved" → "being loved"
      .replace(/^to have\s+/i, 'having ')        // "to have …" → "having …"
      .replace(/^to find\s+/i, 'finding ')       // "to find …" → "finding …"
      .replace(/^to\s+(\w+)/i, function (_, v) {  // generic "to X" → "X-ing"
        return /[aeiou]e$/i.test(v) ? v.slice(0, -1) + 'ing' : v + 'ing';
      })
      .replace(/^[A-Z]/, function (c) { return c.toLowerCase(); });
    var pcWant = pcWantGerund;
    if (pcWant.length > 130) pcWant = pcWant.slice(0, 130).replace(/\s+\S*$/, '') + '…';
    // For the "she had almost X" templates we need the original verb-shape
    var pcWantVerb = (pcWantRaw.replace(/^to\s+/i, '').match(/^[a-z]+/i) || ['said'])[0].toLowerCase();
    var pcWantNoun = pcWantGerund || 'the wanting';

    // Rotating elements (storyId-seeded)
    var rot = (typeof window._rotatingExemplars === 'function') ? window._rotatingExemplars : null;
    var pick = function (key, pool) {
      if (!Array.isArray(pool) || !pool.length) return null;
      if (rot) return rot('packet_' + key, pool, 1)[0];
      return pool[0];
    };

    var DURATION_POOL = ['the last six months', 'the last year', 'three weeks now', 'two months', 'eighteen months', 'the whole season'];
    var TIME_POOL = ['the night of the launch', 'the afternoon at the gallery', 'the Tuesday after the panel', 'the morning of the announcement', 'the hour after the dinner'];
    var VENUE_POOL = ['party', 'gala', 'dinner', 'meeting', 'event', 'gathering'];

    var subs = {
      LI: liName,
      LI_VERB: liVerb,
      LI_DEFLECT: liDeflect,
      PC_FEATURE: pcFeature,
      PC_WANT: pcWant,
      PC_WANT_VERB: pcWantVerb,
      PC_WANT_NOUN: pcWantNoun,
      DURATION: pick('duration', DURATION_POOL) || 'six months',
      TIME: pick('time', TIME_POOL) || 'last spring',
      VENUE: pick('venue', VENUE_POOL) || 'event'
    };

    var fillTemplate = function (str) {
      return String(str).replace(/\{([A-Z_]+)\}/g, function (_, k) { return subs[k] != null ? subs[k] : '{' + k + '}'; });
    };

    var pickFromPool = function (key, pool) {
      if (!Array.isArray(pool) || !pool.length) return null;
      var picked = rot ? rot('packet_' + key, pool, 1)[0] : pool[0];
      return picked ? fillTemplate(picked) : null;
    };

    var attractionMemory = pickFromPool('attraction_' + family, tpl.attraction_memory);
    var unresolvedMoment = pickFromPool('unresolved_' + family, tpl.unresolved_moment);
    var absenceRegister  = pickFromPool('absence_' + family, tpl.absence_register);

    // Fixation objects — pull from LI Bible's signature_feature + pc_keenly_notices basket.
    var fixations = [];
    if (li.signature_feature) {
      var sf = String(li.signature_feature).split(/[,;.]/)[0].trim();
      if (sf) fixations.push({ object: sf, source: 'li.signature_feature', emotion: 'fascination' });
    }
    if (li.pc_keenly_notices) {
      String(li.pc_keenly_notices).split(/[,;]/).forEach(function (f) {
        var t = f.trim();
        if (t && t.length > 4 && fixations.length < 4) fixations.push({ object: t, source: 'li.pc_keenly_notices', emotion: 'attraction' });
      });
    }
    if (li.voice_quality && fixations.length < 4) {
      var vq = String(li.voice_quality).split(/[,;.]/)[0].trim();
      if (vq) fixations.push({ object: vq, source: 'li.voice_quality', emotion: 'longing' });
    }
    if (li.holding_style && fixations.length < 5) {
      var hs = String(li.holding_style).split(/[,;.]/)[0].trim();
      if (hs) fixations.push({ object: hs, source: 'li.holding_style', emotion: 'attraction' });
    }

    return {
      engine_at_gen: engine,
      shape: family === 'COLLISION' ? 'anticipation' : (family === 'LOOMING_PRESENCE' ? 'anticipation' : 'memory'),
      attraction_memory: attractionMemory,
      unresolved_moment: unresolvedMoment,
      absence_register: absenceRegister,
      fixation_objects: fixations,
      uncertainty_ref: (s.pairBond && s.pairBond.uncertainty) ? s.pairBond.uncertainty.source_lock : null,
      derived_at: Date.now()
    };
  }
  window._deriveRomancePacket = _deriveRomancePacket;

  // Build the prose-prompt block for the Scene 1 Romance Packet.
  function _buildScene1RomancePacketBlock(state) {
    var s = state || window.state || {};
    if (!s.scene1RomancePacket) return '';
    var p = s.scene1RomancePacket;
    var lines = [];
    lines.push('');
    lines.push('───────────────────────────────────────────────────────────────');
    lines.push('SCENE 1 ROMANCE PACKET (L1 — what the prose draws from emotionally)');
    lines.push('Shape: ' + p.shape + ' · Engine: ' + p.engine_at_gen);
    lines.push('───────────────────────────────────────────────────────────────');
    lines.push('These are the planning layer\'s emotional-content selections for Scene 1.');
    lines.push('When the prose recalls / imagines / anticipates the LI, draw FROM THIS PACKET, not the broader Bible.');
    lines.push('The Bible behavioral fields (signature_behavior / deflection_pattern / status / competence / institutional position) are CANON BACKDROP for Scene 2+; in Scene 1 they are SUBORDINATE to this packet.');
    lines.push('');
    if (p.attraction_memory) lines.push('  ATTRACTION MEMORY:   ' + p.attraction_memory);
    if (p.unresolved_moment) lines.push('  UNRESOLVED MOMENT:   ' + p.unresolved_moment);
    if (p.absence_register)  lines.push('  ABSENCE REGISTER:    ' + p.absence_register);
    if (p.fixation_objects && p.fixation_objects.length) {
      lines.push('  FIXATION OBJECTS — recurring emotional anchors (orbit these; do NOT introduce new ones):');
      p.fixation_objects.forEach(function (f) {
        lines.push('    • ' + f.object + ' [' + (f.emotion || 'longing') + ']');
      });
    }
    lines.push('');
    lines.push('USAGE: Treat the memory/moment/register entries as SHAPE TEMPLATES — render them in YOUR OWN voice and prose;');
    lines.push('do NOT copy the seed wording verbatim. The packet selects the EMOTIONAL CONTENT; the prose layer renders the surface.');
    lines.push('The fixation objects RECUR — each one should appear in the scene at least once, ideally twice; they are the recurring anchors the reader will remember.');
    return '\n' + lines.join('\n') + '\n';
  }
  window._buildScene1RomancePacketBlock = _buildScene1RomancePacketBlock;

