  // Run after every scene finalize. Toasts + warns ONLY on issues newly seen
  // this session (throttled in-memory). Emits a periodic summary every 5
  // scenes so the user knows the check is alive even when healthy.
  function _storyboundHealthMaybeAlert() {
    let result;
    try { result = _storyboundHealthCheck(); } catch (e) { try { console.warn('[STORYBOUND HEALTH] check threw: ' + (e && e.message)); } catch (_) {} return; }
    if (!result) return;

    const newIssues = result.issues.filter(i => !_healthToastedThisSession.has(i.key));
    if (newIssues.length) {
      // Toast (short — 3s autohide)
      if (typeof showToast === 'function') {
        const msg = newIssues.length === 1
          ? '⚠ Health: ' + newIssues[0].diagnostic.slice(0, 70)
          : '⚠ Health: ' + newIssues.length + ' new issues — _storyboundHealth() for details';
        try { showToast(msg); } catch (_) {}
      }
      // Console
      try {
        console.warn('[STORYBOUND HEALTH ⚠] ' + newIssues.length + ' new issue(s):');
        newIssues.forEach(i => {
          const sev = i.severity.toUpperCase();
          console.warn('  ' + sev + ' · ' + i.category + ': ' + i.diagnostic);
          console.warn('    → ' + i.action);
          console.warn('    → dismiss: window._storyboundHealthAck(\'' + i.key + '\', 5)');
        });
      } catch (_) {}
      newIssues.forEach(i => _healthToastedThisSession.add(i.key));
    }
    // Clear in-memory throttle for issues that have resolved
    const currentKeys = new Set(result.issues.map(i => i.key));
    Array.from(_healthToastedThisSession).forEach(key => {
      if (!currentKeys.has(key)) _healthToastedThisSession.delete(key);
    });

    // Periodic summary every 5 checks
    _healthChecksSinceSummary++;
    if (_healthChecksSinceSummary >= _HEALTH_PERIODIC_EVERY) {
      _healthChecksSinceSummary = 0;
      try {
        if (result.healthy) {
          console.log('[STORYBOUND HEALTH ✓] all checks passing (' + result.scenes + ' scenes, ' + result.classified + ' classified)');
        } else {
          console.log('[STORYBOUND HEALTH ⚠] ' + result.issues.length + ' active issue(s) — _storyboundHealth() for details');
        }
      } catch (_) {}
    }
  }
