  window._lockManifestationHistogram = function (N) {
    N = (typeof N === 'number' && N > 0) ? N : 50;
    var arr = (typeof window._auditTail === 'function') ? window._auditTail(N) : [];
    var classified = arr.filter(function (r) { return r && r.lockTurn; });
    if (!classified.length) { console.warn('[LOCK-AUDIT] no classified scenes yet (last ' + N + ' audits)'); return null; }
    var byLock = {};
    classified.forEach(function (rec) {
      (rec.lockTurn.detected || []).forEach(function (t) {
        if (!t || !t.lock) return;
        var lock = t.lock;
        var manif = String(t.manifestation || 'unknown').split(':')[0].trim();
        if (!byLock[lock]) byLock[lock] = { total: 0, byManif: {} };
        byLock[lock].total += 1;
        byLock[lock].byManif[manif] = (byLock[lock].byManif[manif] || 0) + 1;
      });
    });
    var output = {};
    Object.keys(byLock).forEach(function (lock) {
      var data = byLock[lock];
      var manifEntries = Object.keys(data.byManif).map(function (m) {
        var count = data.byManif[m];
        var pct = Math.round(100 * count / data.total);
        return { manifestation: m, count: count, pct: pct + '%', calcified: pct >= 40 ? '⚠' : '' };
      }).sort(function (a, b) { return b.count - a.count; });
      var fullPool = LOCK_MANIFESTATIONS[String(lock).toLowerCase()] || [];
      var usedVerbs = new Set();
      manifEntries.forEach(function (e) { if (e.manifestation !== 'freeform' && e.manifestation !== 'unknown') usedVerbs.add(e.manifestation); });
      var unusedVerbs = fullPool.map(function (m) {
        var match = m.match(/^([A-Z][A-Z_ ]+?)\b/);
        return match ? match[1].trim() : '';
      }).filter(function (v) { return v && !usedVerbs.has(v); });
      output[lock] = {
        total_presses: data.total,
        distribution: manifEntries,
        unused_pool_shapes: unusedVerbs,
        diversity_index: fullPool.length ? Number((usedVerbs.size / fullPool.length).toFixed(2)) : null
      };
    });
    console.log('[LOCK-AUDIT] manifestation histogram across ' + classified.length + ' classified scene(s):');
    Object.keys(output).forEach(function (lock) {
      var d = output[lock];
      console.log('  ' + lock + ' — ' + d.total_presses + ' press(es) · diversity ' + (d.diversity_index != null ? d.diversity_index : 'n/a') +
        (d.unused_pool_shapes.length ? ' · UNUSED: ' + d.unused_pool_shapes.join(', ') : ''));
      try { console.table(d.distribution); } catch (_) { console.log(d.distribution); }
    });
    return output;
  };

