    strangers:        { match: /strangers|meet.?cute|new.?in.?town|first.?meeting|traveler/i, engines: ['COLLISION', 'LOOMING_PRESENCE'] },
    forced_proximity: { match: /forced.?proximity|snowed.?in|marooned|stranded|roommates|trapped/i, engines: ['COLLISION'] },
    workplace:        { match: /workplace|coworkers?|office|colleagues?|boss/i,   engines: ['COLLISION', 'LOOMING_PRESENCE'] },
    forbidden:        { match: /forbidden|taboo|off.?limits/i,                    engines: ['COLLISION', 'LOOMING_PRESENCE', 'SHARED_HISTORY'] },
