      if (!raw) return '';
      var all = JSON.parse(raw) || {};
      var entries = Array.isArray(all[flavor]) ? all[flavor] : [];
      if (!entries.length) return '';
      var catKey = role === 'li' ? 'liWoundCategory' : 'pcWoundCategory';
      var coreKey = role === 'li' ? 'liWoundCore' : 'pcWoundCore';
      var ALL_CATS = ['PARENTAL', 'PARTNER', 'SIBLING_OR_FRIEND', 'MENTOR', 'PUBLIC', 'DEBT'];
      var recentCats = [], recentCores = [];
      entries.forEach(function (e) {
        if (e && e[catKey]) recentCats.push(String(e[catKey]).toUpperCase());
        if (e && e[coreKey]) recentCores.push(String(e[coreKey]));
      });
      if (!recentCats.length && !recentCores.length) return '';
      var roleLabel = role === 'li' ? 'LOVE INTEREST' : 'PROTAGONIST';
      // Categories used 2+ times OR in the last play are banned; prefer unused.
      var counts = {};
      recentCats.forEach(function (c) { counts[c] = (counts[c] || 0) + 1; });
      var lastCat = recentCats.length ? recentCats[recentCats.length - 1] : null;
      var banned = {};
      Object.keys(counts).forEach(function (c) { if (counts[c] >= 2 || c === lastCat) banned[c] = 1; });
