      if (Object.keys(banned).length) emit.push('FORBIDDEN this play (last-play OR used 2+ times): ' + Object.keys(banned).join(', ') + '. ');
      if (allowed.length) emit.push('CHOOSE wound.category from: ' + allowed.join(', ') + '. ');
      if (unused.length) emit.push('STRONGEST variety move — pick an UNUSED category: ' + unused.join(', ') + '. ');
