  async function _extractAndRecordScene1SignaturePhrases(sceneText) {
    try {
      if (!sceneText || typeof sceneText !== 'string' || sceneText.length < 300) return;
      // Strip HTML markup, marker tokens, and the deck opener/closer so the
      // extractor sees clean prose only.
      var _plain = sceneText
        .replace(/<[^>]+>/g, ' ')
        .replace(/<<MICRO_EXPRESSION>>/gi, '')
        .replace(/<<CONTINUE>>/gi, '')
        .trim();
      if (_plain.length < 200) return;
      var sys =
        'You are a calcification detector for a serial-fiction engine. You read ONE scene and extract the SIGNATURE PHRASINGS — specific 3-10 word phrases that the writer naturally reached for in THIS scene and would likely default to AGAIN in future scenes unless actively rotated. ' +
        'A signature phrasing is SPECIFIC enough that a reader who saw it twice across stories would notice the repetition. Examples of WHAT to extract: distinctive body imagery (e.g., "his jaw tightened" / "his mouth went still"), the protagonist\'s body-response pattern (e.g., "her breath caught at the collarbone"), a specific dollar amount or unusual number ("$47.3 million" / "the 5 p.m. deadline"), a repeated noun or domain word ("the master account" / "the enclave"), templated metaphor ("the kind of stillness that means a person has already decided"), or any phrase that reads as the writer\'s default reach. ' +
        'Examples of what NOT to extract: generic narrative phrases ("she said", "I looked at"), the protagonist or LI name alone, common dialogue beats, the deck/tarot mandated closer line. ' +
        'Return ONLY a JSON array of 5-8 strings, no commentary, no markdown, no code fences. Each string is one signature phrasing, exactly as it appeared in the prose (preserve capitalization and punctuation where distinctive). Begin with [ and end with ].';
      var res = await _auditPost({ temperature: 0.2, max_tokens: 400, messages: [ { role: 'system', content: sys }, { role: 'user', content: _plain.slice(0, 6000) } ] });
      if (!res.ok) { try { console.warn('[SIGNATURE-PHRASES] extractor HTTP ' + res.status); } catch (_) {} return; }
      var data = await res.json();
      var rawc = (data && typeof data.content === 'string') ? data.content : '';
      rawc = rawc.replace(/^\s*```[a-z]*\s*/i, '').replace(/\s*```\s*$/i, '').trim();
      var lb = rawc.indexOf('['), rb = rawc.lastIndexOf(']');
      if (lb === -1 || rb === -1 || rb <= lb) { try { console.warn('[SIGNATURE-PHRASES] extractor: no JSON array in output'); } catch (_) {} return; }
      var arr;
      try { arr = JSON.parse(rawc.slice(lb, rb + 1)); }
      catch (_pe) { try { console.warn('[SIGNATURE-PHRASES] extractor: JSON parse failed: ' + (_pe && _pe.message)); } catch (_) {} return; }
      if (!Array.isArray(arr)) return;
      _updateLastFlavorHistorySignaturePhrases(arr);
    } catch (e) { try { console.warn('[SIGNATURE-PHRASES] extractor errored (non-fatal):', e && e.message); } catch (_) {} }
  }
