    var subs = (_ctax.tax && _ctax.tax[cat]) || CRISIS_TAXONOMY[cat] || [];
    var _shown = (typeof window._rotatingExemplars === 'function')
      ? window._rotatingExemplars('crisis_sub_' + _ctax.key + '_' + cat, subs, Math.min(5, subs.length)) : subs.slice(0, 5);
    var out = '\nCRISIS FAMILY FOR THIS STORY (preselected — Roman 2026-06-05; HARD): the protagonist\'s opening crisis belongs to the family **' + cat + '**. ' + guidance + '\n';
    out += 'The A-plot goal, personalStakePC, antagonist, and namedClock MUST EMERGE FROM this crisis family — the world/flavor is the ARENA, the crisis family is the ENGINE. Do NOT default to the genre\'s rote spine (for a billionaire: a hostile takeover / losing the company / being voted out / a boardroom war) UNLESS the family above is STATUS_DESTRUCTION.\n';
    if (_shown.length) out += 'Concrete shapes in this family + world (pick the one that fits THIS protagonist, or invent a fresh variant in the same family): ' + _shown.join(' / ') + '.\n';
    // HARD INCOMPATIBILITY TABLE (Roman 2026-06-06 — rejection-grade; the family is AUTHORITATIVE,
