    // HEAVY band keywords
    if (/\b(trust\s+fracture|moral\s+collision|sacrifice\s+crisis|betrayal|impossible\s+loyalty|attachment[- ]?threat|repair)\b/.test(t)) return 'heavy';
    // LIGHT band keywords
