      if (!liteRomanceClose) why.push('LITE LI-gravity dropped >12pt (candidate: the heavy A-PLOT PRESSURE / SOURCE-FIELD WEIGHTING block)');
      if (!liteNoNewStructFail) why.push('LITE added a structure violation (enum/quote-mash/cast/crisis) — but these are mount-gate-repaired in prod, so weigh lightly');
