    var _first = function (t, n) { return String(t).split(/\s+/).slice(0, n).join(' '); };
    console.log('%c[S1:HVL:READ] ───── VARIANT A (HEAVY) first ~600 words ─────', 'color:#c9a24e');
    console.log(_first(pairs[0].A.text, 600));
    console.log('%c[S1:HVL:READ] ───── VARIANT B (LITE+structure) first ~600 words ─────', 'color:#c9a24e');
    console.log(_first(pairs[0].B.text, 600));
    console.log('%c[S1:HVL] done — full prose on the returned object (.pairs[i].A.text / .B.text). Decision rule: LITE within ~90–95% reader-quality AND saves ~10–20¢ → move Scene 1 to LITE/HYBRID.', 'color:#c9a24e');
    return { pairs: pairs, cost: { heavy: heavyCost, lite: liteCost, savings: heavyCost - liteCost, biblePremium: _biblePremium }, verdict: { liteCompetitive: liteCompetitive, liteNotColder: liteNotColder, liteTargetOk: liteTargetOk, liteRomanceClose: liteRomanceClose, liteNoNewStructFail: liteNoNewStructFail } };
