  // ════════════════════════════════════════════════════════════════════════════
  // window._scene1DoctrineCompare({pairs})  → ONE COMMAND, no flags / no reload.
  // Generates Scene 1 with the FULL LI-TEXTURE DOCTRINE vs the COMPRESSED variant
  // from the SAME cached prompt (only that doctrine block differs — same seed, same
  // bibles, same model Sonnet), audits both, prints a copy-paste comparison.
  // Needs: one Scene 1 played on this build (caches the prompt + both doctrine
  // variants). Read-only — writes nothing to story state/library.
  // ════════════════════════════════════════════════════════════════════════════
  window._scene1DoctrineCompare = async function (opts) {
    opts = opts || {};
    var N = Math.min(3, Math.max(1, opts.pairs || 2));
    var P = (window.state && window.state._lastScene1AuditPrompt) || null;
    if (!P || !P.system) { console.warn('[S1:DOC] No cached Scene-1 prompt. Play ONE billionaire_modern literary Scene 1 on THIS build, then re-run window._scene1DoctrineCompare().'); return null; }
    var V = window._liTexDoctrineVariants || null;
    if (!V || !V.full || !V.compact) { console.warn('[S1:DOC] Doctrine variants not captured. They cache when a Scene-1 prose prompt builds on this build — play one Scene 1 first.'); return null; }
    // Build both system prompts by swapping ONLY the LI-TEXTURE DOCTRINE block.
    var sysFull, sysCompact, swapNote;
    if (P.system.indexOf(V.full) !== -1)      { sysFull = P.system; sysCompact = P.system.split(V.full).join(V.compact); swapNote = 'cached=FULL → derived COMPRESSED'; }
    else if (P.system.indexOf(V.compact) !== -1) { sysCompact = P.system; sysFull = P.system.split(V.compact).join(V.full); swapNote = 'cached=COMPRESSED → derived FULL'; }
    else { console.warn('[S1:DOC] LI-TEXTURE DOCTRINE not found in the cached prompt (LI on-stage this scene? stale cache?) — regenerate a fresh offstage-LI Scene 1.'); return null; }
    if (sysFull === sysCompact) { console.warn('[S1:DOC] swap produced no change — aborting.'); return null; }
    var _liFirst = String(P.li || (window.state && window.state.loveInterestName) || 'Roman').split(/\s+/)[0] || 'Roman';
    var _liRe = new RegExp('\\b' + _liFirst.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'gi');
    var _DESIRE = /\b(want\w*|desire\w*|ache\w*|long\w*|crav\w*|hunger\w*|need\w*|pull\w*|heat|skin|mouth|lips?|breath\w*|touch\w*|warmth|closer|kiss\w*|yearn\w*|tremb\w*)\b/gi;
    var _density = function (t) { var w = String(t).split(/\s+/).filter(Boolean).length || 1; return { li: (t.match(_liRe) || []).length, des: (t.match(_DESIRE) || []).length, words: w, desPer1k: Math.round(1000 * (t.match(_DESIRE) || []).length / w) }; };
    var _rawSonnet = async function (sys) {
      try { var r = await window.StoryboundOrchestration.callChatGPT([{ role: 'system', content: sys }, { role: 'user', content: P.user }], 'PRIMARY_AUTHOR', { model: 'claude-sonnet-4-5', temperature: 0.7, max_tokens: 3600 }); return (typeof r === 'string') ? r : ((r && r.content) || ''); }
      catch (e) { console.warn('[S1:DOC] sonnet failed:', e && e.message); return ''; }
    };
    var _runQuality = async function (text) {
      var snapG = (window.state && window.state.rPlot) ? window.state.rPlot._gravity : undefined;
      var snapT = window.state ? window.state._ownershipTrajectory : undefined;
      var snapF = window._forceAudits;
      var g = null;
      try { window._forceAudits = true; await window._auditSceneEmotionalGravity(text, {}); g = (window.state && window.state.rPlot) ? window.state.rPlot._gravity : null; }
      catch (e) { console.warn('[S1:DOC] gravity audit threw:', e && e.message); }
      finally { try { if (window.state && window.state.rPlot) window.state.rPlot._gravity = snapG; window.state._ownershipTrajectory = snapT; window._forceAudits = snapF; } catch (_) {} }
      return g;
    };
    var _row = function (label, g, de) {
      var des = g && g.desire, dt = g && g.desireTarget, bk = g && g.buckets, rm = g && g.romanMode, own = g && g.ownership, ws = g && g.woundSource;
      console.log('  ' + label.padEnd(12)
        + ' desire=' + String(des ? des.verdict : '?').padEnd(13) + '(hot ' + (des ? des.hot : '?') + '/cold ' + (des ? des.cold : '?') + ')'
        + ' · target=' + String(dt ? dt.target : '?').padEnd(8) + '(Roman ' + (dt ? dt.roman : '?') + '%)'
        + ' · LI=' + String(g ? g.verdict : '?') + ' ' + (g ? g.liPct : '?') + '% ' + String(g ? g.register : '?')
        + ' · want-him=' + (rm ? rm.wanting : '?') + '%'
        + ' · R/A=' + (bk ? bk.rplotShare : '?') + '/' + (bk ? bk.aplotShare : '?')
        + ' · trueRom=' + (own ? own.trueRomancePct : '?') + '%'
        + ' · woundFail=' + (ws ? !!ws.coreRomanceFail : '?')
        + ' · LI-mentions=' + de.li + ' desire/1k=' + de.desPer1k);
      return { desire: des ? des.verdict : '?', hot: des ? des.hot : null, target: dt ? dt.target : '?', roman: dt ? dt.roman : null, liPct: g ? g.liPct : null, wanting: rm ? rm.wanting : null, trueRom: own ? own.trueRomancePct : null, woundFail: ws ? !!ws.coreRomanceFail : false, liMentions: de.li, desPer1k: de.desPer1k };
    };
    console.log('%c[S1:DOC] LI-TEXTURE DOCTRINE A/B — ' + N + ' pair(s) · same seed/bibles/model (Sonnet) · only the doctrine block differs · ' + swapNote, 'color:#c9a24e;font-weight:bold');
    console.log('[S1:DOC] doctrine size: FULL ' + V.full.length + 'c (~' + Math.round(V.full.length / 4) + 't) · COMPRESSED ' + V.compact.length + 'c (~' + Math.round(V.compact.length / 4) + 't) · saves ~' + Math.round((V.full.length - V.compact.length) / 4) + 't/scene (~$' + ((V.full.length - V.compact.length) / 4 * 0.000003).toFixed(4) + ' Sonnet-input)');
    var rows = [];
    for (var i = 0; i < N; i++) {
      console.log('[S1:DOC] ── pair ' + (i + 1) + '/' + N + ' — generating FULL + COMPRESSED …');
      var tF = await _rawSonnet(sysFull); var tC = await _rawSonnet(sysCompact);
      if (!tF || tF.length < 120 || !tC || tC.length < 120) { console.warn('[S1:DOC] pair ' + (i + 1) + ' empty/short — skipped'); continue; }
      var gF = await _runQuality(tF), dF = _density(tF);
      var gC = await _runQuality(tC), dC = _density(tC);
      console.log('[S1:DOC] pair ' + (i + 1) + ':');
      var rF = _row('FULL', gF, dF); var rC = _row('COMPRESSED', gC, dC);
      rows.push({ full: rF, compact: rC, tF: tF, tC: tC });
    }
    if (!rows.length) { console.warn('[S1:DOC] no complete pairs.'); return null; }
    // ── VERDICT ──
    var _coldRank = { COLD: 0, MIXED: 1, DESIRE_DRIVEN: 2 };
    var _ge = function (b, a) { return (_coldRank[b] != null ? _coldRank[b] : 1) >= (_coldRank[a] != null ? _coldRank[a] : 1); };
    var notColder = rows.every(function (r) { return _ge(r.compact.desire, r.full.desire); });
    var targetOk = rows.every(function (r) { return r.compact.target !== 'PLOT_TRUTH' || r.full.target === 'PLOT_TRUTH'; });
    var liClose = rows.every(function (r) { return r.full.liPct == null || r.compact.liPct == null || r.compact.liPct >= r.full.liPct - 10; });
    var desireDensityOk = rows.every(function (r) { return r.compact.desPer1k >= Math.round(r.full.desPer1k * 0.7); });
    var noWoundRegress = rows.every(function (r) { return !r.compact.woundFail || r.full.woundFail; });
    var holds = notColder && targetOk && liClose && desireDensityOk && noWoundRegress;
    console.log('%c[S1:DOC:VERDICT] ─────────────', 'color:#c9a24e;font-weight:bold');
    console.log('  desire not colder:        ' + (notColder ? '✓' : '✗') + '   FULL=[' + rows.map(function (r) { return r.full.desire; }).join(',') + '] COMPRESSED=[' + rows.map(function (r) { return r.compact.desire; }).join(',') + ']');
    console.log('  desire-target not worse:  ' + (targetOk ? '✓' : '✗') + '   FULL=[' + rows.map(function (r) { return r.full.target; }).join(',') + '] COMPRESSED=[' + rows.map(function (r) { return r.compact.target; }).join(',') + ']');
    console.log('  LI gravity within ~10pt:  ' + (liClose ? '✓' : '✗') + '   FULL=[' + rows.map(function (r) { return r.full.liPct; }).join(',') + '] COMPRESSED=[' + rows.map(function (r) { return r.compact.liPct; }).join(',') + ']');
    console.log('  desire-density held:      ' + (desireDensityOk ? '✓' : '✗') + '   FULL/1k=[' + rows.map(function (r) { return r.full.desPer1k; }).join(',') + '] COMPRESSED/1k=[' + rows.map(function (r) { return r.compact.desPer1k; }).join(',') + ']');
    console.log('  no wound-source regress:  ' + (noWoundRegress ? '✓' : '✗'));
    console.log('%c  ⟹ ' + (holds ? 'COMPRESSED HOLDS — quality parity on this sample; safe to flip default and bank ~' + Math.round((V.full.length - V.compact.length) / 4) + 't/scene. (n=' + rows.length + ' — re-run {pairs:3} to confirm.)' : 'COMPRESSED REGRESSED on a dimension above — keep FULL or revise the compression.'), 'color:' + (holds ? '#7ec77e' : '#e0a85e') + ';font-weight:bold');
    // ── HUMAN READ (pair 1, first ~450 words each) ──
    var _first = function (t, n) { return String(t).split(/\s+/).slice(0, n).join(' '); };
    console.log('%c[S1:DOC:READ] ── FULL doctrine, first ~450 words ──', 'color:#c9a24e');
    console.log(_first(rows[0].tF, 450));
    console.log('%c[S1:DOC:READ] ── COMPRESSED doctrine, first ~450 words ──', 'color:#c9a24e');
    console.log(_first(rows[0].tC, 450));
    console.log('%c[S1:DOC] done — full prose on the returned object (.rows[i].tF / .tC).', 'color:#c9a24e');
    return { rows: rows, holds: holds, savesTok: Math.round((V.full.length - V.compact.length) / 4) };
  };

  // ════════════════════════════════════════════════════════════════════════════
  // window._authorModelABTest()  → the real cost+quality A/B (Roman 2026-07-14):
  //   Grok-HEAVY (cold) · Grok-HEAVY (warm, 2nd pass → shows prompt-cache benefit) ·
  //   Mistral-HEAVY (the "cheap model, full directives" idea) · Grok-LITE (current).
  // Fires each config against the LIVE proxies on the SAME real prompts and reports
  // MEASURED token usage + $ (per the pricing table) + the prose to judge by eye.
  // PREREQS: (1) a HEAVY prompt captured — Scene 1 captures it, or set
  //   window.__forceHeavyBuild=true and generate one scene; (2) a LITE prompt captured
  //   — advance into an ordinary connecting scene (Scene 2+, not a kiss/climax). Then
  //   run window._authorModelABTest(). Read-only; makes 3–4 paid model calls.
  // ════════════════════════════════════════════════════════════════════════════
  window._authorModelABTest = async function (opts) {
    opts = opts || {};
    var s = window.state || {};
    var H = s._lastHeavyAuditPrompt, L = s._lastContinuationAuditPrompt;
    if (!H || !H.system) console.warn('[AB] No captured HEAVY prompt. Set window.__forceHeavyBuild=true and generate ONE scene (or use Scene 1), then re-run.');
    if (!L || !L.system) console.warn('[AB] No captured LITE prompt. Advance into an ordinary connecting scene (Scene 2+, NOT a kiss/climax), then re-run. Grok-LITE will be skipped without it.');
    if ((!H || !H.system) && (!L || !L.system)) return null;
    var user = (H && H.system && ('Action: ' + (H.act || '') + '\nDialogue: "' + (H.dia || '') + '"'))
            || (L && L.system && ('Action: ' + (L.act || '') + '\nDialogue: "' + (L.dia || '') + '"'))
            || 'Action: continue the scene\nDialogue: ""';
    var PRICE = {
      'grok-4.3':                    { in: 1.25e-6, out: 2.5e-6, cr: 0.2e-6 },
      'grok-4-1-fast-reasoning':     { in: 0.5e-6,  out: 1.5e-6, cr: 0.08e-6 },
      'mistral-small-latest':        { in: 1e-7,    out: 3e-7,   cr: 1e-7 }
    };
    function priceFor(m) { m = String(m || '').toLowerCase(); if (m.indexOf('mistral') >= 0) return PRICE['mistral-small-latest']; if (m.indexOf('fast-reasoning') >= 0) return PRICE['grok-4-1-fast-reasoning']; return PRICE['grok-4.3']; }
    function summarize(d, label, ms) {
      var u = (d && d.usage) || {};
      var served = (d && (d.model || (d._orchestration && d._orchestration.model))) || '?';
      var pt = u.prompt_tokens || u.input_tokens || 0, ct = u.completion_tokens || u.output_tokens || 0;
      var cached = (u.prompt_tokens_details && u.prompt_tokens_details.cached_tokens) || u.cache_read_input_tokens || u.cached_tokens || 0;
      var fresh = Math.max(0, pt - cached), p = priceFor(served);
      var cost = fresh * p.in + cached * (p.cr || p.in) + ct * p.out;
      var text = (d && d.choices && d.choices[0] && d.choices[0].message && d.choices[0].message.content) || (d && d.content) || '';
      return { label: label, served: served, promptTok: pt, cachedTok: cached, outTok: ct, costUsd: +cost.toFixed(5), ms: Math.round(ms), chars: text.length, text: text };
    }
    async function fire(endpoint, body, label) {
      var t0 = (window.performance && performance.now) ? performance.now() : Date.now();
      try {
        var r = await fetch(endpoint, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
        var d = await r.json();
        var ms = ((window.performance && performance.now) ? performance.now() : Date.now()) - t0;
        if (!r.ok) console.warn('[AB] ' + label + ' HTTP ' + r.status);
        return summarize(d, label, ms);
      } catch (e) { console.warn('[AB] ' + label + ' threw: ' + (e && e.message)); return { label: label, error: (e && e.message) || 'err' }; }
    }
    var grokBody = function (sys) { return { role: 'NARRATIVE_AUTHOR', preferredModel: 'grok-4.3', messages: [{ role: 'system', content: sys }, { role: 'user', content: user }], max_tokens: 3000, temperature: 0.7 }; };
    var mistralBody = function (sys) { return { model: 'mistral-small-latest', messages: [{ role: 'system', content: sys }, { role: 'user', content: user }], max_tokens: 3000, temperature: 0.7 }; };
    console.log('[AB] firing (HEAVY ' + (H && H.system ? H.system.length : '—') + 'c, LITE ' + (L && L.system ? L.system.length : '—') + 'c)…');
    var rows = [];
    if (H && H.system) {
      rows.push(await fire('/api/proxy', grokBody(H.system), 'Grok-HEAVY (cold)'));
      rows.push(await fire('/api/proxy', grokBody(H.system), 'Grok-HEAVY (warm)'));
      if (opts.mistral !== false) rows.push(await fire('/api/mistral-proxy', mistralBody(H.system), 'Mistral-HEAVY'));
    }
    if (L && L.system) rows.push(await fire('/api/proxy', grokBody(L.system), 'Grok-LITE'));
    var live = rows.filter(function (r) { return !r.error; });
    try { console.table(live.map(function (r) { return { config: r.label, served: r.served, prompt_tok: r.promptTok, cached_tok: r.cachedTok, out_tok: r.outTok, cost: '$' + r.costUsd, ms: r.ms, prose_chars: r.chars }; })); } catch (_) { console.log(live); }
    console.log('%c[AB] PROSE — cost is measured; QUALITY is yours to judge by eye:', 'font-weight:bold;color:#c9a24e');
    live.forEach(function (r) { console.log('\n════════ ' + r.label + '  ($' + r.costUsd + ' · ' + r.chars + 'c · ' + r.ms + 'ms) ════════\n' + r.text); });
    return { rows: rows };
  };

  // ════════════════════════════════════════════════════════════════════════════
  // window._continuationModelCompare({pairs})  → Sonnet-LITE vs Grok-LITE on the
  // SAME continuation prompt. Continuations dominate per-story cost (~$0.10 each ×
  // 19 ≈ $1.90/story) and currently run on Sonnet; Grok-4-1-fast-reasoning is ~6×
  // cheaper input / ~10× cheaper output. This tests whether Grok holds prose quality
