  /**
   * Sync legacy romantic-target fields from canonical normalizedPartnerKernel.
   * Canonical source: state.normalizedPartnerKernel (set by name normalization)
   * Compatibility mirrors: state.playerName, state.loveInterestName, state.storybeau
   * These mirrors are read by fatecards.js and romance-integrity checks.
   */
  function _syncRomanticTargetState() {
    const pName = state.normalizedPlayerKernel || null;
    const lName = state.normalizedPartnerKernel || null;
    state.playerName = pName;
    state.loveInterestName = lName;
    state.storybeau = lName ? { name: lName, role: 'primary romantic interest' } : null;
  }

  /**
   * Transform a character name for world-linguistic coherence.
   * Strips titles, simplifies for primitive worlds, ensures cultural consistency.
   * Both player and LI pass through the same pipeline.
   */
  var _TITLE_PATTERN = /^(lord|lady|sir|dame|duke|duchess|count|countess|baron|baroness|prince|princess|king|queen|emperor|empress|captain|commander|general|doctor|professor|reverend|father|mother|sister|brother)\s+/i;
  var _SURNAME_PATTERN = /^(\S+)\s+(of|de|von|van|del|di|zu|the)\s+/i;

  function _transformNameForWorld(name, world) {
    if (!name || !world) return name;
    var w = world.toLowerCase();

    // Historical prehistoric: phonetic simplification (oral-language feel)
    if (w === 'historical' && state.historicalCognitiveBand && /^prehistoric/.test(state.historicalCognitiveBand)) {
      // Strip all titles and aristocratic particles
      var stripped = name.replace(_TITLE_PATTERN, '').trim();
      stripped = stripped.replace(_SURNAME_PATTERN, '$1').trim();
      // Take only first name / word
      var parts = stripped.split(/\s+/);
      var first = parts[0] || stripped;
      // Phonetic syllable split: break on vowel-consonant boundaries
      var syllables = first.match(/[^aeiouy]*[aeiouy]+(?:[^aeiouy]*$)?/gi) || [first];
      // Keep 1-2 strongest syllables (deterministic: first + last if 3+)
      var result;
      if (syllables.length <= 2) {
        result = syllables.join('');
      } else {
        // First syllable + last syllable for recognition + natural ending
        result = syllables[0] + syllables[syllables.length - 1];
      }
      // Cap at 6 chars — trim from end at a natural consonant/vowel boundary
      if (result.length > 6) {
        // Find last vowel within first 6 chars and cut after it + one trailing consonant
        var trimmed = result.slice(0, 6);
        var lastVowel = trimmed.search(/[aeiouy][^aeiouy]*$/i);
        if (lastVowel >= 2) {
          // Keep through the consonant(s) after the last vowel, max 1
          trimmed = trimmed.slice(0, lastVowel + 2);
        }
        result = trimmed;
      }
      // Short names (1-3 chars): keep as-is
      if (result.length < 2) result = first.slice(0, 3);
      return result.charAt(0).toUpperCase() + result.slice(1).toLowerCase();
    }

    // Fantasy / Historical / PostApocalyptic: strip modern titles only
    if (w === 'fantasy' || w === 'historical' || w === 'postapocalyptic') {
      // Strip explicitly modern titles (Doctor, Professor, etc.)
      var modernTitles = /^(doctor|professor|reverend|captain|commander|general)\s+/i;
      return name.replace(modernTitles, '').trim() || name;
    }

    // SciFi / Dystopia: allow most names, strip feudal titles
    if (w === 'scifi' || w === 'dystopia') {
      var feudalTitles = /^(lord|lady|duke|duchess|count|countess|baron|baroness|prince|princess|king|queen|emperor|empress)\s+/i;
      return name.replace(feudalTitles, '').trim() || name;
    }

    // Modern: allow anything
    return name;
  }

