  "continuityProbe": { "depicted_li_gender": "male | female | unclear", "depicted_pc_gender": "male | female | unclear", "present_characters": [ { "name": "<character name>", "presence_mode": "IN_PERSON | ON_PHONE | OFFSTAGE_REFERENCED", "role": "<2-5 word role>" } ], "location_change": { "changed": false, "transition_shown": false, "reason": null } },
