  // Text-block resolver — returns null (use default), '' (suppress), or a transform string.
  function _axisToneOverride(block, direction) {
    var toneKey = _resolveToneKey();
    if (toneKey === 'Earnest') return null; // baseline
    var toneTable = _AXIS_TONE_TRANSFORMS[toneKey];
    if (!toneTable) return null;
    var blockValue = toneTable[block];
    if (blockValue === undefined) return null;
    if (typeof blockValue === 'string') return blockValue; // applies to both directions (including '' to suppress)
    if (blockValue && typeof blockValue === 'object') {
      var dirText = blockValue[direction];
      return (dirText === undefined) ? null : dirText;
    }
    return null;
  }
  window._axisToneOverride = _axisToneOverride;

  // Pacing-modulator scale composer. Returns a scalar (default 1.0) that
  // composes multiplicatively with the axis pacing multiplier in
  // _showStagedBeat. 0 suppresses the modulator entirely; 0.5 halves its
  // distance from 1.0.
  function _axisToneModulatorScale(direction) {
    var toneKey = _resolveToneKey();
    if (toneKey === 'Earnest') return 1.0;
    var toneTable = _AXIS_TONE_TRANSFORMS[toneKey];
    if (!toneTable) return 1.0;
    var ps = toneTable.pacing_scale;
    if (ps === undefined) return 1.0;
    if (typeof ps === 'number') return ps;
    if (ps && typeof ps === 'object' && direction in ps) {
      var v = ps[direction];
      return (typeof v === 'number') ? v : 1.0;
    }
    return 1.0;
  }
  window._axisToneModulatorScale = _axisToneModulatorScale;

