      var label = (ALT_POV_LABELS[kind] && ALT_POV_LABELS[kind].full) || kind;
      var cta = (ALT_POV_LABELS[kind] && ALT_POV_LABELS[kind].cta) || ('Read ' + label);
      var costLine = (pricing.kind === 'class2')
