  function _hasPriorRenderedScene() {
    try {
      if (typeof StoryPagination === 'undefined' || !StoryPagination.getAllContent) return false;
      var t = StoryPagination.getAllContent().replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
      return t.length > 1500;
    } catch (_) { return false; }
  }

  // ── SCENE CONTINUATION DIRECTIVE (Roman 2026-06-06) ────────────────────────
  // ROOT CAUSE FIX: the literary scene generator's user message is ONLY the
  // player's Action/Dialogue — the prior scene's prose ending is NOT in the
  // prompt anywhere, and the SCENE ENVIRONMENT ANCHOR forces every scene to open
  // from a physical establishing shot. Result: scenes RE-OPEN with the same
  // "morning light / phone on the counter / voicemail unread" beat, and a scene
  // that should CONTINUE a live moment (e.g. right after a Petition-summoned
  // phone call) instead resets to a fresh morning and contradicts what just
  // ═══════════════════════════════════════════════════════════════════════
  // META-EGG SYSTEM — small in-fiction wink when the player types meta
  // commentary into say/do ("write better", "write like Hemingway", "be
  // shorter"). Detection runs at submit, BEFORE the explicit-sniffer and
  // intent-transmutation, and rewrites the input to a tiny neutral PC beat so
  // the meta text never enacts as a diegetic command. One-shot: consumed by
  // the next scene's prompt builder (buildMetaEggDirective) and cleared.
  //
  // Two kinds:
  //   • dad_joke — "write/be/make X" stylistic imperatives → smuggle the
  //     literal X into one prose sentence as a knowing wink. Fate amused
  //     itself; the line reads as ordinary prose, never a 4th-wall break.
  //   • shorter — length complaints → Fate-attributed compression (~250-350w).
  //
  // SKIPPED entirely in OAS / intimacy / Scene 1.
  // ═══════════════════════════════════════════════════════════════════════
  var _META_EGG_DAD_JOKE_PATTERNS = [
    // "write like Hemingway" / "be like Stephen King" — captures "like X".
    /^(?:please\s+|could\s+you\s+|can\s+you\s+)?(?:write|write this|be|sound|make it|make this|do it|do this)\s+(like\s+[A-Za-z][\w' .-]{1,28})\s*[.!?]*\s*$/i,
    // "write more poetic" / "be more cinematic" — captures "more X".
    /^(?:please\s+|could\s+you\s+|can\s+you\s+)?(?:write|write this|be|sound|make it|make this|do it|do this)\s+(more\s+[A-Za-z][\w-]{2,20}(?:\s+[A-Za-z][\w-]{2,20})?)\s*[.!?]*\s*$/i,
    // "write better" / "be sharper" / "make it tighter" — captures X.
    /^(?:please\s+|could\s+you\s+|can\s+you\s+)?(?:write|write this|be|sound|make it|make this|do it|do this)\s+([A-Za-z][\w-]{2,20})\s*[.!?]*\s*$/i
  ];
  var _META_EGG_SHORTER_RX = /^(?:please\s+)?(?:make it\s+|be\s+|keep it\s+|write\s+)?(shorter|tldr|tl;dr|too long|get on with it|concise|wrap it up|too verbose|too wordy|less prose)\b/i;
  // Routed to a dedicated LI in-character humor beat (NOT the dad-joke smuggle)
  // — checked BEFORE the dad-joke loop so "be funnier" doesn't fall through.
  var _META_EGG_FUNNIER_RX = /^(?:please\s+)?(?:(?:be|make it|make this|sound|do it|do this|write|write this)\s+)?(?:more\s+)?(funnier|funny|humor(?:ous)?|less\s+serious|too\s+serious|lighten\s+up|crack\s+a\s+joke|tell\s+a\s+joke|make\s+me\s+laugh)\b/i;
  // Reject payloads that read as diegetic story-content rather than stylistic
  // meta — guards against e.g. "be careful", "make it stop", "do this alone".
  var _META_EGG_PAYLOAD_DIEGETIC_REJECTS = /^(a\s|an\s|the\s|my\s|his\s|her\s|their\s|your\s|to\s|with\s|him|her|them|out|up|down|over|on|in|off|away|back|here|there|that|this|stop|quick|alone|fast|free|safe|naked|hard|careful|gentle|nice|mean|kind|cruel|loud|quiet)\b/i;

  function _detectMetaEgg(actText, diaText) {
    try {
      if (!state) return null;
      // Hard skips: never fire inside OAS / intimacy / Scene 1 — eggs are a
      // Fate-mischief moment, not appropriate inside a charged scene or
      // before the player has landed in the basic rhythm.
      if (state.intimacyDialogue && state.intimacyDialogue.active) return null;
      if (state.intimacyPhase && state.intimacyPhase !== 'none') return null;
      if (state.storyturn === 'ST3' || state.storyturn === 'ST4') return null;
      if ((state.turnCount || 0) < 1) return null;
      var combined = String((actText || '') + ' ' + (diaText || '')).trim();
      if (!combined || combined.length < 4 || combined.length > 60) return null;
      // Length complaint first (its own compression directive, not a smuggle).
      if (_META_EGG_SHORTER_RX.test(combined)) {
        return { kind: 'shorter', payload: '', originalAct: actText || '', originalDia: diaText || '' };
      }
      // "Be funnier" routes to a dedicated LI in-character humor beat — checked
      // BEFORE the dad-joke loop so "funnier" doesn't get captured as a smuggle.
      if (_META_EGG_FUNNIER_RX.test(combined)) {
        return { kind: 'funnier', payload: '', originalAct: actText || '', originalDia: diaText || '' };
      }
      // Dad-joke smuggle: stylistic imperative → capture the X to smuggle.
      for (var i = 0; i < _META_EGG_DAD_JOKE_PATTERNS.length; i++) {
        var m = combined.match(_META_EGG_DAD_JOKE_PATTERNS[i]);
        if (!m) continue;
        var phrase = (m[1] || '').trim().replace(/[.!?,;:"']+$/, '');
        if (!phrase || phrase.length < 2 || phrase.length > 30) continue;
        if (phrase.split(/\s+/).length > 4) continue;
        if (_META_EGG_PAYLOAD_DIEGETIC_REJECTS.test(phrase)) continue;
        return { kind: 'dad_joke', payload: phrase, originalAct: actText || '', originalDia: diaText || '' };
      }
      return null;
    } catch (_) { return null; }
  }

  // Tiny neutral PC beat used to replace the suppressed meta input so the
  // model has SOMETHING to enact and the AGENCY check doesn't fire empty.
  // POV-aware so it doesn't clash with the scene's narration register.
  function _metaEggSubstituteBeat() {
    try {
      var pool = [
        'I let the silence run a beat longer than it needs to.',
        'I look down at my hands, gathering the thought.',
        'I take a slow breath and let the moment settle.'
      ];
      var pov = (state && state.povMode) || '';
      var p = (state && state.picks && state.picks.pov) || '';
      var first  = (pov === '1st' || pov === 'first' || p === '1st' || p === 'first');
      var second = (pov === '2nd' || pov === 'second' || p === '2nd' || p === 'second');
      var pick = pool[Math.floor(Math.random() * pool.length)];
      if (first) return pick;
      if (second) return pick.replace(/\bI\b/g, 'You').replace(/\bmy\b/g, 'your');
      // 3rd (default) — gender-aware verb agreement.
      var gen = String((state && (state.gender || (state.picks && state.picks.identity && state.picks.identity.playerGender))) || 'female').toLowerCase();
      var subj = gen === 'male' ? 'He' : (gen === 'non-binary' ? 'They' : 'She');
      var poss = gen === 'male' ? 'his' : (gen === 'non-binary' ? 'their' : 'her');
      var s = gen === 'non-binary' ? '' : 's';
      return pick
        .replace(/\bI\b/g, subj)
        .replace(/\bmy\b/g, poss)
        .replace(/\blet\b/g, 'let' + s)
        .replace(/\blook\b/g, 'look' + s)
        .replace(/\btake\b/g, 'take' + s);
    } catch (_) { return 'She lets the silence run a beat longer than it needs to.'; }
  }

  // One-shot directive consumed at next-scene prompt build. Wired into
  // sceneDirectives so it flows through the literary turn fullSys.
  function buildMetaEggDirective() {
    try {
      var egg = state && state._pendingMetaEgg;
      if (!egg) return '';
      state._pendingMetaEgg = null; // consume — one-shot
      if (egg.kind === 'dad_joke' && egg.payload) {
        var p = egg.payload;
        return '\n\nMETA EGG — FATE\'S WRITTEN WINK (ONE-SHOT, this scene only):\n' +
          'Fate amused itself this scene. At ONE plausible moment in the scene, a character (the PC or any NPC on stage) LITERALLY WRITES the phrase "' + p + '" on a plausible available surface — and the protagonist NOTICES it. The written word IS the joke; the act lands as a small visual beat (one or two sentences); the scene moves on without commentary.\n' +
          '  • The phrase must appear EXACTLY as "' + p + '" — preserve proper-noun capitalization; otherwise lowercase as the written act naturally would be. Render it in quotes or italics within the prose so the reader sees the literal word(s).\n' +
          '  • Pick a surface plausible to the world/era and the scene\'s location: modern → margin of a notepad, napkin, sticky-note, fogged glass, whiteboard, dust on a desk, the back of a receipt, a phone\'s notes app, condensation on a mirror. Historical → parchment edge, chalkboard, ledger margin, sand. Prehistoric → ash, scraped into bark, finger in damp earth. Sci-fi → smart-surface, projected note, scratched into a panel. Whatever the scene already affords.\n' +
          '  • Pick a WRITER plausible to the moment: PC writing it = self-reminder, idle scribble, half-formed thought rendered tangible. NPC writing it = absentminded note, doodle, list item, marginalia. Either way, NO diegetic motive is named. The act is small and glancing.\n' +
          '  • The PC SEES it, registers it (a small jolt, a half-noticed glance, a faint wrongness), and does NOT remark on it as strange. NOT a question, NOT a confrontation. Just noticing.\n' +
          '  • ONE instance only. Do NOT lampshade it, do NOT explain why the character wrote it, do NOT alter plot or characters around it. The scene continues per all other directives. Do NOT actually adopt the style the phrase names (do NOT write the scene "better," do NOT imitate the named author) — the WRITTEN WORD on the surface IS the joke.\n' +
          '  • Worked examples:\n' +
          '      - "better"         → "On the corner of his notepad, in distracted cursive, he\'d written better and underlined it once. She wasn\'t sure he knew he\'d done it."\n' +
          '      - "like a human"   → "Someone had scrawled like a human in the margin of the proofs — in her own handwriting, she realized, with a small jolt of not remembering."\n' +
          '      - "like Hemingway" → "On the bar napkin, in pen, in handwriting she didn\'t recognize, someone had written like Hemingway and pushed it across the lacquer toward her."\n' +
          '      - "more poetic"    → "He doodled more poetic in the steam on the window without looking at it, the way someone hums a song they can\'t quite place."\n' +
          '  • The player\'s meta-comment ("' + (egg.originalAct || egg.originalDia || '').replace(/"/g, "'") + '") is NOT a diegetic action — the protagonist did not speak or do anything the player typed. Treat it strictly as Fate\'s prompt for this single written gag.\n';
      }
      if (egg.kind === 'funnier') {
        return '\n\nMETA EGG — LI HUMOR BEAT (ONE-SHOT, Fate\'s mischief):\n' +
          'Give the love interest ONE earned moment of HUMOR this scene — fully IN CHARACTER for their archetype, voice, and current emotional register. A sharp dry quip, a self-aware aside, a wry observation, an absurd noticing, a mock-solemn one-liner — whatever lands as funny in THIS PARTICULAR LI\'s register.\n' +
          '  • ONE moment, not a thread. One quip + one small beat of the PC\'s reaction, then the scene proceeds per all other directives.\n' +
          '  • NEVER stand-up comedy. NEVER an out-of-character joke. NEVER lampshade or explain why it was funny.\n' +
          '  • Honor the LI archetype: an Armored Fox quip is sharp + glancing + slightly evasive; a Dark Vice quip is bone-dry + cool + a touch cruel; a Spellbinder quip is theatrical + knowing; a Beautiful Ruin quip is rueful + self-deprecating; an Open Vein character barely jokes at all and the "humor" lands as a single dry observation, not a punchline. Mismatched humor reads as the model not knowing the character — defer to the LI directives already in this prompt.\n' +
          '  • SAFETY RAIL (HARD): if the scene\'s emotional register is genuinely heavy (grief, fresh crisis, intimate aftermath, safety beat, breakup, confrontation), SKIP this directive entirely — let the scene play straight. Fate\'s mischief was poorly-timed; better to no-op than to crack a joke over a wound. Do NOT acknowledge the skip in prose.\n' +
          '  • The player\'s meta-comment ("' + (egg.originalAct || egg.originalDia || '').replace(/"/g, "'") + '") is NOT a diegetic action — the protagonist did not say or do it. Treat it strictly as Fate\'s cue for this single in-character LI beat.\n';
      }
      if (egg.kind === 'shorter') {
        return '\n\nMETA EGG — TIGHTEN (ONE-SHOT, Fate-attributed compression):\n' +
          'Fate has tilted this scene toward density. Target ~250-350 words instead of the standard length. One or two scene moments, dense prose, every paragraph carrying weight. No throat-clearing, no setup, no expansion. The compression is Fate\'s tilt, not the protagonist\'s awareness — do NOT call attention to brevity.\n';
      }
      return '';
    } catch (_) { return ''; }
  }
  window.buildMetaEggDirective = buildMetaEggDirective;
  window._detectMetaEgg = _detectMetaEgg;

  // DEFERRED-SETUP DIRECTIVE — the UNIVERSAL Scene-2 consumer (Roman 2026-06-27). ONE producer
  // (the Scene-1 ledger; Hot&Fast is currently the only producer, but world-orientation /
  // rival-intro / magic-system / etc. can add debts to the SAME ledger later without touching
  // Scene 2 again) → ONE consumer (this). Injected at the two prompt-family roots every Scene-2
  // authoring path shares: _literarySceneMandate (heavy / orchestration / multi-pass) + the lite
  // system. Packet-driven (NOT gated on _hasPriorRenderedScene's char count — a short Hot&Fast S1
  // would trip that). One-shot via ledger.consumed (set at the Scene-2 finalize).
  // CONTINUITY OBLIGATION LEDGER (Roman 2026-06-27) — record a missed HARD beat as a debt.
  // The producer (post-scene fulfillment audit) calls this; a new hard debt invalidates any
  // speculative pre-gen so it can't ship a Scene N+1 that predates the debt.
  function _recordObligationDebt(debt) {
    try {
      if (!debt || !debt.id) return;
      state._obligationLedger = Array.isArray(state._obligationLedger) ? state._obligationLedger : [];
      if (state._obligationLedger.some(function (d) { return d && !d.paid && (d.id === debt.id || (d.description && debt.description && d.description === debt.description)); })) return; // dedupe live by id, with description fallback (same obligation re-declared in a later scene under a new id)
      if (debt.bornScene == null) debt.bornScene = (typeof state.turnCount === 'number') ? state.turnCount : 0;
      state._obligationLedger.push(debt);
      try { console.log('[OBLIGATION:RECORDED] id=' + debt.id + ' (' + (debt.importance || '?') + ') — ' + String(debt.description || '').slice(0, 90)); } catch (_) {}
      if (debt.importance === 'hard' && typeof window.invalidateSpeculativeScene === 'function') { try { window.invalidateSpeculativeScene('obligation_change'); try { console.log('[SPEC-PREFETCH:INVALIDATED] reason=obligation-debt id=' + debt.id); } catch (_) {} } catch (_) {} } // stale pre-gen predates this debt
    } catch (_) {}
  }
  window._recordObligationDebt = _recordObligationDebt;

  // Renders carried HARD obligation debts into the scene prompt. Safeguards (Roman 2026-06-27):
  // ≤2 hard + ≤1 soft per scene; expire after 2 scenes; never cosmetic; adapt-if-location-moved.
  function _renderObligationDebts() {
    try {
      var L = state._obligationLedger;
      if (!Array.isArray(L) || !L.length) return '';
      var cur = (typeof state.turnCount === 'number') ? state.turnCount : 0;
      var live = L.filter(function (d) { return d && !d.paid && (cur - (d.bornScene == null ? cur : d.bornScene)) <= 2; });
      var hard = live.filter(function (d) { return d.importance === 'hard'; }).slice(0, 2);
      var soft = live.filter(function (d) { return d.importance !== 'hard'; }).slice(0, 1);
      var pick = hard.concat(soft);
      if (!pick.length) return '';
      try { pick.forEach(function (d) { console.log('[OBLIGATION:DELIVERED] id=' + d.id + ' (' + d.importance + ')'); }); } catch (_) {}
      return '\n  CONTINUITY OBLIGATION (HARD — a required causal beat was set up earlier but NOT delivered; the STORY may not skip it even though the prose could). Pay the following EARLY, through CONSEQUENCE / DIALOGUE / ACTION, never as exposition: '
        + pick.map(function (d) { return '«' + String(d.description || d.id) + '»' + (d.locationBound ? ' (if you are no longer in/near the ' + d.locationBound + ', ADAPT — deliver the same causal FUNCTION through a new object / person / consequence; never force the literal staging)' : ''); }).join('; ')
        + '. Do NOT drop these and do NOT stack them as a recap; if paying one literally would break causality, deliver its CONSEQUENCE instead.\n';
    } catch (_) { return ''; }
  }
  window._renderObligationDebts = _renderObligationDebts;

  // UNIVERSAL deferred-setup consumer — ONE consumer for BOTH producers: (1) the Hot&Fast
  // Scene-1→2 packet, and (2) the Continuity Obligation Ledger (carried missed hard beats).
  function _buildDeferredSetupDirective() {
    var out = '';
    // (1) Hot&Fast Scene-1→2 deferred-setup packet
    try {
      if ((typeof _hotFastActive === 'function') && _hotFastActive() && state._hotFastDeferredPacket && !state._hotFastDeferredPacket.consumed) {
        var _p = state._hotFastDeferredPacket; var _debts = [];
        if (_p.pcEmbodimentDebt) _debts.push('the PROTAGONIST is not yet embodied — pay ONE concise felt-body OR physical/social grounding beat for her EARLY (first 250–400 words), through ACTION (never a mirror, a self-inventory, or a feature list), without interrupting the consequence');
        if (_p.liDescriptionDebt) _debts.push('the LOVE INTEREST has no physical/behavioral image yet — establish him through what he DOES here, not a portrait');
        if (_p.desireDebt) _debts.push('her DESIRE/pull toward him has not landed — let it surface through her body and attention, not a statement');
        try { console.log('[SCENE2:DEFERRED-SETUP-DIRECTIVE] fired · debts pc=' + _p.pcEmbodimentDebt + ' li=' + _p.liDescriptionDebt + ' desire=' + _p.desireDebt); } catch (_) {}
        out += '\n  HOT&FAST DEFERRED-SETUP (HARD — Scene 1 was a SHORT hot opener that deliberately deferred world/relationship setup; Scene 2 PAYS that debt, but THROUGH CONSEQUENCE, DIALOGUE, and RELATIONSHIP PRESSURE — NEVER an exposition/encyclopedia catch-up): build this scene as the CONSEQUENCE of the player\'s Scene-1 choice, and AS that consequence unfolds, ground the world and the relationship Scene 1 left thin — reveal them through what HAPPENS and what people DO/SAY under pressure, never a backstory paragraph. '
          + (_debts.length ? 'Pay these specific debts EARLY, woven into the action, never stacked or dumped: ' + _debts.join('; ') + '. ' : '')
          + 'Anything Scene 1 ALREADY established (her embodiment, his look, her wanting) — do NOT repeat it unless it has CHANGED under the new pressure; rotate to a fresh facet instead.\n';
      }
    } catch (_) {}
    // (2) Continuity Obligation Ledger — carried missed hard beats (all literary scenes)
    try { out += _renderObligationDebts(); } catch (_) {}
    return out;
  }
  window._buildDeferredSetupDirective = _buildDeferredSetupDirective;

  // PLOT CONTRACT (Roman 2026-06-27) — GATED, default OFF. Literary-only; never CG; never
  // Hot&Fast unless explicitly enabled. Flag: window._enableLiteraryPlotContract===true OR
  // state.flags.literaryPlotContract===true. Off → zero behavior change (no contract gen, no
  // directive, no audit scoring). Circuit-breaker for the prompt-surgery that adds per-scene
  // hard-beat obligations to literary planning.
  function _plotContractActive() {
    try {
      // DEFAULT ON (Roman 2026-06-27) — a dropped hard causal beat is a correctness bug, not a
      // preference; this guards Literary (incl. Hot&Fast) AND CG. MASTER KILL SWITCH for fast
      // rollback: window._plotContractKill = true  (or window._enableLiteraryPlotContract = false
      // / state.flags.plotContract = false). If prose ever feels mechanical/checklist-y, TUNE the
      // directive+generator phrasing FIRST (soften wording, 3→1-2 beats) — do not kill the ledger.
      if (window._plotContractKill === true
        || window._enableLiteraryPlotContract === false
        || (window.state && state.flags && state.flags.plotContract === false)) return false;
      var s = window.state || {};
      var _isLit = s.storyMode === 'literary' || s.renderMode === 'literary' || s.storyModality === 'literary';
      var _isCG = s.currentEngine === 'graphic' || s.renderMode === 'staged_story_mode' || s.storyModality === 'cinematic' || s._cgScreenplayMode === true;
      return _isLit || _isCG;
    } catch (_) { return false; }
  }
  window._plotContractActive = _plotContractActive;

  // THIS scene's hard-beat obligations (the contract). Injected at the same two roots as the
  // deferred-setup/ledger consumer. Reads state._scenePlotContract (populated by the generator).
  function _buildPlotContractDirective() {
    try {
      if (!_plotContractActive()) return '';
      var pc = state._scenePlotContract;
      var beats = (pc && Array.isArray(pc.hardBeats)) ? pc.hardBeats.filter(function (b) { return b && b.description; }) : [];
      if (!beats.length) return '';
      try { console.log('[PLOT-CONTRACT:DIRECTIVE] scene=' + (state.turnCount == null ? '?' : state.turnCount) + ' beats=' + beats.length); } catch (_) {}
      return '\n  PLOT CONTRACT (HARD — this scene MUST LAND these concrete causal beats. The prose may be beautiful, but the STORY does not advance unless these happen. Deliver each through ACTION / DIALOGUE / CONSEQUENCE — never as exposition, never as optional flavor, never skipped to spend words on atmosphere or attraction): '
        + beats.map(function (b) { return '«' + String(b.description) + '»'; }).join('; ')
        + '. These are obligations, not suggestions.\n';
    } catch (_) { return ''; }
  }
  window._buildPlotContractDirective = _buildPlotContractDirective;

  // PLOT-CONTRACT GENERATOR (Roman 2026-06-27, GATED). Skeleton-gen only runs on the legacy
  // path, so contract-gen is a small dedicated gpt-4o-mini call (fires ONLY when the flag is on)
  // run before prompt-build for literary Scene 2+. Produces 1–3 concrete causal hard beats →
  // state._scenePlotContract, which _buildPlotContractDirective then injects at the two roots.
  async function _generateLiteraryPlotContract(act, dia) {
    try {
      var s = window.state || {};
      if (!_plotContractActive()) return;
      // NOTE: this generator only runs from the Scene-2+ submitBtn path (the _literarySceneMandate
      // block), so Scene 1 is already excluded by the call site. Do NOT gate on turnCount here —
      // turnCount lags (0 at the Scene-2 build) and would wrongly skip the generator.
      var sc = s._sceneStateCard || {};
      var rp = s.rPlot || {};
      var milestones = Array.isArray(rp.relationshipMilestones) ? rp.relationshipMilestones.slice(0, 4) : [];
      var pressures = Array.isArray(rp.issuePressures) ? rp.issuePressures.slice(0, 4) : [];
      var goal = (s.aPlot && s.aPlot.goal) || '';
      var sys = 'You are the PLOT-CONTRACT planner for an interactive romance engine. Output the 1–3 CONCRETE CAUSAL HARD BEATS this next scene MUST land so the STORY advances — never atmosphere, never generic emotion, never description, never a "vibe". Each beat must be TESTABLE after the scene (did it literally happen, yes/no) and CAUSAL (it changes what is possible next).\n'
        + 'VALID examples: "PC discovers the forged ledger page in the library"; "Dorian publicly refuses to deny knowing PC"; "the antagonist delivers a midnight deadline forcing PC to choose"; "PC accepts his help but hides the stolen card"; "the rival reveals they know PC lied".\n'
        + 'INVALID — NEVER output these shapes: "make the scene tense"; "deepen the mystery"; "show attraction"; "describe the love interest vividly"; "add gothic atmosphere"; "make him seem dangerous".\n'
        + 'Derive the beats from: the A-plot goal, the outstanding relationship obligations, WHERE the last scene ended, and the player\'s action. Output 1–3 beats (4 ONLY for a climax/turning point). If a beat is tied to a place, set locationBound.\n'
        + 'Return ONLY JSON, no prose: { "hardBeats": [ { "id":"", "type":"plot|relationship|object|reveal|choice|consequence", "description":"", "whyItMatters":"", "locationBound": null, "carryStrategy":"pay_if_plausible_else_adapt", "dropAllowed": false } ] }';
      var usr = 'A-plot goal: ' + JSON.stringify(goal).slice(0, 300)
        + '\nOutstanding relationship milestones: ' + JSON.stringify(milestones).slice(0, 400)
        + '\nIssue pressures: ' + JSON.stringify(pressures).slice(0, 300)
        + '\nWhere the LAST scene ended: ' + JSON.stringify(sc).slice(0, 400)
        + '\nPlayer action: ' + String(act || '').slice(0, 300) + '\nPlayer dialogue: ' + String(dia || '').slice(0, 300)
        + '\nScene index: ' + (s.turnCount || 0);
      var res = await fetch('/api/chatgpt-proxy', { method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ messages: [{ role: 'system', content: sys }, { role: 'user', content: usr }], role: 'PRIMARY_AUTHOR', model: 'gpt-4o-mini', temperature: 0.3, max_tokens: 420, jsonMode: true }) });
      if (!res.ok) return;
      var data = await res.json();
      var content = (data && data.content) || (data && data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content); // proxy returns {content}; OpenAI returns {choices}
      if (!content) return;
      var parsed; try { parsed = JSON.parse(content); } catch (e) { var m = String(content).match(/\{[\s\S]*\}/); if (!m) return; try { parsed = JSON.parse(m[0]); } catch (e2) { return; } }
      var beats = (parsed && Array.isArray(parsed.hardBeats)) ? parsed.hardBeats.filter(function (b) { return b && b.description; }).slice(0, 4) : [];
      beats.forEach(function (b, i) { b.id = 'scene' + (s.turnCount || 0) + '_beat' + (i + 1); b.importance = 'hard'; b.bornScene = (s.turnCount || 0); }); // canonical id (overwrites any LLM-supplied id) so logs/debts are stable across Literary + CG
      state._scenePlotContract = { sceneIndex: (s.turnCount || 0), hardBeats: beats };
      try { console.log('[PLOT-CONTRACT:ENABLED] true'); console.log('[PLOT-CONTRACT:BEATS] scene=' + (s.turnCount || 0) + ' count=' + beats.length); } catch (_) {}
    } catch (_) {}
  }
  window._generateLiteraryPlotContract = _generateLiteraryPlotContract;

  // happened. This feeds the model the prior scene's actual ending tail + hard
  // continuity rules, and (on a live pickup) overrides the anchor's open-from-
  // an-object rule. Sets state._sceneLiveContinuation for buildSkeletonDirective.
  function buildSceneContinuationDirective() {
    try {
      state._sceneLiveContinuation = false;
      if (!_hasPriorRenderedScene()) return '';                  // opening scene → no prior beat (turnCount is unreliable here)
      if (typeof StoryPagination === 'undefined' || !StoryPagination.getAllContent) return '';
      var all = StoryPagination.getAllContent().replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
      if (!all || all.length < 40) return '';
      var ending = all.slice(-600);
      // Sanitize explicit anatomical terms (some continuation paths route to OpenAI).
      ending = ending.replace(/\b(cock|pussy|clit(?:oris)?|nipples?|erect(?:ion)?|orgasm|thrust(?:ing|ed|s)?|moan(?:ing|ed|s)?|grind(?:ing|ed|s)?|penetrat(?:e[ds]?|ion)|cum(?:ming|s)?)\b/gi, '[intimate detail]');
      // Trim to a clean sentence start so the excerpt doesn't begin mid-word.
      var cut = ending.search(/[.!?"”’]\s+[A-Z“"]/);
      if (cut > 0 && cut < ending.length - 60) ending = ending.slice(cut + 1).trim();

      // LIVE-PICKUP detection — did the prior scene end mid-moment (open dialogue,
      // a question, an active phone call)? If so this scene continues that beat
      // rather than resetting to an establishing shot.
      var tail = ending.slice(-240);
      var tailLower = tail.toLowerCase();
      var endsOnDialogue = /["”’]\s*$/.test(ending) || /,\s*["”’]?\s*(?:he|she|they|[A-Z][a-z]+)\s+(?:said|asked|murmured|breathed|whispered|added)\.?["”’]?\s*$/.test(ending);
      var endsOnQuestion = /\?["”’]?\s*$/.test(ending);
      var liveCall = /\b(?:phone|call(?:ing|ed)?|the line|on the line|voicemail|receiver|speaker|dial(?:ed|ing)?|ringing|hung up|hello)\b/.test(tailLower);
      var liveContinuation = endsOnDialogue || endsOnQuestion || liveCall;
      state._sceneLiveContinuation = liveContinuation;

      var d = '\n\nSCENE CONTINUATION (HARD — this scene is a DIRECT CONTINUATION of the story, NOT a fresh start):\n';
      d += 'The previous scene ended here (verbatim tail, for continuity only — do not quote it back): "…' + ending.replace(/"/g, "'") + '"\n';
      d += '  RULES:\n';
      d += '  1. NEVER contradict or silently undo what just happened. If the protagonist just spoke with someone (in person OR by phone), that conversation HAPPENED — do NOT re-stage it as missed / unread / not-yet-occurred, and do NOT re-attribute it to a different character. Carry forward who was present, where, and what was said.\n';
      d += '  2. CARRY THE LIVE THREAD. If the prior scene ended mid-conversation, mid-phone-call, on an unanswered line, or on a question, this scene CONTINUES that exact moment — the protagonist is STILL in it. The player\'s Action/Dialogue is the protagonist\'s response WITHIN this continuing moment, not the start of a new day.\n';
      d += '  3. DO NOT RESET TO AN ESTABLISHING SHOT. Forbidden opening moves when continuing: waking to a new morning, setting down / picking up the phone, checking a notification / voicemail / message, or a fresh "the [light] catches the [surface]" scene-setting beat — UNLESS the player\'s action explicitly creates that time gap. Begin INSIDE the ongoing moment.\n';
      d += '  CAUSAL LINK (HARD — THEREFORE / BUT, never "and then"): this scene must follow from the last as a CONSEQUENCE (therefore: the prior ending + the player\'s action FORCED this situation) or a COMPLICATION (but: a reversal / obstacle / cost the prior moment created). Before the first line, answer "what in the prior scene + the player\'s action FORCES this scene to exist?" and let THAT pressure open it — not a new beat that could have followed any scene. And by the scene\'s end, something must CHANGE that forces the next scene (a choice taken, a truth surfaced, a cost incurred, a line crossed); do not close on a flat beat that leaves the next scene free to be anything.\n';
      if (liveContinuation) {
        d += '  4. LIVE PICKUP DETECTED (the prior scene ended mid-moment — open dialogue / question / active call). This scene OPENS in that live moment and this OVERRIDES the SCENE ENVIRONMENT ANCHOR\'s "first sentence must originate from the anchor" rule: do NOT open from a physical establishing object — continue the live exchange. Any environment anchor may surface LATER, woven into the ongoing action.\n';
      } else {
        d += '  4. If the prior scene ended on a settled emotional beat (not a live exchange), a SMALL time-skip is allowed — but the emotional state and all established facts carry over; never reset to a neutral establishing shot that ignores the prior scene\'s charge.\n';
      }
      // ANTI-REGRESSION (Roman 2026-06-15): if this story opened DEFERRED (PC-owned crisis,
      // LI absent from Scene 1), the Scene-1 crisis must NOT evaporate the moment romance
      // enters. Reaches both literary + CG (this builder feeds both).
      try {
        if ((typeof _liArrival === 'function') && _liArrival(state) === 'DEFERRED') {
          d += '  5. DEFERRED-ARRIVAL CONTINUITY (HARD — this story opened on a PC-OWNED crisis with the love interest absent): the protagonist\'s opening crisis is STILL ACTIVE and unresolved. The love interest\'s arrival must INTERTWINE with that crisis — he enters INTO it (complicating it, colliding with it, pressing on it, or being entangled by it), never erasing or replacing it. FORBIDDEN: the crisis quietly disappears the moment the romance begins ("PC crisis → LI appears → crisis forgotten"). REQUIRED: crisis and romance escalate TOGETHER — the romance is now happening ON TOP OF the still-burning problem, and the crisis keeps costing her something while the attraction builds.\n';
        }
      } catch (_) {}
      // STORY SPINE — Layer 1 (Roman 2026-06-15): this issue's relationship JOB. The
      // UNIVERSAL per-scene path — fires even when no cgScaffold exists. Pacing, not a scene plan.
      try { d += (_buildIssueRelationshipStageDirective(state) || ''); } catch (_) {}
      return d;
    } catch (_) { return ''; }
  }

  // ── PLAYER IMPACT / DIVERGENCE READ (Roman 2026-06-06) ──────────────────────
  // Principle: a Petition/Tempt fate event AND any "wild" say/do are the SAME
  // problem — player input diverged from the plan and the story MUST metabolize
  // it, not smooth it over. This computes one per-turn signal that every layer
  // (staging skeleton + prose writer) reads. TELEMETRY-FIRST on the SPINE: it
  // LOGS when a player move collides with a pending A-plot milestone but does NOT
  // rewrite the milestone array. The SCENE-LEVEL reaction (writer + staging react
  // to the input) IS active, because the plot cannot pretend nothing happened.
  function _impactContentTokens(s) {
    var STOP = new Set(['the','a','an','of','on','in','at','to','and','with','from','its','her','his','their','that','this','as','through','over','into','by','for','i','you','he','she','they','it','me','my','your','him','them','is','was','be','am','are','do','did','does','will','would','could','should','not','no','yes']);
    return new Set(String(s || '').toLowerCase().replace(/[^a-z\s]/g, ' ').split(/\s+/).filter(function (w) { return w.length > 2 && !STOP.has(w); }));
  }
  function _impactTokenOverlap(a, b) {
    var sa = _impactContentTokens(a), sb = _impactContentTokens(b);
    if (!sa.size || !sb.size) return 0;
    var inter = 0; sa.forEach(function (t) { if (sb.has(t)) inter++; });
    return inter / (sa.size + sb.size - inter); // Jaccard
  }
  function _classifyPlayerDivergence(combined) {
    var t = (combined || '').toLowerCase();
    var tags = [];
    if (/\b(shoot|shot|gun|pistol|rifle|knife|stab|stabb\w*|blade|strangle|chok(e|ing|ed)|punch|slap|kill|murder|attack|weapon|throw\w*\s+\w+\s+at|smash|hit\s+(him|her|them))\b/.test(t)) tags.push('violence');
    if (/\b(this is (a|just a)?\s*(game|story|simulation|book|dream|fiction)|you'?re (a|an)\s*(ai|character|narrator|program)|fourth wall|i'?m the (player|reader|author|user)|none of this is real|wake up from)\b/.test(t)) tags.push('world_break');
    if (/\b(the truth is|confess\w*|i'?m actually|i lied|my secret|never told you|admit\w*|i'?m really|i did it|it was me)\b/.test(t)) tags.push('reveal');
    if (/\b(i love you|marry me|leave you|break up|it'?s over|divorce|run away with|propose|i'?m leaving you|never see you again)\b/.test(t)) tags.push('relationship_pivot');
    if (/\b(walk away|leave the room|run\b|flee|hang up|i refuse|i won'?t|get out|storm out|slam the door|ignore (him|her|them)|turn (and )?(go|leave))\b/.test(t)) tags.push('flee_refuse');
    if (/\b(call|phone|text|summon|find|go to|drive to|show up at|bring|fetch|invite|track down)\b/.test(t)) tags.push('summon_or_move');
    return tags;
  }
  function _computePlayerImpactRead(rawAct, rawDia, act, dia, opts) {
    opts = opts || {};
    try {
      var raw = ((rawAct || '') + ' ' + (rawDia || '')).trim();
      // Fate event invoked this turn (Petition/Tempt mid-scene injection or a wish).
      var fate = null;
      if (state._pendingFateChange && state._pendingFateChange.text) {
        fate = { cardType: state._pendingFateChange.cardType || 'fate', text: state._pendingFateChange.text };
      } else if (state.temptFateWish) {
        fate = { cardType: 'tempt_fate', text: String(state.temptFateWish) };
      }
      var tags = _classifyPlayerDivergence(raw);
      var score = 0;
      if (tags.indexOf('violence') >= 0 || tags.indexOf('world_break') >= 0) score = 3;
      else if (tags.indexOf('reveal') >= 0 || tags.indexOf('relationship_pivot') >= 0) score = 2;
      else if (tags.indexOf('flee_refuse') >= 0 || tags.indexOf('summon_or_move') >= 0) score = 1;
      if (fate) score = Math.max(score, 2);
      var mustReact = score >= 2 || tags.indexOf('violence') >= 0 || !!fate;

      // NOTE (Roman 2026-06-06): the old lexical-Jaccard collision-vs-NEXT-milestone
      // was REMOVED — it only checked the immediate pending milestone and missed
      // semantic matches ("Roman calls" vs "Roman finally reaches out" share one
      // token → ~0.2 overlap → missed). Concrete, semantic, ALL-FUTURE-milestone
      // collision telemetry now piggybacks on the post-prose continuity probe
      // (_extractStoryMemory's milestone_collision field, intervention turns only).
      // This read stays a cheap scene-level signal that the probe also consumes.
      var read = {
        raw: { do: (rawAct || '').trim(), say: (rawDia || '').trim() },
        normalized: { do: (act || '').trim(), say: (dia || '').trim() },
        fate: fate, class: tags, divergenceScore: score, mustReact: mustReact,
        atTurn: state.turnCount || 0
      };
      if (!opts.noPersist) {
        state._playerImpactRead = read;
        try {
          console.log('[PLAYER-IMPACT] turn ' + read.atTurn + ' — score=' + score + (tags.length ? ' class=[' + tags.join(',') + ']' : '') + ' mustReact=' + mustReact + (fate ? ' fate=' + fate.cardType : ''));
        } catch (_) {}
      }
      return read;
    } catch (_) { if (!opts.noPersist) state._playerImpactRead = null; return null; }
  }

  // Surfaces the player-impact read to the prose writer (fullSys) AND the staging
  // skeleton planner. Carries the LITERAL input (so a normalization/safety pass
  // that softened it can't make the writer blind to what the player actually did)
  // and a HARD react-don't-smooth mandate, escalated for off-script input.
  function buildPlayerImpactDirective(readOverride) {
    try {
      var r = readOverride || state._playerImpactRead;
      if (!r) return '';
      var doo = (r.raw && r.raw.do) || '';
      var say = (r.raw && r.raw.say) || '';
      if (!doo && !say && !r.fate) return '';
      var d = '\n\nPLAYER MOVE — METABOLIZE, DO NOT SMOOTH OVER (HARD):\n';
      d += 'The player just acted. Their literal input is CANON; the scene MUST react to it proportionally — characters respond in-character, the situation changes shape, consequences begin. Never ignore it, quietly normalize it into something tamer, or write as if it did not happen.\n';
      if (doo) d += '  • PLAYER DID: "' + doo.replace(/"/g, "'").slice(0, 240) + '"\n';
      if (say) d += '  • PLAYER SAID: "' + say.replace(/"/g, "'").slice(0, 240) + '"\n';
      if (r.fate) d += '  • FATE INTERVENTION (' + r.fate.cardType + '): "' + String(r.fate.text || '').replace(/"/g, "'").slice(0, 240) + '" — this CHANGED what would otherwise have happened; treat it as real and let it ripple forward.\n';
      if (r.mustReact) {
        d += '  ↳ HIGH-IMPACT / OFF-SCRIPT INPUT' + (r.class && r.class.length ? ' (' + r.class.join(', ') + ')' : '') + ': this DEVIATES from the expected beat. Do NOT steer back to the planned conversation as if nothing happened — the other character(s) react to THIS, the moment escalates or breaks from the plan, and the scene ends somewhere the plan did not predict. The story bends around the player; the player is not quietly overruled.\n';
      }
      return d;
    } catch (_) { return ''; }
  }
  window.buildPlayerImpactDirective = buildPlayerImpactDirective;

  // NOTE (Roman 2026-06-06b): the spine-collision audit is NO LONGER a dedicated
  // LLM round-trip. It now piggybacks on the post-prose continuity probe
  // (_extractStoryMemory) via a conditional `milestone_collision` schema field that
  // fires only on intervention turns. Same telemetry ([SPINE-COLLISION] + the
  // _spineCollisionLedger feeding the [MILESTONE-REDUNDANCY] check in _tickAPlot),
  // one fewer call. See _extractStoryMemory for the folded-in logic.

  // ── PHRASE ENTROPY GUARD ──
  // Extracts short verb/sensory fragments from scene text to prevent repetition.
  const _PHRASE_STOPWORDS = new Set(['the','a','an','and','but','or','in','on','at','to','for','of','is','was','were','are','be','been','has','had','have','with','that','this','from','they','them','their','she','her','he','him','his','it','its']);

  function extractPhraseFragments(sceneText) {
      if (!sceneText || typeof sceneText !== 'string') return;
      const sentences = sceneText.replace(/["""]/g, '').split(/[.!?]+/).filter(s => s.trim().length > 10);
      const fragments = [];
      for (const sentence of sentences) {
          const words = sentence.trim().split(/\s+/).filter(w => w.length > 2);
          // Sliding window: 3-6 word fragments containing a verb-like word
          for (let len = 3; len <= Math.min(6, words.length); len++) {
              for (let i = 0; i <= words.length - len; i++) {
                  const frag = words.slice(i, i + len);
                  const meaningful = frag.filter(w => !_PHRASE_STOPWORDS.has(w.toLowerCase()));
                  if (meaningful.length >= 2) {
                      fragments.push(frag.join(' ').toLowerCase());
                  }
              }
          }
      }
      // Deduplicate, pick up to 10 most distinctive (longest first)
      const unique = [...new Set(fragments)].sort((a, b) => b.length - a.length).slice(0, 10);
      if (!state.recentPhraseFragments) state.recentPhraseFragments = [];
      state.recentPhraseFragments.push(...unique);
      state.recentPhraseFragments = state.recentPhraseFragments.slice(-20);
  }

  function buildPhraseEntropyDirective() {
      const frags = state.recentPhraseFragments;
      if (!frags || frags.length < 3) return '';
      const sample = frags.slice(-8).map(f => `"${f}"`).join(', ');
      return `\nPHRASE VARIETY CONSTRAINT:\nAvoid repeating recent phrase fragments such as: ${sample}\nUse fresh sentence structures and sensory descriptions.\n`;
  }

  function buildEmotionEmbodimentDirective() {
      return `\nEMOTION EMBODIMENT:\nWhen describing emotion, prefer physical expression over abstract summary. Express through: body movement, breath, posture, hand/eye movement, object interaction, environmental reaction.\nIf an emotional concept appears, precede it with a physical signal.\nAllow emotion through dialogue: "You knew," she said quietly > "She felt betrayed."\n`;
  }

  // ── LAYER 2 — EPOCH STATE RESET ──
  // Clears world-cycle entropy and epoch-level flags.
  // Called ONLY on full world change (resetForNewStory / performAuthReset).
  function _resetEpochState() {
      state.world_cycle_id = null;
      state._syzygyOccurred = false;
      state.world_cycle_label = null;
      state.worldInstanceId = null;
      state.worldName = null;
      state.previousTitle = null;
      state.previousTitleMode = null;
      state.continuationPath = null;
      state.ffAppearance = {}; // First Favored color lock — fresh per new story (L2); survives issues (L3-only resets)
      state.kwisheenAppearance = {}; // Named-Kwisheen color/pattern lock — same lifetime as ffAppearance (L2 reset, survives issues)
      state.pcAppearance = {}; // Deterministic human-PC look fallback (unlocked look) — same lifetime as ffAppearance (L2 reset, survives issues)

      // Clear all entropy axis objects
      const entropyKeys = [
          '_fantasyCoreEntropy', '_modernCoreEntropy', '_smallTownEntropy',
          '_collegeEntropy', '_officeEntropy', '_friendsEntropy',
          '_supernaturalEntropy', '_superheroicEntropy',
          '_historicalCoreEntropy', '_dystopiaCoreEntropy', '_blueBloodEntropy'
      ];
      for (const k of entropyKeys) {
          state[k] = undefined;
      }

      // Blue Blood variant must be cleared alongside its entropy.
      // BlueBlood is the only Modern flavor with a weighted variant system
      // (royal 85% / aristocratic 15%) that gates variant-specific entropy axes
      // and structural contract injection. If entropy is cleared but variant
      // persists, the next story silently reuses the old variant without reroll.
      state._blueBloodVariant = undefined;
      state._blueBloodVariantRerolled = false; // dev diagnostic reset
  }

  // ── LAYER 1 — REGION PHYSICS RESET ──
  // Clears Fantasy region invariants (governance, seat, magic bias, etc.).
  // Called ONLY on full world change (resetForNewStory / performAuthReset).
  function _resetRegionPhysics() {
      state.fantasyRegion = undefined;
      state.fantasyRegionSeat = undefined;
      state.fantasyRegionGovernance = undefined;
      state.fantasyRegionStatus = undefined;
      state.fantasyRegionReality = undefined;
      state.fantasyMagicExpressionBias = undefined;
      state._fatelandsCurrentLocation = undefined;
      state._regionSource = undefined;
      // Identity is NOT cleared here — see _resetIdentityState()
      // Region changes (e.g. travel) should preserve species identity
  }

  // ── L0 META STATE RESET ──
  // Sits ABOVE Layer 1 (Region Physics) in the state hierarchy.
  // Holds the recursive Simulation meta-world wrapper: an underlay cosmology
  // that persists while activeWorld (host frame) swaps between books.
  //
  // CRITICAL: called ONLY from performAuthReset. NEVER from resetForNewStory,
  // _resetRegionPhysics, _resetEpochState, _resetStoryState, startBook2, or
  // startNewInWorld. The meta-world is the one thing that must survive every
  // intra-story reset — including Book 1 → Book 2 host-frame swaps.
  function _resetMetaState() {
      state.metaWorld = null;          // 'simulation' | null
      state.activeWorld = null;        // Host frame the player is currently inside (e.g. 'prehistoric')
      // Reserved for later phases — declared here for shape stability:
      state.simulationLayerDepth = 0;
      state.simulationAwareness = 0;   // 0=fully immersed … 5=recursive cosmology awareness
      state.simulationLeakageLevel = 0;
      state.frameBreachProgress = 0;
      state.operatorAwareness = 0;
      state.recursiveResonanceLedger = [];
      state.sharedContinuityArtifacts = [];
  }

  // ── L0 META-WORLD OVERLAY APPLIER ──
  // Called whenever a story's worldSubtype is committed (shape commit / restore /
  // any other story-start path). Configures the L0 meta-world wrapper based on
  // the committed subtype.
  //
  // For Phase 1: only 'simulation' is a meta-world. Book 1 is LOCKED to
  // Prehistoric (no override). Any non-simulation subtype clears any lingering
  // simulation meta state from a prior story (auth reset clears it too, but a
  // mid-session story switch needs an inline clear too).
  function _applyMetaWorldOverlay(subtype) {
      if (subtype === 'simulation') {
          state.metaWorld = 'simulation';
          state.activeWorld = 'prehistoric';   // Book 1 locked — see project_simulation_cosmology_canon
          state.simulationLayerDepth = 0;
          state.simulationAwareness = 0;
          state.simulationLeakageLevel = 0;
          state.frameBreachProgress = 0;
          state.operatorAwareness = 0;
          state.recursiveResonanceLedger = [];
          state.sharedContinuityArtifacts = [];
      } else if (state.metaWorld === 'simulation') {
          // Different worldSubtype committed — the player chose a non-simulation
          // cosmology. Clear stale meta-world wrapper.
          _resetMetaState();
      }
  }
  // Exposed for orchestration helpers and the directive builders that need to
  // re-derive meta state defensively if a save predates this field.
  window._applyMetaWorldOverlay = _applyMetaWorldOverlay;

  // ── IDENTITY STATE RESET ──
  // Clears all species, LI, reveal, reaction, and Thornwild transformation state.
  // Called ONLY on full story reset or new story start — never on region travel.
  function _resetIdentityState() {
      // Species identity
      state._playerSpecies = undefined;
      state._identityLock = undefined;
      state._speciesSource = undefined;
      state._isHybrid = undefined;
      // LI species
      state._liSpecies = undefined;
      state._liSpeciesSource = undefined;
      // LI cultural origin region (independent of species — drives
      // region-keyed speech layers like Shackle Isles maritime patois).
      // Defaults to fantasyRegion at story init when not explicitly set.
      state._liOriginRegion = undefined;
      // Per-NPC species table (named secondary characters). Reset
      // alongside LI species so a fresh story starts with no inherited
      // classifications. See _classifyNPCSpecies / _recordNPCSighting.
      if (typeof window._resetNPCSpeciesTable === 'function') {
        try { window._resetNPCSpeciesTable(state); } catch (_) {}
      } else {
        state.npcSpecies = {};
      }
      // Historical culture profile — cleared per story so a new story
      // re-classifies from its own worldCustomText. See
      // _resolveHistoricalCultureProfile / _HISTORICAL_CULTURE_ROSTER.
      if (typeof window._resetHistoricalCultureProfile === 'function') {
        try { window._resetHistoricalCultureProfile(state); } catch (_) {}
      } else {
        state._historicalCultureProfile = null;
        state._histCultureLLMInflight = {};
      }
      state._relationshipRiskLevel = undefined;
      // Thornwild transformation
      state._thornwildPath = undefined;
      state._thornwildStage = undefined;
      state._firstSignTriggered = undefined;
      state._firstSignType = undefined;
      state._thornwildCureTaboo = undefined;
      state._transformationPressure = undefined;
      state._pressureStage = undefined;
      state._criticalCountdown = undefined;
      state._lastPressureExprCategory = undefined;
      state._exprRecent = undefined;
      state._sceneExprCategory = undefined;
      state._sceneExprTurn = undefined;
      // ── Typed System Registry — set by scene driver, NOT model ──
      // Three layers: narrativeActors (affect events), worldSystems (affect environment),
      // narrativeVoice (affect narration style). Injection order: actors → world → voice.
      if (!state.systems) state.systems = {};
      state.systems.narrativeActors = {
        weaver: { active: false, encounterCount: 0 },
        keepers: { presence: 'none', encounterCount: 0 },
        reliquary: { active: false, encounterCount: 0 },
        commoner: { active: false, encounterCount: 0 },
        parasite: { active: false, encounterCount: 0 },
        absolvers: { active: false, encounterCount: 0 }
      };
      state.systems.worldSystems = {
        chorus: { active: false, tier: 0 }
        // veilwood, ashenVerge — future migration
      };
      state.systems.narrativeVoice = {
        pov4th: { active: false, chorusOverride: false },
        pov5th: { active: false }
      };
      // Legacy aliases — keep until all consumers migrate
      state._weaverActive = false;
      state._weaverEncounterCount = 0;
      state._keeperPresence = 'none';
      state._keeperEncounterCount = 0;
      // Thornwild response / flight
      state._thornwildResponse = undefined;
      state._isRootless = undefined;
      state._escapeTarget = undefined;
      // Reset relationship state (includes reveal, suspicion, transit)
      _resetRelationshipState();
  }

  // ── RELATIONSHIP STATE RESET ──
  // Clears reveal, suspicion, reaction, transit, pressure, and encounter state.
  // Called ONLY on full story reset or new story start — never mid-story.
  function _resetRelationshipState() {
      // Reveal engine
      state._identityRevealed = undefined;
      state._revealEligible = undefined;
      state._revealTrigger = undefined;
      // Post-reveal reaction
      state._liReactionState = undefined;
      state._liReactionLocked = undefined;
      state._liReactionLockScenes = undefined;
      // Suspicion
      state._liSuspicionLevel = undefined;
      state._liSuspicionTriggers = undefined;
      state._liPreRevealBelief = undefined;
      state._relationshipHistory = undefined;
      // Transit
      state._isInTransit = undefined;
      state._transitOrigin = undefined;
      state._transitDestination = undefined;
      state._transitProgress = undefined;
      state._almostCaughtTriggered = undefined;
      state._transitInterrupted = undefined;
      state._pursuitLevel = undefined;
      // Travel pressure
      state._travelPressure = undefined;
      state._encounterCooldown = undefined;
      // Scene driver
      state._sceneDriver = undefined;
      state._sceneDriverCooldowns = undefined;
      state._sceneDriverBlend = undefined;
      state._driverUsageHistory = undefined;
      state._encounterStarvationCounter = undefined;
      state._postRevealSceneCount = undefined;
      state._driverLastForced = undefined;
      state._driverForceCooldown = undefined;
      state._encounterGrace = undefined;
      state._encounterNearMisses = undefined;
      state._encounterHardForced = undefined;
  }

  // Shared: mount generated scene + wire interstitial continue button
  function _mountAndTransition(title, synopsis, body, interstitial, continueBtn, statusEl, label) {
      StoryPagination.init();
      StoryPagination.clear();
      body = sanitizeFatelandsUnits(body);
      StoryPagination.addPage(formatStory(body), true);
      state.turnCount = 1;
      state.scenes = state.scenes || [];
      state.scenes.push({ title, synopsis, text: body, fateCard: null });
      try { if (typeof window._sbBetaSceneDone === 'function') window._sbBetaSceneDone(body); } catch (_) {}

      if (statusEl) statusEl.textContent = label + ' ready';
      if (continueBtn) {
          continueBtn.textContent = 'Continue to ' + label;
          continueBtn.classList.remove('hidden');
          continueBtn.onclick = function() {
              if (interstitial) interstitial.classList.add('hidden');
              window.showScreen('game');
              showReaderPage(2);
              if (!state._titlePageShown) showTitlePage();
              if (window.dealFateCards) window.dealFateCards();
              if (window.initFateCards) window.initFateCards();
              document.getElementById('submitBtn').disabled = false;
              saveStorySnapshot();
              console.log('[' + label.toUpperCase() + '] Mounted and Title page shown');
          };
      }
  }

  // ════════════════════════════════════════════════════════════════════
  // START BOOK 2 — Sequel: same characters, same world
  // ════════════════════════════════════════════════════════════════════

  window.startBook2 = async function() {
      // Reentrancy guard — prevent double-click / concurrent execution
      if (state._isTransitioning) return;
      state._isTransitioning = true;
      const btn = document.getElementById('btnStartBook2');
      if (btn) btn.disabled = true;

      console.log('[BOOK2] Starting Book 2 flow');

      // Snapshot everything BEFORE any mutation or async work
      const lockedChars = state.main_characters_locked;
      const lockedPicks = { ...state.picks };
      const lockedWorld = state.picks?.world;
      const lockedTone = state.picks?.tone;
      const lockedFlavor = state.picks?.flavor;
      const lockedGenre = state.picks?.genre;
      const lockedArchetype = state.archetype ? { ...state.archetype } : { primary: 'BEAUTIFUL_RUIN', modifier: null };
      const lockedIntensity = state.intensity;
      const seriesId = state.series_id;
      const bookNumber = (state.book_number || 1) + 1;
      const previousTitle = state.immutableTitle || state.story?.title || 'Untitled';
      const continuitySummary = state.book1_continuity_summary;
      const lockedCycleLabel = state.world_cycle_label;
      const baseSysPrompt = state.sysPrompt || '';

      // Archive + show interstitial (safe — does not mutate core state)
      let interstitial, continueBtn, statusEl, book1StoryId;
      try {
          const archive = await _archiveAndShowInterstitial();
          book1StoryId = archive.book1StoryId;
          interstitial = archive.interstitial;
          continueBtn = archive.continueBtn;
          statusEl = archive.statusEl;
      } catch (archiveErr) {
          console.error('[BOOK2] Archive failed:', archiveErr);
          state._isTransitioning = false;
          if (btn) btn.disabled = false;
          return;
      }

      // Generate Book 2 title + blurb + Scene 1 — NO state mutation until success
      try {
          if (statusEl) statusEl.textContent = 'Composing next issue title…';
          const titleResult = await callChat([{role:'user', content:`Generate a title for Book 2 of a romance series.

Book 1 title: "${previousTitle}"
World: ${lockedWorld}
Tone: ${lockedTone}
Genre/Flavor: ${lockedGenre}/${lockedFlavor}

RULES:
- Echo Book 1's title pattern/style (if "X of Y", use similar structure; if "The ___", echo that)
- Must feel like a natural sequel — connected but distinct
- Do NOT include "Book 2" or "Book II" in the title text
- Keep under 8 words
- Return ONLY the title, no quotes, no explanation`}]);
          let book2Title = (titleResult || 'Untitled').trim().replace(/^["']|["']$/g, '');
          // F3 (Roman 2026-07-03): the title callChat sometimes ignores "Return ONLY the title" and returns
          // scene prose (observed: a full scene with UNRELATED characters). Sanitize — a title is short,
          // one line, no dialogue/paragraphs, and only names THIS couple. On any failure, fall back
          // deterministically to Book 1's core title (the arcTitle system replaces the working title later).
          try {
            const _knownNames = [lockedChars && lockedChars.playerName, lockedChars && lockedChars.partnerName]
              .filter(Boolean).map(function (n) { return String(n).toLowerCase(); });
            const _titleBad = (function (t) {
              if (!t || t.length < 2) return 'empty';
              if (t.split(/\s+/).length > 8) return 'too_long';
              if (/\n/.test(t) || /[.!?].*[.!?]/.test(t)) return 'multi_sentence';
              if (/["'“”].*\b(said|asked|murmured|whispered|replied)\b/i.test(t)) return 'dialogue';
              const _caps = (t.match(/\b[A-Z][a-z]{2,}\b/g) || []).filter(function (w) {
                return ['The','And','Of','For','With','Into','From','Book','II','III'].indexOf(w) < 0 && _knownNames.indexOf(w.toLowerCase()) < 0;
              });
              if (_caps.length > 3) return 'unrelated_names';
              if (typeof validateTitle === 'function') { try { if (!validateTitle(t, lockedTone).valid) return 'validateTitle'; } catch (_) {} }
              return null;
            })(book2Title);
            if (_titleBad) {
              const _base = String(previousTitle || '').replace(/["'“”]/g, '').replace(/\s*[:—–-].*$/, '').trim() || 'The Story';
              book2Title = _base;
              console.log('[BOOK2:TITLE] gen output rejected (' + _titleBad + ') — deterministic fallback: "' + book2Title + '"');
            }
          } catch (_) {}

          if (statusEl) statusEl.textContent = 'Writing next issue opening…';

          const blurbResult = await callChat([{role:'user', content:`Write a back-cover blurb for Book 2 of a romance series.

Book 1 title: "${previousTitle}"
Book 2 title: "${book2Title}"
World: ${lockedWorld}, Tone: ${lockedTone}
Characters: ${lockedChars.playerName} and ${lockedChars.partnerName}

Book 1 ended with:
${(continuitySummary || '').slice(0, 500)}

RULES:
- 2-4 short paragraphs
- Reference unresolved threads from Book 1 without exposition dumping
- Hook + tension + promise
- NO "In Book 1..." or "Previously..." framing
- Tone must match: ${lockedTone}
- Write like a bestseller's back cover

Return ONLY the blurb paragraphs:`}]);
          const blurbText = (blurbResult || '').trim();

          // Append Book 2 continuation context to system prompt
          const book2SysAddendum = `

═══════════════════════════════════════════════════
BOOK 2 CONTINUATION CONTEXT (INTERNAL — never expose to reader)
═══════════════════════════════════════════════════
This is Book ${bookNumber} of an ongoing series. The same protagonists continue.
Protagonist: ${lockedChars.playerName} (${lockedChars.playerGender}, ${lockedChars.playerPronouns})
Love Interest: ${lockedChars.partnerName} (${lockedChars.partnerGender}, ${lockedChars.partnerPronouns})

BOOK 1 ENDING SUMMARY:
${continuitySummary || 'Book 1 ended. Continue the story.'}

CONTINUATION RULES:
- Do NOT reset relationships. Characters remember everything from Book 1.
- Do NOT reintroduce origins or backstories as if the reader is new.
- Start with a new inciting complication that logically follows Book 1's ending.
- Maintain the emotional continuity — if they were together, they are still together; if strained, still strained.
- The tone, world, and dynamic constraints remain identical.
═══════════════════════════════════════════════════
`;
          // i18n (Roman 2026-07-10): Book-2 follows the GLOBAL userLanguage like any other generation. At
          // this point turnCount is still Book-1's (>0) and state.storyLanguage is Book-1's creation language,
          // so _buildLanguageDirective() auto-emits the CONTINUATION directive when the user switched language
          // between books (continue in the new language, preserve facts/names/canon, don't rewrite Book 1),
          // and '' when English→English (existing behavior unchanged).
          const _book2Lang = (typeof _buildLanguageDirective === 'function') ? _buildLanguageDirective() : '';
          const newSysPrompt = baseSysPrompt + book2SysAddendum + _book2Lang;

          let sceneText = await callChat([
              { role: 'system', content: newSysPrompt },
              { role: 'user', content: `Write Scene 1 of Book ${bookNumber} — a direct continuation of Book 1.

The reader already knows these characters intimately. Begin with a new situation, complication, or shift that picks up from where Book 1 left off.

Include at the start of your response:
[TITLE: "${book2Title}"]
[SYNOPSIS: "Back-cover jacket blurb for the OPENING ARC of this story (its first issue) — NOT a recap of scene 1's literal action. Rise above the opening beat: in evocative, enticing book-jacket marketing voice (2-3 sentences, ~35-60 words, present tense), name the central predicament and the stakes closing in across this opening arc, anchored in one concrete world-detail. END ON A HALF-CLIFFHANGER — a question, threat, or threshold left hanging, never resolved. Do NOT center the love interest or romance; do NOT reveal outcomes or spoilers. Do NOT mention or anchor on a tarot deck, tarot/fortune cards, fortune-telling, or 'Fate' as an object/mechanic — that is Storybound's meta framing, NOT this story's premise. Anchor the concrete world-detail in the A-plot itself (the real conflict, place, role, or object that drives the plot)."]

Then write the scene prose (800-1200 words).

Do NOT summarize Book 1. Do NOT reintroduce characters. Jump straight into the new story.` }
          ]);

          const { synopsis, blurb: parsedBlurb, body } = parseScene1Response(sceneText);
          // Headless test capture (harness only): stash the generated Book-2 Scene-1 prose so it survives
          // even if the DOM mount below throws without a live page. Never set in prod.
          try { if (typeof window !== 'undefined' && window._book2TestBypass) { state._book2TestSceneBody = body; state._book2TestRawSceneText = sceneText; } } catch (_) {}

          // ── ALL ASYNC WORK COMPLETE — now commit state reset ──
          // ── RELATIONSHIP CONTINUITY (Roman 2026-06-15): Book 2 / next issue
          // is the SAME couple. _resetStoryState() blanks the relationship to
          // 'strangers' (intimacyPhase→false, attraction anchors cleared),
          // directly contradicting the "maintain emotional continuity" prose
          // addendum built above. Snapshot the lived relationship-progression
          // state and restore it AFTER the reset so an issue boundary never
          // resets the couple to strangers. (new-in-world / new-story paths do
          // NOT do this — those are a fresh couple and SHOULD reset.)
          var _carriedRel = {
              relationship_phase: state.relationship_phase,
              relationshipPhase:  state.relationshipPhase,
              intimacyPhase:      state.intimacyPhase,
              attraction:         state.attraction,
              attractionMemory:   state.attractionMemory,
              attractionMisread:  state.attractionMisread,
              storySpine:         state.storySpine,  // run-level pattern identity — same run, keep its shape/arc
              _prefMemory:        state._prefMemory   // reader-preference memory — same couple keeps their learned taste (Issue 2 remembers Issue 1's axes)
          };
          _resetStoryState();
          if (_carriedRel._prefMemory)        state._prefMemory        = _carriedRel._prefMemory;
          if (_carriedRel.storySpine)         state.storySpine         = _carriedRel.storySpine;
          if (_carriedRel.relationship_phase) state.relationship_phase = _carriedRel.relationship_phase;
          if (_carriedRel.relationshipPhase)  state.relationshipPhase  = _carriedRel.relationshipPhase;
          if (_carriedRel.intimacyPhase)      state.intimacyPhase      = _carriedRel.intimacyPhase;
          if (_carriedRel.attraction)         state.attraction         = _carriedRel.attraction;
          if (_carriedRel.attractionMemory)   state.attractionMemory   = _carriedRel.attractionMemory;
          if (_carriedRel.attractionMisread)  state.attractionMisread  = _carriedRel.attractionMisread;
          console.log('[ISSUE-CONTINUITY] carried relationship_phase=' + state.relationship_phase + ' intimacyPhase=' + state.intimacyPhase + ' across issue boundary');
          // Book 2 is a continuation issue in the same publication run —
          // share state.issueNumber (anthology id), increment within-run index.
          // state.issueNumber is NOT cleared by _resetStoryState, so claims
          // from Book 1 carry forward automatically.
          state.issueIndexInRun = (Number.isInteger(state.issueIndexInRun) && state.issueIndexInRun > 0 ? state.issueIndexInRun : 1) + 1;
          // Defensive restore of epoch state (already preserved, but safety net)
          state.world_cycle_label = lockedCycleLabel;
          state.book_number = bookNumber;
          state.series_id = seriesId;
          state.previous_story_id = book1StoryId;
          state.main_characters_locked = lockedChars;
          state.book1_continuity_summary = continuitySummary;
          state.picks = lockedPicks;
          // silent_apply: pre-tune this continuation issue from the couple's remembered taste (Issue 2
          // opens already tuned; series_id + _prefMemory are restored by now, so the resolver silent-
          // applies same-series high-confidence axes instead of re-onboarding).
          try { if (typeof _applyRememberedPreferences === 'function') _applyRememberedPreferences(); } catch (_) {}
          state.picks.identity = {
              playerName: lockedChars.playerName,
              partnerName: lockedChars.partnerName,
              displayPlayerName: lockedChars.displayPlayerName,
              displayPartnerName: lockedChars.displayPartnerName
          };
          state.archetype = lockedArchetype;
          state.intensity = lockedIntensity;
          state.gender = lockedChars.playerGender;
          state.loveInterest = lockedChars.partnerGender;
          state.previousTitle = previousTitle;
          state.continuationPath = 'continue';
          state.immutableTitle = book2Title;
          state.book_subhead = null;
          state.sysPrompt = newSysPrompt;
          state._synopsisBlurb = blurbText;
          state.story = state.story || {};
          state.story.title = book2Title;
          if (synopsis) state._synopsisMetadata = synopsis;
          if (parsedBlurb && !state._synopsisBlurb) state._synopsisBlurb = parsedBlurb;

          clearStoryContent();
          document.getElementById('storyTitle').textContent = book2Title;
          applyStoryTitleTooltips();

          _mountAndTransition(book2Title, synopsis, body, interstitial, continueBtn, statusEl, 'Book 2');
          state._isTransitioning = false;
          console.log('[BOOK2] Book 2 generation complete: "' + book2Title + '"');

      } catch (err) {
          console.error('[BOOK2] Generation failed:', err);
          state._isTransitioning = false;
          if (btn) btn.disabled = false;
          if (statusEl) statusEl.textContent = 'Generation failed. Please try again.';
          if (continueBtn) {
              continueBtn.textContent = 'Try Again';
              continueBtn.classList.remove('hidden');
              continueBtn.onclick = function() {
                  if (interstitial) interstitial.classList.add('hidden');
                  window.startBook2();
              };
          }
      }
  };

  // ════════════════════════════════════════════════════════════════════
  // NEW STORY IN THIS WORLD — New characters, same world/pov/length
  // ════════════════════════════════════════════════════════════════════

  window.startNewInWorld = async function() {
      // Reentrancy guard — prevent double-click / concurrent execution
      if (state._isTransitioning) return;
      state._isTransitioning = true;
      const btn = document.getElementById('btnNewInWorld');
      if (btn) btn.disabled = true;

      console.log('[NEW-WORLD] Starting new story in same world');

      // Snapshot everything BEFORE any mutation or async work
      const lockedWorld = state.picks?.world;
      const lockedPov = state.picks?.pov;
      const lockedTone = state.picks?.tone;
      const lockedFlavor = state.picks?.flavor;
      const lockedGenre = state.picks?.genre;
      const lockedEra = state.picks?.era;
      const lockedIntensity = state.intensity;
      const lockedStoryLength = state.storyLength;
      const lockedWorldSubtype = state.picks?.worldSubtype;
      const lockedWorldCustomText = state.worldCustomTexts;
      const previousTitle = state.immutableTitle || state.story?.title || 'Untitled';
      const baseSysPrompt = state.sysPrompt || '';
      const previousPressure = state.picks?.pressure;
      const previousDynamic = state.picks?.dynamic;

      // Auto-pick new Story Pull (different from previous if possible)
      const ALL_PRESSURES = ['PowerControl', 'EscapePursuit', 'DesireObsession', 'Survival', 'RiskExposure', 'ObligationBurden', 'ReckoningPast', 'Transformation'];
      const otherPressures = ALL_PRESSURES.filter(p => p !== previousPressure);
      const newPressure = otherPressures[Math.floor(Math.random() * otherPressures.length)];

      // Auto-pick new Story Polarity (different from previous if possible)
      const ALL_DYNAMICS = ['Friends', 'Enemies', 'SecondChance', 'Forbidden', 'Proximity', 'SecretIdentity'];
      const otherDynamics = ALL_DYNAMICS.filter(d => d !== previousDynamic);
      const newDynamic = otherDynamics[Math.floor(Math.random() * otherDynamics.length)];

      // Auto-pick new archetype (LI mask)
      const ALL_ARCHETYPES = ['HEART_WARDEN', 'OPEN_VEIN', 'SPELLBINDER', 'ARMORED_FOX', 'DARK_VICE', 'BEAUTIFUL_RUIN', 'ETERNAL_FLAME'];
      const newArchetype = ALL_ARCHETYPES[Math.floor(Math.random() * ALL_ARCHETYPES.length)];

      // Auto-pick new character names
      const FEMALE_NAMES = ['Elara Vance', 'Cassandra Wells', 'Mira Thornwood', 'Vivian Blake', 'Cordelia Hart', 'Aurelia Stone', 'Seraphina Cole', 'Isadora Crane', 'Helena Frost', 'Rosalind Grey', 'Celestine Moore', 'Evangeline Price', 'Lydia Sterling', 'Ophelia Dane', 'Tatiana West'];
      const MALE_NAMES = ['Sebastian Blackwood', 'Julian Ashford', 'Marcus Thorne', 'Alexander Crane', 'Dominic Vale', 'Lucian Grey', 'Theodore Sterling', 'Maximilian Drake', 'Gabriel Frost', 'Benedict Hale', 'Damien Cross', 'Vincent Ashmore', 'Nathaniel Wolfe', 'Adrian Sinclair', 'Dorian Vance'];

      // Randomize genders for new characters
      const genders = ['Female', 'Male'];
      const playerGender = genders[Math.floor(Math.random() * genders.length)];
      const partnerGender = genders[Math.floor(Math.random() * genders.length)];

      const playerNames = playerGender === 'Female' ? FEMALE_NAMES : MALE_NAMES;
      const partnerNames = partnerGender === 'Female' ? FEMALE_NAMES : MALE_NAMES;
      const newPlayerName = playerNames[Math.floor(Math.random() * playerNames.length)];
      let newPartnerName = partnerNames[Math.floor(Math.random() * partnerNames.length)];
      while (newPartnerName === newPlayerName) {
          newPartnerName = partnerNames[Math.floor(Math.random() * partnerNames.length)];
      }

      // Derive pronouns from gender
      const playerPronouns = playerGender === 'Female' ? 'She/Her' : playerGender === 'Male' ? 'He/Him' : 'They/Them';
      const partnerPronouns = partnerGender === 'Female' ? 'She/Her' : partnerGender === 'Male' ? 'He/Him' : 'They/Them';

      // Derive author gender/pronouns (same logic as corridor)
      let authorGender, authorPronouns;
      if (playerGender === 'Male' && partnerGender === 'Female') { authorGender = 'Female'; authorPronouns = 'She/Her'; }
      else if (playerGender === 'Male' && partnerGender === 'Male') { authorGender = 'Male'; authorPronouns = 'He/Him'; }
      else if (playerGender === 'Female' && partnerGender === 'Female') { authorGender = 'Female'; authorPronouns = 'She/Her'; }
      else { authorGender = 'Non-Binary'; authorPronouns = 'They/Them'; }

      // Archive + show interstitial (safe — does not mutate core state)
      let interstitial, continueBtn, statusEl;
      try {
          const archive = await _archiveAndShowInterstitial();
          interstitial = archive.interstitial;
          continueBtn = archive.continueBtn;
          statusEl = archive.statusEl;
      } catch (archiveErr) {
          console.error('[NEW-WORLD] Archive failed:', archiveErr);
          state._isTransitioning = false;
          if (btn) btn.disabled = false;
          return;
      }

      // Generate title + blurb + Scene 1 — NO state mutation until success
      try {
          if (statusEl) statusEl.textContent = 'Generating new story title...';

          const titleResult = await callChat([{role:'user', content:`Generate a title for a new romance novel set in the same world as "${previousTitle}".

World: ${lockedWorld}
Tone: ${lockedTone}
Genre/Flavor: ${lockedGenre}/${lockedFlavor}
Dynamic: ${newDynamic}

RULES:
- Echo the tone/style of "${previousTitle}" (if poetic, stay poetic; if punchy, stay punchy)
- This is NOT a sequel — new characters, new story
- Keep under 8 words
- Return ONLY the title, no quotes, no explanation`}]);
          const baseTitle = (titleResult || 'Untitled').trim().replace(/^["']|["']$/g, '');

          if (statusEl) statusEl.textContent = 'Writing opening scene...';

          const blurbResult = await callChat([{role:'user', content:`Write a back-cover blurb for a new romance novel.

Title: "${baseTitle}"
World: ${lockedWorld}, Tone: ${lockedTone}, Dynamic: ${newDynamic}
Protagonist: ${newPlayerName} (${playerGender})
Love Interest: ${newPartnerName} (${partnerGender})

RULES:
- 2-4 short paragraphs
- Hook + tension + promise
- This is a standalone novel, not a sequel
- Tone must match: ${lockedTone}
- Write like a bestseller's back cover

Return ONLY the blurb paragraphs:`}]);
          const blurbText = (blurbResult || '').trim();

          // Build system prompt for new story (reuse base but strip any Book 2 addenda)
          // i18n (Roman 2026-07-10): a STANDALONE new-in-world story follows the global userLanguage with the
          // NORMAL directive (forceFresh — the prior story's stale turnCount/storyLanguage must not trigger the
          // continuation clause here). '' for English → existing behavior unchanged.
          const cleanSys = baseSysPrompt.replace(/═+\nBOOK 2 CONTINUATION CONTEXT[\s\S]*?═+\n?/g, '') +
              ((typeof _buildLanguageDirective === 'function') ? _buildLanguageDirective(null, { forceFresh: true }) : '');

          let sceneText = await callChat([
              { role: 'system', content: cleanSys },
              { role: 'user', content: `Write Scene 1 of a new romance novel set in ${lockedWorld}.

Protagonist: ${newPlayerName} (${playerGender}, ${playerPronouns})
Love Interest: ${newPartnerName} (${partnerGender}, ${partnerPronouns}) — a ${newArchetype.replace(/_/g, ' ').toLowerCase()} archetype
Dynamic: ${newDynamic}
Story Pull: ${newPressure}

This is a STANDALONE story — no returning characters, no sequel continuity.

Include at the start of your response:
[TITLE: "${baseTitle}"]
[SYNOPSIS: "Back-cover jacket blurb for the OPENING ARC of this story (its first issue) — NOT a recap of scene 1's literal action. Rise above the opening beat: in evocative, enticing book-jacket marketing voice (2-3 sentences, ~35-60 words, present tense), name the central predicament and the stakes closing in across this opening arc, anchored in one concrete world-detail. END ON A HALF-CLIFFHANGER — a question, threat, or threshold left hanging, never resolved. Do NOT center the love interest or romance; do NOT reveal outcomes or spoilers. Do NOT mention or anchor on a tarot deck, tarot/fortune cards, fortune-telling, or 'Fate' as an object/mechanic — that is Storybound's meta framing, NOT this story's premise. Anchor the concrete world-detail in the A-plot itself (the real conflict, place, role, or object that drives the plot)."]

Then write the scene prose (800-1200 words). Introduce both characters and establish the central tension.` }
          ]);

          const { synopsis, blurb: parsedBlurb, body } = parseScene1Response(sceneText);

          // ── ALL ASYNC WORK COMPLETE — now commit state reset ──
          _resetStoryState();
          // New-in-world is a fresh publication run — new anthology continuity.
          // Clear any anthology id claimed by the previous run so the new
          // story renders "#?.1" until its own completion-claim allocates.
          state.issueIndexInRun = 1;
          state.issueNumber = null;
          state.issueFlavor = null;
          state.issueIsGenesis = false;
          state.book_number = 1;
          state.series_id = null;
          state.previous_story_id = null;
          state.main_characters_locked = null;
          state.book1_continuity_summary = null;

          // Restore world/pov/length
          state.picks = state.picks || {};
          state.picks.world = lockedWorld;
          state.picks.pov = lockedPov;
          state.picks.tone = lockedTone;
          state.picks.flavor = lockedFlavor;
          state.picks.genre = lockedGenre;
          state.picks.era = lockedEra;
          state.picks.worldSubtype = lockedWorldSubtype;
          state.worldCustomTexts = lockedWorldCustomText;
          state.intensity = lockedIntensity;
          state.storyLength = lockedStoryLength;

          // Set new auto-chosen values
          state.picks.pressure = newPressure;
          state.picks.dynamic = newDynamic;
          state.archetype = { primary: newArchetype, modifier: null };
          state.gender = playerGender;
          state.authorGender = authorGender;
          state.authorPronouns = authorPronouns;
          state.loveInterest = partnerGender;
          state.picks.identity = {
              playerName: newPlayerName,
              partnerName: newPartnerName,
              displayPlayerName: newPlayerName,
              displayPartnerName: newPartnerName
          };
          state.continuationPath = 'new_world';
          state.immutableTitle = baseTitle;
          state.book_subhead = 'In the world of ' + previousTitle;
          state.previousTitle = previousTitle;
          state.sysPrompt = cleanSys;
          state._synopsisBlurb = blurbText;
          state.story = state.story || {};
          state.story.title = baseTitle;
          if (synopsis) state._synopsisMetadata = synopsis;
          if (parsedBlurb && !state._synopsisBlurb) state._synopsisBlurb = parsedBlurb;

          clearStoryContent();
          document.getElementById('storyTitle').textContent = baseTitle;
          applyStoryTitleTooltips();

          _mountAndTransition(baseTitle, synopsis, body, interstitial, continueBtn, statusEl, 'New Story');
          state._isTransitioning = false;
          console.log('[NEW-WORLD] New story generation complete: "' + baseTitle + '"');

      } catch (err) {
          console.error('[NEW-WORLD] Generation failed:', err);
          state._isTransitioning = false;
          if (btn) btn.disabled = false;
          if (statusEl) statusEl.textContent = 'Generation failed. Please try again.';
          if (continueBtn) {
              continueBtn.textContent = 'Try Again';
              continueBtn.classList.remove('hidden');
              continueBtn.onclick = function() {
                  if (interstitial) interstitial.classList.add('hidden');
                  window.startNewInWorld();
              };
          }
      }
  };

  // Show cover from End Page (reuses existing cover display)
  window.showCoverFromEndPage = function() {
      const coverImg = document.getElementById('bookCoverImg');
      if (coverImg && coverImg.src) {
          const bookCoverPage = document.getElementById('bookCoverPage');
          const bookObject = document.getElementById('bookObject');
          const storyContent = document.getElementById('storyContent');
          if (bookCoverPage) bookCoverPage.classList.remove('hidden');
          if (bookObject) bookObject.classList.remove('hidden');
          if (storyContent) storyContent.classList.add('hidden');
          try { if (typeof renderIssueBadge === 'function') renderIssueBadge(); } catch (_) {}
      }
  };

  /**
   * Handle user selection of continuation path
   * @param {string} path - 'continue' | 'same_world' | 'new_story'
   */
  function selectContinuationPath(path) {
      // Map string to constant
      const pathMap = {
          'continue': CONTINUATION_PATHS.CONTINUE,
          'same_world': CONTINUATION_PATHS.SAME_WORLD,
          'new_story': CONTINUATION_PATHS.NEW_STORY
      };
      const selectedPath = pathMap[path] || CONTINUATION_PATHS.NEW_STORY;

      console.log('[Continuation] Path selected:', selectedPath);

      // Store prior world nouns before path initialization (for NEW_STORY validation)
      const priorNouns = collectPriorWorldNouns();
      state._priorWorldNouns = priorNouns;

      // Preserve world for SAME_WORLD path before any resets
      const preservedWorld = state.picks?.world;
      const preservedTitle = state.immutableTitle;
      const preservedTitleMode = state.previousTitleMode;

      // Initialize the path (sets continuation state)
      initializeContinuationPath(selectedPath);

      // Hide modal
      hideContinuationFork();

      // Handle path-specific state management
      if (selectedPath === CONTINUATION_PATHS.CONTINUE) {
          // Direct sequel — preserve most state, just reset story position
          state.storyEnded = false;
          state.turnCount = 0;
          state._loggedStoryStart = false;
          state._loggedScene3 = false;
          state._loggedScene6 = false;
          state._loggedPetitionOpen = false;
          state._loggedPetitionSubmit = false;
          clearStoryContent();
          // Title should echo previous title's mode
          state.previousTitle = preservedTitle;
          console.log('[Continuation] CONTINUE: Story state reset for sequel');
          window.showScreen('setup');
      } else if (selectedPath === CONTINUATION_PATHS.SAME_WORLD) {
          // Same world, new story — reset story but keep world
          resetForNewStory();
          state.picks.world = preservedWorld; // Restore world selection
          state.previousTitle = preservedTitle;
          state.previousTitleMode = preservedTitleMode;
          // Pre-select the world card in UI
          preselectWorldCard(preservedWorld);
          console.log('[Continuation] SAME_WORLD: Fresh story in', preservedWorld);
          window.showScreen('setup');
      } else {
          // Completely new story — full reset
          resetForNewStory();
          console.log('[Continuation] NEW_STORY: Full reset');
          window.showScreen('setup');
      }
  }

  /**
   * Clear story content without resetting picks
   */
  function clearStoryContent() {
      state.currentStoryContent = '';
      state.storyHistory = [];
      localStorage.removeItem('sb_saved_story');
      // Clear pagination if available
      if (typeof StoryPagination !== 'undefined' && StoryPagination.clear) {
          StoryPagination.clear();
      }
      const storyEl = document.getElementById('storyText');
      if (storyEl) {
          // Clear ONLY the rendered content, NOT all of #storyText. Its STATIC children
          // (#storyTitle, #sceneNumber, #storyPagesContainer) must survive — `innerHTML=''`
          // here was destroying the book title + scene number + the pages container, leaving
          // a blank reader the pagination self-heal could only partly rebuild (Roman 2026-06-29).
          var _pcEl = document.getElementById('storyPagesContainer');
          if (_pcEl) _pcEl.innerHTML = ''; else storyEl.innerHTML = '';   // fallback only if the container is already gone
          var _stTitle = document.getElementById('storyTitle'); if (_stTitle) _stTitle.textContent = '';
          var _scNum = document.getElementById('sceneNumber'); if (_scNum) _scNum.textContent = '';
          var _wtl = document.getElementById('workingTitleLabel'); if (_wtl) _wtl.classList.add('hidden');
      }
      // Reset curl pages
      const titlePage = document.getElementById('sbTitlePage');
      if (titlePage) { titlePage.classList.add('hidden'); titlePage.classList.remove('sb-curling'); }
      window._titlePageActive = false;
      const frontispiece = document.getElementById('fatelandsFrontispiece');
      if (frontispiece) { frontispiece.classList.add('hidden'); frontispiece.classList.remove('sb-curling'); }
      window._frontispieceActive = false;
      document.getElementById('storyContent')?.classList.remove('frontispiece-active');   // clear so a lingering class can't hide the next story's chrome
      const settingPlate = document.getElementById('settingPlate');
      if (settingPlate) { settingPlate.classList.remove('sb-curling'); }
      window._settingPlateActive = false;
      // Hide End Page if showing
      const endPage = document.getElementById('storyEndPage');
      if (endPage) endPage.classList.add('hidden');
  }

  /**
   * Reset state for a new story (preserves subscription/payment state)
   */
  function resetForNewStory() {
      // TEASE TIER: Prevent reset unless user has credits or entitlement
      if (isTeaseTier() && !canStartCustomTeaseStory()) {
          console.warn('[CREDITS] New story blocked — no custom story credits');
          window.showPaywall('unlock');
          return;
      }
      // SIGNATURE-PHRASE LEDGER (Roman 2026-06-09): harvest the OUTGOING story's
      // distinctive phrases (before its prose is cleared) so they're banned for the
      // next 5 stories, then advance the story counter + prune. Fire-and-forget.
      try {
          var _outgoing = '';
          try { if (window.StoryPagination && StoryPagination.getAllContent) _outgoing = String(StoryPagination.getAllContent() || ''); } catch (_) {}
          if (typeof _harvestSignaturePhrases === 'function' && _outgoing) _harvestSignaturePhrases(_outgoing, state && state.storyId);
          if (typeof _advancePhraseLedgerStory === 'function') _advancePhraseLedgerStory();
      } catch (_) {}
      // Modality CTA latch — clear it whenever a new story starts so the
      // CTA on the next entry isn't permanently disabled by a prior latch.
      state._modalityCtaInFlight = false;
      var _ctaEl = document.getElementById('beginBtn');
      if (_ctaEl) {
          // Re-disable until user picks a modality fresh (matches initial state).
          _ctaEl.disabled = true;
      }
      // Also clear modality button active state — fresh story = fresh choice.
      ['modeLiterary', 'modeCinegraphic'].forEach(function(id) {
          var el = document.getElementById(id);
          if (el) el.classList.remove('active');
      });
      state.storyModality = 'literary'; // restore default (matches init)

      // Clear Famous Fate flags so the next story doesn't inherit private-only /
      // literary-lock / cover-skip / orb-disable behavior, and restore the
      // Cinegraphic option in the UI.
      state.fateMode = null;
      state.famousFate = null;
      document.body.classList.remove('famous-fate-active');
      var _ffCinReset = document.getElementById('modeCinegraphic');
      if (_ffCinReset) { _ffCinReset.style.display = ''; _ffCinReset.disabled = false; }

      // ── ALL THREE LAYERS RESET (full world change) ──
      _resetStoryState();          // Layer 3 — couple mechanics
      _resetEpochState();          // Layer 2 — world-cycle entropy
      _resetRegionPhysics();       // Layer 1 — geographic invariants
      _resetIdentityState();       // Species, LI, reveal, Thornwild
      _applyContentRegister();     // re-assert content register — iOS stays APPLE_SAFE across new-story

      // Series / book metadata
      state.book_number = 1;
      state.series_id = null;
      state.previous_story_id = null;
      state.main_characters_locked = null;
      state.book1_continuity_summary = null;
      state.book_subhead = null;
      // Taste is STARTER-BOOK-ONLY (Roman 2026-05-29). For any other reset path
      // the storyLength is left empty so the corridor's length pick is the
      // authoritative source; defaulting to 'taste' here was making non-starter
      // stories fall into per-scene 1F pricing despite a paid 40F issue.
      state.storyLength = '';

      clearStoryContent();

      // Reset DSP state for new story
      if (typeof resetDSPState === 'function') resetDSPState();

      // Reset title state
      state.immutableTitle = null;
      state.coverArchetype = null;

      // Reset visual state
      state.visual = { autoLock: true, locked: false, lastImageUrl: "", bible: { style: "", setting: "", characters: {} }, sceneBudgets: {}, visualizedScenes: {}, characterVisualProfiles: {}, _visionCache: null };


      // Clear cover state — full reset (new world = new visual identity)
      state.coverSeed = null;
      state.coverEvolution = { damageLevel: 0, displacementLevel: 0, exposureLevel: 0 };
      state.coverEcho = { physical: null, positional: null, environmental: null };
      state._coverEvolutionLastST = null;
      state._coverAssemblyObjectShown = false;
      state._coverAssemblyObject = null;
      state._coverWorldKey = null;
      state.titleHistory = [];
      state._narrativeTriad = null;
      state._recentTitleStructures = [];
      state._recentTonePatterns = [];
      state.arcTitle = null;
      state._arcTitlePending = null;
      state._arcTitlePendingStyle = null;
      state._arcTitleStyle = null;
      state._issueCoverRenderedForIndex = null; // re-arm auto issue-end cover for the new story
      state._backCoverSynopsisRefreshedForIndex = null; // re-arm issue-end back-cover synopsis refresh
      state._arcTitleEvolved = false;
      state.arcTitleJustRevealed = false;
      state.titleEvolutionHistory = [];
      state._gnTitleRevealed = false;
      if (_coverAbortController) { _coverAbortController.abort(); _coverAbortController = null; }
      if (typeof resetBookState === 'function') resetBookState();
      const coverImg = document.getElementById('bookCoverImg');
      if (coverImg) coverImg.src = '';
      const coverLoading = document.getElementById('coverLoadingState');
      if (coverLoading) coverLoading.classList.add('hidden');
      const bookObj = document.getElementById('bookObject');
      if (bookObj) bookObj.classList.add('hidden');

      // Reset Storyturn state
      if (typeof resetStoryturnState === 'function') resetStoryturnState();

      // SLOT CONSISTENCY (Gap fix): _resetStoryState nulls state.storyId, but
      // makeStoryId() returns localStorage['sb_current_story_id'] FIRST if set —
      // so without clearing the slot the next mint resurrects the just-reset
      // story's id (snapshot collision / "new" story reusing the old id).
      // clearStoryForNewStart already does this; align resetForNewStory with it.
      if (typeof clearCurrentStoryId === 'function') clearCurrentStoryId();
  }

  /**
   * Pre-select a world card in the setup UI
   */
  function preselectWorldCard(world) {
      if (!world) return;
      // Find and select the world card
      const worldCards = document.querySelectorAll('.sb-card[data-grp="world"]');
      worldCards.forEach(card => {
          card.classList.remove('selected', 'flipped');
          if (card.dataset.val === world) {
              card.classList.add('selected', 'flipped');
          }
      });
  }

  /**
   * Default to new story if modal closed without selection
   */
  function defaultContinuationPath() {
      console.log('[Continuation] Default path: NEW_STORY');
      selectContinuationPath('new_story');
  }

  // Expose fork modal handlers globally
  window.showContinuationFork = showContinuationFork;
  window.hideContinuationFork = hideContinuationFork;
  window.selectContinuationPath = selectContinuationPath;
  window.defaultContinuationPath = defaultContinuationPath;

  /**
   * FALLBACK TITLE GENERATOR
   * Creates a deterministic name-based title when validation fails.
   * Pattern A: [FirstName]'s [Qualifier]
   * Pattern B: [FullName]: [Qualifier]
   *
   * @param {object} opts - { playerName, partnerName, world, tone, genre }
   * @returns {string} - Fallback title (never fails)
   */
  function generateFallbackTitle(opts) {
      const { playerName, partnerName, world, tone, genre } = opts;

      // Get qualifiers for this world (fallback to Modern)
      const qualifiers = TITLE_FALLBACK_QUALIFIERS[world] || TITLE_FALLBACK_QUALIFIERS.Modern;

      // Deterministic qualifier selection via hash of tone+genre
      const hashSeed = (tone || 'Earnest') + (genre || 'Romance');
      const qualifierIndex = simpleHash(hashSeed) % qualifiers.length;
      const qualifier = qualifiers[qualifierIndex];

      // Prefer love interest name for more intrigue, fallback to player
      const primaryName = partnerName || playerName;
      const firstName = extractFirstName(primaryName);

      // If we have a valid first name, use Pattern A
      if (firstName && firstName.length > 1 && !/^(the|a)\s/i.test(firstName)) {
          return `${firstName}'s ${qualifier}`;
      }

      // If we have a full name with 2+ parts, use Pattern B
      if (primaryName && primaryName.includes(' ')) {
          return `${primaryName}: ${qualifier}`;
      }

      // Last resort: use qualifier alone with dramatic framing
      return `The ${qualifier}`;
  }

  // Expose validators globally for Dev HUD
  window.validateTitle = validateTitle;
  window.generateFallbackTitle = generateFallbackTitle;

  // ============================================================
  // TITLE ↔ COVER SIGNAL ALIGNMENT LAYER
  // ============================================================
  // Ensures title and cover art signal the SAME dominant axis.
  // Primary axis: exactly one (usually Arousal)
  // Secondary axis: optional (max one)
  // All other axes: neutral
  // ============================================================

  /**
   * SIGNAL AXIS DEFINITIONS
   * Each axis has detection patterns for both title and cover
   */
  const SIGNAL_AXES = {
      AROUSAL: 'arousal',
      TONE: 'tone',
      GENRE: 'genre'
  };

  /**
   * AROUSAL SIGNAL PATTERNS
   * Title/cover must independently signal the arousal tier
   */
  const AROUSAL_SIGNALS = {
      Clean: {
          title: {
              allow: /\b(distance|restraint|waiting|watching|almost|nearly|silence|apart)\b/i,
              forbid: /\b(burn|ache|want|hunger|possession|devour|consume|claim)\b/i
          },
          cover: {
              allow: ['separation', 'stillness', 'restraint', 'waiting', 'longing from afar'],
              forbid: ['touch', 'embrace', 'intimacy', 'skin', 'heat', 'tension']
          },
          signal: 'restraint, distance'
      },
      Naughty: {
          title: {
              allow: /\b(almost|want|tempt|tease|forbidden|secret|risk|dare|edge)\b/i,
              forbid: /\b(claim|possess|devour|consume|take|surrender|yield)\b/i
          },
          cover: {
              allow: ['suggestion', 'withholding', 'anticipation', 'almost-touch', 'nearness'],
              forbid: ['explicit intimacy', 'possession', 'surrender', 'exposure']
          },
          signal: 'suggestion, withholding'
      },
      Steamy: {
          title: {
              allow: /\b(want|ache|burn|claim|mine|yours|possess|surrender|give|take)\b/i,
              forbid: /\b(filth|raw|intrude|force|use|ruin|wreck|break)\b/i
          },
          cover: {
              allow: ['intimacy', 'possession', 'surrender', 'closeness', 'heat', 'connection'],
              forbid: ['clinical', 'crude', 'explicit anatomy', 'shock']
          },
          signal: 'intimacy, possession'
      },
      Passionate: {
          title: {
              allow: /\b(filth|raw|ruin|wreck|use|break|devour|consume|claim|take)\b/i,
              forbid: /\b(sweet|gentle|soft|tender|pure|innocent|chaste)\b/i
          },
          cover: {
              allow: ['intrusion', 'bluntness', 'rawness', 'edge', 'danger', 'intensity'],
              forbid: ['sweetness', 'gentleness', 'purity', 'innocence']
          },
          signal: 'intrusion, bluntness'
      }
  };

  /**
   * TONE SIGNAL PATTERNS
   * Secondary axis - tone signals in title/cover
   */
  const TONE_AXIS_SIGNALS = {
      Earnest: {
          title: null, // Most permissive
          cover: ['sincerity', 'hope', 'warmth', 'openness']
      },
      WryConfession: {
          title: /\b(almost|anyway|still|wrong|mistake|lie|truth|never)\b/i,
          cover: ['irony', 'self-awareness', 'confession', 'doubt']
      },
      Dark: {
          title: /\b(blood|bone|ash|ruin|end|last|only|never|death)\b/i,
          cover: ['weight', 'shadow', 'gravity', 'consequence', 'doom']
      },
      Mythic: {
          title: /\b(fated|destined|eternal|ancient|prophecy|legend|chosen)\b/i,
          cover: ['fate', 'destiny', 'grandeur', 'ancient weight']
      }
  };

  /**
   * GENRE SIGNAL PATTERNS
   * Secondary axis - genre signals in title/cover
   */
  const GENRE_AXIS_SIGNALS = {
      Billionaire: {
          title: /\b(empire|fortune|deal|contract|merger|penthouse|heir)\b/i,
          cover: ['wealth', 'power', 'luxury', 'corporate', 'skyline']
      },
      CrimeSyndicate: {
          title: /\b(blood|family|loyalty|debt|oath|boss|territory)\b/i,
          cover: ['danger', 'shadows', 'underworld', 'loyalty']
      },
      Espionage: {
          title: /\b(secret|agent|cover|mission|asset|handler|burn)\b/i,
          cover: ['mystery', 'concealment', 'danger', 'surveillance']
      },
      Noir: {
          title: /\b(smoke|rain|night|shadow|dame|case|trouble)\b/i,
          cover: ['shadow', 'mystery', 'urban night', 'smoke', 'rain']
      },
      Heist: {
          title: /\b(score|job|crew|vault|mark|inside|take)\b/i,
          cover: ['precision', 'tension', 'planning', 'stakes']
      }
  };

  /**
   * Extract dominant signal axis from title
   * @param {string} title - The book title
   * @param {string} arousal - Current arousal level
   * @param {string} tone - Current tone
   * @param {string} genre - Current genre
   * @returns {{ primary: string, secondary: string|null, arousalMatch: boolean, signals: object }}
   */
  function extractTitleSignals(title, arousal, tone, genre) {
      const cleanTitle = (title || '').toLowerCase().trim();
      const signals = {
          arousal: null,
          tone: null,
          genre: null
      };

      // Check arousal signals
      const arousalConfig = AROUSAL_SIGNALS[arousal];
      if (arousalConfig?.title?.allow?.test(cleanTitle)) {
          signals.arousal = arousal;
      }
      // Check for arousal contradiction
      const arousalContradiction = arousalConfig?.title?.forbid?.test(cleanTitle);

      // Check tone signals
      const toneConfig = TONE_AXIS_SIGNALS[tone];
      if (toneConfig?.title?.test(cleanTitle)) {
          signals.tone = tone;
      }

      // Check genre signals
      const genreConfig = GENRE_AXIS_SIGNALS[genre];
      if (genreConfig?.title?.test(cleanTitle)) {
          signals.genre = genre;
      }

      // Determine primary axis (priority: arousal > tone > genre)
      let primary = null;
      let secondary = null;

      if (signals.arousal) {
          primary = SIGNAL_AXES.AROUSAL;
          if (signals.tone) secondary = SIGNAL_AXES.TONE;
          else if (signals.genre) secondary = SIGNAL_AXES.GENRE;
      } else if (signals.tone) {
          primary = SIGNAL_AXES.TONE;
          if (signals.genre) secondary = SIGNAL_AXES.GENRE;
      } else if (signals.genre) {
          primary = SIGNAL_AXES.GENRE;
      }

      return {
          primary,
          secondary,
          arousalMatch: signals.arousal === arousal,
          arousalContradiction,
          signals
      };
  }

  /**
   * Extract dominant signal axis from cover prompt
   * @param {object} coverPrompt - The cover prompt object from buildCoverPrompt
   * @param {string} arousal - Current arousal level
   * @param {string} tone - Current tone
   * @param {string} genre - Current genre
   * @returns {{ primary: string, secondary: string|null, arousalMatch: boolean, signals: object }}
   */
  function extractCoverSignals(coverPrompt, arousal, tone, genre) {
      const promptText = (coverPrompt?.promptText || '').toLowerCase();
      const emotion = (coverPrompt?.emotion || '').toLowerCase();
      const signals = {
          arousal: null,
          tone: null,
          genre: null
      };

      // Check arousal signals in cover
      const arousalConfig = AROUSAL_SIGNALS[arousal];
      if (arousalConfig?.cover?.allow) {
          const hasArousalSignal = arousalConfig.cover.allow.some(sig =>
              promptText.includes(sig.toLowerCase()) || emotion.includes(sig.toLowerCase())
          );
          if (hasArousalSignal) signals.arousal = arousal;
      }

      // Check for arousal contradiction
      let arousalContradiction = false;
      if (arousalConfig?.cover?.forbid) {
          arousalContradiction = arousalConfig.cover.forbid.some(sig =>
              promptText.includes(sig.toLowerCase()) || emotion.includes(sig.toLowerCase())
          );
      }

      // Check tone signals
      const toneConfig = TONE_AXIS_SIGNALS[tone];
      if (toneConfig?.cover) {
          const hasToneSignal = toneConfig.cover.some(sig =>
              promptText.includes(sig.toLowerCase()) || emotion.includes(sig.toLowerCase())
          );
          if (hasToneSignal) signals.tone = tone;
      }

      // Check genre signals
      const genreConfig = GENRE_AXIS_SIGNALS[genre];
      if (genreConfig?.cover) {
          const hasGenreSignal = genreConfig.cover.some(sig =>
              promptText.includes(sig.toLowerCase())
          );
          if (hasGenreSignal) signals.genre = genre;
      }

      // Frame/border state for composed cover validation
      const keyholeEl = document.getElementById('coverKeyholeOverlay');
      const borderEl = document.getElementById('coverOrnateBorder');
      const frameType = keyholeEl && !keyholeEl.classList.contains('hidden') ? 'keyhole' : null;
      const borderType = borderEl && !borderEl.classList.contains('hidden') ? 'erotic' : null;

      // Cover framing no longer signals arousal — determine axes from content only
      let primary = null;
      let secondary = null;
      let arousalMatchOverride = false;

      if (false) {
          // Placeholder — arousal-based framing overrides removed
          primary = SIGNAL_AXES.AROUSAL;
          arousalMatchOverride = true;
          // Secondary can still be tone or genre from image
          if (signals.tone) secondary = SIGNAL_AXES.TONE;
          else if (signals.genre) secondary = SIGNAL_AXES.GENRE;
      } else if (signals.arousal) {
          primary = SIGNAL_AXES.AROUSAL;
          if (signals.tone) secondary = SIGNAL_AXES.TONE;
          else if (signals.genre) secondary = SIGNAL_AXES.GENRE;
      } else if (signals.tone) {
          primary = SIGNAL_AXES.TONE;
          if (signals.genre) secondary = SIGNAL_AXES.GENRE;
      } else if (signals.genre) {
          primary = SIGNAL_AXES.GENRE;
      }

      return {
          primary,
          secondary,
          arousalMatch: arousalMatchOverride || signals.arousal === arousal,
          arousalContradiction: arousalMatchOverride ? false : arousalContradiction,
          signals,
          // Composed cover signals (framing is part of the cover signal)
          frameType,
          borderType,
          dirtyFramingOverride: hasDirtyFraming && arousal === 'Passionate'
      };
  }

  /**
   * SIGNAL ALIGNMENT VALIDATION
   * Validates that title and cover signal the same dominant axis
   * @param {string} title - The book title
   * @param {object} coverPrompt - Cover prompt from buildCoverPrompt
   * @param {object} context - { arousal, tone, genre }
   * @returns {{ aligned: boolean, errors: Array<{code: string, message: string}>, titleSignals: object, coverSignals: object }}
   */
  function validateSignalAlignment(title, coverPrompt, context) {
      const { arousal, tone, genre } = context;
      const errors = [];

      // Extract signals from both sources
      const titleSignals = extractTitleSignals(title, arousal, tone, genre);
      const coverSignals = extractCoverSignals(coverPrompt, arousal, tone, genre);

      // CHECK 1: Primary axis alignment
      if (titleSignals.primary && coverSignals.primary) {
          if (titleSignals.primary !== coverSignals.primary) {
              errors.push({
                  code: 'SIGNAL_AXIS_MISMATCH',
                  message: `Title signals ${titleSignals.primary}, cover signals ${coverSignals.primary}`
              });
          }
      }

      // CHECK 2: Arousal contradiction (HARD FAIL)
      if (titleSignals.arousalContradiction) {
          errors.push({
              code: 'TITLE_AROUSAL_CONTRADICTION',
              message: `Title contains words forbidden at ${arousal} arousal level`
          });
      }
      if (coverSignals.arousalContradiction) {
          errors.push({
              code: 'COVER_AROUSAL_CONTRADICTION',
              message: `Cover contains signals forbidden at ${arousal} arousal level`
          });
      }

      // CHECK 3: Neither signals arousal (advisory only — covers no longer signal explicitness tier)
      if (arousal === 'Steamy' || arousal === 'Passionate') {
          if (!titleSignals.arousalMatch && !coverSignals.arousalMatch) {
              errors.push({
                  code: 'AROUSAL_SIGNAL_ABSENT',
                  message: `${arousal} intensity but neither title nor cover signals it`
              });
          }
      }

      if (false) {
          // Removed: keyhole/framing validation for explicit tiers
          if (true) {
              errors.push({
                  code: 'DIRTY_FRAME_ABSENT',
                  message: 'Dirty intensity requires keyhole/metalwork framing'
              });
          }
          // Note: titleSignals.arousalMatch and coverSignals.arousalMatch NOT required for Dirty
          // The composed cover (image + keyhole frame) is the signal, not image alone
      }

      // CHECK 4: Ambiguity check - no clear primary in either
      if (!titleSignals.primary && !coverSignals.primary) {
          errors.push({
              code: 'SIGNAL_AMBIGUOUS',
              message: 'Neither title nor cover has a clear primary signal axis'
          });
      }

      // CHECK 5: Secondary axis conflict
      if (titleSignals.secondary && coverSignals.secondary) {
          if (titleSignals.secondary !== coverSignals.secondary) {
              // Soft warning, not hard fail
              console.log('[SignalAlignment] Secondary axis differs:', titleSignals.secondary, 'vs', coverSignals.secondary);
          }
      }

      return {
          aligned: errors.length === 0,
          errors,
          titleSignals,
          coverSignals,
          context: {
              expectedArousal: arousal,
              arousalSignal: AROUSAL_SIGNALS[arousal]?.signal || 'neutral'
          }
      };
  }

  /**
   * Quick arousal inference from title alone
   * Used for pre-validation before cover is generated
   * @param {string} title - The book title
   * @returns {string|null} - Inferred arousal tier or null if ambiguous
   */
  function inferArousalFromTitle(title) {
      const cleanTitle = (title || '').toLowerCase().trim();

      // Check in order from most restrictive to least
      for (const level of ['Passionate', 'Steamy', 'Naughty', 'Clean']) {
          const config = AROUSAL_SIGNALS[level];
          if (config?.title?.allow?.test(cleanTitle)) {
              // Also check it doesn't violate this level's forbid
              if (!config.title.forbid?.test(cleanTitle)) {
                  return level;
              }
          }
      }
      return null; // Ambiguous
  }

  // Expose signal alignment functions globally
  window.validateSignalAlignment = validateSignalAlignment;
  window.extractTitleSignals = extractTitleSignals;
  window.extractCoverSignals = extractCoverSignals;
  window.inferArousalFromTitle = inferArousalFromTitle;
  window.SIGNAL_AXES = SIGNAL_AXES;
  window.AROUSAL_SIGNALS = AROUSAL_SIGNALS;

  /**
   * DSP VALIDATION — Strict template enforcement
   * DSP must EXACTLY match: "In [WORLD], shaped by [GENRE], a question awaits:
   * Will [ARCH_ADJ] desire redeem this [TONE_ADJ] affair — or ruin it?"
   *
   * @param {string} dspText - The DSP text to validate (HTML stripped)
   * @param {object} inputs - { world, genre, archetypeId, tone }
   * @returns {{ pass: boolean, errors: Array<{code: string, message: string}> }}
   */
  function validateDSP(dspText, inputs) {
      const errors = [];
      const { world, genre, archetypeId, tone } = inputs;

      // Strip HTML tags for validation
      const plainText = dspText.replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim();

      // Get expected phrases from locked dictionaries
      const expectedWorld = DSP_WORLD_PHRASES[world];
      const expectedGenre = DSP_GENRE_PARAPHRASES[genre];
      const expectedArch = DSP_ARCHETYPE_ADJECTIVES[archetypeId];
      const expectedTone = DSP_TONAL_ADJECTIVES[tone];

      // Validate world phrase exists
      if (!expectedWorld) {
          errors.push({
              code: VALIDATION_ERRORS.DSP_INVALID_WORLD_PHRASE,
              message: `No DSP world phrase for: "${world}"`
          });
      }

      // Validate genre phrase exists
      if (!expectedGenre) {
          errors.push({
              code: VALIDATION_ERRORS.DSP_INVALID_GENRE_PHRASE,
              message: `No DSP genre paraphrase for: "${genre}"`
          });
      }

      // Validate archetype adjective exists
      if (!expectedArch) {
          errors.push({
              code: VALIDATION_ERRORS.DSP_INVALID_ARCHETYPE_ADJ,
              message: `No DSP archetype adjective for: "${archetypeId}"`
          });
      }

      // Validate tone adjective exists
      if (!expectedTone) {
          errors.push({
              code: VALIDATION_ERRORS.DSP_INVALID_TONE_ADJ,
              message: `No DSP tonal adjective for: "${tone}"`
          });
      }

      // If any dictionary lookups failed, return early
      if (errors.length > 0) {
          return { pass: false, errors };
      }

      // Build expected DSP text (exact template)
      const expectedDSP = `In ${expectedWorld}, shaped by ${expectedGenre}, a question awaits: Will ${expectedArch} desire redeem this ${expectedTone} affair — or ruin it?`;

      // Normalize both for comparison (handle HTML entities)
      const normalizedExpected = expectedDSP.replace(/\s+/g, ' ').trim();
      const normalizedActual = plainText
          .replace(/&#8201;/g, ' ')
          .replace(/&#8212;/g, '—')
          .replace(/\u2009/g, ' ')  // thin space
          .replace(/\u2014/g, '—')  // em dash
          .replace(/\s+/g, ' ')
          .trim();

      // Check for exact match
      if (normalizedActual !== normalizedExpected) {
          // Diagnose specific failure
          if (!normalizedActual.startsWith('In ')) {
              errors.push({
                  code: VALIDATION_ERRORS.DSP_TEMPLATE_VIOLATION,
                  message: 'DSP must start with "In "'
              });
          }
          if (!normalizedActual.includes(expectedWorld)) {
              errors.push({
                  code: VALIDATION_ERRORS.DSP_INVALID_WORLD_PHRASE,
                  message: `World phrase "${expectedWorld}" not found in DSP`
              });
          }
          if (!normalizedActual.includes(expectedGenre)) {
              errors.push({
                  code: VALIDATION_ERRORS.DSP_INVALID_GENRE_PHRASE,
                  message: `Genre phrase "${expectedGenre}" not found in DSP`
              });
          }
          if (!normalizedActual.includes(expectedArch)) {
              errors.push({
                  code: VALIDATION_ERRORS.DSP_INVALID_ARCHETYPE_ADJ,
                  message: `Archetype adjective "${expectedArch}" not found in DSP`
              });
          }
          if (!normalizedActual.includes(expectedTone)) {
              errors.push({
                  code: VALIDATION_ERRORS.DSP_INVALID_TONE_ADJ,
                  message: `Tone adjective "${expectedTone}" not found in DSP`
              });
          }

          // STRICT ADJECTIVE POSITION VALIDATION
          // Verify exact adjective appears in correct DSP slot
          const archSlotMatch = normalizedActual.match(/Will\s+(\w+)\s+desire/i);
          if (archSlotMatch && archSlotMatch[1].toLowerCase() !== expectedArch.toLowerCase()) {
              errors.push({
                  code: VALIDATION_ERRORS.DSP_INVALID_ARCHETYPE_ADJ,
                  message: `Wrong adjective in archetype slot: found "${archSlotMatch[1]}", expected "${expectedArch}"`
              });
          }
          const toneSlotMatch = normalizedActual.match(/this\s+(\w+)\s+affair/i);
          if (toneSlotMatch && toneSlotMatch[1].toLowerCase() !== expectedTone.toLowerCase()) {
              errors.push({
                  code: VALIDATION_ERRORS.DSP_INVALID_TONE_ADJ,
                  message: `Wrong adjective in tone slot: found "${toneSlotMatch[1]}", expected "${expectedTone}"`
              });
          }

          // Check for world subtype leakage
          const SUBTYPE_PATTERNS = [
              /\bsmall[- ]town\b/i, /\bcampus\b/i, /\boffice\b/i, /\bold[- ]money\b/i,
              /\bcyberpunk\b/i, /\bspace opera\b/i, /\bgalactic\b/i, /\bVictorian\b/i,
              /\bRegency\b/i, /\bMedieval\b/i, /\bAncient\b/i
          ];
          for (const pattern of SUBTYPE_PATTERNS) {
              if (pattern.test(normalizedActual)) {
                  errors.push({
                      code: VALIDATION_ERRORS.DSP_WORLD_SUBTYPE_LEAK,
                      message: `World subtype leaked into DSP: ${normalizedActual.match(pattern)?.[0]}`
                  });
                  break;
              }
          }

          // Check for extra prose
          if (normalizedActual.length > normalizedExpected.length + 10) {
              errors.push({
                  code: VALIDATION_ERRORS.DSP_EXTRA_PROSE,
                  message: 'DSP contains extra prose beyond locked template'
              });
          }

          // Check for legacy phrasing — comprehensive list of deprecated DSP text
          const LEGACY_PATTERNS = [
              /\bdestiny story prompt\b/i,
              /\byour story\b/i,
              /\bonce upon\b/i,
              /\bin this tale\b/i,
              // Legacy world phrases (pre-canon)
              /\bstrangers meet\b/i,
              /\bpower lingers\b/i,
              /\bforces move\b/i,
              /\bvows bind\b/i,
              /\bold powers\b/i,
              /\bcity of strangers\b/i,
              /\bthe present day\b/i,
              /\ban earlier era\b/i,
              /\bsupernatural forces\b/i,
              /\bambition and consequence\b/i,
              // Legacy genre phrases (pre-canon)
              /\bdangerous games\b/i,
              /\bshadow and silk\b/i,
              /\bhigh stakes\b/i,
              /\bforbidden fruit\b/i,
              /\bsecret desires\b/i,
              /\bpassion and peril\b/i,
              /\blove and loss\b/i,
              // Meta-narrative leakage
              /\bthe narrative\b/i,
              /\bthe story\b/i,
              /\bthis romance\b/i,
              /\btheir journey\b/i
          ];
          for (const pattern of LEGACY_PATTERNS) {
              if (pattern.test(normalizedActual)) {
                  errors.push({
                      code: VALIDATION_ERRORS.DSP_LEGACY_PHRASING,
                      message: `Legacy phrasing detected: ${normalizedActual.match(pattern)?.[0]}`
                  });
                  break;
              }
          }

          // WORD-SOURCE VALIDATION: DSP output must contain ONLY words from selected phrases
          // Extract content words (skip articles, prepositions, punctuation)
          const STRUCTURAL_WORDS = new Set([
              'in', 'a', 'an', 'the', 'of', 'and', 'or', 'by', 'shaped', 'question', 'awaits',
              'will', 'desire', 'redeem', 'this', 'affair', 'ruin', 'it', 'to', 'for', 'with'
          ]);
          const dspWords = normalizedActual.toLowerCase()
              .replace(/[.,!?;:\u2014\u2013\u2009\u00a0]/g, ' ')
              .split(/\s+/)
              .filter(w => w.length > 2 && !STRUCTURAL_WORDS.has(w));

          // Build allowed word set from selected phrases
          const allowedWords = new Set();
          (expectedWorld || '').toLowerCase().split(/\s+/).forEach(w => allowedWords.add(w.replace(/[.,]/g, '')));
          (expectedGenre || '').toLowerCase().split(/\s+/).forEach(w => allowedWords.add(w.replace(/[.,]/g, '')));
          (expectedArch || '').toLowerCase().split(/\s+/).forEach(w => allowedWords.add(w.replace(/[.,]/g, '')));
          (expectedTone || '').toLowerCase().split(/\s+/).forEach(w => allowedWords.add(w.replace(/[.,]/g, '')));
          // Add structural words to allowed set
          STRUCTURAL_WORDS.forEach(w => allowedWords.add(w));

          const illegalWords = dspWords.filter(w => !allowedWords.has(w));
          if (illegalWords.length > 0) {
              errors.push({
                  code: VALIDATION_ERRORS.DSP_EXTRA_PROSE,
                  message: `DSP contains words not from canonical phrases: ${illegalWords.slice(0, 5).join(', ')}`
              });
          }

          // Generic template violation if no specific error found
          if (errors.length === 0) {
              errors.push({
                  code: VALIDATION_ERRORS.DSP_TEMPLATE_VIOLATION,
                  message: `DSP does not match locked template. Expected: "${normalizedExpected.slice(0, 50)}..."`
              });
          }
      }

      return { pass: errors.length === 0, errors };
  }

  /**
   * POV VALIDATION (5th Person) — Comprehensive scene validation
   *
   * @param {string} sceneText - The scene prose to validate
   * @param {object} context - { sceneIndex, isErotic }
   * @returns {{ pass: boolean, errors: Array<{code: string, message: string}>, metrics: object }}
   */
  function validatePOV(sceneText, context) {
      const errors = [];
      const { sceneIndex = 0, isErotic = false } = context;
      const isSceneOne = sceneIndex === 0;

      // Count Author mentions
      const authorMatches = sceneText.match(/\bFate\b/g) || [];
      const authorMentions = authorMatches.length;

      // Extract first words and last paragraph
      const trimmed = sceneText.trim();
      const firstTwoWords = trimmed.split(/\s+/).slice(0, 2).join(' ');
      const paragraphs = trimmed.split(/\n\n+/);
      const lastParagraph = paragraphs[paragraphs.length - 1] || '';
      const sentences = lastParagraph.match(/[^.!?]+[.!?]+/g) || [lastParagraph];
      const lastTwoSentences = sentences.slice(-2).join(' ');

      // RULE 1: First two words = "Fate" (always enforced)
      const hasValidOpener = /^Fate\b/i.test(trimmed);
      if (!hasValidOpener) {
          errors.push({
              code: VALIDATION_ERRORS.POV_INVALID_OPENER,
              message: `Opening must start with "Fate". Found: "${firstTwoWords}"`
          });
      }

      // RULE 2: Final perspective = Fate (structural check)
      const AUTHOR_CLOSING_VERBS = [
          'held', 'tilted', 'set', 'arranged', 'steered', 'coaxed', 'seeded', 'threaded',
          'watched', 'waited', 'considered', 'wondered', 'doubted', 'resisted', 'smiled',
          'frowned', 'paused', 'knew', 'felt', 'sensed', 'released', 'tightened', 'loosened'
      ];
      const closingVerbPattern = new RegExp(
          'Fate\\s+(' + AUTHOR_CLOSING_VERBS.join('|') + ')\\b', 'i'
      );
      const authorReflectionPattern = /Fate.{0,60}(uncertain|doubt|wonder|question|resist|perhaps|might|whether|if only)/i;
      const hasValidCloser = closingVerbPattern.test(lastTwoSentences) || authorReflectionPattern.test(lastTwoSentences);

      if (!hasValidCloser && !isErotic) {
          errors.push({
              code: VALIDATION_ERRORS.POV_INVALID_CLOSER,
              message: 'Scene must end with Fate as final perspective (action verb or reflection)'
          });
      }

      // RULE 3: Scene prose = strict 3rd person limited
      const firstPersonPattern = /\b(I|me|my|mine|myself)\b(?!\s*["'])/gi;
      const firstPersonMatches = sceneText.match(firstPersonPattern) || [];
      // Filter out dialogue (rough heuristic: not near quotes)
      const nonDialogueFirstPerson = firstPersonMatches.filter(match => {
          const idx = sceneText.indexOf(match);
          const nearbyText = sceneText.slice(Math.max(0, idx - 20), idx + 20);
          return !/"[^"]*$/.test(nearbyText.slice(0, 20)) && !/^[^"]*"/.test(nearbyText.slice(20));
      });
      if (nonDialogueFirstPerson.length > 2) {
          errors.push({
              code: VALIDATION_ERRORS.POV_NON_3RD_PERSON,
              message: `Scene contains ${nonDialogueFirstPerson.length} first-person references outside dialogue`
          });
      }

      // RULE 4: Author NEVER narrates action or scenery (banned voyeur verbs)
      const BANNED_AUTHOR_VERBS = ['watched', 'observed', 'saw', 'looked on', 'gazed at', 'witnessed', 'noticed', 'perceived'];
      const bannedPattern = new RegExp('Fate\\s+(' + BANNED_AUTHOR_VERBS.join('|') + ')\\b', 'gi');
      const bannedMatches = sceneText.match(bannedPattern) || [];
      if (bannedMatches.length > 0) {
          errors.push({
              code: VALIDATION_ERRORS.POV_AUTHOR_NARRATES_ACTION,
              message: `Fate uses banned voyeur verbs: ${bannedMatches.slice(0, 3).join(', ')}`
          });
      }

      // RULE 5: Frequency requirements
      if (isSceneOne && authorMentions < 6) {
          errors.push({
              code: VALIDATION_ERRORS.POV_SCENE1_FREQUENCY,
              message: `Scene 1 requires ≥6 Fate mentions. Found: ${authorMentions}`
          });
      } else if (!isSceneOne && !isErotic && (authorMentions < 1 || authorMentions > 3)) {
          errors.push({
              code: VALIDATION_ERRORS.POV_LATER_FREQUENCY,
              message: `Later scenes require 1-3 Fate mentions. Found: ${authorMentions}`
          });
      }

      // RULE 6: Erotic scenes = 0 Author mentions
      if (isErotic && authorMentions > 0) {
          errors.push({
              code: VALIDATION_ERRORS.POV_EROTIC_AUTHOR_PRESENT,
              message: `Erotic scenes must have 0 Fate mentions. Found: ${authorMentions}`
          });
      }

      // RULE 7: Meta-awareness spike ~5% (check for excess)
      const metaAwarenessPatterns = [
          /\b(character|story|narrative|plot|author|reader|page|chapter)\b/gi,
          /\b(as if|somehow|knew|felt|sensed)\s+(that|the|this)\s+(story|tale|narrative)/gi
      ];
      let metaCount = 0;
      metaAwarenessPatterns.forEach(p => {
          const matches = sceneText.match(p);
          if (matches) metaCount += matches.length;
      });
      const wordCount = sceneText.split(/\s+/).length;
      const metaRatio = metaCount / wordCount;
      if (metaRatio > 0.08) { // ~8% threshold
          errors.push({
              code: VALIDATION_ERRORS.POV_META_AWARENESS_EXCESS,
              message: `Meta-awareness exceeds 5% threshold. Ratio: ${(metaRatio * 100).toFixed(1)}%`
          });
      }



      const metrics = {
          authorMentions,
          isSceneOne,
          isErotic,
          hasValidOpener,
          hasValidCloser,
          wordCount
      };

      return { pass: errors.length === 0, errors, metrics };
  }

  /**
   * Get current validation state for Dev HUD
   * Runs all validators against current story state
   */
  function getValidationStatus() {
      const results = {};

      // DSP validation
      const dspEl = document.getElementById('synopsisText');
      if (dspEl && state.picks) {
          const dspResult = validateDSP(dspEl.textContent || '', {
              world: state.picks.world || 'Modern',
              genre: state.picks.genre || 'Billionaire',
              archetypeId: (state.archetype?.primary) || 'BEAUTIFUL_RUIN',
              tone: state.picks.tone || 'Earnest'
          });
          results.dsp = dspResult;
      }

      // POV validation (last generated scene)
      if (state.povMode === 'author5th' && window.StoryPagination) {
          const lastContent = StoryPagination.getAllContent().replace(/<[^>]*>/g, ' ');
          const lastScene = lastContent.slice(-2000);
          const povResult = validatePOV(lastScene, {
              sceneIndex: state.turnCount || 0,
              isErotic: isIntimacyAllowedAtCurrentStoryturn() && state.turnCount > 0,
          });
          results.pov = povResult;
      }

      // Tone validation
      if (state.picks?.tone && window.StoryPagination) {
          const lastContent = StoryPagination.getAllContent().replace(/<[^>]*>/g, ' ');
          const lastScene = lastContent.slice(-2000);
          const toneResult = validateTone(lastScene, state.picks.tone);
          results.tone = toneResult;
      }

      // Erotic escalation validation — removed (intensity no longer controls routing)

      // Title validation
      const titleEl = document.getElementById('storyTitle');
      if (titleEl && titleEl.textContent) {
          const titleResult = validateTitle(titleEl.textContent.trim(), state.picks?.tone);
          results.title = titleResult;
      }

      // Signal alignment validation
      if (titleEl && titleEl.textContent) {
          const currentTitle = titleEl.textContent.trim();
          const mockCoverPrompt = {
              promptText: 'emotion: ' + (state.coverEmotion || 'mystery'),
              emotion: state.coverEmotion || 'mystery'
          };
          const signalResult = validateSignalAlignment(currentTitle, mockCoverPrompt, {
              arousal: state.intensity || 'Naughty',
              tone: state.picks?.tone || 'Earnest',
              genre: state.picks?.genre || 'Romance'
          });
          results.signal = signalResult;
      }

      return results;
  }

  // Expose validators globally for Dev HUD access
  window.validateDSP = validateDSP;
  window.validatePOV = validatePOV;
  window.validateTone = validateTone;
  window.validateEroticEscalation = validateEroticEscalation;
  window.getValidationStatus = getValidationStatus;
  window.VALIDATION_ERRORS = VALIDATION_ERRORS;

  // ============================================================
  // NARRATIVE VOCABULARY BANS — POST-GENERATION ENFORCEMENT
  // ============================================================
  // System-internal terms that must NEVER appear in reader-facing text.
  // "The Author" is ALWAYS banned — the 5th-person entity is now "Fate".
  // Archetype names influence structure/pacing/framing but are invisible
  // to readers — they must never surface in prose, dialogue, or synopsis.
  // ============================================================

  const VOCAB_BAN_PATTERNS = [
      // "The Author" — legacy narrator term, always banned (entity is now "Fate")
      { id: 'AUTHOR_LEAK',          rx: /The Author\b/g,                                     fatePOVExempt: false },
      // Any X Warden compound (Heart Warden, Shadow Warden, Blood Warden, etc.)
      { id: 'WARDEN_COMPOUND',      rx: /(?:Heart|Shadow|Blood|\w+)\s+Warden\b/gi,                 fatePOVExempt: false },
      // Cover-composition archetype names leaked into prose
      { id: 'ARCHETYPE_THRESHOLD',  rx: /\bThreshold\b/g,                                          fatePOVExempt: false },
      { id: 'ARCHETYPE_EMBLEM',     rx: /\bEmblem\b/g,                                             fatePOVExempt: false },
      // Canonical 7-archetype display names
      { id: 'ARCHETYPE_OPEN_VEIN',  rx: /\bOpen Vein\b/gi,                                         fatePOVExempt: false },
      { id: 'ARCHETYPE_SPELLBINDER',rx: /\bSpellbinder\b/gi,                                       fatePOVExempt: false },
      { id: 'ARCHETYPE_ARMORED_FOX',rx: /\bArmored Fox\b/gi,                                       fatePOVExempt: false },
      { id: 'ARCHETYPE_DARK_VICE',  rx: /\bDark Vice\b/gi,                                         fatePOVExempt: false },
      { id: 'ARCHETYPE_BEAUTIFUL_RUIN', rx: /\bBeautiful Ruin\b/gi,                                fatePOVExempt: false },
      { id: 'ARCHETYPE_ETERNAL_FLAME',  rx: /\bEternal Flame\b/gi,                                 fatePOVExempt: false },
      // Archetype section titles — metadata only, never in prose
      { id: 'ARCHETYPE_STORYBEAU',   rx: /\bStorybeau\b/gi,                                        fatePOVExempt: false },
      { id: 'ARCHETYPE_STORYBELLE',  rx: /\bStorybelle\b/gi,                                       fatePOVExempt: false },
      { id: 'ARCHETYPE_STORYBOO',    rx: /\bStoryboo\b/gi,                                         fatePOVExempt: false },
      // Decorative Fate language — Fate acts structurally, never as atmospheric decoration
      { id: 'FATE_DECORATIVE_SMILED',  rx: /\bFate smiled\b/gi,                                    fatePOVExempt: false },
      { id: 'FATE_DECORATIVE_WATCHED', rx: /\bFate watched\b/gi,                                   fatePOVExempt: false },
      { id: 'FATE_DECORATIVE_SENSED',  rx: /\bFate sensed\b/gi,                                    fatePOVExempt: false },
      { id: 'FATE_DECORATIVE_COILED',  rx: /\bFate coiled\b/gi,                                    fatePOVExempt: false },
      { id: 'FATE_DECORATIVE_KNEW',    rx: /\bFate knew\b/gi,                                      fatePOVExempt: false }
  ];

  // Human-readable ban description per pattern (for negative-constraint injection)
  const VOCAB_BAN_LABELS = {
      AUTHOR_LEAK:            '"The Author" — legacy narrator term, always banned (use "Fate")',
      WARDEN_COMPOUND:        'X Warden compound — system-internal archetype name',
      ARCHETYPE_THRESHOLD:    '"Threshold" — internal cover-composition archetype',
      ARCHETYPE_EMBLEM:       '"Emblem" — internal cover-composition archetype',
      ARCHETYPE_OPEN_VEIN:    '"Open Vein" — internal character archetype',
      ARCHETYPE_SPELLBINDER:  '"Spellbinder" — internal character archetype',
      ARCHETYPE_ARMORED_FOX:  '"Armored Fox" — internal character archetype',
      ARCHETYPE_DARK_VICE:    '"Dark Vice" — internal character archetype',
      ARCHETYPE_BEAUTIFUL_RUIN: '"Beautiful Ruin" — internal character archetype',
      ARCHETYPE_ETERNAL_FLAME:  '"Eternal Flame" — internal character archetype',
      ARCHETYPE_STORYBEAU:      '"Storybeau" — LI category label, metadata only',
      ARCHETYPE_STORYBELLE:     '"Storybelle" — LI category label, metadata only',
      ARCHETYPE_STORYBOO:       '"Storyboo" — LI category label, metadata only',
      FATE_DECORATIVE_SMILED:   '"Fate smiled" — decorative Fate language banned',
      FATE_DECORATIVE_WATCHED:  '"Fate watched" — decorative Fate language banned',
      FATE_DECORATIVE_SENSED:   '"Fate sensed" — decorative Fate language banned',
      FATE_DECORATIVE_COILED:   '"Fate coiled" — decorative Fate language banned',
      FATE_DECORATIVE_KNEW:     '"Fate knew" — decorative Fate language banned'
  };

  /**
   * Scan text for vocabulary ban violations.
   * @param {string} text          - The generated text to check
   * @param {object} context       - { type: 'prose'|'synopsis'|'title'|'cover', isFatePOV: boolean }
   * @returns {{ clean: boolean, violations: Array<{id:string, matches:string[]}> }}
   */
  function scrubNarrativeVocabulary(text, context) {
      if (!text || typeof text !== 'string') return { clean: true, violations: [] };

      const violations = [];
      const isFatePOV = context.isFatePOV && context.type === 'prose';

      for (const ban of VOCAB_BAN_PATTERNS) {
          // "Fate" is allowed in Fate POV prose (5th-person mode)
          if (ban.fatePOVExempt && isFatePOV) continue;

          // Reset regex lastIndex (global flag)
          ban.rx.lastIndex = 0;
          const matches = text.match(ban.rx);
          if (matches && matches.length > 0) {
              violations.push({ id: ban.id, matches });
          }
      }

      return { clean: violations.length === 0, violations };
  }

  /**
   * Build a negative-constraint instruction string from violations.
   * Injected into the system prompt on regeneration.
   */
  function buildVocabBanConstraint(violations) {
      const lines = violations.map(v =>
          `- NEVER use ${VOCAB_BAN_LABELS[v.id] || v.id}. Found: "${v.matches.join('", "')}" — remove or rephrase.`
      );
      return `\n\nCRITICAL VOCABULARY BAN — the following terms are system-internal and MUST NOT appear in your output:\n${lines.join('\n')}\nRewrite any sentence that would contain these terms. They are invisible to the reader and must never surface in prose, dialogue, synopsis, or titles.\n`;
  }

  /**
   * Enforce vocabulary bans with one-shot regeneration.
   *
   * @param {string}   text          - generated text to check
   * @param {object}   context       - { type, isFatePOV }
   * @param {function} regenerateFn  - async (negativeConstraint: string) => string
   *                                   Called once on violation. Receives the negative-constraint
   *                                   string to append to the system prompt. Must return new text.
   * @returns {string} clean (or best-effort) text
   */
  async function enforceVocabularyBans(text, context, regenerateFn) {
      const result = scrubNarrativeVocabulary(text, context);
      if (result.clean) return text;

      console.warn('[VOCAB_BAN] Violations in ' + context.type + ':', result.violations);

      if (!regenerateFn) {
          console.error('[VOCAB_BAN] No regeneration function provided — returning dirty text');
          return text;
      }

      // Preserve a mandated Scene 1 closer (set upstream by the deck
      // mandate gate) across the regen. The vocab-ban regenerator
      // rebuilds the entire text from scratch and can drop the closer
      // appended by SCENE1-GATE. Without this guard, every regen path
      // erodes the closer enforcement — only the FINAL regen output
      // ships, and that output may have lost the deck-onboarding
      // anchor.
      var _stateRef = (typeof window !== 'undefined' && window.state) ? window.state : null;
      var _mandatedCloser = _stateRef && _stateRef._sceneOneMandatedCloser || null;
      var _closerWasInInput = _mandatedCloser && typeof text === 'string' && text.includes(_mandatedCloser);

      // Regenerate once with explicit negative constraint
      const constraint = buildVocabBanConstraint(result.violations);
      console.log('[VOCAB_BAN] Regenerating with negative constraint');
      let regenerated = await regenerateFn(constraint);

      // Re-apply the mandated closer if it survived a prior regen but
      // was lost by THIS one.
      if (_closerWasInInput && typeof regenerated === 'string' && !regenerated.includes(_mandatedCloser)) {
          regenerated = regenerated.trim() + '\n\n' + _mandatedCloser;
          console.log('[VOCAB_BAN] Re-appended mandated closer lost during vocab-ban regen');
      }

      // Re-check — if still dirty, log hard warning but return anyway
      const recheck = scrubNarrativeVocabulary(regenerated, context);
      if (!recheck.clean) {
          console.error('[VOCAB_BAN] Regeneration STILL violates bans:', recheck.violations.map(v => v.id));
      } else {
          console.log('[VOCAB_BAN] Regeneration passed vocabulary check');
      }

      return regenerated;
  }

  /**
   * Cinematic Metaphor Quality Guard — fires only for safe-mode ST3+ scenes
   * where buildSafeST3Directive picked a domain and stashed it on state.
   * Two failure modes trigger one regenerate with a strict-mode hint:
   *   1. Evasive filler matches (`_CINEMATIC_EVASIVE_PATTERNS`)
   *   2. No domain-signal vocabulary present (LLM picked the directive but
   *      drifted into a different metaphor or none at all)
   *   3. Beat coverage too low — fewer than 2 of 4 dramatic-arc beats
   *      (approach / escalation / climax / aftermath) detected for the
   *      picked domain. Skipped on short scenes (< MIN_LEN_FOR_BEATS)
   *      since interruption/hesitation paths legitimately can't hit 2.
   *   4. Domain-keyword stuffing — only checked on first pass; the
   *      threshold scales with text length so long scenes that
   *      legitimately repeat vocabulary aren't false-flagged.
   *
   * Single retry only (no chaining). Stuffing is NOT re-checked on the
   * second pass — accept whatever the regenerator produces per the
   * guide-don't-fight rule.
   *
   * Retries + per-beat misses are tallied on `state._cinematicTelemetry`
   * so weak regex cells can be identified after a few real scenes.
   *
   * @param {string}   text          - generated scene text
   * @param {string}   domain        - the metaphor domain stashed on state
   * @param {function} regenerateFn  - async (negativeConstraint: string) => string
   * @param {object}   state         - story state (for telemetry; optional)
   * @returns {Promise<string>}      - clean (or best-effort) text
   */
  async function enforceCinematicMetaphorQuality(text, domain, regenerateFn, state) {
      if (!domain) return text;

      const failsEvasion = _failsCinematicEvasion(text);
      const failsSignal  = !_domainSignalOk(text, domain);
      const beatReport   = _beatCoverageReport(text, domain);
      const failsBeats   = (text && text.length > MIN_LEN_FOR_BEATS) && !beatReport.ok;
      const failsStuffing = _domainSignalDensityFail(text, domain); // first-pass only

      if (!failsEvasion && !failsSignal && !failsBeats && !failsStuffing) return text;

      if (!regenerateFn) {
          console.warn('[CINEMATIC] Quality check failed but no regenerator',
              { failsEvasion, failsSignal, failsBeats, failsStuffing, domain });
          return text;
      }

      // Telemetry — log misses BEFORE retrying so we know what the model
      // dropped on the first pass.
      if (failsBeats) _logBeatMisses(state, domain, beatReport.misses);
      _logCinematicRetry(state, domain);

      const reasons = [];
      if (failsEvasion)  reasons.push('evasive filler detected (e.g., "the room did what rooms do")');
      if (failsSignal)   reasons.push(`no "${domain}" domain vocabulary present`);
      if (failsBeats)    reasons.push(`beat coverage too low (missed: ${beatReport.misses.join(', ')})`);
      if (failsStuffing) reasons.push(`domain keyword density too high — write metaphor, not vocabulary salad`);
      console.warn('[CINEMATIC] Regenerating —', reasons.join('; '));

      const constraint =
          `\n\nSTRICT CINEMATIC RETRY: Your previous draft failed: ${reasons.join('; ')}.\n` +
          `Use a single "${domain}" metaphor with explicit beat mapping ` +
          `(approach→pressure/orbit, escalation→build/strain, climax→rupture/break, aftermath→stillness/debris). ` +
          `No filler, no personified rooms/lamps/night, no self-aware deflection, no keyword stuffing.`;

      const regenerated = await regenerateFn(constraint);

      // Second-pass observability ONLY — single-retry rule means we accept
      // the regenerated text regardless. Stuffing is intentionally NOT
      // re-checked here (would create a feedback loop with the strict note).
      const stillEvasive    = _failsCinematicEvasion(regenerated);
      const stillUnsignaled = !_domainSignalOk(regenerated, domain);
      const secondReport    = _beatCoverageReport(regenerated, domain);
      const stillThinBeats  = (regenerated && regenerated.length > MIN_LEN_FOR_BEATS) && !secondReport.ok;
      if (stillEvasive || stillUnsignaled || stillThinBeats) {
          console.error('[CINEMATIC] Regeneration STILL fails',
              { stillEvasive, stillUnsignaled, stillThinBeats, misses: secondReport.misses, domain });
      } else {
          console.log('[CINEMATIC] Regeneration passed metaphor quality check');
      }
      return regenerated;
  }

