  function openProfileModal() {
      populateProfileStatus();
      document.getElementById('profileModal')?.classList.remove('hidden');
      try { if (typeof window._initLangSelectors === 'function') window._initLangSelectors(); } catch (_) {}
  }
  window.openProfileModal = openProfileModal;

  window.closeProfileModal = function() {
      document.getElementById('profileModal')?.classList.add('hidden');
  };

  async function populateProfileStatus() {
      const el = document.getElementById('profileStatusContent');
      if (!el) return;

      // Refresh storypass fortunes from DB (may have been zeroed by refund webhook)
      if (state.storyId && typeof _loadStorypassFortunes === 'function') {
        await _loadStorypassFortunes();
      }

      // 2026-06-02 (Roman): Re-hydrate subscription tier from Supabase before
      // rendering. The Account panel previously read in-memory state set at
      // page load, so a Stripe-portal cancellation that fired the webhook
      // AFTER the user landed wouldn't surface until the next full reload.
      // Symptom: user canceled Favored via Stripe, hard-refreshed, still saw
      // "Favored" in Account. Fetching fresh now keeps this view honest.
      // Fire-and-await: short Supabase round-trip; profileModal blocks input
      // already so the tiny delay is invisible.
      try {
          if (_supabaseProfileId && typeof hydrateProfile === 'function') {
              const _fresh = await hydrateProfile(_supabaseProfileId);
              if (_fresh && typeof hydrateState === 'function') {
                  // Capture live ephemeral fields hydrateState would clobber,
                  // mirror the loadStorySnapshot pattern from app.js:82322.
                  const _liveFortunes = state.fortunes;
                  hydrateState(_fresh);
                  // hydrateState pulls fortunes from the profile (canonical),
                  // but only restore live fortunes if the in-memory value is
                  // HIGHER (mid-session purchase not yet round-tripped).
                  if (typeof _liveFortunes === 'number' && _liveFortunes > (state.fortunes || 0)) {
                      state.fortunes = _liveFortunes;
                  }
              }
          }
      } catch (e) {
          console.warn('[ACCOUNT:REFRESH] subscription tier re-hydrate failed (non-blocking):', e && e.message);
      }

      const tierMap = { free: 'Tease', paid: 'Storied', storied: 'Storied', favored: 'Favored', chosen: 'Chosen' };
      const tier = state.tier || 'free';
      const hasPass = state.hasPass || (typeof hasStorypassForCurrentStory === 'function' && hasStorypassForCurrentStory());
      let tierDisplay = tierMap[tier] || tier;
      if (hasPass && tierDisplay === 'Tease') tierDisplay = 'Storypass';
      if (state.subscriptionTier === 'favored') tierDisplay = 'Favored';
      if (state.subscriptionTier === 'chosen') tierDisplay = 'Chosen';
      if (!state.subscribed) tierDisplay = tierMap[tier] || tier;  // belt-and-suspenders: canceled subs land here
      // 2026-06-02 (Roman): surface portal-scheduled cancellation. The sub
      // is still active and the user retains full benefits until the date
      // in billingGraceUntil — but they cancelled in Stripe and need to
      // know when it actually ends.
      if (state.billingStatus === 'canceling' && state.billingGraceUntil) {
          try {
              const _endDate = new Date(state.billingGraceUntil);
              const _endLabel = _endDate.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' });
              tierDisplay += ' (ending ' + _endLabel + ')';
          } catch (_) {
              tierDisplay += ' (ending soon)';
          }
      }

      const resonanceState = getFateResonanceState();
      const resonanceDisplay = resonanceState !== 'Quiet'
          ? `<div><strong>Fate Resonance:</strong> ${resonanceState}</div>`
          : '';

      const echoCount = state.bonus_tempt_charges || 0;
      const echoDisplay = `<div style="font-size:0.85em;color:rgba(218,165,32,0.55);margin-top:4px;">Tempt Fate (Earned): ${echoCount}</div>`;

      const fortuneLines = `<div><strong>Fortunes:</strong> ${state.fortunes || 0}</div>`;
      const freeTasteLine = '';

      var manageLink = (state.subscribed || state.subscriptionTier)
          ? '<div style="margin-top:8px;"><a href="#" onclick="window.openBillingPortal();return false;" style="color:#c9a84c;font-size:0.85em;">Manage Subscription</a></div>'
          : '';

      el.innerHTML =
          `<div><strong>Tier:</strong> ${tierDisplay}</div>` +
          fortuneLines +
          freeTasteLine +
          resonanceDisplay +
          echoDisplay +
          manageLink;
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // NAVIGATION CONTRACT — STORYBOUND READER FLOW (AUTHORITATIVE)
  // TAG: storybound/navigation-contract-v1
  // ═══════════════════════════════════════════════════════════════════════════

  // ───────────────────────────────────────────────
  // SECTION 1 — CANONICAL STORY CREATION FLOW (LOCKED)
  // ───────────────────────────────────────────────
  // The authoritative forward navigation order for a new story is:
  //
  // 1. Shape Your Story
  // 2. Cover Display (single cover view, NOT gallery)
  // 3. Setting
  // 4. Story (Scene 1)
  //
  // This order must be preserved.
  //
  // Notes:
  // - The Cover Display is part of the main flow.
  // - The Cover Gallery is NOT part of the main flow.
  // - The Cover Display shows the current cover state
  //   (Sketch / Thumbnail / Final), if available.
  // ───────────────────────────────────────────────

  // ───────────────────────────────────────────────
  // SECTION 2 — RESTART / RESUME FLOW (LOCKED)
  // ───────────────────────────────────────────────
  // When a user resumes an existing story:
  //
  // 1. Show the Cover Display (single cover view)
  // 2. Then load the most recent Story scene
  //
  // This applies regardless of:
  // - cover completion state
  // - number of scenes written
  // - story length tier
  //
  // Rationale:
  // - The cover re-orients tone and promise.
  // - Every reading session begins at the book's cover.
  // ───────────────────────────────────────────────

  // ───────────────────────────────────────────────
  // SECTION 3 — BACK BUTTON CONTRACT (AUTHORITATIVE)
  // ───────────────────────────────────────────────
  // The Back button must reverse the canonical flow
  // and must never route to side chambers by default.
  //
  // Back behavior by context:
  //
  // - From Story:
  //   → Setting
  //
  // - From Setting:
  //   → Cover Display (single view)
  //
  // - From Cover Display:
  //   → Shape Your Story
  //
  // - From Shape Your Story:
  //   → Exit / Mode Select (existing behavior)
  //
  // At no point may the Back button route to:
  // - Cover Gallery
  // - Cover regeneration views
  // - Any modal or optional artifact browser
  // ───────────────────────────────────────────────

  // ───────────────────────────────────────────────
  // SECTION 4 — SIDE CHAMBERS (NON-PARENTAL)
  // ───────────────────────────────────────────────
  // The following are side chambers, not navigation parents:
  //
  // - Cover Gallery
  // - Fate Card detail views
  // - Visualizer previews
  // - Help / Settings modals
  //
  // Rules:
  // - Side chambers are entered only via explicit user action.
  // - Exiting a side chamber returns the user
  //   to the immediate prior context.
  // - Side chambers must never appear in Back history
  //   unless explicitly navigated to.
  // ───────────────────────────────────────────────

  // ───────────────────────────────────────────────
  // SECTION 5 — PRECEDENCE CLAUSE (FAILSAFE)
  // ───────────────────────────────────────────────
  // If any conflict exists between:
  // - legacy navigation logic
  // - modal history
  // - inferred routing
  // - Back-button heuristics
  //
  // This Navigation Contract overrides them.
  // ───────────────────────────────────────────────

  // ═══════════════════════════════════════════════════════════════════════════
  // CANONICAL STATES — FIRST-CLASS NAVIGATION STATES (AUTHORITATIVE)
  // TAG: storybound/canonical-states-v1
  // ═══════════════════════════════════════════════════════════════════════════

  // ───────────────────────────────────────────────
  // PART 1 — CANONICAL STATES (ORDERED)
  // ───────────────────────────────────────────────
  // 1. SHAPE_YOUR_STORY  (screen: 'setup')
  // 2. COVER_DISPLAY     (screen: 'game', _readerPage: 0)
  // 3. SETTING           (screen: 'game', _readerPage: 'setting')
  // 4. STORY_READER      (screen: 'game', _readerPage: >= 1)
  //
  // Notes:
  // - COVER_DISPLAY is a single-cover view, not a gallery.
  // - SETTING is a full page/state, not a modal or overlay.
  // - STORY_READER begins at Scene 1.
  // ───────────────────────────────────────────────

  const CANONICAL_STATES = {
      SHAPE_YOUR_STORY: 'setup',
      COVER_DISPLAY: 'coverDisplay',
      SETTING: 'setting',
      STORY_READER: 'storyReader'
  };

  const CANONICAL_STATE_ORDER = [
      CANONICAL_STATES.SHAPE_YOUR_STORY,
      CANONICAL_STATES.COVER_DISPLAY,
      CANONICAL_STATES.SETTING,
      CANONICAL_STATES.STORY_READER
  ];

  // ───────────────────────────────────────────────
  // PART 2 — COVER_DISPLAY STATE (DEFINITION)
  // ───────────────────────────────────────────────
  // Behavior:
  // - Renders the current story's primary cover only.
  // - If no cover exists, render a placeholder + CTA.
  // - Must not allow browsing alternate covers.
  // - Must not auto-open Cover Gallery.
  //
  // Rules:
  // - COVER_DISPLAY is part of the main flow.
  // - COVER_DISPLAY is NOT a modal.
  // - COVER_DISPLAY has a Back destination and a Forward destination.
  // ───────────────────────────────────────────────

  // ───────────────────────────────────────────────
  // PART 3 — SETTING STATE (RESTORATION)
  // ───────────────────────────────────────────────
  // Behavior:
  // - Displays world, location, and initial conditions.
  // - Occurs after COVER_DISPLAY and before STORY_READER.
  // - Is revisitable via Back navigation from STORY_READER.
  //
  // Rules:
  // - SETTING must not be collapsed into Shape or Story.
  // - SETTING must not be implemented as a modal.
  // - SETTING participates in Back-button reversal.
  // ───────────────────────────────────────────────

  // ───────────────────────────────────────────────
  // PART 4 — FORWARD NAVIGATION (LOCKED)
  // ───────────────────────────────────────────────
  // Canonical forward flow:
  //
  // SHAPE_YOUR_STORY
  // → COVER_DISPLAY
  // → SETTING
  // → STORY_READER (Scene 1)
  //
  // This flow must be respected for:
  // - new stories
  // - regenerated stories
  // - restarted stories
  // ───────────────────────────────────────────────

  // ───────────────────────────────────────────────
  // PART 5 — RESTART / RESUME FLOW (LOCKED)
  // ───────────────────────────────────────────────
  // When resuming an existing story:
  //
  // 1. Enter COVER_DISPLAY
  // 2. Then proceed to the most recent STORY_READER scene
  //
  // SETTING is skipped on resume unless explicitly navigated to.
  // ───────────────────────────────────────────────

  // ───────────────────────────────────────────────
  // PART 6 — BACK BUTTON INTEGRATION (AUTHORITATIVE)
  // ───────────────────────────────────────────────
  // Back behavior must reverse the canonical state order:
  //
  // - From STORY_READER → SETTING
  // - From SETTING → COVER_DISPLAY
  // - From COVER_DISPLAY → SHAPE_YOUR_STORY
  //
  // At no point may Back route to:
  // - Cover Gallery
  // - Any modal
  // - Any non-canonical state
  // ───────────────────────────────────────────────

  // ───────────────────────────────────────────────
  // PART 7 — FAILURE PREVENTION CLAUSE
  // ───────────────────────────────────────────────
  // "If a state does not exist as a first-class state,
  // it may not be used as a Back or Forward destination."
  // ───────────────────────────────────────────────

  // --- NAVIGATION STATE ---
  let _navHistory = [];
  let _currentScreenId = 'legalGate';

  function updateNavUI() {
      const backBtn = document.getElementById('globalBackBtn');
      const burger = document.getElementById('burgerBtn');

      if(backBtn) {
          const hidden = ['ageGate', 'legalGate'].includes(_currentScreenId);
          if(hidden) backBtn.classList.add('hidden');
          else backBtn.classList.remove('hidden');
      }
      
      if(burger) {
          if(_currentScreenId === 'legalGate') burger.classList.add('hidden');
          else burger.classList.remove('hidden');
      }
  }

  function goBack() {
      // tierGate → back to legalGate (re-read bindings)
      if (_currentScreenId === 'tierGate') {
          showScreen('legalGate');
          // If all pacts already accepted, show Proceed button so user can advance
          if (_pactAccepted.tos && _pactAccepted.privacy && _pactAccepted.adult) {
              var proceedBtn = document.getElementById('pactProceedBtn');
              if (proceedBtn) {
                  proceedBtn.classList.remove('hidden');
                  proceedBtn.onclick = function() {
                      if (window.playUISound) window.playUISound('button_click');
                      proceedBtn.classList.add('hidden');
                      showScreen('tierGate');
                  };
              }
          }
          return;
      }

      // LINEAR READER NAVIGATION (book system disabled)
      if (_currentScreenId === 'game') {
          if (!USE_OPENING_BOOK) {
              // Back in-story → step back through pages (preserve story state)
              if (_readerPage >= 2) {
                  // From scene → cover (synopsis page removed 2026-05-28; was page 1)
                  showReaderPage(0);
                  return;
              }
              if (_readerPage === 1) {
                  // From synopsis → cover
                  showReaderPage(0);
                  return;
              }
              // At Cover (page 0) — go back to corridor "Begin Story" page
              window.showScreen('setup', true);
              if (typeof navigateToCorridorRow === 'function' && typeof STAGE_INDEX !== 'undefined') {
                  setTimeout(function() { navigateToCorridorRow(STAGE_INDEX.beginstory); }, 50);
              }
              return;
          } else {
              // BOOK SYSTEM (disabled — this branch won't run when USE_OPENING_BOOK = false)
              const bookCover = document.getElementById('bookCover');
              const isBookOpen = bookCover?.classList.contains('hinge-open') || _bookOpened;

              if (isBookOpen && _bookPageIndex > 0) {
                  if (typeof previousBookPage === 'function' && previousBookPage()) {
                      return;
                  }
              }

              if (isBookOpen && _bookPageIndex === 0) {
                  const bookCoverPage = document.getElementById('bookCoverPage');
                  const storyContent = document.getElementById('storyContent');
                  if (bookCover) {
                      bookCover.classList.remove('hinge-open', 'courtesy-peek');
                  }
                  if (bookCoverPage) {
                      bookCoverPage.classList.remove('hidden');
                  }
                  if (storyContent) {
                      storyContent.classList.add('hidden');
                  }
                  _bookOpened = false;
                  setBookPage(0);
                  return;
              }
          }
      }

      // modeSelect clears _navHistory — explicit back to Private Library
      // (vaultLibraryScreen). Tease/Indulge tierGate is no longer part of
      // the flow above modeSelect.
      if (_currentScreenId === 'modeSelect') {
          window.showScreen('vaultLibraryScreen', true);
          return;
      }

      // CORRIDOR BACK: Step back one corridor row instead of exiting to modeSelect
      if (_currentScreenId === 'setup' && document.body.classList.contains('corridor-mode')) {
          if (corridorActiveRowIndex > 0) {
              navigatePrevRow();
              return;
          }
          // At row 0 — fall through to exit corridor → modeSelect
      }

      if (_navHistory.length === 0) {
          if(typeof coupleCleanup === 'function' && state.mode === 'couple') coupleCleanup();
          window.showScreen('modeSelect');
          return;
      }
      const prev = _navHistory.pop();
      window.showScreen(prev, true);
  }

  window.showScreen = function(id, isBack = false){
      if (document.body.classList.contains('booting')) {
        if (window.__initialScreenSet) return;
        window.__initialScreenSet = true;
      }
      closeAllOverlays();
      // PASS 1 FIX: Clear any stuck toasts on screen change
      if (typeof clearToasts === 'function') clearToasts();

      // Capture previous screen for BACK-TO-CONFIG detection
      const previousScreen = _currentScreenId;

      // UX-2 FIX: Clean up fate visuals when leaving setup screen
      // GUARD: Skip cleanup if Guided Fate visuals are still active (will be torn down later)
      if (_currentScreenId === 'setup' && id !== 'setup') {
          if (!_guidedFateVisualsActive && typeof cleanupFateVisuals === 'function') cleanupFateVisuals();
      }

      // Hide corridor Continue button when leaving setup screen
      if (id !== 'setup') {
          const controlPlaneBtn = document.getElementById('continueButton');
          if (controlPlaneBtn) controlPlaneBtn.classList.remove('visible');
      }

      // Scroll-unlock guard: body.corridor-mode sets overflow:hidden to keep the
      // card-selection flow locked to one viewport. If navigation leaves setup via
      // any path that didn't go through the corridor-complete handler, the class
      // can persist and block scroll in the reader. Strip it whenever we leave setup.
      if (id !== 'setup' && document.body.classList.contains('corridor-mode')) {
          document.body.classList.remove('corridor-mode');
      }
      // Symmetric restore: when returning to setup and the active row is still
      // mid-corridor (not yet at the final beginstory row), re-engage corridor
      // styling. Covers two cases:
      //   (a) user navigated back to setup from the reader mid-corridor → simple
      //       re-add when neither class is set.
      //   (b) user had previously COMPLETED the corridor (corridor-complete set)
      //       and is now navigating back to an earlier row (via back-nav, a new
      //       story flow, etc.). Without clearing corridor-complete, the Lora
      //       small-caps section-title styling and flex-grown sections won't
      //       re-engage — titles look big/un-kerned and cards get pushed low.
      if (id === 'setup') {
          var _isMidCorridor = (typeof corridorActiveRowIndex !== 'undefined')
              && (typeof CORRIDOR_STAGES !== 'undefined')
              && corridorActiveRowIndex < (CORRIDOR_STAGES.length - 1);
          if (_isMidCorridor) {
              if (document.body.classList.contains('corridor-complete')) {
                  document.body.classList.remove('corridor-complete');
              }
              if (!document.body.classList.contains('corridor-mode')) {
                  document.body.classList.add('corridor-mode');
              }
          }
      }

      if(id === 'tierGate') {
          // Reset tier cards so they start face-down each time
          if (window.resetTierCards) window.resetTierCards();
      }

      // Leaving modeSelect (or navigating to any non-modeSelect screen) —
      // cancel any pending inactivity-nudge timer so it can't fire on a
      // screen it wasn't meant for. Scoped check so a redundant cancel
      // when staying on modeSelect is cheap and safe.
      if (id !== 'modeSelect' && typeof window._clearModeSelectNudgeTimer === 'function') {
          window._clearModeSelectNudgeTimer();
      }

      if(id === 'modeSelect') {
          _navHistory = [];
          // Update Solo subtitle based on permission gradient
          if (typeof updateSoloSubtitle === 'function') updateSoloSubtitle();
          // Reset mode cards so they start face-down each time
          if (window.resetModeCards) window.resetModeCards();
          // First-shape session: pin the Concierge summon figure as soon as
          // the user exits the Private Library into modeSelect, and fire the
          // initial whisper. Deferred to next task so window._showSummon is
          // definitely assigned (same IIFE-sync timing race fix as in
          // initCorridor). Also arms the modeSelect inactivity-nudge timer
          // (separate from the corridor hesitation chain, which is gated to
          // body.corridor-mode).
          setTimeout(function() {
              try {
                  if (state.isFirstShapeSession) {
                      if (typeof window._showSummon === 'function') window._showSummon();
                      if (typeof window._renderConciergeWhisper === 'function') window._renderConciergeWhisper('modeSelect');
                      if (typeof window._armModeSelectNudgeTimer === 'function') window._armModeSelectNudgeTimer();
                  }
              } catch (_) {}
          }, 0);
      } else if (!isBack && _currentScreenId && _currentScreenId !== id) {
         if(!['ageGate', 'legalGate', 'tierGate'].includes(_currentScreenId)) {
             _navHistory.push(_currentScreenId);
         }
      }

      document.querySelectorAll('.screen').forEach(el => el.classList.add('hidden'));

      const target = document.getElementById(id);
      if(target) target.classList.remove('hidden');
      
      const app = document.getElementById('app');
      if (app && target) {
          if (app.contains(target)) app.classList.remove('hidden');
          else app.classList.add('hidden');
      }

      // CORRECTIVE PASS FIX 4: Do NOT scroll when entering game screen
      // The game screen uses a fixed book cover page overlay that handles its own viewport.
      // Scrolling to top during the loading transition causes a jarring jump.
      if (id !== 'game') {
          window.scrollTo(0,0);
      }
      _currentScreenId = id;
      window._currentScreenId = id;
      updateNavUI();
      // Update fortune widget visibility on screen change
      if (window.updateFortuneDisplay) window.updateFortuneDisplay();

      // Update DSP visibility based on screen (state-based, not scroll-based)
      if (typeof updateDSPVisibility === 'function') {
          updateDSPVisibility(id);
      }

      // Initialize fate hand system when entering setup screen
      if(id === 'setup') {
          // ═══════════════════════════════════════════════════════════════
          // BACK-TO-CONFIG RESET — Re-arm generation when navigating back
          // ═══════════════════════════════════════════════════════════════
          // When user navigates back to Story Settings:
          // - Guided Fate cards become active again
          // - Prior story/cover is discarded (treated as new session)
          // - Clear "already generated" flags
          // - Do NOT auto-generate, just re-arm the system
          // ═══════════════════════════════════════════════════════════════
          if (isBack && previousScreen === 'game') {
              console.log('[BACK-TO-CONFIG] User navigated back to setup — re-arming generation system');

              // Clear prior story/cover assets
              state._backgroundStoryText = null;
              state._backgroundStoryTitle = null;
              state._backgroundStorySynopsis = null;
              state._synopsisMetadata = null;
              state._synopsisBlurb = null;
              state._titlePageShown = false;

              // Reset cover Assembly object tracking (treat as new story)
              state._coverAssemblyObjectShown = false;
              state._coverAssemblyObject = null;
              state._coverWorldKey = null;

              // Reset cover generation flags (re-arms for new cover)
              if (window.resetCoverGenerationFlags) window.resetCoverGenerationFlags();

              // Reset cover shape hash (allows regeneration with new selections)
              if (window.clearCoverShapeHash) window.clearCoverShapeHash();

              // Reset background story flags
              if (window.resetBackgroundStory) window.resetBackgroundStory();

              // Reset DSP state for fresh generation
              if (typeof resetDSPState === 'function') resetDSPState();

              // Clear cover image
              const coverImg = document.getElementById('bookCoverImg');
              if (coverImg) coverImg.src = '';

              // Clear title (will be regenerated)
              const storyTitle = document.getElementById('storyTitle');
              if (storyTitle) storyTitle.textContent = '';

              // Re-activate Guided Fate cards (they should be interactive again)
              // The initFateHandSystem call below will reinitialize them

              console.log('[BACK-TO-CONFIG] Complete — next Generate action will be treated as first-time');
          }

          initFateHandSystem();
          // Start ambient sparkles around the Guided Fate card
          if (typeof startAmbientCardSparkles === 'function') startAmbientCardSparkles();
          // Couple/stranger subhead removed — pink text no longer shown
          const coupleSubhead = document.getElementById('coupleSubhead');
          if (coupleSubhead) coupleSubhead.classList.add('hidden');
          // "Shape Your Story Together" in couple/stranger modes
          var sysTitle = document.getElementById('shapeYourStoryTitle');
          if (sysTitle) sysTitle.textContent = (state.mode === 'couple' || state.mode === 'stranger') ? 'Shape Your Story Together' : 'Shape Your Story';
          // Show breadcrumb at 'shape' step
          if (window.updateBreadcrumb) window.updateBreadcrumb('shape');
          // Update Fortune display
          if (window.updateFortuneDisplay) window.updateFortuneDisplay();
      } else if (id === 'game') {
          // Game screen breadcrumb is managed by Cover/Setting/Story views
          // Don't update here — let the view functions handle it
      } else {
          if (typeof stopAmbientCardSparkles === 'function') stopAmbientCardSparkles();
          // Stop fate card sparkle cycle when leaving game screen
          if (window.stopSparkleCycle) window.stopSparkleCycle();
          // Hide breadcrumb on non-story screens (modeSelect, tierGate, etc.)
          if (window.hideBreadcrumb) window.hideBreadcrumb();
      }
  };

  function initNavBindings() {
      const app = document.getElementById('app');
      if (app) {
          Array.from(app.children).forEach(el => {
              if (el.tagName === 'DIV') el.classList.add('screen');
          });
      }
      ['ageGate', 'legalGate', 'tierGate'].forEach(id => {
          const el = document.getElementById(id);
          if (el) el.classList.add('screen');
      });

      const backBtn = document.getElementById('globalBackBtn');
      if(backBtn && !backBtn.dataset.navBound) {
          backBtn.dataset.navBound = "true";
          backBtn.addEventListener('click', goBack);
      }
      
      // Global Locked Click Delegation
      // Allows preview buttons within locked cards to still function
      if (!document._lockedClickBound) {
          document._lockedClickBound = true;
          document.addEventListener('click', (e) => {
              // Allow preview buttons to work even in locked cards
              // Check both the target and all ancestors for .preview-btn
              const previewBtn = e.target.closest('.preview-btn');
              if (previewBtn) {
                  // Explicitly show preview and stop - don't let anything else handle this
                  e.stopPropagation();
                  const previewText = document.getElementById('previewText');
                  const previewModal = document.getElementById('previewModal');
                  if (previewText && previewModal && previewBtn.dataset.txt) {
                      previewText.textContent = previewBtn.dataset.txt;
                      previewModal.classList.remove('hidden');
                  }
                  return;
              }

              const lockedTarget = e.target.closest('.locked, .locked-style, .locked-input, .locked-taste, .locked-pass, [data-locked]');
              if (lockedTarget) {
                  e.preventDefault();
                  e.stopPropagation();
                  e.stopImmediatePropagation();

                  window.openPaywall(lockedTarget.dataset.paywallMode || 'unlock');
              }
          }, true);
      } 

      document.addEventListener('keydown', (e) => {
          if (e.ctrlKey && e.shiftKey && (e.key === 'a' || e.key === 'A')) {
              const p = document.getElementById('auth-panel');
              if(p) p.classList.toggle('hidden');
          }
      });
  }

  // --- SAFETY & CONSENT ---
  // PASS 1 FIX: Toast system with proper auto-dismiss and anti-stacking
  let _toastTimer = null;

  // Reusable info modal — for "can't do that, here's why" cases where a
  // 3-second toast is too easy to miss. The toast (showToast below) is
  // still the right choice for transient confirmations; showInfoModal is
  // for explanations the user needs to actually read.
  // body accepts HTML so the caller can include <strong>, <em>, links, etc.
  function showInfoModal(title, body) {
      var existing = document.getElementById('_genericInfoModal');
      if (existing) existing.remove();
      var modal = document.createElement('div');
      modal.id = '_genericInfoModal';
      modal.className = 'overlay';
      modal.style.zIndex = '10095';
      modal.innerHTML =
        '<div class="box" style="max-width:460px; padding: 28px 32px; text-align:center;">' +
          '<h3 style="margin: 0 0 14px; color: var(--gold);">' +
            String(title || '').replace(/[<>]/g, '') +
          '</h3>' +
          '<div style="margin: 0 0 22px; font-size: 14px; line-height: 1.55; color: rgba(240,233,214,0.88); text-align: left;">' +
            String(body || '') +
          '</div>' +
          '<button class="sb-btn-png md" id="_genericInfoModalOk">Got it</button>' +
        '</div>';
      document.body.appendChild(modal);
      function close() {
        if (modal.parentNode) modal.parentNode.removeChild(modal);
        document.removeEventListener('keydown', onEsc);
      }
      document.getElementById('_genericInfoModalOk').addEventListener('click', close);
      modal.addEventListener('click', function(e) { if (e.target === modal) close(); });
      function onEsc(e) { if (e.key === 'Escape') close(); }
      document.addEventListener('keydown', onEsc);
  }
  window.showInfoModal = showInfoModal;

  function showToast(msg) {
      const t = document.getElementById('toast');
      if (!t) return;

      // Clear any existing toast timer to prevent stacking
      if (_toastTimer) {
          clearTimeout(_toastTimer);
          _toastTimer = null;
      }

      // Set content and show
      t.textContent = msg;
      t.classList.remove('hidden');

      // Reset animation by forcing reflow
      t.style.animation = 'none';
      void t.offsetWidth;
      t.style.animation = 'toastFadeInOut 3s forwards';

      // Explicit hide after animation completes (failsafe)
      _toastTimer = setTimeout(() => {
          t.classList.add('hidden');
          t.style.animation = 'none';
          _toastTimer = null;
      }, 3100);
  }

  // Persistent reward modal — used when a notification MUST be read, not
  // glimpsed (subscriber bonus on Fortune-pack purchase is the first case).
  // Stays on screen until the user clicks the acknowledge button.
  function showSubscriberBonusReward(bonusAmount, tierName) {
      if (!bonusAmount || bonusAmount <= 0) return;
      // Idempotency: don't stack if one is already open.
      if (document.getElementById('subscriberBonusReward')) return;

      var backdrop = document.createElement('div');
      backdrop.id = 'subscriberBonusReward';
      backdrop.style.cssText =
          'position:fixed;inset:0;z-index:100000;' +
          'background:rgba(0,0,0,0.72);' +
          'display:flex;align-items:center;justify-content:center;' +
          'animation:subBonusFadeIn 0.35s ease-out;';

      var card = document.createElement('div');
      card.style.cssText =
          'background:linear-gradient(155deg,#1a1306 0%,#2a1f0a 60%,#1a1306 100%);' +
          'border:2px solid #c9a24e;' +
          'border-radius:12px;' +
          'padding:32px 36px 28px;' +
          'max-width:420px;width:88%;' +
          'box-shadow:0 8px 40px rgba(0,0,0,0.7),0 0 24px rgba(201,162,78,0.25);' +
          'text-align:center;' +
          'font-family:inherit;color:#f0e3c0;';

      var tierLabel = (tierName || 'Subscriber');
      tierLabel = tierLabel.charAt(0).toUpperCase() + tierLabel.slice(1);

      card.innerHTML =
          '<div style="font-size:13px;letter-spacing:0.25em;text-transform:uppercase;color:#c9a24e;margin-bottom:14px;">Fate Rewards You</div>' +
          '<div style="font-size:48px;font-weight:800;color:#ffd97a;margin:6px 0 4px;line-height:1;">+' + bonusAmount + '</div>' +
          '<div style="font-size:16px;color:#f0e3c0;margin-bottom:6px;">Fortunes — free</div>' +
          '<div style="font-size:13px;color:#c9a24e;font-style:italic;margin-bottom:24px;">' + tierLabel + ' subscriber bonus (+10%)</div>' +
          '<button id="subscriberBonusRewardOk" type="button" style="' +
              'background:linear-gradient(180deg,#c9a24e 0%,#a07c30 100%);' +
              'color:#1a1306;border:none;border-radius:6px;' +
              'padding:11px 28px;font-size:14px;font-weight:700;' +
              'letter-spacing:0.1em;text-transform:uppercase;cursor:pointer;' +
              'box-shadow:0 2px 8px rgba(0,0,0,0.5);' +
              '">Got It</button>';

      backdrop.appendChild(card);

      // Inject keyframes once.
      if (!document.getElementById('subBonusKeyframes')) {
          var style = document.createElement('style');
          style.id = 'subBonusKeyframes';
          style.textContent =
              '@keyframes subBonusFadeIn{from{opacity:0;transform:scale(0.96)}to{opacity:1;transform:scale(1)}}';
          document.head.appendChild(style);
      }

      var dismiss = function() {
          if (backdrop.parentNode) backdrop.parentNode.removeChild(backdrop);
      };
      document.body.appendChild(backdrop);
      var okBtn = card.querySelector('#subscriberBonusRewardOk');
      if (okBtn) okBtn.addEventListener('click', dismiss);
      // Backdrop click does NOT dismiss — must click the button (per request,
      // notification stays until acknowledged).
  }
  window.showSubscriberBonusReward = showSubscriberBonusReward;

  // Persistent "sorry, Fate stumbled" modal — shown when a scene-gen failure
  // is auto-detected and we comp the player a free Tempt Fate charge. Same
  // shape as the subscriber-bonus reward: stays until acknowledged.
  function showSorryTemptModal() {
      if (document.getElementById('sorryTemptReward')) return;

      var backdrop = document.createElement('div');
      backdrop.id = 'sorryTemptReward';
      backdrop.style.cssText =
          'position:fixed;inset:0;z-index:100000;' +
          'background:rgba(0,0,0,0.72);' +
          'display:flex;align-items:center;justify-content:center;' +
          'animation:subBonusFadeIn 0.35s ease-out;';

      var card = document.createElement('div');
      card.style.cssText =
          'background:linear-gradient(155deg,#1a1306 0%,#2a1f0a 60%,#1a1306 100%);' +
          'border:2px solid #c9a24e;' +
          'border-radius:12px;' +
          'padding:32px 36px 28px;' +
          'max-width:440px;width:88%;' +
          'box-shadow:0 8px 40px rgba(0,0,0,0.7),0 0 24px rgba(201,162,78,0.25);' +
          'text-align:center;' +
          'font-family:inherit;color:#f0e3c0;';

      card.innerHTML =
          '<div style="font-size:13px;letter-spacing:0.25em;text-transform:uppercase;color:#c9a24e;margin-bottom:14px;">Fate Stumbled</div>' +
          '<div style="font-size:15px;line-height:1.5;color:#f0e3c0;margin-bottom:14px;">Something snagged mid-scene. Your last finished scene is safe — just submit again to continue.</div>' +
          '<div style="font-size:34px;font-weight:800;color:#ffd97a;margin:14px 0 4px;line-height:1;">+1 Tempt Fate</div>' +
          '<div style="font-size:13px;color:#c9a24e;font-style:italic;margin-bottom:24px;">on the house — sorry for the snag</div>' +
          '<button id="sorryTemptOk" type="button" style="' +
              'background:linear-gradient(180deg,#c9a24e 0%,#a07c30 100%);' +
              'color:#1a1306;border:none;border-radius:6px;' +
              'padding:11px 28px;font-size:14px;font-weight:700;' +
              'letter-spacing:0.1em;text-transform:uppercase;cursor:pointer;' +
              'box-shadow:0 2px 8px rgba(0,0,0,0.5);' +
              '">Got It</button>';

      backdrop.appendChild(card);
      document.body.appendChild(backdrop);

      var dismiss = function() {
          if (backdrop.parentNode) backdrop.parentNode.removeChild(backdrop);
      };
      var okBtn = card.querySelector('#sorryTemptOk');
      if (okBtn) okBtn.addEventListener('click', dismiss);
  }
  window.showSorryTemptModal = showSorryTemptModal;

  // Subscription re-purchase confirmation modal. Shown when a user clicks
  // a subscription tier in the paywall while they're ALREADY subscribed.
  // Three flavors:
  //   • same tier   → "you already have this"
  //   • upgrade     → "this will move you UP a tier"
  //   • downgrade   → "this will move you DOWN — most users don't mean this"
  // Persistent — must be acknowledged before checkout fires. The Confirm
  // button calls onConfirm() to continue to Stripe; Cancel just dismisses.
  function _tierRank(t) {
      return ({ storied: 1, favored: 2, chosen: 3 })[String(t || '').toLowerCase()] || 0;
  }
  function _showSubscriptionConfirmModal(opts) {
      opts = opts || {};
      var currentTier = String(opts.currentTier || '').toLowerCase();
      var newTier = String(opts.newTier || '').toLowerCase();
      var onConfirm = (typeof opts.onConfirm === 'function') ? opts.onConfirm : function () {};
      var currentLabel = currentTier ? currentTier.charAt(0).toUpperCase() + currentTier.slice(1) : 'Subscribed';
      var newLabel = newTier ? newTier.charAt(0).toUpperCase() + newTier.slice(1) : 'Tier';

      var currentRank = _tierRank(currentTier);
      var newRank = _tierRank(newTier);

      var headline, body, confirmText, cancelText, accentColor;
      if (currentRank === newRank) {
          headline = 'You\'re already ' + currentLabel;
          body = 'Your active membership is ' + currentLabel + '. Subscribing again would add a SECOND, duplicate subscription on your Stripe account — you\'d be billed twice every month. If you wanted more Fortunes this cycle, close this and grab a Fortune pack instead. If you genuinely want a second subscription, continue.';
          confirmText = 'Subscribe again anyway';
          cancelText = 'Cancel';
          accentColor = '#c9a24e';
      } else if (newRank > currentRank) {
          headline = 'Upgrade to ' + newLabel + '?';
          body = 'You\'re currently subscribed to ' + currentLabel + '. Continuing will UPGRADE your membership to ' + newLabel + ' — the higher monthly rate, with the larger Fortune allowance and ' + newLabel + '-exclusive perks. Stripe will prorate the change. Continue?';
          confirmText = 'Upgrade to ' + newLabel;
          cancelText = 'Cancel — keep ' + currentLabel;
          accentColor = '#c9a24e';
      } else {
          headline = 'Downgrade from ' + currentLabel + '?';
          body = 'You\'re currently subscribed to ' + currentLabel + ' — a HIGHER tier than ' + newLabel + '. Continuing will REPLACE your ' + currentLabel + ' membership with ' + newLabel + ', and you\'ll lose ' + currentLabel + '-exclusive benefits going forward. Most players who click here do not mean to downgrade — they\'re trying to top up Fortunes. If you need more Fortunes this cycle, close this and grab a Fortune pack instead.';
          confirmText = 'Downgrade to ' + newLabel;
          cancelText = 'Keep my ' + currentLabel + ' membership';
          accentColor = '#c95a4e';  // amber-red — visual warning for downgrade
      }

      if (document.getElementById('subscriptionConfirmModal')) return;

      var backdrop = document.createElement('div');
      backdrop.id = 'subscriptionConfirmModal';
      backdrop.style.cssText =
          'position:fixed;inset:0;z-index:100001;' +
          'background:rgba(0,0,0,0.78);' +
          'display:flex;align-items:center;justify-content:center;' +
          'animation:subBonusFadeIn 0.35s ease-out;';

      var card = document.createElement('div');
      card.style.cssText =
          'background:linear-gradient(155deg,#1a1306 0%,#2a1f0a 60%,#1a1306 100%);' +
          'border:2px solid ' + accentColor + ';' +
          'border-radius:12px;' +
          'padding:32px 36px 28px;' +
          'max-width:540px;width:90%;' +
          'box-shadow:0 8px 40px rgba(0,0,0,0.7),0 0 24px rgba(201,162,78,0.25);' +
          'text-align:left;' +
          'font-family:inherit;color:#f0e3c0;';

      card.innerHTML =
          '<div style="font-size:13px;letter-spacing:0.25em;text-transform:uppercase;color:' + accentColor + ';margin-bottom:14px;text-align:center;">Confirm Subscription Change</div>' +
          '<div style="font-size:22px;font-weight:700;color:#ffd97a;margin:6px 0 18px;line-height:1.3;text-align:center;">' + headline + '</div>' +
          '<div style="font-size:14px;line-height:1.6;color:#f0e3c0;margin-bottom:24px;">' + body + '</div>' +
          '<div style="display:flex;flex-direction:column;gap:10px;">' +
          '  <button id="subConfirmProceed" type="button" style="' +
                'background:linear-gradient(180deg,' + accentColor + ' 0%,#8a5a20 100%);' +
                'color:#1a1306;border:none;border-radius:6px;' +
                'padding:12px 20px;font-size:14px;font-weight:700;' +
                'letter-spacing:0.08em;text-transform:uppercase;cursor:pointer;' +
                'box-shadow:0 2px 8px rgba(0,0,0,0.5);' +
                '">' + confirmText + '</button>' +
          '  <button id="subConfirmCancel" type="button" style="' +
                'background:transparent;color:#f0e3c0;' +
                'border:1px solid rgba(240,227,192,0.4);border-radius:6px;' +
                'padding:11px 20px;font-size:13px;font-weight:600;' +
                'letter-spacing:0.06em;cursor:pointer;' +
                '">' + cancelText + '</button>' +
          '</div>' +
          '<div style="font-size:11px;color:rgba(240,227,192,0.55);margin-top:18px;text-align:center;line-height:1.5;">Billing questions? <span style="color:#c9a24e;text-decoration:underline;cursor:pointer;" id="subConfirmSupport">Report an Issue → Account / Billing</span></div>';

      backdrop.appendChild(card);
      document.body.appendChild(backdrop);

      var dismiss = function () {
          if (backdrop.parentNode) backdrop.parentNode.removeChild(backdrop);
      };
      card.querySelector('#subConfirmProceed').addEventListener('click', function () {
          dismiss();
          try { onConfirm(); } catch (e) { console.warn('[SUB:CONFIRM] onConfirm threw:', e && e.message); }
      });
      card.querySelector('#subConfirmCancel').addEventListener('click', dismiss);
      card.querySelector('#subConfirmSupport').addEventListener('click', function () {
          dismiss();
          // Route to Report an Issue if the hook exists; otherwise just close.
          try {
              if (typeof window._openReportAnIssue === 'function') window._openReportAnIssue('billing');
              else if (typeof window.openVault === 'function') window.openVault('report');
          } catch (_) {}
      });
  }
  window._showSubscriptionConfirmModal = _showSubscriptionConfirmModal;

  // Lightweight "Fate stumbled" toast — used for tier-A (silent recovery,
  // attempt < threshold) and tier-C (already-granted-for-this-scene). The
  // persistent goodwill modal (showSorryTemptModal) is reserved for tier-B
  // when the same scene fails twice and a Tempt is actually granted.
  function _showSceneStumbleToast() {
      if (typeof showToast === 'function') {
          showToast('Fate stumbled. Your progress is safe.');
      }
  }
  window._showSceneStumbleToast = _showSceneStumbleToast;

  // In-flight guard — prevents a flurry of rejections from queueing N
  // parallel POSTs. Server is authoritative dedup (PK on
  // (user, story, scene) enforces one log row per scene-incident regardless
  // of how many times we POST); this guard is a courtesy short-circuit.
  var _temptFailureInFlight = false;

  // Route the server response into the right UX tier.
  //   source='granted'         → tier-B: persistent modal, +1 charge landed
  //   source='already_granted' → tier-C: toast (we already gave one for this scene)
  //   source='recovered'       → tier-A: toast (attempt count below threshold)
  function _applyTemptFailureResponse(data) {
      if (!data || !data.ok) {
          console.warn('[SCENE-FAIL] Server returned non-ok:', data);
          // Safety net: player still needs to know the scene crashed and
          // retrying is OK. Don't leave them staring at a silent UI.
          _showSceneStumbleToast();
          return;
      }
      if (typeof data.bonus_tempt_charges === 'number') {
          state.bonus_tempt_charges = data.bonus_tempt_charges;
      }
      var src = data.source;
      var n = data.attemptCount || 0;
      if (src === 'granted') {
          console.log('[SCENE-FAIL] Threshold reached (attempt ' + n + ') — granted +1 Tempt (balance=' +
              state.bonus_tempt_charges + ')');
          showSorryTemptModal();
      } else if (src === 'already_granted') {
          console.log('[SCENE-FAIL] Already granted for this scene-incident (attempt ' + n + ') — toast only');
          _showSceneStumbleToast();
      } else if (src === 'recovered') {
          console.log('[SCENE-FAIL] Recovered (attempt ' + n + ' < threshold) — toast only, no grant');
          _showSceneStumbleToast();
      } else {
          console.warn('[SCENE-FAIL] Unknown source from server:', src);
          _showSceneStumbleToast();
      }
  }

  // Record a scene-gen failure server-side. Server decides which tier
  // applies (see _applyTemptFailureResponse). No client-side dedup beyond
  // the single-request in-flight guard — server is authoritative.
  function _recordSceneGenFailure(reason) {
      if (_temptFailureInFlight) {
          console.log('[SCENE-FAIL] POST already in flight — skipping duplicate trigger');
          return false;
      }
      try {
          var sid = String(state.storyId || 'no-story');
          var scnNum = (state.turnCount != null && Number.isFinite(state.turnCount)) ? state.turnCount : -1;
          var reasonClean = String(reason || 'unknown').slice(0, 64);

          // Logged-out / no-profile fallback: can't record server-side, no
          // grant ladder. Still toast so the player sees the system caught
          // the failure.
          if (!_supabaseProfileId) {
              console.log('[SCENE-FAIL] No profile id — toast-only fallback');
              _showSceneStumbleToast();
              return true;
          }

          _temptFailureInFlight = true;
          fetch('/api/record-tempt-failure', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                  userId: _supabaseProfileId,
                  storyId: sid,
                  sceneIdx: scnNum,
                  reason: reasonClean,
              }),
          })
          .then(function(r) { return r.json().catch(function() { return null; }); })
          .then(function(data) {
              _temptFailureInFlight = false;
              _applyTemptFailureResponse(data);
          })
          .catch(function(e) {
              _temptFailureInFlight = false;
              console.warn('[SCENE-FAIL] Server record fetch failed (non-blocking):',
                  e && e.message);
              // Network failure — toast as safety net so the spinner-recovery
              // isn't silent.
              _showSceneStumbleToast();
          });
          return true;
      } catch (e) {
          _temptFailureInFlight = false;
          console.warn('[SCENE-FAIL] Record threw (non-blocking):', e && e.message);
          return false;
      }
  }
  window._recordSceneGenFailure = _recordSceneGenFailure;

  // Recover from an in-flight scene-gen failure: drop the in-flight lock,
  // re-enable the submit button, clear the orphaned cost accumulator, and
  // record the failure server-side (which routes to toast or modal+grant
  // based on the per-scene attempt count). Called from the
  // unhandledrejection listener below.
  function _handleSceneGenFailure(err) {
      try {
          console.error('[SCENE-GEN:FAIL] Caught uncaught rejection during scene gen:', err && (err.message || err));
          state._isAdvancingScene = false;
          var _submitBtn = document.getElementById('submitBtn');
          if (_submitBtn) {
              _submitBtn.classList.remove('submitting');
              _submitBtn.disabled = false;
          }
          if (typeof _clearSceneCostAcc === 'function') _clearSceneCostAcc();
          _recordSceneGenFailure('scene_gen_uncaught');
      } catch (e) {
          console.warn('[SCENE-GEN:FAIL] Recovery handler threw:', e && e.message);
      }
  }
  window._handleSceneGenFailure = _handleSceneGenFailure;

  // Heuristic: is this unhandled rejection plausibly from scene generation?
  // Background work (image preload, audio fetch, telemetry POST, vault save)
  // can also reject while a scene is in flight; granting on those would be
  // wrong. Layered filter:
  //   1. Reason is an Error-like object (not a string, not a primitive, not null).
  //   2. Not an intentional cancellation (AbortError / DOMException 'AbortError').
  //   3. The stack references our authored code (app.js / orchestration-client.js
  //      / fatecards.js). External-library frames don't count by themselves —
  //      our scene-gen call chain always passes through one of these files.
  //   4. The stack is NOT dominated by background-work markers (vault save,
  //      preload, telemetry) — these run during scene gen but aren't the gen
  //      itself, and their failures should not trigger grants.
  function _isPlausibleSceneGenRejection(reason) {
      if (reason == null) return false;
      if (typeof reason !== 'object') return false;
      // AbortController cancellations — intentional, not failures.
      var name = (reason.name || '') + '';
      if (name === 'AbortError') return false;
      // Browser DOMException-style aborts come through with code 20.
      if (reason.code === 20) return false;
      var stack = String(reason.stack || reason.message || '');
      if (!stack) return false;
      var touchesOurCode = /app\.js|orchestration-client\.js|fatecards\.js/.test(stack);
      if (!touchesOurCode) return false;
      // Exclude rejections whose stack TOP frame names a known non-gen path.
      // These run during in-flight scene gen but aren't the gen itself.
      var topFrame = stack.split('\n').slice(0, 3).join('\n');
      var nonGenPattern = /(loadVaultLibrary|preloadNextScene|saveStorySnapshot|recordEvent|track[A-Z]\w*Event|trackTelemetry|fortuneSync|sb_lib_metadata|hydrateProfile)/;
      if (nonGenPattern.test(topFrame)) return false;
      return true;
  }

  // Global unhandledrejection listener — catches async errors that escape the
  // submit handler's nested try/catches. Gated on:
  //   • state._isAdvancingScene (scene gen WAS in flight when this rejected), AND
  //   • _isPlausibleSceneGenRejection (the rejection looks like it came from
  //     scene-gen code, not unrelated background work).
  // Server-side idempotency (grant_tempt_failure RPC) is the ultimate safety
  // net for any false-positive that slips past these two heuristics.
  if (!window._sorryTemptListenerInstalled) {
      window._sorryTemptListenerInstalled = true;
      window.addEventListener('unhandledrejection', function(event) {
          if (!window.state || !state._isAdvancingScene) return;
          if (!_isPlausibleSceneGenRejection(event.reason)) {
              console.log('[SORRY-TEMPT] Rejection during scene gen but not plausibly scene-gen-sourced — ignoring.',
                  'reason=', event.reason && (event.reason.message || event.reason));
              return;
          }
          _handleSceneGenFailure(event.reason);
          // Don't preventDefault — let the console error surface for debugging.
      });
  }

  // ───────────────────────────────────────────────────────────────────────
  // INLINE TEXT PROMPT — replacement for window.prompt(). Renders a small
  // centered overlay with a single text input + OK/Cancel buttons. Returns
  // a Promise<string|null> (null on cancel/Escape). Why: window.prompt() is
  // unreliable cross-context — Chrome lets users tick "Don't allow this site
  // to ask again" after one dialog, after which all future prompts silently
  // no-op until they re-enable in site settings. Inline UI sidesteps that
  // entirely. Single-instance: opening a second prompt resolves the first
  // with null and replaces the UI.
  // ───────────────────────────────────────────────────────────────────────
  let _inlinePromptResolver = null;
  function inlinePromptText(opts) {
    opts = opts || {};
    // If a previous prompt is still up, cancel it.
    if (_inlinePromptResolver) {
      try { _inlinePromptResolver(null); } catch (_) {}
      _inlinePromptResolver = null;
      var oldEl = document.getElementById('inlinePromptOverlay');
      if (oldEl && oldEl.parentNode) oldEl.parentNode.removeChild(oldEl);
    }

    return new Promise(function(resolve) {
      _inlinePromptResolver = resolve;

      var overlay = document.createElement('div');
      overlay.id = 'inlinePromptOverlay';
      overlay.style.cssText = 'position:fixed;inset:0;z-index:99998;background:rgba(0,0,0,0.55);display:flex;align-items:center;justify-content:center;backdrop-filter:blur(3px);';

      var panel = document.createElement('div');
      panel.style.cssText = 'background:linear-gradient(165deg,rgba(36,28,18,0.97),rgba(20,16,10,0.98));border:1px solid rgba(212,175,55,0.5);border-radius:8px;padding:18px 22px;min-width:280px;max-width:90vw;box-shadow:0 10px 40px rgba(0,0,0,0.6),inset 0 0 0 1px rgba(212,175,55,0.12);font-family:Lora,serif;color:#e8d9b0;';

      var titleEl = document.createElement('div');
      titleEl.style.cssText = 'font-size:14px;margin-bottom:10px;color:rgba(232,217,176,0.92);';
      titleEl.textContent = opts.title || 'Enter a value:';

      var input = document.createElement('input');
      input.type = 'text';
      input.value = opts.defaultValue || '';
      if (opts.maxLength) input.maxLength = opts.maxLength;
      if (opts.placeholder) input.placeholder = opts.placeholder;
      input.style.cssText = 'width:100%;box-sizing:border-box;background:rgba(0,0,0,0.4);border:1px solid rgba(212,175,55,0.35);border-radius:4px;color:#f3e4b8;font-family:Lora,serif;font-size:14px;padding:8px 10px;outline:none;';
      input.addEventListener('focus', function(){ input.style.borderColor = 'rgba(232,200,120,0.75)'; });
      input.addEventListener('blur',  function(){ input.style.borderColor = 'rgba(212,175,55,0.35)'; });

      var btnRow = document.createElement('div');
      btnRow.style.cssText = 'display:flex;justify-content:flex-end;gap:8px;margin-top:14px;';

      var cancelBtn = document.createElement('button');
      cancelBtn.type = 'button';
      cancelBtn.textContent = opts.cancelLabel || 'Cancel';
      cancelBtn.style.cssText = 'background:none;border:1px solid rgba(180,180,180,0.3);color:rgba(220,220,220,0.7);padding:6px 14px;border-radius:4px;cursor:pointer;font-family:Lora,serif;font-size:13px;';

      var okBtn = document.createElement('button');
      okBtn.type = 'button';
      okBtn.textContent = opts.confirmLabel || 'OK';
      okBtn.style.cssText = 'background:linear-gradient(180deg,rgba(212,175,100,0.85),rgba(180,145,80,0.85));border:1px solid rgba(232,200,120,0.9);color:#1a1208;padding:6px 16px;border-radius:4px;cursor:pointer;font-family:Lora,serif;font-size:13px;font-weight:500;';

      function close(value) {
        var resolver = _inlinePromptResolver;
        _inlinePromptResolver = null;
        if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
        document.removeEventListener('keydown', onKey);
        if (resolver) resolver(value);
      }
      function onKey(e) {
        if (e.key === 'Escape') { e.preventDefault(); close(null); }
        else if (e.key === 'Enter') { e.preventDefault(); commit(); }
      }
      function commit() {
        var v = input.value;
        close(v == null ? null : String(v));
      }

      cancelBtn.addEventListener('click', function(){ close(null); });
      okBtn.addEventListener('click', commit);
      // Click outside the panel cancels.
      overlay.addEventListener('click', function(e){ if (e.target === overlay) close(null); });
      document.addEventListener('keydown', onKey);

      btnRow.appendChild(cancelBtn);
      btnRow.appendChild(okBtn);
      panel.appendChild(titleEl);
      panel.appendChild(input);
      panel.appendChild(btnRow);
      overlay.appendChild(panel);
      document.body.appendChild(overlay);

      // Focus + select existing text for fast edit.
      setTimeout(function() { input.focus(); input.select(); }, 0);
    });
  }
  window.inlinePromptText = inlinePromptText;

  // ───────────────────────────────────────────────────────────────────────
  // INLINE CONFIRM — replacement for window.confirm(). Same rationale as
  // inlinePromptText above: Chrome's native dialog shows "Prevent this page
  // from creating additional dialogs," and once a user ticks it, every
  // subsequent confirm() silently returns false. The delete-book handler
  // bailed out cleanly because confirm() lied about the user's intent.
  // Returns Promise<boolean> — true = confirm clicked, false = cancel/Escape/
  // backdrop click.
  // ───────────────────────────────────────────────────────────────────────
  let _inlineConfirmResolver = null;
  function inlineConfirm(opts) {
    opts = opts || {};
    // Cancel any prior open confirm — resolve it as false.
    if (_inlineConfirmResolver) {
      try { _inlineConfirmResolver(false); } catch (_) {}
      _inlineConfirmResolver = null;
      var oldEl = document.getElementById('inlineConfirmOverlay');
      if (oldEl && oldEl.parentNode) oldEl.parentNode.removeChild(oldEl);
    }

    return new Promise(function(resolve) {
      _inlineConfirmResolver = resolve;

      var overlay = document.createElement('div');
      overlay.id = 'inlineConfirmOverlay';
      overlay.style.cssText = 'position:fixed;inset:0;z-index:99998;background:rgba(0,0,0,0.55);display:flex;align-items:center;justify-content:center;backdrop-filter:blur(3px);';

      var panel = document.createElement('div');
      panel.style.cssText = 'background:linear-gradient(165deg,rgba(36,28,18,0.97),rgba(20,16,10,0.98));border:1px solid rgba(212,175,55,0.5);border-radius:8px;padding:20px 24px;min-width:320px;max-width:90vw;box-shadow:0 10px 40px rgba(0,0,0,0.6),inset 0 0 0 1px rgba(212,175,55,0.12);font-family:Lora,serif;color:#e8d9b0;';

      // Optional title — bolder line above the body.
      if (opts.title) {
        var titleEl = document.createElement('div');
        titleEl.style.cssText = 'font-size:15px;font-weight:600;margin-bottom:10px;color:#f3e4b8;';
        titleEl.textContent = opts.title;
        panel.appendChild(titleEl);
      }

      var bodyEl = document.createElement('div');
      bodyEl.style.cssText = 'font-size:14px;line-height:1.5;color:rgba(232,217,176,0.92);';
      bodyEl.textContent = opts.body || 'Are you sure?';
      panel.appendChild(bodyEl);

      var btnRow = document.createElement('div');
      btnRow.style.cssText = 'display:flex;justify-content:flex-end;gap:8px;margin-top:16px;';

      var cancelBtn = document.createElement('button');
      cancelBtn.type = 'button';
      cancelBtn.textContent = opts.cancelLabel || 'Cancel';
      cancelBtn.style.cssText = 'background:none;border:1px solid rgba(180,180,180,0.3);color:rgba(220,220,220,0.7);padding:7px 16px;border-radius:4px;cursor:pointer;font-family:Lora,serif;font-size:13px;';

      var okBtn = document.createElement('button');
      okBtn.type = 'button';
      okBtn.textContent = opts.confirmLabel || 'Confirm';
      // Danger variant = red-accented confirm for destructive actions.
      var _danger = !!opts.danger;
      okBtn.style.cssText = _danger
        ? 'background:linear-gradient(180deg,rgba(201,90,78,0.92),rgba(160,60,50,0.92));border:1px solid rgba(220,120,100,0.9);color:#fff;padding:7px 18px;border-radius:4px;cursor:pointer;font-family:Lora,serif;font-size:13px;font-weight:600;'
        : 'background:linear-gradient(180deg,rgba(212,175,100,0.85),rgba(180,145,80,0.85));border:1px solid rgba(232,200,120,0.9);color:#1a1208;padding:7px 18px;border-radius:4px;cursor:pointer;font-family:Lora,serif;font-size:13px;font-weight:500;';

      function close(value) {
        var resolver = _inlineConfirmResolver;
        _inlineConfirmResolver = null;
        if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
        document.removeEventListener('keydown', onKey);
        if (resolver) resolver(!!value);
      }
      function onKey(e) {
        if (e.key === 'Escape') { e.preventDefault(); close(false); }
        else if (e.key === 'Enter') { e.preventDefault(); close(true); }
      }
      cancelBtn.addEventListener('click', function(){ close(false); });
      okBtn.addEventListener('click', function(){ close(true); });
      overlay.addEventListener('click', function(e){ if (e.target === overlay) close(false); });
      document.addEventListener('keydown', onKey);

      btnRow.appendChild(cancelBtn);
      btnRow.appendChild(okBtn);
      panel.appendChild(btnRow);
      overlay.appendChild(panel);
      document.body.appendChild(overlay);

      // Focus the Cancel button by default — safer for destructive actions
      // (user must tab/click to confirm, not just hit Enter).
      setTimeout(function() { (_danger ? cancelBtn : okBtn).focus(); }, 0);
    });
  }
  window.inlineConfirm = inlineConfirm;

  // Clear any stuck toasts (call on state changes)
  function clearToasts() {
      const t = document.getElementById('toast');
      if (t) {
          t.classList.add('hidden');
          t.style.animation = 'none';
      }
      if (_toastTimer) {
          clearTimeout(_toastTimer);
          _toastTimer = null;
      }
  }

  function sanitizeUserIntent(action, dialogue) {
      const input = (action + " " + dialogue).toLowerCase();
      const nonConPatterns = [
          /\brape\b/i, /\b(non[-\s]?consensual|without consent)\b/i,
          /\bagainst (her|his|their) will\b/i, /\bforce\b/i
      ];
      
      if(nonConPatterns.some(rx => rx.test(input))) {
          const now = Date.now();
          if (now - (state.lastNonConPushAt || 0) > 15 * 60 * 1000) state.nonConPushCount = 0;
          state.nonConPushCount = (state.nonConPushCount || 0) + 1;
          state.lastNonConPushAt = now;

          const directive = "ABSOLUTE SAFETY RULE: User input implied non-consensual dynamics. 1. DO NOT depict the act. NO sexual violence. 2. REFRAME: Partner deflects safely OR shifts to explicit, enthusiastic consent negotiation.";
          return { safeAction: undefined, safeDialogue: undefined, flags: ["redirect_nonconsent"], directive };
      }
      return { safeAction: undefined, safeDialogue: undefined, flags: [], directive: "" };
  }

