  //            state.intimacyPhase === true at storyturn ST3/ST4/ST5
  // ═══════════════════════════════════════════════════════════════════════════

  function _isInEmbodiedContext() {
    var s = window.state || {};
    if (s.intimacyDialogue && s.intimacyDialogue.active) return true;
    // OAS body-class is the most authoritative live signal that an
    // intimate scene is in progress — set by _initIntimacyDialogue
    // before state.intimacyDialogue is fully populated, and by the
    // dev-launch path BEFORE intimacyDialogue.active is true. Treat
    // it as a hard "yes, embodied" so Petition / Tempt suggestion
    // pickers grab the erotic lists even on the very first click
    // after OAS mounts.
    try {
      if (document.body && document.body.classList.contains('oas-active')) return true;
    } catch (_) {}
    if (s.intimacyPhase) {
      var st = String(s.storyturn || 'ST1');
      if (st === 'ST3' || st === 'ST4' || st === 'ST5') return true;
    }
    return false;
  }
  window._isInEmbodiedContext = _isInEmbodiedContext;

  // ─── Slice 2: speculative Grok intimate fate-card cache ──────────────────
  // Fires when scene finalizes AND next-turn cards will be intimate. Kicks
  // off the batch preview generator in background; fatecards.js reads cache
  // at deal time. Cached by turnCount so re-deals within the same turn reuse.
  // Falls back silently to template generator if Grok fails or hasn't returned
  // by the time cards are dealt.
  async function _speculativeGrokIntimateFateCards() {
    var s = window.state || {};
    if (!_isInEmbodiedContext()) return; // not intimate → no speculative call
    var tc = (s.turnCount || 0) + 1; // cards are dealt for the NEXT turn after finalize
    // Idempotency — don't refetch if we already have a cache for this turn or a
    // request in flight.
    if (s._grokIntimateFateCards && s._grokIntimateFateCards.turnCount === tc) return;
    if (s._grokIntimateFateCardsInFlight === tc) return;
    s._grokIntimateFateCardsInFlight = tc;
    var orch = window.StoryboundOrchestration;
    if (!orch || typeof orch.generateIntimateFatePreviewsBatch !== 'function') {
      s._grokIntimateFateCardsInFlight = null;
      return;
    }
    try {
      console.log('[FATE:INTIMATE:SPEC] firing speculative batch for turn ' + tc);
      var result = await orch.generateIntimateFatePreviewsBatch();
      if (result && Object.keys(result).length) {
        // A1-F4 (Fable CG audit 2026-07-13): stamp the CANONICAL fate-context hash (same one the literary
        // speculative path validates, getFateContextHash → fateCard|action|dialogue|tone|world|intensity|
        // petition) so the consumer can discard the cache if card / character-input / world-flavor /
        // obligation changed between finalize and deal. turnCount alone (below) only catches scene
        // progression. A mismatch safely falls back to the same on-demand generateIntimateFatePreviewsBatch().
        s._grokIntimateFateCards = { turnCount: tc, fateContextHash: (typeof getFateContextHash === 'function' ? getFateContextHash() : null), cards: result, generatedAt: Date.now() };
        console.log('[FATE:INTIMATE:SPEC] cached ' + Object.keys(result).length + ' card previews for turn ' + tc);
      } else {
        console.log('[FATE:INTIMATE:SPEC] empty result — template fallback will apply');
      }
    } catch (e) {
      console.warn('[FATE:INTIMATE:SPEC] threw:', e && e.message);
    } finally {
      s._grokIntimateFateCardsInFlight = null;
    }
  }
  window._speculativeGrokIntimateFateCards = _speculativeGrokIntimateFateCards;

  // Petition default suggestions — these were inlined in the HTML literal of
