      // ── ST3 TIMING ──
      var firstST3 = null;
      for (var i = 0; i < scenes.length; i++) {
        if (_stPhaseToIndex(scenes[i].st_final) >= 3) { firstST3 = scenes[i].scene; break; }
      }

