    _storyTags.intensity.level = state.intensity === 'Steamy' ? 'high' : 'medium';
    if (state.romanticTensionLevel >= 2) _storyTags.intensity.volatility = 'spiking';
    else if (state.commitmentDrift > 3) _storyTags.intensity.volatility = 'oscillating';

    // Title resolution — check both literary (#storyTitle) and GN (#gnStoryTitle)
    // reader DOM, then fall through to state fields. Previously the snapshot
    // ONLY read #storyTitle, so GN stories were saving with empty titles
