  window.saveStoryManual = saveStorySnapshot;

  // ═══════════════════════════════════════════════════════════════════
  // SUPABASE STORY SNAPSHOT PERSISTENCE (Phase 1)
  // Parallel write alongside localStorage. Never blocks UI.
  // ═══════════════════════════════════════════════════════════════════

  // Missing denormalized columns — sticky per session so we stop retrying the full
  // payload after the first schema-cache miss. Populated lazily from Supabase error messages.
  // Exposed on window for smoke-test observability.
  window._supabaseSnapshotMissingCols = window._supabaseSnapshotMissingCols || null;

  async function saveStorySnapshotToSupabase(profileId, storyId, snapshot) {
    var basePayload = {
      profile_id: profileId,
      story_id: storyId,
      snapshot: snapshot,
      updated_at: snapshot.updated_at || new Date().toISOString()
    };
    var optionalCols = {
      title: snapshot.title || 'Untitled',
      turn_count: (snapshot.stateSnapshot || {}).turnCount || 0
    };

    function buildPayload() {
      var p = Object.assign({}, basePayload);
      Object.keys(optionalCols).forEach(function(k) {
        if (!window._supabaseSnapshotMissingCols || window._supabaseSnapshotMissingCols.indexOf(k) === -1) {
          p[k] = optionalCols[k];
        }
      });
      return p;
    }

    async function attempt() {
      return await sb
        .from('story_snapshots')
        .upsert(buildPayload(), { onConflict: 'profile_id,story_id' });
    }

    try {
      var result = await attempt();
      if (result.error) {
        var msg = result.error.message || '';
        // Schema-cache miss: "Could not find the 'X' column of 'story_snapshots' in the schema cache"
        var colMatch = /Could not find the '([^']+)' column/i.exec(msg);
        if (colMatch && optionalCols.hasOwnProperty(colMatch[1])) {
          window._supabaseSnapshotMissingCols = window._supabaseSnapshotMissingCols || [];
          if (window._supabaseSnapshotMissingCols.indexOf(colMatch[1]) === -1) {
            window._supabaseSnapshotMissingCols.push(colMatch[1]);
          }
          console.warn('[Supabase] story_snapshots.' + colMatch[1] + ' column missing — retrying without it. Add the column via migration to restore denormalized lookups.');
          result = await attempt();
        }
      }
      if (result.error) {
        console.error('[Supabase] Snapshot save failed:', result.error.message);
      } else {
        console.log('[Supabase] Snapshot saved for story:', storyId);
      }
    } catch (err) {
      console.error('[Supabase] Snapshot save error:', err);
    }
  }

  async function loadSupabaseSnapshot(profileId, storyId) {
    try {
      const { data, error } = await sb
        .from('story_snapshots')
        .select('snapshot, updated_at')
        .eq('profile_id', profileId)
        .eq('story_id', storyId)
        .maybeSingle();
      if (error) {
        console.error('[Supabase] Snapshot load failed:', error.message);
        return null;
      }
      return data; // { snapshot, updated_at } or null
    } catch (err) {
      console.error('[Supabase] Snapshot load error:', err);
      return null;
    }
  }

  // CORRECTIVE: Load story data from localStorage or IndexedDB
  // ── LEGACY SPECIES NORMALIZATION (2026-05-27) ──
  // The Thornwild rename (Werefolk→Wildfolk, Werebeast→Wilder, Half-Beast→
  // Half-Wild) changed the species ENUM. Old saved stories persist the legacy
  // values; map them forward on load so the renamed `=== 'Wilder'` comparisons
  // still match. window-exposed so any other ingestion point can reuse it.
  function _normalizeLegacySpecies(v) {
    if (typeof v !== 'string') return v;
    if (v === 'Werebeast' || v === 'Werebeasts') return 'Wilder';
    if (v === 'Half-Beast') return 'Half-Wild';
    if (v === 'Werefolk') return 'Wildfolk';
    // Kwisheen rename (2026-05-27): Octofolk→Kwisheen, Half-Octofolk→Half-Kwisheen, Octo-Favored→Kwisheen-Favored.
    if (v === 'Octofolk') return 'Kwisheen';
    if (v === 'Half-Octofolk') return 'Half-Kwisheen';
    if (v === 'Octo-Favored') return 'Kwisheen-Favored';
    return v;
  }
  window._normalizeLegacySpecies = _normalizeLegacySpecies;
  function _migrateLegacySpeciesState() {
    try {
      var s = window.state; if (!s) return;
      if (s._playerSpecies) s._playerSpecies = _normalizeLegacySpecies(s._playerSpecies);
      if (s._liSpecies)     s._liSpecies     = _normalizeLegacySpecies(s._liSpecies);
      if (s.npcSpecies && typeof s.npcSpecies === 'object') {
        Object.keys(s.npcSpecies).forEach(function(k){
          var e = s.npcSpecies[k];
          if (typeof e === 'string') s.npcSpecies[k] = _normalizeLegacySpecies(e);
          else if (e && typeof e === 'object' && e.species) e.species = _normalizeLegacySpecies(e.species);
        });
      }
    } catch (_) {}
  }

  async function loadStoryData(targetStoryId) {
      // Per-story load path — when a specific storyId is requested, the
      // single-slot localStorage MUST match or we route through IDB.
      // Returning the wrong story silently was the previous failure mode
      // (Vault "Continue" loaded sb_saved_story regardless of which row
      // the user clicked).
      if (targetStoryId) {
          // Try localStorage single slot, only return if it matches.
          var raw = localStorage.getItem('sb_saved_story');
          if (raw) {
              try {
                  var data = JSON.parse(raw);
                  if (data && (data.storyId === targetStoryId || data.story_id === targetStoryId)) {
                      return data;
                  }
              } catch (e) {
                  console.warn('Failed to parse localStorage story', e);
              }
          }
          // Try IDB per-story record.
          var idbData = await loadFromIndexedDB(targetStoryId);
          if (idbData) return idbData;
          // No local copy for this storyId — caller can attempt Supabase.
          return null;
      }
      // No target — current behavior (load whatever's in the single
      // active slot, used at boot to restore the last-active story).
      var raw0 = localStorage.getItem('sb_saved_story');
      if (raw0) {
          try {
              return JSON.parse(raw0);
          } catch (e) {
              console.warn('Failed to parse localStorage story', e);
          }
      }
      if (localStorage.getItem('sb_story_in_idb') === '1') {
          var idbData0 = await loadFromIndexedDB();
          if (idbData0) return idbData0;
      }
      return null;
  }

  window.continueStory = async function(targetStoryId){
    try { if (typeof sbLogBeta === 'function') sbLogBeta('library_resume_clicked', { storyId: targetStoryId || null }); } catch (_) {}
    // Vault Continue passes the specific storyId; boot-time restore
    // calls without an arg to load the last-active story.
    let data = await loadStoryData(targetStoryId);
    try { if (typeof sbLogBeta === 'function') sbLogBeta(data ? 'story_resumed' : 'page_refreshed_resume_attempted', { storyId: targetStoryId || (data && (data.storyId || data.story_id)) || null, restored: !!data, fateMode: (data && data.stateSnapshot && data.stateSnapshot.fateMode) || null }); } catch (_) {}
    // Supabase fallback when a specific story was requested but no
    // local copy exists (cross-device sync / device migration).
    if (!data && targetStoryId && sb && _supabaseProfileId) {
      try {
        const remoteOnly = await loadSupabaseSnapshot(_supabaseProfileId, targetStoryId);
        if (remoteOnly && remoteOnly.snapshot) {
          console.log('[CONTINUE] Loaded story ' + targetStoryId + ' from Supabase (no local copy)');
          data = remoteOnly.snapshot;
        }
      } catch (err) {
        console.warn('[CONTINUE] Supabase fallback for ' + targetStoryId + ' failed:', err && err.message);
      }
    }
    if (!data) {
        showToast('No saved story found.');
        return;
    }

    // Supabase snapshot merge: if remote is newer, replace local data.
    // Skipped when we already loaded directly from Supabase above.
    if (sb && _supabaseProfileId && data.storyId) {
      try {
        const remote = await loadSupabaseSnapshot(_supabaseProfileId, data.storyId);
        if (remote?.snapshot && remote.updated_at) {
          const localTime = data.updated_at ? new Date(data.updated_at).getTime() : 0;
          const remoteTime = new Date(remote.updated_at).getTime();
          if (remoteTime > localTime) {
            console.log('[Supabase] Remote snapshot is newer, using it');
            data = remote.snapshot;
          }
        }
      } catch (err) {
        console.error('[Supabase] Snapshot merge check failed:', err);
      }
    }

    state.storyId = data.storyId || makeStoryId();
    localStorage.setItem('sb_current_story_id', state.storyId);
    syncCurrentStoryPass();

    // Account-level fields (Fortunes / subscription / tier) belong to the LIVE
    // profile, NOT the per-story snapshot. The snapshot persisted them only for
    // legacy reasons; Object.assigning them back clobbers the live balance with
    // the stale save-time value (widget jumps e.g. 316→2 until the next server
    // round-trip re-syncs it). Capture the live values now, restore below.
    var _liveFortunes = state.fortunes;
    var _liveSubscribed = state.subscribed;
    var _liveRealSubscribed = state._realSubscribed;
    var _liveTier = state.tier;
    if(data.stateSnapshot) Object.assign(state, data.stateSnapshot);
    // Onboarding emergence gates (Scene-2 Petition / Scene-3 Tempt examine) are
    // LIVE-PLAY one-shots; never re-arm them on a reopened story. Any 'awaiting-
    // arm' flag that lingered in the snapshot would re-fire the gate on restore —
    // Roman 2026-06-09: a reopened story landed on Scene 2 trapped behind the Tempt
    // zoom with no Submit. Clear the pending arm flags + any stranded gate class so
    // resume lands cleanly on the live scene. (The *EmergenceFired one-shots stay as
    // saved, so completed onboarding is never replayed.)
    state._petitionFrameLandedAwaitingArm = false;
    state._temptFrameLandedAwaitingArm = false;
    state._deckExamineArmed = false;
    try { document.body.classList.remove('examine-card-gate-active'); } catch (_) {}
    // Story Pull / Story Polarity provenance for loaded saves: if the snapshot
    // carries pressure/dynamic but no source tag, it predates the inference
    // system — mark it 'legacy' so the resolvers never re-roll an in-progress
    // story's architecture. (Newer saves carry 'inferred'/'user' already.)
    if (state.picks?.pressure && !state.storyPullSource) state.storyPullSource = 'legacy';
    if (state.picks?.dynamic && !state.storyPolaritySource) state.storyPolaritySource = 'legacy';
    // Backfill romantic-target bridge for old snapshots missing storybeau
    if (state.normalizedPartnerKernel && !state.storybeau) _syncRomanticTargetState();
    // Normalize legacy 'Were-' species values from old saves (Werebeast→Wilder,
    // Half-Beast→Half-Wild, Werefolk→Wildfolk) so the renamed === comparisons match.
    _migrateLegacySpeciesState();
    // Canonicalize legacy tone values from saved state
    if (state.picks?.tone) state.picks.tone = canonicalizeTone(state.picks.tone);
    deriveToneBias();
    state.sysPrompt = data.sysPrompt || state.sysPrompt;
    state.subscribed = !!data.subscribed;
    // Restore the live account-level fields the snapshot assign clobbered above.
    // Story state stays loaded; the Fortunes balance + entitlement stay current
    // instead of reverting to save-time. Runs BEFORE applyAccessLocks() below so
    // entitlement locks reflect the live subscription, not the stale snapshot.
    if (typeof _liveFortunes === 'number') state.fortunes = _liveFortunes;
    if (typeof _liveSubscribed !== 'undefined') state.subscribed = _liveSubscribed;
    if (typeof _liveRealSubscribed !== 'undefined') state._realSubscribed = _liveRealSubscribed;
    if (_liveTier != null) state.tier = _liveTier;
    if (typeof updateFortuneDisplay === 'function') { try { updateFortuneDisplay(); } catch (_) {} }
    // (authorChairActive removed — Petition Fate replaces quill)

    updateBatedBreathState();
    applyAccessLocks();

    { const _stTitleEl = document.getElementById('storyTitle'); if (_stTitleEl) _stTitleEl.textContent = data.title || ''; }
    applyStoryTitleTooltips();
    // BOOK FLOW SPEC: Synopsis is metadata only, never rendered
    // Inside cover = blank paper, Setting plate = visual only
    state._synopsisMetadata = data.synopsis || '';
    state.renderMode = data.render_mode || 'literary';
    state.graphicStyle = _enforceIllustratorGuard(_resolveArtistId(data.graphic_style || 'ender_bond'));

    // Load story into pagination system
    StoryPagination.clear();
    if (data.storyPages && Array.isArray(data.storyPages) && data.storyPages.length > 0) {
        // Load saved pages (defensive whisper strip — handles legacy
        // snapshots saved before _stripFateWhispers was wired at save time).
        var _stripFn = (typeof window._stripFateWhispers === 'function') ? window._stripFateWhispers : function(x){ return x; };
        var _cleanPages = Array.isArray(data.storyPages) ? data.storyPages.map(_stripFn) : data.storyPages;
        StoryPagination.setPages(_cleanPages);
    } else if (data.storyHTML) {
        // Fallback: load as single page (defensive whisper strip)
        var _cleanHtml = (typeof window._stripFateWhispers === 'function') ? window._stripFateWhispers(data.storyHTML) : data.storyHTML;
        StoryPagination.addPage(_cleanHtml, true);
    }
    state.lastSavedWordCount = currentStoryWordCount();

    // Setting shot removed from auto-load - requires explicit user action

    window.showScreen('game');
    if (state.fateOptions && state.fateOptions.length) state.fateOptions = filterFateCardsForBatedBreath(state.fateOptions);
    // FIX: Use dealFateCards (not initCards) to get clickable, flippable cards with handlers
    if(window.dealFateCards) window.dealFateCards();
    else if(window.initCards) window.initCards();
    // REBIND: Ensure FX handlers are attached after navigation
    if (window.initFateCards) window.initFateCards();
    resetTurnSnapshotFlag();

    // EARNED COVER SYSTEM: Update cover button for continued story
    _lastNotifiedCoverStage = getCurrentCoverStage();
    updateReaderCoverButton();

    // RESUME INTO THE STORY (not the cover). showScreen('game') alone leaves
    // the reader on whatever _readerPage was — which is 0 (the cover) after a
    // full-page reload (e.g. the Stripe checkout redirect), so the user landed
    // on the cover / "click anywhere to continue" instead of their scene. Open
    // the latest scene page. Skipped for completed books (the End Page below
    // owns that) and for stories with no scene pages yet (stay on the cover).
    if (!(state.book_complete && state.storyEnded)) {
        var _resumePageCount = (typeof StoryPagination.getPageCount === 'function') ? StoryPagination.getPageCount() : 0;
        if (_resumePageCount > 0) {
            if (typeof StoryPagination.goToPage === 'function') StoryPagination.goToPage(_resumePageCount - 1, false);
            if (typeof showReaderPage === 'function') showReaderPage(2);
        }
    }

    // RESUME LORE DECORATION (Roman 2026-07-13, Root 3): the ledger (state._loreLedger) rides
    // along in the snapshot (cleanState = {...state}) and is restored above, but the saved scene
    // HTML was mounted un-decorated — formatStory's gen-time decorator never runs on the resume
    // path. Re-run the decorator on the LIVE mounted scene so bold world-anchors + hover tooltips
    // work after a reload (e.g. returning from a Fortunes purchase mid-story). Live-DOM variant
    // mutates in place (no innerHTML re-parse) so micro-choice/fate-whisper handlers survive;
    // idempotent (skips text already inside .lore-term); no-op when the ledger is empty.
    try {
        setTimeout(function () {
            try {
                var _lel = document.getElementById('storyText') || document.getElementById('storyContent');
                if (_lel && typeof _loreDecorateElement === 'function') _loreDecorateElement(_lel);
            } catch (_) {}
        }, 120);
    } catch (_) {}

    // BOOK COMPLETE: If restored story was completed, re-show End Page
    if (state.book_complete && state.storyEnded) {
        showStoryEndPage();
    }

    // ISSUE CLIFFHANGER (R4): if this resumed story sits on an issue-finale
    // cliffhanger awaiting purchase, re-arm the pause + "Continue to Issue N" modal.
    // _isAtIssueCliffhanger() re-derives from the restored turnCount, so the
    // continuation is never lost across refresh/reopen.
    try { if (typeof _maybeArmIssueCliffhanger === 'function') setTimeout(_maybeArmIssueCliffhanger, 500); } catch (_) {}
  };

  function updateContinueButtons(){
    const show = hasSavedStory();
    const btn1 = document.getElementById('continueStoryBtn');
    const btn2 = document.getElementById('continueFromTierBtn');
    if(btn1) btn1.classList.toggle('hidden', !show);
    if(btn2) btn2.classList.toggle('hidden', !show);
  }

  window.restart = function(){
    // TEASE TIER: Prevent restart unless user has credits or entitlement
    if (isTeaseTier() && !canStartCustomTeaseStory()) {
        console.warn('[CREDITS] Restart blocked — no custom story credits');
        window.showPaywall('unlock');
        return;
    }
    if(state.mode === 'couple') window.coupleCleanup();
    if (window.stopSparkleCycle) window.stopSparkleCycle(); // Clear any active fate card sparkles
    state.mode = 'solo';
    // Preserve storyId on restart — only "New Story" flows generate new storyIds
    // clearCurrentStoryId() and storyId null intentionally omitted
    state.access = state.subscribed ? 'sub' : 'free';
    syncTierFromAccess();
    localStorage.removeItem('sb_saved_story');
    // Reset state
    state.turnCount = 0;
    state._loggedStoryStart = false;
    state._loggedScene3 = false;
    state._loggedScene6 = false;
    state._loggedPetitionOpen = false;
    state._loggedPetitionSubmit = false;
    // Taste is STARTER-BOOK-ONLY (Roman 2026-05-29). restart() runs for any
    // story restart — letting it stamp 'taste' here turned non-starter restarts
    // into per-scene-1F-pricing on top of the paid issue. Leave empty; corridor
    // / starter-setup is responsible for the actual tier.
    state.storyLength = '';
    state.storyEnded = false;
    state.archetype = { primary: 'BEAUTIFUL_RUIN', modifier: null };

    // FIX: Full 4-axis + world state reset (prevents Ash Quarter / Warden-Cadre leak)
    state.picks = { world: 'Modern', tone: 'Earnest', genre: 'Billionaire', dynamic: 'Enemies', era: null, pov: 'First' };
    state.intensity = 'Steamy';
    state.storypassEligible = undefined; // Reset - will be computed at story creation
    state.visual = { autoLock: true, locked: false, lastImageUrl: "", bible: { style: "", setting: "", characters: {} }, sceneBudgets: {}, visualizedScenes: {}, characterVisualProfiles: {}, _visionCache: null };
    // SPECULATIVE PRELOAD: Reset on restart
    state.speculativeNextScene = null;
    state.isPreloadingNextScene = false;
    state.coverArchetype = null;
    state.lenses = [];
    state.withheldCoreVariant = null;
    state.normalizedPlayerKernel = null;
    state.normalizedPartnerKernel = null;
    state.rawPlayerName = null;
    state.rawPartnerName = null;
    state.playerName = null;
    state.loveInterestName = null;
    state.storybeau = null;
    // Reset story shape snapshot (forces "Begin Story" on new session)
    state._lastGeneratedShapeSnapshot = null;

    // FIX: Cover regeneration reset — allow new cover without hard refresh
    if (_coverAbortController) { _coverAbortController.abort(); _coverAbortController = null; }
    resetBookState();
    // Reset DSP state for fresh intro/placeholder cycle
    if (typeof resetDSPState === 'function') resetDSPState();
    const coverImg = document.getElementById('bookCoverImg');
    if (coverImg) coverImg.src = '';
    const coverLoading = document.getElementById('coverLoadingState');
    if (coverLoading) coverLoading.classList.add('hidden');
    const bookObj = document.getElementById('bookObject');
    if (bookObj) bookObj.classList.add('hidden');
    if (_coverPhraseInterval) { clearInterval(_coverPhraseInterval); _coverPhraseInterval = null; }
    if (_coverProgressInterval) { clearInterval(_coverProgressInterval); _coverProgressInterval = null; }

    // Reset card UI to match default state
    const cardDefaults = { world: 'Modern', tone: 'Earnest', genre: 'Billionaire', dynamic: 'Enemies', intensity: 'Steamy', length: 'taste', pov: 'First' };
    Object.entries(cardDefaults).forEach(([grp, val]) => {
        document.querySelectorAll(`.sb-card[data-grp="${grp}"]`).forEach(c => {
            c.classList.remove('selected', 'flipped');
        });
        const def = document.querySelector(`.sb-card[data-grp="${grp}"][data-val="${val}"]`);
        if (def) def.classList.add('selected', 'flipped');
    });

    // Reset name inputs
    const pInput = $('playerNameInput');
    if (pInput) pInput.value = '';
    const lInput = $('partnerNameInput');
    if (lInput) lInput.value = '';

    // Clear pagination system
    StoryPagination.clear();
    // Re-render archetype cards to show default selection
    if (typeof renderArchetypeCards === 'function') renderArchetypeCards();
    if (typeof updateArchetypeSelectionSummary === 'function') updateArchetypeSelectionSummary();

    // PASS 9E: Reset fate card state
    const fateCard = $('fateDestinyCard');
    if (fateCard) {
        fateCard.dataset.fateUsed = 'false';
        fateCard.style.opacity = '1';
        fateCard.style.pointerEvents = 'auto';
        fateCard.classList.remove('flipped');
    }

    updateContinueButtons();
    window.showScreen('setup');
    // FIX: Explicit lock re-application ensures intensity cards reflect current access tier
    applyAccessLocks();
    applyIntensityLocks();
    updateBatedBreathState();
  };

