      // Famous Fate flow where the player names their own book / movie / show.
      // launchKind routes it to _openFamousFateEntry (name-fandom form) instead of
      // the literary _launchStarterStory path.
      id: 'starter_famous_fate',
      title: 'Your Favorite Book, Movie, or Show',
      subtitle: 'A Famous Fate',
      author: 'S. Tory Bound',
      // Spine reads as one line (overrides the default title + author spine text).
      spineText: 'Famous Fate — Enter Your Favorite Book, Movie, or Show',
