              try { logEvent('fortune_spent', { amount, context, dev: true }); } catch (_) {}
              try { if (typeof sbLogBeta === 'function') sbLogBeta('fortune_debit_succeeded', { amount: amount, context: context, beforeBalance: _betaBefore, afterBalance: state.fortunes, sceneIndex: _betaScene, dev: true }); } catch (_) {}
