  // ═══════════════════════════════════════════════════════════════════
  // DRIP FORTUNE SYSTEM — Expiring temporary credits (4-hour lifespan)
  // Grants 1 free fortune when all permanent pools are empty.
  // ═══════════════════════════════════════════════════════════════════
  const DRIP_FORTUNE_INTERVAL_MS = 4 * 60 * 60 * 1000; // 4 hours
  const DRIP_FORTUNE_MAX = 1; // max drip credits that can accumulate
  let _dripFortuneTimerId = null;

  function _shouldGrantDripFortune() {
      const f = getAvailableFortunes();
      // Only grant when all permanent pools are empty
      if (f.global > 0 || f.storypass > 0) return false;
      // Cap accumulation
      if ((state.dripFortunes || 0) >= DRIP_FORTUNE_MAX) return false;
      return true;
  }

  function _grantDripFortune() {
      if (!_shouldGrantDripFortune()) return;
      state.dripFortunes = (state.dripFortunes || 0) + 1;
      state._dripFortuneGrantedAt = Date.now();
      console.log('[DRIP] Fortune granted. Balance:', state.dripFortunes);
      if (window.updateFortuneDisplay) window.updateFortuneDisplay();
  }

  function _expireDripFortunes() {
      if ((state.dripFortunes || 0) <= 0) return;
      const grantedAt = state._dripFortuneGrantedAt || 0;
      if (grantedAt && (Date.now() - grantedAt) >= DRIP_FORTUNE_INTERVAL_MS) {
          console.log('[DRIP] Fortune expired. Was:', state.dripFortunes);
          state.dripFortunes = 0;
          state._dripFortuneGrantedAt = null;
          if (window.updateFortuneDisplay) window.updateFortuneDisplay();
      }
  }

  function _startDripFortuneTimer() {
      if (_dripFortuneTimerId) return;
      // Check expiry + eligibility every 60s
      _dripFortuneTimerId = setInterval(() => {
          _expireDripFortunes();
          _grantDripFortune();
      }, 60 * 1000);
      // Immediate check on start
      _expireDripFortunes();
      _grantDripFortune();
  }

  function _stopDripFortuneTimer() {
      if (_dripFortuneTimerId) {
          clearInterval(_dripFortuneTimerId);
          _dripFortuneTimerId = null;
      }
  }

  // Show floating "–1 Fortune" feedback under Begin Story button
  function showBeginFortuneSacrificeFeedback() {
      const btn = $('beginFortuneBtn');
      if (!btn) return;
      const fb = document.createElement('span');
      fb.className = 'begin-fortune-feedback';
      fb.innerHTML = `–1${_fortuneIconHTML()}`;
      btn.appendChild(fb);
      fb.addEventListener('animationend', () => fb.remove());
  }

  // Animate fortune count from oldVal up to newVal with stepping
  function animateFortuneCountUp(oldVal, newVal) {
      if (newVal <= oldVal) return;
      const targets = ['beginFortuneCount', 'fortuneBalanceDisplay', 'gnFortuneBalanceDisplay', 'fortuneHudCount', 'fortuneModalBalance'];
      const delta = newVal - oldVal;
      const stepDuration = Math.min(80, 1200 / delta); // cap total ~1.2s
      let current = oldVal;
      const interval = setInterval(() => {
          current++;
          targets.forEach(id => {
              const el = $(id);
              if (el) {
                  el.innerHTML = `${current}${_fortuneIconHTML()}`;
                  el.classList.remove('counting-up');
                  void el.offsetWidth; // reflow to re-trigger animation
                  el.classList.add('counting-up');
              }
          });
          if (current >= newVal) {
              clearInterval(interval);
              // Clean up animation class after last pulse
              setTimeout(() => {
                  targets.forEach(id => {
                      const el = $(id);
                      if (el) el.classList.remove('counting-up');
                  });
              }, 150);
          }
      }, stepDuration);
  }

  // Check if prompt contains blocked terms
  function checkPromptSafety(prompt) {
      const lower = (prompt || '').toLowerCase();
      const found = COVER_BLOCKED_TERMS.filter(term => lower.includes(term));
      return {
          safe: found.length === 0,
          blockedTerms: found
      };
  }

  // Auto-sanitize prompt by removing blocked terms
  function sanitizeCoverPrompt(prompt) {
      let sanitized = prompt;
      let modified = false;
      for (const term of COVER_BLOCKED_TERMS) {
          const regex = new RegExp(term, 'gi');
          if (regex.test(sanitized)) {
              sanitized = sanitized.replace(regex, '').replace(/\s+/g, ' ').trim();
              modified = true;
          }
      }
      return { sanitized, modified };
  }

  // Build the cover prompt for user display/editing (paid covers only)
  function buildEditableCoverPrompt() {
      const world = state.picks?.world || 'Modern';
      const genre = state.picks?.genre || 'Billionaire';
      const tone = state.picks?.tone || 'Earnest';
      // Title resolution: render no title if not finalized (no placeholder prose)
      const rawTitle = $('storyTitle')?.textContent?.trim() || state._backgroundStoryTitle?.trim() || '';
      const title = (rawTitle && rawTitle !== 'Untitled') ? rawTitle : '';

      // Determine world key and get Assembly object
      const wl1 = world.toLowerCase();
      const worldKey = wl1.includes('fantasy') ? 'fantasy'
          : wl1.includes('histor') ? 'historical'
          : wl1.includes('sci') ? 'scifi'
          : wl1.includes('dystop') ? 'dystopia'
          : (wl1.includes('post') && wl1.includes('apocal')) ? 'postapocalyptic'
          : wl1.includes('paranormal') || wl1.includes('vampire') ? 'paranormal'
          : 'modern';

      // Object names for metadata tracking (scene fragments are in generateMinimalCoverV1)
      const ASSEMBLY_OBJECT_NAMES = {
          modern: ['vintage key', 'silk ribbon', 'pearl earring', 'champagne glass', 'red lipstick', 'leather journal', 'single rose', 'antique locket'],
          fantasy: ['ornate dagger', 'crystal vial', 'wax-sealed letter', 'jeweled crown', 'silver mask', 'enchanted mirror', 'golden chalice', 'raven feather'],
          historical: ['quill pen', 'pocket watch', 'cameo brooch', 'candelabra', 'love letter', 'silk fan', 'brass compass', 'velvet glove'],
          scifi: ['holographic card', 'chrome ring', 'data chip', 'neural interface', 'crystal shard', 'metallic rose', 'quantum locket', 'star map'],
          paranormal: ['blood vial', 'moonstone pendant', 'black candle', 'silver dagger', 'tarot card', 'obsidian mirror', 'wolf fang', 'crimson ribbon']
      };

      const objectList = ASSEMBLY_OBJECT_NAMES[worldKey] || ASSEMBLY_OBJECT_NAMES.modern;
      const selectedObject = state._coverAssemblyObject || objectList[Math.floor(Math.random() * objectList.length)];

      return {
          title,
          world: worldKey,
          genre,
          tone,
          focalObject: selectedObject,
          prompt: `Book cover for "${title}" - a ${tone.toLowerCase()} ${genre.toLowerCase()} story set in a ${worldKey} world. Focal object: ${selectedObject}. Elegant, cinematic, painterly style. No people or faces.`
      };
  }

  // Legacy fortune modal — redirects to 3-card paywall (payModal)
