  // Storypass is deprecated — what used to be a story-scoped "$3 pass"
  // is now just a 20-Fortune purchase. The function name + callsites
  // are retained for backward compat, but the actual purchase routes
  // through the standard fortune_20 path. No story-scoping check
  // anymore — Fortunes are universal and can be bought anytime.
  function purchaseStorypass() {
      if (window._devBypass) {
          console.log('%c[DEV] Faking +20 Fortunes purchase', 'color: #ffd700');
          state.fortunes = (state.fortunes || 0) + 20;
          closeFortunePurchaseModal();
          if (window.updateFortuneDisplay) window.updateFortuneDisplay();
          showToast('+20 Fortunes added (dev mode)');
          return;
      }
      console.log('[Fortunes] 20-pack purchase requested — routing to Stripe');
      closeFortunePurchaseModal();
      initiateStripeCheckout('fortune_20');
  }

  // Subscription purchase — routes to Stripe subscription checkout.
  // If the user is ALREADY subscribed, intercept with a confirmation modal
  // (same-tier warning / upgrade summary / downgrade warning) before
  // proceeding. Without this gate, a Chosen subscriber clicking "Favored"
  // to top up Fortunes can silently downgrade themselves.
  function purchaseSubscription(tierName) {
      var _proceed = function () {
          if (window._devBypass) {
              console.log(`%c[DEV] Faking subscription: ${tierName}`, 'color: #ffd700');
              state.subscribed = true;
              state.subscriptionTier = tierName;
              const bonuses = { storied: 100, favored: 200, chosen: 400 };
              const oldFortunes = state.fortunes || 0;
              state.fortunes = oldFortunes + (bonuses[tierName] || 100);
              closeFortunePurchaseModal();
              if (window.updateFortuneDisplay) window.updateFortuneDisplay();
              animateFortuneCountUp(oldFortunes, state.fortunes);
              showToast(`${tierName.charAt(0).toUpperCase() + tierName.slice(1)} membership activated (dev mode)`);
              return;
          }
          console.log(`[Subscription] Purchase requested: ${tierName}`);
          closeFortunePurchaseModal();
          initiateStripeCheckout(tierName);
      };

      // Already subscribed? Show confirmation modal first.
      var _currentTier = String(state.subscriptionTier || '').toLowerCase();
      var _isSubscribed = !!state.subscribed && _tierRank(_currentTier) > 0;
      if (_isSubscribed && typeof _showSubscriptionConfirmModal === 'function') {
          console.log('[Subscription] Already subscribed (' + _currentTier + ') — routing to confirm modal before checkout to ' + tierName);
          _showSubscriptionConfirmModal({
              currentTier: _currentTier,
              newTier: tierName,
              onConfirm: _proceed
          });
          return;
      }
      _proceed();
  }

  // Handle fortune pack purchase (Stripe integration)
  function purchaseFortunePack(packSize, priceLabel) {
      /* Membership bonus: members receive +10% Fortunes when adding reserves */
      const memberMultiplier = state.subscribed ? 1.10 : 1;
      /* Seasonal promotion bonus (stacks with membership) */
      const seasonalMultiplier = (typeof window._getSeasonalBonusMultiplier === 'function')
          ? window._getSeasonalBonusMultiplier() : 1;
      /* Fate Event bonus (stacks with membership + seasonal) */
      const fateEventMultiplier = (typeof window._getFateEventBonusMultiplier === 'function')
          ? window._getFateEventBonusMultiplier() : 1;
      const combinedMultiplier = memberMultiplier * seasonalMultiplier * fateEventMultiplier;
      const effectiveSize = Math.round(packSize * combinedMultiplier);

      // Build bonus breakdown for logging/display
      const bonusParts = [];
      if (state.subscribed) bonusParts.push('+10% member bonus');
      if (seasonalMultiplier > 1) bonusParts.push('+' + Math.round((seasonalMultiplier - 1) * 100) + '% seasonal bonus');
      if (fateEventMultiplier > 1) bonusParts.push('+' + Math.round((fateEventMultiplier - 1) * 100) + '% Fate Event bonus');
      const bonusDesc = bonusParts.length > 0 ? ' (' + bonusParts.join(', ') + ')' : '';

      if (window._devBypass) {
        console.log(`%c[DEV] Faking fortune purchase: +${effectiveSize} (base ${packSize}${bonusDesc})`, 'color: #ffd700');
        const oldFortunes = state.fortunes || 0;
        state.fortunes = oldFortunes + effectiveSize;
        state.purchasedFortunes = (state.purchasedFortunes || 0) + effectiveSize;
        // Permanent flag — survives spending all Fortunes back to 0. Used by
        // fatecards.js resolveUnlockCount to keep the full 5-card deck
        // unlocked for anyone who has ever paid into the system.
        state.hasEverPurchased = true;
        // Grant a story credit (buying fortunes unlocks another original story)
        grantFreeCustomStoryCredit('fortune_purchase');
        closeFortunePurchaseModal();
        // Also dismiss paywall modal if fortune was bought from there
        const pm = $('payModal');
        if (pm && !pm.classList.contains('hidden')) {
            pm.classList.add('hidden');
            if (window.onPaywallDismiss) window.onPaywallDismiss();
        }
        if (window.updateFortuneDisplay) window.updateFortuneDisplay();
        animateFortuneCountUp(oldFortunes, state.fortunes);
        showToast(`+${effectiveSize} Fortunes added${bonusDesc} (dev mode)`);
        return;
      }
      console.log(`[Fortunes] Purchase requested: ${effectiveSize} fortunes (base ${packSize}, ${priceLabel})${bonusDesc}`);
      closeFortunePurchaseModal();
      initiateStripeCheckout('fortune_' + packSize);
  }

  // Generate cover with custom (paid) prompt
  async function generatePaidCover(customPrompt) {
      const btn = $('btnGenerateCover');
      const loading = $('coverGenLoading');
      const complete = $('coverGenComplete');

      if (btn) {
          btn.disabled = true;
          btn.textContent = 'Generating...';
      }
      if (loading) loading.style.display = 'flex';
      if (complete) complete.classList.add('hidden');

      startCoverButtonEmitter(btn);

      // Start background story if not started
      if (!_backgroundStoryStarted) {
          console.log('[PARALLEL:GEN] Starting background story generation');
          _backgroundStoryStarted = true;
          _backgroundStoryPromise = startBackgroundStoryGeneration();
      }

      try {
          // Build full prompt with user customization
          // Title resolution: render no title if not finalized (no placeholder prose)
          const rawTitle = $('storyTitle')?.textContent?.trim() || state._backgroundStoryTitle?.trim() || '';
          const title = (rawTitle && rawTitle !== 'Untitled') ? rawTitle : '';
          const world = state.picks?.world || 'Modern';
          const wl2 = world.toLowerCase();
          const worldKey = wl2.includes('fantasy') ? 'fantasy'
              : wl2.includes('histor') ? 'historical'
              : wl2.includes('sci') ? 'scifi'
              : wl2.includes('dystop') ? 'dystopia'
              : (wl2.includes('post') && wl2.includes('apocal')) ? 'postapocalyptic'
              : wl2.includes('paranormal') ? 'paranormal' : 'modern';

          const fullPrompt = `BOOK COVER IMAGE — PAID CUSTOM GENERATION

TITLE: "${title}"
AUTHOR LINE: "by S. Tory Bound"

USER PROMPT:
${customPrompt}

ABSOLUTE RULES:
- Subject matter: objects, environments, textures, symbols only
- A subtle human SHADOW is allowed but must be secondary
- Title text: large, high contrast, readable at thumbnail size
- Author line: smaller, elegant, below the title
- Style: elegant painterly realism, fine art quality
- Premium published novel aesthetic

WORLD MATERIAL TREATMENT (${worldKey}):
${worldKey === 'fantasy' ? '- Aged stone, tarnished metal, worn fabric textures' :
  worldKey === 'historical' ? '- Wood, brass, parchment, oil-stained cloth textures' :
  worldKey === 'scifi' ? '- Brushed alloy, polymer, subtle luminescence' :
  worldKey === 'paranormal' ? '- Dark velvet, oxidized silver, candlelit warmth' :
  '- Concrete, glass, leather, modern luxury textures'}

The final image must look like a real published novel cover.`;

          // REGRESSION GUARD: Block cinematic drift for Wry Confessional
          assertWryConfessionalVisual(fullPrompt, 'generatePaidCover');

          const res = await fetch(IMAGE_PROXY_URL, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                  prompt: fullPrompt,
                  imageIntent: 'book_cover',
                  size: '1024x1536', // 5:7 portrait ratio (matches Minimal v1)
                  _minimalV1: true   // Use same backend path as free covers
              })
          });

          if (!res.ok) throw new Error(`Image API error: ${res.status}`);

          const data = await res.json();
          const coverUrl = data.url || data.image || data.data?.[0]?.url;

          if (!coverUrl) {
              throw new Error('No cover URL returned');
          }

          _preGeneratedCoverUrl = coverUrl;
          state.coverImage = _preGeneratedCoverUrl;
          _coverGenUsed = true;
          _lastCoverShapeHash = computeStoryShapeHash();

          stopCoverButtonEmitter();
          if (loading) loading.style.display = 'none';
          if (complete) complete.classList.remove('hidden');

          if (btn) {
              btn.textContent = 'See Your Book Cover';
              btn.disabled = false;
              btn.classList.add('begin-story-ready');
          }
          _coverBtnIsBeginStory = true;

          console.log('[COVER$] Paid cover generated successfully');
          return true;

      } catch (err) {
          console.error('[COVER$] Paid cover generation failed:', err);
          stopCoverButtonEmitter();

          if (btn) {
              btn.textContent = 'Generation Failed';
              btn.disabled = false;
          }
          if (loading) loading.style.display = 'none';

          showToast('Cover generation failed. No Fortune consumed — please retry.');
          return false;
      }
  }

