  // ── Fortune Widget click → open Treasury panel ──
  // The widget is the persistent bottom-right balance display. Clicking
  // it should open the Treasury (balance breakdown + purchase CTAs +
  // subscription state). Convention: balance widgets open the wallet,
  // not the buy flow. The Treasury already exposes a "Buy more
  // Fortunes" CTA inside, so user retains agency at step one and can
  // get to purchase in one more click if they want.
  //
  // Prior behavior was to toggle a dropdown breakdown, but the
  // breakdown was unified into a single balance and the element was
  // removed — leaving the click as a dead handler that did nothing.
  (function _initFortuneWidget() {
      var fwMain = document.getElementById('fwFortuneMain');
      if (!fwMain) return;
      fwMain.style.cursor = 'pointer';
      fwMain.setAttribute('title', 'Open Treasury — balance + purchase + subscription');
      fwMain.addEventListener('click', function(e) {
          e.stopPropagation();
          // Treasury lives INSIDE the Vault > Account sub-panel as a
          // collapsible row. Just toggling the inner treasuryPanel did
          // nothing while the Vault overlay + Account sub were hidden.
          // Cascade through the three layers: open overlay → show
          // Account sub → expand Treasury row.
          try {
              // 1. Open the Vault overlay if it isn't already.
              var overlay = document.getElementById('menuOverlay');
              if (overlay && overlay.classList.contains('hidden')) {
                  try { if (typeof renderBurgerMenu === 'function') renderBurgerMenu(); } catch (_) {}
                  // Reset to main panel state first (the vault's normal
                  // open-from-burger pattern at app.js:66884).
                  var mainPanel = document.querySelector('.vault-panel');
                  if (mainPanel) mainPanel.classList.remove('hidden');
                  document.querySelectorAll('.vault-sub').forEach(function(s) { s.classList.add('hidden'); });
                  overlay.classList.remove('hidden');
              }
              // 2. Hide main panel, reveal the Account sub-panel.
              var mainPanel2 = document.querySelector('.vault-panel');
              if (mainPanel2) mainPanel2.classList.add('hidden');
              var accountSub = document.getElementById('vaultAccount');
              if (accountSub) accountSub.classList.remove('hidden');
              // 3. Expand the Treasury collapsible row (if collapsed).
              var treasury = document.getElementById('treasuryPanel');
              if (treasury && treasury.classList.contains('hidden')) {
                  if (typeof window.toggleTreasury === 'function') {
                      window.toggleTreasury();
                  } else {
                      treasury.classList.remove('hidden');
                      if (typeof window.populateTreasury === 'function') window.populateTreasury();
                  }
              } else if (treasury) {
                  // Already expanded — just repopulate so balance is fresh.
                  if (typeof window.populateTreasury === 'function') window.populateTreasury();
              }
              // 4. Scroll the Treasury panel into view inside the Account
              // sub — if Account is tall, the Treasury row may be off-screen.
              if (treasury && typeof treasury.scrollIntoView === 'function') {
                  requestAnimationFrame(function() {
                      try { treasury.scrollIntoView({ behavior: 'smooth', block: 'center' }); } catch (_) {}
                  });
              }
          } catch (err) {
              try { console.warn('[fortune-widget] click handler threw:', err && err.message); } catch (_) {}
          }
      });
  })();

  // Fortune dropdown toggle + update
  function toggleFortuneDropdown(dropdownId) {
    var dd = document.getElementById(dropdownId || 'fortuneDropdown');
    if (!dd) return;
    var isHidden = dd.classList.contains('hidden');
    dd.classList.toggle('hidden');
    if (isHidden) updateFortuneDropdown();
  }
  function updateFortuneDropdown() {
    var f = getAvailableFortunes();
    // Update both prose and GN dropdown elements
    ['', 'gn'].forEach(function(prefix) {
      var pfx = prefix ? prefix.charAt(0).toUpperCase() + prefix.slice(1) : '';
      var elSub = document.getElementById((prefix ? prefix + 'F' : 'f') + 'ortuneDropSub');
      var elPur = document.getElementById((prefix ? prefix + 'F' : 'f') + 'ortuneDropPurchased');
      var elSp = document.getElementById((prefix ? prefix + 'F' : 'f') + 'ortuneDropStorypass');
      var elDrip = document.getElementById((prefix ? prefix + 'F' : 'f') + 'ortuneDropDrip');
      if (elSub) elSub.textContent = f.subscription || 0;
      if (elPur) elPur.textContent = f.purchased || 0;
      if (elSp) elSp.textContent = f.storypass || 0;
      if (elDrip) elDrip.textContent = f.drip || 0;
    });
  }
  // Close dropdown when clicking outside
  document.addEventListener('click', function(e) {
    var wrap = e.target.closest('.fortune-dropdown-wrap');
    document.querySelectorAll('.fortune-dropdown').forEach(function(dd) {
      if (!dd.classList.contains('hidden') && !wrap) {
        dd.classList.add('hidden');
      }
    });
  });
  window.toggleFortuneDropdown = toggleFortuneDropdown;

  // EARNED COVER SYSTEM exports
  window.getCurrentCoverStage = getCurrentCoverStage;
  window.getMaxCoverStage = getMaxCoverStage;
  window.isCoverStageUnlocked = isCoverStageUnlocked;
  window.updateReaderCoverButton = updateReaderCoverButton;
  window.checkCoverStageUpgrade = checkCoverStageUpgrade;
  window.COVER_STAGES = COVER_STAGES;
  window.COVER_STAGE_LABELS = COVER_STAGE_LABELS;

  // ═══════════════════════════════════════════════════════════════════════════

  let _coverGenUsed = false;
  let _preGeneratedCoverUrl = null;
  let _backgroundStoryPromise = null;      // Promise for background story generation
  let _backgroundStoryStarted = false;     // Flag: story generation in progress
  let _coverBtnIsBeginStory = false;       // Flag: button has transitioned to "Begin Story"

  // ═══════════════════════════════════════════════════════════════════════════
  // COVER BUTTON SPARKLE EMITTER — Multi-tone gold radial emission
  // ═══════════════════════════════════════════════════════════════════════════
  // Trigger: Generate Cover button click (runs while generation is in progress)
  // Scope: Anchored to button PERIMETER, particles radiate outward
  // Style: Multi-tone gold palette, per-sparkle variance, short lifetimes
  // Stop: When generation completes, stop spawning, let existing particles fade
  // ═══════════════════════════════════════════════════════════════════════════

  let _coverSparkleContainerId = null;

  function startCoverButtonEmitter(btn) {
      if (!btn || _coverSparkleContainerId) return;

      // Create fixed overlay for sparkles (prevents opacity inheritance from button)
      const rect = btn.getBoundingClientRect();
      const overlay = document.createElement('div');
      overlay.id = 'coverBtnSparkles';
      overlay.className = 'authorship-sparkle-container';
      overlay.style.cssText = `
          position:fixed;left:${rect.left}px;top:${rect.top}px;
          width:${rect.width}px;height:${rect.height}px;
          pointer-events:none;z-index:2500;overflow:visible;
          opacity:1 !important;filter:none !important;
      `;
      document.body.appendChild(overlay);
      _coverSparkleContainerId = 'coverBtnSparkles';

      startSparkleEmitter(_coverSparkleContainerId, 'coverButton', 5, { initialBurst: 5 });
      console.log('[FX:COVER-BTN] Sparkle emitter started (unified)');
  }

  function stopCoverButtonEmitter() {
      if (!_coverSparkleContainerId) return;
      removeAnchoredSparkleContainer(_coverSparkleContainerId);
      _coverSparkleContainerId = null;
      console.log('[FX:COVER-BTN] Sparkle emitter stopped (unified)');
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // STORY SHAPE HASH — Track selections to gate cover regeneration
  // ═══════════════════════════════════════════════════════════════════════════
  let _lastCoverShapeHash = null;

  function computeStoryShapeHash() {
      // Combine all Story Shape selections into a deterministic string
      const parts = [
          state.picks?.world || '',
          state.picks?.genre || '',
          state.picks?.tone || '',
          state.picks?.dynamic || '',
          state.picks?.pov || '',
          state.archetype?.primary || '',
          state.archetype?.modifier || '',
          state.intensity || '',
          state.storyLength || ''
      ];
      return parts.join('|');
  }

  // Expose function to clear hash when Story Shape changes (called from card click handlers)
  window.clearCoverShapeHash = function() {
      _lastCoverShapeHash = null;
      console.log('[COVER:HASH] Cleared — regeneration enabled');
  };

  // ═══════════════════════════════════════════════════════════════════════════
  // GENERATE COVER BUTTON CLICK HANDLER — DISABLED (Earned Cover Phase B)
  // ═══════════════════════════════════════════════════════════════════════════
  // Pre-story cover generation is permanently disabled.
  // Use btnReaderCover in Reader mode instead.
  // ═══════════════════════════════════════════════════════════════════════════
  $('btnGenerateCover')?.addEventListener('click', async () => {
      // HARD BLOCK: Pre-story cover generation disabled (Earned Cover Phase B)
      console.warn('[COVER:BLOCKED] Pre-story cover generation disabled — use Reader cover button');
      showToast('Cover generation is available after starting your story');
      return;

      // === LEGACY CODE BELOW — UNREACHABLE ===
      const btn = $('btnGenerateCover');
      const status = $('coverGenStatus');
      const loading = $('coverGenLoading');
      const complete = $('coverGenComplete');
      const locked = $('coverGenLocked');

      // ═══════════════════════════════════════════════════════════════════
      // IF BUTTON IS IN "SEE COVER" MODE, NAVIGATE TO COVER VIEW
      // ═══════════════════════════════════════════════════════════════════
      if (_coverBtnIsBeginStory) {
          console.log('[COVER:NAV] Navigating to Cover View');
          showCoverView();
          return;
      }

      // ═══════════════════════════════════════════════════════════════════
      // STORY EXISTENCE GATE — Block cover generation if no story exists
      // ═══════════════════════════════════════════════════════════════════
      const storyContent = StoryPagination.getAllContent();
      if (!state.storyId || !storyContent || storyContent.trim().length === 0) {
          console.warn('[COVER:GATE] No story exists — cover generation blocked');
          showToast('Generate your story first before creating a cover');
          return;
      }

      // ═══════════════════════════════════════════════════════════════════
      // STORY SHAPE HASH CHECK — Block regeneration if selections unchanged
      // ═══════════════════════════════════════════════════════════════════
      const currentHash = computeStoryShapeHash();
      if (_lastCoverShapeHash && _lastCoverShapeHash === currentHash && _coverGenUsed) {
          console.log('[COVER:HASH] Story Shape unchanged — regeneration blocked');
          showToast('Change your Story Shape selections to generate a new cover');
          return;
      }

      // ═══════════════════════════════════════════════════════════════════
      // FORTUNE CHECK — First cover is free, subsequent regens cost 1 fortune
      // ═══════════════════════════════════════════════════════════════════
      if (_coverGenUsed && !hasFortunes()) {
          console.log('[Fortunes] No fortunes for cover regen — showing purchase modal');
          openFortunePurchaseModal();
          return;
      }

      // NOTE: Fortune consumed AFTER successful generation (see below)

      // Show loading state
      btn.disabled = true;
      btn.textContent = 'Generating...';
      if (status) status.classList.remove('hidden');
      if (loading) loading.style.display = 'flex';
      if (complete) complete.classList.add('hidden');
      if (locked) locked.classList.add('hidden');

      // ═══════════════════════════════════════════════════════════════════
      // TITLE RESOLUTION CHECK — Wait for title, proceed with empty if timeout
      // No placeholder prose on covers — title renders only when finalized
      // ═══════════════════════════════════════════════════════════════════
      const MAX_TITLE_WAIT_MS = 8000; // 8 seconds max wait

      let resolvedTitle = $('storyTitle')?.textContent?.trim() || '';
      const isUnresolved = !resolvedTitle || resolvedTitle === 'Untitled' || resolvedTitle === '';

      if (isUnresolved) {
          console.log('[COVER:TITLE] Title unresolved, waiting for pipeline...');
          btn.textContent = 'Generating title...';

          // Poll for title resolution
          const startWait = Date.now();
          while (Date.now() - startWait < MAX_TITLE_WAIT_MS) {
              await new Promise(r => setTimeout(r, 300));
              resolvedTitle = $('storyTitle')?.textContent?.trim()
                  || state._backgroundStoryTitle?.trim()
                  || '';
              if (resolvedTitle && resolvedTitle !== 'Untitled' && resolvedTitle !== '') {
                  console.log('[COVER:TITLE] Title resolved:', resolvedTitle);
                  break;
              }
          }

          // If still unresolved after timeout, proceed with no title (no placeholder)
          if (!resolvedTitle || resolvedTitle === 'Untitled' || resolvedTitle === '') {
              resolvedTitle = '';
              console.log('[COVER:TITLE] Timeout, proceeding with no title');
          }

          btn.textContent = 'Generating...';
      }

      console.log('[COVER:TITLE] Proceeding with title:', resolvedTitle || '(none)');

      // ═══════════════════════════════════════════════════════════════════
      // START FIREFLY EMITTER ON BUTTON (continuous while generating)
      // ═══════════════════════════════════════════════════════════════════
      startCoverButtonEmitter(btn);

      // ═══════════════════════════════════════════════════════════════════
      // START STORY GENERATION IN BACKGROUND (parallel with cover)
      // ═══════════════════════════════════════════════════════════════════
      if (!_backgroundStoryStarted) {
          console.log('[PARALLEL:GEN] Starting background story generation');
          _backgroundStoryStarted = true;
          _backgroundStoryPromise = startBackgroundStoryGeneration();
      }

      // ═══════════════════════════════════════════════════════════════════
      // START COVER GENERATION (fire and forget, but await for UI update)
      // ═══════════════════════════════════════════════════════════════════
      try {
          const coverUrl = await generateMinimalCoverV1({
              synopsis: state._synopsisMetadata || '',
              title: resolvedTitle,
              authorName: CANONICAL_AUTHOR_NAME,
              world: state.picks?.world || 'Modern',
              genre: state.picks?.genre || 'Billionaire',
              tone: state.picks?.tone || 'Earnest',
              intensity: state.intensity || 'Naughty'
          });

          // ═══════════════════════════════════════════════════════════════
          // VALIDATE COVER URL — Only proceed if we got a valid image
          // ═══════════════════════════════════════════════════════════════
          if (!coverUrl) {
              console.error('[COVER:GEN] Generation returned null/empty URL');
              stopCoverButtonEmitter();
              btn.textContent = 'Generation Failed - Try Again';
              btn.disabled = false;
              if (loading) loading.style.display = 'none';
              // NOTE: No Fortune consumed on failure
              return;
          }

          // ═══════════════════════════════════════════════════════════════
          // FORTUNE CONSUMPTION — First cover free, subsequent regens cost 1
          // ═══════════════════════════════════════════════════════════════
          if (_coverGenUsed) {
              await consumeFortune(1, 'cover_regen');
          }
          if (window.updateFortuneDisplay) window.updateFortuneDisplay();

          _preGeneratedCoverUrl = coverUrl;
          state.coverImage = _preGeneratedCoverUrl;
          _coverGenUsed = true;

          // Save Story Shape hash to gate future regeneration
          _lastCoverShapeHash = computeStoryShapeHash();
          console.log('[COVER:HASH] Saved hash:', _lastCoverShapeHash);

          console.log('[COVER:GEN] Cover URL acquired:', coverUrl.substring(0, 80) + '...');

          // ═══════════════════════════════════════════════════════════════
          // COVER COMPLETE: Show success state, stop emitter
          // ═══════════════════════════════════════════════════════════════
          stopCoverButtonEmitter(); // Stop spawning, let existing particles fade
          if (loading) loading.style.display = 'none';
          if (complete) complete.classList.remove('hidden');

          // Replace button with "See Your Book Cover"
          btn.textContent = 'See Your Book Cover';
          btn.disabled = false;
          // PLAQUE REGIME: No opacity mutation — material is static
          btn.classList.add('begin-story-ready');
          _coverBtnIsBeginStory = true; // Mark button as ready to navigate

          console.log('[COVER:GEN] Cover complete, button now "See Your Book Cover"');

      } catch (err) {
          console.error('[COVER:PREGEN] Failed:', err);
          stopCoverButtonEmitter(); // Stop spawning on failure too
          btn.textContent = 'Generation Failed - Try Again';
          btn.disabled = false;
          if (loading) loading.style.display = 'none';
      }
  });

  // ═══════════════════════════════════════════════════════════════════════════
  // READER COVER BUTTON — Earned Cover System (Reader UI only)
  // ═══════════════════════════════════════════════════════════════════════════
  // This is the ONLY authorized cover generation entry point.
  // Requires: state.storyId exists, story content exists
  // Cover stage is determined by story progress (turnCount + storyLength)
  // ═══════════════════════════════════════════════════════════════════════════

  // ═══════════════════════════════════════════════════════════════════════════
  // READER COVER BUTTON — Opens Cover Gallery Modal (does NOT generate directly)
  // ═══════════════════════════════════════════════════════════════════════════
  $('btnReaderCover')?.addEventListener('click', () => {
      // STORY EXISTENCE GATE
      const storyContent = StoryPagination.getAllContent();
      if (!state.storyId || !storyContent || storyContent.trim().length === 0) {
          console.warn('[COVER:READER] No story exists — blocked');
          showToast('Generate your story first');
          return;
      }

      // PART B: Start generation IMMEDIATELY before modal opens
      const nextStage = getNextGeneratableStage();
      if (nextStage) {
          // Start generation now (async, don't await)
          _gallerySelectedStage = nextStage;
          generateCoverInGallery();
          console.log('[COVER:READER] Started generation for', nextStage, 'before modal open');
      }

      // Open the Cover Gallery Modal (generation already in progress)
      openCoverGalleryModal();
  });

  // ═══════════════════════════════════════════════════════════════════════════
  // COVER GALLERY MODAL BUTTON WIRING
  // ═══════════════════════════════════════════════════════════════════════════
  $('btnGalleryClose')?.addEventListener('click', closeCoverGalleryModal);
  $('btnGalleryGenerate')?.addEventListener('click', generateCoverInGallery);
  $('btnGalleryPrimary')?.addEventListener('click', selectCoverAsPrimary);
  $('btnGalleryPrev')?.addEventListener('click', galleryPrevStage);
  $('btnGalleryNext')?.addEventListener('click', galleryNextStage);

  // ═══════════════════════════════════════════════════════════════════════════
  // BACKGROUND STORY GENERATION
  // ═══════════════════════════════════════════════════════════════════════════
  // This function starts story generation in the background.
  // Returns a promise that resolves when story text is ready.
  // ═══════════════════════════════════════════════════════════════════════════
  /**
   * Resolve world flavors: classify manual pick, auto-stack probabilistically.
   * Returns array of {val, type} (max length 2).
   * type = 'systemic' | 'contextual' | 'unclassified'
   */
  function resolveWorldFlavors(world, manualPick) {
      if (!manualPick) {
          // Modern auto-resolution: modern_core as default systemic + 90% contextual auto-pick
          if (world === 'Modern') {
              const result = [{ val: 'modern_core', type: 'systemic' }];
              if (Math.random() < 0.90) {
                  const pool = WORLD_CONTEXTUAL_POOL.Modern;
                  const pick = pool[Math.floor(Math.random() * pool.length)];
                  result.push({ val: pick, type: 'contextual' });
              }
              return result;
          }
          // Fantasy auto-resolution: fantasy_core always active + 90% contextual auto-pick
          if (world === 'Fantasy') {
              const result = [{ val: 'fantasy_core', type: 'systemic' }];
              if (Math.random() < 0.90) {
                  const pool = WORLD_CONTEXTUAL_POOL.Fantasy;
                  const pick = pool[Math.floor(Math.random() * pool.length)];
                  result.push({ val: pick, type: 'contextual' });
              }
              return result;
          }
          return [];
      }

      const type = SYSTEMIC_FLAVORS.has(manualPick) ? 'systemic'
                 : CONTEXTUAL_FLAVORS.has(manualPick) ? 'contextual'
                 : 'unclassified';
      const result = [{ val: manualPick, type }];

      // Fantasy: always prepend fantasy_core as systemic baseline
      if (world === 'Fantasy' && manualPick !== 'fantasy_core') {
          result.unshift({ val: 'fantasy_core', type: 'systemic' });
      }

      // Dystopia: inject systemic core, no auto-stack
      if (world === 'Dystopia') {
        result.unshift({ type: 'systemic', val: 'dystopia_core' });
        return result;
      }

      // PostApocalyptic: no auto-stack
      if (world === 'PostApocalyptic') return result;

      // Historical: inject systemic core, no auto-stack
      if (world === 'Historical') {
        result.unshift({ type: 'systemic', val: 'historical_core' });
        return result;
      }

      // Fantasy / SciFi / Modern: 25% chance of auto-stacking a 2nd contextual
      const pool = WORLD_CONTEXTUAL_POOL[world];
      if (pool && Math.random() < 0.25) {
          const candidates = pool.filter(v => v !== manualPick && CONTEXTUAL_FLAVORS.has(v));
          if (candidates.length > 0) {
              const pick = candidates[Math.floor(Math.random() * candidates.length)];
              result.push({ val: pick, type: 'contextual' });
          }
      }

      return result;
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // MODERN WORLD BLOCK — Canonical injection (locked language)
  // Modern contains no systemic pressure by default. It must resolve at least
  // one contextual flavor; zero-flavor Modern risks generic setting drift.
  // Max 2 contextual flavors. Never reveal internal classification labels.
  // ═══════════════════════════════════════════════════════════════════════════

  const MODERN_CONTEXTUAL_LABELS = {
      small_town: 'Small Town',
      college: 'College',
      friends: 'Friends',
      blue_blood: 'Blue Blood',
      office: 'Office (9\u20135)',
      supernatural_modern: 'Supernatural',
      superheroic_modern: 'Superheroic'
  };

  const MODERN_SOCIAL_PHYSICS_LAW = `
MODERN SOCIAL PHYSICS LAW:
Modern relationships exist inside overlapping social systems.
Friend groups, workplaces, digital communication, and reputation influence how romance unfolds.
Private decisions may quickly become visible through social networks or online behavior.
Romantic tension often arises from conflicting social expectations.`;

  const MODERN_FLAVOR_PRESSURE_LAW = `
MODERN FLAVOR PRESSURE LAW:
Each modern flavor generates its own social pressures that complicate romance.
Friend groups, careers, reputation, and public visibility should naturally create emotional and social tension.
Romantic choices should interact with the social environment of the flavor.`;

  // NOTE: Emotional Timing Physics — NOT duplicated here.
  // Existing pacing systems already enforce emotional timing:
  //   - buildPrematureRomanceDirective() (line 12946) — prevents premature romance collapse
  //   - Storyturn gating (ST1-ST6) — controls intimacy progression milestones
  //   - ST3 pacing cooldown (line 75609) — 2-turn breathing room after intimacy attempts
  //   - ROMANTIC_UNCERTAINTY directive (persistent cache) — requires hesitation before escalation
  //   - REL_SHIFT directive (persistent cache) — no easy reciprocation without complication
  //   - ESCALATION directive (persistent cache) — tension never resets to zero
  //   - buildRomanceProgressionDirective() — progression tracking per scene
  // Small reinforcement added below to complement existing systems.

  // NOTE: Memory Weighting / Emotional Gravity — NOT duplicated here.
  // Storybound already contains comprehensive emotional memory systems:
  //   - buildCallbackEchoDirective() (line 17928) — callback ledger, scene echoes with ✦ markers
  //   - buildChoiceMemoryDirective() — player choice memory resurfaces as consequences
  //   - buildMotifEchoDirective() (line 18059) — motif echo memory, max 5 active symbolic motifs
  //   - buildEmotionalResidueDirective() (line 7215) — emotional residue/persistence tracking
  //   - buildNarrativeGravityDirective() — primary/secondary/emotional arc gravity
  //   - buildMomentumDirective() — narrative momentum tracking
  //   - ECHO_CONSEQUENCE (persistent cache) — player decisions resurface as rumors/consequences
  //   - CONVERGING_FATE (persistent cache) — multiple threads converge in significant moments
  //   - state.motifLedger — max 5 active symbolic motifs with expression rotation
  //   - state.narrativeGravity — primary_arc, secondary_arc, emotional_arc tracking
  //   - state.relationshipVector — 6-axis emotional tracking (attraction, trust, resentment, jealousy, etc.)
  // Small reinforcement added below to complement existing systems.

  // ── Emotional Echo Gravity — extends existing callback ledger with intensity weighting ──
  // Audit confirmed: callbackLedger (max 12), emotionalResidue, motifEcho, narrativeGravity,
  // emotionalMomentum, choiceMemory, foreshadow, and convergingFate already exist.
  // This extension adds intensity-weighted echo bias to the existing callback system.

  const EMOTIONAL_ECHO_KEYWORDS = {
      confession: /\b(confess|admit|reveal|truth|honest|I love)\b/i,
      vulnerability: /\b(vulnerable|afraid|scared|need you|can't lose|tears|trembl|broke down)\b/i,
      betrayal: /\b(betray|lied|deceiv|trust.*broken|behind.*back)\b/i,
      conflict: /\b(argument|fight|shouted|furious|stormed|slammed|accused)\b/i,
      reconciliation: /\b(forgive|sorry|reconcil|make.*amends|peace|apologize)\b/i,
      devotion: /\b(sacrifice|protect|anything.*for|risk.*everything|chose.*you)\b/i
  };

  function detectEmotionalAnchor(sceneText) {
      if (!sceneText || !state.turnCount || state.turnCount < 4) return null;
      const matched = [];
      for (const [theme, pattern] of Object.entries(EMOTIONAL_ECHO_KEYWORDS)) {
          if (pattern.test(sceneText)) matched.push(theme);
      }
      if (matched.length === 0) return null;
      // Only anchor if 2+ emotional signals detected (avoids noise)
      if (matched.length < 2) return null;
      return { scene: state.turnCount, themes: matched, weight: matched.length >= 3 ? 'major' : 'emotional' };
  }

  function registerEmotionalAnchor(sceneText) {
      const anchor = detectEmotionalAnchor(sceneText);
      if (!anchor) return;
      if (!state.emotionalEchoAnchors) state.emotionalEchoAnchors = [];
      // Prevent duplicate for same scene
      if (state.emotionalEchoAnchors.some(a => a.scene === anchor.scene)) return;
      state.emotionalEchoAnchors.push(anchor);
      // Cap at 5 — drop oldest
      while (state.emotionalEchoAnchors.length > 5) state.emotionalEchoAnchors.shift();
      console.log('[EchoGravity] Emotional anchor registered:', anchor);
  }

  function buildEmotionalEchoGravityDirective() {
      const anchors = state.emotionalEchoAnchors;
      if (!anchors || anchors.length === 0) return '';
      if (!state.turnCount || state.turnCount < 6) return '';
      // ~30% base chance, nudged by phase gravity after vulnerability threshold
      const echoChance = typeof applyPhaseGravity === 'function'
          ? applyPhaseGravity(0.30, 'aftershockSensitivity')
          : 0.30;
      if (Math.random() > echoChance) return '';
      // Weighted random selection with age decay (prevents recency bias)
      const eligible = anchors.filter(a => (state.turnCount - a.scene) >= 2);
      if (eligible.length === 0) return '';
      const weights = eligible.map(a => {
          const baseWeight = a.weight === 'major' ? 3 : 2;
          const agePenalty = (state.turnCount - a.scene) * 0.05;
          return Math.max(0.5, baseWeight - agePenalty);
      });
      const totalWeight = weights.reduce((s, w) => s + w, 0);
      let roll = Math.random() * totalWeight;
      let selected = eligible[0];
      for (let i = 0; i < eligible.length; i++) {
          roll -= weights[i];
          if (roll <= 0) { selected = eligible[i]; break; }
      }
      return `\nEMOTIONAL ECHO GRAVITY: An emotionally significant moment from scene ${selected.scene} (${selected.themes.join(', ')}) may subtly influence this scene. Characters may hesitate, remember, or react based on that earlier event. The echo should be subtle — a pause, a glance, a word chosen carefully — not an explicit callback.`;
  }

  const EMOTIONAL_MEMORY_REINFORCEMENT = `
EMOTIONAL MEMORY REMINDER:
Important emotional moments from earlier scenes may continue to influence character behavior.
Past vulnerability, betrayal, confession, or trust can shape how characters respond now.
Characters should occasionally reference or be affected by significant earlier events.`;

  const SCENE_INTERRUPTION_PHYSICS = `
SCENE INTERRUPTION PHYSICS:
Scenes occur within active environments. Occasional small interruptions (people, sounds, movement, notifications, or background activity) may briefly disrupt conversations or shift attention.
Interruptions should be brief and organic, not major plot events.`;

  const EMOTIONAL_COST_OF_PROGRESS = `
EMOTIONAL COST OF PROGRESS:
Meaningful emotional progress often carries cost or risk.
Confessions, vulnerability, reconciliation, or intimacy may involve hesitation, uncertainty, or emotional exposure.
Progress should feel earned, not convenient.`;

  // Consolidated: CULTURAL_SOCIAL_PHYSICS + SOCIAL_MEMORY_OF_ACTIONS → SOCIAL_DYNAMICS
  const SOCIAL_DYNAMICS = `
SOCIAL DYNAMICS:
Characters behave according to their society's social norms — hierarchy, reputation, ritual, or ownership structures shape speech and conflict.
Communities remember meaningful past actions; reputation, trust, or suspicion influences later interactions.`;

  const PUBLIC_PRIVATE_BEHAVIOR = `
PUBLIC VS PRIVATE BEHAVIOR:
Characters may behave differently in public and private settings.
Reputation, hierarchy, and witnesses may shape public behavior, while private moments may allow more honesty or vulnerability.`;

  const AMBIENT_HUMAN_AGENCY = `
AMBIENT HUMAN AGENCY:
Side characters behave like independent people with their own lives, limited patience, and imperfect understanding.
They may misunderstand, interrupt, or prioritize their own concerns instead of fully focusing on the protagonist's emotional situation.`;

  // Consolidated: ENVIRONMENTAL_RESONANCE + TERRITORIAL_SPACE_DYNAMICS + APPROACH_DISTANCE_DYNAMICS → SPATIAL_DYNAMICS
  const SPATIAL_DYNAMICS = `
SPATIAL DYNAMICS:
Environmental details may occasionally resonate with or contrast the emotional tone.
Locations may function as territories — authority shifts depending on who controls the space.
Physical distance between characters signals attraction, challenge, hesitation, or control.`;

  const CHARACTER_PRIVATE_MOTIVES = `
CHARACTER PRIVATE MOTIVES:
Characters may have private motives or goals influencing their behavior. They may pursue personal objectives, test others, or conceal intentions rather than simply reacting to the protagonist.`;

  const NARRATIVE_VOICE_VARIATION = `
NARRATIVE VOICE VARIATION:
The narrative voice may vary slightly between stories. Sentence rhythm, description density, metaphor usage, and interior thoughts may reflect a consistent stylistic tone unique to the story.`;

  const NPC_ROMANTIC_BOUNDARY = `
NPC ROMANTIC BOUNDARY:
Minor characters should not develop romantic chemistry with the protagonist unless they are intentionally introduced as a Rival.
Casual friendliness, teasing, or warmth is acceptable, but sustained romantic tension should remain focused on the primary relationship and any explicit rival.`;

  const SOCIAL_FRICTION_PHYSICS = `
SOCIAL FRICTION PHYSICS:
Conversations may contain natural social friction.
Characters may hesitate, misunderstand, deflect, interrupt, or partially answer instead of communicating perfectly.
Small resistance increases realism — avoid scenes where characters communicate with mechanical clarity.`;

  // ── Emotional Threshold Crossing — permanent relationship milestones ──
  function registerThresholdCrossing(sceneText) {
      if (!sceneText) return;
      if (!state._relationshipThresholds) {
          state._relationshipThresholds = {
              confessionCrossed: false,
              vulnerabilityCrossed: false,
              betrayalCrossed: false,
              reconciliationCrossed: false,
              devotionCrossed: false
          };
      }
      // Reuse echo keywords — threshold requires 3+ signals (major emotional event only)
      const matched = [];
      for (const [theme, pattern] of Object.entries(EMOTIONAL_ECHO_KEYWORDS)) {
          if (pattern.test(sceneText)) matched.push(theme);
      }
      if (matched.length < 3) return;
      const t = state._relationshipThresholds;
      if (matched.includes('confession') && !t.confessionCrossed) { t.confessionCrossed = true; console.log('[Threshold] Confession crossed'); }
      if (matched.includes('vulnerability') && !t.vulnerabilityCrossed) { t.vulnerabilityCrossed = true; console.log('[Threshold] Vulnerability crossed'); }
      if (matched.includes('betrayal') && !t.betrayalCrossed) { t.betrayalCrossed = true; console.log('[Threshold] Betrayal crossed'); }
      if (matched.includes('reconciliation') && !t.reconciliationCrossed) { t.reconciliationCrossed = true; console.log('[Threshold] Reconciliation crossed'); }
      if (matched.includes('devotion') && !t.devotionCrossed) { t.devotionCrossed = true; console.log('[Threshold] Devotion crossed'); }
  }

  // ── Relationship Phase Gravity — threshold-based probability nudges ──
  // Returns a small multiplier object that other probabilistic systems can query.
  // No new directive text — nudges are internal only.
  function getRelationshipPhaseGravity() {
      const t = state._relationshipThresholds;
      if (!t) return null;
      const gravity = {};
      if (t.confessionCrossed) {
          gravity.vulnerability = 1.10;       // +10% vulnerability moments
          gravity.jealousy = 1.08;            // +8% jealousy triggers
          gravity.territoryPressure = 1.08;
          gravity.emotionalAvoidance = 0.90;  // -10% complete avoidance
      }
      if (t.vulnerabilityCrossed) {
          gravity.intimateConversation = 1.10;
          gravity.emotionalHonesty = 1.08;
          gravity.aftershockSensitivity = 1.05;
      }
      if (t.betrayalCrossed) {
          gravity.hesitation = 1.10;
          gravity.trustRebuilding = 1.10;
          gravity.socialFriction = 1.08;
          gravity.misinterpretation = 1.08;
      }
      if (t.reconciliationCrossed) {
          gravity.emotionalOpenness = 1.08;
          gravity.protectiveBehavior = 1.05;
          gravity.devotionSignals = 1.05;
      }
      if (t.devotionCrossed) {
          gravity.protectiveness = 1.10;
          gravity.sacrificeGestures = 1.05;
          gravity.territorySignals = 1.05;
      }
      return Object.keys(gravity).length > 0 ? gravity : null;
  }

  // Apply phase gravity to a probability value (returns adjusted probability)
  function applyPhaseGravity(baseProbability, gravityKey) {
      const gravity = getRelationshipPhaseGravity();
      if (!gravity || !gravity[gravityKey]) return baseProbability;
      return Math.min(1.0, baseProbability * gravity[gravityKey]);
  }

  function buildRelationshipThresholdDirective() {
      const t = state._relationshipThresholds;
      if (!t) return '';
      const crossed = [];
      const tendencies = [];
      if (t.confessionCrossed) {
          crossed.push('romantic feelings have been acknowledged');
          tendencies.push('characters cannot pretend feelings are unknown — vulnerability and jealousy may surface more easily');
      }
      if (t.vulnerabilityCrossed) {
          crossed.push('deep vulnerability has been shared');
          tendencies.push('emotional honesty comes more naturally, but sensitivity to emotional aftershocks is heightened');
      }
      if (t.betrayalCrossed) {
          crossed.push('trust has been broken and may recover slowly');
          tendencies.push('hesitation, misinterpretation, and social friction are more likely — trust must be actively rebuilt');
      }
      if (t.reconciliationCrossed) {
          crossed.push('a serious conflict has been reconciled');
          tendencies.push('emotional openness and protective behavior increase, but fragility remains');
      }
      if (t.devotionCrossed) {
          crossed.push('an act of sacrifice or devotion has occurred');
          tendencies.push('protectiveness and territorial signals may intensify');
      }
      if (crossed.length === 0) return '';
      return `\nRELATIONSHIP THRESHOLDS CROSSED:
The relationship has passed permanent emotional milestones that continue to shape how the characters perceive each other:
${crossed.map(c => '- ' + c).join('\n')}
Emotional tendencies:
${tendencies.map(t => '- ' + t).join('\n')}
These milestones cannot be undone. Characters should behave consistently with this shared history.`;
  }

  const EMOTIONAL_TIMING_REINFORCEMENT = `
EMOTIONAL TIMING REMINDER:
Confessions, forgiveness, and deep vulnerability should emerge only after sufficient relational tension.
Characters should struggle, hesitate, or misinterpret before reaching emotional clarity.
Avoid resolving emotional conflicts in a single scene.`;

