  function buildModernWorldBlock(resolvedFlavors) {
      let block = `
WORLD: Modern
"a modern world of ambition and things left unsaid"

REALITY MODEL:
\u2022 Contemporary society
\u2022 Real-world physics
\u2022 Institutions, reputation, and social perception influence relationships
\u2022 Love unfolds within existing social structures rather than mythic or systemic forces`;

      // Extract contextual flavors only (skip systemic modern_core)
      const contextuals = (resolvedFlavors || [])
          .filter(f => f.type === 'contextual' && MODERN_CONTEXTUAL_LABELS[f.val])
          .slice(0, 2); // Hard cap: never exceed 2

      for (const flavor of contextuals) {
          const label = MODERN_CONTEXTUAL_LABELS[flavor.val];
          const effect = CONTEXT_GRAVITY[flavor.val] || '';
          block += `\n\nWorld Context: ${label}`;
          if (effect) block += `\nContext Effect: ${effect}`;

          // Inject flavor pressure context — visible to model during generation
          const pressure = MODERN_FLAVOR_PRESSURE[flavor.val];
          if (pressure) {
              block += `\n\nMODERN FLAVOR CONTEXT — ${label}:`;
              block += `\nCore Pressure: ${pressure.corePressure}`;
              block += `\nSocial Network Effect: ${pressure.socialNetwork}`;
              block += `\nRomantic Risk: ${pressure.romanticRisk}`;
              block += `\nEscalation Pattern: ${pressure.escalation}`;
              if (pressure.attentionEconomy) block += `\nAttention Economy: ${pressure.attentionEconomy}`;
              if (pressure.lifeTrajectory) block += `\nLife Trajectory Pressures: ${pressure.lifeTrajectory}`;
          }
      }

      block += MODERN_SOCIAL_PHYSICS_LAW;
      block += MODERN_FLAVOR_PRESSURE_LAW;
      block += MODERN_ATTENTION_ECONOMY_LAW;
      block += MODERN_LIFE_TRAJECTORY_LAW;

      // Canon anchor for turn 2+ world drift prevention
      for (const flavor of contextuals) {
          if (WORLD_CANON_ANCHORS[flavor.val]) {
              block += `\n${WORLD_CANON_ANCHORS[flavor.val]}`;
              break; // One anchor per scene
          }
      }

      return block;
  }

