  // ── Thirst: participant selection scoring for ST3 multi-participant scenes ──
  // Lightweight algorithm: scores candidates by recency penalties, builds group iteratively.
  // Called from prompt builder to inject recommended participants into strategy directive.
  function _thirstSelectParticipants() {
      if (!state.thirstRotation) return [];
      var candidates = (state.liCandidates || [])
          .filter(function(c) { return c.interestScore > 0; })
          .map(function(c) { return c.id; });
      // Also include active temptation characters
      (state.activeTemptations || []).forEach(function(t) {
          if (t.characterId && candidates.indexOf(t.characterId) === -1) {
              candidates.push(t.characterId);
          }
      });
      // Also include external suitors
      (state.externalSuitors || []).forEach(function(s) {
          if (s.characterId && s.active && candidates.indexOf(s.characterId) === -1) {
              candidates.push(s.characterId);
          }
      });
      if (candidates.length < 2) return candidates;

      var rot = state.thirstRotation;
      var lastGroup = rot.lastST3Participants || [];
      var recent = rot.recentParticipants || [];
      var recentPairsSet = {};
      (rot.recentPairs || []).slice(-6).forEach(function(p) { recentPairsSet[p] = true; });

      // Score each candidate
      function score(cId, alreadySelected) {
          var s = 100;
          // Penalty: was in last group
          if (lastGroup.indexOf(cId) !== -1) s -= 40;
          // Penalty: per occurrence in recent participants
          recent.forEach(function(r) { if (r === cId) s -= 10; });
          // Penalty: forms a recently-seen pair with already-selected
          (alreadySelected || []).forEach(function(sel) {
              var pair = [cId, sel].sort().join(',');
              if (recentPairsSet[pair]) s -= 25;
          });
          // Bonus: not seen in last 3 ST3 scenes (~6–9 recent entries)
          var lastNine = recent.slice(-9);
          if (lastNine.indexOf(cId) === -1) s += 20;
          return s;
      }

      // Score normalization: if all scores are low, halve recency penalties and rescore
      var _penaltyScale = 1;
      var _maxScore = 0;
      candidates.forEach(function(c) { var s = score(c, []); if (s > _maxScore) _maxScore = s; });
      if (_maxScore < 40) {
          _penaltyScale = 0.5; // soft reset — halve recency weights for this pass
      }

      // Wrap scoring with penalty scale
      function scaledScore(cId, alreadySelected) {
          var s = 100;
          if (lastGroup.indexOf(cId) !== -1) s -= 40 * _penaltyScale;
          recent.forEach(function(r) { if (r === cId) s -= 10 * _penaltyScale; });
          (alreadySelected || []).forEach(function(sel) {
              var pair = [cId, sel].sort().join(',');
              if (recentPairsSet[pair]) s -= 25 * _penaltyScale;
          });
          var lastNineS = recent.slice(-9);
          if (lastNineS.indexOf(cId) === -1) s += 20;
          return s;
      }

      // Build group iteratively
      var selected = [];
      var remaining = candidates.slice();
      var _scoreFn = _penaltyScale < 1 ? scaledScore : score;

      // Pick first
      remaining.sort(function(a, b) { return _scoreFn(b, selected) - _scoreFn(a, selected); });
      selected.push(remaining.shift());

      // Pick second
      remaining.sort(function(a, b) { return _scoreFn(b, selected) - _scoreFn(a, selected); });
      if (remaining.length > 0) selected.push(remaining.shift());

      // Optional third: only if pool >= 5
      if (candidates.length >= 5 && remaining.length > 0) {
          remaining.sort(function(a, b) { return _scoreFn(b, selected) - _scoreFn(a, selected); });
          selected.push(remaining.shift());
      }

      // Hard constraint: must not exactly match last group
      if (selected.length === lastGroup.length && selected.slice().sort().join(',') === lastGroup.slice().sort().join(',')) {
          // Swap last pick with next-best remaining
          if (remaining.length > 0) {
              selected.pop();
              selected.push(remaining[0]);
          }
      }

      // Hard constraint: at least 1 participant not in previous group
      var hasNewParticipant = selected.some(function(s) { return lastGroup.indexOf(s) === -1; });
      if (!hasNewParticipant && remaining.length > 0) {
          // Replace lowest-scored participant with someone new
          selected[selected.length - 1] = remaining[0];
      }

      return selected;
  }
  window._thirstSelectParticipants = _thirstSelectParticipants;

  function buildDystopiaWorldBlock(resolvedFlavors) {
      const customText = state.worldCustomTexts?.['Dystopia'] || '';

      let block = `
WORLD: Dystopia
"a world where the system itself threatens love"

Dystopia in Storybound is not an aesthetic. It is a structural pressure system that destabilizes love.
Every flavor must answer: What makes loving someone dangerous here?

REALITY MODEL:
• Dystopian pressures operate through culture, technology, economics, psychology, infrastructure, biology, or ideology
• Each flavor operates through a single dominant pressure — flavors must not overlap
• Dystopias reshape intimacy by destabilizing privacy, exclusivity, identity continuity, emotional autonomy, and social trust
• The system always pressures the bond — love becomes dangerous because the world cannot tolerate its natural structure

THEMATIC IDENTITY:
Dystopia in Storybound is systemic, structural, psychological, political, intimate.
The system does not simply restrict love — it redefines the conditions under which love can exist.

DYSTOPIA FLAVOR LAW:
All scenes must derive tension from the flavor's specific systemic mechanic.
Do NOT introduce unrelated dystopian tropes such as: surveillance towers, wardens, riot police, generic rebellion graffiti, authoritarian patrols.
The world must express the specific systemic mechanic of the selected flavor.
Dystopias are not aesthetic settings — they are romance-breaking systemic pressures.

PROHIBITED NARRATIVE SHORTCUTS:
Storybound dystopias are romance traps, not revolution stories.
Do NOT introduce: organized resistance movements, rebel factions, underground networks, revolutionary leaders, overthrow-the-regime plots, secret dissidents, resistance cells, rebel hideouts, or insurgent missions.
The tension comes from the systemic pressure on the romantic bond — not from fighting the system.`;

      // Flavor injection (Dystopia selects exactly one flavor)
      const flavorEntry = (resolvedFlavors || [])
          .find(f => DYSTOPIA_FLAVOR_LABELS[f.val]);
      if (flavorEntry) {
          // Validate canonical flavor
          if (!validateDystopiaFlavor(flavorEntry.val)) {
              console.error('[DYSTOPIA] Non-canonical flavor rejected:', flavorEntry.val);
          }
          const label = DYSTOPIA_FLAVOR_LABELS[flavorEntry.val];
          const effect = DYSTOPIA_FLAVOR_EFFECTS[flavorEntry.val] || '';
          const canon = DYSTOPIA_FLAVOR_CANON[flavorEntry.val];
          block += `\n\nDystopian Pressure: ${label}`;
          if (effect) block += `\nPressure Effect: ${effect}`;
          if (canon) {
              block += `\n\nCANONICAL FLAVOR DEFINITION — ${label.toUpperCase()}:`;
              block += `\nSystemic Pressure: ${canon.pressure}`;
              block += `\nRomantic Danger: ${canon.romanticDanger}`;
              block += `\nWorld Physics: ${canon.worldPhysics}`;
              block += `\n\nAll scene tension MUST arise from this systemic pressure. Generic dystopian imagery without connection to this mechanic is a generation failure.`;
          }
          // ── Thirst: scene-level rotation, casting, multi-participant, and power distribution ──
          if (flavorEntry.val === 'thirst' && state.thirstRotation) {
              var _lastGroup = (state.thirstRotation.lastST3Participants || []).join(', ') || 'none';
              var _recentRotation = (state.thirstRotation.suitorHistory || []).slice(-6).join(' → ') || 'none';
              var _recentPairs = (state.thirstRotation.recentPairs || []).slice(-4).join('; ') || 'none';
              block += `\n\nTHIRST — CASTING DIVERSITY (SCENE-LEVEL):`;
              block += `\nThe contender pool must maintain pressure diversity — not gender homogeneity.`;
              block += `\nEach contender fulfills a distinct pressure role: desire (romantic pull), threat (destabilize/coerce), or leverage (system knowledge/access).`;
              block += `\nNo two primary contenders may occupy identical pressure roles.`;
              block += `\n\nTHIRST — ROTATION ENFORCEMENT (SCENE-LEVEL):`;
              block += `\n- Intimacy model: DISTRIBUTED (4–5 eligible participants, combination rotation required)`;
              block += `\n- ST3 scenes involve 2–3 participants (co-participation in maintenance, not exclusive selection)`;
              block += `\n- Last ST3 group: ${_lastGroup}`;
              block += `\n- Recent rotation: ${_recentRotation}`;
              block += `\n- Recent pairs: ${_recentPairs}`;
              block += `\n- HARD RULE: Do NOT repeat the exact same group as last scene`;
              block += `\n- Avoid repeating any pair from the last 2 scenes`;
              block += `\n- At least 1 participant must be someone NOT in the previous group`;
              block += `\n- Each ST3 must create intra-group tension AND inter-group consequences`;
              block += `\n- ST1 scenes: selection is public or semi-observed — show reactions from watchers`;
              block += `\n- ST2 scenes: boundaries include refusing selection, altering rotation, withholding access`;
              block += `\n- No exclusive romantic lock-in. No dominant main LI. Maintain multi-node tension.`;
              block += `\n\nTHIRST — POWER DISTRIBUTION (SCENE-LEVEL):`;
              block += `\nEvery intimacy scene must visibly change who holds power.`;
              block += `\nThe scene must leave behind at least one of:`;
              block += `\n- A shift in who the system depends on`;
              block += `\n- A shift in who can destabilize it`;
              block += `\n- A shift in who the protagonist fears losing or provoking`;
              block += `\nIf the scene could be removed without affecting future power dynamics, it is invalid.`;
              block += `\nIntimacy without consequence is not Thirst — it is generic romance.`;
              block += `\n\nTHIRST — STRUCTURAL REQUIREMENTS (MANDATORY — every ST3 scene):`;
              block += `\nEvery ST3 scene MUST include all three of the following:`;
              block += `\n1) A CONCRETE SHIFT IN LEVERAGE`;
              block += `\n   - One participant gains a specific advantage tied to the system (access, knowledge, control, dependency, or exclusive capability)`;
              block += `\n   - This must be explicit and attributable: who gained what, and why it matters`;
              block += `\n2) A REACTIVE CONSEQUENCE FROM OUTSIDE THE GROUP`;
              block += `\n   - At least one non-participant must respond with intent (confrontation, restriction, alliance, sabotage, surveillance, withdrawal of support)`;
              block += `\n   - Not just emotion — must imply or initiate action`;
              block += `\n3) A BINDING FORWARD HOOK`;
              block += `\n   - The scene must introduce a specific constraint, risk, or dependency that will limit or shape what can happen in the next scene`;
              block += `\n   - The hook must be: actionable (someone can act on it), restrictive (it removes or complicates options), and attributable (tied to a specific participant or system component)`;
              block += `\n   - Vague implications are invalid`;
              block += `\n   - If the next scene could ignore this hook without consequence, the hook is invalid`;
              block += `\nIf any of the above are missing, the scene is invalid.`;
              block += `\nIntegrate these elements naturally — they must emerge through action, dialogue, or implication, not summaries or explanations.`;
              block += `\n\n4) INSTABILITY ESCALATION (CARRY-FORWARD RULE):`;
              block += `\n   - The instability introduced in this scene must build upon, intensify, or complicate an existing unresolved tension from prior scenes.`;
              block += `\n   - Do NOT resolve or reset prior tensions unless doing so creates a larger or more dangerous imbalance.`;
              block += `\n   - Each scene should make the system harder to stabilize, not easier.`;
              block += `\n\nTHIRST — CANONICAL WATER SYSTEM (LOCKED SCHEMA):`;
              block += `\nThe purification system consists of EXACTLY five core components. Do not invent new system parts beyond these.`;
              block += `\n1) INTAKE GATE — Controls raw water entry. Actions: open, restrict, seal. Risks: contamination surge, debris overload, flow imbalance.`;
              block += `\n2) PRESSURE CHAMBER — Regulates internal system pressure. Actions: vent, pressurize, equalize. Risks: overpressure shock, rupture, cascade imbalance.`;
              block += `\n3) FILTRATION STACK — Multi-layer membrane filtration. Actions: cycle, flush, isolate layers. Risks: clogging, bypass contamination, reduced output.`;
              block += `\n4) DOSING LINE — Introduces treatment agents (coagulant/disinfectant). Actions: dose, cut, recalibrate timing. Risks: under-treatment (unsafe water), over-treatment (toxicity).`;
              block += `\n5) PURGE/BACKFLOW CHANNEL — Removes waste, prevents buildup. Actions: purge, redirect, seal return. Risks: backflow contamination, pressure feedback, system fouling.`;
              block += `\nSYSTEM RULES:`;
              block += `\n- All technical interactions MUST involve one or more of these components`;
              block += `\n- Components may interact (intake affects pressure, dosing affects filtration)`;
              block += `\n- Do NOT introduce new machinery, subsystems, or vague "controls"`;
              block += `\nKNOWLEDGE DISTRIBUTION:`;
              block += `\n- No single character fully understands all five components`;
              block += `\n- Each key participant specializes in ONE primary domain: intake control, pressure regulation, filtration handling, chemical dosing, or purge/backflow management`;
              block += `\n- Complex operations require coordination across multiple participants`;
              block += `\nSCENE REQUIREMENTS:`;
              block += `\n- Every system interaction must reference a specific component, use a specific action, and imply a consequence if done incorrectly`;
              block += `\n- Technical detail: 1-2 lines max per interaction, embedded in action or dialogue, never explained like a manual`;
              block += `\n- Avoid vague phrases like "adjust the system", "stabilize the flow", "fix the pressure"`;
              block += `\n- Every system action must carry a potential failure mode that persists or compounds across scenes`;
              block += `\nCONSISTENCY RULE:`;
              block += `\n- Once a behavior or constraint is established for a component, it must remain consistent across all future scenes unless explicitly altered by events in the story.`;
              block += `\nCOMPONENT COVERAGE PRESSURE:`;
              block += `\n- Across consecutive scenes, vary which components are active.`;
              block += `\n- Avoid repeatedly centering the same component unless driven by ongoing instability.`;
              block += `\n- If a component has not been used recently, reintroduce it through: new failure modes, deferred consequences, or interaction with another component.`;
              block += `\n- The system should feel interconnected and fully utilized over time.`;
              block += `\n\nTHIRST — CHARACTER IDENTITY ANCHOR (MANDATORY):`;
              block += `\nEach participant must express a consistent, recognizable behavioral signature.`;
              block += `\nBefore writing dialogue or action, each participant has a stable identity vector:`;
              block += `\n- CONTROL STYLE: how they act under pressure (precise, forceful, evasive, adaptive, withholding)`;
              block += `\n- EMOTIONAL EXPRESSION: how they reveal intent (direct, masked, ironic, restrained, volatile)`;
              block += `\n- DECISION PATTERN: how they choose (risk-accepting, risk-averse, opportunistic, principled, reactive)`;
              block += `\nThese traits must remain consistent across scenes, shape speech/action/response, and differentiate from all other participants.`;
              block += `\nIn every multi-participant scene: each participant must behave in a way that could ONLY come from their identity vector.`;
              block += `\nParticipants may take similar actions, but for different reasons, with different timing, tone, or intent.`;
              block += `\nIdentity must be expressed through why they act, how they act, and when they act — not just what action they take.`;
              block += `\nDialogue must reflect identity through word choice, sentence structure, and timing (interrupting, waiting, deflecting).`;
              block += `\nIf two participants could swap lines without changing the scene, the scene is invalid.`;
              block += `\nDo not explicitly describe these traits — they must be inferred through behavior.`;
              block += `\n\nTHIRST — MICRO-VARIATION LAYER (WITHIN-CHARACTER):`;
              block += `\nA character's identity defines HOW they act — not the exact words or patterns they repeat.`;
              block += `\nFor each participant across scenes, vary at least one of:`;
              block += `\n- Expression form (direct statement → question → implication → silence)`;
              block += `\n- Tactical approach (act immediately → delay → redirect → test others first)`;
              block += `\n- Interaction target (address different participants, shift group → individual → indirect)`;
              block += `\n- Timing (interrupt → wait → speak last → speak early)`;
              block += `\nVariation must NOT break identity vector — a precise character stays precise but may express it differently.`;
              block += `\nAvoid identical sentence structures, recurring catchphrases, or identical decision patterns across similar situations.`;
              block += `\nVariation should feel natural and situational — adaptive behavior, not inconsistency.`;
          }

          // ── THIRST BEHAVIORAL ENGINE: phase + favorite + near-choice + climax ──
          if (flavorEntry.val === 'thirst') {
            // State initialization
            state.thirstPhase = state.thirstPhase || 'distribution';
            state.thirstAttentionMap = state.thirstAttentionMap || {};
            state.thirstFavorite = state.thirstFavorite || null;
            state.thirstNearChoiceLevel = state.thirstNearChoiceLevel || 0;
            state.thirstTensionMap = state.thirstTensionMap || {};
            state.thirstChoiceMade = state.thirstChoiceMade || false;
            var _tTurn = state.turnCount || 0;

            // Phase transitions
            if (state.thirstPhase === 'distribution' && _tTurn >= 3) {
              state.thirstPhase = 'emergence';
            }
            // Detect emerging favorite from attention map
            var _maxAttn = 0; var _favId = null;
            for (var _sk in state.thirstAttentionMap) {
              if (state.thirstAttentionMap[_sk] > _maxAttn) { _maxAttn = state.thirstAttentionMap[_sk]; _favId = _sk; }
            }
            // Favorite validation: must emerge from contrast (2+ subjects engaged, clear margin)
            var _engagedCount = Object.keys(state.thirstAttentionMap).filter(function(k) { return state.thirstAttentionMap[k] > 0; }).length;
            var _secondMax = 0;
            for (var _sk2 in state.thirstAttentionMap) { if (_sk2 !== _favId && state.thirstAttentionMap[_sk2] > _secondMax) _secondMax = state.thirstAttentionMap[_sk2]; }
            if (_favId && _maxAttn >= 3 && _engagedCount >= 2 && (_maxAttn - _secondMax) >= 2) state.thirstFavorite = _favId;
            if (state.thirstPhase === 'emergence' && state.thirstFavorite) {
              state.thirstPhase = 'crisis';
            }

            // Near-choice: fires every 2-3 scenes in emergence/crisis
            if (state.thirstPhase !== 'distribution' && _tTurn >= 4) {
              state.thirstNearChoiceLevel = Math.min((state.thirstNearChoiceLevel || 0) + 1, 3);
            }

            // Climax gate: near-choice level 2+ and clear favorite
            var _thirstClimaxAvailable = state.thirstNearChoiceLevel >= 2 && state.thirstFavorite && !state.thirstChoiceMade;

            // Phase directive
            var _thirstPhaseDir = '';
            if (state.thirstPhase === 'distribution') {
              _thirstPhaseDir = '\nTHIRST PHASE: DISTRIBUTION. Maintain rotation across participants. No single subject dominates attention. Power balance must remain distributed.';
            } else if (state.thirstPhase === 'emergence') {
              _thirstPhaseDir = '\nTHIRST PHASE: EMERGENCE. One subject (' + (state.thirstFavorite || 'emerging') + ') begins receiving more attention. Other participants react with intent \u2014 compete, withdraw, redirect, or form temporary alignments. Reactions must vary and evolve.' +
                '\nFAVORITE RESISTANCE: The favored subject must not fully reciprocate immediately. They may hesitate, deflect, or complicate attention. Favoring increases difficulty, not reduces it.';
            } else {
              _thirstPhaseDir = '\nTHIRST PHASE: CRISIS. Favoring ' + (state.thirstFavorite || 'one subject') + ' creates instability. Each scene must increase the cost of exclusivity \u2014 social, structural, or emotional consequences. Options narrow or become more difficult.' +
                '\nPARTICIPANT STRATEGY: Non-favored subjects act with intent. They compete, redirect, or form alignments against the favorite. No passive observers.' +
                '\nFAVORITE RESISTANCE: The favored subject complicates access. Favoring increases difficulty.';
            }
            block += _thirstPhaseDir;

            // Near-choice tension
            if (state.thirstNearChoiceLevel > 0 && state.thirstPhase !== 'distribution') {
              var _ncIntensity = state.thirstNearChoiceLevel <= 1 ? 'subtle preference visible' : (state.thirstNearChoiceLevel === 2 ? 'noticeable shift in attention' : 'near-commitment, other participants aware');
              block += '\nNEAR-CHOICE[' + state.thirstNearChoiceLevel + ']: The player almost chose one subject \u2014 ' + _ncIntensity + '. This must feel closer than before but must not resolve exclusivity.';
            }

            // Multi-actor residue
            block += '\nRESIDUE: Participants remember shifts in attention. Behavior must reflect accumulated imbalance. No reset to neutral group dynamic.';
            block += '\nMULTI-ACTOR INVARIANT: Even when a favorite emerges, other participants must remain active and influential. No scene may fully isolate the favorite from the group dynamic. Exclusivity increases pressure, not removes others.';

            // Climax gate
            if (_thirstClimaxAvailable) {
              block += '\nCLIMAX AVAILABLE: A true choice is possible. Selecting one subject permanently alters the system. Other participants must react to this shift. Consequences must be irreversible.';
            }
            if (state.thirstChoiceMade) {
              block += '\nCHOICE MADE: The system is permanently altered. Rotation is disrupted. Consequences of exclusivity are active and escalating.';
            }

            console.log('[THIRST] phase=' + state.thirstPhase + ' favorite=' + (state.thirstFavorite || 'none') + ' nearChoice=' + state.thirstNearChoiceLevel + ' climax=' + _thirstClimaxAvailable);

            // ── THIRST COUPLE MODE: co-rulers → fracture → rivals ──
            if (state.mode === 'couple') {
              if (!state.thirstCouple) {
                state.thirstCouple = {
                  mode: 'co_rulers',
                  jealousy: { p1: 0, p2: 0 },
                  imbalanceScore: 0,
                  fractureProgress: 0
                };
              }
              var _tc = state.thirstCouple;

              // Imbalance detection
              var _imbalLabel = _tc.imbalanceScore < 20 ? 'stable' : (_tc.imbalanceScore < 40 ? 'strain' : 'fracture risk');

              // Mode transitions
              if (_tc.mode === 'co_rulers' && _tc.fractureProgress > 50) {
                _tc.mode = 'fractured';
                console.log('[THIRST:COUPLE] co_rulers \u2192 fractured');
              }
              if (_tc.mode === 'fractured' && _tc.fractureProgress > 80) {
                _tc.mode = 'rivals';
                console.log('[THIRST:COUPLE] fractured \u2192 rivals');
              }

              // Fracture increment: jealousy + imbalance co-occurrence
              if ((_tc.jealousy.p1 > 40 || _tc.jealousy.p2 > 40) && _tc.imbalanceScore > 20) {
                _tc.fractureProgress = Math.min(100, _tc.fractureProgress + 5);
              }

              // Mode directives
              var _tcDir = '';
              if (_tc.mode === 'co_rulers') {
                _tcDir = '\nTHIRST COUPLE: CO-RULERS. Both players control access together. Intimacy = power transfer (each engagement shifts influence). Jealousy expresses unevenly \u2014 as restraint, distance, control, or sudden intensity. Every ST3 must change power distribution.';
              } else if (_tc.mode === 'fractured') {
                _tcDir = '\nTHIRST COUPLE: FRACTURED. Unity no longer assumed. Decisions carry subtext. Players act with partial independence. Warlords start choosing sides. Power no longer feels shared \u2014 one leads, one reacts.';
              } else {
                _tcDir = '\nTHIRST COUPLE: RIVALS. They are no longer managing power together. They are shaping separate futures. Rotation breaks into competing bids. Scenes include undercutting, strategic denial, alliance locking. Even in rivalry, interactions must produce shifts in power, alignment, or consequence \u2014 conflict must not stall progression.';
              }
              _tcDir += '\nImbalance: ' + _imbalLabel + '. Jealousy: P1=' + _tc.jealousy.p1 + ' P2=' + _tc.jealousy.p2 + '. Fracture: ' + _tc.fractureProgress + '%.';
              _tcDir += '\nNever force betrayal \u2014 create conditions where it feels inevitable. No neutral ST3 outcomes. Every scene must shift power, relationship, or resource stability.';
              block += _tcDir;

              console.log('[THIRST:COUPLE] mode=' + _tc.mode + ' imbalance=' + _imbalLabel + ' jealousy=P1:' + _tc.jealousy.p1 + '/P2:' + _tc.jealousy.p2 + ' fracture=' + _tc.fractureProgress + '%');
            }
          }

          // 4th Person material observer hints
          if (state.povMode === 'environment4th' && DYSTOPIA_4TH_PERSON_HINTS[flavorEntry.val]) {
              block += `\n\nMATERIAL OBSERVER — FLAVOR INTERACTION:`;
              block += `\nMaterial observers should interpret the systemic pressure through physical evidence.`;
              block += `\nFlavor-specific observer examples: ${DYSTOPIA_4TH_PERSON_HINTS[flavorEntry.val]}`;
          }
      }

      if (customText) {
          block += `\n\nCustom Setting: ${customText}`;
          block += `\nTreat as location, institution, or thematic pressure. Ground the dystopia in this specific context.`;
      }

      // A/B logging: compare old builder output vs new registry output
      if (typeof composeWorld === 'function' && resolvedFlavors && resolvedFlavors.length) {
        try {
          var composed = composeWorld('Dystopia', resolvedFlavors, state);
          var newBlock = formatComposedWorld(composed);
          function quickDiffScore(a, b) { return Math.abs(a.length - b.length); }
          console.group('[DYSTOPIA A/B TEST]');
          console.log('OLD BLOCK length:', block.length, 'tokens (~' + Math.round(block.length / 4) + ')');
          console.log('NEW BLOCK length:', newBlock.length, 'tokens (~' + Math.round(newBlock.length / 4) + ')');
          console.log('DIFF SCORE:', quickDiffScore(block, newBlock));
          console.log('OLD BLOCK preview:', block.slice(0, 300));
          console.log('NEW BLOCK preview:', newBlock.slice(0, 300));
          console.groupEnd();
        } catch (_abErr) {
          console.warn('[DYSTOPIA A/B] Error:', _abErr.message);
        }
      }

      return block;
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // POST-APOCALYPTIC WORLD BLOCK — Canonical injection for PostApocalyptic stories.
  // Survival strain, not ideology. The world has already broken. Romance fights
  // damage, not systems. Each flavor = single dominant survival pressure.
  // ═══════════════════════════════════════════════════════════════════════════

  const POSTAPOC_FLAVOR_LABELS = {
      ashfall: 'Ashfall',
      year_zero: 'Year 0',
      dystimulation: 'Dystimulation',
      predation: 'Predation',
      hunger: 'Hunger'
  };

  const POSTAPOC_FLAVOR_EFFECTS = {
      ashfall: 'Environmental hostility. The world burns between you. Toxic air, radiation, extreme heat, ash storms, contaminated environments. Touch may carry lethal risk. Love requires proximity. The world punishes proximity. Physical closeness itself incurs danger.',
      year_zero: 'Psychological rupture. Love is the aftermath. The catastrophe happened recently. Survivors shaped by survivor\'s guilt, trauma bonding, before/after identity rupture, shock and instability. Relationships emerge from wreckage. Love is unstable because everyone is still breaking.',
      dystimulation: 'Trauma-blunted reward systems. You must risk everything to feel anything. Emotional reward systems dulled by trauma. Desire exists but buried beneath numbness. Intimacy may require adrenaline, danger, emotional surrender, extreme novelty. Connection is rare — when it appears, it can be explosive.',
      predation: 'Absence of institutional protection. Love makes you prey. No safety net. Trust can be exploited. Softness attracts violence. Communities may weaponize vulnerability. To love someone is to expose them — and yourself. Attachment creates leverage and targets.',
      hunger: 'Chronic scarcity. Love competes with survival. Essential resources scarce: food, water, medicine, fuel. Someone may have to go without. Generosity threatens survival. Attachment forces impossible decisions. Caring for one person may doom another.'
  };

  const POSTAPOC_DISTINCTIONS = `
CRITICAL DISTINCTIONS (prevent flavor drift):
• Ashfall ≠ Hunger — environment pressure ≠ resource scarcity
• Dystimulation ≠ Dysconsent — neurochemical trauma ≠ regulatory control
• Predation ≠ Small Town — lethal exposure ≠ social scrutiny
• Year 0 ≠ Erasure — psychological trauma ≠ identity mutation`;

  function buildPostApocWorldBlock(resolvedFlavors) {
      const customText = state.worldCustomTexts?.['PostApocalyptic'] || '';

      let block = `
WORLD: Post-Apocalyptic
"a broken world where love fights damage, not systems"

Post-Apocalyptic is not dystopia. It is not ideology. It is not governance. It is survival strain.
The world has already broken. Romance fights damage, not systems.

REALITY MODEL:
• Civilization has fractured or collapsed. Infrastructure is unreliable. Communities are fragile.
• The body and environment are under constant pressure — visceral, immediate, embodied
• No abstract commentary, no satire, no theoretical framing — only consequence
• If a world appears stable or systemically organized, it is no longer Post-Apocalyptic
• Remaining societies are fragmented, improvised, unstable. Trust is scarce. Attachment introduces vulnerability.

CORE TENSION: survival vs attachment
Love demands loyalty. Survival demands compromise.`;

      // Flavor injection (exactly one per PostApoc story)
      const flavorEntry = (resolvedFlavors || [])
          .find(f => POSTAPOC_FLAVOR_LABELS[f.val]);
      if (flavorEntry) {
          const label = POSTAPOC_FLAVOR_LABELS[flavorEntry.val];
          const effect = POSTAPOC_FLAVOR_EFFECTS[flavorEntry.val] || '';
          block += `\n\nSurvival Pressure: ${label}`;
          if (effect) block += `\nPressure Effect: ${effect}`;
      }

      block += POSTAPOC_DISTINCTIONS;

      block += `

THEMATIC IDENTITY:
Post-Apocalyptic stories are physical, raw, scarred, intimate, survival-driven.
The world is broken. Love persists anyway. But every attachment carries risk.`;

      if (customText) {
          block += `\n\nCustom Setting: ${customText}`;
          block += `\nTreat as location, catastrophe type, or survival context. Ground the post-apocalyptic world in this specific setting.`;
      }

      return block;
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // WORLD SEPARATION CONTRACT — Prevents world-type drift during generation.
  // Each world has a distinct pressure model. Flavors add pressure within a
  // world but never change the world type. Per-world forbidden drift lists.
  // ═══════════════════════════════════════════════════════════════════════════

  const WORLD_FORBIDDEN_DRIFT = {
      Fantasy: 'scientific explanations replacing magic, corporate power structures dominating conflict, dystopian ideological control, modern institutional realism',
      SciFi: 'magic systems, mystical bloodlines, supernatural fate mechanics, dystopian ideological governance',
      Dystopia: 'collapsed civilization, wilderness survival focus, speculative alien science, fantasy magic',
      PostApocalyptic: 'stable governing systems, ideological social structures, advanced speculative technology, magical cosmology',
      Modern: 'systemic authoritarian control, advanced speculative technology, magical cosmology, world-ending collapse',
      Historical: 'modern cultural attitudes, advanced technology, speculative science, magic unless explicitly alternate-history'
  };

  const WORLD_ROMANCE_PRESSURE = {
      Fantasy: 'love vs sacrifice',
      SciFi: 'love vs discovery',
      Dystopia: 'love vs system',
      PostApocalyptic: 'love vs survival',
      Modern: 'love vs society',
      Historical: 'love vs tradition'
  };

  function buildWorldSeparationContract(world) {
      if (!world) return '';
      const forbidden = WORLD_FORBIDDEN_DRIFT[world];
      const pressure = WORLD_ROMANCE_PRESSURE[world];
      if (!forbidden && !pressure) return '';

      let block = `

WORLD SEPARATION CONTRACT (MANDATORY):
This story operates inside one world: ${world}. Flavors add pressure within this world but do NOT change the world type.
If a scene begins drifting into another world's pressure model, correct it back to ${world}.`;
      if (pressure) block += `\nRomance Pressure Axis: ${pressure}.`;
      if (forbidden) block += `\nForbidden Drift: ${forbidden}.`;
      return block;
  }

  /**
   * Build world flavor directives for LLM system prompt.
   * Accepts resolved flavor array from resolveWorldFlavors().
   * Systemic → World Flavor + World Pressure; Contextual → World Context + Context Effect.
   * Max 4 flavor-related prompt lines. Never exposes classification labels.
   */
  // Famous Fate: user-directed IP/world generation. Emits a canon-faithful
  // directive (world, embodied character, period, story wish) injected into the
  // system prompt. Empty for non-Famous-Fate stories.
  function _buildFamousFateCanonDirective() {
    var ff = state.famousFate;
    if (!ff || !ff.enabled || state.fateMode !== 'famous_fate') return '';
    // Read the IMMUTABLE original text the reader typed (never the classifier's).
    var orig = ff.original || ff;
    var period = ff.period || (orig && orig.period) || 'canon';
    // Timeline placement + the canon RULE that applies to it. The two are kept
    // consistent so the prompt never says "honor canon" and "alternate timeline"
    // at once without clarifying how they interact.
    var placement = ({
      pre: 'BEFORE the canonical events (a prequel era).',
      canon: 'DURING the canonical timeline.',
      post: 'AFTER the canonical events (a sequel era).',
      alternate: 'an ALTERNATE timeline / what-if branching off canon.'
    })[period] || 'DURING the canonical timeline.';
    var canonRule = ({
      pre: 'CANON RULE (pre-canon): Stay consistent with established lore and with the KNOWN FUTURE — nothing here may contradict canonical later events unless the reader\'s request intentionally diverges. Honor geography, factions, technology/magic rules, and tone.',
      canon: 'CANON RULE (canon): Stay fully consistent with established continuity — geography, factions, timeline, technology/magic rules, characterization, and tone.',
      post: 'CANON RULE (post-canon): Treat all canonical events as having HAPPENED; continue naturally forward from them. Honor the established world\'s rules and tone; introduce new developments that follow plausibly from canon.',
      alternate: 'CANON RULE (alternate timeline): BEGIN grounded in canon (world rules, characters, tone), then FREELY DIVERGE after the branching point implied by the reader\'s request. Established world mechanics still hold unless the divergence explicitly changes them; canonical later events are NOT binding past the branch.'
    })[period] || 'CANON RULE: Stay consistent with established continuity.';
    var lines = [];
    lines.push('\n=== FAMOUS FATE — USER-DIRECTED WORLD (canon permitted) ===');
    lines.push('The reader has explicitly asked to play inside a named world/fandom and embody a specific character. This is user-directed generation: render that world and its characters using the names as given. Do NOT sanitize the IP into a generic equivalent.');
    if (orig && orig.world) lines.push('- World / setting: ' + orig.world);
    if (orig && orig.embody) lines.push('- The reader embodies: ' + orig.embody + ' — write the protagonist AS this character (voice, history, abilities, relationships).');
    lines.push('- Timeline placement: ' + placement);
    if (orig && orig.storyWish) lines.push('- Desired story: ' + orig.storyWish + '.');
    lines.push('- ' + canonRule);
    lines.push('- NAME RESOLVER (world- & speaker-aware — RESOLVE address, never fixed-substitute): For the protagonist and any canonical cast, hold THREE identities in mind: (a) EMBODIED — what the reader typed when choosing who to play ("Old Man Logan"); (b) CANONICAL — the character\'s real names/aliases (Logan / James Howlett / Wolverine); (c) CURRENT SOCIAL — what THIS story\'s world actually knows them as, given the fiction already established. For every act of address or reference, resolve rather than substitute: "Given THIS world, THIS speaker, their RELATIONSHIP, and the identity the character is presenting here, what would they naturally call him in THIS moment?"');
    lines.push('- THE HOST WORLD\'S SOCIAL REALITY OVERRIDES THE SOURCE FRANCHISE\'S NAMING HABITS. In a crossover the host world governs. E.g. Wolverine dropped into a wizarding school where no one knows him → "Professor Logan" / "Mr. Logan" / "the new Defense professor" / "that strange wizard" until he earns a reputation; if he is openly known there as Wolverine → "Wolverine" from acquaintances, "Logan" from close friends; if he is undercover under an assumed name → others use that alias while his own interiority still thinks of himself as Logan. Same logic for Batman in a medieval realm, Sherlock in a sci-fi setting, etc.');
    lines.push('- WITHIN a given speaker/relationship, match canon\'s real usage: intimates/family use personal names (Alfred→"Bruce", MJ→"Peter", a friend→"Logan", certain speakers→"Anakin"); strangers/enemies/public/press use the alias or codename. For some characters the ALIAS *is* what nearly everyone naturally says (Batman, Superman, Wonder Woman, the Joker, Magneto, Mystique) — keep those even with intimates. The one thing to avoid outright is the fan/marketing/title LABEL no one says in dialogue (an "Old Man ___" framing, a media-title nickname): the reader may type it as the EMBODIED identity, but in-world people still address him the natural way.');
    lines.push('- NAMES CARRY STORY: a shift in how someone is addressed is a narrative TOOL, not noise. "Mr. Logan" → "Logan" can mark growing intimacy; switching to "Wolverine" mid-battle can mark respect or mythic stature; an enemy using his real/secret name can land as a threat. Let forms of address evolve with the relationship and the moment instead of pinning one fixed label per character. Get canonical given names, surnames, aliases, honorifics, and forms of address right for the whole cast — love interest and side characters included.');
    lines.push('- REAL-PERSON RULE: All characters in the story must be FICTIONAL. Do NOT depict real public figures (living or historical — celebrities, politicians, athletes, musicians, etc.) as characters. If the setting would historically involve real people, use fictional analogues instead. Real actors/creators the reader may have named are NOT characters in the story.');
    // ── ROMANCE & INTIMACY POLICY (Famous Fate is still Storybound) ──
    var rom = ff.romance || {};
    if (rom.noLoveInterest) {
      lines.push('--- NO LOVE INTEREST — PURE ADVENTURE (the reader opted out of romance) ---');
      lines.push('- The reader chose NO love interest. This is a pure adventure / gen-fiction story in this world: do NOT introduce a romance, a love interest, attraction, flirtation, seduction, courtship, or intimacy of any kind, and do NOT frame any character as a romantic prospect for the protagonist.');
      lines.push('- Storybound\'s relationship engine is OFF for this story. Organize it around the franchise\'s OWN non-romantic engines instead: adventure, mystery, danger, mission, quest, rivalry, camaraderie, wonder, and stakes — the plot a knowledgeable fan expects.');
      lines.push('- OPENING: keep Storybound\'s Hot-Crisis PACING and momentum, but the crisis is a PLOT / ADVENTURE crisis (a case, a threat, a quest, a mystery), NOT a romantic one. Plot-first, not romance-first.');
      lines.push('- Platonic bonds are welcome and encouraged — friendship, loyalty, mentorship, rivalry, found-family (Holmes & Watson; Harry, Ron & Hermione; Pooh & friends) — but keep every relationship strictly non-romantic and non-sexual.');
      lines.push('- This is a PRIVATE story for this reader only; it is never published publicly.');
      return lines.join('\n');
    }
    lines.push('--- ROMANCE & INTIMACY (still Storybound — romance-first, NOT a safe mode) ---');
    lines.push('- This is a full Storybound romance, not a watered-down one. The franchise supplies setting, conflict, lore, rules, and atmosphere; Storybound supplies the relationship engine — attraction, chemistry, emotional progression, intimacy, and romance pacing. Make them complement: do NOT let the romance erase the franchise, and do NOT let the franchise erase the romance.');
    lines.push('- OPENING: keep Storybound\'s architecture (Hot Crisis / Hot-and-Fast, Therefore/But, romance-first, plot-second), but INFER the kind of opening conflict a knowledgeable fan would immediately recognize as natural for THIS universe, and express Storybound\'s Hot Crisis through the franchise\'s OWN conflict vocabulary rather than a generic Storybound scenario. Do not reach for a template — find the conflict that genuinely fits this world. Do not replace Storybound\'s pacing; translate it.');
    if (rom.partnerMode === 'canonical') {
      lines.push('- LOVE INTEREST: the reader chose to romance an EXISTING character' + (rom.requestedPartner ? (' (' + rom.requestedPartner + ')') : '') + '. Run the normal romance engine with a clearly adult, non-familial canonical character (subject to the safeguards below).');
    } else {
      lines.push('- LOVE INTEREST: create an ORIGINAL love interest who genuinely belongs in this universe — native to the world, not a famous canonical figure, and unconstrained by decades of canon so they can fully participate in the relationship engine. This is preferred; do NOT default to canonical shipping.');
    }
    // FOUR ROMANCE ENVELOPES (protagonist LIFE STAGE × universe CONTENT PROFILE).
    // Life stage and relationship STYLE are separate concepts. Explicit requires
    // adult + mature; the other three are romantic but non-explicit, each with a
    // distinct emotional register.
    if (rom.envelope === 'child') {
      lines.push('- ROMANCE ENVELOPE = CHILD (HARD): the embodied protagonist is a young child. NO romance and NO sexual content of any kind. Write friendship, wonder, adventure, family warmth, and emotional bonds appropriate to a child. Never romanticize or sexualize the protagonist or anyone around them.');
    } else if (rom.envelope === 'adult') {
      lines.push('- ROMANCE ENVELOPE = ADULT (adult protagonist + mature universe): full Storybound romance — flirting, attraction, intimacy, and explicit literary scenes — subject to Storybound\'s normal content policies.');
    } else if (rom.envelope === 'allages_adult') {
      lines.push('- ROMANCE ENVELOPE = ALL-AGES ADULT (adult/established characters in a family / all-ages universe): write a FULLY romantic ADULT relationship in the wholesome register native to this world — affection, courtship, devotion, partnership, domesticity, longing, kisses, comedy, and established-couple warmth. These are mature partners (e.g. long-established couples), NOT teenagers — do NOT write teenage first-love awkwardness. DO NOT write explicit sexual content; fade or redirect if a scene tips toward sex. The restriction is the UNIVERSE\'S all-ages tone, not the characters\' ages.');
    } else {
      lines.push('- ROMANCE ENVELOPE = TEEN / COMING-OF-AGE (protagonist is a teenager, school-age, or of unconfirmed adult status): the romance engine STAYS ALIVE but the ceiling is coming-of-age, NOT adult. ALLOW: crushes, butterflies, jealousy, first love, awkward flirting, hand-holding, hugs, kisses, dating, emotional intimacy. DO NOT write explicit sexual content; fade or redirect if a scene tips toward sex. Match the tone of earnest coming-of-age fiction.');
    }
    lines.push('- PROHIBITED ROMANCE (HARD, all envelopes): never render explicit intimacy for parent/child, guardian/ward, mentor/protégé, teacher/student, adoptive-family, sibling, or otherwise clearly familial relationships. Do NOT reinterpret such a bond as romantic or rewrite it into something explicit — keep it non-romantic.');
    lines.push('- This is a PRIVATE story for this reader only; it is never published publicly.');
    return lines.join('\n');
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // FAMOUS FATE — CHARACTER CONTRACT (2026-06-28)
  // A durable, franchise-agnostic abstraction that turns latent canon knowledge
  // into an explicit contract, so scenes can't forget powers, give a character a
  // mundane injury a power would prevent, break a world-law, OR drift the
  // character's VOICE (Wolverine giving a diplomatic speech, Batman blurting his
  // feelings). Four independent sections:
  //   1. FACTS         — powers (w/ implication+limit), aliases, history
  //   2. BEHAVIOR      — voice + invariants (usually / rarely / never)
  //   3. SOCIAL REALITY— who calls them what, what this world knows them as,
  //                      current presented identity (crossover-aware)
  //   4. WORLD CONTRACT— rule-systems + interactions, hard laws, ASSUMED TRUTHS
  //                      (what each society believes, public history, current year)
  // Generated ONCE at setup in TWO PHASES (extract objective facts → synthesize
  // the writing contract; extraction is easier than inference, so they're split).
  // Stored at state.ffContract (plain JSON → rides the snapshot like Body Bibles),
  // injected into every scene prompt, and enforced per scene by an author-
  // independent validator that surgically repairs violations. FF-only.
  // ═══════════════════════════════════════════════════════════════════════════

  // Shared Grok JSON helper (one fetch + tolerant parse). reasoning:true → the
  // thinking model (recall/judgment); false → non-reasoning (cheaper checks).
  async function _ffGrokJSON(sys, usr, opts) {
    opts = opts || {};
    var model = opts.reasoning ? 'grok-4-1-fast-reasoning' : 'grok-4-1-fast-non-reasoning';
    try {
      var res = await fetch('/api/proxy', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ messages: [{ role: 'system', content: sys }, { role: 'user', content: usr }], role: 'SPECIALIST_RENDERER', preferredModel: model, temperature: (opts.temperature == null ? 0.2 : opts.temperature), max_tokens: opts.maxTokens || 2000, convId: opts.conv || 'sb-ff-contract' })
      });
      if (!res.ok) { try { console.warn('[FF-CONTRACT] ' + (opts.label || '') + ' HTTP ' + res.status); } catch (_) {} return null; }
      var data = await res.json();
      try { if (typeof _recordProxyTextCost === 'function') _recordProxyTextCost(data, model, opts.costCat || 'setup'); } catch (_) {}
      var rawc = (data && data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content) || (data && data.content) || '';
      rawc = String(rawc || '').replace(/^\s*```[a-z]*\s*/i, '').replace(/\s*```\s*$/i, '').trim();
      try { return JSON.parse(rawc); }
      catch (_e1) { try { var s = rawc.indexOf('{'), e = rawc.lastIndexOf('}'); if (s !== -1 && e !== -1) return JSON.parse(rawc.slice(s, e + 1).replace(/,\s*([}\]])/g, '$1')); } catch (_e2) {} }
      return null;
    } catch (_eF) { try { console.warn('[FF-CONTRACT] ' + (opts.label || '') + ' threw:', _eF && _eF.message); } catch (__) {} return null; }
  }

  // ── SHARED CANON CACHE (Supabase via /api/famous-fate-canon) ──
  // Cross-story reuse: a character/world/relationship generated once for a
  // universe is reused until edited, so "Professor X" isn't reinvented every
  // story. All failure-tolerant — a cache miss/error just means we generate.
  function _ffCanonNormKey(s) { return String(s || '').trim().toLowerCase().replace(/\s+/g, ' ').slice(0, 160); }
  function _ffUniverseKey() { try { var o = (state.famousFate && (state.famousFate.original || state.famousFate)) || {}; return _ffCanonNormKey(o.world || ''); } catch (_) { return ''; } }
  // DEDICATED per-IP POOLS generation (Roman 2026-06-30 refactor): one focused Grok call that
  // returns the 5 per-IP pools, so they no longer bloat (and truncate) the Phase-1 facts call.
  // Cached per-(universe,character); see the apply block in _generateFamousFateContract.
  async function _ffGeneratePools(ctx, charName, worldName, crossover) {
    try {
      var nm = String(charName || 'this character');
      // CROSSOVER (Roman 2026-07-09): a buried conditional "CROSSOVER RULE" in the bullets was ignored
      // (Logan-in-HP produced Weapon-X arcs). Prepend a HARD override that names the host world + forbids
      // the character's home-franchise threats, seeded with the real worldCanon factions/enemies/places.
      var _cxHdr = '';
      if (crossover && crossover.worldCanon) {
        var _cxwc = crossover.worldCanon || {};
        _cxHdr = 'CROSSOVER OVERRIDE (HARD — this GOVERNS every pool below and OVERRIDES each "typical of this canon" instruction): ' + nm + ' is an OUTSIDER embodied inside the world of "' + (_cxwc.source || worldName) + '". The HOST WORLD owns ALL threats, enemies, reversals, arcs, and settings. Draw crisisArchetypes, cliffhangerArchetypes, and worldArcs ENTIRELY from "' + (_cxwc.source || worldName) + '"\'s OWN canon — its factions=' + JSON.stringify(_cxwc.factions || []) + ', antagonistForces=' + JSON.stringify(_cxwc.antagonistForces || []) + ', places=' + JSON.stringify(_cxwc.namedPlaces || []) + ', rules=' + JSON.stringify(_cxwc.worldRules || '') + '. ' + nm + ' brings ONLY their own powers/body/wound to face those HOST-WORLD threats. FORBIDDEN: never use ' + nm + '\'s home-franchise villains, factions, programs, or events (Logan in Harry Potter → Death Eaters / Dementors / dark-arts curses / rogue Aurors, NEVER Sabretooth / Weapon X / Sentinels / Department H). ONLY canonWounds may stay the character\'s own (their personal aches travel with them); everything else is the host world\'s.\n\n';
      }
      var sys = _cxHdr + 'You are a canon story-pool author for an interactive romance set in an established fictional world. For the embodied canon character ' + nm + (worldName ? ' in ' + worldName : '') + ', generate FIVE per-IP story pools, each drawn from THIS character\'s REAL canon (NOT generic romance/Storybound defaults). Output ONLY one JSON object in the given shape — no prose, no fences.\n'
        + '• crisisArchetypes: 8-12 CRISES TYPICAL OF THIS CANON — dangers/conflicts THIS character + world actually face, unmistakably this IP. Span HOT (in-motion attack/ambush/hunt/raid/mission-gone-wrong/abduction) and COLD (a buried secret resurfacing, a reckoning arriving, a quiet betrayal). NOT generic corporate/board/SEC/severance/"scandal breaking" unless canon-native. (X-Men bar: a Sentinel deployment; a mutant abducted by Weapon X; a Hellfire Club power-play; the Morlocks under attack; Sabretooth resurfacing to hunt.) CROSSOVER RULE: if the character\'s home canon differs from the host world/setting, the HOST WORLD governs the threats + setting and the SOURCE FRANCHISE governs the character — native-to-host crises this character uniquely faces (Wolverine at Hogwarts → a Death Eater raid his claws suit, not Sentinels). Each: { premise, temp:"hot"|"cold", scale:"personal"|"team"|"world", enemy }.\n'
        + '• cliffhangerArchetypes: 8-12 mid/late-story REVERSALS/BOMBSHELLS typical of THIS canon (return-from-the-dead, clone/doppelganger, hidden-kin reveal, resurrected enemy, betrayal/identity unmasking, buried-memory detonation). NOT generic Storybound dooms (a terminal/cancer diagnosis, arranged-marriage debt, witness-protection identity, generic blackmail) unless canon-native. (Wolverine bar: his son DAKEN returns; an X-23/Albert-type CLONE surfaces; the Weapon X programming reactivates; a stolen-memory truth detonates; a trusted ally revealed an impostor.) Each: { twist, kind:"return"|"clone"|"kin"|"resurrection"|"betrayal"|"memory"|"unmasking", who }.\n'
        + '• worldArcs: 6-10 LARGER MULTI-ISSUE pressures typical of this canon (a brewing war/faction conflict, a hunt unfolding over time, a conspiracy tightening, a rising enemy campaign, a reckoning building) — native, NOT generic PUBLIC_SCANDAL/POWER_REVERSAL/corporate arcs. CROSSOVER RULE: the HOST WORLD governs the arc. Each: { arc, kind:"war"|"hunt"|"conspiracy"|"uprising"|"reckoning"|"invasion", who }.\n'
        + '• titleSeeds: 6-10 evocative WORKING-TITLE fragments specific to this story\'s world + character — canon-flavored and atmospheric (e.g. for Wolverine: "The Weapon and the Storm", "Adamantium Lullaby", "Ghosts of the Program", "No Memory of Mercy"). NOT the generic "Fate"-template register ("Fate Walks Into the Room"). Each a 2-6 word title/fragment, no author byline.\n'
        + '• canonWounds: 3-6 of THIS character\'s DEFINING canon traumas / wounds — the REAL aches that define them (e.g. Wolverine: the Weapon X program + the adamantium forced onto his bones; memories stolen and falsified; the berserker rage he fears in himself; the lovers and people he failed to protect; Sabretooth\'s lifelong hunt). NOT generic secret-baby / estranged-relative / custody / corporate wounds.\n'
        + '• canonVow: ONLY populate `power` if the character canonically REFUSES to use a specific power/ability as a DEFINING, characterizing trait — a sworn abstention, not a mere limit or weakness (e.g. Old Man Logan has not popped his claws in ~50 years after the night he was tricked into killing the X-Men; Banner refusing to become the Hulk; Jean refusing the Phoenix). Most characters have NO such vow — leave `power` an EMPTY STRING and the others empty. Give the in-character `reason` and `heldFor` only when `power` is set.';
      var schema = '{ "crisisArchetypes":[{"premise":"","temp":"hot|cold","scale":"personal|team|world","enemy":""}], "cliffhangerArchetypes":[{"twist":"","kind":"return|clone|kin|resurrection|betrayal|memory|unmasking","who":""}], "worldArcs":[{"arc":"","kind":"war|hunt|conspiracy|uprising|reckoning|invasion","who":""}], "titleSeeds":["short 2-6 word title fragment"], "canonWounds":["a defining canon trauma/wound"], "canonVow":{"power":"the specific ability they have SWORN OFF / refuse to use (empty string if none)","reason":"the oath/trauma/cost behind the refusal","heldFor":"how long / since when, e.g. ~50 years"} }';
      var out = await _ffGrokJSON(sys, (ctx || '') + '\n\nGenerate the pools as EXACTLY this shape:\n' + schema, { reasoning: false, maxTokens: 2800, conv: 'sb-ff-pools', label: 'phase-pools', costCat: 'setup' });
      return (out && typeof out === 'object') ? out : null;
    } catch (_) { return null; }
  }

  // DEDICATED CANON-BEAT LEDGER generation (Roman 2026-06-30, v1) — the "canon memory" for
  // period=canon: an ordered list of the source work's MAJOR beats, so the story can follow canon
  // beat-by-beat while the player takes canon-equivalent actions, and branch to adaptive FF when
  // they veer. Generated in its OWN focused call (NOT the Phase-1 facts call — 8-20 rich beats would
  // truncate the character contract, same reason the pools were split out) and cached per-(universe,
  // source). Beat 1 MUST equal the canonOpening. Each beat carries the canon situation + the state it
  // requires + the player actions that count as staying-on-canon vs bending vs breaking canon.
  async function _ffGenerateCanonBeats(ctx, source, opening, storyline) {
    try {
      if (!source) return null;
      var _openLine = (opening && (opening.incitingBeat || opening.premise)) ? String(opening.incitingBeat || opening.premise) : '';
      var sys = 'You are a canon STORY-BEAT cartographer for an interactive romance that lets a reader play THROUGH a known source work while it stays faithful to canon. For the work "' + String(source) + '", output an ORDERED list of 8-20 MAJOR canon story beats — the load-bearing plot moments a knowledgeable fan would recognize as the spine of that work, from the opening to the climax. Output ONLY one JSON object {"beats":[...]} — no prose, no fences.\n'
        + '• BEAT 1 MUST BE the canonical OPENING scene ANCHORED TO THE EMBODIED PROTAGONIST (the "READER EMBODIES" character in the context above)' + (_openLine ? (' — which is: "' + _openLine + '"') : '') + ' — the scene where THAT character first meaningfully ENTERS the source. Do not invent a different beat 1, and do NOT use a framing device / narrator frame / prologue / cold-open the embodied character is not in (e.g. embody=Han Solo → beat 1 is the Mos Eisley cantina where Han appears, NOT the Tantive IV boarding he is not in).\n'
        + '• ANCHOR THE WHOLE SEQUENCE to the embodied character\'s path through the source. A canon event the EMBODIED character is NOT present for (a framing narrator, an off-screen opening battle, another character\'s solo scene) is NOT one of THEIR beats to witness — mark it momentum="world_parallel" (below) so the character intersects it or hears about it, rather than opening on / standing inside a scene they were never in.\n'
        + '• Beats are the SOURCE\'S OWN plot points in order (not generic romance beats). Skip filler; keep the ~8-20 that actually define the arc.\n'
        + '• act = which of the source\'s THREE ACTS this beat belongs to (1|2|3). ACT 1 = the SETUP through the inciting incident and the turn/decision that LAUNCHES the main journey — the Act-1→Act-2 boundary is the POINT OF NO RETURN that commits the protagonist to the central conflict (e.g. Old Man Logan: Act 1 = the homestead rent standoff, the deadline, the pressure, and Logan accepting the job/road that launches the journey — it ENDS before any midpoint loss; the family\'s murder and the revenge are ACT 3, NOT Act 1). ACT 2 = rising complications, the midpoint, escalating stakes. ACT 3 = the climax and resolution. Tag EVERY beat with its act, faithful to THIS source\'s structure. Most sources reach the Act-1→Act-2 turn within the first several beats.\n'
        + '\n═══ CAUSAL DEPENDENCY GRAPH (this is what the runtime actually tracks — author it with discipline) ═══\n'
        + '• Output a top-level "stateVariables" array: the SMALL set of variables LATER plot machinery depends on. Each has an intrinsic "kind" — one of THREE:\n'
        + '    STATE = a boolean WORLD FACT that can flip and GATES beats (family_alive, journey_started, rent_deadline_active, death_star_intact). If a beat depends on a STATE that becomes false, that beat is IMPOSSIBLE (the engine skips it, or pivots if the spine collapses).\n'
        + '    ROLE = a SUBSTITUTABLE POSITION a character occupies (guide, mentor, final_antagonist, love_interest, gatekeeper). A ROLE break does NOT block the beat — the engine fills it with a SUCCESSOR. ROLE variables ALSO carry: "unique" (false = a successor cleanly fills it → REPAIR; "maybe" = replaceable but it opens a power vacuum → FORK; true = this specific relationship IS the story, cannot be honestly replaced → PIVOT/history-rewritten), "preserve": [thematic/emotional/pressure/ideological roles a successor must inherit — NEVER identity/appearance/methods], "successors": [ordered ladder: existing lieutenant → rival → heir → faction leader → ambitious subordinate → ideological successor → (last resort) new emergent].\n'
        + '    EVENT = a HISTORICAL FACT, IMMUTABLE once it happens (family_murdered, bridge_destroyed, prophecy_revealed). Gates beats like STATE, but can only go false→true (it occurs), NEVER true→false (you cannot un-happen history).\n'
        + '  Each: { "id": snake_case, "text": one clause, "kind": "state|role|event", "initiallyTrue": bool, "confidence": 0..1, "lifespan": "transient|persistent|long_arc|whole_story", plus unique/preserve/successors for ROLE only }. HARD LIMITS: 3-6 per act, ≤15 total. A variable EXISTS ONLY IF a later beat consumes it. NEVER emit iconic-but-inert texture ("logan_wears_hat", "harry_wins_quidditch") — preserve CAUSES, not events. confidence = genuine canon machinery vs adaptation artifact (low → pruned). CLASSIFY CAREFULLY: a variable that GATES whether a beat can happen is STATE (or EVENT if it is a produced historical fact); ROLE is ONLY for a substitutable character/position. E.g. journey_started = STATE; the traveling companion = ROLE. successors MUST be CONCRETE candidates ordered by PRECEDENCE — list NAMED figures who already exist in this canon/world and could plausibly step into the function FIRST; fall back to an archetype only when no named candidate exists (so a repair honors the graph instead of inventing a stranger). final_antagonist: ROLE, unique "maybe", successors ["Baron Zemo (surviving lieutenant)","the Skull\'s chief enforcer","an heir/clone raised to the throne"].\n'
        + '  ★ THE DEPENDENCY TEST (CAUSAL ASSUMPTION, NOT BEAT ASSOCIATION — this is the #1 modeling error): a beat does NOT consume a variable merely because it MENTIONS it. For EVERY beat ask: "if this variable were ALREADY FALSE before this beat, would the story still naturally ARRIVE at this beat, and would this beat still make sense?" If NO → the beat DEPENDS ON it (list it in dependsOn), even if the beat never mentions it. Walk EVERY beat against EVERY long-lived variable. Worked example — Old Man Logan\'s vow (claws_sheathed, STATE, initiallyTrue true): b1 rent-collection ASSUMES he stays passive → depends; b2 deadline ASSUMES he stayed passive → depends; b3 Hawkeye recruits "the man who won\'t fight" → depends; b4 the journey ASSUMES he hasn\'t snapped → depends. The dependency only ENDS once he canonically breaks the vow. Result: claws_sheathed is consumed by b1-b4+ and lifespan long_arc — NOT consumed once. This same test catches every long-lived STATE: a hidden identity, an undercover mission, a false marriage, a secret heir, a disguise, an un-revealed prophecy, an active curse, a kept vow — all are ASSUMED by many beats though MENTIONED by one.\n'
        + '  lifespan (self-check for the audit): transient = 1-2 beats (a locked door); persistent = ~half the story (journey_started); long_arc = a whole act-range (the vow, a disguise); whole_story = nearly every beat (voldemort_alive, death_star_intact). Your dependsOn edges MUST match the lifespan you declare — a long_arc/whole_story variable consumed by only 1-2 beats is a FAILED dependency pass; go back and add the beats that ASSUME it.\n'
        + '• For each beat add "produces": [variable ids this beat makes TRUE] and "dependsOn": [ { "variable": id, "reason": why THIS beat needs it } ]. (The variable\'s kind lives on the variable, above — the edge is just variable+reason.)\n'
        + '• For each beat add "obligations": { "must": [the causal things this scene MUST establish — mirror produces/dependsOn], "should": [flavor the author may vary or drop: sarcasm, jokes, exact staging] }. Keep it tight.\n'
        + '• requiredState = the canon facts that must hold AT this beat for the story to still be "on canon" (booleans/short values a runtime cursor can check — e.g. {"loganStillAtFarm":true,"familyAlive":true,"clawsSheathed":true}). Include a sworn-power state (e.g. clawsSheathed / hulkContained) when the character has a canon abstention.\n'
        + '• canonEquivalentPlayerActions = things the player could DO/SAY here that KEEP the story on canon (what the canon character actually does or plausibly would). softDivergenceTriggers = actions that bend the beat but the canon arc can still recover. hardDivergenceTriggers = actions that BREAK this beat\'s canon (the story must go adaptive) — e.g. using a canonically-abstained power early, killing a character who lives, fleeing a confrontation the character faces.\n'
        + '• presentCharacters = the canon characters physically in that beat. setting = where it happens. nextCanonBeat = the beatIndex that follows (the last beat\'s nextCanonBeat = null).\n'
        + '• romanceMode = does THIS beat organize around romantic desire, or not? Decided by the BEAT, NEVER by whether a love interest is present. "desire_allowed" = the beat is ABOUT romantic desire / flirtation / courtship / longing / seduction / confession / intimacy / relationship tension. "desire_yields" = a love interest or spouse may be PRESENT, but the beat is danger / family pressure / violence / politics / grief / survival / betrayal / humiliation (e.g. Old Man Logan\'s homestead rent standoff — Maureen present but the beat is family-under-threat, not romance). "defer_to_intro" = romance has not entered this beat yet. When in doubt choose desire_yields (present is NOT the same as romantic). BEAT 1 must match the canonOpening\'s romance shape.\n'
        + '• momentum = "world_parallel" if this beat happens on its OWN (a person already en route, an event already scheduled, a faction already moving) whether or not the protagonist is present; "player_gated" if it happens ONLY when the protagonist is there and acts (e.g. the protagonist personally rescuing someone). MOST world beats are world_parallel — the world does not wait for the hero, and canon events keep their momentum even after the player veers off canon.\n'
        + '• For each world_parallel beat also give: triggerWhen = roughly when it comes due ("early" | "mid" | "late", or "after beat N"); outcomeIfAbsent = what happens to this beat if the protagonist is NOT there to change it (e.g. "the prisoner dies in the arena unsaved"; "the courier reaches the settlement and delivers the warning too late"); canIntersectPlayer = true if this event could TRAVEL to / sweep into wherever the protagonist currently is (a courier arriving, an army marching through, an ally on the road), false if it is fixed in place and the protagonist would have to GO to it (a prisoner in a distant arena).\n'
        + '• triggerWindow = a WHEN structure so a runtime clock fires this beat at the right time (not just next-in-line): { "kind": "immediate" | "next_scene" | "after_n_scenes" | "after_beat" | "parallel_clock", "minScene": <int, scenes AFTER the player leaves canon before this can fire; 0 if immediate>, "maxScene": <int, by which it MUST have happened, or null>, "afterBeat": <beatIndex it follows, or null>, "afterEvent": <a few words naming an earlier beat/outcome it waits on, or null> }. Use "immediate"/"next_scene" for things already in motion (a courier a day out), "after_n_scenes"/"parallel_clock" for slower world machinery. urgency = "high" | "medium" | "low" (how fast it presses once due). canWaitForPlayer = true if the event would realistically HOLD for the protagonist to arrive, false if it happens on schedule regardless (a scheduled execution does not wait).\n'
        + '• ALSO output a "canonRevealLedger" array (TWIST WITHHOLDING) — the story\'s MAJOR REVEALS that the protagonist/viewer is NOT allowed to know until a specific later beat, so the engine can conceal them beforehand. MOST stories have NO twist → return an EMPTY array []. Include a reveal ONLY for a genuine late-story twist / hidden identity / secret betrayal / death / false memory / culprit. Each reveal: { "revealId": short slug, "revealText": one plain sentence stating the true reveal, "revealBeatIndex": the 1-based beatIndex at which the reveal LANDS in canon (NUMERIC), "revealType": "identity_twist|betrayal|death|false_memory|hidden_relationship|culprit_reveal|other", "forbiddenBeforeBeat": [the EXPLICIT reveal words/phrases/concepts that must NEVER appear before that beat], "allowedAliasesBeforeReveal": [the SAFE ways to refer to the concealed figure/fact before the reveal] }. EXAMPLE (Fight Club, embody=the Narrator): { "revealId":"tyler_identity", "revealText":"Tyler Durden is the Narrator\'s dissociated identity — they are the same person", "revealBeatIndex":<the beat where the Narrator realizes it>, "revealType":"identity_twist", "forbiddenBeforeBeat":["alter ego","split identity","dissociated identity","Tyler is you","same person","inside my own skull","shooting himself","imaginary friend","hallucination","talking to himself"], "allowedAliasesBeforeReveal":["Tyler Durden","the charismatic stranger","the man from the plane","the dangerous friend","the man who seemed to know what he wanted before he did"] }. CRITICAL: forbiddenBeforeBeat is EXPLICIT-REVEAL language ONLY — dread/ambiguity/foreshadowing are ALLOWED and must NOT be listed; ban only the words that STATE the twist.';
      var schema = '{ "stateVariables": [ { "id": "snake_case_id", "text": "one clause", "kind": "state|role|event", "lifespan": "transient|persistent|long_arc|whole_story", "initiallyTrue": true, "confidence": 0.9, "unique": "false|true|maybe (ROLE only)", "preserve": ["roles a successor inherits — ROLE only"], "successors": ["ordered successor ladder — ROLE only"] } ], "beats": [ { "beatIndex": 1, "act": 1, "canonBeat": "the canon plot moment in one clear sentence", "setting": "", "presentCharacters": ["canon names"], "romanceMode": "desire_allowed|desire_yields|defer_to_intro", "formOpportunity": "none|courtship|vow|confession|death|duel|reverie|chorus|prophecy|ritual|song|letter|monologue (the DRAMATIC TYPE of this beat, for the style layer to decide whether a strict-verse burst is apt; use \\"none\\" for ordinary action/transition/dialogue beats — MOST beats are \\"none\\")", "produces": ["variable ids this beat makes true"], "dependsOn": [ { "variable": "variable id", "reason": "why this beat needs it" } ], "obligations": { "must": ["causal things this scene must establish"], "should": ["flavor the author may vary or drop"] }, "canonEquivalentPlayerActions": ["stay-on-canon action"], "hardDivergenceTriggers": ["breaks canon → go adaptive"], "momentum": "world_parallel|player_gated", "triggerWhen": "early|mid|late|after beat N", "triggerWindow": { "kind": "immediate|next_scene|after_n_scenes|after_beat|parallel_clock", "minScene": 0, "maxScene": null, "afterBeat": null, "afterEvent": null }, "urgency": "medium", "canWaitForPlayer": true, "outcomeIfAbsent": "what happens to this beat if the protagonist is not there", "canIntersectPlayer": true, "nextCanonBeat": 2 } ], "canonRevealLedger": [ { "revealId": "", "revealText": "", "revealBeatIndex": 0, "revealType": "identity_twist|betrayal|death|false_memory|hidden_relationship|culprit_reveal|other", "forbiddenBeforeBeat": [], "allowedAliasesBeforeReveal": [] } ] }';
      var usr = (ctx || '') + '\nSOURCE WORK: ' + String(source)
        + (_openLine ? ('\nCANONICAL OPENING (beat 1): ' + _openLine) : '')
        + (storyline ? ('\nCANON STORYLINE (the arc these beats trace): ' + String(storyline)) : '')
        + '\n\nGenerate the ordered canon beat ledger as EXACTLY this shape:\n' + schema;
      // maxTokens raised 4200→7000 (Roman 2026-07-06): the state/role/event graph (per-variable successor
      // ladders + preserve arrays + obligations) makes the JSON bigger; 4200 truncated it → parse-fail → null.
      // maxTokens 7000→10000 (Roman 2026-07-08): adding the top-level canonScope object to this call's
      // output tipped a near-ceiling generation into TRUNCATED JSON → parse-fail → NULL beats (the whole
      // ledger died, and with it the [FF-SCOPE] measurement that lives in the beats-success block). The
      // extra headroom lets beats + causal graph + reveals + canonScope all land intact.
      var out = await _ffGrokJSON(sys, usr, { reasoning: false, maxTokens: 10000, conv: 'sb-ff-canonbeats', label: 'phase-canon-beats', costCat: 'setup' });
      var beats = (out && Array.isArray(out.beats)) ? out.beats : (Array.isArray(out) ? out : null);
      if (!(beats && beats.length)) { try { console.warn('[FF-CANON-LEDGER] beats-gen returned ' + (out == null ? 'NULL (parse/HTTP fail — likely truncated JSON)' : 'no beats[] (keys: ' + Object.keys(out).slice(0, 8).join(',') + ')')); } catch (_) {} return null; }
      // canonRevealLedger (TWIST WITHHOLDING) — travels alongside the beats; empty for non-twist stories.
      var reveals = (out && Array.isArray(out.canonRevealLedger)) ? out.canonRevealLedger : [];
      // ACT-ONE BOUNDARY (Roman 2026-07-06): the FF issue is scoped to Act 1 (see GOAL MANDATE), so
      // compute where Act 1 ends. Prefer the model's per-beat `act` tag; fall back to the last "early"
      // triggerWhen beat; else the first ~40% of beats (never past the arc, never 0).
      var actOneEndBeat = 0;
      try {
        beats.forEach(function (b) { if (b && Number(b.act) === 1) { var bi = Number(b.beatIndex) || 0; if (bi > actOneEndBeat) actOneEndBeat = bi; } });
        if (!actOneEndBeat) beats.forEach(function (b) { if (b && /early/i.test(String(b.triggerWhen || ''))) { var bi = Number(b.beatIndex) || 0; if (bi > actOneEndBeat) actOneEndBeat = bi; } });
        if (!actOneEndBeat) actOneEndBeat = Math.max(1, Math.ceil(beats.length * 0.4));
      } catch (_) { actOneEndBeat = Math.max(1, Math.ceil(beats.length * 0.4)); }
      var stateVariables = (out && Array.isArray(out.stateVariables)) ? out.stateVariables.filter(function (v) { return v && v.id; }) : [];
      return { beats: beats, reveals: reveals, actOneEndBeat: actOneEndBeat, stateVariables: stateVariables };
    } catch (_) { return null; }
  }

  // CANON SCOPE — a SEPARATE, focused extraction (Roman 2026-07-08). Was folded into the beat cartographer,
  // which coupled it to that call SUCCEEDING — a cartographer truncation/failure (beats-gen returned NULL)
  // then left canonSceneBudget UNSET on a fresh story (the `undefined` Roman saw). Split out so SCOPE
  // survives a beat failure, and so the cartographer output is smaller (less likely to truncate).
