      yoshi: 'male', kenji: 'male', daichi: 'male',
      // -or female English names (rule below misclassifies as male)
      eleanor: 'female', honor: 'female',
      // -e endings not covered by -ie/-y rule (rule lands them at
      // consonant default which is male)
      beatrice: 'female', chloe: 'female', zoe: 'female', zoey: 'female',
      phoebe: 'female', penelope: 'female', daphne: 'female',
      catherine: 'female', madeline: 'female', adelaide: 'female',
      // -ol/-el endings ambiguous; common female ones
