      // -e male short forms (avoid female misclassification if we ever
      // extend -e to default female)
      jake: 'male', luke: 'male', cole: 'male', blake: 'male', drake: 'male',
      george: 'male', wade: 'male', kobe: 'male', dwayne: 'male'
