    if (n in EDGE) return EDGE[n];

    // (2) Strong feminine suffixes — high-confidence female regardless
    // of the broader ending rules below.
    if (/(ella|anna|elia|aria|enna|onna|inna|illa|anda|inda|onda|essa|etta|ette|elle|ola|ana|ina|ela|ila|isa|esa|ica|ika|uka|yna|yra|elyn|lyn|leen|line|rine|teen|ette|elle)$/.test(n)) return 'female';

