  var _MICRO_VAGUE_TERMS = /\b(something|anything|things|stuff|whatever|some\s*thing)\b/i;
  var _MICRO_EMOTIONAL_FILLER = /\b(feeling\s+(?:something|anything|this|that|it)|just\s+a\s+feeling|a\s+feeling|the\s+feeling|emotions|feelings)\b/i;
