      totalStories: st.totalStories,
      sourceDistribution: st.sourceDistribution,
      sourcePct: pct(st.sourceDistribution),
      reveals: st.revealed,
      revealRatePct: st.totalStories ? +(100 * st.revealed / st.totalStories).toFixed(1) : 0,
      lockScene: lockSceneAgg('lockScene'),
      revealScene: lockSceneAgg('revealScene'),
