  var _MICRO_INTIMACY_AXIS  = /\b(take\s+hold|hold\s+yourself|surrender|let\s+go|hold\s+a\s+quiet|give\s+(?:in|up|over)|yield|dissolve|melt|sink|come\s+apart|stay\s+in\s+your\s+body|stay\s+with\s+yourself)\b/i;
  var _MICRO_INTENSITY_AXIS = /\b(let\s+it\s+(?:affect|land|register|in)|hold\s+(?:it\s+at\s+arm|it\s+together)|let\s+(?:yourself|it)\s+(?:be\s+)?pulled|keep\s+(?:your\s+)?distance|follow\s+the\s+feeling|resist\s+it|let\s+it\s+land|don'?t\s+let\s+it|focus\s+on\s+it|try\s+to\s+ignore)\b/i;
