  // ═══════════════════════════════════════════════════════════════════════════
  // CHARACTER REGISTRY — Golden Master Workflow
  // Separates style learning from character identity. When a golden master
  // exists for a character, the style pack is bypassed and the golden master
  // images are used as the sole reference (copy mode, not style learning).
  // ═══════════════════════════════════════════════════════════════════════════

  var CHARACTER_REGISTRY = {};

  // Character detection patterns — maps regex to registry key
  var _CHARACTER_DETECT_PATTERNS = [
    { pattern: /first\s*favored/i, id: 'first_favored' },
    { pattern: /part[- ]?favored/i, id: 'part_favored' },
    { pattern: /favorborn/i, id: 'favorborn' },
    { pattern: /winged\s*ones?/i, id: 'winged_one' }
  ];

  /**
   * Detect known characters in scene text.
   * Returns array of CHARACTER_REGISTRY entries that have golden masters.
   */
  function _detectGoldenMasterCharacters(sceneText) {
    if (!sceneText) return [];
    var lower = sceneText.toLowerCase();
    var found = [];
    for (var i = 0; i < _CHARACTER_DETECT_PATTERNS.length; i++) {
      var entry = _CHARACTER_DETECT_PATTERNS[i];
      if (entry.pattern.test(lower)) {
        var reg = CHARACTER_REGISTRY[entry.id];
        if (reg && reg.hasGoldenMaster && reg.goldenMasterImages && reg.goldenMasterImages.length > 0) {
          found.push({ id: entry.id, registry: reg });
        }
      }
    }
    return found;
  }

  /**
   * Generate a golden master image for a character.
   * Uses illustrator style pack ONLY — no character reference images.
   * Renders a neutral full-body reference pose.
   *
   * @param {string} characterId - Registry key (e.g. 'first_favored')
   * @param {string} characterDescription - Visual description of the character
   * @param {string} [artistKey] - Illustrator key (defaults to current gnArtist)
   */
  async function generateGoldenMaster(characterId, characterDescription, artistKey) {
    artistKey = artistKey || state.gnArtist || 'ender_bond';
    var style = RENDER_STYLE_SYSTEM[artistKey] || RENDER_STYLE_SYSTEM.ender_bond;

    if (!CHARACTER_REGISTRY[characterId]) {
      CHARACTER_REGISTRY[characterId] = {
        illustrator: artistKey,
        goldenMasterImages: [],
        hasGoldenMaster: false
      };
    }

    var prompt = style.style_anchor + '. ' +
      'STYLE ONLY — DO NOT COPY COMPOSITION from any reference. ' +
      _STYLE_OVERRIDE_SENTINEL + ' ' +
      'Draw the following character in a neutral, full-body pose against a simple background. ' +
      'Character faces slightly toward camera. Arms relaxed at sides. Even, flat lighting. ' +
      'Focus on character design accuracy — face, body proportions, clothing, distinctive features. ' +
      characterDescription;

    prompt = purgeBannedTokens(prompt);
    console.log('[GOLDEN-MASTER] Generating for "' + characterId + '" with artist "' + artistKey + '" (' + prompt.length + ' chars)');

    // Use style pack refs ONLY (no character refs, no scene refs)
    var result = await callGeminiImageGen(prompt, '1024x1024', 90000);
    if (result) {
      CHARACTER_REGISTRY[characterId].goldenMasterImages.push(result);
      CHARACTER_REGISTRY[characterId].illustrator = artistKey;
      // Mark as ready when at least 1 image exists
      CHARACTER_REGISTRY[characterId].hasGoldenMaster = CHARACTER_REGISTRY[characterId].goldenMasterImages.length > 0;
      console.log('[GOLDEN-MASTER] Saved for "' + characterId + '" (' + CHARACTER_REGISTRY[characterId].goldenMasterImages.length + ' images)');
    } else {
      console.warn('[GOLDEN-MASTER] Generation failed for "' + characterId + '"');
    }
    return result;
  }
  window.generateGoldenMaster = generateGoldenMaster;
  window.CHARACTER_REGISTRY = CHARACTER_REGISTRY;

  // ── Region Constraints — anti-trope guardrails for non-Thornwild Fatelands regions ──
  // Each region: function (role in world), antiDefault (what it must NOT become), pressure (persistent tension).
  // Applied via explicit region name OR semantic detection from scene keywords.
  var REGION_CONSTRAINTS = {
    lytharyn: {
      function: 'Institutional center for understanding, controlling, and extracting knowledge of magic and anomaly. Academies, magical study, structured learning, and ritual instruction are CORE to this region.',
      antiDefault: 'NOT a whimsical magic school. NOT a coming-of-age fantasy academy. NOT a cozy or safe learning environment. Lytharyn is austere, competitive, and increasingly inhuman. Knowledge is extracted, not gifted. Controlled, not freely shared. Tied to cost or sacrifice. Students are resources as much as learners. Advancement requires loss, risk, or trade.',
      pressure: 'Understanding something may change or damage the observer. Rituals demand real consequence. Every scholar is visibly sacrificed — faces lose softness, environments trend toward stark minimalism. The cost of clarity is loneliness. Beauty is the first thing consumed and the last thing mourned.'
    },
    vaelryn_reach: {
      function: 'Human monarchy claiming Favor-legitimacy. Ritual sovereign center. Ceremonial authority over continent — contested, not absolute.',
      antiDefault: 'NOT a generic medieval court. NOT a Renaissance faire. NOT Game of Thrones. Vaelryn is a mountain fortress of suppressed desire — passion expressed only through restraint. The court is vertical (carved into peaks, clouds below), not pastoral. Politics is lineage-bound, not feudal-mechanical.',
      pressure: 'Desire is the currency that cannot be spent. The most intense bonds are the most hidden. Public composure at all times — visible passion is political suicide.'
    },
    pulse_point: {
      function: 'Primary trade hub of the Fatelands. Controls exchange between Shackle Isles, inland river systems, and southern ocean routes. Organized around the Meridian Spire (tidal/celestial tracking). Circular harbor city with spiral shell layout, massive tidal clock harbor, bronze spire and lighthouse structures.',
      antiDefault: 'Pulse Point is dense, golden-hour-lit, wooden, and layered — curved harbor walls, gated water flow, ship masts packed tight. Technology is strictly seafaring / Renaissance-era. Trade is social and physical. Architecture: timber, bronze, rope, sailcloth, coral stone. Lighting: amber lanterns, low sun, warm atmospheric haze.',
      pressure: 'Defined by density + transaction + proximity. Wealth and poverty exist side-by-side with no buffer. Everything is for sale but nothing is clean. Deals are constant, overlapping, competitive. Space is limited — bodies, ships, and interests collide. Information, goods, and favors move faster than trust. Every interaction is closer than it should be, faster than it should be, more consequential than it appears. Pulse Point is not chaotic — it is compressed.'
    },
    the_shackle_isles: {
      function: 'A fluid network of power built on movement, trade, and exploitation. Piracy, smuggling, slavers, and cult activity are CORE to this region. Law D exploitation — transferred sacrifice. Four islands, four methods of extraction.',
      antiDefault: 'The Shackle Isles are storm-lashed, transactional, and predatory. Identity is currency, weapon, and commodity. Self-sacrifice is seen as weakness — taking from others is the norm. Alliances are temporary and conditional. Power shifts rapidly. Trust is a liability. Visual: dark seas, storm-battered docks, salt-crusted timber, tattered sails, low grey skies.',
      pressure: 'Freedom exists, but only for those who can enforce it. Everyone here has lost something involuntarily. Names taken, voices stripped, years extracted. Romance is the one form of self-sacrifice that still carries meaning — and that makes it dangerous.'
    },
    the_ashen_verge: {
      function: 'Militarized frontier containing the Fold — a captured fragment of the Devouring Eye. Maintained by House Dathros. Entry requires bonded pairs; solo incursion is taboo.',
      antiDefault: 'The Ashen Verge is an existential frontier — reality itself is unstable. Buildings exist in two states simultaneously. Roads fork into versions of themselves. This is containment of something that should not exist. Visual: ash-grey stone, distortion haze, overlapping architecture, reality seams.',
      pressure: 'Reality is not guaranteed. Proximity to the Fold erodes certainty of self. Sacrifice here is measured in years of life, pain tolerance, certainty of self. Scars = identity spent. The Fold does not kill — it resolves you into something you never chose.'
    }
  };

  // Semantic region detection — infer region from scene keywords when not explicitly named
  function _detectImpliedRegion(sceneText) {
    if (!sceneText) return null;
    var lower = sceneText.toLowerCase();
    // Explicit names first (highest priority)
    if (/lytharyn/i.test(lower)) return 'lytharyn';
    if (/vaelryn|high\s*court/i.test(lower)) return 'vaelryn_reach';
    if (/pulse\s*point/i.test(lower)) return 'pulse_point';
    if (/shackle\s*isle|blackmoor|cinderwake|quiet\s*chain|sanctum\s*reeve/i.test(lower)) return 'the_shackle_isles';
    if (/ashen\s*verge|the\s*fold|lost\s*dathros/i.test(lower)) return 'the_ashen_verge';
    // Semantic inference (lower priority)
    if (/\b(arcane.*scholar|arcane.*study|knowledge.*archive|crystal.*tower|mage.*academy)\b/i.test(lower)) return 'lytharyn';
    if (/\b(royal.*court|throne.*room|noble.*lineage|coronation|royal.*decree)\b/i.test(lower)) return 'vaelryn_reach';
    if (/\b(trade.*port|merchant.*dock|harbor.*market|maritime.*trade|cargo.*ship)\b/i.test(lower)) return 'pulse_point';
    if (/\b(prison.*island|chain.*archipelago|identity.*stolen|name.*taken|island.*fortress)\b/i.test(lower)) return 'the_shackle_isles';
    if (/\b(reality.*collapse|fold.*entry|bonded.*pair|containment.*zone|reality.*unstable)\b/i.test(lower)) return 'the_ashen_verge';
    return null;
  }

  // Build region constraint directive — inject into scene prompt when region is active
  function buildRegionConstraintDirective(sceneText) {
    var region = state.fantasyRegion || _detectImpliedRegion(sceneText);
    if (!region || !REGION_CONSTRAINTS[region]) return '';
    // Thornwild has its own system — skip
    if (region === 'the_thornwild') return '';
    var rc = REGION_CONSTRAINTS[region];
    return '\nREGION: ' + region.replace(/_/g, ' ').toUpperCase() + ': ' + rc.function + ' ' + rc.antiDefault + ' PERSISTENT TENSION: ' + rc.pressure + '\n';
  }

  // ── Scene Reference Images — keyword-matched location/concept references for Gemini ──
  // Each entry: { patterns: [regex], images: [paths], label: string }
  // Max 3 scene refs sent per render (+ 1 artist ref = 4 total) to stay under Gemini payload limits
  var SCENE_REFERENCE_IMAGES = [
    { patterns: [/vaelryn|high\s*court/i], images: ['/assets/Fatelands/Vaelerynsreach.png'], label: 'Vaelryn Reach' },
    { patterns: [/ashen\s*verge|war\s*marshal|the\s*fold|dathros/i], images: ['/assets/Fatelands/AshenVerge2.jpg?v=20260402'], label: 'Ashen Verge' },
    { patterns: [/lytharyn/i], images: ['/assets/Fatelands/Lytharyn.png'], label: 'Lytharyn' },
    { patterns: [/veilwood|first\s*favored/i], images: ['/assets/Fatelands/Veilwood-photo-wisps.png?v=20260402'], label: 'Veilwood canonical anchor' },
    { patterns: [/thornwild/i], images: ['/assets/Fatelands/Thornwild.png'], label: 'Thornwild' },
    { patterns: [/pulse\s*point/i], images: ['/assets/Fatelands/PulsePoint.png'], label: 'Pulse Point' },
    { patterns: [/gloamwater/i], images: ['/assets/Fatelands/GloamwaterBay.png'], label: 'Gloamwater Bay' },
    { patterns: [/underwild/i], images: ['/assets/Fatelands/Underwild.png?v=20260404'], label: 'Underwild' },
    { patterns: [/kwisheen|octo.?folk/i], images: ['/assets/Fatelands/Kwisheen_Pair_Anchor.jpg?v=20260404', '/assets/Fatelands/Kwisheen_Male_Anchor.jpg?v=20260404', '/assets/Fatelands/Kwisheen_Female_Anchor.jpg?v=20260404'], label: 'Kwisheen anatomy anchor' },
    { patterns: [/shackle\s*isles?|blackmoor|cinderwake|quiet\s*chain/i], images: ['/assets/Fatelands/ShackleIsles1.png'], label: 'Shackle Isles' },
    { patterns: [/fate.?s\s*favor|drowned\s*vein/i], images: ['/assets/Fatelands/FatesFavor.png'], label: "Fate's Favor" },
    { patterns: [/ascendant\s*run|syzygy/i], images: ['/assets/Fatelands/AscendantRun.png'], label: 'Ascendant Run' }
  ];
  var MAX_SCENE_REFS = 3;

  // ═══════════════════════════════════════════════════════════════════════════
