  // Flat pool for legacy compatibility
  var GN_INTIMACY_METAPHORS = [].concat(
    _METAPHOR_LIBRARY.subtle.map(function(e) { return e.text; }),
    _METAPHOR_LIBRARY.building.map(function(e) { return e.text; }),
    _METAPHOR_LIBRARY.rupture.map(function(e) { return e.text; }),
    _METAPHOR_LIBRARY.cosmicRupture.map(function(e) { return e.text; })
  );

  // Anti-repetition tracking
