      if (_filteredChars.indexOf('protagonist') === -1) _filteredChars.unshift('protagonist');
      var _strippedCount = (p0.characters_present || []).length - _filteredChars.length;
      if (_strippedCount > 0) {
        try { console.log('[STAGED:PHASE0] stripped ' + _strippedCount + ' LI-name token(s) from characters_present (was: ' + JSON.stringify(p0.characters_present) + ')'); } catch (_) {}
      }
