        if ((_rp.shot_style || '') === (_rc.shot_style || '')) _push('shot_style', _rp.shot_style || 'default');
        if ((_rp.proximity || '') === (_rc.proximity || '')) _push('proximity', _rp.proximity || 'unset');
        if (JSON.stringify((_rp.characters_present || []).slice().sort()) === JSON.stringify((_rc.characters_present || []).slice().sort())) _push('chars', JSON.stringify(_rp.characters_present || []));
