    var _phaseForBeatLookup = function(beatIdx) {
      var match = phases[0];
      for (var i = 0; i < phases.length; i++) {
        if (beatIdx >= phases[i].startBeat) match = phases[i];
        else break;
      }
      return match;
    };
    var _phaseCutCount = {};
    var _sceneCutCount = 0;
    var _scenePCCutCount = 0;
