  // Boredom score from input-length gradient. Two signals combined:
  //   1. Trailing-window mean drop — last 3 turns shorter than the
  //      preceding 3 by >= 30%
  //   2. Recent absolute shortness — last input under 20 chars
  // Returns 0..3. Calling code uses this to escalate the LLM prompt
  // (annotation) and trigger pivot-offer UI when score >= 2.
  function _scoreBoredomGradient(lengths) {
    if (!Array.isArray(lengths) || lengths.length < 3) return 0;
    var score = 0;
    var n = lengths.length;
    var last = lengths[n - 1];
    // Last input very short
    if (last <= 10) score += 2;
    else if (last <= 25) score += 1;
    // Trailing window mean drop
    if (n >= 6) {
      var recent3 = (lengths[n - 1] + lengths[n - 2] + lengths[n - 3]) / 3;
      var prior3  = (lengths[n - 4] + lengths[n - 5] + lengths[n - 6]) / 3;
      if (prior3 > 0 && (recent3 / prior3) <= 0.5) score += 2;
      else if (prior3 > 0 && (recent3 / prior3) <= 0.7) score += 1;
    } else if (n >= 4) {
      var rec2 = (lengths[n - 1] + lengths[n - 2]) / 2;
      var pri2 = (lengths[n - 3] + (lengths[n - 4] || lengths[n - 3])) / 2;
      if (pri2 > 0 && (rec2 / pri2) <= 0.5) score += 1;
    }
    return Math.min(3, score);
  }

  // Hedging detector — scans user input for hedge tokens that
  // indicate reticence. When matched, the LLM prompt's user-input
  // section gets a [user is hedging] annotation so the LI can
  // soften the response and offer agency back ("Then we slow
  // down. Tell me when").
  function _detectUserHedging(text) {
    if (!text || typeof text !== 'string') return false;
    var t = text.toLowerCase();
    // Phrase matches first (longer, more reliable)
    var phrases = [
      "i don't know", "i dont know", "i'm not sure", "im not sure",
      "not sure if", "i guess", "kind of", "kinda", "sort of",
      "i mean", "maybe i", "i think i", "i'm not really",
      "i don't really", "might want", "might be", "could be",
      "is it ok", "is that ok", "is this ok", "if that's", "if thats"
    ];
    for (var i = 0; i < phrases.length; i++) {
      if (t.indexOf(phrases[i]) !== -1) return true;
    }
    // Lone hedge words (only count if input is short — long inputs
    // with "maybe" once aren't necessarily hedging)
    if (t.length <= 60) {
      if (/\b(maybe|perhaps|possibly)\b/.test(t)) return true;
    }
    return false;
  }

  // ── FATE-CARD ENGAGEMENT CONSUME (2026-05-22) ──────────────────
  // Called at submit time (both literary + CG paths). Computes the
