    _applyOasTextMode(next);
    _updateOasTextModeBtn(next);
    try { console.log('[OAS:TEXT-MODE] ' + (next ? 'ON (mouth hidden, log expanded)' : 'OFF (visual mode)')); } catch (_) {}
