    var _qmInitIcon = _qmInitMuted ? _OAS_ICON_SPEAKER_MUTED : _OAS_ICON_SPEAKER;
    var _qmInitTitle = _qmInitMuted ? 'Audio muted — tap to unmute' : 'Mute audio (heartbeat + ambient)';
