  var _OAS_EXPLICIT_VOCAB_RX = /\b(cock|dick|pussy|cunt|fuck|fucking|fucked|cum|cumming|tits|nipples?|clit|suck|sucking|lick|licking|ride|riding|orgasm|deepthroat|swallow)\b/i;

