    var stance = String(s._intensityStance || '').toLowerCase();
    var cg = s.chargeGravity || { avoidance: 0, dwell: 0 };
    var dwellLead = (cg.dwell || 0) - (cg.avoidance || 0);
    var explicitRecent = (s._oasRecentExplicitTurns || []).length;
    var tone = String((s.picks && s.picks.tone) || '').toLowerCase();
    var inToneSuppression = (tone === 'wry' || tone === 'wryconfession' || tone === 'wry confessional' || tone === 'comedic' || tone === 'comedy');

