    if (stance === 'away' && dwellLead <= -4) {
      if (prior !== 'reserved') {
        try { console.log('[OAS:REGISTER-MODE] ' + prior + ' → reserved (stance=away, dwellLead=' + dwellLead + ')'); } catch (_) {}
        // Axis-payoff stamp: freshly chose the cleaner register → the directive rewards it next beat
        // (LI reads the restraint as intriguing, works harder), never shaming the reader as delicate.
        try { s._oasRegisterModeStamp = { mode: 'reserved', turn: (s.turnCount || 0) }; } catch (_) {}
        try { if (typeof _recordReaderPreference === 'function') _recordReaderPreference('coarse_demure', 'reserved', { source: 'register' }); } catch (_) {}
      }
      s._oasRegisterMode = 'reserved';
      return 'reserved';
    }

