    if (prior !== 'default') {
      try { console.log('[OAS:REGISTER-MODE] ' + prior + ' → default (stance=' + (stance || 'unset') + ', dwellLead=' + dwellLead + ', explicit_recent=' + explicitRecent + ')'); } catch (_) {}
    }
