    var _intensity = String(intensityHint || 'light').toLowerCase();
    if (_intensity !== 'light' && _intensity !== 'medium' && _intensity !== 'strong') _intensity = 'light';
    if (isHalfFavored) {
      if (_intensity === 'strong') _intensity = 'medium';
      else if (_intensity === 'medium') _intensity = 'light';
      // 'light' stays 'light'
    }
    var intensityNote = '';
    if (_intensity === 'light') {
      intensityNote = 'LIGHT INTENSITY (this scene): casual register. Mostly modern-readable. Occasional compression or subtle inversion — one per several lines, not every line. The heritage is a flicker, not a flood.';
    } else if (_intensity === 'medium') {
      intensityNote = 'MEDIUM INTENSITY (this scene): more ceremonial. Ritual framing surfaces. Aphoristic compression more common. The character may speak as if their words are being witnessed by ancestors. Still readable; never theatrical.';
    } else {
      intensityNote = 'STRONG INTENSITY (this scene): grief / intimacy / rage / transcendence pressure. Poetic compression allowed. Sentence rhythm may become more mythic or tidal. Ancient metaphor domains accessible. STILL within readability — never collapse into nonsense or pastiche.';
    }

    // Wry tone exception.
    var isWry = String(wryEarnest || '').toLowerCase().indexOf('wry') !== -1;
    var wryNote = isWry
      ? '\n\nWRY OVERLAY: this scene is in Wry tone. The First Favored register may LAND with deliberate comic contrast — ' + liName + ' sounds dry, elegant, old-fashioned, or overly formal against the surrounding world for amusing effect. MAX ~1 notable register-collision per scene. No memeification. The collision is observed, not performed.'
      : '';

    // Multi-speaker FF clause — when other First Favored characters
