        var tier = fireCount <= 1 ? 'light' : fireCount === 2 ? 'medium' : 'strong';
        var tierNote = tier === 'light'
          ? 'LIGHT INITIATIVE: ' + liName + ' redirects with warmth or a small physical pull — a hand at the jaw, a "come here", a line that brings ' + pcName + '\'s attention back without forcing it. The pivot is generous, not corrective.'
          : tier === 'medium'
