    if (!d || !d.liTurnHistory || d.liTurnHistory.length < 3) return consensusTone;
    var last3 = d.liTurnHistory.slice(-3);
    var s1 = last3[0].userSignal, s2 = last3[1].userSignal, s3 = last3[2].userSignal;
