      var vagueOpenerPatterns = [
        /^"?i\s+haven'?t\s+told\s+(anyone|anybody)\s+(this|that|about\s+it)\b/i,
        /^"?there'?s\s+something\s+(i\s+(should|need\s+to|have\s+to))?\s*(say|tell\s+you|admit)\b/i,
        /^"?i\s+(need|have)\s+to\s+(say|tell\s+you|admit)\s+(this|that|something)\b/i,
        /^"?i\s+(want|need)\s+to\s+(say|tell\s+you|let\s+you\s+know)\s+something\b/i,
        /^"?i\s+have\s+to\s+(confess|admit)\s+something\b/i
      ];
