    ctrlRow.style.cssText = 'display:flex;gap:6px;align-items:center;margin-bottom:6px;';
    var modelLabel = document.createElement('label');
    modelLabel.textContent = 'Model';
    modelLabel.style.cssText = 'color:#c9a24e;font-size:10px;letter-spacing:0.04em;';
    var modelSelect = document.createElement('select');
    modelSelect.id = 'oasReviewModel';
    modelSelect.style.cssText = 'background:#0e0a06;color:#f3e6c8;border:1px solid rgba(201,162,78,0.4);border-radius:3px;padding:3px 5px;font:11px sans-serif;';
    var fluxOpt = document.createElement('option');
    fluxOpt.value = 'flux'; fluxOpt.textContent = 'Flux Kontext';
    if (_oasReviewState.model === 'flux') fluxOpt.selected = true;
    var geminiOpt = document.createElement('option');
    geminiOpt.value = 'gemini'; geminiOpt.textContent = 'Gemini';
