    modifier.style.cssText = 'flex:1;background:#0e0a06;color:#f3e6c8;border:1px solid rgba(201,162,78,0.4);border-radius:3px;padding:4px 6px;font:11px sans-serif;resize:none;';
    ctrlRow.appendChild(modifier);
