        arcDistinct: +mean(function (r) { return r.scores.arcDistinct; }).toFixed(3),
        redundancy: sum(function (r) { return r.scores.redundancy; }),
        escalationOnly: sum(function (r) { return r.scores.escalationOnly; }),
