        console.log('%c  ⟹ ' + MODELS[MODELS.length - 1] + ' vs ' + MODELS[MODELS.length - 2] + ': thesisDistinct ' + (dDist >= 0 ? '+' : '') + dDist.toFixed(3) + ', escalationOnly ' + b.escalationOnly + ' vs ' + a.escalationOnly + ', cost ' + costMult.toFixed(1) + '×. ' + (dDist > 0.05 || (a.escalationOnly - b.escalationOnly) >= Math.ceil(seeds.length / 4) ? 'Quality gap looks REAL — read the blind dump to confirm.' : 'Quality gap looks SMALL — the cheaper model may win. Read the blind dump.'), 'color:#7ec77e;font-weight:bold');
