      var emotional = /\b(love|trust|fear|hate|need|miss|care|vulnerable|heart|sorry|forgive|confess)\b/.test(combined);
      var boundary  = /\b(kiss|touch|hold|push\s+away|pull\s+(?:close|away)|step\s+(?:closer|back)|reach|take\s+my|into\s+my)\b/.test(combined);
      if (!decisive && !emotional && !boundary) return;

      var liName = (state.partnerName && String(state.partnerName).trim())
        || 'The Love Interest';
      if (!state.characterGravity) state.characterGravity = {};
      if (!state.characterGravity[liName]) {
        state.characterGravity[liName] = {
          gravityScore: 0, momentsShared: 0, emotionalMoments: 0, threadConnections: 0
        };
      }
      var g = state.characterGravity[liName];
      g.gravityScore   = (g.gravityScore   || 0) + 1;
      g.momentsShared  = (g.momentsShared  || 0) + 1;
      if (emotional) g.emotionalMoments = (g.emotionalMoments || 0) + 1;
      g.lastSeenScene  = (state.turnCount || 0) + 1;
