      if (!state.currentEngine || state.currentEngine !== 'graphic') return;

      state.desireProfile = state.desireProfile || {
        control: 0, tenderness: 0, taboo: 0, surrender: 0
      };

      var combined = ((rawAct || '') + ' ' + (rawDia || '')).toLowerCase();
      if (!combined.trim()) return;

      var delta = 0.02;
      var prox  = state.proximitySignal    || 0;
      var tens  = state._lastTensionIntensity || 0;
      var ptype = state._lastPressureType;

