  // ── GN Scene 1 background preload ──
  // Kicks off the (expensive) panel-prompt LLM call + per-panel image
  // generation while the user is viewing the cover. When the user finally
  // clicks "Open" on the cover, _startGNScene1 picks up the cached result
  // and mounts panels instantly instead of waiting another 30-60s.
  //
  // No DOM updates, no fortune charge, no scene-state mutation here — this
  // is a pure background fetch that only writes to:
  //   state._preGNScene1Promise — in-flight promise (await-ready)
  //   state._preGNScene1         — { structuredPlan, pageHtml } when done
  //   state._gnPanelPlans[0]     — populated so downstream callbacks (motif
  //                                seeding, narrative state) can find it
  //
  // Cleared on cover-cancel and _exitGNEngine (so a back-out doesn't leave
  // a stale Scene 1 lingering in state for the next attempt).
  async function _pregenGNScene1Async() {
    // DEFENSIVE GUARD — legacy panel preload never fires in staged mode.
    // (Cover-view caller already gates on _isLegacyGNMode(); this is the
    // belt-and-suspenders second check at the function boundary.)
    if (!_assertRenderMode('graphic_novel')) return null;
    if (state._preGNScene1 || state._preGNScene1Promise) return state._preGNScene1Promise;
    if (state.currentEngine !== 'graphic') return null;
    if (typeof _buildGNPanelPrompt !== 'function') return null;
    if (!window.StoryboundOrchestration?.callChatGPT) return null;

    const _runPreload = async function() {
      console.log('[GN:PRELOAD] Scene 1 preload starting (cover view → reader background)');
      const _t0 = Date.now();
      try {
        const panelPrompt = _buildGNPanelPrompt(0);
        // Scene 1 max_tokens raised 1200 → 2400 — the prior ceiling was
        // forcing the LLM to truncate composition objects + visual fields
        // when asked for 4 panels with substantial content. 2400 gives
        // enough headroom for full composition detail across 4 panels +
        // captions + dialogue without hitting the cap.
        const panelResult = await window.StoryboundOrchestration.callChatGPT([
          { role: 'system', content: _GN_PANEL_SYSTEM_PROMPT },
          { role: 'user',   content: panelPrompt }
        ], { temperature: 0.8, max_tokens: 2400 });

        const structuredPlan = _parseStructuredPanels(panelResult, 0);
        if (!structuredPlan) {
          console.warn('[GN:PRELOAD] Structured plan parse failed — preload aborted (consumer will fall back to prose path)');
          return null;
        }

        // Stash the plan so post-mount hooks (motif seeding, narrative
        // state) can see it whether or not the preload was used.
        state._gnPanelPlans = state._gnPanelPlans || {};
        state._gnPanelPlans[0] = structuredPlan;

        const pageHtml = await _renderGNFromPanels(structuredPlan, 0);
        if (!pageHtml) {
          console.warn('[GN:PRELOAD] _renderGNFromPanels returned empty — preload aborted');
          return null;
        }

        const result = { structuredPlan: structuredPlan, pageHtml: pageHtml };
        state._preGNScene1 = result;
        console.log('[GN:PRELOAD] Scene 1 ready in', (Date.now() - _t0), 'ms — instant mount on Open');
        return result;
      } catch (err) {
        console.warn('[GN:PRELOAD] Failed (non-fatal — consumer regenerates fresh):', err && err.message);
        return null;
      } finally {
        // Clear the promise handle once settled so a future preload attempt
        // can re-fire if needed (e.g. user backed out and re-entered).
        if (state._preGNScene1Promise === _promise) state._preGNScene1Promise = null;
      }
    };

    const _promise = _runPreload();
    state._preGNScene1Promise = _promise;
    return _promise;
  }

