    // Safe no-op when state.omen or fate state are unset; accumulates
    // pressure only when real signals (greater petitions, etc.) exist.
    try {
      if (typeof advanceOmenDecay === 'function') advanceOmenDecay();
    } catch (_) {}

    // Collect behavioral signals
    _collectTempoSignal(action, dialogue);
    state._a0 = _detectAgency((action || '') + ' ' + (dialogue || ''));
