  // (Quill/Veto committed phrase system removed — replaced by Petition Fate)

  // --- META SYSTEM (RESTORED) ---
  function buildMetaDirective(){
     if(state.awareness === 0) return "";
     if(Math.random() > state.metaChance) return "";
     const stance = META_DIRECTIVES[state.stance] || META_DIRECTIVES['aid'];
     const directive = stance[Math.floor(Math.random() * stance.length)];
     return `META-NARRATIVE INTERVENTION: ${directive}`;
  }

  window.setMetaStance = function(s){
      // Tempt Fate requires explicit paid invocation — not just a stance toggle
      if (s === 'seduce') {
          invokeTemptFate();
          return;
      }
      state.stance = s;
      document.querySelectorAll('.meta-stance').forEach(b => b.classList.remove('active'));
      const btn = document.querySelector(`.meta-stance[onclick="window.setMetaStance('${s}')"]`);
      if(btn) btn.classList.add('active');
  };

  /**
   * TEMPT FATE — Explicit invocation flow.
   * 1. Compute cost
   * 2. Confirm with player
   * 3. Deduct Fortunes atomically
   * 4. Set invocation flag
   * 5. Activate stance
   */
  async function invokeTemptFate(skipConfirm = false) {
      // Fortune's Favor — check for free bonus charges before paid path
      let usedFreeCharge = false;
      // ONBOARDING FREE CREDIT: Scene 3 emergence grants a one-time free
      // Tempt Fate invocation. Flag is consumed regardless of outcome.
      if (state._temptGrantsFreeCredit) {
          state._temptGrantsFreeCredit = false;
          usedFreeCharge = true;
          try { console.log('[TEMPT] Onboarding free credit consumed — no fortune deduction.'); } catch (_) {}
          if (typeof showToast === 'function') showToast('Fate takes nothing — this one was on the house.');
          showTemptShudder();
          setTimeout(() => updateTemptFateSparkle(), 100);
      } else if (consumeFortuneFavorCharge()) {
          usedFreeCharge = true;
          // Free charge consumed — skip cost/confirm/deduction
          showTemptShudder();
          // Update sparkle state (may remove if last charge)
          setTimeout(() => updateTemptFateSparkle(), 100);
      } else {
          const cost = getTemptFateCost();

          // Check balance — open purchase modal if insufficient
          if ((state.fortunes || 0) < cost) {
              if (typeof openFortunePurchaseModal === 'function') openFortunePurchaseModal();
              return;
          }

          // Cost confirmation (skip when invoked from zoom card — zoom IS the confirmation)
          if (!skipConfirm) {
              const confirmed = confirm(`Tempt Fate costs ${cost} Fortune${cost !== 1 ? 's' : ''}. Proceed?`);
              if (!confirmed) return;
          }

          // Atomic deduction
          const burned = await consumeFortune(cost, 'tempt_fate');
          if (!burned) {
              console.error('[TEMPT] Fortune deduction failed');
              if (typeof openFortunePurchaseModal === 'function') openFortunePurchaseModal();
              return;
          }
          if (window.updateFortuneDisplay) window.updateFortuneDisplay();
      }

      // Set invocation flag + increment consecutive count + raise heat
      state.tempt_fate_invoked_this_turn = true;
      // NIL: Earned Rupture Authority — Tempt invocation is the heaviest
      // narrative-pressure signal. Vector hint: 'nihilism' (Tempt = the
      // urge to rewrite reality, often a nihilistic gesture). +3.
      try {
        if (typeof _accumulateNilRupturePressure === 'function') {
          _accumulateNilRupturePressure('tempt_fate_invoked', 3, 'nihilism');
        }
      } catch (_) {}
      // Tarot onboarding: using Tempt Fate completes onboarding
      if (typeof completeTarotOnboarding === 'function' && !isTarotOnboardingComplete()) completeTarotOnboarding();
      state.consecutive_tempt_fate_count = (state.consecutive_tempt_fate_count || 0) + 1;
      // Heat increments unbounded (cap removed 2026-05-17). Decay still
      // applies (-1 per non-Tempt scene, floored at 0). Cost is computed
      // via _temptFateBaseCost geometric formula, so any heat value yields
      // a finite cost.
      state.tempt_fate_heat = (state.tempt_fate_heat || 0) + 1;

      // Deck escalation axes — exposure is monotonic, incremented on every
      // Tempt invocation; instability rises only when overuse thresholds
      // (length-aware) are met. Tier flags derived from exposure.
      state.deckExposure = (state.deckExposure || 0) + 1;
      if (typeof _refreshDeckExposureTiers === 'function') {
        try { _refreshDeckExposureTiers(); } catch (_) {}
      }
      if (typeof _computeOveruseTrigger === 'function' && _computeOveruseTrigger()) {
        state._deckInstabilityLevel = Math.min(2, (state._deckInstabilityLevel || 0) + 1);
      }

      // Fate Event — Tempt Fate used
      if (typeof window._tryTriggerFateEvent === 'function') {
          window._tryTriggerFateEvent('tempt_fate_used');
      }

      // Badge engine — Tempt Fate milestones
      withProfileId(profileId => {
        incrementBadge(sb, profileId, 'tempt_first');
        if (state.consecutive_tempt_fate_count >= 3) {
          awardBadge(sb, profileId, 'tempt_disturb_fate');
        }
      });

      // Onboarding: mark first Tempt Fate invocation
      if (!state.has_triggered_first_tempt_fate) {
          state.has_triggered_first_tempt_fate = true;
      }

      // Fate Resonance — account-level mythic aura increment (narrative only)
      incrementFateResonance();

      // Activate stance for narrative directives
      state.stance = 'seduce';
      document.querySelectorAll('.meta-stance').forEach(b => b.classList.remove('active'));
      const btn = document.querySelector('.meta-stance[onclick="window.setMetaStance(\'seduce\')"]');
      if (btn) btn.classList.add('active');

      // ── WRY DISTORTION — Tempt Fate tone override ──
      // When an Earnest Fantasy story gets pushed too hard by Tempt Fate (3+ consecutive),
      // reality buckles: tone shifts to Wry for 3-5 scenes, artist overrides to Olen Droll,
      // narrator becomes deadpan observational.
      if (state.consecutive_tempt_fate_count >= 3 &&
          state.picks?.tone !== 'WryConfession' &&
          state.picks?.world === 'Fantasy' &&
          !(state._wryDistortion && state._wryDistortion.active)) {
        var _wryDuration = 3 + Math.floor(Math.random() * 3); // 3-5 scenes
        state._wryDistortion = {
          active: true,
          scenesRemaining: _wryDuration,
          originalArtist: state.gnArtist || null,
          originalTone: state.picks?.tone || 'Earnest',
          hangoverScene: false
        };
        // Override artist to Olen Droll for duration
        if (state.gnArtist && state.gnArtist !== 'olen_droll') {
          state.gnArtist = 'olen_droll';
        }
        console.log('[WRY_DISTORTION] ACTIVATED — reality buckles. Duration: ' + _wryDuration + ' scenes. Original artist: ' + state._wryDistortion.originalArtist + ', Original tone: ' + state._wryDistortion.originalTone);
      }

      console.log(`[TEMPT_FATE] Invoked. ${usedFreeCharge ? 'Cost: FREE (bonus charge)' : 'Cost: ' + getTemptFateCost()}, Heat: ${state.tempt_fate_heat}, Consecutive: ${state.consecutive_tempt_fate_count}, Remaining Fortunes: ${state.fortunes}, Resonance: ${state.fate_resonance_intensity} (${getFateResonanceState()})`);
  }

  // --- BEGIN STORY VALIDATION GUARDRAIL ---
  function validateBeginStory() {
      const errors = [];

      // Skip validation if Fate triggered (all values are pre-set correctly)
      if (state._fateTriggered) {
          return errors;
      }

      // Check archetype selection
      const archetypeValidation = validateArchetypeSelection(state.archetype.primary, state.archetype.modifier);
      if (!archetypeValidation.valid) {
          errors.push(archetypeValidation.errors[0] || 'Please select a Primary Archetype.');
      }

      // 4-axis validation: world, tone, genre, dynamic are required (single-select)
      if (!state.picks.world) {
          errors.push('Please select a Story World.');
      }

      if (!state.picks.tone) {
          errors.push('Please select a Story Tone.');
      }

      if (!state.picks.genre) {
          errors.push('Please select a Genre.');
      }

      if (!state.picks.dynamic) {
          errors.push('Please select a Relationship Dynamic.');
      }

      // Historical world requires era selection
      if (state.picks.world === 'Historical' && !state.picks.era) {
          errors.push('Please select a Historical Era.');
      }

      // SciFi world requires a vector (worldSubtype) selection
      if (state.picks.world === 'SciFi' && !state.picks.worldSubtype) {
          errors.push('__SCIFI_FLAVOR_REQUIRED__');
      }

      return errors;
  }

  // ========================================
  // LET FATE DECIDE - Auto-selection System
  // ========================================

  // Weighted random selection helper
  function weightedSelect(options, weights) {
    const totalWeight = weights.reduce((a, b) => a + b, 0);
    let random = Math.random() * totalWeight;
    for (let i = 0; i < options.length; i++) {
      random -= weights[i];
      if (random <= 0) return options[i];
    }
    return options[options.length - 1];
  }

