    state.picks.worldSubtype = ((state.fateMode === 'famous_fate' || state.famousFate || (fateChoices && fateChoices.famousFate))
      && /post.?apoc|apocalyp|dystop|wasteland|ashfall/i.test(String((fateChoices && (fateChoices.world || fateChoices.worldFlavor)) || '')))
      ? '' : fateChoices.worldFlavor;
    state.picks.tone = canonicalizeTone(fateChoices.tone);
