    reading.activeParagraphId = state.activeParagraphId || null;
    reading.activeParagraphText = (state.activeParagraphText || '').slice(0, 600) || null;
    reading.scrollY = (typeof window.scrollY === 'number') ? Math.round(window.scrollY) : null;
