  // ── REAL_EVENT_BAN v1 · deterministic pre-filter (Roman 2026-07-01) ─────────
  // A DELIBERATELY TINY set of unmistakable high-signal PHRASES only — NO list of
  // individual killer/victim/atrocity names (that's a maintenance trap and the
  // wrong architecture). The CLASSIFIER does the real work (the single "is this
  // centered on a REAL person / REAL event?" question). This pre-filter just short-
  // circuits the few phrasings that are real-atrocity roleplay on their face, so we
  // can hard-block them without spending an LLM call. FICTIONAL villains/horror/
  // crime MUST pass (Hannibal, Bateman, the Joker, Voldemort, Batman, HP) — none of
  // them trip these phrases. Runs FIRST at FF submit. Returns { blocked:true,
  // category, matched } on a hit, else { blocked:false }. Categories:
  // serial_killer | mass_shooting | terrorism | genocide | real_victim | war_crime | other.
  function _ffDetectRealEventBan(text) {
    var s = String(text || '').toLowerCase();
    if (!s.trim()) return { blocked: false };
    // Normalize curly quotes + collapse whitespace/punct so "9 / 11", "sept. 11" behave.
    var norm = s.replace(/[‘’]/g, "'").replace(/[._]+/g, ' ').replace(/\s+/g, ' ').trim();

    // Roleplay/POV framing token (used to qualify the softer phrases below).
    var RP = "(?:roleplay|role-play|\\brp\\b|pov|point of view|perspective|play(?:ing)? as|embody|be the|from the)";

    // TINY high-signal PHRASE set — [regex, category]. Phrases, not names.
    var PHRASES = [
      // "school shooter" / "school shooting" — real-atrocity roleplay on its face.
      [/\bschool\s*shoot(?:er|ing)\b/i, 'mass_shooting'],
      // "9/11 hijacker" / "september 11 hijacker".
      [/\b(?:9\s*[\/\-]\s*11|nine[\s-]?eleven|(?:september|sept)\s*11(?:th)?)\s+hijacker\b/i, 'terrorism'],
      // "columbine roleplay" (columbine + roleplay/POV/shooter framing).
      [new RegExp('\\bcolumbine\\b[^.?!]{0,20}(?:' + RP + '|shoot(?:er|ing)|massacre)', 'i'), 'mass_shooting'],
      // "play as a real serial killer" (real + serial killer/mass shooter/terrorist).
      [/\breal\s+(?:serial\s+killer|mass\s+shooter|terrorist)\b/i, 'serial_killer'],
      // "from the hijacker's/bomber's/shooter's POV".
      [/\bfrom the (?:hijacker|bomber|terrorist)(?:'s)?\s+(?:pov|point of view|perspective|eyes|side)\b/i, 'terrorism'],
      [/\bfrom the (?:shooter|gunman)(?:'s)?\s+(?:pov|point of view|perspective|eyes|side)\b/i, 'mass_shooting'],
      // "recreate a real murder / massacre" (realness-qualified to spare fiction).
      [/\b(?:recreate|reenact|re-enact|relive)\b[^.?!]{0,40}\b(?:real|actual|true)\b[^.?!]{0,20}\b(?:murder|killing|massacre|shooting|attack)\b/i, 'real_victim']
    ];

    // "mass shooting" + roleplay/POV framing (either order) — the phrase alone is
    // too broad to block, so it must be paired with a roleplay/embodiment cue.
    var _hasMassShoot = /\bmass\s*shoot(?:er|ing)\b/i.test(norm);
    var _hasRP = new RegExp(RP, 'i').test(norm);
    if (_hasMassShoot && _hasRP) return { blocked: true, category: 'mass_shooting', matched: 'phrase' };

    for (var k = 0; k < PHRASES.length; k++) {
      if (PHRASES[k][0].test(norm)) return { blocked: true, category: PHRASES[k][1], matched: 'phrase' };
    }

    return { blocked: false };
  }

