          var _fcMsg = 'Couldn’t confidently resolve “' + (world || embody || 'that story') + '”' + (embody ? (' + “' + embody + '”') : '') + ' for Canon mode. Try a more specific work, or switch to Alternate-timeline mode.';
          if (_ffErr) { _ffErr.textContent = _fcMsg; _ffErr.classList.remove('hidden'); }
