      if (_beginBtn) { _beginBtn.disabled = false; _beginBtn.textContent = 'Begin Famous Fate'; }
      try { _ffSummoningHide(); } catch (_) {}
      var _rpMsg = 'Famous Fate is for fictional worlds and characters — you can’t play (or include) a real person. Try a fictional character from any story, world, or fandom.';
      if (_ffErr) { _ffErr.textContent = _rpMsg; _ffErr.classList.remove('hidden'); }
      else if (typeof showToast === 'function') showToast(_rpMsg);
