      lifeStage: _stageResolved,                  // AXIS 1 resolved ('unknown' preserved)
      universeProfile: _uni,                      // AXIS 2
      explicitEligible: _explicitEligible && !_noLoveInterest,
      romanceAllowed: _romanceAllowed && !_noLoveInterest,
      noLoveInterest: _noLoveInterest,            // reader opted out of romance entirely
      classifierLifeStage: _stage,                // raw classifier verdict
      adultOverride: _explicitAdult,
      partnerMode: _partnerMode,                  // 'original' | 'canonical' | 'none'
      requestedPartner: (cls && cls.requestedPartner) || null,
      prohibitedReason: (cls && cls.prohibitedReason) || null
