    state._chargeIntimacyStanceCountedThisStory = false;
    state._desireObs = null;             // desire-observation tally (Say/Do + Fate + probes), per-story
    state.desireCalibration = undefined; // finalized dwell−avoidance at ST3 (Slice 2); cross-issue persistence is a later concern
