    // scene grounds the reader in no physical place at all), mirroring the people detectors' clear-absence
    // bar to avoid false positives. Validate-only, batch-tracked (sb_setting_desc_failrate: fail + floor).
    function _settingDescriptionCheck(prose, stage) {
      try {
        if (!prose || typeof prose !== 'string') return null;
        var st = window.state || {};
        var paras = prose.split(/\n\s*\n/).filter(function (p) { return p && p.trim().length; });
        var head = paras.slice(0, 2).join(' ');
        if (!head) head = prose.slice(0, 700);
        var MATERIAL = /\b(?:marble|granite|stone|brick|concrete|wood(?:en)?|oak|pine|timber|plank|glass|mirror|metal|iron|steel|brass|bronze|copper|leather|velvet|silk|linen|cotton|wool|canvas|parchment|paper|carpet|rug|tile|slate|plaster|clay|sand|ash|mud|moss|bark|thornwild|veilwood|spiralgrass|snow|ice|dust|smoke|straw|rope|chain|blade|wax|fur|hide|scale|bone)\b/i;
        var LIGHT = /\b(?:light|lit|sunlight|moonlight|moon(?:s)?|candle(?:light)?|lantern|lamp|firelight|glow|gloom|shadow(?:s|ed)?|dark(?:ness)?|dim(?:ly)?|bright|golden|amber|silver(?:ed)?|dusk|dawn|twilight|noon|midnight|shade|shaft|flicker|guttering|blaze|glint|gleam)\b/i;
        var hasMaterial = MATERIAL.test(head);
        var hasLight = LIGHT.test(head);
        var hasPlace = hasMaterial && hasLight;   // the ④ floor: a named surface/material + the quality of light
        var fail = !hasMaterial && !hasLight;     // conservative: no physical grounding at all in the first ~2¶
        if (stage === 'final') {
          try {
            var key = 'sb_setting_desc_failrate';
            var arr = JSON.parse(localStorage.getItem(key) || '[]') || []; if (!Array.isArray(arr)) arr = [];
            var sid = String(st.storyId || '');
            if (arr.length && arr[arr.length - 1] && arr[arr.length - 1].id === sid) { arr[arr.length - 1].fail = fail ? 1 : 0; arr[arr.length - 1].floor = hasPlace ? 1 : 0; }
            else arr.push({ id: sid, fail: fail ? 1 : 0, floor: hasPlace ? 1 : 0 });
            while (arr.length > 20) arr.shift();
            localStorage.setItem(key, JSON.stringify(arr));
            var fails = arr.reduce(function (a, b) { return a + (b && b.fail ? 1 : 0); }, 0);
            var floorMet = arr.reduce(function (a, b) { return a + (b && b.floor ? 1 : 0); }, 0);
            if (fail) console.warn('[GEN-FAIL:SETTING:FINAL] first ~2¶ establish NO physical place — no material/surface noun AND no light-quality token. The reader cannot SEE where this happens. BATCH RATE: ' + fails + '/' + arr.length + ' setting-unestablished; FLOOR MET ' + floorMet + '/' + arr.length + '. [tracked, NOT repaired]');
            else if (!hasPlace) console.log('[GEN-FAIL:SETTING:FINAL] ~ partial: ' + (hasMaterial ? 'material present, LIGHT-quality missing' : 'light present, MATERIAL missing') + ' — below the {material + light} floor. FLOOR MET ' + floorMet + '/' + arr.length + '.');
            else console.log('[GEN-FAIL:SETTING:FINAL] ✓ place established (material + light) in first ~2¶. FLOOR MET ' + floorMet + '/' + arr.length + '.');
          } catch (_) {}
        }
        return { hasMaterial: hasMaterial, hasLight: hasLight, hasPlace: hasPlace, fail: fail };
      } catch (_) { return null; }
    }
    window._settingDescriptionCheck = _settingDescriptionCheck;

    // LI-EMBODIMENT — LONGING-THROUGH-ABSTRACTION detector (Roman 2026-06-06). THE MEASUREMENT GAP:
    // `[SCENE1:DESIRE]` scored "I wanted him to have written it" as 104% desire while the reader saw
    // 0 — because that is wanting an OUTCOME / an IDEA of him, not a MAN. Roman's distinction (proven
    // to survive the A-plotectomy, so it is NOT an A-plot artifact): the model renders the LI through
    // PERSONHOOD (face / voice / body / scent / weight / touch / movement) vs ABSTRACTION (his
    // handwriting, a note, his family's board seat, behavioral TELLS like "his thumb stopped" /
    // "answered a question I hadn't asked", what-it-MEANS, the decision-about-him). The desire
    // detector is blind to the difference; this makes it visible. Validate-only.
    function _auditLIEmbodiment(prose, stage) {
      try {
        if (!prose || typeof prose !== 'string') return null;
        var st = window.state || {};
        var liFirst = String(st.loveInterestName || (st.picks && st.picks.identity && st.picks.identity.partnerName) || '').split(/\s+/)[0] || '';
        if (!liFirst) return null;
        var liEsc = liFirst.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        var liRe = new RegExp('\\b' + liEsc + '\\b|\\b(?:his|him|he)\\b', 'i');
        var sents = prose.split(/(?<=[.!?])\s+/).filter(function (s) { return liRe.test(s); });
        // PERSONHOOD — his physical / sensory self as the object of wanting (a body, not a signal).
        var PERSONHOOD = /\b(?:voice|laugh|laughed|whisper|murmur|breath|breathing|scent|smell|cologne|warmth|warm|heat|skin|mouth|lips|jaw|throat|neck|chest|shoulders?|forearms?|wrists?|build|frame|weight|moved|movement|the way he moved|closer|leaned|lean|pull(?:ed)?|touch|touched|kiss|kissed|hold|held|stubble|beard|broad|tall|dark[- ]haired|silver at|grey at)\b/i;
        // ABSTRACTION — artifact / institution / behavioral tell / meaning / decision (an idea, not a body).
        var ABSTRACTION = /\b(?:handwriting|script|note|letter|card|envelope|document|deed|affidavit|contract|signature|board|enclave|company|firm|syndicate|reputation|influence|family|mother|father|the way he (?:answered|deflected|tracked|waited|listened|knew|read)|thumb (?:stopped|stilled|stop)|answered a question|question i (?:hadn|had not)|what it meant|meant something|whether to call|decision)\b/i;
        var nPers = 0, nAbs = 0;
        sents.forEach(function (s) { var p = PERSONHOOD.test(s), a = ABSTRACTION.test(s); if (p) nPers++; if (a && !p) nAbs++; });
        var total = nPers + nAbs;
        if (stage === 'final' && total >= 2) {
          var absShare = Math.round(100 * nAbs / total);
          if (nPers === 0 || absShare >= 65) {
            console.warn('[LI-EMBODIMENT] ✗ LONGING-THROUGH-ABSTRACTION (' + absShare + '% abstraction) — of ' + total + ' ' + liFirst + '-charged lines, ' + nAbs + ' anchor on ABSTRACTION (handwriting / note / board / family / behavioral-tell / what-it-means) vs ' + nPers + ' on PERSONHOOD (voice / scent / body / touch / weight / movement). She is wanting an IDEA of him, not a man — this is the desire the [SCENE1:DESIRE] % counts but the reader does NOT feel. The fix lives in the desire GENERATOR, not the ownership layer.');
          } else {
            console.log('[LI-EMBODIMENT] ✓ longing has a BODY — ' + nPers + ' personhood vs ' + nAbs + ' abstraction lines (' + absShare + '% abstraction). She wants the man, not the idea.');
          }
        }
        return { personhood: nPers, abstraction: nAbs };
      } catch (_) { return null; }
    }
    window._auditLIEmbodiment = _auditLIEmbodiment;

    // STRUCTURAL PAYLOAD AUDIT (Roman 2026-06-04). The mechanical fallback
    // (_scene1FallbackRewrite) truncates Scene 1 to its last ~350 words — it is
    // PAYLOAD-BLIND, so it eats whatever required element happens to live in the
    // discarded front. LI description was the FIRST thing measured lost; it is not
    // necessarily the only one. This measures the 4 required payloads in any prose
    // so the call site can diff before/after and report EXACTLY what the rewrite
    // removed: [REWRITE:PAYLOAD-LOSS] lost = X. Measurement only — no preservation.
    function _measureScene1Payloads(prose) {
      var out = { crisis: false, li_attraction_anchor: false, micro_choice: false, hook: false };
      try {
        if (!prose || typeof prose !== 'string') return out;
        // CRISIS — a concrete catastrophe in the prose (the HOT opener / one fire).
        out.crisis = /\b(?:fired|ousted|voted (?:me|her|him|them) out|laid off|terminated|dismissed|escort(?:ed)? out|walked (?:me|her|him) out|security|dying|died|dead|death|funeral|diagnos|overdose|hospital|collaps(?:e|ed|ing)|bankrupt|ruin(?:ed)?|evict(?:ed)?|foreclos|arrest(?:ed)?|police|sued|lawsuit|charges|betray(?:ed|al)?|exposed|scandal|leak(?:ed)?|crash(?:ed)?|explosion|attack(?:ed)?|breakup|divorce|stripped of|missing|kidnapp?ed|overdue|deadline)\b/i.test(prose);
        // LI ATTRACTION ANCHOR — an image-defining LI physical anchor (build/hair/face).
        // Meaningful LI physical presence (≥2 categories) — the audit measures what
        // the truncation REMOVED, so it uses presence, not the stricter "picturable"
        // (build/hair/face) bar that GEN-FAIL:LI-DESCRIPTION:FINAL owns. A draft with
        // 4 LI categories truncated to 1 ("suit") registers here as a loss.
        try { var _r = (typeof window._liDescriptionCheck === 'function') ? window._liDescriptionCheck(prose) : null; out.li_attraction_anchor = !!(_r && _r.hits && _r.hits.length >= 2); } catch (_) {}
        // MICRO-CHOICE — the canonical micro-decision question (or its markers).
        var _q = (window.state && (window.state._microDecisionLibraryQuestion || window.state._scene1ScaffoldedMicroQuestion)) || '';
        out.micro_choice = /<<MICRO_EXPRESSION>>/i.test(prose) || (_q && _q.length > 8 && prose.indexOf(_q) !== -1) || false;
        // HOOK — the concrete hook object/signal the scaffold planned.
        var _ho = (window.state && window.state._scene1HookObject) || '';
        if (_ho && _ho.length > 2) {
          var _hoCore = _ho.replace(/^(?:a|an|the)\s+/i, '').split(/\s+/)[0];
          try { out.hook = new RegExp('\\b' + _hoCore.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'i').test(prose); } catch (_) { out.hook = prose.toLowerCase().indexOf(_ho.toLowerCase()) !== -1; }
        }
      } catch (_) {}
      return out;
    }
    window._measureScene1Payloads = _measureScene1Payloads;

    // INTERIORITY AUDIT LENS (Roman 2026-06-05 — HYPOTHESIS TEST, not a fix). When a
    // Scene 1 reads COLD the cause may be ANALYSIS replacing EXPERIENCE: the narrator
    // INTERPRETS / EXPLAINS / THEORIZES emotion ("I wanted X" / "I had no idea what was
    // mine") instead of SENSING / NOTICING it ("the room felt too bright" / "the words
    // refused to connect"). Crisis affects INTERIORITY first; archetype governs only
    // EXTERIOR behavior. This MEASURES the analysis-vs-experience ratio so the
    // hypothesis can be tested across runs before any doctrine is written. Pure regex,
    // no LLM, no localStorage (the quota lockout is fresh). Console only.
    function _measureInteriority(prose) {
      try {
        if (!prose || typeof prose !== 'string') return null;
        var ANALYSIS = [
          /\bI (wanted|needed|knew|realized|understood|wondered|thought|believed|suspected|decided|figured|wasn'?t sure|had no idea|did(n'?t| not) know|still did(n'?t| not) know)\b/i,
          /\bI felt (like|as if|a|an|the|myself|something|nothing|everything|too)\b/i,
          /\bwhat (was|wasn'?t|is|isn'?t) (actually|really|truly|even|still )?(mine|hers|his|true|real|left|me)\b/i,
          /\bthe (truth|reason|point|problem|question|thing) (was|is)\b/i,
          /\bI'?d spent \w+ (years|months|weeks|decades)\b/i,
          /\b(some|part) of (me|her|him)\b/i,
          /\bI told myself\b/i,
          /\b(which |that )?meant (that|nothing|everything|I|she|he|the)\b/i,
          /\bknowing (exactly|full well|that |what )\b/i,
          /\bthe way I'?d been taught\b/i,
          /\bI (was|am) the kind of (person|woman|man)\b/i
        ];
        var EXPERIENCE = [
          /\b(too bright|too loud|too quiet|too close|too still|too sharp)\b/i,
          /\b(tunnel(ed|ing|s)?|refused to|would(n'?t| not) (stay|connect|come|hold)|went (uneven|still|cold|tight|hot|numb)|caught (in|on)|flick(ed|ing)|buzz(ed|ing)|humm?(ed|ing)|narrowed|blurred|swam)\b/i,
          /\b(my|her|his) (pulse|heart|throat|chest|hands?|breath|hearing|skin|jaw|spine|stomach|mouth|fingers?|knuckles?|ribs?|ears?)\b/i,
          /\bI (noticed|caught|heard|saw|smelled|tasted|felt the (cold|heat|weight|edge|warmth|press|grain))\b/i,
          /\b(the (room|light|air|sound|silence|words?|smell|fluorescents?|glow|page|folder|screen|hum|noise))\b[^.?!\n]{0,32}\b(felt|seemed|went|grew|pressed|sat|hung|sharpen|tilt|too|refused)\b/i
        ];
        var sents = prose.split(/(?<=[.!?])\s+/).map(function (s) { return s.trim(); }).filter(function (s) { return s.length > 4; });
        var analysisLines = [], experience = 0;
        sents.forEach(function (s) {
          if (ANALYSIS.some(function (r) { return r.test(s); })) { analysisLines.push(s); return; }
          if (EXPERIENCE.some(function (r) { return r.test(s); })) experience++;
        });
        var aN = analysisLines.length, total = aN + experience;
        return { analysis: aN, experience: experience, ratio: total ? Math.round((aN / total) * 100) : 0, analysisLines: analysisLines };
      } catch (_) { return null; }
    }
    window._measureInteriority = _measureInteriority;

    // GENERIC SEEDED EXEMPLAR ROTATION (Roman 2026-06-05). Static exemplar banks shown
    // VERBATIM every run fossilize into latent canon — the model copies the vivid example
    // (red dress / pulse went uneven / grandmother's ring / quarter-inch nod). The audit
    // found NO pool is code-rotated; every one just says "please vary" and the model
    // doesn't. This is the fix: from a LARGE pool, show a SEEDED SUBSET of `count` vivid
    // examples this story, walking a cursor so consecutive stories get NON-overlapping
    // windows (variety across recent stories guaranteed; wraps after pool/count stories).
    // It SELECTS, it does NOT abstract — the examples stay vivid. Idempotent within a story.
    function _rotatingExemplars(poolKey, pool, count) {
      try {
        if (!Array.isArray(pool) || !pool.length) return [];
        // SIGNATURE-PHRASE LEDGER FILTER (Roman 2026-06-09): drop exemplars whose
        // text contains a currently-banned phrase so a harvested/recurring line
        // stops being SHOWN as a seed. The phrase that recurs in BOTH the Sonnet
        // AND Grok versions of a seed is coming from the prompt (an exemplar like
        // this), not the prose writer — so de-prime it HERE, at the source. Only
        // applied when enough fresh exemplars remain (never starves the pool).
        try {
          if (typeof _phraseLedgerBannedSet === 'function') {
            var _banned = _phraseLedgerBannedSet();
            if (_banned && _banned.size) {
              var _fresh = pool.filter(function (e) {
                var s = String(e || '').toLowerCase();
                var bad = false; _banned.forEach(function (b) { if (b && b.length >= 6 && s.indexOf(b) !== -1) bad = true; });
                return !bad;
              });
              if (_fresh.length >= Math.min(count || 4, 2)) pool = _fresh;
            }
          }
        } catch (_) {}
        count = Math.min(count || 4, pool.length);
        if (pool.length <= count) return pool.slice();
        var sid = (window.state && window.state.storyId) || '';
        var stateKey = '_exrot_' + poolKey;
        var windowAt = function (off) {
          var s = [];
          for (var i = 0; i < count; i++) s.push(pool[(off + i) % pool.length]);
          return s;
        };
        // 1. In-session memory cache (fast path): same issue this session → same subset.
        //    GUARD (Roman 2026-06-15): only reuse when sid is truthy. An EMPTY sid
        //    (e.g. the Fate working-title pick runs at handleBeginStory BEFORE
        //    state.storyId is assigned ~202603) would otherwise match the persisted
        //    {sid:'', off:0} from the first story and PIN every story to offset 0 —
        //    the "all 10 stories titled 'Fate at the Threshold'" bug. Empty sid →
        //    fall through to the walking cursor (advances per call → variety).
        if (sid && window.state && window.state[stateKey] && window.state[stateKey].sid === sid) {
          return windowAt(window.state[stateKey].off);
        }
        // 2. Persisted offset for THIS issue (survives a page reload): if we already
        //    resolved an offset for this storyId, REUSE it — do NOT advance the cursor.
        //    This makes "same issue always gets the same subset, even after reload" true.
        var offKey = 'sb_exrot_off_' + poolKey; // one small {sid,off} per pool, overwritten per issue (bounded)
        try {
          var stored = JSON.parse(localStorage.getItem(offKey) || 'null');
          if (sid && stored && stored.sid === sid && typeof stored.off === 'number') {
            if (window.state) window.state[stateKey] = { sid: sid, off: stored.off };
            return windowAt(stored.off);
          }
        } catch (_) {}
        // 3. Genuinely new issue: take the walking cursor, advance it (keeps consecutive
        //    issues non-overlapping), and persist the offset for this issue.
        var lsKey = 'sb_exrot_' + poolKey;
        var cursor = 0;
        try { cursor = parseInt(localStorage.getItem(lsKey) || '0', 10) || 0; } catch (_) {}
        var offset = ((cursor % pool.length) + pool.length) % pool.length;
        try { localStorage.setItem(lsKey, String((offset + count) % pool.length)); } catch (_) {}
        // Only write the per-sid reuse cache when sid is real — never under sid:''
        // (else the next empty-sid call would reuse offset 0 and re-pin everything).
        if (sid) {
          try { localStorage.setItem(offKey, JSON.stringify({ sid: sid, off: offset })); } catch (_) {}
          try { if (window.state) window.state[stateKey] = { sid: sid, off: offset }; } catch (_) {}
        }
        return windowAt(offset);
      } catch (_) { return (pool || []).slice(0, count || 4); }
    }
    window._rotatingExemplars = _rotatingExemplars;

    // === ROTATING EXEMPLAR POOLS (large pools; the harness shows a seeded subset per
    // story). Each example stays VIVID — content varies (jacket / earrings / boots /
    // scent / glasses / coffee) so SHAPE is taught without one iconic line fossilizing.
    // POOL #1 — PC self-presentation beat (was 8 static, shown every Scene 1; source of
    // "red dress called trouble" / "grandmother's ring"). Expanded to 16; harness shows 5.
    // Roman 2026-06-10 — DE-PRIMED off the corporate operator. The old pool was
    // ALL deposition / trial / dean / "rooms I meant to win" / briefed / take /
    // obey framings — it taught the model to write the high-competence operator
    // heroine and literally seeded the calcified "rooms I meant to win" phrase.
    // Rewritten as a YOUNGER, EMOTIONALLY PERMEABLE, creative/independent heroine
    // (see [[project_heroine_profile]]). Same register + anchor spread preserved;
    // no calcified motif shapes (no pulse / voice-drop / collarbone-line / restless-
    // hands / lip-bite / ring-twist / take-the-room).
    window._PC_SELF_PRES_POOL = [
      '[sardonic / tactical, anchor=clothing] "I cuffed my sleeves to the elbow, slow, the way I always did before something that scared me — let the room call it confidence if it wanted to."',
      '[vulnerable / raw, anchor=hands] "My hands had started shaking again. I made a fist to hide it; the tremor just climbed to my elbow, the way it had all that first year on my own."',
      '[intense / uncurated, anchor=clothing] "I\'d worn the red dress because I was angry — the shade my mother used to call trouble, the one that made my reflection look like someone who had already decided."',
      '[defiant / practical, anchor=shoes/posture] "I kicked my shoes off under the table. Barefoot was how I thought best; every place I\'d ever worked had a sign about it and I\'d ignored every sign."',
      '[self-aware / introspective, anchor=reflection-glance] "I caught my own reflection in the dark window and went still: the narrow look I got right before doing something my sister would have called stupid."',
      '[calculated / armored, anchor=posture] "I let my shoulders drop into something looser than I felt — the ease I put on like a coat, the only armor I\'d ever really learned to wear."',
      '[contained / observant, anchor=jewelry/object] "I kept turning the little enamel pin on my collar, the habit I get when I\'m bracing for something. He noticed. I hadn\'t meant for him to."',
      '[openly amused / disarming, anchor=voice/laugh] "I laughed once, the wrong way — too loud, too sudden — and felt my face go hot. I didn\'t apologize for it, which surprised us both."',
      '[sardonic / tactical, anchor=eyewear] "I shoved my glasses up into my hair and left them there — my tell, since school, that I\'d stopped second-guessing and was about to make a mess on purpose."',
      '[vulnerable / raw, anchor=mouth/breath] "I pressed the back of my hand to my mouth and breathed out slow against it, a trick from the year I couldn\'t sleep through the night."',
      '[intense / uncurated, anchor=scent] "I\'d put on the heavy perfume on purpose — the one that arrives a half-second before I do. Today I didn\'t want to be easy to overlook."',
      '[defiant / practical, anchor=posture/lean] "I planted both forearms on the table and leaned in past polite. Polite had never once gotten me anything I actually wanted."',
      '[self-aware / introspective, anchor=object/hands] "I lined my pen up dead parallel to the table edge and caught myself doing it — the old need to make one small thing behave when nothing else would."',
      '[contained / observant, anchor=clothing] "I buttoned my jacket up though the room was warm — the way I close myself off when I can\'t yet read what a person wants from me."',
      '[calculated / armored, anchor=stillness] "I held still and let the quiet do the work, the way I had as the youngest in a loud house — say less, and they lean in to find you."',
      '[warm / disarming, anchor=hands/posture] "I wrapped both hands around the coffee like it was the only warm thing in the building and let them see I was cold. Sometimes letting someone see you need warmth is the fastest way to let them close."'
    ];

    // POOL #2 — the four "shape banks" (were rendered as full static menus every run,
    // with only a soft "pick a different shape" line — NO code rotation; source of
    // "ponytail-loosened" / "knuckle-scar" / "silver-hair+glasses"). Each expanded; the
    // harness shows a 4-item seeded subset per story (re-numbered at the call site).
    // ── LI PHYSICAL ROTATION POOLS (Roman 2026-06-08) — fed to the LI body-bible
    // generator via window._rotatingExemplars (storyId-seeded walking cursor →
    // non-overlapping windows across stories). Large pools so the billionaire-LI
    // never reduces to greying-temples / dark-eyes / glass-tap across a dozen plays.
    window._LI_HAIR_POOL = [
      // Roman 2026-06-12: replaced calcified entry — the original 'dark, cut
      // close on the sides, longer on top, never quite styled' surfaced
      // verbatim in generated LI Bibles across 8+ stories (model copied the
      // pool's first entry as the path of least resistance). Replacement is
      // a structurally different shape: color + texture + length-as-history.
      'auburn and thick, gone shaggy past a clean shape he no longer asks his barber to restore',
      'rust-red and overgrown, shoved back with one hand',
      'close-cropped black going silver only at the crown',
      'sandy and sun-stripped, a little too long for the role and aware of it',
      'jet black and heavy, falling into his eyes until he rakes it back',
      'ash-brown, military-short, growing out unevenly',
      'thick chestnut waves he clearly fights and loses to',
      'shaved to the skin, a faint old scar showing through above one ear',
      'dark curls kept ruthlessly short, one always escaping at the front',
      'prematurely white at thirty-four, worn defiantly long',
      'coppery and fine, flattened on one side by a hand he keeps running through it',
      'blue-black and glossy, the only vain thing about him',
      'dark and thick, expensively cut and a little overgrown between appointments',
      'auburn, cut by someone expensive but slept-on',
      'salt-and-pepper, a number-two all over, no fuss',
      'long enough to tie back, dark with a single grey streak off-centre',
      'platinum-bleached at the tips, roots two shades darker',
      'warm brown, side-parted with old-fashioned care he is faintly embarrassed by',
      'black and coarse, a cowlick at the back no cut will lie flat',
      'silvered all over at forty, long enough to read as choice not surrender',
      'dirty-blond, perpetually wind-wrecked, like he just got off a boat',
      'deep brown and lustrous, the kind that falls back into place on its own',
      'shorn close on a head shaped well enough to carry it',
      'ink-dark, one white patch at the temple from an old injury',
      'tawny and thick, pushed straight back over a barbershop fade',
      'red-brown, a stubborn part that drifts left by noon',
      'iron-grey and thick all over, a full silver head he keeps well-barbered',
      'fine and pale-gold, kept short to disguise how soft it is'
    ];
    // Roman 2026-06-10 — DE-PRIMED + INTERLEAVED. The old pool clustered greys at the
    // window-start positions the hard-assign reads ([0] of a rotated window), so the LI
    // got pale-grey/amber eyes story after story. It also CONTAINED the two calcified
    // descriptions the reader kept seeing: "deep-set slate, with a permanent faint
    // squint" (the "perpetually squinting eyes") and "storm-grey with a darker ring at
    // the rim" (the "ringed iris") — both REMOVED. Greys/ambers cut to a handful and
