        var baseW = _allyFnBaseWeightFn(s);
        var tier = String(s.storyLength || s.tier || 'fling').toLowerCase();
        var castSize = (/taste|fling/.test(tier)) ? 2 : (/soulmate|epic/.test(tier)) ? 4 : 3;
        var rolePool = (typeof window._resolveSocialRolesPool === 'function') ? window._resolveSocialRolesPool(s) : ['a close friend', 'a sibling', 'a coworker'];
        castSize = Math.min(castSize, rolePool.length, KEYS.length);
        var roleKey = 'social_roles_' + (typeof _resolveSocialWorldKey === 'function' ? _resolveSocialWorldKey(s) : 'modern');
        var roles = (typeof window._rotatingExemplars === 'function') ? window._rotatingExemplars(roleKey, rolePool, castSize) : rolePool.slice(0, castSize);
