              // collapsed to the same 3 every story. If cast ≤ slots, it just uses all.
              var _ffSEKey = 'sb_ff_socialeco_off_' + ((typeof _ffCharKey === 'function') ? _ffCharKey(_pcN) : 'ff');
              var _ffOff = 0;
              try { _ffOff = (parseInt(localStorage.getItem(_ffSEKey) || '0', 10) || 0); } catch (_) {}
              var _ffPicked = [];
