        s._socialEventResolved = true;
        s._socialEvent = null;
        var tier = String(s.storyLength || s.tier || 'fling').toLowerCase();
        if (/taste|fling/.test(tier)) return null;   // needs setup→turn room across issues
        var shape = (typeof window._storyShape === 'function') ? window._storyShape(s) : 'STRAIGHT';
        var arc = (s.storySpine && s.storySpine.worldArcs && s.storySpine.worldArcs[0]) || null;
