        if (arc) (_SOCIAL_EVENT_BY_WORLDARC[arc] || []).forEach(function (k) { if (pool.indexOf(k) === -1) pool.push(k); });
        if (!pool.length) return null;                 // shape/arc doesn't license betrayal — none, by design
