        var TRUST_W = { LOYALIST: 2.2, PROTECTOR: 2.0, SACRIFICE_VOICE: 1.6, MATCHMAKER: 1.6, ACCELERATOR: 1.4, TEMPTER: 1.2, CHAOS_AGENT: 1.1, TRUTH_TELLER: 1.0, BRAKE: 0.9, RIVAL_VOICE: 0.6, SKEPTIC: 0.5 };
        var weights = members.map(function (m, i) { return (TRUST_W[m.fnKey] || 1) * (i === 0 ? 1.4 : 1); });
        var total = weights.reduce(function (a, b) { return a + b; }, 0);
        var r = Math.random() * total, idx = 0;
        for (var i = 0; i < members.length; i++) { r -= weights[i]; if (r <= 0) { idx = i; break; } }
        var timing = (arc === 'BETRAYAL_WITHIN') ? _SOCIAL_EVENT_TIMING._arc_BETRAYAL_WITHIN : (_SOCIAL_EVENT_TIMING[shape] || _SOCIAL_EVENT_TIMING._default);
        s._socialEvent = { eventKey: evKey, event: ev, memberIndex: idx, member: members[idx], timing: timing, shape: shape, arc: arc };
        try { console.log('[SOCIAL-EVENT] ' + members[idx].role + ' (fn ' + members[idx].fnKey + ') → ' + evKey + ' @ ' + (arc || shape)); } catch (_) {}
