          (ap.namedClock ? 'CLOCK: ' + String(ap.namedClock).slice(0, 120) + '\n' : '') +
          '\nReturn ONLY this JSON:\n{\n  "family": "<one of: Institutional | Criminal | Romantic | Family | Survival | Mystery | Political | Adventure | Social | Reputational>",\n  "subtype": "<2-4 word label>",\n  "reason": "<one sentence: what mechanism actually drives the stakes>"\n}';
        var res = await _auditPost({ temperature: 0.2, max_tokens: 200, messages: [ { role: 'system', content: sys }, { role: 'user', content: usr } ] });
        if (!res.ok) { try { console.warn('[A-PLOT:CONFLICT-FAMILY] HTTP ' + res.status); } catch (_) {} return null; }
