          desireHot: (typeof extra.desireHot === 'number') ? extra.desireHot : null,
          desireTarget: extra.desireTarget || '',
          desireRomanPct: (typeof extra.desireRomanPct === 'number') ? extra.desireRomanPct : null,
          // OWNERSHIP fields (Roman 2026-06-05) — these were already computed per-run
          // ([R-PLOT:OWNERSHIP] / [SCENE1:DESIRE-TARGET] / [ROMAN:MODE] / [WOUND→SOURCE])
