          rplotTrueRomancePct: (typeof extra.rplotTrueRomancePct === 'number') ? extra.rplotTrueRomancePct : null,
          rplotSelfDirected: (typeof extra.rplotSelfDirected === 'number') ? extra.rplotSelfDirected : null,
