          woundSourcePct: (typeof extra.woundSourcePct === 'number') ? extra.woundSourcePct : null,
          woundSourceOwnsGravity: (extra.woundSourceOwnsGravity == null) ? null : !!extra.woundSourceOwnsGravity,
          romanModeWanting: (typeof extra.romanModeWanting === 'number') ? extra.romanModeWanting : null,
          romanModeObject: (typeof extra.romanModeObject === 'number') ? extra.romanModeObject : null,
