        if (!Array.isArray(arr) || !arr.length) { console.warn('[COLD-OWNERSHIP] ledger empty — play more stories.'); return { total: 0 }; }
        var withDesire = arr.filter(function (e) { return e && e.desireVerdict; });
        var cold = withDesire.filter(function (e) { return e.desireVerdict === 'COLD'; });
        var warm = withDesire.filter(function (e) { return e.desireVerdict && e.desireVerdict !== 'COLD'; });
