    'my hero academia': 'lytharyn', 'my hero': 'lytharyn', 'academia': 'lytharyn', 'ua high': 'lytharyn',
    'wizarding school': 'lytharyn', 'magic academy': 'lytharyn', 'mage academy': 'lytharyn',
    'sorcery school': 'lytharyn', 'witch academy': 'lytharyn', 'witch school': 'lytharyn',
