    // GLOAMWATER BAY — Kwisheen, sea magic, mythic ocean
    'atlantis': 'gloamwater_bay', 'ariel': 'gloamwater_bay', 'kwisheen': 'gloamwater_bay',
    'underwater city': 'gloamwater_bay', 'sea kingdom': 'gloamwater_bay',
