    // PULSE POINT — mercantile port, trade hub
    'trade city': 'pulse_point', 'merchant city': 'pulse_point', 'port city': 'pulse_point',
    'market city': 'pulse_point', 'freeport': 'pulse_point', 'bazaar': 'pulse_point',
