    'mordor': 'fates_favor', 'the blight': 'fates_favor',

    // THE ASHEN VERGE — war-torn wasteland, apocalypse, reality collapse, the Fold
    'wasteland': 'the_ashen_verge', 'apocalypse': 'the_ashen_verge',
