    var _ab = state.systems.narrativeActors.absolvers;
    if (!_ab) _ab = state.systems.narrativeActors.absolvers = { active: false, encounterCount: 0 };
    if (state._absolversActive !== undefined) _ab.active = !!state._absolversActive;
    if (state._absolversEncounterCount !== undefined) _ab.encounterCount = state._absolversEncounterCount || 0;
    state._absolversActive = _ab.active;
    state._absolversEncounterCount = _ab.encounterCount;

    // ── Chorus (Glass House): derive from worldSubtype pick
    if (!state.systems.worldSystems) state.systems.worldSystems = {};
    var _ch = state.systems.worldSystems.chorus;
    if (!_ch) _ch = state.systems.worldSystems.chorus = { active: false, tier: 0 };
    var _isGlassHouse = state.picks && state.picks.worldSubtype === 'glass_house';
    _ch.active = !!_isGlassHouse;
    if (_ch.active) {
      // tier 1 = Scene 1 (full bible), tier 2 = Scene 2+ (compressed anchor)
      _ch.tier = (!state.turnCount || state.turnCount === 0) ? 1 : 2;
    } else {
      _ch.tier = 0;
    }

    // ── Narrative Voice: derive from state.povMode, enforce mutual exclusion ──
    if (!state.systems.narrativeVoice) state.systems.narrativeVoice = {};
    var _p4 = state.systems.narrativeVoice.pov4th;
    if (!_p4) _p4 = state.systems.narrativeVoice.pov4th = { active: false, chorusOverride: false };
    var _p5 = state.systems.narrativeVoice.pov5th;
    if (!_p5) _p5 = state.systems.narrativeVoice.pov5th = { active: false };

