  /**
   * Type-aware system activation check.
   * @param {string} type — 'narrativeActors', 'worldSystems', or 'narrativeVoice'
   * @param {string} name — system name within that type
   * @returns {boolean}
   */
  function _isSystemActive(type, name) {
    _syncSystemRegistry();
    var layer = state.systems[type];
    if (!layer) return false;
    var sys = layer[name];
    if (!sys) return false;

    if (type === 'narrativeActors') {
      // Actors have type-specific activation logic
      if (name === 'keepers') return sys.presence && sys.presence !== 'none';
      return !!sys.active || (sys.encounterCount || 0) > 0;
    }
    if (type === 'worldSystems') {
      return !!sys.active;
    }
    if (type === 'narrativeVoice') {
      return !!sys.active;
    }
    return false;
  }

  /** Backward-compatible alias — narrative actors only */
  function _isActorActive(name) {
    return _isSystemActive('narrativeActors', name);
  }

  /**
   * Check if ANY narrative actor or world system is active (for token scaling).
   * @returns {boolean}
   */
  function _hasActiveComplexSystems() {
    _syncSystemRegistry();
    var actors = state.systems.narrativeActors || {};
    for (var k in actors) {
      if (actors.hasOwnProperty(k) && _isSystemActive('narrativeActors', k)) return true;
    }
    var worlds = state.systems.worldSystems || {};
    for (var k in worlds) {
      if (worlds.hasOwnProperty(k) && _isSystemActive('worldSystems', k)) return true;
    }
    return false;
  }

  /**
   * Debug snapshot of all active systems. Call per scene for visibility.
   * @returns {object} { actors: [...], world: [...], voice: [...] }
   */
  function _activeSystemsDebug() {
    _syncSystemRegistry();
    var result = { actors: [], world: [], voice: [] };
    var actors = state.systems.narrativeActors || {};
    for (var k in actors) {
      if (actors.hasOwnProperty(k) && _isSystemActive('narrativeActors', k)) {
        var sys = actors[k];
        result.actors.push(k + '(' + (sys.presence || (sys.active ? 'active' : 'enc:' + sys.encounterCount)) + ')');
      }
    }
    var worlds = state.systems.worldSystems || {};
    for (var k in worlds) {
      if (worlds.hasOwnProperty(k) && _isSystemActive('worldSystems', k)) {
        result.world.push(k);
      }
    }
    var voices = state.systems.narrativeVoice || {};
    for (var k in voices) {
      if (voices.hasOwnProperty(k) && _isSystemActive('narrativeVoice', k)) {
        var vsys = voices[k];
        var label = k;
        if (k === 'pov4th' && vsys.chorusOverride) label += '+chorus';
        result.voice.push(label);
      }
    }
    return result;
  }

