  /**
   * Assign a Thornwild transformation path based on species, tone, and randomness.
   * Called when player or LI is Thornwild-affiliated.
   */
  function _assignThornwildPath(targetState) {
    if (targetState._thornwildPath) return; // already assigned
    var tone = (state.picks?.tone || '').toLowerCase();
    var roll = Math.random();

    // Tone biases path selection
    if (tone === 'dark' || tone === 'gothic') {
      // Horror-leaning → brood emphasis
      if (roll < 0.20) targetState._thornwildPath = 'cycle_bound';
      else if (roll < 0.50) targetState._thornwildPath = 'drift_bound';
      else targetState._thornwildPath = 'brood_bound';
    } else if (tone === 'earnest' || tone === 'literary') {
      // Character-driven → drift emphasis
      if (roll < 0.30) targetState._thornwildPath = 'cycle_bound';
      else if (roll < 0.70) targetState._thornwildPath = 'drift_bound';
      else targetState._thornwildPath = 'brood_bound';
    } else {
      // Default balanced
      if (roll < 0.40) targetState._thornwildPath = 'cycle_bound';
      else if (roll < 0.75) targetState._thornwildPath = 'drift_bound';
      else targetState._thornwildPath = 'brood_bound';
    }

    targetState._thornwildStage = 'latent';
    targetState._firstSignTriggered = false;
    targetState._firstSignType = null;
    targetState._thornwildCureTaboo = true;
    targetState._thornwildResponse = null;
    targetState._isRootless = false;
    targetState._pursuitLevel = 'none';
    targetState._escapeTarget = null;
    targetState._transformationPressure = 0;
    targetState._pressureStage = 'low';

    console.log('[THORNWILD] Path assigned:', targetState._thornwildPath, '(tone: ' + tone + ')');
  }

  /**
   * Select a First Sign type for the given path. Called once when first sign triggers.
   */
  function _selectFirstSign(path) {
    var pathData = _THORNWILD_PATHS[path];
    if (!pathData || !pathData.first_signs) return null;
    return pathData.first_signs[Math.floor(Math.random() * pathData.first_signs.length)];
  }

  // ── Transformation Pressure Base Rates ──
  var _TRANSFORMATION_PRESSURE_BASE = {
    cycle_bound: 5,
    drift_bound: 6,
    brood_bound: 8
  };

  /**
   * Get the current pressure stage label from a pressure value.
   */
  function _getPressureStage(pressure) {
    if (pressure < 30) return 'low';
    if (pressure < 65) return 'rising';
    if (pressure < 85) return 'high';
    return 'critical';
  }

  /**
   * Advance transformation pressure. Called each scene for Thornwild-affiliated characters.
   * Non-linear: base ± variance + random surge events.
   * Respects scene driver priority — suppresses spikes during higher-priority scenes.
   * Critical stage triggers countdown to forced resolution.
   * @returns {{ stage: string, pressureEvent: string|null, surge: boolean, criticalCountdown: number|null }}
   */
  function _advanceTransformationPressure() {
    if (!state._thornwildPath) return { stage: 'none', pressureEvent: null, surge: false, criticalCountdown: null };
    if (state._transformationPressure === undefined) state._transformationPressure = 0;

    var base = _TRANSFORMATION_PRESSURE_BASE[state._thornwildPath] || 5;
    var gain = base;

    // ── Non-linear variance: base ± random(-2 to +3) ──
    gain += Math.floor(Math.random() * 6) - 2; // range: -2 to +3

    // Response modifiers
    var resp = state._thornwildResponse;
    if (resp === 'deny') gain += 3;
    else if (resp === 'hide') gain += 2;
    else if (resp === 'accept') gain -= 2;

    // Context modifiers
    var rk = _resolveRegionKey(state.fantasyRegion || '');
    if (rk === 'the_thornwild') gain += 5;

    // ── Scene driver integration (soft suppression) ──
    var driver = state._sceneDriver || 'baseline';
    var highPriorityScene = (driver === 'reveal' || driver === 'post_reveal' || driver === 'almost_caught');
    var surge = false;

    if (!highPriorityScene) {
      // ── Full surge: 10–20% chance, +5 to +10 ──
      var surgeChance = 0.10 + Math.random() * 0.10;
      if (Math.random() < surgeChance) {
        var surgeAmount = 5 + Math.floor(Math.random() * 6);
        gain += surgeAmount;
        surge = true;
        console.log('[THORNWILD:PRESSURE] SURGE +' + surgeAmount);
      }
    } else {
      // ── Soft suppression: reduced surge (5–10% chance, +2 to +5) ──
      var softSurgeChance = 0.05 + Math.random() * 0.05;
      if (Math.random() < softSurgeChance) {
        var softSurgeAmount = 2 + Math.floor(Math.random() * 4);
        gain += softSurgeAmount;
        surge = true;
        console.log('[THORNWILD:PRESSURE] SOFT SURGE +' + softSurgeAmount + ' (during ' + driver + ')');
      }
    }

    // Clamp gain to at least +1
    gain = Math.max(1, gain);

    state._transformationPressure = Math.min(100, state._transformationPressure + gain);

    // Floor: once First Sign occurs, pressure can never return to zero
    if (state._firstSignTriggered && state._transformationPressure < 15) {
      state._transformationPressure = 15;
    }

    // Derive stage
    var prevStage = state._pressureStage;
    state._pressureStage = _getPressureStage(state._transformationPressure);

    // ── Critical countdown: initialize on first entry to critical ──
    if (state._pressureStage === 'critical' && state._criticalCountdown === undefined) {
      state._criticalCountdown = 1 + Math.floor(Math.random() * 3); // 1–3 scenes
      console.log('[THORNWILD:PRESSURE] Critical countdown initialized:', state._criticalCountdown, 'scenes');
    }

    // ── Critical countdown tick — always advances while pressure ≥85 ──
    var forcedResolution = false;
    if (state._criticalCountdown !== undefined && state._criticalCountdown !== null) {
      if (state._pressureStage === 'critical') {
        // Countdown ticks EVERY scene regardless of driver — urgency is inescapable
        state._criticalCountdown--;
        if (state._criticalCountdown <= 0) {
          forcedResolution = true;
          console.log('[THORNWILD:PRESSURE] CRITICAL COUNTDOWN REACHED ZERO — forced resolution (driver: ' + driver + ')');
        } else {
          console.log('[THORNWILD:PRESSURE] Critical countdown:', state._criticalCountdown, 'remaining (driver: ' + driver + ')');
        }
      }
    }

    // Check for stage-transition events
    var pressureEvent = null;
    if (forcedResolution) {
      pressureEvent = 'forced_resolution';
    } else if (state._transformationPressure >= 85 && state._thornwildStage !== 'advanced') {
      pressureEvent = 'critical_threshold';
    } else if (state._transformationPressure >= 65 && state._thornwildStage === 'first_sign') {
      pressureEvent = 'progression_threshold';
    } else if (state._transformationPressure >= 30 && state._thornwildStage === 'latent') {
      pressureEvent = 'first_sign_eligible';
    }

    console.log('[THORNWILD:PRESSURE]', state._transformationPressure, '(' + state._pressureStage + ')', pressureEvent || '', surge ? 'SURGE' : '');
    return { stage: state._pressureStage, pressureEvent: pressureEvent, surge: surge, criticalCountdown: state._criticalCountdown };
  }

  /**
   * Apply limited pressure relief. Cannot return to zero after First Sign.
   * @param {number} amount — relief amount (typical: 5–15)
   */
  function _relieveTransformationPressure(amount) {
    if (state._transformationPressure === undefined) return;
    var floor = state._firstSignTriggered ? 15 : 0;
    state._transformationPressure = Math.max(floor, state._transformationPressure - (amount || 5));
    state._pressureStage = _getPressureStage(state._transformationPressure);
    console.log('[THORNWILD:PRESSURE] Relief applied, now:', state._transformationPressure, '(' + state._pressureStage + ')');
  }

  // ══════════════════════════════════════════════════════════════════════
  // SCENE DRIVER SYSTEM
  // Ensures only ONE dominant narrative driver controls each scene.
  // Priority order (highest → lowest):
  //   almost_caught > reveal > post_reveal > transformation > encounter >
  //   suspicion > transit > baseline
  // ══════════════════════════════════════════════════════════════════════

  var _DRIVER_PRIORITY = [
    'almost_caught',   // 1 — overrides everything
    'reveal',          // 2 — identity exposure moment
    'post_reveal',     // 3 — reaction behavior locked
    'transformation',  // 4 — critical pressure only (≥85)
    'encounter',       // 5 — external event
    'suspicion',       // 6 — subtle dialogue shifts
    'transit',         // 7 — progression only
    'baseline'         // 8 — default
  ];

  // Driver descriptions for prompt injection
  var _DRIVER_DESCRIPTIONS = {
    almost_caught:  'HIGH-PRESSURE INTERCEPTION. Pursuers nearly caught the protagonist. Immediate threat, vulnerability, environmental constraint. Overrides all other narrative concerns.',
    reveal:         'IDENTITY REVEAL. The protagonist\'s true nature is being exposed. This scene is about that moment ONLY — no external distractions, no unrelated encounters. Focus entirely on the reveal and its immediate emotional impact.',
    post_reveal:    'POST-REVEAL REACTION. The Love Interest is processing the revelation. Enforce the current reaction state (accept/reject/obsession/weaponize) through every line of dialogue and physical interaction. Emotional continuity is paramount.',
    transformation: 'TRANSFORMATION CRISIS. Pressure has reached critical levels. Internal and physical focus — the body is demanding attention. Loss of control, visible changes, or imminent event. Other characters react to what they see.',
    encounter:      'ENCOUNTER. An external event shaped by the current region\'s signature. The encounter is the scene\'s primary tension. Other systems provide background texture only.',
    suspicion:      'SUSPICION ESCALATION. The Love Interest is noticing inconsistencies. Tension comes through dialogue shifts and behavioral probing. No structural interruptions — the scene\'s surface appears normal while subtext carries the weight.',
    transit:        'TRANSIT PROGRESSION. The journey continues. Movement, terrain, distance. Low narrative weight — focus on the physical experience of travel. Other systems are dormant this scene.',
    baseline:       'BASELINE. No dominant system is active. Write a character-driven scene focused on relationship development, world exploration, or plot advancement. Pacing should breathe.'
  };

  /**
   * Evaluate all active systems and select the highest-priority scene driver.
   * Respects cooldowns, starvation prevention, post-reveal softening, and encounter guarantees.
   * Low-tier drivers (suspicion, transit, baseline) can blend — see _sceneDriverBlend.
   * @returns {string} — the selected driver name
   */
  function _resolveSceneDriver() {
    state._sceneDriverCooldowns = state._sceneDriverCooldowns || {};
    state._driverUsageHistory = state._driverUsageHistory || [];
    state._encounterStarvationCounter = state._encounterStarvationCounter || 0;
    state._postRevealSceneCount = state._postRevealSceneCount || 0;
    state._driverLastForced = state._driverLastForced || null;
    state._driverForceCooldown = state._driverForceCooldown || 0;

    // Tick cooldowns
    for (var cd in state._sceneDriverCooldowns) {
      if (state._sceneDriverCooldowns[cd] > 0) state._sceneDriverCooldowns[cd]--;
    }
    if (state._driverForceCooldown > 0) state._driverForceCooldown--;

    // ── Post-reveal softening: track scenes since reveal ──
    if (state._identityRevealed && state._liReactionLocked) {
      state._postRevealSceneCount++;
    }
    var postRevealSoftened = state._postRevealSceneCount > 2;

    // ── Variety bonus: check if last 3 drivers were all different ──
    var recentVariety = false;
    if (state._driverUsageHistory.length >= 3) {
      var last3 = state._driverUsageHistory.slice(-3);
      recentVariety = (last3[0] !== last3[1] && last3[1] !== last3[2] && last3[0] !== last3[2]);
    }

    // ── Starvation detection: same driver ≥3 of last 4 scenes ──
    var starvedBoost = null;
    if (state._driverUsageHistory.length >= 4 && !recentVariety) {
      var recent4 = state._driverUsageHistory.slice(-4);
      var counts = {};
      for (var h = 0; h < recent4.length; h++) {
        counts[recent4[h]] = (counts[recent4[h]] || 0) + 1;
      }
      for (var dh in counts) {
        if (counts[dh] >= 3) {
          var dominated = _DRIVER_PRIORITY.indexOf(dh);
          for (var bp = dominated + 1; bp < _DRIVER_PRIORITY.length; bp++) {
            if (_DRIVER_PRIORITY[bp] !== 'baseline') {
              starvedBoost = _DRIVER_PRIORITY[bp];
              break;
            }
          }
          break;
        }
      }
    }

    // ── Anti-oscillation: don't re-boost a recently forced driver ──
    if (starvedBoost && state._driverForceCooldown > 0 && starvedBoost === state._driverLastForced) {
      console.log('[SCENE-DRIVER] Anti-oscillation: suppressing re-boost of', starvedBoost);
      starvedBoost = null;
    }

    // ── Encounter starvation tracking ──
    if ((state._travelPressure || 0) >= 60 && (state._encounterCooldown || 0) <= 0) {
      state._encounterStarvationCounter++;
    } else {
      state._encounterStarvationCounter = 0;
    }

    // ── Evaluate eligibility (highest priority first) ──
    var eligible = null;

    // 1. almost_caught — absolute override
    if (!eligible && state._transitInterrupted && !state._sceneDriverCooldowns.almost_caught) {
      eligible = 'almost_caught';
    }

    // 2. reveal — absolute override
    if (!eligible && state._revealEligible && !state._identityRevealed && !state._sceneDriverCooldowns.reveal) {
      if ((state._liSuspicionLevel || 0) >= 70) {
        eligible = 'reveal';
      }
    }

    // 3. post_reveal — full priority for 2 scenes, then softened
    if (!eligible && state._identityRevealed && state._liReactionLocked && !state._sceneDriverCooldowns.post_reveal) {
      if (!postRevealSoftened) {
        eligible = 'post_reveal';
      }
    }

    // 4. transformation (critical only)
    if (!eligible && (state._transformationPressure || 0) >= 85 && !state._sceneDriverCooldowns.transformation) {
      eligible = 'transformation';
    }

    // 5. encounter — soft force with grace window, near-miss memory, context check
    state._encounterGrace = state._encounterGrace || 0;
    state._encounterNearMisses = state._encounterNearMisses || 0;
    if (state._encounterGrace > 0) state._encounterGrace--;

    if (!eligible) {
      var encounterEligible = (state._travelPressure || 0) >= 60 && (state._encounterCooldown || 0) <= 0;
      // Context check: don't force during high-emotional windows
      var encounterBlocked = (!postRevealSoftened && state._identityRevealed && state._liReactionLocked) ||
                              (state._sceneDriverCooldowns.transformation && (state._transformationPressure || 0) >= 85);
      if (encounterEligible && encounterBlocked) {
        // Delayed — set grace window so encounter doesn't burst immediately after
        state._encounterGrace = 1;
        console.log('[SCENE-DRIVER] Encounter delayed (context block, grace set, starvation:', state._encounterStarvationCounter + ')');
      } else if (encounterEligible && !encounterBlocked) {
        // Grace window cap: after a delay, don't immediately burst
        var graceCap = state._encounterGrace > 0 ? 0.65 : 1.0;

        if (state._encounterStarvationCounter >= 5) {
          // Hard force — but soft landing via prompt injection
          eligible = 'encounter';
          state._encounterHardForced = true;
          state._encounterNearMisses = 0;
          console.log('[SCENE-DRIVER] Encounter HARD forced (starvation:', state._encounterStarvationCounter + ')');
        } else if (state._encounterStarvationCounter >= 3) {
          // Soft force: base 80–90% + near-miss bonus, capped at 95%, further capped by grace
          var nearMissBonus = (state._encounterNearMisses || 0) * 0.05;
          var softProb = Math.min(0.95, 0.80 + Math.random() * 0.10 + nearMissBonus) * graceCap;
          if (Math.random() < softProb) {
            eligible = 'encounter';
            state._encounterNearMisses = 0;
            state._encounterHardForced = false;
            console.log('[SCENE-DRIVER] Encounter SOFT forced (' + Math.round(softProb * 100) + '%, misses:', state._encounterNearMisses + ')');
          } else {
            // Near-miss: didn't fire despite eligibility
            state._encounterNearMisses++;
            console.log('[SCENE-DRIVER] Encounter near-miss #' + state._encounterNearMisses + ' (prob was ' + Math.round(softProb * 100) + '%)');
          }
        } else {
          eligible = 'encounter';
          state._encounterHardForced = false;
          state._encounterNearMisses = 0;
        }
      }
    }

    // 5b. softened post_reveal
    if (!eligible && postRevealSoftened && state._identityRevealed && state._liReactionLocked && !state._sceneDriverCooldowns.post_reveal) {
      eligible = 'post_reveal';
    }

    // 6. suspicion
    if (!eligible && !state._identityRevealed && (state._liSuspicionLevel || 0) >= 25) {
      eligible = 'suspicion';
    }

    // 7. transit
    if (!eligible && state._isInTransit) {
      eligible = 'transit';
    }

    // 8. baseline
    if (!eligible) {
      eligible = 'baseline';
    }

    // ── Starvation boost override (with anti-oscillation) ──
    if (starvedBoost && eligible !== 'almost_caught' && eligible !== 'reveal') {
      var boostValid = false;
      if (starvedBoost === 'encounter' && ((state._travelPressure || 0) >= 60 || state._encounterStarvationCounter >= 3)) boostValid = true;
      else if (starvedBoost === 'transformation' && (state._transformationPressure || 0) >= 85) boostValid = true;
      else if (starvedBoost === 'suspicion' && !state._identityRevealed && (state._liSuspicionLevel || 0) >= 25) boostValid = true;
      else if (starvedBoost === 'transit' && state._isInTransit) boostValid = true;
      if (boostValid) {
        console.log('[SCENE-DRIVER] Starvation boost: ' + eligible + ' → ' + starvedBoost);
        eligible = starvedBoost;
        // Anti-oscillation: record forced driver and set cooldown
        state._driverLastForced = starvedBoost;
        state._driverForceCooldown = 2;
      }
    }

    // ── Apply cooldowns for major drivers ──
    if (eligible === 'almost_caught') {
      state._sceneDriverCooldowns.almost_caught = 999;
    } else if (eligible === 'reveal') {
      state._sceneDriverCooldowns.reveal = 2;
    } else if (eligible === 'transformation') {
      state._sceneDriverCooldowns.transformation = 2;
    }
    if (eligible === 'encounter') {
      state._encounterStarvationCounter = 0;
    }

    // ── Low-tier blending ──
    state._sceneDriverBlend = null;
    if (eligible === 'baseline' || eligible === 'transit') {
      if (!state._identityRevealed && (state._liSuspicionLevel || 0) >= 25) {
        state._sceneDriverBlend = 'suspicion';
      }
    }
    if (eligible === 'transit') {
      if (!state._sceneDriverBlend) state._sceneDriverBlend = 'baseline';
    }

    // ── Record history ──
    state._driverUsageHistory.push(eligible);
    if (state._driverUsageHistory.length > 10) state._driverUsageHistory.shift();

    state._sceneDriver = eligible;
    console.log('[SCENE-DRIVER] Selected:', eligible, state._sceneDriverBlend ? '(blend: ' + state._sceneDriverBlend + ')' : '', recentVariety ? '(variety bonus active)' : '');
    return eligible;
  }

  /**
   * Select an escape destination based on player psychology and narrative tone.
   */
  function _selectEscapeDestination() {
    var tone = (state.picks?.tone || '').toLowerCase();
    var destinations = Object.keys(_THORNWILD_ESCAPE_DESTINATIONS);
    // Tone-biased selection
    if (tone === 'dark' || tone === 'gothic') return 'the_ashen_verge';
    if (tone === 'literary') return 'the_veilwood';
    // Random from pool
    return destinations[Math.floor(Math.random() * destinations.length)];
  }

  // ══════════════════════════════════════════════════════════════════════
  // LI VISIBILITY HIERARCHY — Mystery-First Male Face System
  // The man who matters most is the hardest to fully see.
  // Only PRIMARY_LI gets the face mystery system. Others are visible.
  // ══════════════════════════════════════════════════════════════════════

  // Visibility roles
  var LI_ROLE = { PRIMARY: 'PRIMARY_LI', SECONDARY: 'SECONDARY_LI', TERTIARY: 'TERTIARY_LI', UNKNOWN: 'UNKNOWN_ENTITY', NON_LI_MYSTERY: 'NON_LI_MYSTERY' };

  // Signature visibility modes — each active LI must have a UNIQUE mode
  // Determines HOW identity is expressed visually, not just whether face is shown.
  var SIG_MODE = { SHADOW: 'SHADOW', EYES: 'EYES', HANDS: 'HANDS', MOUTH: 'MOUTH', FULL_FACE: 'FULL_FACE' };

  // Signature shape profiles — silhouette differentiation layer
  // Each active LI must have a unique shape. Readable even in full shadow.
  var SIG_SHAPE = { TALL_LINEAR: 'TALL_LINEAR', BROAD_HEAVY: 'BROAD_HEAVY', LEAN_ANGULAR: 'LEAN_ANGULAR', COMPACT_CONTROLLED: 'COMPACT_CONTROLLED' };

  // Shape profile rendering descriptions
  var _SHAPE_DIRECTIVES = {};
  _SHAPE_DIRECTIVES[SIG_SHAPE.TALL_LINEAR] = 'tall vertical silhouette, still upright posture, narrow shoulders, elongated proportions';
  _SHAPE_DIRECTIVES[SIG_SHAPE.BROAD_HEAVY] = 'wide grounded silhouette, powerful build, squared shoulders, low center of gravity';
  _SHAPE_DIRECTIVES[SIG_SHAPE.LEAN_ANGULAR] = 'sharp angular silhouette, forward-leaning posture, kinetic energy, defined edges';
  _SHAPE_DIRECTIVES[SIG_SHAPE.COMPACT_CONTROLLED] = 'contained compact silhouette, precise minimal movement, tight posture, economical presence';

  // Single-LI mode rotation pool and tracking
  var _SINGLE_LI_ROTATION = [SIG_MODE.SHADOW, SIG_MODE.EYES, SIG_MODE.HANDS, SIG_MODE.MOUTH];

  // Face visibility states (PRIMARY_LI only)
  // 0 = obscured (shadow/silhouette/turned away)
  // 1 = partial (jaw, mouth, profile — no full frontal)
  // 2 = near-reveal (most features visible, one key element withheld)
  // 3 = revealed (full face rendered)
  var FACE_STATE = { OBSCURED: 0, PARTIAL: 1, NEAR_REVEAL: 2, REVEALED: 3 };

  // ─────────────────────────────────────────────────────────────────────
  // MYSTERY MAN ELIGIBILITY GATE
  // ─────────────────────────────────────────────────────────────────────
  // Mystery Man concealment is the romance-novel trope of the unattainable
  // mystery male — it ONLY applies when the audience-fantasy axis is "PC
  // attracted to a male LI." Specifically: female PC + male LI.
  //
  // For every other dynamic (M/F where the LI is female, F/F, M/M), the LI
  // should be visible from scene 1: there's no cultural-fantasy reason to
  // conceal them, and concealment actively hurts those story types by
  // dehumanizing the LI as a faceless object.
  //
  // This helper is the SINGLE source of truth. Any system that gates on
  // "should this LI be hidden?" must consult this function.
  function _isMysteryManEligibleLI(liId) {
    if (!state) return false;
    // LI-POV COMPANION EDITION (Roman 2026-06-21): the edition is narrated BY the LI,
    // so he cannot be a "Mystery Man" concealed from his own narration. Hard-disable
    // concealed framing here regardless of revealed-state — the prior code relied only
    // on the `!revealed` gate, which is incidental, not a rule.
    if (state.altPOVEdition === 'LI') return false;
    // Resolve PC gender (lowercased).
    var pcGender = String(state.gender || state.playerGender || state.picks?.gender || 'female').toLowerCase();
    // Resolve this LI's gender. For the primary LI we have multiple
    // possible sources; prefer per-candidate data, fall back to top-level.
    var liGender = '';
    if (liId && state.liCandidates) {
      var cand = state.liCandidates.find(function(c) { return c.id === liId; });
      if (cand && cand.liGender) liGender = String(cand.liGender).toLowerCase();
    }
    if (!liGender) {
      liGender = String(state.loveInterest || state.loveInterestGender || _defaultLIGenderForPC(state)).toLowerCase();
    }
    // Mystery Man fires only for the heterosexual female-PC + male-LI combo.
    return (pcGender === 'female' && liGender === 'male');
  }
  window._isMysteryManEligibleLI = _isMysteryManEligibleLI;

  /**
   * Initialize or update LI visibility roles based on current story state.
   * Called when LI candidates change or attraction shifts.
   */
  function _updateLIVisibilityRoles() {
    var vis = state.liFaceVisibility || {};
    var primaryId = state.currentPrimaryLiId;
    var sceneIdx = state.turnCount || 0;

    // ── MODE PERSISTENCE LOCK ──
    // Modes are assigned once per scene. If already assigned for this scene,
    // skip reassignment to prevent mid-scene mode changes.
    // Reassignment triggers: new scene (turnCount changed) OR active LI count changed.
    var prevLockScene = state._liModeLockScene;
    var prevLICount = state._liModeLockCount;
    var currentLICount = (state.liCandidates || []).length;
    if (prevLockScene === sceneIdx && prevLICount === currentLICount) {
      return; // modes already locked for this scene — no changes
    }
    state._liModeLockScene = sceneIdx;
    state._liModeLockCount = currentLICount;

    // Auto-detect primary from liDominantCandidateId or loveInterestName
    if (!primaryId) {
      primaryId = state.liDominantCandidateId || state.loveInterestName || null;
      if (primaryId) state.currentPrimaryLiId = primaryId;
    }

    // ── Shape profile pool ──
    var availableShapes = [SIG_SHAPE.TALL_LINEAR, SIG_SHAPE.BROAD_HEAVY, SIG_SHAPE.LEAN_ANGULAR, SIG_SHAPE.COMPACT_CONTROLLED];
    var usedShapes = {};

    // Set primary LI — default signature: SHADOW, assign shape if missing.
    // MM ELIGIBILITY: only female-PC + male-LI dynamics start concealed.
    // All other dynamics start at REVEALED (face visible from scene 1).
    if (primaryId && !vis[primaryId]) {
      var pShape = availableShapes[0]; usedShapes[pShape] = true;
      var _mmEligible = (typeof _isMysteryManEligibleLI === 'function')
          ? _isMysteryManEligibleLI(primaryId)
          : true;
      var _initFaceState = _mmEligible ? FACE_STATE.OBSCURED : FACE_STATE.REVEALED;
      vis[primaryId] = { role: LI_ROLE.PRIMARY, faceState: _initFaceState, sigMode: SIG_MODE.SHADOW, sigShape: pShape, transitionScene: null };
      try { console.log('[LI:FACE] init primary ' + primaryId + ' → ' + (_mmEligible ? 'OBSCURED (MM eligible: female PC + male LI)' : 'REVEALED (MM not applicable)')); } catch (_) {}
    } else if (primaryId && vis[primaryId]) {
      vis[primaryId].role = LI_ROLE.PRIMARY;
      if (!vis[primaryId].sigMode) vis[primaryId].sigMode = SIG_MODE.SHADOW;
      if (!vis[primaryId].sigShape) { vis[primaryId].sigShape = availableShapes[0]; }
      usedShapes[vis[primaryId].sigShape] = true;
    }

    // Count active secondary LIs to determine single vs multi-LI mode
    var candidates = state.liCandidates || [];
    var activeLICount = candidates.filter(function(c) { return c.id !== primaryId; }).length;
    var isSingleLI = activeLICount === 0;

    // ── Single-LI mode: PRIMARY rotates through all signature modes per scene ──
    if (isSingleLI && primaryId && vis[primaryId]) {
      var rotIdx = state._liSigRotationIdx || 0;
      vis[primaryId].sigMode = _SINGLE_LI_ROTATION[rotIdx % _SINGLE_LI_ROTATION.length];
      state._liSigRotationIdx = rotIdx + 1;
    }

    // ── Multi-LI mode: each LI gets exactly one exclusive mode ──
    var usedModes = {};
    if (primaryId && vis[primaryId]) usedModes[vis[primaryId].sigMode] = true;
    // In multi-LI, primary keeps SHADOW; in single-LI, it rotates (set above)
    if (!isSingleLI && primaryId && vis[primaryId]) {
      vis[primaryId].sigMode = SIG_MODE.SHADOW;
      usedModes[SIG_MODE.SHADOW] = true;
    }
    var availableModes = [SIG_MODE.EYES, SIG_MODE.HANDS, SIG_MODE.MOUTH, SIG_MODE.FULL_FACE];

    for (var ci = 0; ci < candidates.length; ci++) {
      var cid = candidates[ci].id;
      if (cid === primaryId) continue;
      if (!vis[cid]) {
        // Assign unique mode + shape
        var mode = SIG_MODE.FULL_FACE;
        for (var mi = 0; mi < availableModes.length; mi++) {
          if (!usedModes[availableModes[mi]]) { mode = availableModes[mi]; break; }
        }
        usedModes[mode] = true;
        var shape = SIG_SHAPE.BROAD_HEAVY;
        for (var si = 0; si < availableShapes.length; si++) {
          if (!usedShapes[availableShapes[si]]) { shape = availableShapes[si]; break; }
        }
        usedShapes[shape] = true;
        vis[cid] = { role: LI_ROLE.SECONDARY, faceState: FACE_STATE.REVEALED, sigMode: mode, sigShape: shape, transitionScene: null };
      } else if (vis[cid].role === LI_ROLE.PRIMARY && cid !== primaryId) {
        vis[cid].role = LI_ROLE.SECONDARY;
        vis[cid].faceState = FACE_STATE.REVEALED;
        if (!vis[cid].sigMode || vis[cid].sigMode === SIG_MODE.SHADOW) {
          for (var mi2 = 0; mi2 < availableModes.length; mi2++) {
            if (!usedModes[availableModes[mi2]]) { vis[cid].sigMode = availableModes[mi2]; usedModes[availableModes[mi2]] = true; break; }
          }
        }
        if (!vis[cid].sigShape) {
          for (var si2 = 0; si2 < availableShapes.length; si2++) {
            if (!usedShapes[availableShapes[si2]]) { vis[cid].sigShape = availableShapes[si2]; usedShapes[availableShapes[si2]] = true; break; }
          }
        }
      }
      if (vis[cid]) {
        if (vis[cid].sigMode) usedModes[vis[cid].sigMode] = true;
        if (vis[cid].sigShape) usedShapes[vis[cid].sigShape] = true;
      }
    }

    // External suitors / temptations → tertiary (FULL_FACE, remaining shape)
    var temptations = state.activeTemptations || [];
    for (var ti = 0; ti < temptations.length; ti++) {
      var tid = temptations[ti].characterId;
      if (tid && !vis[tid] && tid !== primaryId) {
        var tShape = SIG_SHAPE.COMPACT_CONTROLLED;
        for (var si3 = 0; si3 < availableShapes.length; si3++) {
          if (!usedShapes[availableShapes[si3]]) { tShape = availableShapes[si3]; break; }
        }
        usedShapes[tShape] = true;
        vis[tid] = { role: LI_ROLE.TERTIARY, faceState: FACE_STATE.REVEALED, sigMode: SIG_MODE.FULL_FACE, sigShape: tShape, transitionScene: null };
      }
    }

    state.liFaceVisibility = vis;
  }

  /**
   * Add a NON_LI_MYSTERY presence to the scene.
   * Max 10-20% of scenes. Must resolve within 1-3 scenes.
   * Cannot coexist with obscured PRIMARY_LI in the same panel.
   */
  function _addNonLIMystery(characterId) {
    var vis = state.liFaceVisibility || {};
    var sceneIdx = state.turnCount || 0;
    var totalScenes = Math.max(sceneIdx, 1);

    // Frequency cap: max ~15% of scenes
    if (state._nonLiMysteryCount / totalScenes > 0.15 && totalScenes >= 5) {
      console.log('[LI:MYSTERY] Frequency cap reached (' + state._nonLiMysteryCount + '/' + totalScenes + ')');
      return false;
    }

    // Assign shape that differs from PRIMARY_LI
    var primaryShape = (primaryId && vis[primaryId]) ? vis[primaryId].sigShape : null;
    var mysteryShape = SIG_SHAPE.BROAD_HEAVY; // default different from TALL_LINEAR primary default
    var allShapes = [SIG_SHAPE.BROAD_HEAVY, SIG_SHAPE.COMPACT_CONTROLLED, SIG_SHAPE.LEAN_ANGULAR, SIG_SHAPE.TALL_LINEAR];
    for (var msi = 0; msi < allShapes.length; msi++) {
      if (allShapes[msi] !== primaryShape) { mysteryShape = allShapes[msi]; break; }
    }
    vis[characterId] = { role: LI_ROLE.NON_LI_MYSTERY, faceState: FACE_STATE.OBSCURED, sigMode: SIG_MODE.SHADOW, sigShape: mysteryShape, transitionScene: null, _resolveByScene: sceneIdx + 3 };
    state._nonLiMysteryCount++;
    state.liFaceVisibility = vis;
    console.log('[LI:MYSTERY] Added ' + characterId + ' (resolve by scene ' + (sceneIdx + 3) + ')');
    return true;
  }

  /**
   * Resolve a NON_LI_MYSTERY — either reveal identity or remove from scene.
   */
  function _resolveNonLIMystery(characterId, newRole) {
    var vis = state.liFaceVisibility || {};
    var entry = vis[characterId];
    if (!entry || entry.role !== LI_ROLE.NON_LI_MYSTERY) return;

    if (newRole === LI_ROLE.PRIMARY || newRole === LI_ROLE.SECONDARY) {
      // Promote to LI role — must go through _shiftPrimaryLI or manual assignment
      entry.role = newRole;
      entry.faceState = newRole === LI_ROLE.PRIMARY ? FACE_STATE.OBSCURED : FACE_STATE.REVEALED;
      console.log('[LI:MYSTERY] ' + characterId + ' resolved → ' + newRole);
    } else {
      // Remove from tracking
      delete vis[characterId];
      console.log('[LI:MYSTERY] ' + characterId + ' removed from scene');
    }
    state.liFaceVisibility = vis;
  }

  /**
   * Advance PRIMARY_LI face visibility state.
   * Called per scene. Progression depends on intimacy level and scene count.
   */
  function _advanceFaceVisibility() {
    var primaryId = state.currentPrimaryLiId;
    if (!primaryId) return;
    var vis = state.liFaceVisibility || {};
    var entry = vis[primaryId];
    if (!entry || entry.role !== LI_ROLE.PRIMARY) return;
    if (entry.faceState >= FACE_STATE.REVEALED) return; // already revealed

    // MM ELIGIBILITY GATE: non-MM-eligible LIs are initialized at REVEALED
    // and never need progression. The early-return above catches them, but
    // double-check for safety in case state was migrated/loaded mid-story.
    if (typeof _isMysteryManEligibleLI === 'function' && !_isMysteryManEligibleLI(primaryId)) {
      if (entry.faceState !== FACE_STATE.REVEALED) {
        entry.faceState = FACE_STATE.REVEALED;
        try { console.log('[LI:FACE] ' + primaryId + ' force-promoted to REVEALED — non-MM-eligible LI shouldn\'t be concealed'); } catch (_) {}
        vis[primaryId] = entry;
        state.liFaceVisibility = vis;
      }
      return;
    }

    var sceneIdx = state.turnCount || 0;
    var intimacy = state.intimacyLevel || 0;
    // ST4 gate: REVEALED transition is locked behind ST4 (Consequence Taken).
    // Pre-ST4, NEAR_REVEAL is the ceiling — face partially visible enough to
    // read emotion, but not unambiguously identifiable. ST4 is the canonical
    // narrative gate for irreversible identity disclosure.
    var _currentSt = String(state.storyturn || 'ST1');
    var _stIdx = (function() {
      var m = _currentSt.match(/ST(\d+)/i);
      return m ? parseInt(m[1], 10) : 1;
    })();
    var _atOrPastST4 = _stIdx >= 4;

    // Progression triggers:
    // 0 → 1: after 2+ scenes of interaction
    // 1 → 2: after intimacy reaches moderate level (3+) or 5+ scenes
    // 2 → 3: after high intimacy (5+) or explicit narrative reveal moment AND ST4+
    if (entry.faceState === FACE_STATE.OBSCURED && sceneIdx >= 2) {
      entry.faceState = FACE_STATE.PARTIAL;
      console.log('[LI:FACE] ' + primaryId + ' → PARTIAL (scene ' + sceneIdx + ')');
    } else if (entry.faceState === FACE_STATE.PARTIAL && (intimacy >= 3 || sceneIdx >= 5)) {
      entry.faceState = FACE_STATE.NEAR_REVEAL;
      console.log('[LI:FACE] ' + primaryId + ' → NEAR_REVEAL (scene ' + sceneIdx + ', intimacy ' + intimacy + ')');
    } else if (entry.faceState === FACE_STATE.NEAR_REVEAL && (intimacy >= 5 || sceneIdx >= 8)) {
      // ST4 gate: even if intimacy/scene thresholds are met, hold at NEAR_REVEAL
      // until storyturn reaches ST4. The face-reveal modal then fires on ST4
      // entry to let the user describe + lock the LI's appearance.
      if (!_atOrPastST4) {
        try { console.log('[LI:FACE] ' + primaryId + ' REVEAL withheld (st=' + _currentSt + ', not yet ST4) — holding at NEAR_REVEAL'); } catch (_) {}
      } else {
        entry.faceState = FACE_STATE.REVEALED;
        console.log('[LI:FACE] ' + primaryId + ' → REVEALED (scene ' + sceneIdx + ', intimacy ' + intimacy + ', st=' + _currentSt + ')');
        // Trigger the face-reveal modal (player describes + locks the look).
        // Modal handles its own state transitions; this is a fire-and-forget.
        if (typeof _maybeOpenLiFaceRevealModal === 'function') {
          try { _maybeOpenLiFaceRevealModal(primaryId); } catch (_e) { console.warn('[LI:FACE] reveal modal trigger failed:', _e && _e.message); }
        }
      }
    }

    vis[primaryId] = entry;
    state.liFaceVisibility = vis;
  }

  /**
   * Handle attraction shift: reassign primary LI.
   * Previous primary locks at revealed. New primary transitions to obscured over 1-2 scenes.
   */
  function _shiftPrimaryLI(newPrimaryId) {
    var oldPrimaryId = state.currentPrimaryLiId;
    if (oldPrimaryId === newPrimaryId) return;
    var vis = state.liFaceVisibility || {};
    var sceneIdx = state.turnCount || 0;

    // Lock old primary at revealed
    if (oldPrimaryId && vis[oldPrimaryId]) {
      vis[oldPrimaryId].role = LI_ROLE.SECONDARY;
      vis[oldPrimaryId].faceState = FACE_STATE.REVEALED;
      console.log('[LI:SHIFT] ' + oldPrimaryId + ' → SECONDARY (locked at revealed)');
    }

    // New primary: gradual re-obscuration over 2 scenes
    if (!vis[newPrimaryId]) {
      vis[newPrimaryId] = { role: LI_ROLE.PRIMARY, faceState: FACE_STATE.REVEALED, transitionScene: sceneIdx };
    } else {
      vis[newPrimaryId].role = LI_ROLE.PRIMARY;
      vis[newPrimaryId].transitionScene = sceneIdx;
      // Don't instantly obscure — start transition from current state
    }

    // Queue gradual transition: revealed → near_reveal → partial over next 2 scenes
    state._liFaceTransitionQueue = [{ fromId: oldPrimaryId, toId: newPrimaryId, startScene: sceneIdx }];
    state.currentPrimaryLiId = newPrimaryId;
    state.liFaceVisibility = vis;
    console.log('[LI:SHIFT] New primary: ' + newPrimaryId + ' (transition from scene ' + sceneIdx + ')');
  }

  /**
   * Process pending face transitions (called per scene).
   */
  function _processFaceTransitions() {
    var queue = state._liFaceTransitionQueue || [];
    if (!queue.length) return;
    var vis = state.liFaceVisibility || {};
    var sceneIdx = state.turnCount || 0;
    var remaining = [];

    for (var qi = 0; qi < queue.length; qi++) {
      var t = queue[qi];
      var entry = vis[t.toId];
      if (!entry) continue;
      var elapsed = sceneIdx - t.startScene;

      if (elapsed >= 2) {
        // Transition complete — now at obscured, resume normal progression
        entry.faceState = FACE_STATE.OBSCURED;
        entry.transitionScene = null;
        console.log('[LI:TRANSITION] ' + t.toId + ' transition complete → OBSCURED');
      } else if (elapsed === 1) {
        entry.faceState = FACE_STATE.PARTIAL;
      } else {
        entry.faceState = FACE_STATE.NEAR_REVEAL;
        remaining.push(t);
      }
    }

    state._liFaceTransitionQueue = remaining;

    // Auto-expire NON_LI_MYSTERY entries past their resolve deadline
    var sceneNow = state.turnCount || 0;
    for (var mid in vis) {
      if (vis[mid].role === LI_ROLE.NON_LI_MYSTERY && vis[mid]._resolveByScene && sceneNow >= vis[mid]._resolveByScene) {
        console.log('[LI:MYSTERY] ' + mid + ' auto-expired at scene ' + sceneNow);
        delete vis[mid];
      }
    }

    state.liFaceVisibility = vis;
  }

  /**
   * Get the face visibility state for a character.
   * Returns the faceState (0-3) or REVEALED by default for non-primary.
   */
  function _getFaceVisibility(characterId) {
    if (!characterId) return FACE_STATE.REVEALED;
    var vis = state.liFaceVisibility || {};
    var entry = vis[characterId];
    if (!entry) return FACE_STATE.REVEALED;
    return entry.faceState;
  }

  /**
   * Get the visibility role for a character.
   */
  function _getLIVisibilityRole(characterId) {
    if (!characterId) return LI_ROLE.TERTIARY;
    var vis = state.liFaceVisibility || {};
    var entry = vis[characterId];
    return entry ? entry.role : LI_ROLE.TERTIARY;
  }

  /**
   * Build GN rendering directives for face visibility per character.
   * Returns prompt text to inject into GN panel prompts.
   */
  function _buildFaceVisibilityDirectives() {
    var vis = state.liFaceVisibility || {};
    var primaryId = state.currentPrimaryLiId;
    if (!primaryId && Object.keys(vis).length === 0) return '';

    var entry = primaryId ? vis[primaryId] : null;
    var directives = [];
    var sigMode = entry ? (entry.sigMode || SIG_MODE.SHADOW) : SIG_MODE.SHADOW;
    var hasObscuredPrimary = entry && entry.faceState < FACE_STATE.REVEALED;

    // ── SHAPE PROFILES: inject silhouette differentiation for all active LIs ──
    for (var shapeId in vis) {
      var sv = vis[shapeId];
      if (sv.sigShape && _SHAPE_DIRECTIVES[sv.sigShape]) {
        directives.push('BODY SILHOUETTE (' + shapeId + '): ' + _SHAPE_DIRECTIVES[sv.sigShape] + '. Must be visually distinct from all other male figures.');
      }
    }

    // ── PRIMARY_LI: signature mode modulates how face state is expressed ──
    if (entry && entry.faceState < FACE_STATE.REVEALED) {
      if (sigMode === SIG_MODE.SHADOW) {
        switch (entry.faceState) {
          case FACE_STATE.OBSCURED:
            directives.push('PRIMARY MALE CHARACTER: Fully obscured via shadow, backlighting, or turned-away angle. NO frontal face visible. Identity carried through silhouette, posture, and body language.');
            break;
          case FACE_STATE.PARTIAL:
            directives.push('PRIMARY MALE CHARACTER: Jaw, mouth, or profile visible through shadow. Eyes and upper face remain in darkness. Identity through body and partial features.');
            break;
          case FACE_STATE.NEAR_REVEAL:
            directives.push('PRIMARY MALE CHARACTER: Most features visible through thinning shadow, one element withheld — eyes still in darkness, or a slight turn away.');
            break;
        }
      } else if (sigMode === SIG_MODE.EYES) {
        switch (entry.faceState) {
          case FACE_STATE.OBSCURED:
            directives.push('PRIMARY MALE CHARACTER: Eyes barely visible in darkness — twin points of light or sharp glints. Rest of face and body in deep shadow. Eyes are the only identity anchor.');
            break;
          case FACE_STATE.PARTIAL:
            directives.push('PRIMARY MALE CHARACTER: Eyes clearly visible with intense gaze, high contrast lighting around them. Rest of face softly hidden or cropped. Eyes dominate framing.');
            break;
          case FACE_STATE.NEAR_REVEAL:
            directives.push('PRIMARY MALE CHARACTER: Strong eye visibility with partial facial structure emerging around them. Eyes remain the dominant visual anchor even as more face appears.');
            break;
        }
      } else if (sigMode === SIG_MODE.HANDS) {
        switch (entry.faceState) {
          case FACE_STATE.OBSCURED:
            directives.push('PRIMARY MALE CHARACTER: Face not shown — cropped above shoulders or turned fully away. Identity expressed through hands: grip, gesture, tension, touch. Hands are detailed and expressive.');
            break;
          case FACE_STATE.PARTIAL:
            directives.push('PRIMARY MALE CHARACTER: Face at edge of frame or partially cropped. Hands remain the primary visual anchor with detailed fingers and interaction. Lower face may be visible.');
            break;
          case FACE_STATE.NEAR_REVEAL:
            directives.push('PRIMARY MALE CHARACTER: Face mostly visible but hands still draw the eye through physical action or proximity. Hands remain a signature element even as face emerges.');
            break;
        }
      } else if (sigMode === SIG_MODE.MOUTH) {
        switch (entry.faceState) {
          case FACE_STATE.OBSCURED:
            directives.push('PRIMARY MALE CHARACTER: Only mouth and jawline faintly visible in shadow or tight crop. Eyes and upper face completely hidden. Expression conveyed through lips, breath, and jaw tension.');
            break;
          case FACE_STATE.PARTIAL:
            directives.push('PRIMARY MALE CHARACTER: Mouth, jaw, and lower face clearly rendered in close framing. Lips and jawline are the identity anchor. Eyes remain cropped or in shadow. Intimate, not wide.');
            break;
          case FACE_STATE.NEAR_REVEAL:
            directives.push('PRIMARY MALE CHARACTER: Lower face fully visible with mouth as dominant feature. Upper face emerging but mouth remains the visual anchor — expression reads through lips and jaw even as eyes appear.');
            break;
        }
      }
    }

    // ── SECONDARY LIs: signature-mode-specific rendering ──
    for (var cid in vis) {
      if (cid === primaryId) continue;
      var cv = vis[cid];
      if (cv.role === LI_ROLE.SECONDARY) {
        var sm = cv.sigMode || SIG_MODE.FULL_FACE;
        if (sm === SIG_MODE.EYES) {
          directives.push('SECONDARY CHARACTER (' + cid + '): Face visible but eyes are the dominant visual anchor. Framing prioritizes intense gaze. High contrast lighting around eyes. Clear distinguishing features.');
        } else if (sm === SIG_MODE.HANDS) {
          directives.push('SECONDARY CHARACTER (' + cid + '): Face visible. Hands are a signature element — detailed, expressive, often in foreground interaction. Clear distinguishing features.');
        } else if (sm === SIG_MODE.MOUTH) {
          directives.push('SECONDARY CHARACTER (' + cid + '): Face visible with mouth and jawline as signature anchor. Close or mid-close framing preferred. Expression reads through lips and lower face. Clear distinguishing features.');
        } else {
          directives.push('SECONDARY CHARACTER (' + cid + '): Face fully visible. Attractive but grounded realism. Clear distinguishing features from other characters.');
        }
      } else if (cv.role === LI_ROLE.UNKNOWN) {
        directives.push('UNKNOWN FIGURE (' + cid + '): Fully obscured. Silhouette or deep shadow only. No facial identity.');
      } else if (cv.role === LI_ROLE.NON_LI_MYSTERY) {
        // NON_LI_MYSTERY: obscured but NOT romanticized, visually distinct from PRIMARY_LI silhouette
        directives.push('NON-ROMANTIC OBSCURED FIGURE (' + cid + '): Face hidden via shadow or silhouette. Non-romantic framing — ambiguous intent, neither threatening nor safe. Body language readable but NOT stylized. Must be visually distinguishable from any romantic silhouette (different build, posture, or positioning).');
      }
    }

    // ── Multi-LI composition rules ──
    var activeCount = Object.keys(vis).length;
    if (activeCount > 1) {
      // Only one obscured figure per panel
      if (hasObscuredPrimary) {
        directives.push('COMPOSITION: Only the primary romantic focus may have an obscured face. All other characters must have clearly visible, distinct faces.');
        // If NON_LI_MYSTERY is also present, it must be partially clarified
        for (var mid in vis) {
          if (vis[mid].role === LI_ROLE.NON_LI_MYSTERY && hasObscuredPrimary) {
            directives.push('PANEL SAFETY: Since primary character is obscured, the non-romantic mystery figure (' + mid + ') must be partially clarified or positioned out of this panel to avoid visual confusion.');
          }
        }
      }
      // Distinct anchors rule
      directives.push('MULTI-CHARACTER RULE: Each character must be identifiable via a different visual anchor (silhouette, eyes, hands, mouth, or full face). No two characters may share the same anchor type in one panel. EYES and MOUTH anchors must not compete in the same focal region — separate them spatially.');
    }

    return directives.length > 0 ? '\n' + directives.join('\n') + '\n' : '';
  }

  // Expose for GN prompt assembly
  window._updateLIVisibilityRoles = _updateLIVisibilityRoles;
  window._advanceFaceVisibility = _advanceFaceVisibility;
  window._shiftPrimaryLI = _shiftPrimaryLI;
  window._processFaceTransitions = _processFaceTransitions;
  window._getFaceVisibility = _getFaceVisibility;
  window._getLIVisibilityRole = _getLIVisibilityRole;
  window._buildFaceVisibilityDirectives = _buildFaceVisibilityDirectives;
  window.LI_ROLE = LI_ROLE;
  window.FACE_STATE = FACE_STATE;
  window.SIG_MODE = SIG_MODE;
  window.SIG_SHAPE = SIG_SHAPE;
  window._addNonLIMystery = _addNonLIMystery;
  window._resolveNonLIMystery = _resolveNonLIMystery;

  // ══════════════════════════════════════════════════════════════════════
  // PRE-REVEAL SUSPICION + RELATIONSHIP MEMORY SYSTEM
  // Tracks LI suspicion buildup, stores reveal snapshot, maintains history.
  // ══════════════════════════════════════════════════════════════════════

  /**
   * Initialize suspicion and relationship tracking. Called once.
   */
  function _initSuspicionState() {
    if (state._liSuspicionLevel !== undefined) return;
    state._liSuspicionLevel = 0;
    state._liSuspicionTriggers = [];
    state._relationshipHistory = [];
    state._liPreRevealBelief = null;
  }

  /**
   * Increment LI suspicion. Called by scene hooks when triggers fire.
   * @param {number} amount — suspicion increment (0–25 typical)
   * @param {string} trigger — description of what caused it
   */
  function _incrementSuspicion(amount, trigger) {
    if (state._identityRevealed) return; // post-reveal: suspicion is moot
    state._liSuspicionLevel = Math.min(100, Math.max(0, (state._liSuspicionLevel || 0) + amount));
    if (trigger) {
      state._liSuspicionTriggers = state._liSuspicionTriggers || [];
      state._liSuspicionTriggers.push({ trigger: trigger, level: state._liSuspicionLevel, scene: state.turnCount || 0 });
    }
    // Record in relationship history
    _appendRelationshipEvent('suspicion_spike', trigger + ' (→' + state._liSuspicionLevel + ')');
    console.log('[SUSPICION] Level:', state._liSuspicionLevel, 'trigger:', trigger);
  }

  /**
   * Snapshot suspicion state at reveal moment.
   */
  function _capturePreRevealBelief() {
    state._liPreRevealBelief = {
      suspicionLevel: state._liSuspicionLevel || 0,
      emotionalTone: _getSuspicionTone(state._liSuspicionLevel || 0),
      trustLevelEstimate: state._liSuspicionLevel < 30 ? 'high' : state._liSuspicionLevel < 60 ? 'moderate' : 'low'
    };
    _appendRelationshipEvent('reveal', 'identity revealed at suspicion ' + (state._liSuspicionLevel || 0));
    console.log('[SUSPICION] Pre-reveal belief captured:', state._liPreRevealBelief);
  }

  function _getSuspicionTone(level) {
    if (level < 25) return 'mild_curiosity';
    if (level < 60) return 'uneasy_questioning';
    if (level < 85) return 'active_suspicion';
    return 'near_certainty';
  }

  function _appendRelationshipEvent(type, description) {
    state._relationshipHistory = state._relationshipHistory || [];
    state._relationshipHistory.push({ type: type, desc: description, scene: state.turnCount || 0 });
    // Cap history at 50 events
    if (state._relationshipHistory.length > 50) state._relationshipHistory.shift();
  }

  // ══════════════════════════════════════════════════════════════════════
  // TRANSIT + ESCAPE JOURNEY SYSTEM
  // Ties Thornwild escape to map loupe movement over multiple scenes.
  // ══════════════════════════════════════════════════════════════════════

  /**
   * Initialize transit state when character flees Thornwild.
   */
  function _initTransitState() {
    if (!state._escapeTarget) {
      state._escapeTarget = _selectEscapeDestination();
    }
    state._isInTransit = true;
    state._transitOrigin = 'the_thornwild';
    state._transitDestination = state._escapeTarget;
    state._transitProgress = 0;
    state._almostCaughtTriggered = false;
    state._transitInterrupted = false;
    if (!state._pursuitLevel || state._pursuitLevel === 'none') {
      state._pursuitLevel = 'active';
    }
    console.log('[TRANSIT] Initialized: ' + state._transitOrigin + ' → ' + state._transitDestination + ' (pursuit: ' + state._pursuitLevel + ')');
  }

  /**
   * Advance transit progress. Called each scene during transit.
   * @returns {{ arrived: boolean, intercepted: boolean }}
   */
  function _advanceTransit() {
    if (!state._isInTransit) return { arrived: false, intercepted: false };

    var result = { arrived: false, intercepted: false };

    // Check for Almost Caught interception
    if (!state._almostCaughtTriggered &&
        state._transitProgress >= 0.65 && state._transitProgress <= 0.8 &&
        (state._pursuitLevel === 'active' || state._pursuitLevel === 'relentless')) {
      state._almostCaughtTriggered = true;
      state._transitInterrupted = true;
      // Escalate pursuit
      if (state._pursuitLevel === 'active') state._pursuitLevel = 'relentless';
      // Slight progress penalty
      state._transitProgress = Math.max(0, state._transitProgress - 0.05);
      _appendRelationshipEvent('almost_caught', 'intercepted at progress ' + state._transitProgress.toFixed(2));
      console.log('[TRANSIT] ALMOST CAUGHT — pursuit escalated to:', state._pursuitLevel);
      result.intercepted = true;
      return result; // stall for this scene
    }

    // Clear interruption flag
    state._transitInterrupted = false;

    // Normal progress
    var increment = 0.2 + Math.random() * 0.2; // 0.2–0.4
    // Pursuit slows progress
    if (state._pursuitLevel === 'relentless') increment *= 0.7;
    else if (state._pursuitLevel === 'active') increment *= 0.85;

    state._transitProgress = Math.min(1.0, state._transitProgress + increment);

    // Check arrival
    if (state._transitProgress >= 1.0) {
      state._isInTransit = false;
      state._fatelandsCurrentLocation = state._transitDestination;
      state.fantasyRegion = state._transitDestination;
      _appendRelationshipEvent('arrival', 'reached ' + state._transitDestination);
      console.log('[TRANSIT] ARRIVED at:', state._transitDestination);
      result.arrived = true;
    }

    return result;
  }

  // ══════════════════════════════════════════════════════════════════════
  // PRESSURE-BASED ENCOUNTER SYSTEM
  // Replaces random encounters with pressure accumulation + release.
  // ══════════════════════════════════════════════════════════════════════

  function _initTravelPressure() {
    if (state._travelPressure !== undefined) return;
    state._travelPressure = 0;
    state._encounterCooldown = 0;
  }

  /**
   * Accumulate travel pressure based on current state. Called each scene.
   * @returns {{ encounter: boolean, type: string|null, intensity: string|null }}
   */
  function _advanceTravelPressure() {
    _initTravelPressure();
    var result = { encounter: false, type: null, intensity: null };

    // Cooldown tick
    if (state._encounterCooldown > 0) {
      state._encounterCooldown--;
    }

    // ── Pressure accumulation ──
    var gain = 0;
    // Pursuit
    var pl = state._pursuitLevel || 'none';
    if (pl === 'low') gain += 5;
    else if (pl === 'active') gain += 12;
    else if (pl === 'relentless') gain += 20;
    // Identity status
    if (state._identityRevealed) gain += 15;
    else if ((state._liSuspicionLevel || 0) > 50) gain += 10;
    else if (state._playerSpecies && state._playerSpecies !== 'Human') gain += 5;
    // Dangerous region
    var rk = _resolveRegionKey(state.fantasyRegion || '');
    if (rk === 'the_thornwild' || rk === 'the_ashen_verge') gain += 10;
    if (rk === 'the_shackle_isles') gain += 5;

    state._travelPressure = Math.min(100, state._travelPressure + gain);

    // ── Pressure decay from safe context ──
    // (Handled by caller — call _decayTravelPressure() after safe scenes)

    // ── Encounter trigger ──
    if (state._travelPressure >= 60 && state._encounterCooldown <= 0) {
      // Select encounter type based on region signature
      result.encounter = true;
      result.type = _selectEncounterType(rk);
      // Intensity from pressure level
      if (state._travelPressure >= 85) result.intensity = 'near_failure';
      else if (state._travelPressure >= 70) result.intensity = 'dangerous';
      else result.intensity = 'tense';
      // Reset
      state._travelPressure = 30 + Math.floor(Math.random() * 10);
      state._encounterCooldown = 2;
      _appendRelationshipEvent('encounter', result.type + ' (' + result.intensity + ')');
      console.log('[ENCOUNTER]', result.type, 'at intensity', result.intensity);
    }

    return result;
  }

  function _decayTravelPressure(amount) {
    state._travelPressure = Math.max(0, (state._travelPressure || 0) - (amount || 10));
  }

  function _selectEncounterType(regionKey) {
    var sig = _REGION_ENCOUNTER_SIGNATURES[regionKey];
    var types = sig ? sig.encounter_types : ['pursuit', 'environmental', 'social', 'internal'];
    return types[Math.floor(Math.random() * types.length)];
  }

