        var _pcArchKey = ((state.picks && (state.picks.playermask || state.picks.playerMask)) || state.playerMask || state.playermask || '').toString().toUpperCase().replace(/[^A-Z_]/g, '');
        var _pcProfileForAche = (typeof _PC_NARRATOR_ARCHETYPE_PROFILES !== 'undefined' && _PC_NARRATOR_ARCHETYPE_PROFILES[_pcArchKey]) || null;
