      if (!questionLine || questionLine.length < 6) {
          return text.replace(re, '\n\n').trim();
      }

      // Canonical form: "Is this best [A] or [B]?"
      // Extract:
      //   • stem (noun-phrase between "Is this " and the first "[")
      //   • optionA / optionB (bracketed contents)
      //   • cleanQuestion (question with literal brackets stripped — what the
      //     reader sees, with bracketed segments wrapped as pills by the
      //     existing inline-pill renderer)
      // The committed-line builder in the existing hydrator (line ~141189)
      // detects noun-phrase stems via the regex extended in this commit to
      // include "best", and produces "This is <stem> <A>, not <B>." form.
      // For "Is this best [growled in the ear] or [said with eyes and hands]?":
      //   stem = "best"
      //   optionA = "growled in the ear"
      //   optionB = "said with eyes and hands"
      //   cleanQuestion = "Is this best growled in the ear or said with eyes and hands?"
      //   commit line = "This is best growled in the ear, not said with eyes and hands."
      var stem = '';
      var optionA = '';
      var optionB = '';
      var stripped = questionLine
          .replace(/^\s*is\s+this\s+/i, '')
          .replace(/\s*[\?\.]+\s*$/, '')
          .trim();
      var firstBracket = stripped.indexOf('[');
      if (firstBracket > 0) {
          stem = stripped.slice(0, firstBracket).trim();
      }
      var bracketRe = /\[([^\]]+)\]/g;
      var bracketHits = [];
      var bm;
      while ((bm = bracketRe.exec(inner)) !== null) {
          bracketHits.push(bm[1].trim());
      }
      if (bracketHits.length >= 2) {
          optionA = bracketHits[0];
          optionB = bracketHits[1];
      }

      // Fallback path — if LLM didn't follow canonical form, try " — or " / " or "
      // splits on the stripped question and accept whatever's there. Won't have a
      // clean stem, so committed line falls back to the noun-led non-stem form
      // ("This is X, not Y.") via the existing builder.
      if (!optionA || !optionB) {
          if (/—\s*or\s+/i.test(stripped) || /\s+or\s+/i.test(stripped)) {
              var parts = stripped.split(/\s*—\s*or\s+|\s+or\s+/i);
              if (parts.length >= 2) {
                  optionA = (parts[0] || '').replace(/^.*?(?:best|something(?:\s+to\s+be)?)\s*/i, '').trim() || optionA;
                  optionB = (parts[1] || '').replace(/[?.]+$/, '').trim() || optionB;
              }
          }
      }
      if (!optionA || !optionB) {
          // Couldn't parse — strip the block to avoid rendering a malformed probe.
          return text.replace(re, '\n\n').trim();
      }

      // Strip literal brackets from the question text — the reader must NEVER
      // see "[" or "]" around the pills. The inline-pill hydrator finds the
      // bracketless A/B labels in the cleaned question and wraps them as pills.
      var cleanQuestion = questionLine.replace(/\[([^\]]+)\]/g, '$1');

      // Build placeholder. data-mode="scene_expression_mode" → existing hydrator
      // click handler routes to the axis-aware code path below. data-axis
      // identifies WHICH axis the click should write to (voice / intensity /
      // control / tempo). data-stem enables noun-phrase stem committed-line
      // rendering for stems "best" (added to detector regex).
      var ph = '<div class="scene1-micro-expr scene1-micro-expr-transitional"' +
               ' data-mode="scene_expression_mode" data-placement="tail"' +
               ' data-axis="' + _attrTransExpr(resolvedAxis) + '"' +
               ' data-q="' + _attrTransExpr(cleanQuestion) + '"' +
               (stem ? ' data-stem="' + _attrTransExpr(stem) + '"' : '') +
               ' data-a="' + _attrTransExpr(optionA) + '"' +
               ' data-b="' + _attrTransExpr(optionB) + '"></div>';
