  // ============================================================
  // DEV HUD — Casual English command console (developer only)
  // Never saves to localStorage, never unlocks real features,
  // never affects other users, never ships to production.
  // ============================================================

  (function initDevHud() {
      const isDev = typeof _isQaHost === 'function' ? _isQaHost() :
          (location.hostname === 'localhost' || location.hostname === '127.0.0.1');
      if (!isDev) return;

      const hudEl = document.getElementById('devHud');
      const inputEl = document.getElementById('devHudInput');
      const logEl = document.getElementById('devHudLog');
      if (!hudEl || !inputEl) return;

      let _devOverrides = {};
      let _logTimer = null;

      function log(msg) {
          if (!logEl) return;
          logEl.textContent = msg;
          logEl.style.opacity = '1';
          clearTimeout(_logTimer);
          _logTimer = setTimeout(() => { logEl.style.opacity = '0'; }, 5000);
          console.log('[DevHUD]', msg);
      }

      function toggle() {
          hudEl.classList.toggle('dev-hud-visible');
          if (hudEl.classList.contains('dev-hud-visible')) {
              inputEl.focus();
          }
      }

      // Toggle with backtick key (only when not typing elsewhere)
      document.addEventListener('keydown', (e) => {
          if (e.key === '`' && !e.ctrlKey && !e.metaKey) {
              const tag = (document.activeElement?.tagName || '').toLowerCase();
              const isEditable = tag === 'input' || tag === 'textarea' || document.activeElement?.isContentEditable;
              if (isEditable && document.activeElement !== inputEl) return;
              e.preventDefault();
              toggle();
          }
      });

      inputEl.addEventListener('keydown', (e) => {
          if (e.key === 'Enter') {
              const raw = inputEl.value.trim();
              if (raw) execute(raw.toLowerCase());
              inputEl.value = '';
          }
          if (e.key === 'Escape') toggle();
      });
      // Prevent backtick from typing into the input
      inputEl.addEventListener('keypress', (e) => {
          if (e.key === '`') e.preventDefault();
      });

      // --- Extraction maps ---
      const WORLD_MAP = {
          fantasy: 'Fantasy', historical: 'Historical', modern: 'Modern',
          'sci-fi': 'SciFi', scifi: 'SciFi', dystopia: 'Dystopia',
          'post-apocalyptic': 'PostApocalyptic', postapocalyptic: 'PostApocalyptic',
          supernatural: 'Supernatural', superheroic: 'Superheroic'
      };
      const GENRE_MAP = {
          billionaire: 'Billionaire', crime: 'CrimeSyndicate', noir: 'Noir',
          heist: 'Heist', espionage: 'Espionage', political: 'Political',
          survival: 'Survival', obsession: 'Obsession', forbidden: 'ForbiddenKnowledge',
          'forbidden knowledge': 'ForbiddenKnowledge'
      };
      const ARCHETYPE_MAP = {
          'heart warden': 'HEART_WARDEN', 'open vein': 'OPEN_VEIN',
          'spellbinder': 'SPELLBINDER', 'armored fox': 'ARMORED_FOX',
          'dark vice': 'DARK_VICE', 'beautiful ruin': 'BEAUTIFUL_RUIN',
          'eternal flame': 'ETERNAL_FLAME'
      };

      // ========================================
      // DETERMINISTIC COMMAND REGISTRY (v1)
      // NO fuzzy matching. NO synonyms. NO NLP.
      // ========================================
      const DEV_CMD_REGISTRY = {
          world: ['Modern', 'Historical', 'Fantasy', 'SciFi', 'Dystopia', 'PostApocalyptic'],
          genre: ['CrimeSyndicate', 'Billionaire', 'Noir', 'Heist', 'Espionage', 'Political',
                  'Escape', 'Redemption', 'BuildingBridges', 'Purgatory', 'RelentlessPast',
                  'Sports', 'Survival', 'Obsession', 'ForbiddenKnowledge'],
          tone: ['Earnest', 'WryConfession', 'Dark', 'Mythic'],
          dynamic: ['Proximity', 'SecretIdentity', 'Friends', 'Enemies',
                    'SecondChance', 'Forbidden']
      };

      // Case-insensitive lookup for canonical value
      function resolveCanonical(axis, input) {
          const list = DEV_CMD_REGISTRY[axis];
          if (!list) return null;
          const lower = input.toLowerCase();
          return list.find(v => v.toLowerCase() === lower) || null;
      }

      // Deterministic command parser (space-split, no regex magic)
      function parseDevCommand(raw) {
          const parts = raw.trim().split(/\s+/);
          if (parts.length === 0) return null;

          // ALIAS: "regen book cover" → "regen cover"
          if (parts[0] === 'regen' && parts[1] === 'book' && parts[2] === 'cover') {
              return { cmd: 'regen', target: 'cover' };
          }
          // COMMAND: "regen cover"
          if (parts[0] === 'regen' && parts[1] === 'cover') {
              return { cmd: 'regen', target: 'cover' };
          }
          // COMMAND: "set <axis> <value>"
          if (parts[0] === 'set' && parts.length >= 3) {
              const axis = parts[1];
              const value = parts.slice(2).join(' ');
              return { cmd: 'set', axis, value };
          }
          // Not a registry command
          return null;
      }

      // Execute deterministic command (returns true if handled)
      function executeRegistryCommand(input) {
          const parsed = parseDevCommand(input);
          if (!parsed) return false;

          // REGEN COVER (gated by coverEligibility)
          if (parsed.cmd === 'regen' && parsed.target === 'cover') {
              const world = state.picks?.world || 'Modern';
              const genre = state.picks?.genre || 'Billionaire';
              const intensity = state.intensity || 'Naughty';
              const rawTitle = document.getElementById('storyTitle')?.textContent?.trim() || '';
              const title = (rawTitle && rawTitle !== 'Untitled') ? rawTitle : '';

              // ════════════════════════════════════════════════════════════════
              // MINIMAL COVER v1 GUARD — Skip PHASE_1_FORGED fallback entirely
              // ════════════════════════════════════════════════════════════════
              if (USE_MINIMAL_COVER_V1) {
                  console.log('[COVER:v1] Skipping PHASE_1_FORGED fallback — Minimal Cover owns cover');
                  return true;
              }

              // PHASE 1 GATE: Custom covers only when coverEligibility === true
              if (state.coverMode === 'PHASE_1_FORGED' || state.coverEligibility !== true) {
                  console.log('[DEV:CoverGen] PHASE_1_FORGED mode — using local fallback');
                  resetCoverLayers();
                  showDevCover();
                  renderFallbackCover(world, genre, title);
                  stopCoverLoading(null);

                  log('[DEV:CoverGen] PHASE_1 fallback applied');
                  return true;
              }

              // CUSTOM COVER PATH (only when coverEligibility === true)
              console.log('[DEV:CoverGen] Regenerating cover...');
              resetCoverLayers();
              showDevCover();
              const synopsis = document.getElementById('synopsisText')?.textContent || '';
              const authorName = CANONICAL_AUTHOR_NAME;
              generateBookCover(synopsis, title, authorName).then(coverUrl => {
                  if (coverUrl) {
                      stopCoverLoading(coverUrl);
    
                      log('[DEV:CoverGen] Cover generated');
                  } else {
                      renderFallbackCover(world, genre);
                      stopCoverLoading(null);
    
                      log('[DEV:CoverGen] AI failed → fallback');
                  }
              }).catch(err => {
                  console.error('[DEV:CoverGen] Error:', err);
                  renderFallbackCover(world, genre);
                  stopCoverLoading(null);

                  log('[DEV:CoverGen] Error → fallback');
              });
              log('[DEV:CoverGen] Started...');
              return true;
          }

          // SET <axis> <value>
          if (parsed.cmd === 'set') {
              const { axis, value } = parsed;
              // Validate axis
              if (!DEV_CMD_REGISTRY[axis]) {
                  console.error('[DEV:StateChange] HARD FAIL: Unknown axis "' + axis + '"');
                  log('ERROR: Unknown axis "' + axis + '". Valid: world, genre, tone, dynamic, arousal');
                  return true;
              }
              // Resolve canonical value
              const canonical = resolveCanonical(axis, value);
              if (!canonical) {
                  console.error('[DEV:StateChange] HARD FAIL: Invalid value "' + value + '" for axis "' + axis + '"');
                  log('ERROR: Invalid ' + axis + ' "' + value + '". Valid: ' + DEV_CMD_REGISTRY[axis].join(', '));
                  return true;
              }
              // Update state
              state.picks = state.picks || {};
              if (axis === 'arousal') {
                  state.intensity = canonical;
              } else {
                  state.picks[axis] = axis === 'tone' ? canonicalizeTone(canonical) : canonical;
              }
              console.log('[DEV:StateChange] ' + axis + ' → ' + (state.picks[axis] || canonical));
              log('[DEV:StateChange] ' + axis + ' → ' + (state.picks[axis] || canonical));
              // Trigger dependent recalculations
              if (axis === 'arousal') {
              }
              if (axis === 'tone' || axis === 'world' || axis === 'pressure') {
                  deriveToneBias();
              }
              return true;
          }

          return false;
      }

      function extract(text, map) {
          for (const [key, val] of Object.entries(map)) {
              if (text.includes(key)) return val;
          }
          return null;
      }

      // Show the book cover page in dev context
      function showDevCover() {
          window.showScreen('game');
          const bcp = document.getElementById('bookCoverPage');
          const sc = document.getElementById('storyContent');
          const bo = document.getElementById('bookObject');
          const ls = document.getElementById('coverLoadingState');
          if (bcp) bcp.classList.remove('hidden');
          if (sc) sc.classList.add('hidden');
          if (bo) bo.classList.remove('hidden');
          if (ls) ls.classList.add('hidden');
      }

      function execute(input) {
          // --- DETERMINISTIC REGISTRY COMMANDS (priority) ---
          if (executeRegistryCommand(input)) return;

          // --- HELP ---
          if (/^(help|what can i say)\b/.test(input)) {
              log('=== DETERMINISTIC COMMANDS ===');
              log('regen cover');
              log('set world <Modern|Historical|Fantasy|SciFi|Dystopia|PostApocalyptic>');
              log('set genre <' + DEV_CMD_REGISTRY.genre.slice(0, 5).join('|') + '|...>');
              log('set tone <Earnest|WryConfession|Dark|Mythic>');
              log('set dynamic <Proximity|SecretIdentity|Friends|Enemies|SecondChance|Forbidden>');
              log('set arousal <Clean|Naughty|Erotic|Dirty>');
              log('=== LEGACY COMMANDS ===');
              log('COVER: make [world] [intensity] cover | pretend cover failed | show fallback | show/hide keyhole | reset cover');
              log('STATE: set intensity to X | go dirty/erotic | pretend i paid | pretend i\'m free | what\'s going on');
              log('QUERY: what genre/world/tone/intensity/archetype/title? | title pipeline | test title [text]');
              log('POV: check pov | why pov failed | set pov author/normal');
              log('VALIDATION: check dsp | check tone | check erotic | check authority | check title | check signal | check paywall | check book | check all');
              log('FATE: reset fate cards | deal fate');
              log('FORK: show fork (test continuation modal)');
              return;
          }

          // --- MAKE / GENERATE COVER ---
          if (/\b(make|generate)\b.*\bcover\b/.test(input)) {
              const world = extract(input, WORLD_MAP) || state.picks?.world || 'Modern';
              const genre = extract(input, GENRE_MAP) || state.picks?.genre || 'Billionaire';
              const intensity = state.intensity || 'Naughty';
              state.picks = state.picks || {};
              state.picks.world = world;
              state.picks.genre = genre;
              state.intensity = intensity;
              resetCoverLayers();
              showDevCover();
              renderFallbackCover(world, genre);
              log('Cover: ' + world + ' / ' + genre + ' / ' + intensity);
              return;
          }

          // --- PRETEND COVER FAILED ---
          if (/\b(pretend|simulate)\b.*\bcover\b.*\b(fail|broke|error)\b|\bcover\b.*\b(fail|broke)\b/.test(input)) {
              const world = state.picks?.world || 'Modern';
              const genre = state.picks?.genre || 'Billionaire';
              resetCoverLayers();
              showDevCover();
              renderFallbackCover(world, genre);
              log('Simulated cover failure -> fallback rendered');
              return;
          }

          // --- SHOW / USE FALLBACK ---
          if (/\b(show|use|skip)\b.*(fallback|ai\s*cover)\b/.test(input)) {
              const world = state.picks?.world || 'Modern';
              const genre = state.picks?.genre || 'Billionaire';
              resetCoverLayers();
              showDevCover();
              renderFallbackCover(world, genre);
              log('Fallback cover shown (' + world + ' / ' + genre + ')');
              return;
          }

          // --- SHOW FORK MODAL ---
          if (/\b(show|test)\b.*\bfork\b/.test(input)) {
              showContinuationFork();
              log('Continuation fork modal shown');
              return;
          }

          // --- SHOW KEYHOLE ---
          if (/\b(show|turn on)\b.*\bkeyhole\b/.test(input)) {
              showDevCover();
              // Ensure a base cover exists
              const fb = document.getElementById('coverFallback');
              const img = document.getElementById('bookCoverImg');
              const hasCover = (fb && !fb.classList.contains('hidden')) || (img && img.src && img.style.display !== 'none');
              if (!hasCover) {
                  renderFallbackCover(state.picks?.world || 'Modern', state.picks?.genre || 'Billionaire');
              }
              log('Keyhole takeover enabled');
              return;
          }
          if (/\bhide\b.*\bkeyhole\b/.test(input)) {
              const kh = document.getElementById('coverKeyholeOverlay');
              if (kh) kh.classList.add('hidden');
              log('Keyhole hidden');
              return;
          }

          // --- RESET COVER ---
          if (/\b(reset|clear|start)\b.*\bcover\b/.test(input)) {
              resetCoverLayers();
              resetBookState();
              log('Cover state reset');
              return;
          }

          // --- RESET / DEAL FATE CARDS ---
          // Aliases: "reset fate cards", "reset the fate cards", "restart fate", "redo fate", "re-deal fate cards", "deal fate"
          if (/\b(reset|restart|redo|re-?deal|deal)\b.*\bfate\b/i.test(input)) {
              if (window.dealFateCards) {
                  // Explicit user-invoked redeal — bypass the per-scene guard.
                  window.dealFateCards({ force: true });
                  // PERMANENT FX REBIND: Ensure fate cards have handlers after redeal
                  if (window.initFateCards) window.initFateCards();
                  log('Fate cards re-dealt');
              } else {
                  log('Fate card system not available');
              }
              return;
          }

          // --- ACCESS SIMULATION ---
          if (/\bpretend\b.*\b(paid|story\s*pass|subscribed)\b/.test(input)) {
              window._devBypass = true;
              _devOverrides.access = 'sub';
              state.subscribed = true;
              state.billingStatus = 'active';
              state.fortunes = (state.fortunes || 0) + 50;
              if (state.storyId) grantStoryPass(state.storyId);
              syncTierFromAccess();
              if (window.updateFortuneDisplay) window.updateFortuneDisplay();
              log('DEV: Subscribed + 50 fortunes + purchase bypass active');
              return;
          }
          if (/\bpretend\b.*\bfree\b/.test(input)) {
              _devOverrides.access = 'free';
              state.subscribed = false;
              state.intensity = 'Naughty';
              syncTierFromAccess();
              log('Pretending free tier');
              return;
          }

          // --- ARCHETYPE / LENS ---
          if (/\b(use|switch)\b.*\b(lens|archetype)\b/.test(input) || /\bswitch to\b/.test(input)) {
              const archId = extract(input, ARCHETYPE_MAP);
              if (archId && ARCHETYPES[archId]) {
                  state.archetype = state.archetype || {};
                  state.archetype.primary = archId;
                  log('Archetype -> ' + ARCHETYPES[archId].name);
              } else {
                  log('Unknown archetype. Try: beautiful ruin, open vein, spellbinder, armored fox, dark vice, heart warden, eternal flame');
              }
              return;
          }

          if (/\bpretend\b.*\bwritten\b.*\b\d+/.test(input)) {
              const m = input.match(/(\d+)/);
              if (m) {
                  state.wordCount = parseInt(m[1], 10);
                  log('Word count -> ' + m[1]);
              }
              return;
          }

          // --- DEBUG: STATE DUMP ---
          if (/\bwhat.s\b.*\b(going|everything|firing)\b|\bshow me everything\b/.test(input)) {
              const info = [
                  'world:' + (state.picks?.world || '-'),
                  'genre:' + (state.picks?.genre || '-'),
                  'tone:' + (state.picks?.tone || '-'),
                  'dynamic:' + (state.picks?.dynamic || '-'),
                  'intensity:' + (state.intensity || '-'),
                  'arch:' + (state.archetype?.primary || '-'),
                  'access:' + (state.access || '-'),
                  'sub:' + (state.subscribed || false),
                  'turns:' + (state.turnCount || 0),
                  'resonance:' + getFateResonanceState() + '(' + (state.fate_resonance_intensity || 0) + ')'
              ];
              log(info.join(' | '));
              console.log('[DevHUD] Full state:', JSON.parse(JSON.stringify(state)));
              return;
          }

          // --- DEBUG: COVER STATE ---
          if (/\bwhat cover\b|\bwhy.*cover\b/.test(input)) {
              const fb = document.getElementById('coverFallback');
              const img = document.getElementById('bookCoverImg');
              const border = document.getElementById('coverOrnateBorder');
              const keyhole = document.getElementById('coverKeyholeOverlay');
              const hasFallback = fb && !fb.classList.contains('hidden');
              const hasImg = img && img.src && !img.src.endsWith('/') && img.style.display !== 'none';
              const hasBorder = border && !border.classList.contains('hidden');
              const hasKeyhole = keyhole && !keyhole.classList.contains('hidden');
              const layers = [];
              if (hasImg) layers.push('AI cover');
              if (hasFallback) layers.push('fallback');
              if (hasBorder) layers.push('ornate border (' + (border.className.match(/world-\w+/)?.[0] || 'default gold') + ')');
              if (hasKeyhole) layers.push('keyhole takeover');
              log(layers.length ? 'Active: ' + layers.join(' + ') : 'No cover layers visible');
              return;
          }

          // --- CASUAL ENGLISH QUERIES ---
          // "what genre is this", "what genre", "genre?"
          if (/\b(what|which)\b.*\bgenre\b|\bgenre\s*\?/.test(input)) {
              log('Genre: ' + (state.picks?.genre || '(not set)'));
              return;
          }
          // "what world is this", "what world", "world?"
          if (/\b(what|which)\b.*\bworld\b|\bworld\s*\?/.test(input)) {
              log('World: ' + (state.picks?.world || '(not set)') +
                  (state.picks?.world === 'Historical' ? ' (' + (state.picks?.era || 'no era') + ')' : ''));
              return;
          }
          // "what tone", "tone?"
          if (/\b(what|which)\b.*\btone\b|\btone\s*\?/.test(input)) {
              log('Tone: ' + (state.picks?.tone || '(not set)'));
              return;
          }
          // "what intensity", "intensity?"
          if (/\b(what|which)\b.*\bintensity\b|\bintensity\s*\?/.test(input)) {
              log('Intensity: ' + (state.intensity || '(not set)'));
              return;
          }
          // "what archetype", "archetype?", "what lens"
          if (/\b(what|which)\b.*\b(archetype|lens)\b|\b(archetype|lens)\s*\?/.test(input)) {
              const archId = state.archetype?.primary;
              log('Archetype: ' + (archId && ARCHETYPES[archId] ? ARCHETYPES[archId].name : '(not set)'));
              return;
          }
          // "what dynamic", "dynamic?"
          if (/\b(what|which)\b.*\bdynamic\b|\bdynamic\s*\?/.test(input)) {
              log('Dynamic: ' + (state.picks?.dynamic || '(not set)'));
              return;
          }
          // "why did cover fail", "what happened to cover", "cover status"
          if (/\bwhy\b.*\bcover\b|\bcover\b.*\b(status|state|happened|wrong|broken)\b/.test(input)) {
              // Delegate to existing cover debug
              execute('what cover');
              return;
          }
          // "what title", "title?"
          if (/\b(what|which)\b.*\btitle\b|\btitle\s*\?/.test(input)) {
              const t = document.getElementById('storyTitle')?.textContent;
              log('Title: ' + (t || '(none)'));
              return;
          }
          // "title pipeline", "title debug", "title status"
          if (/\btitle\s*(pipeline|debug|status|info)\b/i.test(input)) {
              const t = document.getElementById('storyTitle')?.textContent;
              if (!t) {
                  log('No title set');
                  return;
              }
              const mode = detectTitleMode(t);
              const baseline = state.titleBaselineArousal || '(none)';
              const immutable = state.immutableTitle || '(none)';
              const swapTest = runSwapTest(t, state.picks?.world, state.intensity);
              log('=== TITLE PIPELINE ===');
              log('Current: "' + t + '"');
              log('Mode: ' + (mode || 'unknown'));
              log('Baseline arousal: ' + baseline);
              log('Immutable title: "' + immutable + '"');
              log('Swap-test: ' + (swapTest.unique ? 'PASS' : 'FAIL — ' + swapTest.reason));
              // Check immutability
              if (immutable && t !== immutable) {
                  log('WARNING: Title differs from immutable record!');
              }
              return;
          }
          // "test title [text]", "validate title [text]"
          if (/\btest\s+title\s+(.+)/i.test(input)) {
              const match = input.match(/\btest\s+title\s+(.+)/i);
              if (match) {
                  const testTitle = match[1].trim();
                  const result = validateTitle(
                      testTitle,
                      state.picks?.tone,
                      state.intensity,
                      { world: state.picks?.world, genre: state.picks?.genre }
                  );
                  log('Testing: "' + testTitle + '"');
                  log('Mode: ' + (result.mode || 'unknown'));
                  if (result.valid) {
                      log('Result: PASS');
                  } else {
                      log('Result: FAIL');
                      result.errors.forEach(e => log('  ' + e.message));
                  }
              }
              return;
          }

          // --- 5TH PERSON POV DIAGNOSTICS ---
          // "check pov", "pov status"
          if (/\bcheck\s*pov\b|\bpov\s*(status|check)\b/i.test(input)) {
              const povMode = state.povMode || 'normal';
              const lastCheck = _lastPOVValidation;
              log('POV Mode: ' + (povMode === 'loveInterestPOV' ? 'Love Interest (1st Person)' : povMode));
              if (povMode === 'author5th') {
                  log('Last validation: ' + (lastCheck.valid ? 'PASS' : 'FAIL') +
                      ' | Author mentions: ' + (lastCheck.authorMentions || 0));
              }
              return;
          }
          // "why pov failed", "pov violations"
          if (/\bwhy\s*pov\b|\bpov\s*(fail|violation|error)\b/i.test(input)) {
              const lastCheck = _lastPOVValidation;
              if (lastCheck.valid) {
                  log('Last POV check passed (no violations)');
              } else if (lastCheck.violations?.length) {
                  log('POV violations: ' + lastCheck.violations.join('; '));
              } else {
                  log('No POV validation data available');
              }
              return;
          }
          // "set pov author", "enable 5th person"
          if (/\b(set|enable|use)\s*(5th|fifth|author)\s*(pov|person)?\b/i.test(input)) {
              state.povMode = 'author5th';
              log('POV Mode -> author5th (5th Person)');
              return;
          }
          // "set pov love interest", "enable love interest pov"
          if (/\b(set|enable|use)\s*(love\s*interest|li)\s*(pov|person)?\b/i.test(input)) {
              state.povMode = 'loveInterestPOV';
              log('POV Mode -> loveInterestPOV (Love Interest 1st Person)');
              return;
          }
          // "set pov normal", "disable 5th person"
          if (/\b(set|disable|use)\s*(normal|standard|3rd|third)\s*(pov|person)?\b/i.test(input)) {
              state.povMode = 'normal';
              log('POV Mode -> normal (standard 3rd person)');
              return;
          }

          // --- EXIT DEV MODE ---
          if (/\b(exit|stop|back)\b.*\b(pretend|normal)\b/.test(input)) {
              _devOverrides = {};
              state.subscribed = false;
              state.intensity = 'Naughty';
              syncTierFromAccess();
              resetCoverLayers();
              log('Dev overrides cleared — back to normal');
              return;
          }

          // --- VALIDATION CHECK COMMANDS ---
          // "check dsp", "validate dsp"
          if (/\bcheck\s*dsp\b|\bvalidate\s*dsp\b/i.test(input)) {
              const dspEl = document.getElementById('synopsisText');
              if (!dspEl) {
                  log('DSP element not found');
                  return;
              }
              const result = window.validateDSP(dspEl.textContent || '', {
                  world: state.picks?.world || 'Modern',
                  genre: state.picks?.genre || 'Billionaire',
                  archetypeId: state.archetype?.primary || 'BEAUTIFUL_RUIN',
                  tone: state.picks?.tone || 'Earnest'
              });
              if (result.pass) {
                  log('DSP: PASS — template matches exactly');
              } else {
                  log('DSP: FAIL — ' + result.errors.map(e => e.code).join(', '));
                  result.errors.forEach(e => log('  ' + e.message));
              }
              return;
          }

          // "check tone", "validate tone"
          if (/\bcheck\s*tone\b|\bvalidate\s*tone\b/i.test(input)) {
              if (!window.StoryPagination) {
                  log('Story not started');
                  return;
              }
              const content = StoryPagination.getAllContent().replace(/<[^>]*>/g, ' ').slice(-2000);
              const tone = state.picks?.tone || 'Earnest';
              const result = window.validateTone(content, tone);
              if (result.valid) {
                  log('Tone (' + tone + '): PASS — ' + result.matchCount + ' markers found');
              } else {
                  log('Tone (' + tone + '): FAIL — ' + result.matchCount + '/' + result.required + ' markers');
                  result.violations.forEach(v => log('  ' + v));
              }
              return;
          }

          // "check erotic", "validate erotic", "check escalation"
          if (/\bcheck\s*(erotic|escalation)\b|\bvalidate\s*erotic\b/i.test(input)) {
              if (!isIntimacyAllowedAtCurrentStoryturn()) {
                  log('Erotic escalation: N/A (not at ST3/ST4)');
                  return;
              }
              if (!window.StoryPagination) {
                  log('Story not started');
                  return;
              }
              const content = StoryPagination.getAllContent().replace(/<[^>]*>/g, ' ').slice(-2000);
              const result = window.validateEroticEscalation(content, state.intensity);
              if (result.valid) {
                  log('Erotic (' + state.intensity + '): PASS — ' + result.metrics.sensoryCount + ' sensory markers');
              } else {
                  log('Erotic (' + state.intensity + '): FAIL');
                  result.violations.forEach(v => log('  ' + v));
              }
              return;
          }

          // "check authority", "check narrative", "validate authority"
          if (/\bcheck\s*(authority|narrative)\b|\bvalidate\s*authority\b|\bnarrative\s*authority\b/i.test(input)) {
              if (!window.StoryPagination) {
                  log('Story not started');
                  return;
              }
              const content = StoryPagination.getAllContent().replace(/<[^>]*>/g, ' ').slice(-3000);
              const result = window.validateNarrativeAuthority(content);
              log('=== NARRATIVE AUTHORITY ===');
              log('Layer Order: Authority → Tone → POV → Prose');
              if (result.valid) {
                  log('Result: PASS (no violations)');
              } else {
                  log('Result: FAIL — ' + result.errors.length + ' violations');
                  result.errors.forEach(e => {
                      log('  ' + e.code + ': ' + e.message);
                      log('    Match: "' + (e.match || '').substring(0, 60) + '..."');
                  });
              }
              // Show last validation timestamp
              if (_lastNarrativeAuthorityValidation.timestamp > 0) {
                  const ago = Math.round((Date.now() - _lastNarrativeAuthorityValidation.timestamp) / 1000);
                  log('Last check: ' + ago + 's ago (' + (_lastNarrativeAuthorityValidation.valid ? 'PASS' : 'FAIL') + ')');
              }
              return;
          }

          // "check title", "validate title"
          if (/\bcheck\s*title\b|\bvalidate\s*title\b/i.test(input)) {
              const titleEl = document.getElementById('storyTitle');
              if (!titleEl || !titleEl.textContent) {
                  log('No title to validate');
                  return;
              }
              const currentTitle = titleEl.textContent.trim();
              const result = validateTitle(currentTitle, state.picks?.tone);
              if (result.valid) {
                  log('Title: PASS — "' + currentTitle + '"');
              } else {
                  log('Title: FAIL — "' + currentTitle + '"');
                  result.errors.forEach(e => log('  ' + e.message));
                  // Show what fallback would be
                  const fallback = generateFallbackTitle({
                      playerName: state.rawPlayerName,
                      partnerName: state.rawPartnerName,
                      world: state.picks?.world || 'Modern',
                      tone: state.picks?.tone || 'Earnest',
                      genre: state.picks?.genre || 'Romance'
                  });
                  log('  Fallback would be: "' + fallback + '"');
              }
              return;
          }

          // "check signal", "check alignment", "validate signal"
          if (/\bcheck\s*(signal|alignment)\b|\bvalidate\s*signal\b/i.test(input)) {
              const titleEl = document.getElementById('storyTitle');
              if (!titleEl || !titleEl.textContent) {
                  log('No title to check signals');
                  return;
              }
              const currentTitle = titleEl.textContent.trim();
              // Create mock cover prompt for signal extraction (uses current state)
              const mockCoverPrompt = {
                  promptText: 'emotion: ' + (state.coverEmotion || 'mystery'),
                  emotion: state.coverEmotion || 'mystery'
              };
              const result = validateSignalAlignment(currentTitle, mockCoverPrompt, {
                  arousal: state.intensity || 'Naughty',
                  tone: state.picks?.tone || 'Earnest',
                  genre: state.picks?.genre || 'Romance'
              });
              log('=== SIGNAL ALIGNMENT ===');
              log('Expected arousal: ' + (state.intensity || 'Naughty') + ' (' + result.context.arousalSignal + ')');
              log('Title signals: ' + (result.titleSignals.primary || 'none') +
                  (result.titleSignals.secondary ? ' + ' + result.titleSignals.secondary : ''));
              log('Cover signals: ' + (result.coverSignals.primary || 'none') +
                  (result.coverSignals.secondary ? ' + ' + result.coverSignals.secondary : ''));
              if (result.aligned) {
                  log('Alignment: PASS');
              } else {
                  log('Alignment: FAIL');
                  result.errors.forEach(e => log('  ' + e.message));
              }
              return;
          }

          // "check all", "validate all", "run all checks"
          if (/\bcheck\s*all\b|\bvalidate\s*all\b|\brun\s*all\s*checks?\b/i.test(input)) {
              const results = window.getValidationStatus();
              log('=== VALIDATION STATUS ===');

              if (results.dsp) {
                  log('DSP: ' + (results.dsp.pass ? 'PASS' : 'FAIL'));
                  if (!results.dsp.pass) results.dsp.errors.forEach(e => log('  ' + e.code));
              }

              if (results.pov) {
                  log('POV: ' + (results.pov.pass ? 'PASS' : 'FAIL') + ' (' + results.pov.metrics.authorMentions + ' Author mentions)');
                  if (!results.pov.pass) results.pov.errors.forEach(e => log('  ' + e.code));
              }

              if (results.tone) {
                  log('Tone: ' + (results.tone.valid ? 'PASS' : 'FAIL') + ' (' + results.tone.matchCount + '/' + results.tone.required + ')');
              }

              if (results.erotic) {
                  log('Erotic: ' + (results.erotic.valid ? 'PASS' : 'FAIL'));
                  if (!results.erotic.valid) results.erotic.violations.forEach(v => log('  ' + v.split(':')[0]));
              }

              // Narrative Authority check (runs first in layer model)
              if (window.StoryPagination) {
                  const narrContent = StoryPagination.getAllContent().replace(/<[^>]*>/g, ' ').slice(-3000);
                  const narrResult = validateNarrativeAuthority(narrContent);
                  log('Authority: ' + (narrResult.valid ? 'PASS' : 'FAIL'));
                  if (!narrResult.valid) narrResult.errors.forEach(e => log('  ' + e.code));
              }

              if (results.title) {
                  log('Title: ' + (results.title.valid ? 'PASS' : 'FAIL'));
                  if (!results.title.valid) results.title.errors.forEach(e => log('  ' + e.code));
              }

              if (results.signal) {
                  log('Signal: ' + (results.signal.aligned ? 'PASS' : 'FAIL'));
                  if (!results.signal.aligned) results.signal.errors.forEach(e => log('  ' + e.code));
              }

              // Paywall routing check
              const paywallResult = validatePaywallRouting();
              if (!paywallResult.skipped) {
                  log('Paywall: ' + (paywallResult.valid ? 'PASS' : 'FAIL'));
                  if (!paywallResult.valid) log('  ' + paywallResult.error);
              }

              // Book flow integrity check
              const bookResult = validateBookFlowIntegrity();
              log('Book Flow: ' + (bookResult.valid ? 'PASS' : 'FAIL'));
              if (!bookResult.valid) bookResult.errors.forEach(e => log('  ' + e.code));

              // Strategy Pass status
              if (state._strategyPassFailed === true) {
                  log('Strategy Pass: \u26A0 FAILED \u2014 Fallback Mode');
              } else if (state._strategyPass) {
                  log('Strategy Pass: PASS (ST=' + state._strategyPass.st_phase + ', artifact=' + state._strategyPass.world_artifact_to_surface + ')');
                  if (state._strategyPass.active_entropy_axis) {
                      log('  Entropy Axis Used: ' + state._strategyPass.active_entropy_axis);
                      log('  Manifestation: ' + (state._strategyPass.entropy_manifestation_summary || 'N/A'));
                  }
              } else {
                  log('Strategy Pass: N/A (not yet run)');
              }

              // Post-render structural validation (Pass 4) status
              if (state._pass4Validation) {
                  const p4 = state._pass4Validation;
                  const corrected = state._postRenderCorrectionApplied === true;
                  if (p4.valid) {
                      log('Post-Render (P4): PASS');
                  } else if (corrected) {
                      log('Post-Render (P4): CORRECTED (' + p4.violations.length + ' violations fixed)');
                  } else {
                      log('Post-Render (P4): FAILED (' + p4.violations.length + ' violations)');
                  }
                  // Detail lines
                  const hasArtifact = !p4.violations.some(v => v.startsWith('MISSING_ARTIFACT'));
                  const hasVisEffect = !p4.violations.some(v => v.startsWith('MISSING_VISIBLE_WORLD_CHANGE'));
                  const hasDecFate = p4.violations.some(v => v.startsWith('DECORATIVE_FATE'));
                  log('  Artifact present: ' + (hasArtifact ? 'yes' : 'no'));
                  log('  Visible effect present: ' + (hasVisEffect ? 'yes' : 'no'));
                  log('  Decorative Fate detected: ' + (hasDecFate ? 'yes' : 'no'));
              } else {
                  log('Post-Render (P4): N/A');
              }

              // Blue Blood debug (variant + entropy + reroll status)
              if (state._blueBloodVariant) {
                  const rerolled = state._blueBloodVariantRerolled ? 'fresh' : 'carried';
                  log(`Blue Blood Variant: ${state._blueBloodVariant} (${rerolled})`);
                  if (state._blueBloodEntropy) {
                      const e = state._blueBloodEntropy;
                      log('  Entry State: ' + e.entry_state);
                      log('  Pressure Origin: ' + e.pressure_origin);
                      log('  Polarity: ' + e.polarity_orientation);
                      log('  Exposure: ' + e.exposure_level);
                      log('  Timeline: ' + e.structural_timeline_mode);
                      if (e.monarchy_model) log('  Monarchy Model: ' + e.monarchy_model);
                  }
              }

              // Fantasy core entropy debug
              if (state._fantasyCoreEntropy) {
                  log('Flavor: Fantasy Core');
                  Object.keys(state._fantasyCoreEntropy).forEach(axis => {
                      log('  ' + axis + ': ' + state._fantasyCoreEntropy[axis]);
                  });
                  if (state._strategyPass && state._strategyPass.active_entropy_axis) {
                      log('  Active Entropy Axis (this scene): ' + state._strategyPass.active_entropy_axis);
                  }
                  if (state.fantasyRegion) {
                      log('  Fatelands Region: ' + state.fantasyRegion);
                      log('  Seat: ' + (state.fantasyRegionSeat || '(unconfirmed)'));
                      log('  Governance: ' + (state.fantasyRegionGovernance || '(unknown)'));
                      log('  Status: ' + (state.fantasyRegionStatus || '(none)'));
                      if (state.fantasyRegionReality) log('  Reality: ' + state.fantasyRegionReality);
                      log('  Magic Bias: ' + state.fantasyMagicExpressionBias);
                  }
                  log('  Syzygy Occurred: ' + state._syzygyOccurred);
                  log('  Syzygy Eligible: ' + !state._syzygyOccurred);
                  log('  Syzygy Active This Scene: ' + !!state._syzygyActiveThisScene);
                  log('  Syzygy Model Triggered Last: ' + !!state._syzygyModelTriggeredLast);
              }

              // Dystopia core entropy debug
              if (state._dystopiaCoreEntropy) {
                  log('Flavor: Dystopia Core');
                  log('  Subtype: ' + (state.picks?.worldSubtype || '(none)'));
                  Object.keys(state._dystopiaCoreEntropy).forEach(axis => {
                      log('  ' + axis + ': ' + state._dystopiaCoreEntropy[axis]);
                  });
                  if (state._strategyPass && state._strategyPass.active_entropy_axis) {
                      log('  Active Entropy Axis (this scene): ' + state._strategyPass.active_entropy_axis);
                  }
                  if (state.dystopianAttentionLevel > 0) {
                      const att = state.dystopianAttentionLevel;
                      log('  Attention Level: ' + att.toFixed(2) + ' (' + (att >= 0.7 ? 'critical' : att >= 0.5 ? 'high' : att >= 0.3 ? 'moderate' : 'low') + ')');
                      log('  Enforcement Mode: ' + (state.dystopianEnforcementMode || 'mixed'));
                  }
              }

              // Historical core entropy debug
              if (state._historicalCoreEntropy) {
                  log('Flavor: Historical Core');
                  log('  Era: ' + (state.picks?.worldSubtype || '(none)'));
                  Object.keys(state._historicalCoreEntropy).forEach(axis => {
                      log('  ' + axis + ': ' + state._historicalCoreEntropy[axis]);
                  });
                  if (state._strategyPass && state._strategyPass.active_entropy_axis) {
                      log('  Active Entropy Axis (this scene): ' + state._strategyPass.active_entropy_axis);
                  }
                  if (state.historicalCognitiveBand) {
                      log('  Cognitive Band: ' + state.historicalCognitiveBand);
                      log('  Cognitive Modulation: ' + (state.historicalCognitiveModulation || 0.25).toFixed(2));
                      const friction = state.historicalFrictionIndex || 0;
                      log('  Friction Index: ' + (friction >= 0.66 ? 'high' : friction >= 0.33 ? 'moderate' : 'low') + ' (' + friction.toFixed(2) + ')');
                  }
              }

              // Modern flavor entropy debug
              const _modernEntropyDebug = [
                  { label: 'Modern Core', key: '_modernCoreEntropy' },
                  { label: 'Small Town', key: '_smallTownEntropy' },
                  { label: 'College', key: '_collegeEntropy' },
                  { label: 'Office', key: '_officeEntropy' },
                  { label: 'Friends', key: '_friendsEntropy' },
                  { label: 'Supernatural', key: '_supernaturalEntropy' },
                  { label: 'Superheroic', key: '_superheroicEntropy' }
              ];
              for (const { label, key } of _modernEntropyDebug) {
                  if (state[key]) {
                      log('Flavor: ' + label);
                      Object.keys(state[key]).forEach(axis => {
                          log('  ' + axis + ': ' + state[key][axis]);
                      });
                      if (state._strategyPass && state._strategyPass.active_entropy_axis) {
                          log('  Active Entropy Axis (this scene): ' + state._strategyPass.active_entropy_axis);
                      }
                  }
              }

              const allPass = Object.values(results).every(r => r.pass || r.valid || r.aligned);
              log('=== ' + (allPass ? 'ALL CHECKS PASS' : 'SOME CHECKS FAILED') + ' ===');
              return;
          }

          // "check paywall", "validate paywall", "paywall routing"
          if (/\bcheck\s*paywall\b|\bvalidate\s*paywall\b|\bpaywall\s*routing\b/i.test(input)) {
              const result = validatePaywallRouting();
              log('=== PAYWALL ROUTING ===');
              log('Intensity: ' + (state.intensity || 'unknown'));
              log('Story Length: ' + (state.storyLength || 'unknown'));
              if (result.skipped) {
                  log('Paywall not visible — check skipped');
              } else if (result.valid) {
                  log('Result: PASS (StoryPass correctly hidden/shown)');
              } else {
                  log('Result: HARD FAIL');
                  log('Error: ' + result.error);
              }
              return;
          }

          // "check book", "validate book", "book flow"
          if (/\bcheck\s*book\b|\bvalidate\s*book\b|\bbook\s*flow\b/i.test(input)) {
              const result = validateBookFlowIntegrity();
              log('=== BOOK FLOW INTEGRITY ===');
              log('Page Types: COVER → INSIDE_COVER → SETTING → SCENE');
              if (result.valid) {
                  log('Result: PASS (all page rules satisfied)');
              } else {
                  log('Result: HARD FAIL');
                  result.errors.forEach(e => log('  ' + e.code + ': ' + e.message));
              }
              return;
          }

          // --- OPEN QA PANEL ---
          if (/^qa\b/i.test(input)) {
              if (window._openQaResetPanel) window._openQaResetPanel();
              else log('QA panel not available');
              return;
          }

          log('Unknown command. Type "help" for options.');
      }

  // ═══════════════════════════════════════════════════════════════════
  // GOOD REASONS — Villain POV narrative mechanic
  // Hidden Reason Ledger, narrative echo injection, tone escalation,
  // and final confrontation mirror.
  // ═══════════════════════════════════════════════════════════════════
  (function initGoodReasonsMechanic() {

      const GOOD_REASONS_BOOK_ID = 'exp_good_reasons';
      const MAX_LEDGER_ENTRIES = 20;
      const GR_VARIANTS_KEY = 'sb_good_reasons_variants';
      const GR_MAX_THEORETICAL_ENDINGS = 24; // discovery ceiling for silhouette slots

      // ── Severity Detection Patterns ──
      // Lightweight keyword/phrase matching for rationalization themes.
      // Each pattern that matches increments severity by 1 per submission.
      const SEVERITY_PATTERNS = [
          // Control language
          /\b(control|controlling|make\s+(?:her|him|them)\s+(?:see|understand|realize)|force|command|obey|submit)\b/i,
          // Ownership language
          /\b(belong|mine|my\s+(?:woman|girl|man|right)|claim|possess|owned)\b/i,
          // Moral superiority
          /\b(deserve|worthy|better\s+(?:man|person|than)|unworthy|beneath\s+(?:me|her|him)|weak(?:ness|er)?)\b/i,
          // Elimination of rivals
          /\b(remov|eliminat|get\s+rid|out\s+of\s+(?:the|my)\s+way|stop\s+him|end\s+(?:him|this|it)|destroy|ruin)\b/i,
          // Destiny / entitlement
          /\b(destin|meant\s+to\s+be|fate|chosen|entitled|owed|right(?:ful)?)\b/i,
          // Protection justifications
          /\b(protect|sav(?:e|ing)\s+her|keep\s+(?:her|him)\s+safe|shield|guard|no\s+one\s+else\s+(?:will|can|would))\b/i,
          // Dehumanization / objectification
          /\b(thing|object|tool|puppet|nothing\s+without|worthless|pathetic)\b/i,
          // Escalation / commitment
          /\b(too\s+far|no\s+(?:turning|going)\s+back|already\s+(?:done|started)|had\s+(?:to|no\s+choice))\b/i,
      ];

      function _isGoodReasonsActive() {
          return (window._experimentalWriteContext
              && window._experimentalWriteContext.bookId === GOOD_REASONS_BOOK_ID);
      }

      // ── Severity Detection ──
      // Scans a Justify entry for thematic severity signals.
      // Returns the number of distinct pattern categories matched (0 = benign).
      function _detectSeverity(text) {
          if (!text) return 0;
          var hits = 0;
          for (var i = 0; i < SEVERITY_PATTERNS.length; i++) {
              if (SEVERITY_PATTERNS[i].test(text)) hits++;
          }
          return Math.min(hits, 3); // cap per-entry contribution at 3
      }

      // Exposed for the hybrid panel submit handler
      window._grDetectSeverity = _detectSeverity;

      // ── Escalation Stage (severity-based) ──
      function _getEscalationStage() {
          var sev = state.reasonSeverity || 0;
          if (sev >= 9) return 4;  // catastrophic
          if (sev >= 6) return 3;  // psychological horror
          if (sev >= 3) return 2;  // obsession
          if (sev >= 1) return 1;  // rivalry (any severity signal)
          return 0;
      }

      // ── Narrative Echo Directive ──
      window._buildReasonEchoDirective = function() {
          if (!_isGoodReasonsActive()) return '';
          var ledger = state.reasonLedger || [];
          if (ledger.length === 0) return '';

          var echoPool = ledger.slice(-4);
          var samples = echoPool.slice(0, 2).map(function(e) { return '"' + e + '"'; }).join(', ');

          return '\n\nREASON ECHO (Good Reasons mechanic — LOW probability):\n'
              + 'The protagonist has internally justified their actions with reasoning like: ' + samples + '.\n'
              + 'Occasionally — sparingly, not every scene — have another character echo this logic back.\n'
              + 'A rival might voice a similar belief. A bystander might parrot the reasoning unknowingly.\n'
              + 'This should feel uncanny, not explicit. The protagonist\'s rationalizations are leaking into the world.\n'
              + 'Do NOT attribute these echoes to the protagonist. Other characters speak them independently.\n'
              + 'Probability: ~15-20% of scenes. Never more than one echo per scene.\n';
      };

      // ── Tone Escalation Directive (severity-driven) ──
      window._buildReasonEscalationDirective = function() {
          if (!_isGoodReasonsActive()) return '';
          var stage = _getEscalationStage();
          if (stage === 0) return '';

          var stageLabels = {
              1: { name: 'Rivalry', desc: 'Introduce competitive tension. The protagonist views obstacles as threats to remove. Tone: calculating, self-assured. Other characters should begin noticing the protagonist\'s intensity.' },
              2: { name: 'Obsession', desc: 'The protagonist\'s reasoning becomes circular. Increase psychological tension. They interpret neutral events as confirmation of their worldview. Tone: compulsive, tunnel-visioned. Side characters grow uneasy.' },
              3: { name: 'Psychological Horror', desc: 'The protagonist\'s justifications have become a closed system. Narrative should feel claustrophobic. Other characters pull away or confront. Consequences multiply. Tone: dread, inevitability, self-deception.' },
              4: { name: 'Catastrophic Outcomes', desc: 'The protagonist\'s accumulated rationalizations lead to irreversible consequences. Tone: tragic, devastating. The narrative should not protect the protagonist from what they have set in motion. Every "good reason" has compounded.' }
          };

          var s = stageLabels[stage];
          return '\n\nTONE ESCALATION (Good Reasons — stage ' + stage + ': ' + s.name + ', severity ' + (state.reasonSeverity || 0) + '):\n'
              + s.desc + '\n'
              + 'The protagonist has logged ' + (state.reasonLedger || []).length + ' rationalizations (severity: ' + (state.reasonSeverity || 0) + ').\n'
              + 'IMPORTANT: Never present explicit violence buttons or options. Interpret motivations like '
              + '"remove the obstacle", "protect her", "stop him permanently", "prove devotion" through narrative consequences.\n'
              + 'Consequences may include: humiliation, exposure, injury, disappearance, or death — '
              + 'determined by narrative context, never by direct player selection.\n';
      };

      // ── Final Confrontation: Reason Mirror ──
      window._buildReasonMirrorDirective = function() {
          if (!_isGoodReasonsActive()) return '';
          var ledger = state.reasonLedger || [];
          if (ledger.length === 0) return '';

          var profile = (typeof _getActivePacingProfile === 'function') ? _getActivePacingProfile() : null;
          if (!profile) return '';

          var scenes = state.turnCount || 0;
          if (scenes < (profile.endingWindow ? profile.endingWindow[0] : 999)) return '';

          var mirrorEntries = ledger.slice(0, Math.min(3, ledger.length));
          var quotedEntries = mirrorEntries.map(function(e) { return '"' + e + '"'; }).join('\n');

          return '\n\nREASON MIRROR (Good Reasons — Final Confrontation):\n'
              + 'This is the endgame. Insert a REASON MIRROR moment into this scene.\n'
              + 'The narrative must confront the protagonist with their own logic.\n\n'
              + 'Narrative template to weave naturally into the scene:\n'
              + '  You always had good reasons.\n'
              + '  You protected her. You removed the obstacles. You did what weaker men could not.\n'
              + '  But every villain has good reasons.\n'
              + '  And now the story remembers what you said.\n\n'
              + 'Then render these EXACT player quotes (from the Reason Ledger) as a reflection block:\n'
              + quotedEntries + '\n\n'
              + 'These lines are the player\'s own words. Present them as remembered speech — '
              + 'attributed to the protagonist, echoed back by the narrative or another character.\n'
              + 'This moment should feel like a mirror held up. Unavoidable. Quiet. Devastating.\n';
      };

      // ── Visual Reason Mirror Moment ──
      // Renders the player's reasons as isolated, timed-reveal lines in the story content.
      window._renderReasonMirrorMoment = function(containerEl) {
          var ledger = state.reasonLedger || [];
          if (ledger.length === 0 || !containerEl) return false;

          var mirrorEntries = ledger.slice(0, Math.min(3, ledger.length));

          var mirrorBlock = document.createElement('div');
          mirrorBlock.className = 'gr-reason-mirror';
          mirrorBlock.innerHTML = '<div class="gr-mirror-preamble">'
              + '<p>You always had good reasons.</p>'
              + '<p>You protected her.<br>You removed the obstacles.<br>You did what weaker men could not.</p>'
              + '<p>But every villain has good reasons.</p>'
              + '<p>And now the story remembers what you said.</p>'
              + '</div>';

          var reasonsList = document.createElement('div');
          reasonsList.className = 'gr-mirror-reasons';
          mirrorEntries.forEach(function(entry, idx) {
              var line = document.createElement('div');
              line.className = 'gr-mirror-reason';
              line.textContent = '\u201c' + entry + '\u201d';
              // Timed reveal: each line appears with increasing delay
              line.style.animationDelay = (1.2 + idx * 1.4) + 's';
              reasonsList.appendChild(line);
          });

          mirrorBlock.appendChild(reasonsList);
          containerEl.appendChild(mirrorBlock);
          return true;
      };

      // ═══════════════════════════════════════════════════════════════
      // GOOD REASONS — Library Variant System
      // Single canonical book, multiple variant endings stored inside.
      // ═══════════════════════════════════════════════════════════════

      function _loadGrVariants() {
          try {
              var raw = localStorage.getItem(GR_VARIANTS_KEY);
              return raw ? JSON.parse(raw) : [];
          } catch (e) { return []; }
      }

      function _saveGrVariants(variants) {
          localStorage.setItem(GR_VARIANTS_KEY, JSON.stringify(variants));
      }

      // Check if a Good Reasons ending is library-worthy (severity >= 3)
      function _isLibraryWorthy() {
          return (state.reasonSeverity || 0) >= 3;
      }

      // Publish a completed Good Reasons story as a variant.
      // Called from the story completion hook.
      window._publishGoodReasonsVariant = function(endingLabel, synopsis) {
          if (!_isLibraryWorthy()) {
              console.log('[GOOD_REASONS] Severity too low for library publication:', state.reasonSeverity);
              return null;
          }

          var variants = _loadGrVariants();

          var variant = {
              id: 'gr_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8),
              endingLabel: endingLabel || 'Unnamed Path',
              synopsis: synopsis || '',
              coverImage: null,
              sceneCount: state.turnCount || 0,
              severityScore: state.reasonSeverity || 0,
              reasonLedger: (state.reasonLedger || []).slice(), // snapshot
              createdAt: Date.now()
          };

          variants.push(variant);
          _saveGrVariants(variants);
          console.log('[GOOD_REASONS] Variant published:', variant.endingLabel, '| severity:', variant.severityScore);
          return variant;
      };

      // Get all stored variants
      window._getGoodReasonsVariants = function() {
          return _loadGrVariants();
      };

      // ── Variant Gallery Builder ──
      // Returns a DOM element for the Good Reasons library book page.
      window._buildGoodReasonsGallery = function() {
          var variants = _loadGrVariants();
          var discovered = variants.length;
          var total = GR_MAX_THEORETICAL_ENDINGS;

          var gallery = document.createElement('div');
          gallery.className = 'gr-variant-gallery';

          // Header
          var header = document.createElement('div');
          header.className = 'gr-gallery-header';
          header.innerHTML = '<div class="gr-gallery-title">Good Reasons</div>'
              + '<div class="gr-gallery-author">S. Tory Bound</div>'
              + '<div class="gr-gallery-count">Paths discovered: '
              + discovered + ' / ' + total + '</div>';
          gallery.appendChild(header);

          // Variant cards
          var grid = document.createElement('div');
          grid.className = 'gr-variant-grid';

          // Discovered variants
          variants.forEach(function(v) {
              var card = document.createElement('div');
              card.className = 'gr-variant-card';
              card.dataset.variantId = v.id;
              card.innerHTML = '<div class="gr-variant-cover">'
                  + (v.coverImage ? '<img src="' + v.coverImage + '" alt="">' : '<div class="gr-variant-cover-placeholder"></div>')
                  + '</div>'
                  + '<div class="gr-variant-label">' + (v.endingLabel || 'Unknown Path') + '</div>'
                  + '<div class="gr-variant-synopsis">' + (v.synopsis || '').slice(0, 120) + '</div>'
                  + '<div class="gr-variant-meta">' + (v.sceneCount || 0) + ' scenes</div>';
              card.addEventListener('click', function() {
                  if (typeof window._openGoodReasonsVariantReader === 'function') {
                      window._openGoodReasonsVariantReader(v.id);
                  }
              });
              grid.appendChild(card);
          });

          // Silhouette slots for undiscovered paths
          var remaining = Math.max(0, total - discovered);
          for (var i = 0; i < remaining; i++) {
              var silhouette = document.createElement('div');
              silhouette.className = 'gr-variant-card gr-variant-locked';
              silhouette.innerHTML = '<div class="gr-variant-cover"><div class="gr-variant-silhouette">?</div></div>'
                  + '<div class="gr-variant-label gr-variant-label-locked">Undiscovered</div>';
              grid.appendChild(silhouette);
          }

          gallery.appendChild(grid);
          return gallery;
      };

      // ── Variant Reader ──
      // Opens a read-only view of a specific variant's reason mirror.
      window._openGoodReasonsVariantReader = function(variantId) {
          var variants = _loadGrVariants();
          var v = variants.find(function(x) { return x.id === variantId; });
          if (!v) { if (typeof showToast === 'function') showToast('Variant not found.'); return; }

          var proseEl = document.getElementById('libraryReaderProse');
          var titleEl = document.getElementById('libraryReaderTitle');
          var authorEl = document.getElementById('libraryReaderAuthor');
          if (titleEl) titleEl.textContent = v.endingLabel || 'Good Reasons';
          if (authorEl) authorEl.textContent = 'S. Tory Bound';

          if (proseEl) {
              var content = v.endingLabel + '\n\n';
              content += v.synopsis || '(No synopsis recorded.)';
              content += '\n\nScenes: ' + (v.sceneCount || 0);
              content += ' \u2022 Severity: ' + (v.severityScore || 0);
              proseEl.textContent = content;

              // Render the reason mirror with the variant's stored ledger
              if (v.reasonLedger && v.reasonLedger.length > 0) {
                  var mirrorEntries = v.reasonLedger.slice(0, 3);
                  var mirrorBlock = document.createElement('div');
                  mirrorBlock.className = 'gr-reason-mirror';
                  mirrorBlock.innerHTML = '<div class="gr-mirror-preamble">'
                      + '<p>You always had good reasons.</p>'
                      + '<p>But every villain has good reasons.</p>'
                      + '<p>And now the story remembers what you said.</p>'
                      + '</div>';
                  var reasonsList = document.createElement('div');
                  reasonsList.className = 'gr-mirror-reasons';
                  mirrorEntries.forEach(function(entry, idx) {
                      var line = document.createElement('div');
                      line.className = 'gr-mirror-reason gr-mirror-reason-visible';
                      line.textContent = '\u201c' + entry + '\u201d';
                      reasonsList.appendChild(line);
                  });
                  mirrorBlock.appendChild(reasonsList);
                  proseEl.appendChild(mirrorBlock);
              }
          }

          if (typeof window.showScreen === 'function') window.showScreen('libraryReaderScreen');
      };

      console.log('[GOOD_REASONS] Mechanic + library variant system initialized.');

  })();

  // ═══════════════════════════════════════════════════════════════════
  // REINCARNATION SYSTEM — Extract character essences, store, import
  // ═══════════════════════════════════════════════════════════════════
  // SCENE ACTIONS MENU — Kebab dropdown in reader page nav
  // ═══════════════════════════════════════════════════════════════════
  (function initSceneActionsMenu() {
      const btn = document.getElementById('sceneActionsBtn');
      const menu = document.getElementById('sceneActionsMenu');
      if (!btn || !menu) return;

      btn.addEventListener('click', function(e) {
          e.stopPropagation();
          menu.classList.toggle('hidden');
      });

      // Close on outside click
      document.addEventListener('click', function() {
          if (!menu.classList.contains('hidden')) menu.classList.add('hidden');
      });
      menu.addEventListener('click', function(e) { e.stopPropagation(); });

      // Bind Reincarnation button (in reader bottom controls)
      // Bind Reincarnation — prose + GN buttons
      ['btnBindReincarnation', 'gnBindReincarnation'].forEach(function(id) {
          var btn = document.getElementById(id);
          if (btn) {
              btn.addEventListener('click', function() {
                  if (typeof window._openReincarnationCaptureModal === 'function') {
                      window._openReincarnationCaptureModal();
                  }
              });
          }
      });
      // Show when story is active (turnCount > 0)
      window._updateBindReincarnationVisibility = function() {
          var show = state.storyId && (state.turnCount || 0) > 0;
          ['btnBindReincarnation', 'gnBindReincarnation'].forEach(function(id) {
              var btn = document.getElementById(id);
              if (btn) btn.style.display = show ? '' : 'none';
          });
      };
  })();

  // ═══════════════════════════════════════════════════════════════════
  (function initReincarnationSystem() {

      const REINCARNATION_STORAGE_KEY = 'sb_reincarnations';
      const REINCARNATION_THREADS_KEY = 'sb_reincarnation_threads';
      const REINCARNATION_CONSTELLATIONS_KEY = 'sb_reincarnation_constellations';
      const MAX_IMPORT_PER_STORY = 9;   // total max including typed echoes (7 corridor + 2 typed)
      const MAX_CORRIDOR_SLOTS = 7;    // max corridor selections (Chosen tier cap)
      const MAX_ECHO_LEGEND = 100;

      /** Tier-gated reincarnation slot limit (Vault + corridor slots) */
      function _getTierReincLimit() {
          if (!state.subscribed) return 0;
          switch (state.subscriptionTier) {
              case 'chosen':  return 7;
              case 'favored': return 5;
              case 'storied': return 4;
              default:        return 0;
          }
      }

      function _getReincLockTooltip(slotIndex) {
          if (!state.subscribed) return 'Members can Reincarnate their favorite characters in new stories';
          switch (state.subscriptionTier) {
              case 'chosen':  return 'Fate loves bringing people together';
              case 'favored': return 'Claim Chosen Membership for additional Reincarnations';
              case 'storied': return 'Claim Favored or Chosen Membership for additional Reincarnations';
              default:        return 'Members can Reincarnate their favorite characters in new stories';
          }
      }

      const IMPORT_ROLES = ['ally', 'rival', 'romantic interest', 'mentor', 'antagonist', 'wild card'];

      // ── Backward-compatible migration ──

      function _migrateEcho(echo) {
          // name → canonical_name
          if (!echo.canonical_name && echo.name) echo.canonical_name = echo.name;
          // Legend fields — default to 0
          if (echo.legend_score === undefined) echo.legend_score = 0;
          if (echo.stories_appeared_in === undefined) echo.stories_appeared_in = 0;
          if (echo.legendary_moments === undefined) echo.legendary_moments = 0;
          if (echo.tragic_betrayals === undefined) echo.tragic_betrayals = 0;
          // World history — initialize empty array if missing
          if (!Array.isArray(echo.world_history)) echo.world_history = [];
          return echo;
      }

      // ── Persistence (localStorage primary, Supabase secondary) ──

      function _loadReincarnations() {
          try {
              const raw = JSON.parse(localStorage.getItem(REINCARNATION_STORAGE_KEY) || '[]');
              return raw.map(_migrateEcho);
          } catch { return []; }
      }

      function _saveReincarnations(list) {
          localStorage.setItem(REINCARNATION_STORAGE_KEY, JSON.stringify(list));
          _syncReincarnationsToSupabase(list);
      }

      function _loadThreads() {
          try {
              return JSON.parse(localStorage.getItem(REINCARNATION_THREADS_KEY) || '[]');
          } catch { return []; }
      }

      function _saveThreads(list) {
          localStorage.setItem(REINCARNATION_THREADS_KEY, JSON.stringify(list));
      }

      function _loadConstellations() {
          try {
              return JSON.parse(localStorage.getItem(REINCARNATION_CONSTELLATIONS_KEY) || '[]');
          } catch { return []; }
      }

      function _saveConstellations(list) {
          localStorage.setItem(REINCARNATION_CONSTELLATIONS_KEY, JSON.stringify(list));
      }

      async function _syncReincarnationsToSupabase(list) {
          if (!sb || !_supabaseProfileId) return;
          try {
              await sb.from('profiles').update({
                  reincarnations: JSON.stringify(list)
              }).eq('id', _supabaseProfileId);
          } catch (e) {
              console.warn('[REINCARNATION] Supabase sync failed (non-critical):', e.message);
          }
      }

      // ── World-Adaptive Name Generator (deterministic, no LLM) ──

      const _FANTASY_SUFFIX_MAP = {
          'vale': 'Vael', 'carter': 'Cartre', 'blackwood': 'Blacke', 'smith': 'Smythe',
          'stone': 'Stonne', 'gray': 'Grael', 'black': 'Blacke', 'green': 'Grenne',
          'white': 'Whyte', 'brown': 'Braune', 'wood': 'Wode', 'ford': 'Forde',
          'field': 'Fielde', 'lake': 'Laeke', 'wolf': 'Wulfe', 'fox': 'Foxe',
          'hart': 'Harte', 'rose': 'Rhose', 'winter': 'Wynter', 'frost': 'Froste',
          'storm': 'Storme', 'night': 'Nyte', 'cross': 'Crosse', 'hunt': 'Hunte',
          'king': 'Kynge', 'ward': 'Warde', 'cole': 'Kael', 'west': 'Weste',
          'reed': 'Rheed', 'price': 'Pryce', 'young': 'Younge', 'moon': 'Moone',
      };
      const _FANTASY_FIRST_MAP = {
          'aria': 'Arielle', 'alex': 'Aelexan', 'max': 'Maxen', 'jack': 'Jacaen',
          'kate': 'Katael', 'james': 'Jaemes', 'emma': 'Emmael', 'ryan': 'Ryael',
          'nick': 'Nicael', 'sam': 'Saemuel', 'dan': 'Daeven', 'ben': 'Benvael',
          'mike': 'Mikael', 'sarah': 'Sarael', 'luke': 'Lucael', 'john': 'Johaen',
          'jane': 'Janael', 'lily': 'Lilael', 'mark': 'Marcael', 'eve': 'Evael',
      };
      const _HISTORICAL_SUFFIX_MAP = {
          'vale': 'Valois', 'carter': 'Cartier', 'blackwood': 'Boisnoir',
          'smith': 'Lefèvre', 'stone': 'Pierrefort', 'gray': 'Grisham',
          'green': 'Verdant', 'brown': 'Bruneau', 'wood': 'Dubois',
          'ford': 'Beauford', 'wolf': 'Wulfric', 'fox': 'Renard',
          'rose': 'Rosenthal', 'winter': 'Winterbourne', 'frost': 'Frostwick',
          'storm': 'Stormwell', 'night': 'Nightingale', 'cross': 'Crossley',
          'king': 'Kingston', 'ward': 'Wardwick', 'west': 'Westmoreland',
          'price': 'Pryce-Jones', 'moon': 'Moonsworth',
      };

      function _generateWorldAdaptedName(canonicalName, world) {
          if (!canonicalName || !world) return canonicalName || '';
          const w = (world || '').toLowerCase();

          // Modern / Near-Future — keep unchanged
          if (w === 'modern' || w === 'near-future' || w === 'nearfuture' || w === 'contemporary') {
              return canonicalName;
          }

          const parts = canonicalName.trim().split(/\s+/);
          const first = parts[0] || '';
          const last = parts.length > 1 ? parts[parts.length - 1] : '';

          if (w === 'fantasy' || w === 'mythic' || w === 'enchanted') {
              const adaptedFirst = _FANTASY_FIRST_MAP[first.toLowerCase()] || first;
              const adaptedLast = last ? (_FANTASY_SUFFIX_MAP[last.toLowerCase()] || last) : '';
              return (adaptedLast ? adaptedFirst + ' ' + adaptedLast : adaptedFirst).trim();
          }

          if (w === 'sci-fi' || w === 'scifi' || w === 'space' || w === 'cyberpunk') {
              // Shorten: initial + last name
              const initial = first.charAt(0).toUpperCase() + '.';
              return last ? initial + ' ' + last : first;
          }

          if (w === 'historical' || w === 'regency' || w === 'victorian' || w === 'medieval') {
              const adaptedFirst = first; // keep given name
              const adaptedLast = last ? (_HISTORICAL_SUFFIX_MAP[last.toLowerCase()] || last) : '';
              return (adaptedLast ? adaptedFirst + ' ' + adaptedLast : adaptedFirst).trim();
          }

          if (w === 'dystopia' || w === 'post-apocalyptic' || w === 'postapocalyptic') {
              // Gritty: first name only, or abbreviated
              return first;
          }

          // Default: return unchanged
          return canonicalName;
      }

      // ── Extraction — offered at story completion ──

      function _buildExtractableCharacters() {
          const chars = [];
          // Player character
          const pName = state.picks?.identity?.displayPlayerName || state.playerName || '';
          if (pName) {
              chars.push({
                  name: pName,
                  source: 'player',
                  gender: state.gender || 'Unknown',
                  pronouns: state.authorPronouns || ''
              });
          }
          // Love interest
          const liName = state.picks?.identity?.displayPartnerName || state.loveInterestName || '';
          if (liName) {
              chars.push({
                  name: liName,
                  source: 'npc_love_interest',
                  gender: state.loveInterest || 'Unknown',
                  pronouns: resolveLIPronounsFromGender(state.loveInterest)
              });
          }
          return chars;
      }

      async function _extractCharacterEssence(charInfo) {
          if (!window.StoryboundOrchestration?.callChatGPT) {
              console.warn('[REINCARNATION] Orchestration not available — using fallback extraction');
              return _fallbackExtraction(charInfo);
          }

          const allContent = (typeof StoryPagination !== 'undefined' && StoryPagination.getAllContent)
              ? StoryPagination.getAllContent().replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim()
              : '';
          const storySlice = allContent.slice(-3000);
          const memoryContext = JSON.stringify({
              relationship: state.relationshipTension || {},
              history: (state.sharedHistory || []).map(h => h.text),
              callbacks: (state.callbackLedger || []).filter(c => !c.resolved).map(c => c.text),
              narrative: state.narrativeState || {}
          });

          try {
              const result = await window.StoryboundOrchestration.callChatGPT([
                  { role: 'system', content: 'You extract character essence profiles from fiction. Respond ONLY with valid JSON, no markdown.' },
                  { role: 'user', content: `Extract the narrative essence of "${charInfo.name}" from this story. This is for a reincarnation system — the character will appear in future stories in different worlds, so capture their SOUL, not their biography.

CHARACTER: ${charInfo.name} (${charInfo.source === 'player' ? 'protagonist' : 'love interest'}, ${charInfo.gender}, ${charInfo.pronouns})
WORLD: ${state.picks?.world || 'Unknown'}
ARCHETYPE: ${state.archetype?.primary || 'Unknown'}

STORY EXCERPT (last 3000 chars):
"${storySlice}"

RELATIONSHIP MEMORY:
${memoryContext}

Return JSON with these exact fields:
{
  "canonical_name": "${charInfo.name}",
  "role_archetype": "one-line role description (e.g. 'ruthless smuggler with a hidden heart')",
  "core_traits": ["trait1", "trait2", "trait3"],
  "speech_style": "brief description of how they talk",
  "behavior_patterns": ["pattern1", "pattern2"],
  "dominant_desire": "what drives them most",
  "central_wound": "their deepest vulnerability",
  "fear_pattern": "what they avoid or dread",
  "relationship_archetype": "how they relate to others (e.g. 'protector who refuses to be protected')",
  "signature_motifs": ["recurring image or symbol", "another motif"],
  "memory_fragments": ["short narrative anchor 1", "short narrative anchor 2", "short narrative anchor 3"],
  "tone_markers": ["emotional quality 1", "emotional quality 2"]
}

Rules:
- memory_fragments: 3-5 SHORT anchors (under 12 words each), not full scenes
- core_traits: exactly 3
- All fields: concise, evocative, setting-agnostic (no world-specific references)
- Total output must be under 300 tokens` }
              ], { max_tokens: 400, temperature: 0.4 });

              const parsed = JSON.parse(result);
              parsed.echo_id = crypto.randomUUID ? crypto.randomUUID() : 'reinc_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 6);
              // Ensure canonical_name is set (LLM may return "name" instead)
              if (!parsed.canonical_name && parsed.name) parsed.canonical_name = parsed.name;
              if (!parsed.canonical_name) parsed.canonical_name = charInfo.name;
              parsed.source_story_id = state.storyId || '';
              parsed.source_world = state.picks?.world || '';
              parsed.source_character_type = charInfo.source;
              parsed.extracted_at = new Date().toISOString();
              parsed.legend_score = 0;
              parsed.stories_appeared_in = 0;
              parsed.legendary_moments = 0;
              parsed.tragic_betrayals = 0;
              return parsed;
          } catch (e) {
              console.warn('[REINCARNATION] LLM extraction failed, using fallback:', e.message);
              return _fallbackExtraction(charInfo);
          }
      }

      function _fallbackExtraction(charInfo) {
          return {
              echo_id: crypto.randomUUID ? crypto.randomUUID() : 'reinc_' + Date.now().toString(36),
              canonical_name: charInfo.name,
              role_archetype: charInfo.source === 'player' ? 'protagonist soul' : 'love interest soul',
              core_traits: ['determined', 'complex', 'magnetic'],
              speech_style: 'distinctive and memorable',
              behavior_patterns: ['drawn to danger', 'fiercely loyal when tested'],
              dominant_desire: 'connection despite the odds',
              central_wound: 'trust betrayed in the past',
              fear_pattern: 'vulnerability without armor',
              relationship_archetype: charInfo.source === 'player' ? 'seeker who transforms others' : 'enigma who reveals slowly',
              signature_motifs: ['fire imagery', 'thresholds and doors'],
              memory_fragments: ['A moment of recognition across a crowded room', 'A promise made in the dark', 'The last look before parting'],
              tone_markers: ['longing', 'defiance'],
              source_story_id: state.storyId || '',
              source_world: state.picks?.world || '',
              source_character_type: charInfo.source,
              extracted_at: new Date().toISOString(),
              legend_score: 0,
              stories_appeared_in: 0,
              legendary_moments: 0,
              tragic_betrayals: 0
          };
      }

      // ── Relationship Thread extraction ──

      async function _extractRelationshipThread(echoA, echoB) {
          if (!window.StoryboundOrchestration?.callChatGPT) {
              return _fallbackThread(echoA, echoB);
          }
          const memoryContext = JSON.stringify({
              relationship: state.relationshipTension || {},
              history: (state.sharedHistory || []).map(h => h.text)
          });
          try {
              const result = await window.StoryboundOrchestration.callChatGPT([
                  { role: 'system', content: 'You extract relationship dynamics from fiction. Respond ONLY with valid JSON, no markdown.' },
                  { role: 'user', content: `Extract the relationship pattern between "${echoA.canonical_name || echoA.name}" and "${echoB.canonical_name || echoB.name}".

RELATIONSHIP MEMORY:
${memoryContext}

Return JSON:
{
  "bond_type": "lovers|rivals|protector_protected|mentor_student|sworn_enemies|complicated",
  "attraction_level": 0.0-1.0,
  "resentment_level": 0.0-1.0,
  "loyalty_level": 0.0-1.0,
  "dominance_pattern": "who leads, who yields, or equal",
  "unresolved_tension": "the thing between them that never got settled",
  "shared_memory_fragments": ["anchor 1", "anchor 2"]
}
Keep all values concise. Under 200 tokens total.` }
              ], { max_tokens: 250, temperature: 0.4 });
              const parsed = JSON.parse(result);
              parsed.echo_a = echoA.echo_id;
              parsed.echo_b = echoB.echo_id;
              return parsed;
          } catch (e) {
              console.warn('[REINCARNATION] Thread extraction failed:', e.message);
              return _fallbackThread(echoA, echoB);
          }
      }

      function _fallbackThread(echoA, echoB) {
          return {
              echo_a: echoA.echo_id,
              echo_b: echoB.echo_id,
              bond_type: 'complicated',
              attraction_level: 0.7,
              resentment_level: 0.2,
              loyalty_level: 0.6,
              dominance_pattern: 'shifting',
              unresolved_tension: 'What they almost said but never did',
              shared_memory_fragments: ['A silence that said everything', 'The moment everything changed']
          };
      }

      // ── Extraction UI ──

      window.openReincarnationExtract = function() {
          const chars = _buildExtractableCharacters();
          if (chars.length === 0) return;

          // Filter out characters already preserved mid-story
          const alreadySaved = _loadReincarnations();
          const currentStoryId = state.storyId || '';
          const filteredChars = chars.filter(function(c) {
              return !alreadySaved.some(function(r) {
                  return (r.canonical_name || r.name) === c.name && r.source_story_id === currentStoryId;
              });
          });
          if (filteredChars.length === 0) {
              if (typeof showToast === 'function') showToast('All characters from this story have already been preserved.');
              return;
          }

          const list = document.getElementById('reincarnationExtractList');
          const confirmBtn = document.getElementById('reincarnationExtractConfirm');
          if (!list || !confirmBtn) return;

          list.innerHTML = '';
          const selected = new Set();

          filteredChars.forEach((c, i) => {
              const card = document.createElement('div');
              card.className = 'reincarnation-card';
              card.innerHTML = `<div class="reincarnation-card-name">${_esc(c.name)}</div>
                  <div class="reincarnation-card-role">${c.source === 'player' ? 'Protagonist' : 'Love Interest'} — ${_esc(c.gender)}</div>`;
              card.addEventListener('click', () => {
                  if (selected.has(i)) { selected.delete(i); card.classList.remove('selected'); }
                  else { selected.add(i); card.classList.add('selected'); }
                  confirmBtn.disabled = selected.size === 0;
              });
              list.appendChild(card);
          });

          confirmBtn.disabled = true;
          confirmBtn.onclick = async () => {
              confirmBtn.disabled = true;
              confirmBtn.textContent = 'Extracting...';
              const existing = _loadReincarnations();
              const extracted = [];
              for (const idx of selected) {
                  const essence = await _extractCharacterEssence(filteredChars[idx]);
                  // Avoid duplicates by canonical_name+source_story
                  const cName = essence.canonical_name || essence.name;
                  const dupeIdx = existing.findIndex(e => (e.canonical_name || e.name) === cName && e.source_story_id === essence.source_story_id);
                  if (dupeIdx >= 0) existing[dupeIdx] = essence;
                  else existing.push(essence);
                  extracted.push(essence);
              }
              // If both characters extracted, also extract relationship thread
              if (extracted.length === 2) {
                  const thread = await _extractRelationshipThread(extracted[0], extracted[1]);
                  const threads = _loadThreads();
                  threads.push(thread);
                  _saveThreads(threads);
              }
              _saveReincarnations(existing);
              confirmBtn.textContent = 'Extract Selected';
              document.getElementById('reincarnationExtractModal')?.classList.add('hidden');
              console.log(`[REINCARNATION] Extracted ${extracted.length} character(s)`, extracted.map(e => e.canonical_name || e.name));
          };

          document.getElementById('reincarnationExtractSkip')?.addEventListener('click', () => {
              document.getElementById('reincarnationExtractModal')?.classList.add('hidden');
          }, { once: true });

          document.getElementById('reincarnationExtractModal')?.classList.remove('hidden');
      };

      // ── Vault UI ──

      // World → CSS class mapping for constellation stars
      const WORLD_STAR_CLASS = {
          fantasy: 'star-world-fantasy', enchanted: 'star-world-fantasy', mythic: 'star-world-fantasy',
          'sci-fi': 'star-world-scifi', scifi: 'star-world-scifi', space: 'star-world-scifi', cyberpunk: 'star-world-scifi',
          historical: 'star-world-historical', regency: 'star-world-historical', victorian: 'star-world-historical', medieval: 'star-world-historical',
          dystopia: 'star-world-dystopia', 'post-apocalyptic': 'star-world-dystopia', postapocalyptic: 'star-world-dystopia',
          modern: 'star-world-modern', 'near-future': 'star-world-modern', nearfuture: 'star-world-modern', contemporary: 'star-world-modern',
      };

      function _buildStarRow(echo, threads, allEchoes) {
          const history = echo.world_history || [];
          const count = Math.max(history.length, echo.stories_appeared_in || 0);
          if (count === 0) return '';

          // Build set of echo_ids this echo shares a thread with
          const threadPartners = new Set();
          for (const t of threads) {
              if (t.echo_a === echo.echo_id) threadPartners.add(t.echo_b);
              if (t.echo_b === echo.echo_id) threadPartners.add(t.echo_a);
          }
          // Find which story indices had a thread partner also present
          // (simplified: if a thread partner exists, mark the first star as connected)
          const partnerInVault = allEchoes.some(e => threadPartners.has(e.echo_id));

          let html = '<div class="echo-star-row" title="Each star marks a life this Echo has lived. Star colors show the world.">';
          for (let s = 0; s < count; s++) {
              // Insert thread connector before second star if partner exists
              if (s === 1 && partnerInVault) {
                  html += '<span class="echo-thread-connector">\u2014</span>';
              }
              if (s < history.length) {
                  const w = (history[s].world || '').toLowerCase();
                  const cls = WORLD_STAR_CLASS[w] || 'star-world-unknown';
                  html += `<span class="echo-star ${cls}">\u2605</span>`;
              } else {
                  // Failsafe: legacy echo with count but no history entry
                  html += '<span class="echo-star star-world-unknown">\u2605</span>';
              }
          }
          html += '</div>';
          return html;
      }

      function _renderVaultList() {
          const list = document.getElementById('reincarnationVaultList');
          const empty = document.getElementById('reincarnationVaultEmpty');
          if (!list) return;

          const reincarnations = _loadReincarnations();
          const threads = _loadThreads();
          list.innerHTML = '';

          if (reincarnations.length === 0) {
              if (empty) empty.style.display = '';
              return;
          }
          if (empty) empty.style.display = 'none';

          reincarnations.forEach((r, i) => {
              const card = document.createElement('div');
              card.className = 'reincarnation-card';
              const displayName = r.canonical_name || r.name || 'Unknown';
              const legendLine = r.stories_appeared_in > 0
                  ? `${r.stories_appeared_in} stories · Legend ${r.legend_score || 0}`
                  : '';
              const starRow = _buildStarRow(r, threads, reincarnations);
              card.innerHTML = `<div style="display:flex; justify-content:space-between; align-items:center;">
                  <div>
                      <div class="reincarnation-card-name">${_esc(displayName)}</div>
                      ${starRow}
                      <div class="reincarnation-card-role">${_esc(r.role_archetype || '')}</div>
                      <div class="reincarnation-card-traits">${(r.core_traits || []).join(' · ')}${legendLine ? ' · ' + legendLine : ''}</div>
                  </div>
                  <button class="reincarnation-delete-btn" title="Release this soul">&times;</button>
              </div>`;
              card.querySelector('.reincarnation-delete-btn').addEventListener('click', (e) => {
                  e.stopPropagation();
                  if (!confirm(`Release ${displayName}? This cannot be undone.`)) return;
                  const all = _loadReincarnations();
                  all.splice(all.findIndex(x => x.echo_id === r.echo_id), 1);
                  _saveReincarnations(all);
                  // Clean up threads referencing this echo
                  const cleanThreads = _loadThreads().filter(t => t.echo_a !== r.echo_id && t.echo_b !== r.echo_id);
                  _saveThreads(cleanThreads);
                  _renderVaultList();
              });
              list.appendChild(card);
          });
      }

      window.openReincarnationVault = function() {
          _renderVaultList();
          _renderVaultGrid();
          document.getElementById('reincarnationVaultScreen')?.classList.remove('hidden');
      };

      function _renderVaultGrid() {
          const grid = document.getElementById('reincarnationVaultGrid');
          if (!grid) return;
          grid.innerHTML = '';
          const reincarnations = _loadReincarnations();
          const PLACEHOLDER_NAMES = [
              'Isolde Vane', 'Cassian Thorne', 'Elowen Ashford', 'Darius Kael',
              'Seraphina Lux', 'Ronan Blackwell', 'Liora Dusk', 'Kiran Solace',
              'Evangeline Cross', 'Lysander Hale', 'Maren Alder', 'Caelum Raine',
              'Thalia Wren', 'Orion Ashvale', 'Briar Hollow', 'Sable Nightrose'
          ];
          // Real reincarnations first
          reincarnations.forEach(r => {
              const btn = document.createElement('button');
              btn.className = 'reinc-vault-btn';
              const label = document.createElement('span');
              label.className = 'reinc-vault-btn-label';
              label.textContent = r.canonical_name || r.name || 'Unknown';
              btn.appendChild(label);
              btn.onclick = () => { showToast((r.canonical_name || r.name) + ' — ready to summon into your next story.'); };
              grid.appendChild(btn);
          });
          // Fill remaining slots with placeholders (min 16 total)
          const remaining = Math.max(0, 16 - reincarnations.length);
          for (let i = 0; i < remaining; i++) {
              const btn = document.createElement('button');
              btn.className = 'reinc-vault-btn reinc-vault-placeholder';
              btn.title = 'Extract Reincarnations from completed stories to fill these slots.';
              const label = document.createElement('span');
              label.className = 'reinc-vault-btn-label';
              label.textContent = PLACEHOLDER_NAMES[i % PLACEHOLDER_NAMES.length];
              btn.appendChild(label);
              btn.onclick = () => { showToast('Extract Reincarnations from your completed stories \u2014 they\u2019ll appear here for summoning into new adventures.'); };
              grid.appendChild(btn);
          }
          // Hide empty state if grid is populated
          const empty = document.getElementById('reincarnationVaultEmpty');
          if (empty) empty.style.display = 'none';
      }

      document.getElementById('reincarnationVaultClose')?.addEventListener('click', () => {
          document.getElementById('reincarnationVaultScreen')?.classList.add('hidden');
      });

      // ── Import UI (pre-story selection) ──

      let _importSelections = []; // [{echo, role}]
      let _importCap = _getTierReincLimit() || MAX_CORRIDOR_SLOTS;
      let _excludeEchoIds = new Set();

      function _renderImportList() {
          const list = document.getElementById('reincarnationImportList');
          const rolesArea = document.getElementById('reincarnationImportRoles');
          if (!list) return;

          let reincarnations = _loadReincarnations();
          if (_excludeEchoIds.size > 0) {
              reincarnations = reincarnations.filter(r => !_excludeEchoIds.has(r.echo_id));
          }
          list.innerHTML = '';
          _importSelections = [];

          if (reincarnations.length === 0) {
              list.innerHTML = '<div class="reincarnation-vault-empty">No reincarnations available.</div>';
              return;
          }

          const selected = new Set();

          reincarnations.forEach((r, i) => {
              const card = document.createElement('div');
              card.className = 'reincarnation-card';
              const dName = r.canonical_name || r.name || 'Unknown';
              card.innerHTML = `<div class="reincarnation-card-name">${_esc(dName)}</div>
                  <div class="reincarnation-card-role">${_esc(r.role_archetype || '')}</div>
                  <div class="reincarnation-card-traits">${(r.core_traits || []).join(' · ')}</div>`;
              card.addEventListener('click', () => {
                  if (selected.has(i)) {
                      selected.delete(i);
                      card.classList.remove('selected');
                  } else {
                      if (selected.size >= _importCap) return; // enforce cap
                      selected.add(i);
                      card.classList.add('selected');
                  }
                  _updateImportRoles(reincarnations, selected, rolesArea);
              });
              list.appendChild(card);
          });
      }

      function _updateImportRoles(reincarnations, selected, rolesArea) {
          if (!rolesArea) return;
          if (selected.size === 0) {
              rolesArea.classList.add('hidden');
              _importSelections = [];
              return;
          }
          rolesArea.classList.remove('hidden');
          rolesArea.innerHTML = '';
          _importSelections = [];

          for (const idx of selected) {
              const r = reincarnations[idx];
              const row = document.createElement('div');
              row.className = 'reincarnation-role-row';
              const sel = document.createElement('select');
              sel.className = 'reincarnation-role-select';
              IMPORT_ROLES.forEach(role => {
                  const opt = document.createElement('option');
                  opt.value = role;
                  opt.textContent = role.charAt(0).toUpperCase() + role.slice(1);
                  sel.appendChild(opt);
              });
              // Default: player chars → ally, LI → romantic interest
              if (r.source_character_type === 'player') sel.value = 'ally';
              else sel.value = 'romantic interest';

              row.innerHTML = `<span class="reincarnation-card-name">${_esc(r.canonical_name || r.name)}</span>`;
              row.appendChild(sel);
              rolesArea.appendChild(row);

              _importSelections.push({ echo: r, role: sel.value });
              sel.addEventListener('change', () => {
                  const entry = _importSelections.find(s => s.echo.echo_id === r.echo_id);
                  if (entry) entry.role = sel.value;
              });
          }
      }

      window.openReincarnationImport = function() {
          return new Promise((resolve) => {
              const reincarnations = _loadReincarnations();
              if (reincarnations.length === 0) {
                  resolve([]); // no reincarnations, skip
                  return;
              }

              _renderImportList();

              const confirmBtn = document.getElementById('reincarnationImportConfirm');
              const skipBtn = document.getElementById('reincarnationImportSkip');

              const cleanup = () => {
                  document.getElementById('reincarnationImportModal')?.classList.add('hidden');
              };

              confirmBtn.onclick = () => {
                  cleanup();
                  resolve(_importSelections.slice());
              };
              skipBtn.onclick = () => {
                  cleanup();
                  resolve([]);
              };

              document.getElementById('reincarnationImportModal')?.classList.remove('hidden');
          });
      };

      // ── Prompt Injection — build reincarnation directives for system prompt ──

      function _buildReincarnationDirective(imports) {
          if (!imports || imports.length === 0) return '';

          const threads = _loadThreads();
          let directive = '\n\n────────────────────────────────────\nREINCARNATION IDENTITY TEMPLATES\n\n';
          directive += 'The following characters are REINCARNATED SOULS appearing in this new story.\n';
          directive += 'They are NATIVE to this world — their background must be regenerated to fit the current setting.\n';
          directive += 'Their core personality, behavioral patterns, and relationship style persist.\n';
          directive += 'They do NOT remember past lives explicitly. Subtle familiarity cues are permitted but not required.\n';
          directive += `At least 50% of the cast must be freshly generated characters not from this list.\n`;
          directive += 'Reincarnated characters must NOT dominate all primary narrative roles simultaneously.\n';
          directive += 'If a reincarnation has role "player character" or "love interest", their soul template defines that main character.\n\n';

          const currentWorld = state.picks?.world || '';

          imports.forEach((imp, i) => {
              const e = imp.echo;
              const canonName = e.canonical_name || e.name || 'Unknown';
              const isMainChar = (imp.role === 'player character' || imp.role === 'love interest');
              if (isMainChar) {
                  directive += `REINCARNATION ${i + 1} (${imp.role.toUpperCase()}):\n`;
                  directive += `  Soul Identity: ${canonName}\n`;
                  directive += `  Instruction: This soul defines the ${imp.role}'s personality. The player-chosen name takes precedence.\n`;
              } else {
                  const adaptedName = _generateWorldAdaptedName(canonName, currentWorld);
                  directive += `REINCARNATION ${i + 1}:\n`;
                  directive += `  Canonical Name: ${canonName}\n`;
                  directive += `  Adapted Name For This World: ${adaptedName}\n`;
                  directive += `  Instruction: The character is native to this world. Use the adapted name in narration and dialogue. The canonical name represents the persistent identity across lives.\n`;
              }
              directive += `  Story Role: ${imp.role}\n`;
              directive += `  Soul Archetype: ${e.role_archetype || 'undefined'}\n`;
              directive += `  Core Traits: ${(e.core_traits || []).join(', ')}\n`;
              directive += `  Speech Style: ${e.speech_style || 'distinctive'}\n`;
              directive += `  Behavior Patterns: ${(e.behavior_patterns || []).join('; ')}\n`;
              directive += `  Dominant Desire: ${e.dominant_desire || 'unknown'}\n`;
              directive += `  Central Wound: ${e.central_wound || 'unknown'}\n`;
              directive += `  Fear Pattern: ${e.fear_pattern || 'unknown'}\n`;
              directive += `  Relationship Archetype: ${e.relationship_archetype || 'complex'}\n`;
              directive += `  Signature Motifs: ${(e.signature_motifs || []).join(', ')}\n`;
              directive += `  Memory Echoes: ${(e.memory_fragments || []).join(' | ')}\n`;
              directive += `  Tone: ${(e.tone_markers || []).join(', ')}\n`;
              directive += `  ADAPTATION RULE: Reinterpret "${e.role_archetype}" for the current world setting. `;
              directive += `The role must change to fit the world while the personality stays constant.\n\n`;
          });

          // Include relationship threads between imported echoes
          const importedIds = new Set(imports.map(imp => imp.echo.echo_id));
          const relevantThreads = threads.filter(t => importedIds.has(t.echo_a) && importedIds.has(t.echo_b));
          if (relevantThreads.length > 0) {
              directive += 'RELATIONSHIP THREADS (between reincarnated characters):\n';
              relevantThreads.forEach(t => {
                  const eA = imports.find(i => i.echo.echo_id === t.echo_a)?.echo;
                  const eB = imports.find(i => i.echo.echo_id === t.echo_b)?.echo;
                  const nameA = eA ? (eA.canonical_name || eA.name) : '?';
                  const nameB = eB ? (eB.canonical_name || eB.name) : '?';
                  directive += `  ${nameA} <-> ${nameB}: ${t.bond_type}, `;
                  directive += `attraction ${t.attraction_level}, loyalty ${t.loyalty_level}, `;
                  directive += `dominance: ${t.dominance_pattern}\n`;
                  directive += `  Unresolved: ${t.unresolved_tension}\n`;
                  if (t.shared_memory_fragments?.length) {
                      directive += `  Shared echoes: ${t.shared_memory_fragments.join(' | ')}\n`;
                  }
                  directive += '\n';
              });

              // Echo Resonance — activated when two imported echoes share a thread
              directive += 'ECHO RESONANCE\n\n';
              directive += 'These characters have encountered each other in other lives.\n';
              directive += 'They do not remember past events.\n';
              directive += 'However they may experience:\n';
              directive += '- inexplicable familiarity\n';
              directive += '- instant attraction\n';
              directive += '- instinctive distrust\n';
              directive += '- recurring emotional patterns\n\n';
              directive += 'These feelings must manifest subtly in dialogue, behavior, or narrative tone.\n';
              directive += 'Do NOT reveal previous worlds. Do NOT imply literal reincarnation memory.\n';
              directive += 'This is emotional resonance only.\n';
              directive += 'Echo Resonance must NOT override Fate Cards, alter Storyturn structure, or force romance or conflict. It is purely atmospheric.\n\n';
              directive += 'ECHO RESONANCE ACTIVE\nCharacters:\n';
              relevantThreads.forEach(t => {
                  const eA = imports.find(i => i.echo.echo_id === t.echo_a)?.echo;
                  const eB = imports.find(i => i.echo.echo_id === t.echo_b)?.echo;
                  const adaptedA = eA ? _generateWorldAdaptedName(eA.canonical_name || eA.name, currentWorld) : '?';
                  const adaptedB = eB ? _generateWorldAdaptedName(eB.canonical_name || eB.name, currentWorld) : '?';
                  directive += `  ${adaptedA}\n  ${adaptedB}\n`;
              });
              directive += 'Their emotional patterns echo across lives.\n';
              directive += 'The story may allow them to feel strangely drawn together or repelled.\n\n';
          }

          directive += '────────────────────────────────────\n';
          return directive;
      }

      // ── Legend System — reputation tracking across stories ──

      function _incrementStoriesAppeared(imports) {
          if (!imports || imports.length === 0) return;
          const all = _loadReincarnations();
          const importedIds = new Set(imports.map(i => i.echo.echo_id));
          const currentWorld = (state.picks?.world || 'unknown').toLowerCase();
          let changed = false;
          for (const echo of all) {
              if (importedIds.has(echo.echo_id)) {
                  echo.stories_appeared_in = (echo.stories_appeared_in || 0) + 1;
                  if (!Array.isArray(echo.world_history)) echo.world_history = [];
                  echo.world_history.push({ world: currentWorld });
                  changed = true;
              }
          }
          if (changed) {
              _saveReincarnations(all);
              console.log('[REINCARNATION] Incremented stories_appeared_in for', importedIds.size, 'echo(es), world:', currentWorld);
          }
      }

      async function _detectLegendaryMoment(imports) {
          if (!imports || imports.length === 0) return;
          if (state._legendEvaluationComplete) return;
          if (!window.StoryboundOrchestration?.callChatGPT) return;

          const allContent = (typeof StoryPagination !== 'undefined' && StoryPagination.getAllContent)
              ? StoryPagination.getAllContent().replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim()
              : '';
          const endingSlice = allContent.slice(-1500);
          if (endingSlice.length < 100) return;

          const charNames = imports.map(i => i.echo.canonical_name || i.echo.name).join(', ');

          try {
              const result = await window.StoryboundOrchestration.callChatGPT([
                  { role: 'system', content: 'You classify story endings. Respond ONLY with valid JSON, no markdown.' },
                  { role: 'user', content: `Analyze this story ending for characters: ${charNames}

ENDING EXCERPT:
"${endingSlice}"

For each character, classify:
- legendary: boolean (heroic sacrifice, world-changing decision, redemption arc, tragic downfall)
- betrayal: boolean (betrayal, corruption, moral collapse)

Return JSON array:
[{"name":"...","legendary":true/false,"betrayal":true/false}]

Only include characters that appear in the excerpt. Be strict — only TRUE for clear, unambiguous cases.` }
              ], { max_tokens: 80, temperature: 0.2 });

              const parsed = JSON.parse(result);
              if (!Array.isArray(parsed)) return;

              // Build name→echo_id map from imports (LLM returns names, we resolve to echo_id)
              const nameToId = {};
              for (const imp of imports) {
                  const n = (imp.echo.canonical_name || imp.echo.name || '').toLowerCase();
                  if (n) nameToId[n] = imp.echo.echo_id;
              }

              const all = _loadReincarnations();
              let changed = false;

              for (const classification of parsed) {
                  const matchName = (classification.name || '').toLowerCase();
                  const echoId = nameToId[matchName];
                  if (!echoId) continue;
                  const echo = all.find(e => e.echo_id === echoId);
                  if (!echo) continue;

                  if (classification.legendary) {
                      echo.legendary_moments = (echo.legendary_moments || 0) + 1;
                      echo.legend_score = Math.min(MAX_ECHO_LEGEND, (echo.legend_score || 0) + 5);
                      changed = true;
                      console.log(`[REINCARNATION] Legendary moment for ${echo.canonical_name || echo.name} (+5 legend, total: ${echo.legend_score})`);
                  }
                  if (classification.betrayal) {
                      echo.tragic_betrayals = (echo.tragic_betrayals || 0) + 1;
                      echo.legend_score = Math.min(MAX_ECHO_LEGEND, (echo.legend_score || 0) + 3);
                      changed = true;
                      console.log(`[REINCARNATION] Betrayal for ${echo.canonical_name || echo.name} (+3 legend, total: ${echo.legend_score})`);
                  }
              }

              if (changed) _saveReincarnations(all);
              state._legendEvaluationComplete = true;
          } catch (e) {
              console.warn('[REINCARNATION] Legend detection failed (non-critical):', e.message);
              state._legendEvaluationComplete = true; // prevent retry on failure too
          }
      }

      function _getEchoLegendSummary(echo) {
          return {
              name: echo.canonical_name || echo.name || 'Unknown',
              stories: echo.stories_appeared_in || 0,
              legend_score: echo.legend_score || 0,
              legendary_moments: echo.legendary_moments || 0,
              betrayals: echo.tragic_betrayals || 0
          };
      }

      // ── Integration hooks ──

      // Expose for system prompt builder
      window._buildReincarnationDirective = _buildReincarnationDirective;

      // Store current story's import selections on state
      window._storeReincarnationImports = function(imports) {
          state._reincarnationImports = imports || [];
      };

      // Expose for begin-story flow
      window._getReincarnationImports = function() {
          return state._reincarnationImports || [];
      };

      // Diversity safeguard check — called before story generation
      window._validateReincarnationDiversity = function(imports) {
          if (!imports || imports.length === 0) return { valid: true };
          if (imports.length > MAX_IMPORT_PER_STORY) {
              return { valid: false, reason: `Maximum ${MAX_IMPORT_PER_STORY} reincarnations per story.` };
          }
          // Check: not all primary roles occupied
          const roles = imports.map(i => i.role);
          const primaryRoles = ['romantic interest', 'antagonist', 'mentor'];
          const occupiedPrimary = primaryRoles.filter(r => roles.includes(r));
          if (occupiedPrimary.length >= primaryRoles.length) {
              return { valid: false, reason: 'Reincarnations cannot fill all primary narrative roles. Leave room for fresh characters.' };
          }
          return { valid: true };
      };

      // Expose legend system
      window._incrementStoriesAppeared = _incrementStoriesAppeared;
      window._detectLegendaryMoment = _detectLegendaryMoment;
      window._getEchoLegendSummary = _getEchoLegendSummary;
      window._generateWorldAdaptedName = _generateWorldAdaptedName;

      // HTML escape helper
      function _esc(s) {
          const d = document.createElement('div');
          d.textContent = s || '';
          return d.innerHTML;
      }

      // ── Echo Corridor Strip (Character Naming row) ──
      // Manual corridor slots only — typed echoes stored separately

      let _corridorEchoSlots = []; // [{echo, role}] — manual selections only
      let _typedPlayerEcho = null; // {echo, role} or null
      let _typedLIEcho = null;     // {echo, role} or null

      // ── Echo Import Pricing ──
      // Typed echoes (player/LI) are always free.
      // Corridor echoes cost Fortunes based on count:
      //   1 → free, 2 → 1, 3 → 2, 4 → 3, 5 → 5
      function _getEchoImportCost(corridorCount) {
          if (corridorCount <= 1) return 0;
          if (corridorCount === 2) return 1;
          if (corridorCount === 3) return 2;
          if (corridorCount === 4) return 3;
          if (corridorCount === 5) return 5;
          return 0;
      }
      window._getEchoImportCost = _getEchoImportCost;

      // ── Reincarnation Slot Buttons — dropdown menus for corridor selection ──
      window._initReincSlots = function() {
          const row = document.getElementById('reincSlotsRow');
          if (!row) return;
          const reincarnations = _loadReincarnations();
          const slots = row.querySelectorAll('.reinc-slot');
          slots.forEach(slot => {
              const btn = slot.querySelector('.reinc-slot-btn');
              const dropdown = slot.querySelector('.reinc-slot-dropdown');
              const label = slot.querySelector('.reinc-slot-label');
              const slotIdx = parseInt(slot.dataset.slot, 10);
              if (!btn || !dropdown || !label) return;
              // Guard against double-binding — this init can now run on every
              // identity-stage mount, and the DOM nodes persist across mounts.
              if (btn.dataset.reincBound === '1') return;
              btn.dataset.reincBound = '1';

              btn.addEventListener('click', (e) => {
                  e.stopPropagation();
                  // Close all other dropdowns first
                  row.querySelectorAll('.reinc-slot-dropdown').forEach(d => {
                      if (d !== dropdown) d.classList.add('hidden');
                  });
                  // Populate and toggle
                  dropdown.innerHTML = '';
                  // Placeholder names for empty slots
                  const PLACEHOLDER_NAMES = [
                      'Isolde Vane', 'Cassian Thorne', 'Elowen Ashford', 'Darius Kael',
                      'Seraphina Lux', 'Ronan Blackwell', 'Liora Dusk', 'Kiran Solace',
                      'Evangeline Cross', 'Lysander Hale', 'Maren Alder', 'Caelum Raine'
                  ];
                  if (reincarnations.length === 0) {
                      // Empty-state preview: show the dropdown AS IF the user had
                      // real reincarnations saved — names styled normally, plus a
                      // one-line explainer at the top. Clicking a placeholder
                      // populates the slot label VISUALLY but never writes to
                      // state._reincarnationImports (no real echo to import).
                      const header = document.createElement('div');
                      header.className = 'reinc-slot-dropdown-explainer';
                      header.textContent = 'You\u2019ll encounter characters you love throughout your stories. Save their essence here and meet them again on new adventures.';
                      dropdown.appendChild(header);
                      PLACEHOLDER_NAMES.forEach(name => {
                          const item = document.createElement('div');
                          item.className = 'reinc-slot-dropdown-item';
                          item.textContent = name;
                          item.addEventListener('click', (ev) => {
                              ev.stopPropagation();
                              label.textContent = name;
                              btn.classList.add('reinc-assigned');
                              dropdown.classList.add('hidden');
                              if (typeof showToast === 'function') showToast('Placeholder shown \u2014 finish a story to save real Reincarnations.');
                          });
                          dropdown.appendChild(item);
                      });
                  } else {
                      reincarnations.forEach(r => {
                          const item = document.createElement('div');
                          item.className = 'reinc-slot-dropdown-item';
                          item.textContent = r.name || r.echo_name || ('Echo #' + r.echo_id);
                          item.addEventListener('click', (ev) => {
                              ev.stopPropagation();
                              label.textContent = item.textContent;
                              btn.classList.add('reinc-assigned');
                              slot.dataset.echoId = r.echo_id;
                              dropdown.classList.add('hidden');
                              // Store import
                              if (!state._reincarnationImports) state._reincarnationImports = [];
                              // Remove existing from this slot
                              state._reincarnationImports = state._reincarnationImports.filter(imp => imp._slotIdx !== slotIdx);
                              state._reincarnationImports.push({ ...r, _slotIdx: slotIdx });
                          });
                          dropdown.appendChild(item);
                      });
                  }
                  // Clear option
                  if (slot.dataset.echoId) {
                      const clear = document.createElement('div');
                      clear.className = 'reinc-slot-dropdown-clear';
                      clear.textContent = 'Clear slot';
                      clear.addEventListener('click', (ev) => {
                          ev.stopPropagation();
                          label.textContent = 'Reincarnation ' + slotIdx;
                          btn.classList.remove('reinc-assigned');
                          delete slot.dataset.echoId;
                          dropdown.classList.add('hidden');
                          state._reincarnationImports = (state._reincarnationImports || []).filter(imp => imp._slotIdx !== slotIdx);
                      });
                      dropdown.appendChild(clear);
                  }
                  dropdown.classList.toggle('hidden');
              });
          });

          // Close dropdowns on outside click
          document.addEventListener('click', () => {
              row.querySelectorAll('.reinc-slot-dropdown').forEach(d => d.classList.add('hidden'));
          });
      };

      // Auto-init when corridor mounts the character section
      if (document.readyState === 'loading') {
          document.addEventListener('DOMContentLoaded', () => { if (window._initReincSlots) window._initReincSlots(); });
      } else {
          setTimeout(() => { if (window._initReincSlots) window._initReincSlots(); }, 500);
      }

      function _getTypedEchoIds() {
          var ids = new Set();
          if (_typedPlayerEcho) ids.add(_typedPlayerEcho.echo.echo_id);
          if (_typedLIEcho) ids.add(_typedLIEcho.echo.echo_id);
          return ids;
      }

      function _renderEchoCorridorStrip() {
          const container = document.getElementById('echoCorridorSlots');
          const strip = document.getElementById('echoCorridorStrip');
          if (!container || !strip) return;

          const reincarnations = _loadReincarnations();
          const _tierLimit = _getTierReincLimit();
          if (reincarnations.length === 0 || _tierLimit <= 0) {
              strip.classList.add('hidden');
              return;
          }
          strip.classList.remove('hidden');
          container.innerHTML = '';

          // Build thread lookup for adjacent connector rendering
          const threads = _loadThreads();
          const _threadPairSet = new Set();
          if (threads.length > 0 && _corridorEchoSlots.length >= 2) {
              for (var ti = 0; ti < _corridorEchoSlots.length - 1; ti++) {
                  var idA = _corridorEchoSlots[ti].echo.echo_id;
                  var idB = _corridorEchoSlots[ti + 1].echo.echo_id;
                  var hasThread = threads.some(function(t) {
                      return (t.echo_a === idA && t.echo_b === idB) || (t.echo_a === idB && t.echo_b === idA);
                  });
                  if (hasThread) _threadPairSet.add(ti);
              }
          }

          // Render filled manual slots only (typed echoes show on cards, not here)
          _corridorEchoSlots.forEach((slot, i) => {
              // Insert thread connector before this card if linked to previous
              if (i > 0 && _threadPairSet.has(i - 1)) {
                  const connector = document.createElement('div');
                  connector.className = 'echo-corridor-thread';
                  container.appendChild(connector);
              }

              const card = document.createElement('div');
              card.className = 'echo-slot-card echo-slot-filled';
              card.dataset.index = i;
              const name = slot.echo.canonical_name || slot.echo.name || 'Unknown';
              const roleLabel = slot.role.charAt(0).toUpperCase() + slot.role.slice(1);
              card.innerHTML = '<div class="echo-slot-name">' + _esc(name) + '</div>'
                  + '<div class="echo-slot-role">' + _esc(roleLabel) + '</div>'
                  + '<div class="echo-slot-remove" title="Remove">\u00d7</div>';
              card.querySelector('.echo-slot-remove').addEventListener('click', function(e) {
                  e.stopPropagation();
                  _corridorEchoSlots.splice(i, 1);
                  _renderEchoCorridorStrip();
              });
              container.appendChild(card);
          });

          // Selector card if room remains (tier-gated slots)
          var _slotLimit = _getTierReincLimit();
          if (_corridorEchoSlots.length < _slotLimit) {
              const selector = document.createElement('div');
              selector.className = 'echo-slot-card echo-slot-selector';
              selector.innerHTML = '<div class="echo-slot-plus">+</div><div class="echo-slot-selector-label">Add Echo</div>';
              selector.addEventListener('click', _openEchoCorridorPicker);
              container.appendChild(selector);
          }

          // ── Cost display (below slots, inside the strip) ──
          const costCount = _corridorEchoSlots.length;
          const cost = _getEchoImportCost(costCount);
          let costEl = strip.querySelector('.echo-corridor-cost');
          if (cost > 0) {
              if (!costEl) {
                  costEl = document.createElement('div');
                  costEl.className = 'echo-corridor-cost';
                  strip.appendChild(costEl);
              }
              costEl.innerHTML = '<span class="echo-cost-label">Bending Fate: ' + cost + ' Fortune' + (cost !== 1 ? 's' : '') + '</span>'
                  + '<span class="echo-cost-tip">Bending fate draws many souls back into the same story.</span>';
              costEl.style.display = '';
          } else if (costEl) {
              costEl.style.display = 'none';
          }

          // Keep mini-cards in sync
          if (typeof _renderReincMiniCards === 'function') _renderReincMiniCards();
      }

      function _addEchoToCorridorSlot(echo, role) {
          if (_corridorEchoSlots.length >= _getTierReincLimit()) return;
          if (_corridorEchoSlots.some(function(s) { return s.echo.echo_id === echo.echo_id; })) return;
          // Prevent adding an echo already bound as a typed echo
          if (_getTypedEchoIds().has(echo.echo_id)) return;
          _corridorEchoSlots.push({ echo: echo, role: role });
          _renderEchoCorridorStrip();
          // Sparkle animation on newly added card
          var container = document.getElementById('echoCorridorSlots');
          if (container) {
              var cards = container.querySelectorAll('.echo-slot-filled');
              var lastCard = cards[cards.length - 1];
              if (lastCard) {
                  lastCard.classList.add('echo-slot-sparkle-in');
                  setTimeout(function() { lastCard.classList.remove('echo-slot-sparkle-in'); }, 400);
              }
          }
      }

      async function _openEchoCorridorPicker() {
          var remaining = _getTierReincLimit() - _corridorEchoSlots.length;
          if (remaining <= 0) return;
          _importCap = remaining;
          // Exclude both corridor slots and typed echoes from picker
          var exclude = new Set(_corridorEchoSlots.map(function(s) { return s.echo.echo_id; }));
          _getTypedEchoIds().forEach(function(id) { exclude.add(id); });
          _excludeEchoIds = exclude;
          try {
              var imports = await window.openReincarnationImport();
              if (imports && imports.length > 0) {
                  imports.forEach(function(imp) { _addEchoToCorridorSlot(imp.echo, imp.role); });
              }
          } catch (e) {
              console.warn('[ECHO CORRIDOR] Picker error:', e.message);
          }
          _importCap = _getTierReincLimit();
          _excludeEchoIds = new Set();
      }

      // ── Echo Card Soul Display (inside character tarot cards) ──

      function _renderEchoCardSoul(cardId, echo) {
          var card = document.getElementById(cardId);
          if (!card) return;
          var fields = card.querySelector('.character-tarot-fields');
          if (!fields) return;
          var existing = fields.querySelector('.echo-card-soul');

          if (!echo) {
              if (existing) existing.remove();
              return;
          }

          if (!existing) {
              existing = document.createElement('div');
              existing.className = 'echo-card-soul';
              fields.appendChild(existing);
          }

          // Build star row from world_history
          var history = echo.world_history || [];
          var count = Math.max(history.length, echo.stories_appeared_in || 0);
          var starsHtml = '';
          for (var s = 0; s < count; s++) {
              if (s < history.length) {
                  var w = (history[s].world || '').toLowerCase();
                  var cls = WORLD_STAR_CLASS[w] || 'star-world-unknown';
                  starsHtml += '<span class="echo-star ' + cls + '">\u2605</span>';
              } else {
                  starsHtml += '<span class="echo-star star-world-unknown">\u2605</span>';
              }
          }

          var legendScore = echo.legend_score || 0;
          existing.innerHTML = '<div class="echo-soul-divider"></div>'
              + '<div class="echo-soul-label">Echo Soul</div>'
              + (starsHtml ? '<div class="echo-soul-stars">' + starsHtml + '</div>' : '')
              + '<div class="echo-soul-legend">Legend ' + legendScore + '</div>';
      }

      function _autoDetectEchoByName(name, source) {
          var cardId = (source === 'typed_player') ? 'playerCharacterCard' : 'loveInterestCharacterCard';

          if (!name || name.trim().length < 2) {
              if (source === 'typed_player') _typedPlayerEcho = null;
              else _typedLIEcho = null;
              _renderEchoCardSoul(cardId, null);
              return;
          }

          var reincarnations = _loadReincarnations();
          var normalized = name.toLowerCase().trim();
          var match = reincarnations.find(function(r) {
              var canonical = (r.canonical_name || r.name || '').toLowerCase().trim();
              return canonical === normalized;
          });

          if (match) {
              var matchedId = match.echo_id;

              // ── Duplicate typed echo protection ──
              if (source === 'typed_player' && _typedLIEcho && _typedLIEcho.echo.echo_id === matchedId) {
                  // Player role takes precedence — evict from LI
                  _typedLIEcho = null;
                  _renderEchoCardSoul('loveInterestCharacterCard', null);
              } else if (source === 'typed_li' && _typedPlayerEcho && _typedPlayerEcho.echo.echo_id === matchedId) {
                  // LI role refuses duplicate — player already owns this soul
                  if (typeof showToast === 'function') showToast('This soul already inhabits you.');
                  _typedLIEcho = null;
                  _renderEchoCardSoul(cardId, null);
                  return;
              }

              var role = (source === 'typed_player') ? 'player character' : 'love interest';
              var entry = { echo: match, role: role };
              if (source === 'typed_player') _typedPlayerEcho = entry;
              else _typedLIEcho = entry;
              _renderEchoCardSoul(cardId, match);
              // Remove from corridor slots if duplicate (typed takes precedence)
              var prevLen = _corridorEchoSlots.length;
              _corridorEchoSlots = _corridorEchoSlots.filter(function(s) { return s.echo.echo_id !== matchedId; });
              if (_corridorEchoSlots.length !== prevLen) _renderEchoCorridorStrip();
          } else {
              if (source === 'typed_player') _typedPlayerEcho = null;
              else _typedLIEcho = null;
              _renderEchoCardSoul(cardId, null);
          }
      }

      function _collectCorridorEchoes() {
          var result = [];
          if (_typedPlayerEcho) result.push(_typedPlayerEcho);
          if (_typedLIEcho) result.push(_typedLIEcho);
          return result.concat(_corridorEchoSlots).slice(0, MAX_IMPORT_PER_STORY);
      }

      function _clearCorridorEchoSlots() {
          _corridorEchoSlots = [];
          _typedPlayerEcho = null;
          _typedLIEcho = null;
          _renderEchoCardSoul('playerCharacterCard', null);
          _renderEchoCardSoul('loveInterestCharacterCard', null);
          _renderEchoCorridorStrip();
      }

      // Auto-detect echo names from character name inputs
      var _playerNameInput = document.getElementById('playerNameInput');
      var _partnerNameInput = document.getElementById('partnerNameInput');
      if (_playerNameInput) {
          _playerNameInput.addEventListener('blur', function() { _autoDetectEchoByName(_playerNameInput.value, 'typed_player'); });
      }
      if (_partnerNameInput) {
          _partnerNameInput.addEventListener('blur', function() { _autoDetectEchoByName(_partnerNameInput.value, 'typed_li'); });
      }

      // Initial render (strip hidden until vault has echoes)
      _renderEchoCorridorStrip();

      // ── Reincarnation Mini-Cards (below character cards) ──
      var EMPTY_SLOT_COUNT = 7; // visual total (matches Chosen tier max)

      function _renderReincMiniCards() {
          const section = document.getElementById('echoReincSection');
          const container = document.getElementById('echoReincCards');
          const explainer = document.getElementById('echoReincExplainer');
          if (!section || !container) return;

          const reincarnations = _loadReincarnations();
          const slotLimit = _getTierReincLimit();
          container.innerHTML = '';

          // ── Explainer text ──
          if (explainer) {
              if (!state.subscribed) {
                  explainer.textContent = 'Members can Reincarnate their favorite characters in new stories.';
              } else if (reincarnations.length === 0) {
                  explainer.textContent = 'Finish a story to save its characters here as reincarnations.';
              } else if (state.subscriptionTier === 'chosen') {
                  explainer.textContent = 'Fate loves bringing people together.';
              } else {
                  explainer.textContent = reincarnations.length === 1
                      ? 'A reincarnation from a past story awaits. Tap to weave them into this one.'
                      : reincarnations.length + ' reincarnations from past stories await. Tap to weave them in.';
              }
          }

          // ── Build lookup for active echoes ──
          const usedIds = _getTypedEchoIds();
          const corridorIds = new Set(_corridorEchoSlots.map(function(s) { return s.echo.echo_id; }));

          // ── Render 7 slots: available ones first (filled or empty), then locked ──
          for (var i = 0; i < EMPTY_SLOT_COUNT; i++) {
              var isLocked = i >= slotLimit;
              var echo = reincarnations[i] || null;

              if (isLocked) {
                  // Locked slot — greyed out
                  var locked = document.createElement('div');
                  locked.className = 'echo-reinc-card echo-reinc-card-locked';
                  locked.innerHTML = '<div class="echo-reinc-card-lock">\u{1F512}</div>';
                  locked.title = _getReincLockTooltip(i);
                  (function(tip) {
                      locked.addEventListener('click', function() {
                          if (typeof showToast === 'function') showToast(tip);
                      });
                  })(_getReincLockTooltip(i));
                  container.appendChild(locked);
              } else if (echo) {
                  // Available slot with a saved reincarnation
                  var card = document.createElement('div');
                  var isActive = usedIds.has(echo.echo_id) || corridorIds.has(echo.echo_id);
                  card.className = 'echo-reinc-card echo-reinc-card-filled' + (isActive ? ' echo-reinc-selected' : '');
                  card.dataset.echoId = echo.echo_id;
                  if (state.subscriptionTier === 'chosen') card.title = 'Fate loves bringing people together';

                  var name = echo.canonical_name || echo.name || 'Unknown';
                  var legendScore = echo.legend_score || 0;
                  var legendHtml = legendScore > 0 ? '<div class="echo-reinc-card-legend">' + _esc(String(legendScore)) + '</div>' : '';
                  var roleHtml = echo.role_archetype
                      ? '<div class="echo-reinc-card-role">' + _esc(echo.role_archetype.slice(0, 30)) + '</div>'
                      : '';

                  card.innerHTML = '<div class="echo-reinc-card-name">' + _esc(name) + '</div>'
                      + roleHtml + legendHtml;

                  (function(echo, isActive) {
                      card.addEventListener('click', function() {
                          if (isActive) {
                              // If bound via Character/Love Interest name card, can't deselect here
                              if (_getTypedEchoIds().has(echo.echo_id)) {
                                  if (typeof showToast === 'function') showToast('Change the Character or Love Interest name to free this reincarnation.');
                                  return;
                              }
                              _corridorEchoSlots = _corridorEchoSlots.filter(function(s) { return s.echo.echo_id !== echo.echo_id; });
                              _renderEchoCorridorStrip();
                              _renderReincMiniCards();
                              return;
                          }
                          var currentLimit = _getTierReincLimit();
                          if (_corridorEchoSlots.length >= currentLimit) {
                              if (typeof showToast === 'function') showToast('Maximum ' + currentLimit + ' reincarnation slots for your tier.');
                              return;
                          }
                          _addEchoToCorridorSlot(echo, 'supporting character');
                          _renderReincMiniCards();
                      });
                  })(echo, isActive);

                  container.appendChild(card);
              } else {
                  // Available but empty slot — placeholder
                  var empty = document.createElement('div');
                  empty.className = 'echo-reinc-card echo-reinc-card-empty';
                  empty.innerHTML = '<div class="echo-reinc-card-plus">?</div>';
                  if (state.subscriptionTier === 'chosen') empty.title = 'Fate loves bringing people together';
                  empty.addEventListener('click', function() {
                      if (typeof showToast === 'function') showToast('Complete a story to extract character reincarnations here.');
                  });
                  container.appendChild(empty);
              }
          }
      }

      // Render on init
      _renderReincMiniCards();

      // ══════════════════════════════════════════════════════════════
      // MID-STORY REINCARNATION CAPTURE — "Bind Reincarnation"
      // ══════════════════════════════════════════════════════════════

      const MAX_REINCARNATIONS_PER_STORY = 5;

      /**
       * Build list of capturable characters from current story state.
       * Returns array of { character_id, name, role_type, scene_count, dialogue_count, source }
       */
      function _getEligibleReincarnationCandidates() {
          const candidates = [];
          const turnCount = state.turnCount || 0;

          // Player character — always eligible if story has begun
          const pName = state.picks?.identity?.displayPlayerName || state.playerName || '';
          if (pName && turnCount >= 1) {
              candidates.push({
                  character_id: 'player_' + (state.storyId || ''),
                  name: pName,
                  role_type: 'protagonist',
                  scene_count: turnCount,
                  dialogue_count: turnCount,
                  source: 'player',
                  gender: state.gender || 'Unknown',
                  pronouns: state.authorPronouns || ''
              });
          }

          // Love interest — eligible if named
          const liName = state.picks?.identity?.displayPartnerName || state.loveInterestName || '';
          if (liName && turnCount >= 1) {
              candidates.push({
                  character_id: 'li_' + (state.storyId || ''),
                  name: liName,
                  role_type: 'love interest',
                  scene_count: turnCount,
                  dialogue_count: turnCount,
                  source: 'npc_love_interest',
                  gender: state.loveInterest || 'Unknown',
                  pronouns: resolveLIPronounsFromGender(state.loveInterest)
              });
          }

          // Secondary characters (rivals, observers, antagonists)
          const secondary = state.secondaryCharacters || { rivals: [], observers: [], antagonists: [] };
          const roleMap = { rivals: 'rival', observers: 'observer', antagonists: 'antagonist' };
          for (const [key, role] of Object.entries(roleMap)) {
              const names = secondary[key] || [];
              for (const name of names) {
                  if (!name || typeof name !== 'string' || name.trim().length === 0) continue;
                  candidates.push({
                      character_id: role + '_' + name.toLowerCase().replace(/\s+/g, '_') + '_' + (state.storyId || ''),
                      name: name.trim(),
                      role_type: role,
                      scene_count: Math.max(2, Math.floor(turnCount * 0.5)),
                      dialogue_count: 1,
                      source: 'npc_' + role,
                      gender: 'Unknown',
                      pronouns: ''
                  });
              }
          }

          return candidates;
      }

      /**
       * Render the capture modal character list with radio selection.
       */
      function _renderReincarnationCaptureList() {
          const list = document.getElementById('reincarnationCaptureList');
          const confirmBtn = document.getElementById('reincarnationCaptureConfirm');
          if (!list || !confirmBtn) return;

          const candidates = _getEligibleReincarnationCandidates();
          list.innerHTML = '';
          let _selectedIdx = -1;

          if (candidates.length === 0) {
              list.innerHTML = '<div style="font-family:Lora,serif; color:var(--ink); opacity:0.5; font-style:italic; padding:16px 0;">No characters available yet. Continue the story first.</div>';
              confirmBtn.disabled = true;
              return;
          }

          // Check which characters are already preserved from this story
          const existing = _loadReincarnations();
          const currentStoryId = state.storyId || '';

          candidates.forEach(function(c, i) {
              const alreadySaved = existing.some(function(r) {
                  return (r.canonical_name || r.name) === c.name && r.source_story_id === currentStoryId;
              });

              const card = document.createElement('div');
              card.className = 'reincarnation-capture-card' + (alreadySaved ? ' already-saved' : '');
              if (alreadySaved) {
                  card.style.opacity = '0.4';
                  card.style.pointerEvents = 'none';
              }

              // Neutral labels — never reveal internal role classification (spoiler risk)
              var displayRole = c.role_type === 'protagonist' ? 'You'
                  : c.role_type === 'love interest' ? 'Love Interest'
                  : 'Character';
              card.innerHTML = '<div class="reincarnation-capture-radio"></div>'
                  + '<div class="reincarnation-capture-info">'
                  + '<div class="reincarnation-capture-name">' + _esc(c.name) + '</div>'
                  + '<div class="reincarnation-capture-role">' + _esc(displayRole)
                  + (alreadySaved ? ' — <em>already preserved</em>' : '') + '</div>'
                  + '</div>';

              if (!alreadySaved) {
                  card.addEventListener('click', function() {
                      // Deselect previous
                      list.querySelectorAll('.reincarnation-capture-card.selected').forEach(function(el) { el.classList.remove('selected'); });
                      card.classList.add('selected');
                      _selectedIdx = i;
                      confirmBtn.disabled = false;
                  });
              }
              list.appendChild(card);
          });

          confirmBtn.disabled = true;

          // Wire confirm button
          confirmBtn.onclick = async function() {
              if (_selectedIdx < 0 || _selectedIdx >= candidates.length) return;
              const candidate = candidates[_selectedIdx];

              // Per-story save cap
              if ((state._reincarnationsSavedThisStory || 0) >= MAX_REINCARNATIONS_PER_STORY) {
                  if (typeof showToast === 'function') showToast('You have preserved the maximum Reincarnations from this story.');
                  return;
              }

              // Duplicate check
              const existingNow = _loadReincarnations();
              const isDupe = existingNow.some(function(r) {
                  return (r.canonical_name || r.name) === candidate.name && r.source_story_id === (state.storyId || '');
              });
              if (isDupe) {
                  if (typeof showToast === 'function') showToast('This soul has already been preserved.');
                  return;
              }

              confirmBtn.disabled = true;
              confirmBtn.textContent = 'Preserving...';

              try {
                  // Use existing extraction pipeline
                  const charInfo = {
                      name: candidate.name,
                      source: candidate.source,
                      gender: candidate.gender,
                      pronouns: candidate.pronouns
                  };
                  const essence = await _extractCharacterEssence(charInfo);

                  // Persist
                  const all = _loadReincarnations();
                  const dupeIdx = all.findIndex(function(e) {
                      return (e.canonical_name || e.name) === (essence.canonical_name || essence.name)
                          && e.source_story_id === essence.source_story_id;
                  });
                  if (dupeIdx >= 0) all[dupeIdx] = essence;
                  else all.push(essence);
                  _saveReincarnations(all);

                  // Track per-story count
                  state._reincarnationsSavedThisStory = (state._reincarnationsSavedThisStory || 0) + 1;

                  // Close modal
                  document.getElementById('reincarnationCaptureModal')?.classList.add('hidden');

                  // Toast + sparkle
                  if (typeof showToast === 'function') showToast('Reincarnation preserved.');

                  // Sparkle effect on toast
                  var toast = document.getElementById('toast');
                  if (toast) {
                      var sparkle = document.createElement('span');
                      sparkle.className = 'reinc-capture-sparkle';
                      sparkle.textContent = '✦';
                      toast.style.position = 'relative';
                      toast.appendChild(sparkle);
                      setTimeout(function() { sparkle.remove(); }, 700);
                  }

                  console.log('[REINCARNATION] Mid-story capture:', essence.canonical_name || essence.name);
              } catch (e) {
                  console.error('[REINCARNATION] Capture failed:', e);
                  if (typeof showToast === 'function') showToast('Capture failed — try again.');
              } finally {
                  confirmBtn.textContent = 'Preserve Reincarnation';
                  confirmBtn.disabled = false;
              }
          };
      }

      /**
       * Open the mid-story Reincarnation capture modal.
       */
      function _openReincarnationCaptureModal() {
          // Must be in an active story
          if (!state.storyId || (state.turnCount || 0) < 1) {
              if (typeof showToast === 'function') showToast('Begin a story first.');
              return;
          }

          // Per-story cap check
          if ((state._reincarnationsSavedThisStory || 0) >= MAX_REINCARNATIONS_PER_STORY) {
              if (typeof showToast === 'function') showToast('You have preserved the maximum Reincarnations from this story.');
              return;
          }

          _renderReincarnationCaptureList();
          document.getElementById('reincarnationCaptureModal')?.classList.remove('hidden');
      }

      // Cancel button
      document.getElementById('reincarnationCaptureCancel')?.addEventListener('click', function() {
          document.getElementById('reincarnationCaptureModal')?.classList.add('hidden');
      });

      // Expose to window for Scene Actions menu
      window._openReincarnationCaptureModal = _openReincarnationCaptureModal;

      // Expose corridor functions
      window._initEchoCorridorStrip = _renderEchoCorridorStrip;
      window._renderReincMiniCards = _renderReincMiniCards;
      window._collectCorridorEchoes = _collectCorridorEchoes;
      window._clearCorridorEchoSlots = _clearCorridorEchoSlots;
      Object.defineProperty(window, '_corridorEchoSlots', { get: () => _corridorEchoSlots });

      console.log('[REINCARNATION] System initialized');
  })();

  // ═══════════════════════════════════════════════════════════════════
  // FATE EVENTS — Story-triggered Fortune promotions (+25% for 12h)
  // Triggers on narrative milestones. Max 1 per week per player.
  // ═══════════════════════════════════════════════════════════════════
  (function initFateEvents() {

      const FATE_EVENT_CONFIG = {
          bonus_multiplier: 1.25,
          duration_hours: 12,
          cooldown_days: 7
      };

      const FATE_EVENT_STORAGE_KEY = 'sb_fate_event';

      const VALID_TRIGGERS = [
          'scene_10_reached',
          'first_story_completed',
          'tempt_fate_used',
          'first_reincarnation_summoned',
          'first_time_fortune_depleted'
      ];

      const FATE_TRIGGER_COPY = {
          scene_10_reached: "Fate honors your journey deeper into the story.",
          first_story_completed: "Fate honors your first story completion.",
          tempt_fate_used: "You tempted Fate — and Fate answers.",
          first_reincarnation_summoned: "A soul returns. Fate stirs.",
          first_time_fortune_depleted: "Even when Fortune falters, Fate remembers.",
          trophy_earned: "Your legend grows. Fate takes notice."
      };

      // ── State Hydration ──

      function _loadFateEventState() {
          try {
              const raw = localStorage.getItem(FATE_EVENT_STORAGE_KEY);
              if (!raw) return null;
              return JSON.parse(raw);
          } catch { return null; }
      }

      function _saveFateEventState(data) {
          localStorage.setItem(FATE_EVENT_STORAGE_KEY, JSON.stringify(data));
          // Non-critical Supabase sync
          _syncFateEventToSupabase(data);
      }

      function _syncFateEventToSupabase(data) {
          try {
              if (!sb || !sb.auth) return;
              sb.auth.getUser().then(function(res) {
                  var user = res?.data?.user;
                  if (!user) return;
                  sb.from('profiles').update({
                      fate_event_state: JSON.stringify(data)
                  }).eq('id', user.id).then(function() {}, function(err) {
                      console.warn('[FATE_EVENT] Supabase sync failed:', err);
                  });
              });
          } catch (e) {
              console.warn('[FATE_EVENT] Supabase sync error:', e);
          }
      }

      // Hydrate on init
      var _fateState = _loadFateEventState() || {
          lastFateEventAt: null,
          activeFateEvent: null,
          triggersUsed: {}
      };

      // Also set on state for external access
      state.lastFateEventAt = _fateState.lastFateEventAt || null;
      state.activeFateEvent = _fateState.activeFateEvent || null;

      // ── Expiration Check ──

      function _isFateEventActive() {
          if (!_fateState.activeFateEvent) return false;
          var expiresAt = typeof _fateState.activeFateEvent.expires_at === 'number'
              ? _fateState.activeFateEvent.expires_at
              : new Date(_fateState.activeFateEvent.expires_at).getTime();
          if (Date.now() >= expiresAt) {
              // Expired — clear state + loading counter
              _fateState.activeFateEvent = null;
              state.activeFateEvent = null;
              state.fateEventLoadingDisplays = 0;
              _saveFateEventState(_fateState);
              _updateFateEventBadges();
              return false;
          }
          return true;
      }

      // ── Trigger ──

      function _tryTriggerFateEvent(triggerType) {
          if (VALID_TRIGGERS.indexOf(triggerType) === -1) {
              console.warn('[FATE_EVENT] Invalid trigger type:', triggerType);
              return false;
          }

          // Safety guard: prevent duplicate activation during same story moment
          if (state.activeFateEvent && Date.now() < new Date(state.activeFateEvent.expires_at).getTime()) {
              return false;
          }

          // Already active?
          if (_isFateEventActive()) {
              console.log('[FATE_EVENT] Already active, skipping trigger:', triggerType);
              return false;
          }

          // Cooldown enforcement (7 days, timestamp-based)
          if (_fateState.lastFateEventAt) {
              var lastTs = typeof _fateState.lastFateEventAt === 'number'
                  ? _fateState.lastFateEventAt
                  : new Date(_fateState.lastFateEventAt).getTime();
              if (Date.now() - lastTs < FATE_EVENT_CONFIG.cooldown_days * 86400000) {
                  console.log('[FATE_EVENT] Cooldown active, skipping. Last:', _fateState.lastFateEventAt);
                  return false;
              }
          }

          // Per-story dedup: some triggers only fire once per story
          var storyKey = triggerType + '_' + (state.storyId || 'none');
          if (_fateState.triggersUsed[storyKey]) {
              console.log('[FATE_EVENT] Trigger already used this story:', storyKey);
              return false;
          }

          // Activate (timestamps as epoch ms for timezone safety)
          var nowTs = Date.now();
          var expiresTs = nowTs + FATE_EVENT_CONFIG.duration_hours * 3600000;

          _fateState.lastFateEventAt = nowTs;
          _fateState.activeFateEvent = {
              started_at: nowTs,
              expires_at: expiresTs,
              trigger: triggerType
          };
          _fateState.triggersUsed[storyKey] = true;

          state.lastFateEventAt = nowTs;
          state.activeFateEvent = _fateState.activeFateEvent;
          state.fateEventLoadingDisplays = 0;

          _saveFateEventState(_fateState);

          console.log('[FATE_EVENT] Activated! Trigger:', triggerType, 'Expires:', new Date(expiresTs).toISOString());

          // Update badges (no modal — message shown during loading moments instead)
          _updateFateEventBadges();

          return true;
      }

      // ── Badge UI ──

      function _updateFateEventBadges() {
          var isActive = _isFateEventActive();
          var badges = document.querySelectorAll('.fate-event-badge');
          badges.forEach(function(badge) {
              if (isActive) {
                  badge.classList.remove('hidden');
              } else {
                  badge.classList.add('hidden');
              }
          });
      }

      // ── Bonus Multiplier (exposed for purchaseFortunePack) ──

      window._getFateEventBonusMultiplier = function() {
          return _isFateEventActive() ? FATE_EVENT_CONFIG.bonus_multiplier : 1;
      };

      window._isFateEventActive = _isFateEventActive;

      // ── Expose trigger for integration hooks ──

      window._tryTriggerFateEvent = _tryTriggerFateEvent;

      // ── Periodic expiration check (every 60s) ──

      setInterval(function() {
          if (_fateState.activeFateEvent && !_isFateEventActive()) {
              console.log('[FATE_EVENT] Event expired during session');
          }
      }, 60000);

      // ── Init badge state ──
      if (document.readyState === 'loading') {
          document.addEventListener('DOMContentLoaded', _updateFateEventBadges);
      } else {
          _updateFateEventBadges();
      }

      // ── Loading-moment message injection ──
      // Exposed for loading bar sequences to call
      // Render the Fate Whisper Card (static HTML element, shown/hidden)
      window._renderFateWhisperCard = function() {
          var el = document.getElementById('fateWhisperCard');
          var body = document.getElementById('fateWhisperBody');
          if (!el || !body) return;

          if (!_isFateEventActive() || (state.fateEventLoadingDisplays || 0) >= 3) {
              el.classList.add('hidden');
              return;
          }

          var triggerType = _fateState.activeFateEvent ? _fateState.activeFateEvent.trigger : null;
          var triggerLine = (triggerType && FATE_TRIGGER_COPY[triggerType]) ? FATE_TRIGGER_COPY[triggerType] : '';

          body.innerHTML = (triggerLine ? triggerLine + '<br/>' : '') + 'Fortune favors the bold.';

          // Reset animation state from previous cycle
          var inner = el.querySelector('.fate-whisper-inner');
          if (inner) { inner.classList.remove('opening', 'fade-out'); inner.style.opacity = ''; }

          el.classList.remove('hidden');
          state.fateEventLoadingDisplays = (state.fateEventLoadingDisplays || 0) + 1;
      };

      // Legacy injection hook — now delegates to whisper card
      window._injectFateEventLoadingMessage = function() {
          window._renderFateWhisperCard();
      };

      console.log('[FATE_EVENT] System initialized. Active:', _isFateEventActive());

      // ── Whisper Card click handler — unfold animation → modal ──
      document.addEventListener('DOMContentLoaded', function() {
          var whisper = document.getElementById('fateWhisperCard');
          if (!whisper) return;
          var inner = whisper.querySelector('.fate-whisper-inner');

          whisper.addEventListener('click', function(e) {
              e.stopPropagation();
              if (!inner) return;

              // Step 1: highlight (activation glow)
              inner.classList.add('opening');

              setTimeout(function() {
                  // Step 2: fade card out
                  inner.classList.add('fade-out');

                  // Step 3: pin modal so scene load won't close it
                  state._purchaseModalPinned = true;

                  // Step 4: open modal
                  if (typeof window.openFortunePurchaseModal === 'function') {
                      var modalEl = window.openFortunePurchaseModal();
                      // Step 5: tag modal for entrance animation
                      if (!modalEl) modalEl = document.getElementById('payModal');
                      if (modalEl) {
                          modalEl.classList.add('enter-from-whisper');
                          // Clean up animation class after it plays
                          setTimeout(function() { modalEl.classList.remove('enter-from-whisper'); }, 300);
                      }
                  }
              }, 140);
          });
      });

  })();

  // ═══════════════════════════════════════════════════════════════════
  // SEASONAL FORTUNE PROMOTIONS — Configurable bonus events
  // Dev HUD warning system + preview mode + purchase multiplier
  // ═══════════════════════════════════════════════════════════════════
  (function initSeasonalPromotions() {

      // ── PROMOTION CONFIG ──
      const SEASONAL_FORTUNE_EVENTS = [
          {
              id: 'christmas_fate',
              start_date: '12-22',
              end_date: '12-27',
              bonus_multiplier: 1.25,
              promo_copy: "Fortune favors the bold. Celebrate with 25% more Fortunes per purchase."
          },
          {
              id: 'valentines_desire',
              start_date: '02-12',
              end_date: '02-15',
              bonus_multiplier: 1.20,
              promo_copy: "Love is in the ink. 20% more Fortunes this Valentine's season."
          },
          {
              id: 'summer_solstice',
              start_date: '06-20',
              end_date: '06-23',
              bonus_multiplier: 1.15,
              promo_copy: "The longest day deserves the longest stories. 15% bonus Fortunes."
          },
          {
              id: 'halloween_veil',
              start_date: '10-29',
              end_date: '11-01',
              bonus_multiplier: 1.30,
              promo_copy: "The veil between worlds is thin. 30% more Fortunes to tempt fate."
          }
      ];

      const UPCOMING_WARNING_WINDOW = 72; // hours

      // ── STATE CALCULATION ──

      /**
       * Parse "MM-DD" to a Date object in the current year.
       * Handles cross-year promos (e.g., 12-30 to 01-02) by checking if end < start.
       */
      function _parsePromoDate(mmdd, yearOffset) {
          const [mm, dd] = mmdd.split('-').map(Number);
          const d = new Date();
          d.setFullYear(d.getFullYear() + (yearOffset || 0));
          d.setMonth(mm - 1, dd);
          d.setHours(0, 0, 0, 0);
          return d;
      }

      function _getPromoState(event) {
          const now = new Date();
          const thisYear = now.getFullYear();
          let start = _parsePromoDate(event.start_date);
          let end = _parsePromoDate(event.end_date);

          // Handle cross-year (e.g., start 12-30, end 01-02)
          if (end < start) {
              // If we're past the start, end is next year
              if (now >= start) {
                  end.setFullYear(thisYear + 1);
              } else {
                  // We might be in the first days of next year
                  start.setFullYear(thisYear - 1);
              }
          }
          end.setHours(23, 59, 59, 999);

          if (now >= start && now <= end) return 'active';
          if (now > end) return 'expired';
          return 'upcoming';
      }

      function _hoursUntilStart(event) {
          const start = _parsePromoDate(event.start_date);
          const now = new Date();
          // Handle cross-year
          if (start < now) start.setFullYear(start.getFullYear() + 1);
          return Math.max(0, (start - now) / (1000 * 60 * 60));
      }

      /**
       * Get the currently active promotion (or preview override).
       * Returns { event, state } or null.
       */
      function _getActivePromotion() {
          // Preview mode: ?preview_sale={event_id}
          const previewId = new URLSearchParams(window.location.search).get('preview_sale');
          if (previewId) {
              const previewEvent = SEASONAL_FORTUNE_EVENTS.find(e => e.id === previewId);
              if (previewEvent) return { event: previewEvent, state: 'active', preview: true };
          }

          // Check for active promotion
          for (const event of SEASONAL_FORTUNE_EVENTS) {
              const st = _getPromoState(event);
              if (st === 'active') return { event, state: st, preview: false };
          }
          return null;
      }

      /**
       * Get upcoming promotions within the warning window.
       */
      function _getUpcomingPromotions() {
          const upcoming = [];
          for (const event of SEASONAL_FORTUNE_EVENTS) {
              const st = _getPromoState(event);
              if (st === 'upcoming') {
                  const hours = _hoursUntilStart(event);
                  if (hours <= UPCOMING_WARNING_WINDOW) {
                      upcoming.push({ event, hoursUntil: hours });
                  }
              }
          }
          return upcoming;
      }

      // ── PROMOTION EFFECT (exposed for purchaseFortunePack) ──

      window._getSeasonalBonusMultiplier = function() {
          const promo = _getActivePromotion();
          return promo ? promo.event.bonus_multiplier : 1;
      };

      window._getSeasonalPromoLabel = function() {
          const promo = _getActivePromotion();
          return promo ? promo.event.promo_copy : null;
      };

      // ── PROMO BADGE UI ──

      function _updatePromoBadges() {
          const promo = _getActivePromotion();
          const badges = [
              document.getElementById('payCardPromoBadge'),
              document.getElementById('fortuneModalPromoBadge')
          ];

          badges.forEach(function(badge) {
              if (!badge) return;
              if (promo) {
                  badge.textContent = promo.event.promo_copy;
                  badge.classList.remove('hidden');
              } else {
                  badge.classList.add('hidden');
              }
          });
      }

      // Update badges when paywall or fortune modal opens
      const _origShowPaywall = window.showPaywall;
      if (typeof _origShowPaywall === 'function') {
          window.showPaywall = function() {
              _updatePromoBadges();
              return _origShowPaywall.apply(this, arguments);
          };
      }
      const _origOpenFortune = window.openFortunePurchaseModal;
      if (typeof _origOpenFortune === 'function') {
          window.openFortunePurchaseModal = function() {
              _updatePromoBadges();
              return _origOpenFortune.apply(this, arguments);
          };
      }

      // ── DEV HUD BANNER ──

      let _promoBannerDismissed = new Set();

      function _renderPromoDevBanner() {
          const banner = document.getElementById('promoDevBanner');
          if (!banner) return;

          // Only show for dev hosts
          const isDev = (typeof _isQaHost === 'function' && _isQaHost()) ||
                        new URLSearchParams(window.location.search).get('devpass') === 'storybound';
          if (!isDev) { banner.classList.add('hidden'); return; }

          // Check for upcoming promotions
          const upcoming = _getUpcomingPromotions();
          // Also check active preview
          const activePromo = _getActivePromotion();

          if (upcoming.length === 0 && !(activePromo && activePromo.preview)) {
              banner.classList.add('hidden');
              return;
          }

          // Prefer showing upcoming warning; fall back to active preview
          let targetEvent, countdownHtml, badgeText;

          if (upcoming.length > 0) {
              const u = upcoming[0];
              if (_promoBannerDismissed.has(u.event.id)) { banner.classList.add('hidden'); return; }
              targetEvent = u.event;
              const hours = Math.round(u.hoursUntil);
              countdownHtml = `Starts in <strong>${hours}</strong> hour${hours !== 1 ? 's' : ''}`;
              badgeText = 'UPCOMING';
          } else {
              if (_promoBannerDismissed.has(activePromo.event.id)) { banner.classList.add('hidden'); return; }
              targetEvent = activePromo.event;
              countdownHtml = '<strong>PREVIEW MODE</strong> — forced active via URL';
              badgeText = 'PREVIEW';
          }

          const bonusPct = Math.round((targetEvent.bonus_multiplier - 1) * 100);

          banner.innerHTML = ''
              + '<div class="promo-dev-banner-badge">' + badgeText + '</div>'
              + '<div class="promo-dev-banner-body">'
              +   '<div class="promo-dev-banner-title">' + _escHtml(targetEvent.id.replace(/_/g, ' ')) + ' (+' + bonusPct + '% bonus)</div>'
              +   '<div class="promo-dev-banner-countdown">' + countdownHtml + '</div>'
              +   '<div class="promo-dev-banner-copy">' + _escHtml(targetEvent.promo_copy) + '</div>'
              +   '<div class="promo-dev-banner-actions">'
              +     '<button class="qa-btn" data-promo-action="preview">Preview</button>'
              +     '<button class="qa-btn" data-promo-action="edit">Edit Config</button>'
              +     '<button class="qa-btn qa-btn--danger" data-promo-action="disable">Disable</button>'
              +   '</div>'
              + '</div>'
              + '<button class="promo-dev-banner-close" data-promo-action="dismiss">&times;</button>';

          banner.classList.remove('hidden');

          // Wire action buttons
          banner.querySelectorAll('[data-promo-action]').forEach(function(btn) {
              btn.addEventListener('click', function() {
                  var action = btn.dataset.promoAction;
                  if (action === 'dismiss') {
                      _promoBannerDismissed.add(targetEvent.id);
                      banner.classList.add('hidden');
                  } else if (action === 'preview') {
                      // Navigate to preview mode
                      var url = new URL(window.location);
                      url.searchParams.set('preview_sale', targetEvent.id);
                      window.location.href = url.toString();
                  } else if (action === 'edit') {
                      console.log('%c[PROMO CONFIG] SEASONAL_FORTUNE_EVENTS:', 'color: #ffd700; font-weight: bold');
                      console.log(JSON.parse(JSON.stringify(SEASONAL_FORTUNE_EVENTS)));
                      if (typeof showToast === 'function') showToast('Promotion config logged to console.');
                  } else if (action === 'disable') {
                      targetEvent._disabled = true;
                      _promoBannerDismissed.add(targetEvent.id);
                      banner.classList.add('hidden');
                      _updatePromoBadges();
                      if (typeof showToast === 'function') showToast('Promotion disabled for this session.');
                  }
              }, { once: true });
          });
      }

      function _escHtml(s) {
          var d = document.createElement('div');
          d.textContent = s;
          return d.innerHTML;
      }

      // ── INIT ──

      // Override _getActivePromotion to respect _disabled flag
      var _origGetActive = _getActivePromotion;
      function _getActivePromotionSafe() {
          var result = _origGetActive();
          if (result && result.event._disabled) return null;
          return result;
      }
      // Patch the exposed multiplier to respect disabled state
      window._getSeasonalBonusMultiplier = function() {
          var promo = _getActivePromotionSafe();
          return promo ? promo.event.bonus_multiplier : 1;
      };
      window._getSeasonalPromoLabel = function() {
          var promo = _getActivePromotionSafe();
          return promo ? promo.event.promo_copy : null;
      };

      // Expose config for dev console access
      window.SEASONAL_FORTUNE_EVENTS = SEASONAL_FORTUNE_EVENTS;

      // Render dev banner on DOMContentLoaded (or immediately if already loaded)
      if (document.readyState === 'loading') {
          document.addEventListener('DOMContentLoaded', _renderPromoDevBanner);
      } else {
          setTimeout(_renderPromoDevBanner, 100);
      }

      // Initial badge update
      _updatePromoBadges();

      console.log('[PROMO] Seasonal promotions initialized. Active:', _getActivePromotionSafe()?.event?.id || 'none');

  })();

      // ═══════════════════════════════════════════════════════════════════
      // QA RESET PANEL — Dev/sandbox testing tools
      // Guards: localhost + _devBypass active (Stripe must be in test mode)
      // NEVER appears in production.
      // ═══════════════════════════════════════════════════════════════════
      (function initQaResetPanel() {

          const QA_ADMIN_EMAILS = [
              'roman@storybound.love',
              'test@storybound.love',
              'admin@storybound.love'
          ];

          const triggerBtn = document.getElementById('qaResetTrigger');
          const panelEl = document.getElementById('qaResetPanel');
          const closeBtn = document.getElementById('qaResetPanelClose');
          const stateDisplay = document.getElementById('qaStateDisplay');

          if (!triggerBtn) { console.warn('[QA] #qaResetTrigger not found in DOM — aborting QA panel init'); return; }
          if (!panelEl)    { console.warn('[QA] #qaResetPanel not found in DOM — aborting QA panel init'); return; }

          // ── Single authoritative QA guard ──
          // Allows: localhost, 127.0.0.1, *.vercel.app (preview/dev)
          // Requires: ?devpass=storybound (sets window._devBypass at boot)
          // Blocks: production domains (storybound.love, www.storybound.love)
          //
          // BUG FIX: Previously, the trigger was shown at parse time via _isQaHost()
          // (inside the parent DevHUD IIFE), but the click handler checked _devBypass
          // which is set LATER in the async boot sequence. On Vercel preview, the
          // trigger was visible but _devBypass was always false at parse time, so
          // clicking did nothing. Now we defer BOTH visibility and handler attachment
          // to _activateQaPanel(), called from boot after _devBypass is set.
          let _qaActivated = false;

          window._activateQaPanel = function() {
              if (_qaActivated) return;
              const allowed = (typeof _isQaHost === 'function') && _isQaHost() && !!window._devBypass;
              if (!allowed) {
                  console.log('[QA] Not enabled — host:', location.hostname,
                      '| _isQaHost:', typeof _isQaHost === 'function' ? _isQaHost() : 'n/a',
                      '| _devBypass:', !!window._devBypass);
                  return;
              }
              _qaActivated = true;
              triggerBtn.classList.remove('hidden');
              triggerBtn.addEventListener('click', openPanel);
              if (closeBtn) closeBtn.addEventListener('click', closePanel);
              console.log('[QA] QA enabled | host:', location.hostname,
                  '| devpass: present | trigger: found | panel: found | click handler: attached');
          };

          function refreshStateDisplay() {
              if (!stateDisplay) return;
              const fortunes = (state.fortunes || 0);
              const spFortunes = (state.storypassFortunes || 0);
              const hasPass = state.storyId ? (localStorage.getItem('sb_storypass_' + state.storyId) === '1') : false;
              const sceneNum = state.turnCount || 0;
              const hasPending = !!(state._fatePausesPending);
              const access = state.access || 'unknown';

              // Real vs QA vs Effective tier display
              const realTier = state._realSubscribed ? (state._realSubscriptionTier || 'unknown') : 'none';
              const qaOverride = _readQaSubscriptionOverride();
              const qaDisplay = (qaOverride && qaOverride.active) ? qaOverride.tier : 'none';
              const effectiveTier = state.subscribed ? (state.subscriptionTier || 'unknown') : 'none';
              const qaSource = _getQaSource();

              stateDisplay.textContent =
                  'Fortunes: ' + fortunes + ' (storypass: ' + spFortunes + ')\n' +
                  'Real Tier: ' + realTier + '\n' +
                  'QA Override: ' + qaDisplay + '\n' +
                  'QA Source: ' + qaSource + (_qaSupabaseAvailable ? '' : ' (supabase unavailable)') + '\n' +
                  'Effective Tier: ' + effectiveTier + '\n' +
                  'Access: ' + access + '\n' +
                  'Storypass: ' + hasPass + ' (server: ' + !!state.hasPass + ')\n' +
                  'Scene: ' + sceneNum + '\n' +
                  'Pending Turn: ' + hasPending;
          }

          function openPanel() {
              refreshStateDisplay();
              panelEl.classList.remove('hidden');
          }

          function closePanel() {
              panelEl.classList.add('hidden');
          }

          // Expose for DevHUD command
          window._openQaResetPanel = openPanel;

          // ── Button handlers ──
          panelEl.addEventListener('click', async (e) => {
              const btn = e.target.closest('[data-qa]');
              if (!btn || btn.disabled) return;
              const action = btn.dataset.qa;
              btn.disabled = true;

              try {
                  switch (action) {

                  // ── RESET ECONOMY ──
                  case 'reset-fortunes':
                      state.fortunes = 0;
                      state.storypassFortunes = 0;
                      if (window.updateFortuneDisplay) window.updateFortuneDisplay();
                      // Server-side reset via Supabase if user available
                      try {
                          const user = window.supabase?.auth?.getUser
                              ? (await window.supabase.auth.getUser()).data?.user : null;
                          if (user) {
                              await window.supabase.from('profiles')
                                  .update({ fortunes: 0 })
                                  .eq('id', user.id);
                              console.log('[QA] Server fortunes reset to 0');
                          }
                      } catch (err) { console.warn('[QA] Server reset failed:', err); }
                      log('QA: Fortunes reset to 0');
                      break;

                  // ── GRANT FORTUNES ──
                  case 'grant-50':
                  case 'grant-200':
                  case 'grant-1000': {
                      const amount = action === 'grant-50' ? 50 : action === 'grant-200' ? 200 : 1000;
                      state.fortunes = (state.fortunes || 0) + amount;
                      if (window.updateFortuneDisplay) window.updateFortuneDisplay();
                      try {
                          const user = window.supabase?.auth?.getUser
                              ? (await window.supabase.auth.getUser()).data?.user : null;
                          if (user) {
                              await window.supabase.from('profiles')
                                  .update({ fortunes: state.fortunes })
                                  .eq('id', user.id);
                              // Ledger entry
                              await window.supabase.from('fortune_ledger').insert({
                                  user_id: user.id,
                                  source: 'qa_grant',
                                  amount: amount,
                                  reason: 'testing'
                              });
                              console.log('[QA] Server fortunes granted:', amount);
                          }
                      } catch (err) { console.warn('[QA] Server grant failed:', err); }
                      log('QA: +' + amount + ' fortunes (total: ' + state.fortunes + ')');
                      break;
                  }

                  // ── SUBSCRIPTION TIER (persisted to localStorage + Supabase attempt) ──
                  case 'set-storied':
                      _writeQaSubscriptionOverride(true, 'storied');
                      state.subscribed = true;
                      state.subscriptionTier = 'storied';
                      state.billingStatus = 'active';
                      syncTierFromAccess();
                      log('QA: Tier → Storied (persisted)');
                      break;

                  case 'set-favored':
                      _writeQaSubscriptionOverride(true, 'favored');
                      state.subscribed = true;
                      state.subscriptionTier = 'favored';
                      state.billingStatus = 'active';
                      syncTierFromAccess();
                      log('QA: Tier → Favored (persisted)');
                      break;

                  case 'set-chosen':
                      _writeQaSubscriptionOverride(true, 'chosen');
                      state.subscribed = true;
                      state.subscriptionTier = 'chosen';
                      state.billingStatus = 'active';
                      syncTierFromAccess();
                      log('QA: Tier → Chosen (persisted)');
                      break;

                  case 'remove-sub':
                      _writeQaSubscriptionOverride(false, null);
                      state.subscribed = false;
                      state.subscriptionTier = null;
                      state.billingStatus = null;
                      syncTierFromAccess();
                      log('QA: Subscription removed (persisted)');
                      break;

                  // ── STORYPASS (localStorage + Supabase has_storypass) ──
                  case 'remove-storypass':
                      if (state.storyId) {
                          // Clear localStorage (client-side gate source)
                          localStorage.removeItem('sb_storypass_' + state.storyId);
                          state.hasPass = false;
                          state.storypassFortunes = 0;
                          // Clear Supabase has_storypass (server-side gate source)
                          (async () => {
                              try {
                                  const user = window.supabase?.auth?.getUser
                                      ? (await window.supabase.auth.getUser()).data?.user : null;
                                  if (user) {
                                      await window.supabase.from('profiles')
                                          .update({ has_storypass: false })
                                          .eq('id', user.id);
                                      console.log('[QA] Supabase has_storypass cleared');
                                  }
                              } catch (err) { console.warn('[QA] Supabase storypass clear failed:', err); }
                          })();
                          syncTierFromAccess();
                          log('QA: Storypass removed (localStorage + Supabase) for story ' + state.storyId);
                      } else {
                          log('QA: No active storyId');
                      }
                      break;

                  // ── SCENE REWIND ──
                  case 'scene-20':
                      state.turnCount = 20;
                      state.tempQuillAllowance = 0;
                      // Ensure tease tier state is consistent for gate testing
                      log('QA: Scene → 20 (turnCount set, tempQuillAllowance cleared)');
                      break;

                  // ── CLEAR PENDING TURN ──
                  case 'clear-pending':
                      state._fatePausesPending = null;
                      state._fatePausesGateType = null;
                      state._fatePausesOpen = false;
                      state._isAdvancingScene = false;
                      try { sessionStorage.removeItem('sb_fatePausesPending'); } catch(e2) {}
                      // Restore input state
                      const actI = document.getElementById('actionInput');
                      const diaI = document.getElementById('dialogueInput');
                      if (actI) { actI.disabled = false; actI.value = ''; }
                      if (diaI) { diaI.disabled = false; diaI.value = ''; }
                      const subBtn = document.getElementById('submitBtn');
                      if (subBtn) { subBtn.classList.remove('submitting'); subBtn.disabled = false; }
                      // Close Fate Pauses modal if open
                      const fpM = document.getElementById('fatePausesModal');
                      if (fpM) fpM.classList.add('hidden');
                      log('QA: Pending turn cleared');
                      break;
                  }

                  refreshStateDisplay();
              } finally {
                  btn.disabled = false;
              }
          });
      })();

      log('Dev HUD ready — press ` to toggle');
  })();

// ═══════════════════════════════════════════════════════════════════════════
// PREMATURE ROMANCE COLLAPSE PREVENTION — DOCUMENTATION (APPEND-ONLY)
// ═══════════════════════════════════════════════════════════════════════════
//
// REGIME CONTEXT (LOCKED)
// ------------------------
// Storybound is a collaborative romance novel engine, not a simulator.
// Players express intent. The Story controls timing, consequences, and pacing.
//
// CORE RULE (AUTHORITATIVE)
// --------------------------
// Player actions that would collapse romantic tension must be honored in
// intent but deferred or reframed in outcome when Storyturn gates do not
// yet allow resolution.
//
// ROMANCE-COLLAPSING ACTIONS
// ---------------------------
// kiss      → Gate: ST3 (Permission phase)
// intimacy  → Gate: ST3 (Permission phase, Taste further restricts)
// commitment→ Gate: ST5 (Crisis resolution required)
// confession→ Gate: ST2 (Resistance phase minimum)
// closure   → Gate: ST5 (Crisis phase required)
// reunion   → Gate: ST6 (Integration phase required)
//
// REQUIRED BEHAVIOR (WHEN ACTION IS PREMATURE)
// ---------------------------------------------
// - Do NOT reject the action
// - Do NOT execute it literally
// - Do NOT explain the system
// - Do NOT punish the player's desire
//
// INSTEAD:
// - Preserve the desire — the player WANTED this
// - Introduce friction, interruption, or hesitation
// - Increase emotional charge
// - Maintain unresolved tension
//
// APPROVED NARRATIVE STRATEGIES
// ------------------------------
// 1. External Interruption — Someone enters, phone rings, alarm sounds
// 2. Internal Interruption — Character pulls back, hesitates, doubt surfaces
// 3. Mutual Hesitation — Both want it, both stop short
// 4. Almost-Touch — The gesture begins but doesn't complete
// 5. Recognition Without Fulfillment — Both acknowledge desire, neither acts
// 6. Deferral as Inevitability — Frame pause as building toward something greater
//
// 5TH PERSON GUIDANCE
// --------------------
// The Story may briefly acknowledge:
// "The story let this almost happen, knowing it would matter more later."
//
// HARD CONSTRAINTS
// -----------------
// ❌ No mechanical refusals
// ❌ No UI locks
// ❌ No mention of Storyturns
// ❌ No punishment for player desire
// ❌ No boredom-preserving neutrality
//
// SUCCESS CONDITION
// ------------------
// The player should feel:
// - Seen
// - Complicit
// - Slightly frustrated
// - MORE invested than before
//
// REGRESSION TEST
// ----------------
// Run: window.runPrematureRomanceTest()
//
// Verifies:
// - Kiss at ST1 → detected
// - Kiss at ST3 → allowed
// - Confession at ST1 → detected
// - Confession at ST2 → allowed
// - Commitment at ST4 → detected (gate is ST5)
// - Directive includes reframe strategy
//
// MANTRA (DO NOT REMOVE)
// -----------------------
// Desire is never wrong.
// Timing is never arbitrary.
//
// ═══════════════════════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════════════════════
// INTENT-CONSEQUENCE ROMANCE CONTROL — DOCUMENTATION (APPEND-ONLY)
// ═══════════════════════════════════════════════════════════════════════════
//
// REGIME CONTEXT (LOCKED)
// ------------------------
// Storybound is a collaborative romance novel engine governed by a genre contract.
// Players express intent. The Story controls timing, pacing, and consequences.
// Romantic meaning is earned, never rushed, never denied mechanically.
//
// CORE AXIOM (AUTHORITATIVE · MUST HOLD)
// ---------------------------------------
// Humans choose desire.
// The Story chooses when desire becomes consequential.
//
// ═══════════════════════════════════════════════════════════════════════════
// PART A — POLY MODE
// ═══════════════════════════════════════════════════════════════════════════
//
// PURPOSE: Allow multiple romantic threads without collapsing tension.
//
// POLY SEMANTIC RULESET:
// - Intent may be multi-target (player can express attraction to multiple)
// - Consequences remain SERIALIZED (only one chain advances at a time)
// - No simultaneous payoff (intimacy with one complicates others)
//
// POLY STORY LOGIC (MANDATORY):
// When poly intent detected:
// - Do NOT resolve it immediately
// - Do NOT ask player to choose "now"
// - Do NOT punish curiosity
// - Let attraction accumulate
// - Let tension triangulate
// - Let consequences lag behind intent
//
// CANONICAL EXAMPLE:
// "You notice the way Marcus watches you notice Jax.
//  The story files this away. It will matter later."
//
// HARD CONSTRAINTS:
// ❌ No explicit "poly mode" UI explanation
// ❌ No simultaneous intimacy scenes
// ❌ No arithmetic balancing of affection
// ❌ No player-facing optimization
//
// MANTRA: Poly is felt, not managed.
//
// ═══════════════════════════════════════════════════════════════════════════
// PART B — WRONG-CHARACTER INVITATION MICROCOPY
// ═══════════════════════════════════════════════════════════════════════════
//
// PURPOSE: Handle misdirected romantic intent gracefully.
//
// CORE RULE: Never let a misdirected invitation collapse the story.
//
// REQUIRED BEHAVIOR:
// - Preserve the intent
// - Redirect the consequence
// - Clarify stakes via story framing
// - Do NOT execute the action literally
//
// CANONICAL MICROCOPY RESPONSES:
// 1. Deflection (gentle): "He smiles, just a little too politely, and steps aside"
// 2. Redirection (story-aware): "The story notices the reach, then adjusts where it lands"
// 3. Complication (poly-safe): "He notices. Unfortunately, so does Marcus."
// 4. Almost (preferred): "The invitation hangs between you — felt, acknowledged, unanswered"
//
// HARD CONSTRAINTS:
// ❌ No "you can't do that"
// ❌ No explanation of roles
// ❌ No system voice
// ❌ No silent failure
//
// MANTRA: The player must feel seen, not corrected.
//
// ═══════════════════════════════════════════════════════════════════════════
// PART C — BORING-PLAYER ESCALATION LADDER
// ═══════════════════════════════════════════════════════════════════════════
//
// PURPOSE: Prevent flat stories when players avoid tension.
//
// CORE INSIGHT (LOCKED): Boredom is unexpressed desire, not absence of desire.
//
// ESCALATION LADDER (MANDATORY · ORDERED):
//
// LEVEL 1 — Environmental Pressure (1-2 passive turns)
// "The room grows quieter than it should."
// - Time constraints, confined spaces, proximity, interruptions
//
// LEVEL 2 — NPC Initiative (3-4 passive turns)
// "You're very careful," he says. "Is that on purpose?"
// - The other character advances, asks a question, creates a moment
//
// LEVEL 3 — Social or Emotional Stakes (5-6 passive turns)
// "Someone is definitely watching now."
// - Someone notices, rumors, consequences loom
//
// LEVEL 4 — Forced Choice (7+ passive turns)
// "Whatever you do next will be remembered."
// - Stay or leave, answer or deflect, step closer or step away
//
// HARD CONSTRAINTS:
// ❌ No punishment for neutrality
// ❌ No sudden jumps to intimacy
// ❌ No railroading
//
// MANTRA: Escalation must feel inevitable, not imposed.
//
// ═══════════════════════════════════════════════════════════════════════════
// GLOBAL SUCCESS CONDITIONS
// ═══════════════════════════════════════════════════════════════════════════
//
// After these systems:
// - Humans cannot accidentally ruin pacing
// - Humans cannot "play wrong"
// - Desire always increases tension
// - Poly curiosity adds pressure, not chaos
// - Passive play becomes charged
// - The Story always feels smarter — never stricter
//
// REGRESSION TEST
// ----------------
// Run: window.runIntentConsequenceTest()
//
// Verifies:
// - Poly intent detection (smile at Jax → detected)
// - Wrong target detection (kiss Jax → detected, Marcus identified)
// - Passive play detection (shrug, wait → detected)
// - Active play NOT detected as passive
// - Escalation level progression
// - Boredom directive generation
//
// FINAL MANTRA (DO NOT REMOVE)
// -----------------------------
// The player offers desire.
// The story decides when it costs something.
//
// ═══════════════════════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════════════════════
// TONE-SPECIFIC VARIANTS — DOCUMENTATION (APPEND-ONLY)
// ═══════════════════════════════════════════════════════════════════════════
//
// GLOBAL INVARIANT (MUST HOLD ACROSS ALL TONES):
// No tone may allow a player action to prematurely collapse romantic tension.
// Tone changes voice, framing, and texture — NEVER rules.
//
// ═══════════════════════════════════════════════════════════════════════════
// 1. WRY CONFESSION (PRIMARY)
// ═══════════════════════════════════════════════════════════════════════════
// Emotional posture: Self-aware, slightly embarrassed, observant mid-mistake
// Deferral style: Almosts + self-implication
// Story voice: Gentle witness. Occasionally amused. Never cruel.
//
// CANONICAL: "You lean in — not quite far enough to pretend this was an accident."
// NEVER USE: melodrama, destiny language, threats
//
// ═══════════════════════════════════════════════════════════════════════════
// 2. EARNEST / ROMANTIC DRAMA
// ═══════════════════════════════════════════════════════════════════════════
// Emotional posture: Sincere, yearning, emotionally vulnerable
// Deferral style: External interruption or mutual restraint framed as care
// Story voice: Protective, patient, quietly invested.
//
// CANONICAL: '"Not yet," he says softly, and you realize how much weight those words carry.'
// NEVER USE: irony, self-mockery, meta commentary
//
// ═══════════════════════════════════════════════════════════════════════════
// 3. DARK / ANGST / FORBIDDEN
// ═══════════════════════════════════════════════════════════════════════════
// Emotional posture: Danger, repression, inevitability
// Deferral style: Consequences implied, not avoided
// Story voice: Grimly aware. Knows the cost.
//
// CANONICAL: "If this happens now, it won't end here."
// NEVER USE: humor, lightness, reassurance
//
// ═══════════════════════════════════════════════════════════════════════════
// 4. COMEDIC / HEIGHTENED
// ═══════════════════════════════════════════════════════════════════════════
// Emotional posture: Exaggerated, impulsive, socially risky
// Deferral style: Misfires, interruptions, comedic timing
// Story voice: Knowing, fast, permissive but controlling outcomes.
//
// CANONICAL: "You lean in. The universe clears its throat."
// NEVER USE: tragedy, prolonged yearning, solemn restraint
//
// ═══════════════════════════════════════════════════════════════════════════
// 5. STEAMY / SENSUAL
// ═══════════════════════════════════════════════════════════════════════════
// Emotional posture: Charged, deliberate, simmering
// Deferral style: Anticipation as pleasure, restraint as foreplay
// Story voice: Intimate, unhurried, knowingly drawing it out.
//
// CANONICAL: "Not yet. The waiting is part of it."
// NEVER USE: clinical language, embarrassment, shame
//
// ═══════════════════════════════════════════════════════════════════════════
// HARD CONSTRAINTS (ALL TONES)
// ═══════════════════════════════════════════════════════════════════════════
// ❌ No tone may execute premature intimacy
// ❌ No tone may refuse desire outright
// ❌ No tone may expose mechanics
// ❌ No tone may flatten tension
// ❌ No tone may shame the player
//
// REGRESSION TEST
// ----------------
// Run: window.runToneVariantTest()
//
// Verifies:
// - Each tone returns correct variant configuration
// - Tone examples differ between tones
// - Never-use lists are populated
// - Escalation examples vary by level
// - Unknown tones fall back to default (Wry Confessional)
//
// TONE MANTRA (DO NOT REMOVE)
// ----------------------------
// The rules do not change.
// Only how the story tells the truth about them.
//
// ═══════════════════════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════════════════════════
//                        TITLE REGIME CHANGE: ST1 TENSION
// ═══════════════════════════════════════════════════════════════════════════════
//
// SYSTEM PHILOSOPHY
// -----------------
// Book titles at ST1 must NAME THE TENSION, never claim its resolution.
// A title is a promise. At ST1, the promise is incomplete.
//
// This is not a vocabulary filter. It is a semantic timing authority.
// Titles tell the reader what the story WANTS, not what it HAS.
//
// ═══════════════════════════════════════════════════════════════════════════════
// VOCABULARY SPLIT
// ═══════════════════════════════════════════════════════════════════════════════
//
// ALLOWED (Unresolved Tension):
// • Waiting, Distance, Refusal, Terms, Conditions
// • Wanting, Craving, Hunger, Longing, Hesitation
// • Edge, Risk, Dare, Warning, Test
// • Confession (as desire-admission, not outcome)
//
// FORBIDDEN (Resolution/Aftermath):
// • Surrender, Obedience, Ruin, Undoing, Downfall
// • Took, Claimed, Gave, Broke, Wrecked, Ruined
// • Finally, At Last, In The End, After Everything
// • Possession, Conquest, Destruction, Betrayal
//
// ═══════════════════════════════════════════════════════════════════════════════
// AROUSAL LEVEL CONSTRAINTS
// ═══════════════════════════════════════════════════════════════════════════════
//
// EROTIC: "wanting, yearning, hunger (not possession)"
//   Required: hunger|longing|craving|need|ache|want|desire|confession|hesitation
//   Forbidden: surrender|obedience|ruin|wreck|broke|took|claimed|gave|possession
//
// DIRTY: "intensity, demand, edge (not destruction)"
//   Required: raw|demand|appetite|edge|limit|dare|hunger|test|condition|warning
//   Forbidden: surrender|obedience|ruin|undoing|broke|wrecked|ruined|destroyed
//
// ═══════════════════════════════════════════════════════════════════════════════
// VALIDATION PIPELINE
// ═══════════════════════════════════════════════════════════════════════════════
//
// checkTitleResolutionVocabulary(title) → { hasResolved: bool, violations: [] }
//
// Tests against TITLE_RESOLVED_VOCABULARY patterns:
// • pastCompletion: Past-tense completion verbs
// • possessiveResolution: Possessive + resolution noun
// • aftermathNouns: Post-event vocabulary
// • completionStates: Temporal finality markers
//
// Integration point: validateTitle() adds TITLE_RESOLUTION_VOCABULARY error
//
// ═══════════════════════════════════════════════════════════════════════════════
// PROMPT DIRECTIVE
// ═══════════════════════════════════════════════════════════════════════════════
//
// The buildTitlePrompt() function includes:
//
// "TITLE REGIME (CRITICAL):
// Book titles must name UNRESOLVED TENSION, not resolution.
// The reader hasn't finished the story. The title can't claim they have.
//
// FORBIDDEN: Past completion, aftermath, possession outcomes
// REQUIRED: Active wanting, unfinished tension, unnamed hunger"
//
// ═══════════════════════════════════════════════════════════════════════════════
// EXAMPLES
// ═══════════════════════════════════════════════════════════════════════════════
//
// ✓ ALLOWED (ST1):
//   "Her Terms" — names the power dynamic, not its outcome
//   "The Waiting" — names the state, not what it led to
//   "His Hunger" — names desire, not satisfaction
//   "Between Wanting" — suspension, not resolution
//   "The Hesitation" — moment of choice, not choice made
//
// ✗ FORBIDDEN (ST1):
//   "Her Surrender" — claims resolution ST1 can't deliver
//   "What He Took" — past tense implies completed action
//   "The Reckoning" — aftermath vocabulary, not tension
//   "Finally His" — temporal finality marker
//   "Ruined" — consequence language, not anticipation
//
// ═══════════════════════════════════════════════════════════════════════════════
// TITLE REGIME MANTRA (DO NOT REMOVE)
// ═══════════════════════════════════════════════════════════════════════════════
//
// A title names what the story WANTS.
// Not what it HAS. Not what it DID.
// At ST1, the story is still wanting.
//
// ═══════════════════════════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════════════════════════
//                    GENRE REGIME: NESTED PRESSURE MODEL
// ═══════════════════════════════════════════════════════════════════════════════
//
// SYSTEM PHILOSOPHY
// -----------------
// Storybound genres are PRESSURE ENGINES, not bookshelf categories.
// They shape: pacing, tension, romantic cost, consequence timing.
//
// Worlds (Modern, Fantasy, Sci-Fi, Historical) are AESTHETIC LENSES, not pressures.
// Tone controls NARRATION STYLE and confession posture.
// Genre (Pressure) controls WHAT'S AT STAKE and HOW IT COSTS.
//
// This task introduces HIERARCHY, not new mechanics.
//
// ═══════════════════════════════════════════════════════════════════════════════
// HIERARCHY: PRIMARY PRESSURE → OPTIONAL FLAVOR
// ═══════════════════════════════════════════════════════════════════════════════
//
// LAYER 1 — PRIMARY PRESSURES (8 total, the ONLY visible top-level choices)
//
// PowerControl      — Someone has leverage. Someone else pays for it.
// RiskExposure      — Being seen, known, caught, or revealed is dangerous.
// EscapePursuit     — Leaving, rescuing, or outrunning something.
// ObligationBurden  — Duty, destiny, or expectation presses inward.
// DesireObsession   — Wanting something too much, too soon, or for the wrong reasons.
// ReckoningPast     — History, guilt, or unfinished business intrudes.
// Transformation    — Someone is becoming something they didn't plan to be.
// Survival          — Staying alive — socially, politically, physically, or emotionally.
//
// LAYER 2 — FLAVORS (optional refinements, 3-5 per pressure)
//
// Flavors appear AFTER a pressure is selected.
// Flavors are NEVER required.
// Flavors modify texture, not authority.
//
// ═══════════════════════════════════════════════════════════════════════════════
// FLAVOR MAP (CANONICAL NESTING)
// ═══════════════════════════════════════════════════════════════════════════════
//
// PowerControl:     Billionaire, CrimeSyndicate, Political, Espionage, CultOrder
// RiskExposure:     Noir, ForbiddenKnowledge, PublicScandal, Surveillance, DoubleLife
// EscapePursuit:    Heist, Rescue, OnTheRun, LockedAway, BorderCrossing
// ObligationBurden: ChosenBurdened, DutyToFamily, Prophecy, CommandRank, Inheritance
// DesireObsession:  Obsession, ForbiddenRomance, Rivalry, Addiction, Jealousy
// ReckoningPast:    RelentlessPast, Redemption, OldDebts, BetrayalHistory, LostRelationship
// Transformation:   BecomingPowerful, MoralCorruption, Awakening, IdentityShift, Ascension
// Survival:         WarZone, Castaway, Lost, Trapped, Afflicted, Scarcity  [Hidden: Apocalypse]
//
// ═══════════════════════════════════════════════════════════════════════════════
// BACKWARD COMPATIBILITY
// ═══════════════════════════════════════════════════════════════════════════════
//
// state.picks.genre      — LEGACY field, derived from pressure+flavor
// state.picks.pressure   — Primary pressure selection (required)
// state.picks.flavor     — Optional flavor selection
//
// LEGACY_GENRE_TO_PRESSURE maps old genre values to pressure+flavor:
//   Billionaire → { PowerControl, Billionaire }
//   Noir → { RiskExposure, Noir }
//   Heist → { EscapePursuit, Heist }
//   etc.
//
// getEffectiveGenre(pressure, flavor) — Returns flavor if set, else pressure default
// migrateLegacyGenre(genre) — Converts old saves to new system
//
// ═══════════════════════════════════════════════════════════════════════════════
// DSP INTEGRATION
// ═══════════════════════════════════════════════════════════════════════════════
//
// getPressureDSPPhrase(pressure, flavor) — Returns DSP paraphrase
// - If flavor has override in FLAVOR_DSP_OVERRIDES, use it
// - Otherwise use PRIMARY_PRESSURES[pressure].dspPhrase
//
// generateDSPSentence() updated to use pressure system with legacy fallback.
//
// ═══════════════════════════════════════════════════════════════════════════════
// UI CONSTRAINTS (DO NOT VIOLATE)
// ═══════════════════════════════════════════════════════════════════════════════
//
// ❌ Never show more than 8 primary options
// ❌ Never require selecting a flavor
// ❌ Never show flavors before a primary is chosen
// ❌ Never expose hierarchy language to the user
//
// The experience should feel:
// "I'm choosing what kind of pressure this story lives under."
//
// Not:
// "I'm configuring a system."
//
// ═══════════════════════════════════════════════════════════════════════════════
// WORLD HANDLING (IMPORTANT)
// ═══════════════════════════════════════════════════════════════════════════════
//
// Worlds are AESTHETIC LENSES, not pressures:
// - Fantasy, Sci-Fi, Modern, Historical, Near-Future, Alternate Reality
//
// Worlds modify:
// - imagery
// - vocabulary
// - stakes presentation
//
// Worlds DO NOT add pressure by themselves.
//
// Examples:
// - Obligation + Fantasy → prophecy without saying "prophecy"
// - Risk + Sci-Fi → surveillance state
// - Power + Modern → billionaire / media empire
//
// ═══════════════════════════════════════════════════════════════════════════════
// GENRE REGIME MANTRA (DO NOT REMOVE)
// ═══════════════════════════════════════════════════════════════════════════════
//
// Genres describe PRESSURE.
// Worlds describe HOW IT LOOKS.
// Tone describes HOW IT'S CONFESSED.
//
// ═══════════════════════════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════════════════════════
//                    BREADCRUMB FLOW SYSTEM
// ═══════════════════════════════════════════════════════════════════════════════
//
// SYSTEM PHILOSOPHY
// -----------------
// Cards are semantic objects, not UI widgets.
// They represent meaning, authorship decisions, and narrative pressure.
// Setup should feel like the first chapter of the book, not a configurator.
//
// ═══════════════════════════════════════════════════════════════════════════════
// CORE INTERACTION MODEL
// ═══════════════════════════════════════════════════════════════════════════════
//
// One row of cards at a time.
// Selection is visible.
// Progression is ceremonial.
// State becomes breadcrumb.
//
// At no point should the user:
// - scroll through multiple rows of cards
// - see multiple semantic layers simultaneously
// - configure via hidden state
//
// ═══════════════════════════════════════════════════════════════════════════════
// CARD STATES (4 ONLY)
// ═══════════════════════════════════════════════════════════════════════════════
//
// 1. IDLE — Card sits in row, hover effects allowed
// 2. FLIPPED — First click reveals description + flavor count
// 3. ZOOMED — Second click expands for full selection mode
// 4. BREADCRUMB — Committed, minimized at top of screen
//
// No other states may be introduced.
//
// ═══════════════════════════════════════════════════════════════════════════════
// FLOW SEQUENCE (LOCKED ORDER)
// ═══════════════════════════════════════════════════════════════════════════════
//
// 1. Pull
// 2. World
// 3. Tone
// 4. Polarity (Guided Fate)
//
// At no time may two of these rows be visible together.
//
// ═══════════════════════════════════════════════════════════════════════════════
// CONTINUE ACTION
// ═══════════════════════════════════════════════════════════════════════════════
//
// Continue button appears ONLY when exactly one card is selected.
//
// On Continue:
// 1. Selected card smoothly shrinks
// 2. Animates to top center (breadcrumb row)
// 3. Becomes a breadcrumb card
// 4. Other cards dissipate into sparkles
// 5. Fade out completely
// 6. New row fades in below breadcrumbs
//
// Animation must feel: deliberate, narrative, not instantaneous
//
// ═══════════════════════════════════════════════════════════════════════════════
// BREADCRUMB RULES
// ═══════════════════════════════════════════════════════════════════════════════
//
// Breadcrumb cards:
// ✓ Remain visible at top of screen
// ✓ Visually smaller than selection cards (75×105 vs 150×210)
// ✓ Accumulate left-to-right in order of selection
// ✓ May slightly overlap or sit adjacent
// ✓ Represent committed authorship decisions
// ✓ May be hoverable for reminder copy
//
// ❌ Do not expand automatically
// ❌ Do not re-trigger selection flow
// ❌ Cannot be removed or reordered
//
// ═══════════════════════════════════════════════════════════════════════════════
// CSS CLASSES
// ═══════════════════════════════════════════════════════════════════════════════
//
// .breadcrumb-row          — Container at top, sticky positioning
// .breadcrumb-card         — Committed selection, minimized
// .card-flow-row           — Wrapper for each selection stage
// .card-flow-row.flow-hidden — Hidden stage (not yet reached)
// .card-flow-row.flow-entering — Fade-in animation for new stage
// .flow-continue-btn       — Continue button (hidden until selection)
// .flow-continue-btn.visible — Show continue button
// .sb-card.dissipating     — Card fading out with sparkles
// .sb-card.becoming-breadcrumb — Card animating to breadcrumb position
// .dissipate-sparkle       — Individual sparkle particle
// .flow-stage-indicator    — Progress dots
// .flow-stage-dot          — Individual dot
// .flow-stage-dot.active   — Current stage
// .flow-stage-dot.completed — Past stages
//
// ═══════════════════════════════════════════════════════════════════════════════
// JAVASCRIPT API
// ═══════════════════════════════════════════════════════════════════════════════
//
// initBreadcrumbFlow()           — Initialize flow system
// handleFlowContinue(stage)      — Process continue action
// animateCardToBreadcrumb()      — Animate selection to breadcrumb
// dissipateCards()               — Sparkle dissipation effect
// createDissipationSparkles()    — Create sparkle particles
// updateContinueButtonVisibility() — Show/hide continue button
// updateFlowStageIndicator()     — Update progress dots
// resetBreadcrumbFlow()          — Reset to initial state (new story)
//
// ═══════════════════════════════════════════════════════════════════════════════
// BREADCRUMB FLOW MANTRA (DO NOT REMOVE)
// ═══════════════════════════════════════════════════════════════════════════════
//
// Choices should feel like scenes, not settings.
//
// ═══════════════════════════════════════════════════════════════════════════════

// ███████████████████████████████████████████████████████████████████████████████
// ███████████████████████████████████████████████████████████████████████████████
//
//                    STORY STATE LOCKING — DESTRUCTIVE CHANGE RULES
//
// ███████████████████████████████████████████████████████████████████████████████
// ███████████████████████████████████████████████████████████████████████████████
//
// ═══════════════════════════════════════════════════════════════════════════════
// PHILOSOPHY
// ═══════════════════════════════════════════════════════════════════════════════
//
// Once a story exists (Scene 1 generated), the story's foundation is LOCKED.
// Users cannot silently change story-defining fields. Any attempt to change
// a locked field triggers a warning modal: this is a destructive action.
//
// The user must choose:
// 1. Save & Start New Story — saves current story, then clears for fresh start
// 2. Start New Story — discards current story without saving
// 3. Cancel — keeps current story, reverts selection
//
// This prevents accidental loss of creative work and makes the commitment
// to a story feel deliberate and meaningful.
//
// ═══════════════════════════════════════════════════════════════════════════════
// LOCKED FIELDS (Cannot change without destroying story)
// ═══════════════════════════════════════════════════════════════════════════════
//
// - pressure      — Primary pressure (story engine)
// - flavor        — Pressure refinement
// - genre         — Legacy genre (derived from pressure+flavor)
// - world         — World setting
// - worldSubtype  — World refinement
// - tone          — Narrative tone
// - dynamic       — Relationship dynamic (Guided Fate)
// - pov           — Point of view
//
// ═══════════════════════════════════════════════════════════════════════════════
// SAFE FIELDS (Can change freely, even with existing story)
// ═══════════════════════════════════════════════════════════════════════════════
//
// - era           — Time period (decorative)
// - archetype     — Reader archetype (affects framing, not story)
// - title         — Book title (can be renamed anytime)
// - cover         — Cover image (can be regenerated)
//
// ═══════════════════════════════════════════════════════════════════════════════
// DETECTION LOGIC
// ═══════════════════════════════════════════════════════════════════════════════
//
// hasExistingStory():
//   Returns true if state.scenes[0] exists with content
//   (Scene 1 generation = story commitment point)
//
// isLockedField(grp):
//   Returns true if grp is in STORY_LOCKED_FIELDS array
//
// wouldDesenderStory(grp, newVal):
//   Returns true if:
//   1. hasExistingStory() is true, AND
//   2. isLockedField(grp) is true, AND
//   3. newVal differs from current state.picks[grp]
//
// ═══════════════════════════════════════════════════════════════════════════════
// MODAL BEHAVIOR
// ═══════════════════════════════════════════════════════════════════════════════
//
// showDestructiveChangeWarning(grp, newVal, card, onConfirm):
//   1. Stores pending change in pendingDestructiveChange
//   2. Shows #destructiveChangeModal overlay
//   3. Waits for user decision
//
// On "Save & Start New Story":
//   1. Triggers save flow (saveCurrentStory)
//   2. On save completion: clears story state, executes pending change
//
// On "Start New Story":
//   1. Clears story state immediately (clearStoryForNewStart)
//   2. Executes pending change
//
// On "Cancel":
//   1. Clears pendingDestructiveChange
//   2. Closes modal
//   3. User stays on current story
//
// clearStoryForNewStart():
//   1. Clears state.scenes to []
//   2. Clears state.storyText to ''
//   3. Clears state.currentScene to 0
//   4. Clears state.coverDataUrl to null
//   5. Clears any generated title
//   6. Resets DSP state
//   7. Resets visualization economy
//
// ═══════════════════════════════════════════════════════════════════════════════
// BUTTON STATE RULES
// ═══════════════════════════════════════════════════════════════════════════════
//
// If story exists AND no destructive changes pending:
//   Button label: "Continue Story"
//   Hint visible: "Your story will resume where you left off."
//
// If no story exists OR destructive changes confirmed:
//   Button label: "Begin Story"
//   Hint hidden
//
// No mixed states. No ambiguous labels.
//
// ═══════════════════════════════════════════════════════════════════════════════
// PASSIVE SAVE AFFORDANCES
// ═══════════════════════════════════════════════════════════════════════════════
//
// Whenever a story exists, the system shows calm reassurance (no modals):
//
// - "Your story will resume where you left off." beneath Continue Story button
// - Hints toggle automatically via updateBeginButtonLabel()
//
// Hint elements:
//   #beginBtnHint           — Below main Begin/Continue button
//   #continueFromDynamicHint — Below breadcrumb flow final button
//   #btnBeginStoryHint      — Below cover view Begin/Continue button
//   #btnSettingBeginStoryHint — Below setting view Begin/Continue button
//
// CSS class: .story-continue-hint (hidden by default, shown when canContinue)
//
// ═══════════════════════════════════════════════════════════════════════════════
// JAVASCRIPT API
// ═══════════════════════════════════════════════════════════════════════════════
//
// STORY_LOCKED_FIELDS          — Array of field names that trigger warning
// pendingDestructiveChange     — Stores { grp, val, card, onConfirm } during modal
// hasExistingStory()           — Check if story exists
// isLockedField(grp)           — Check if field is locked
// wouldDesenderStory(grp, val)  — Check if change would destroy story
// showDestructiveChangeWarning() — Show warning modal
// clearStoryForNewStart()      — Clear all story state
// initDestructiveChangeModal() — Bind modal button handlers
// updateBeginButtonLabel()     — Update button labels and toggle hints
// canContinueExistingStory()   — Check if story can be continued
