            ctx.fillText(text, x + 2, y + 3);
            // Layer 2: dark body
            ctx.fillStyle = 'rgba(10,8,5,0.85)';
            ctx.fillText(text, x, y + 1);
            // Layer 3: main black lacquer
            ctx.fillStyle = '#0a0806';
            ctx.fillText(text, x, y);
