  function _hash(s) { var h = 5381, i = s ? s.length : 0; while (i--) { h = ((h << 5) + h + s.charCodeAt(i)) >>> 0; } return h.toString(16); }
  function _st() { return (typeof state !== 'undefined' && state) || {}; }
