      var POS = { hall_of_fame: '⭐ excellent', invisible: '✨ seamless craft', emotional: '❤️ landed emotionally', perfect_voice: '🎭 pitch-perfect voice', interesting: '💡 distinctive' };
      var NEG = { needs_work: '⚠ weak', repetitive: '🔁 repetitive' };
