  function _createFatelandsPanel() {
    if (_fatelandsPanel) return;
    var panel = document.createElement('div');
    panel.className = 'fatelands-debug-panel';
    panel.style.display = 'none';

    var header = document.createElement('div');
    header.style.cssText = 'font-size:12px;font-weight:bold;color:#c9a24e;margin-bottom:6px;';
    header.textContent = 'FATELANDS DEBUG';
    panel.appendChild(header);

    // Region buttons
    var regions = window._listFatelandsRegions();
    regions.forEach(function(key) {
      var btn = document.createElement('button');
      btn.textContent = key;
      btn.onclick = function() { window._testFatelandsRegion(key); };
      panel.appendChild(btn);
    });

    // Separator
    var sep = document.createElement('hr');
    sep.style.cssText = 'border:none;border-top:1px solid #333;margin:8px 0;';
    panel.appendChild(sep);

    // Tuning sliders
    function addSlider(label, min, max, step, key) {
      var wrap = document.createElement('div');
      wrap.style.cssText = 'margin-bottom:4px;';
      var text = document.createElement('div');
      text.style.cssText = 'font-size:10px;color:#888;';
      text.textContent = label + ': ' + window._fatelandsTuning[key];
      var input = document.createElement('input');
      input.type = 'range';
      input.min = min; input.max = max; input.step = step;
      input.value = window._fatelandsTuning[key];
      input.style.cssText = 'width:100%;height:14px;';
      input.oninput = function() {
        window._fatelandsTuning[key] = parseFloat(this.value);
        text.textContent = label + ': ' + this.value;
        // Live re-apply if loupe is currently expanding
        if (typeof window._applyFatelandsParallax === 'function') window._applyFatelandsParallax();
      };
      wrap.appendChild(text);
      wrap.appendChild(input);
      panel.appendChild(wrap);
    }
    // Coordinate picker button
    var pickBtn = document.createElement('button');
    pickBtn.textContent = '\uD83D\uDCCD Pick Coords';
    pickBtn.style.cssText = 'width:100%;background:#1a1a1a;color:#0f0;border:1px solid #333;padding:4px;cursor:pointer;border-radius:3px;margin-bottom:8px;font-size:11px;';
    pickBtn.onclick = function() { window._startCoordPicker(); };
    panel.appendChild(pickBtn);

    var coordOutput = document.createElement('div');
    coordOutput.id = 'fatelands-coord-output';
    coordOutput.style.cssText = 'font-size:10px;color:#0f0;margin-bottom:8px;min-height:14px;word-break:break-all;';
    panel.appendChild(coordOutput);

    addSlider('Speed (ms)', 200, 1200, 50, 'speed');
    addSlider('Parallax (px)', 0, 50, 1, 'parallax');
    addSlider('Content Scale', 1.0, 1.2, 0.01, 'scaleContent');
    addSlider('Frame Scale', 1.0, 1.25, 0.01, 'scaleFrame');

    document.body.appendChild(panel);
    _fatelandsPanel = panel;
  }

