  // ── Coordinate Picker: click on map to get normalized x,y for region positions ──
  var _coordPickerActive = false;
  var _coordMarkers = [];

  window._startCoordPicker = function() {
    // Ensure test modal is open with the map
    var overlay = document.getElementById('fatelands-test-overlay');
    if (!overlay || overlay.style.display === 'none') {
      // Open modal without loupe
      if (typeof _ensureFatelandsTestModal === 'function') {
        overlay = _ensureFatelandsTestModal();
        overlay.style.display = 'flex';
      }
      var label = document.getElementById('fatelands-test-label');
      if (label) label.textContent = 'COORD PICKER — click on the map to mark regions';
    }
    if (!overlay) return;

    _coordPickerActive = true;
    var el = overlay._frontispiece;
    var mapImg = el ? el.querySelector('.fatelands-map-img') : null;
    if (!mapImg) { console.warn('[COORD PICKER] No map image'); return; }

    // Clear old loupes and markers
    var old = el.querySelectorAll('.fatelands-loupe, .fatelands-location-label, .fatelands-coord-marker');
    for (var i = 0; i < old.length; i++) old[i].remove();

    mapImg.style.cursor = 'crosshair';
    mapImg.onclick = function(e) {
      if (!_coordPickerActive) return;
      var rect = mapImg.getBoundingClientRect();
      var x = ((e.clientX - rect.left) / rect.width).toFixed(2);
      var y = ((e.clientY - rect.top) / rect.height).toFixed(2);

      // Drop a visual marker
      var front = el.querySelector('.sb-curl-page-front');
      if (front) {
        front.style.position = 'relative';
        var marker = document.createElement('div');
        marker.className = 'fatelands-coord-marker';
        marker.style.cssText = 'position:absolute;width:12px;height:12px;border-radius:50%;background:rgba(255,0,0,0.8);border:2px solid #fff;transform:translate(-50%,-50%);z-index:20;pointer-events:none;';
        var mapOff = mapImg.getBoundingClientRect();
        var frontOff = front.getBoundingClientRect();
        marker.style.left = (e.clientX - frontOff.left) + 'px';
        marker.style.top = (e.clientY - frontOff.top) + 'px';
        // Number label
        var num = document.createElement('span');
        num.style.cssText = 'position:absolute;left:16px;top:-4px;color:#fff;font-size:10px;font-family:monospace;white-space:nowrap;text-shadow:0 0 3px #000;';
        num.textContent = _coordMarkers.length + 1 + ': { x: ' + x + ', y: ' + y + ' }';
        marker.appendChild(num);
        front.appendChild(marker);
        _coordMarkers.push(marker);
      }

      // Output to debug panel + console
      var output = '{ x: ' + x + ', y: ' + y + ' }';
      console.log('[COORD PICKER] #' + _coordMarkers.length + ':', output);
      var coordEl = document.getElementById('fatelands-coord-output');
      if (coordEl) coordEl.textContent = '#' + _coordMarkers.length + ': ' + output;
    };

    console.log('[COORD PICKER] Active — click on the map to mark positions. Call _stopCoordPicker() when done.');
  };

  window._stopCoordPicker = function() {
    _coordPickerActive = false;
    var overlay = document.getElementById('fatelands-test-overlay');
    if (overlay && overlay._frontispiece) {
      var mapImg = overlay._frontispiece.querySelector('.fatelands-map-img');
      if (mapImg) { mapImg.style.cursor = ''; mapImg.onclick = null; }
    }
    // Clear markers
    _coordMarkers.forEach(function(m) { m.remove(); });
    _coordMarkers = [];
    console.log('[COORD PICKER] Stopped');
  };

