  // ── Style Comparison Grid ──
  async function renderGNStyleGrid(opts) {
    var scene = (opts && opts.scene) || 'A man cups her face as they lean in to kiss in the rain';
    var container = document.createElement('div');
    container.style.cssText = 'position:fixed;inset:0;z-index:999998;background:#111;overflow-y:auto;padding:16px;';
    var header = document.createElement('div');
    header.style.cssText = 'display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;';
    header.innerHTML = '<span style="color:#c9a24e;font-family:monospace;font-size:14px;">GN Style Grid</span>';
    var closeBtn = document.createElement('button');
    closeBtn.textContent = '\u2715 Close';
    closeBtn.style.cssText = 'background:#333;color:#fff;border:none;padding:6px 12px;cursor:pointer;border-radius:4px;font-size:12px;';
    closeBtn.onclick = function() { container.remove(); };
    header.appendChild(closeBtn);
    container.appendChild(header);
    var grid = document.createElement('div');
    grid.style.cssText = 'display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px;';
    container.appendChild(grid);
    document.body.appendChild(container);

    for (var i = 0; i < _GN_ARTISTS_LIST.length; i++) {
      var artist = _GN_ARTISTS_LIST[i];
      var wrapper = document.createElement('div');
      wrapper.style.cssText = 'display:flex;flex-direction:column;align-items:center;color:#fff;';
      var label = document.createElement('div');
      label.textContent = artist;
      label.style.cssText = 'margin-bottom:6px;font-size:13px;opacity:0.7;font-family:monospace;';
      wrapper.appendChild(label);
      var status = document.createElement('div');
      status.textContent = 'rendering...';
      status.style.cssText = 'font-size:11px;color:#666;margin-bottom:4px;';
      wrapper.appendChild(status);
      grid.appendChild(wrapper);

      // Render async (sequential to avoid rate limits)
      try {
        status.textContent = 'generating...';
        var imgUrl = await window.renderGNSandbox({ artist: artist, scene: scene, _silent: true });
        var actualPrompt = (window._lastGNPrompts && (window._lastGNPrompts.openai || window._lastGNPrompts.gemini)) || '(prompt not captured)';
        if (imgUrl) {
          var img = document.createElement('img');
          img.src = imgUrl;
          img.style.cssText = 'width:100%;border-radius:6px;cursor:pointer;';
          img.dataset.prompt = actualPrompt;
          img.onclick = (function(p) { return function() { showPromptInspector(p); }; })(actualPrompt);
          wrapper.appendChild(img);
          status.textContent = 'done (' + actualPrompt.length + ' chars)';
          status.style.color = '#4a4';
        } else {
          status.textContent = 'failed (null)';
          status.style.color = '#a44';
        }
      } catch (err) {
        status.textContent = 'error: ' + err.message;
        status.style.color = '#a44';
        console.error('[GN:GRID] Error for', artist, err);
      }
    }
  }
  window.renderGNStyleGrid = renderGNStyleGrid;

