    var artist = (opts && opts.artist) || 'ender_bond';

    var container = document.createElement('div');
    container.style.cssText = 'position:fixed;inset:0;z-index:999998;background:#111;overflow-y:auto;padding:16px;';
    var header = document.createElement('div');
    header.style.cssText = 'display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;';
    header.innerHTML = '<span style="color:#6cf;font-family:monospace;font-size:14px;">Model Comparison \u2014 ' + artist + '</span>';
