        window._gnDevModel = entry.model;
        status.textContent = 'generating (' + entry.label + ')...';
        var imgUrl = await window.renderGNSandbox({ artist: artist, scene: scene, _silent: true });
        // Capture the ACTUAL prompt sent to the provider (not buildRenderPrompt)
        var actualPrompt = (window._lastGNPrompts && window._lastGNPrompts[entry.provider]) || '(prompt not captured)';
        var actualProvider = window._lastActualProvider || entry.label;
