          wrapper.appendChild(img);
          var isFallback = actualProvider.toLowerCase() !== entry.provider.toLowerCase();
          status.textContent = (isFallback ? actualProvider + ' (fallback)' : entry.label) + ' \u2714 (' + actualPrompt.length + ' chars)';
          status.style.color = isFallback ? '#ca4' : '#4a4';
